window.__BOOK__['p10'].push([{"id":"b246-2","bab":"الجزء 19","sec":"ذكر أبي محجن ونسبه — عمر ينفيه إلى جزيرة حضوضى","page":"ج18 ص385 – ج19 ص3","text":"أبو محجن عبد الله بن حبيب بن عمرو بن عمير بن عوف بن عقدة بن عنزة بن عوف قسي وهو ثقيف وقد مضى نسبه في عدة مواضع وأبو محجن من المخضرمين الذين أدركوا الجاهلية والإسلام وهو شاعر فارس شجاع معدود في أولي البأس والنجدة وكان من المعاقرين للخمر المحدودين في شربها\nأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن الحسن الأحول عن ابن الأعرابي عن المفضل قال لما كثر شرب أبي محجن الخمر وأقام عمر بن الخطاب رضي الله عنه عليه الحد مرارا وهو لا ينتهي نفاه إلى جزيرة في البحر يقال لها\nحضوضى وبعث معه حرسيا يقال له ابن جهراء فهرب منه على ساحل البحر ولحق بسعد بن أبي وقاص وقال في ذلك يذكر هربه من ابن جهراء\n(الحمد لله نجاني وخلصني ... من ابن جهراء والبوصي قد حبسا)\n(من يجشم البحر والبوصي مركبه ... إلى حضوضى فبئس المركب التمسا)\n(أبلغ لديك أبا حفص مغلغلة ... عبد الإله إذا ما غار أو جلسا)\n(أني أكر على الأولى إذا فزعوا ... يوما وأحبس تحت الراية الفرسا)\n(أغشى الهياج وتغشاني مضاعفة ... من الحديد إذا ما بعضهم خنسا)\nذه رواية ابن الأعرابي عن المفضل قال ابن الأعرابي وحدثني ابن دأب بسبب نفي عمر إياه فذكر أن أبا محجن هوي امرأة من الأنصار يقال لها شموس فحاول النظر إليها بكل حيلة فلم يقدر عليها فآجر نفسه من عامل\nيعمل في حائط إلى جانب منزلها فأشرف من كوة في البستان فرآها فأنشأ يقول\n(ولقد نظرت إلى الشموس ودونها ... حرج من الرحمن غير قليل)\n(قد كنت أحسبني كأغنى واحد ... ورد المدينة عن زراعة فول)\nفاستعدى زوجها عليه عمر بن الخطاب فنفاه إلى حضوضى وبعث معه رجلا يقال له ابن جهراء قد كان أبو بكر رضي الله عنه يستعين به قال له عمر لا تدع أبا محجن يخرج معه سيفا فعمد أبو محجن إلى سيفه فجعل نصله في غرارة وجعل جفنه في غرارة أخرى فيهما دقيق له فلما انتهى به إلى الساحل وقرب البوصي اشترى أبو محجن شاة وقال لابن جهراء هلم نتغد ووثب إلى الغرارة كأنه يخرج منها دقيقا فأخذ السيف فلما رآه ابن جهراء والسيف في يده خرج يعدو حتى ركب بعيره راجعا إلى عمر فأخبره الخبر","topic":"ذكر أبي محجن ونسبه","topicNo":246,"sp":0,"spl":"ذكر أبي محجن ونسبه — عمر ينفيه إلى جزيرة حضوضى"},
{"id":"b246-3","bab":"الجزء 19","sec":"أبو محجن يقاتل يوم أرماث","page":"ج19 ص5","text":"وأقبل أبو محجن إلى سعد بن أبي وقاص وهو يقاتل العجم يوم القادسية وبلغ عمر خبره فكتب إلى سعد بحبسه فحبسه فلما كان يوم أرماث والتحم القتال سأل ابو محجن امرأة سعد أن تعطيه فرس سعد وتحل قيده ليقاتل\nالمشركين فإن استشهد فلا تبعه عليه وإن سلم عاد حتى يضع رجله في القيد فأعطته الفرس وخلت سبيله وعاهدها على الوفاء فقاتل فأبلى بلاء حسنا إلى الليل ثم عاد إلى حبسه حدثني بهذا الحديث عمي الخراز عن المدائني عن إبراهيم بن حكيم عن عاصم بن عروة أن عمر بن الخطاب رضي الله عنه غرب رجلا من ثقيف وهو أبو محجن وكان يدمن الخمر وأمر ابن جهراء النصري ورجلا آخر أن يحملاه في البحر وذكر الخبر مثل الذي قبله وزاد فيه وقال أبو محجن أيضا صوت\n(صاحبا سوء صحبتهما ... صاحباني يوم أرتحل)\n(ويقولان ارتحل معنا ... فأنادي إنني ثمل)\n(إنني باكرت مترعة ... مزة راووقها خضل)\nلغناء في البيتين الأخيرين لنشو خفيف رمل وأوله\n(ويقولان اصطبح معنا ... )\nال الأصبهاني وهذه القصة كانت لأبي محجن في يوم من أيام حرب القادسية يقال له يوم أرماث وكانت أيامها المشهورة يوم أغواث ويوم أرماث\nويوم الكتائب وخبرها يطول جدا وليس في كلها كان لأبي محجن خبر وإنما ذكرنا هاهنا خبره فذكرنا منها ما كان اتصاله بخبر أبي محجن حدثنا بذلك محمد بن جرير الطبري قال كتب إلي السري بن يحي يذكر عن شعيب عن سيف عن محمد بن طلحة وزياد وابن مخراق عن رجل من طيء قال لما كان يوم الكتائب اقتتل المسلمون والفرس منذ أصبحوا إلى أن انتصف النهار فلما غابت الشمس تزاحف الناس فاقتتلوا حتى انتصف الليل وهذه الليلة كان في صبيحتها يوم أرماث وقد كان المسلمون يوم أغواث أشرفوا على الظفر وقتلوا عامة أعلام الفرس وجالت خيلهم في القلب فلولا أن رجلهم ثبتوا حتى كرت الخيل لكان رئيسهم قد أخذ لأنه كان ينزل عن فرسه ويجلس على سريره ويأمر الناس بالقتال قالوا فلما انتصف الليل تحاجز الناس وبات المسلمون ينتمون منذ لدن أمسوا وسمع ذلك سعد فاستلقى لينام وقال لبعض من عنده إن تم الناس على الانتماء فلا توقظني فإنهم أقوياء على عدوهم وإن سكتوا وسكت العدو فلا تنبهني فإنهم على السواء وإن سمعت العدو ينتمون وهؤلاء سكوت فأنبهني فإن إنتماء العدو من السوء قالوا ولما اشتد القتال في تلك الليلة وكان أبو محجن قد حبسه سعد بكتاب عمر وقيده فهو في القصر صعد أبو محجن إلى سعد يستعفيه\nويستقيله فزبره ورده فنزل فأتى سلمى بنت أبي حفصة فقال يا بنت آل أبي حفصة هل لك إلى خير قالت وما ذاك قال تخلين عني وتعيرينني البلقاء فلله علي إن سلمني الله أرجع إلى حضرتك حتى تضعي رجلي في قيدي فقالت وما أنا وذاك فرجع يوسف في قيوده ويقول\n(كفى حزنا أن تردي الخيل بالقنا ... وأترك مشدودا علي وثاقيا)\n(إذا قمت عناني الحديد وغلفت ... مصاريع من دوني تصم المناديا)\n(وقد كنت ذا مال كثير وإخوة ... فقد تركوني واحدا لا أخاليا)\n(وقد شف جسمي أنني كل شارق ... أعالج كبلا مصمتا قد برانيا)\n(فلله دري يوم أترك موثقا ... وتذهل عني أسرتي ورجاليا)\n(حبيسا عن الحرب العوان وقد بدت ... وإعمال غيري يوم ذاك العواليا)\n(ولله عهد لا أخيس بعهده ... لئن فرجت ألا أزور الحوانيا)\nفقالت له سلمى إني استخرت الله ورضيت بعهدك فأطلقته وقالت\nأما الفرس فلا أعيرها ورجعت إلى بيتها فاقتداها أبو محجن وأخرجها من باب القصر الذي يلي الخندق فركبها ثم دب عليها حتى إذا كان بحيال الميمنة وأضاء النهار وتصاف الناس كبر ثم حمل على ميسرة القوم فلعب برمحه وسلاحه بين الصفين ثم رجع من خلف المسلمين إلى القلب فبدر أمام الناس فحمل على القوم فلعب بين الصفين برمحه وسلاحه وكان يقصف الناس ليلتئذ قصفا منكرا فعجب الناس منه وهم لا يعرفونه ولم يروه بالأمس فقال بعض القوم هذا من أوائل أصحاب هشام بن عتبة أو هشام بنفسه وقال قوم إن كان الخضر يشهد الحروب فهو صاحب البلقاء وقال آخرون لولا أن الملائكة لا تباشر القتال ظاهرا لقلنا هذا ملاك بيننا وجعل سعد يقول وهو مشرف ينظر إليه الطعن طعن أبي محجن والضبر ضبر البلقاء ولولا محبس أبي محجن لقلت هذا أبو محجن وهذه البلقاء فلم يزل يقاتل حتى انتصف الليل فتحاجز أهل العسكرين وأقبل أبو محجن حتى دخل القصر ووضع عن نفسه ودابته وأعاد رجليه في القيد وأنشأ يقول","topic":"ذكر أبي محجن ونسبه","topicNo":246,"sp":1,"spl":"أبو محجن يقاتل يوم أرماث","partial":1},
{"id":"b246-4","bab":"الجزء 19","sec":"أبو محجن يقاتل يوم أرماث","page":"ج19 ص5","text":"(لقد علمت ثقيف غير فخر ... بأنا نحن أكرمهم سيوفا)\n(وأكثرهم دروعا سابغات ... وأصبرهم إذا كرهوا الوقوفا)\n(وأنا رفدهم في كل يوم ... فإن جحدوا فسل بهم عريفا)\n(وليلة قادس لم يشعروا بي ... ولم أكره بمخرجي الزحوفا)\n(فإن أحبس فقد عرفوا بلائي ... وإن أطلق أجرعهم حتوفا)\nفقالت له سلمى يا أبا محجن في أي شيء حبسك هذا الرجل فقال\nأما والله ما حبسني بحرام أكلته ولا شربته ولكني كنت صاحب شراب في الجاهلية وأنا امرؤ شاعر يدب الشعر على لساني فينفثه أحيانا فحبسني لأني قلت\n(إذا مت فادفني إلى أصل كرمة ... تروي عظامي بعد موتي عروقها)\n(ولا تدفنني في الفلاة فإنني ... أخاف إذا ما مت ألا أذوقها)\n(ليروى بخمر الحص لحمي فإنني ... أسير لها من بعد ما قد أسوقها)","topic":"ذكر أبي محجن ونسبه","topicNo":246,"sp":2,"spl":"أبو محجن يقاتل يوم أرماث — سعد بن أبي وقاص يفرج عن أبي محجن"},
{"id":"b246-5","bab":"الجزء 19","sec":"سعد بن أبي وقاص يفرج عن أبي محجن","page":"ج19 ص10","text":"قال وكانت سلمى قد رأت في المسلمين جولة وسعد بن أبي وقاص في القصر لعلة كانت به لم يقدر معها على حضور الحرب وكانت قبله عند المثنى بن حارثة الشيباني فلما قتل خلف عليها سعد فلما رأت شدة البأس صاحت وامثنياه ولا مثنى لي اليوم فلطمها سعد فقالت أف لك أجبنا وغيرة وكانت مغاضبة لسعد عشية أرماث وليلة الهدأة وليلة السواد حتى إذا أصبحت أتته وصالحته وأخبرته خبر أبي محجن فدعا به وأطلقه وقال اذهب فلست مؤاخذك بشيء تقوله حتى تفعله قال لا جرم والله إني لا أجبت لساني إلى صفة قبيح أبدا\nأخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا محمد بن حاتم قال حدثنا محمد بن حازم قال حدثنا عمرو بن المهاجر عن إبراهيم بن محمد بن سعد عن أبيه وأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن الحسن بن دينار مولى بني هاشم عن ابن الأعرابي عن المفضل وروايته أتم قالوا كان أبو محجن الثقفي فيمن خرج مع سعد بن أبي وقاص لحرب الأعاجم فكان سعد يؤتى به شاربا فيتهدده فيقول له لست تاركها إلا لله عز و جل فأما لقولك فلا قالوا فأتي به يوم القادسية وقد شرب الخمر فأمر به إلى القيد وكانت بسعد جراحه فلم يخرج يومئذ إلى الناس فاستعمل على الخيل خالد بن عرفطة فلما التقى الناس قال أبو محجن\n(كفى حزنا أن تردي الخيل بالقنا ... وأترك مشدودا علي وثاقيا)\nذكر الأبيات وسائر خبره مثل ما ذكره محمد بن جرير وزاد فيه فجاءت زبراء امرأة سعد هكذا قال والصحيح أنها سلمى فأخبرت سعدا بخبره فقال سعد أما والله لا أضرب اليوم رجلا أبلى الله المسلمين على يده ما أبلاهم فخلي سبيله فقال أبو محجن قد كنت أشربها إذ كان الحد يقام علي وأطهر منها فأما إذ بهرجتني فلا والله لا أشربها أبدا وقال ابن الأعرابي في خبره وقال أبو محجن في ذلك\n(إن كانت الخمر قد عزت وقد منعت ... وحال من دونها الإسلام والحرج)\n(فقد أباكرها صرفا وأمزجها ... ريا وأطرب أحيانا وأمتزج)\n(وقد تقوم على رأسي منعمة ... خوذ إذا رفعت في صوتها غنج)\n(ترفع الصوت أحيانا وتخفضه ... كما يطن ذباب الروضة الهزج)\nخبرني الجوهري والمهلبي قالا حدثنا عمر بن شبة قال لما انصرف أبو محجن ليعود إلى محبسه رأته امرأة فظنته منهزما فأنشأت تعيره بفراره\n(من فارس كره الطعان يعيرني ... رمحا إذا نزلوا بمزج الصفر)\nقال لها أبو محجن\n(إن الكرام على الجياد مبيتهم ... فدعي الرماح لأهلها وتعطري)","topic":"ذكر أبي محجن ونسبه","topicNo":246,"sp":2,"spl":"أبو محجن يقاتل يوم أرماث — سعد بن أبي وقاص يفرج عن أبي محجن"},
{"id":"b246-6","bab":"الجزء 19","sec":"أبو محجن يرثي أبا عبيد بن مسعود","page":"ج19 ص12","text":"وذكر السري عن شعيب عن سيف في خبره ووافقته رواية ابن الأعرابي عن المفضل أن الناس لما التقوا مع العجم يوم قس الناطف كان مع الأعجام فيل يكر عليهم تقوم له الخيل فقال أبو عبيد بن مسعود هل له مقتل فقيل له نعم خرطومه إلا أنه لا يفلت منه من ضربه قال فأنا أهب نفسي لله وكمن\nله حتى إذا أقبل وثب إليه فضرب خرطومه بالسيف فرمى به ثم شد عليه الفيل فقتله ثم استدار فطحن الأعاجم وانهزموا فقال أبو محجن الثقفي أبا عبيد\n(أنى تسدت نحونا أم يوسف ... ومن دون مسراها فياف مجاهل)\n(إلى فتية بالطف نيلت سراتهم ... وغودر أفراس لهم ورواحل)\n(وأضحى أبو جبر خلاء بيوته ... وقد كان يغشاها الضعاف الأرامل)\n(وأضحى بنو عمرو لدى الجسر منهم ... إلى جانب الأبيات جود ونائل)\n(وما لمت نفسي فيهم غير أنها ... لها أجل لم يأتها وهو عاجل)\n(وما رمت حتى خرقوا بسلاحهم ... إهابي وجادت بالدماء الأباجل)\n(وحتى رأيت مهرتي مزوئرة ... من النبل يدمى نحرها والشواكل)\n(وما رحت حتى كنت آخر رائح ... وصرع حولي الصالحون الأماثل)\n(مررت على الأنصار وسط رحالهم ... فقلت ألا هل منكم اليوم قافل)\n(وقربت رواحا وكورا ونمرقا ... وغودر في أليس بكر ووائل)\n(ألا لعن الله الذين يسرهم ... رداي وما يدرون ما الله فاعل)\nال الأخفش في روايته عن الأحول عن ابن الأعرابي عن المفضل قال أبو محجن في تركه الخمر\n(رأيت الخمر صالحة وفيها ... مناقب تهلك الرجل الحليما)\n(فلا والله أشربها حياتي ... ولا أسقي بها أبدا نديما)\nخبرني عمي قال حدثنا محمد بن سعد الكراني قال حدثنا العمري عن لقيط عن الهيثم بن عدي وأخبرني محمد بن الحسن بن دريد قال حدثنا عبد الرحمن بن أخي الأصمعي عن عمه وأخبرني إبراهيم بن أيوب عن ابن قتيبة قالوا دخل ابن أبي محجن على معاوية فقال له أليس أبوك الذي يقول\n(إذا مت فادفني إلى أصل كرمة ... تروي عظامي بعد موتي عروقها)\n(ولا تدفنني بالفلاة فإنني ... أخاف إذا ما مت ألا أذوقها)\nقال ابن أبي محجن لو شئت لذكرت ما هو أحسن من هذا من شعره قال وما ذاك قال قوله\n(لا تسألي الناس عن مالي وكثرته ... وسائلي الناس ما فعلي وما خلقي)\n(أعطي السنان غداة الروع حصته ... وعامل الرمح أرويه من العلق)\n(وأطعن الطعنة النجلاء عن عرض ... وأحفظ السر فيه ضربة العنق)\n(عف المطالب عما لست نائله ... وإن ظلمت شديد الحقد والحنق)\n(وقد أجود ومالي بذي فنع ... وقد أكر وراء المحجر البرق)\n(والقوم أعلم أني من سراتهم ... إذا سما بصر الرعديدة الشفق)\n(قد يعسر المرء حينا وهو ذو كرم ... وقد يثوب سوام العاجز الحمق)\n(سيكثر المال يوما بعد قلته ... ويكتسي العود بعد اليبس بالورق)\nقال معاوية لئن كنا أسأنا لك القول لنحسنن لك الصفد ثم أجزل جائزته وقال إذا ولدت النساء فلتلد مثلك","topic":"ذكر أبي محجن ونسبه","topicNo":246,"sp":3,"spl":"أبو محجن يرثي أبا عبيد بن مسعود"},
{"id":"b246-7","bab":"الجزء 19","sec":"عمر بن الخطاب يحده في شرب الخمر","page":"ج19 ص15","text":"أخبرني الحسن بن علي وعيسى بن الحسين الوراق قالا حدثنا ابن مهرويه قال حدثني صالح بن عبد الرحمن الهاشمي عن العمري عن العتبي قال أتي عمر بن الخطاب رضي الله عنه بجماعة فيهم أبو محجن الثقفي وقد شربوا الخمر فقال أشربتم الخمر بعد أن حرمها الله ورسوله فقالوا ما حرمها الله ولا رسوله إن الله تعالى يقول\n(ليس على الذين آمنوا وعملوا الصالحات جناح فيما طعموا إذا ما اتقوا وآمنوا وعملوا الصالحات ... )\nفقال عمر لأصحابه ما ترون فيهم فاختلفوا فيهم فبعث إلى علي بن أبي طالب عليه السلام فشاوره فقال علي\nإن كانت هذه الآية كما يقولون فينبغي أن يستحلوا الميتة والدم ولحم الخنزير فسكتوا فقال عمر لعلي ما ترى فيهم قال أرى إن كانوا شربوها مستحلين لها أن يقتلوا وإن كانوا شربوها وهم يؤمنون أنها حرام أن يحدوا فسألهم فقالوا والله ما شككنا في أنها حرام ولكنا قدرنا أن لنا نجاة فيما قلناه فجعل يحدهم رجلا رجلا وهم يخرجون حتى انتهى إلى أبي محجن فلما جلده أنشأ يقول\n(ألم تر أن الدهر يعثر بالفتى ... ولا يستطيع المرء صرف المقادر)\n(صبرت فلم أجزع ولم أك كائعا ... لحادث دهر في الحكومة جائر)\n(وإني لذو صبر وقد مات إخوتي ... ولست عن الصهباء يوما بصابر)\n(رماها أمير المؤمنين بحتفها ... فخلانها يبكون حول المعاصر)\nلما سمع عمر قوله\n(ولست عن الصهباء يوما بصابر ... )\nال قد أبديت ما في نفسك ولأزيدنك عقوبة لإصرارك على شرب الخمر فقال له علي عليه السلام ما ذلك لك وما يجوز أن تعاقب رجلا قال لأفعلن وهو لم يفعل وقد قال الله في الشعراء ( وأنهم يقولون ما لا يفعلون\nفقال عمر قد استثنى الله منهم قوما فقال ( إلا الذين آمنوا وعملوا الصالحات\nفقال علي عليه السلام أفهؤلاء عندك منهم وقد قال رسول الله لا يشرب العبد الخمر حين يشربها وهو مؤمن\nأخبرنا محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم بن فراس قال حدثنا العمري عن الهيثم بن عدي قال أخبرني من مر بقبر أبي محجن الثقفي في نواحي أذربيجان أو قال في نواحي جرجان فرأيت قبره وقد نبتت عليه ثلاثة أصول كرم قد طالت وأثمرت وهي معروشة وعلى قبره مكتوب هذا قبر أبي محجن الثقفي فوقفت طويلا أتعجب مما اتفق له حتى صار كأمنية بلغها حيث يقول\n(إذا مت فادفني إلى أصل كرمة ... تروي عظامي بعد موتي عروقها)\n(ألا يا لقومي لا أرى النجم طالعا ... ولا الشمس إلا حاجبي بيميني)\n(معزيتي خلف القفا بعمودها ... فجل نكيري أن أقول ذريني)\n(أمين على أسرارهن وقد أرى ... أكون على الأسرار غير أمين)\n(فللموت خير من حداج موطأ ... مع الظعن لا يأتي المحل لحين)\nعروضه من الطويل والمعزية امرأة تكون مع الشيخ الخرف تكلؤه وقوله\n(أمين على أسرارهن . . ... .)\nي أن النساء صرن يتحدثن بين يدي بأسرارهن ويفعلن ما كن قبل ذلك يرهبنني فيه لأني لا أضرهن والحداج والحدج مركب من مراكب النساء الشعر لزهير بن جناب الكلبي والغناء لأهل مكة ولحنه من خفيف الثقيل الأول بالوسطى عن الهشامي وحبش وفيه لحنين ثاني ثقيل بالوسطى","topic":"ذكر أبي محجن ونسبه","topicNo":246,"sp":4,"spl":"عمر بن الخطاب يحده في شرب الخمر","partial":1},
{"id":"b247-1","bab":"الجزء 19","sec":"أخبار زهير بن جناب ونسبه","page":"ج19 ص18","text":"زهير بن جناب بن هبل بن عبد الله بن كنانة بن بكر بن عوف بن عذرة بن زيد اللات بن رفيدة بن ثور بن كلب بن وبرة بن تغلب بن حلوان بن عمران بن الحاف بن قضاعة شاعر جاهلي وهو أحد المعمرين وكان سيد بني كلب وقائدهم في حروبهم وكان شجاعا مظفرا ميمون النقيبة في غزواته وهو أحد من مل عمره فشرب الخمر صرفا حتى قتلته ولم يوجد شاعر في الجاهلية والإسلام ولد من الشعراء أكثر ممن ولد زهير وسأذكر أسماءهم وشيئا من شعرهم بعقب ذكر خبره إن شاء الله تعالى","topic":"أخبار زهير بن جناب ونسبه","topicNo":247,"sp":0,"spl":"أخبار زهير بن جناب ونسبه"},
{"id":"b247-2","bab":"الجزء 19","sec":"غزوة غطفان","page":"ج19 ص19","text":"قال ابن الأعرابي كان سبب غزوة زهير بن جناب غطفان أن بني بغيض حين خرجوا من تهامة ساروا بأجمعهم فتعرضت لهم صداء وهي قبيلة من مذحج فقاتلوهم وبنو بغيض سائرون بأهليهم ونسائهم وأموالهم فقاتلوا عن حريمهم فظهروا على صداء فأوجعوا فيهم ونكأوا وعزت بنو بغيض بذلك وأثرت وأصابت غنائم فلما رأوا ذلك قالوا أما والله لنتخذن حرما مثل حرم مكة لا يقتل صيده ولا يعضد شجره ولا يهاج عائذه فوليت ذلك بنو مرة ابن عوف\nثم كان القائم على أمر الحرم وبناء حائطه رياح بن ظالم ففعلوا ذلك وهم على ماء لهم يقال له بس وبلغ فعلهم وما أجمعوا عليه زهير بن جناب وهو يومئذ سيد بني كلب فقال والله لا يكون ذلك أبدا وأنا حي ولا أخلي غطفان تتخذ حرما أبدا فنادى في قومه فاجتمعوا إليه فقام فيهم فذكر حال غطفان وما بلغه عنها وأن أكرم مأثرة يعتقدها هو وقومه أن يمنعوهم من ذلك ويحولوا بينهم وبينه فأجابوه واستمد بني القين من جشم فأبوا أن يغزوا معه فسار في قومه حتى غزا غطفان فقاتلهم فظفر بهم زهير وأصاب حاجته فيهم وأخذ فارسا منهم أسيرا في حرمهم الذي بنوه فقال لبعض أصحابه اضرب رقبته فقال إنه بسل فقال زهير وأبيك ما بسل علي بحرام ثم قام إليه فضرب عنقه وعطل ذلك الحرم ثم من على غطفان ورد النساء واستاق الأموال وقال زهير في ذلك\n(ولم تصبر لنا غطفان لما ... تلاقينا وأحرزت النساء)\n(فلولا الفضل منا ما رجعتم ... إلى عذراء شيمتها الحياء)\n(وكم غادرتم بطلا كميا ... لدى الهيجاء كان له غناء)\n(فدونكم ديونا فاطلبوها ... وأوتارا ودونكم اللقاء)\n(فإنأ حيث لا نخفى عليكم ... ليوث حين يحتضر اللواء)\n(فخلي بعدها غطفان بسا ... وما غطفان والأرض الفضاء)\n(فقد أضحى لحي بني جناب ... قضاء الأرض والماء الرواء)\n(ويصدق طعننا في كل يوم ... وعند الطعن يختبر اللقاء)\n(نفينا نخوة الأعداء عنا ... بأرماح أسنتها ظماء)\n(ولولا صبرنا يوم التقينا ... لقينا مثل ما لقيت صداء)\n(غداة تعرضوا لبني بغيض ... وصدق الطعن للنوكى شفاء)\n(وقد هربت حذار الموت قين ... على آثار من ذهب العفاء)\n(وقد كنا رجونا أن يمدوا ... فأخلفنا من أخوتنا الرجاء)\n(وألهى القين عن نصر الموالي ... حلاب النيب والمرعى الضراء)\nقال أبو عمرو الشيباني كان أبرهة حين طلع نجدا أتاه زهير بن جناب فأكرمه أبرهة وفضله على من أتاه من العرب ثم أمره على ابني وائل تغلب وبكر فوليهم حتى أصابتهم سنة شديدة فاشتد عليهم ما يطلب منهم زهير فأقام بهم زهير في الجدب ومنعهم من النجعة حتى يؤدوا ما عليهم فكادت مواشيهم تهلك فلما رأى ذلك ابن زيابة أحد بني تيم الله بن ثعلبة وكان رجلا فاتكا بيت زهيرا وكان نائما في قبة له من أدم فدخل فألفى\nزهيرا نائما وكان رجلا عظيم البطن فاعتمد التيمي بالسيف على بطن زهير حتى أخرجه من ظهره مارقا بين الصفاق وسلمت أعفاج بطنه وظن التيمي أنه قد قتله وعلم زهير أنه قد سلم فتخوف أن يتحرك فيجهز عليه فسكت وانصرف ابن زيابة إلى قومه فقال لهم قد والله قتلت زهيرا وكفيتكموه فسرهم ذلك ولما علم زهير أنه لم يقدم عليه إلا عن ملأ من قومه بكر وتغلب وإنما مع زهير نفر من قومه بمنزلة الشرط أمر زهير قومه فغيبوه بين عمودين في ثياب ثم أتوا القوم فقالوا لهم إنكم قد فعلتم بصاحبنا ما فعلتم فأذنوا لنا في دفنه ففعلوا فحملوا زهيرا ملفوفا في عمودين والثياب عليه حتى إذا بعدوا عن القوم أخرجوه فلففوه في ثيابه ثم حفروا حفيرة وعمقوا ودفنوا فيها العمودين ثم ساروا ومعهم زهير فلما بلغ زهير أرض قومه جمع لبكر وتغلب الجموع وبلغهم أن زهيرا حي فقال ابن زباية\n(طعنة ما طعنت في غبش الليل ... زهيرا وقد توافى الخصوم)\n(حين تجبي له المواسم بكر ... أين بكر وأين منها الحلوم)\n(خانني السيف إذ طعنت زهيرا ... وهو سيف مضلل مشؤوم)","topic":"أخبار زهير بن جناب ونسبه","topicNo":247,"sp":1,"spl":"غزوة غطفان"},
{"id":"b247-3","bab":"الجزء 19","sec":"زهير يغزو بكرا وتغلب","page":"ج19 ص22","text":"قال وجمع زهير بني كلب ومن تجمع له من شذاذ العرب والقبائل ومن أطاعه من أهل اليمن فغزا بكرا وتغلب ابني وائل وهم على ماء يقال له الحبي وقد كانوا نذروا به فقاتلهم قتالا شديدا ثم انهزمت بكر\nوأسلمت بني تغلب فقاتلت شيئا من قتال ثم انهزمت وأسر كليب ومهلهل ابنا ربيعة واستيقت الأموال وقتلت كلب في تغلب قتلى كثيرة وأسروا جماعة من فرسانهم ووجوههم وقال زهير بن جناب في ذلك\n(تبا لتغلب أن تساق نساؤهم ... سوق الإماء إلى المواسم عطلا)\n(لحقت أوائل خيلنا سرعانهم ... حتى أسرن على الحبي مهلهلا)\n(إنا مهلهل ما تطيش رماحنا ... أيام تنقف في يديك الحنظلا)\n(ولت حماتك هاربين من الوغى ... وبقيت في حلق الحديد مكبلا)\n(فلئن قهرت لقد أسرتك عنوة ... ولئن قتلت لقد تكون مؤملا)\nوقال أيضا يعير بني تغلب بهذه الوقعة في قصيدة أولها حي دارا تغيرت بالجناب ... أقفرت من كواعب أتراب\nقول فيها\n(أين أين الفرار من حذر الموت ... وإذا يتقون بالأسلاب)\n(إذ أسرنا مهلهلا وأخاه ... وابن عمرو في القد وابن شهاب)\n(وسبينا من تغلب كل بيضاء ... رقود الضحى برود الرضاب)\n(يوم يدعو مهلهل يا لبكرها ... أهذي حفيظة الأحساب)\n(ويحكم ويحكم أبيح حماكم ... يا بني تغلب أما من ضراب)\n(وهم هاربون في كل فج ... كشريد النعام فوق الروابي)\n(واستدارت رحى المنايا عليهم ... بليوث من عامر وجناب)\n(طحنتهم أرحاؤها بطحون ... ذات ظفر حديدة الأنياب)\n(فهم بين هارب ليس يألوا ... وقتيل معفر في التراب)\n(فضل العز عزنا حين نسموا ... مثل فضل السماء فوق السحاب)\nخبرني محمد بن الحسن بن دريد قال حدثنا عمي عن ابن الكلبي عن أبيه قال وفد زهير بن جناب وأخوه حارثة على بعض ملوك غسان فلما دخلا عليه حدثاه وأنشداه فأعجب بهما ونادمهما فقال يوما لهما إن أمي عليلة شديدة العلة وقد أعياني دواؤها فهل تعرفان لها دواء فقال حارثة كميرة حارة وكانت فيه لوثة فقال الملك أي شيء قلت فقال له زهير كميئة حارة تطعمها فوثب الملك وقد فهم الأولى والآخرة يريهما أنه يأمر بإصلاح\nالكمأة لها وحلم عن مقالة حارثة وقال حارثة لزهير يا زهير اقلب ما شئت ينقلب فأرسلها مثلا","topic":"أخبار زهير بن جناب ونسبه","topicNo":247,"sp":2,"spl":"زهير يغزو بكرا وتغلب"},
{"id":"b247-4","bab":"الجزء 19","sec":"بلغ عمرا طويلا فكان يخرج تائها","page":"ج19 ص25","text":"أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني أحمد بن الغيث الباهلي عن أبيه قال كان من حديث زهير بن جناب الكلبي أنه كان قد بلغ عمرا طويلا حتى ذهب عقله وكان يخرج تائها لا يدري أين يذهب فتلحقه المرأة من أهله والصبي فترده وتقول له إني أخاف عليك الذئب أن يأكلك فأين تذهب فذهب يوما من أيامه ولحقته ابنة له فردته فرجع معها وهو يهدج كأنه رأل وراحت عليهم سماء في الصيف فعلتهم منها بغشة ثم أردفها غيث فنظر وسمع له الشيخ زجلا منكرا فقال ما هذا يا بنية فقالت عارض هائل إن أصابنا دون أهلنا هلكنا فقال انعتيه لي فقالت أراه منبطحا مسلنطحا قد ضاق ذرعا وركب ردعا ذا هيدب يطير وهماهم وزفير ينهض نهض الطير\nالكسير عليه مثل شباريق الساج في ظلمة الليل الداج يتضاحك مثل شعل النيران تهرب منه الطير وتوائل منه الحشرة قال أي بنية وائلي منه إلى عصر قبل أن لا عين ولا أثر أخبرني محمد بن القاسم الأنباري قال حدثني أبي قال حدثني أحمد ابن عبيد عن ابن الكلبي عن مشيخة من الكلبيين قالوا عاش زهير بن جناب بن هبل بن عبد الله خمسين ومائتي سنة أوقع فيها مائتي وقعة في العرب ولم تجتمع قضاعة إلا عليه وعلى حن بن العذري ولم يكن في اليمن أشجع ولا أخطب ولا أوجه عند الملوك من زهير وكان يدعى الكاهن لصحة رأيه قال هشام ذكر حماد الراوية أن زهيرا عاش أربعمائة وخمسين سنة قال وقال الشرقي بن القطامي عاش زهير أربعمائة سنة فرأته ابنة له فقالت لابن ابنها خذ بيد جدك فقال له من أنت فقال فلان بن فلان بن فلانة فأنشأ يقول\n(أبني إن أهلك فقد ... أورثتكم مجدا بنيه)\n(وتركتكم أبناء سادات ... زنادكم وريه)\n(ولكل ما نال الفتى ... قد نلته إلا التحيه)\n(والموت خير للفتى ... فليهلكن وبه بقيه)\n(من أن يرى الشيخ البجال ... وقد تهادى بالعشيه)\n(ولقد شهدت النار للأسلاف ... توقد في طميه)\n(ولقد رحلت البازل الكوماء ... ليس لها وليه)\n(وخطبت خطبة ماجد ... غير الضعيف ولا العييه)\n(ولقد غدوت بمشرف القطرين ... لم يغمز شظيه)\n(فأصبت من بقر الجناب ... ضحىومن حمر القفيه)\nال ابن الكلبي وقال زهير في كبره أيضا\n(ألا يالقومي لا أرى النجم طالعا ... ولا الشمس إلا حاجبي بيميني)\n(معزبتي عند القفا بعمودها ... فأقصى نكيري أن أقول ذريني)\n(أمين على أسرارهن وقد أرى ... أكون على الأسرار غير أمين)\n(فللموت خير من حداج موطأ ... على الظعن لا يأتي المحل لحين)\nال وقال زهير أيضا في كبره\n(إن تنسي الأيام إلا جلالة ... أمت حين لا تأسى علي العوائد)\n(فيأذى بي الأدنى ويشمت بي العدا ... ويأمن كيدي الكاشحون الأباعد)\nال وقال زهير أيضا\n(لقد عمرت حتى لا أبالي ... أحتفي في صباحي أم مسائي)\n(وحق لمن أتت مائتان عاما ... عليه أن يمل من الثواء)\n(شهدت الموقدين على خزازى ... وبالسلان جمعا ذا زهاء)\n(ونادمت الملوك من آل عمرو ... وبعدهم بني ماء السماء)\nال ابن الكلبي وكان زهير إذا قال ألا إن الحي ظاعن ظعنت قضاعة وإذا قال ألا إن الحي مقيم نزلوا وأقاموا فلما أن أسن نصب ابن أخيه عبد الله ابن عليم للرياسة في كلب وطمع أن يكون كعمه وتجتمع قضاعة كلها عليه فقال زهير يوما ألا إن الحي ظاعن فقال عبد الله ألا إن الحي مقيم فقال زهير ألا إن الحي مقيم فقال عبد الله ألا إن الحي ظاعن فقال زهير من هذا المخالف علي منذ اليوم فقالوا ابن أخيك عبد الله بن عليم فقال أعدى الناس للمرء ابن أخيه إلا أنه لا يدع قاتل عمه أو يقتله ثم أنشأ يقول\n(وكيف بمن لا أستطيع فراقه ... ومن هو إن لم تجمع الدار آلف)\n(أمير شقاق إن أقم لا يقم معي ... ويرحل وإن أرحل يقم ويخالف)\nم شرب الخمر صرفا حتى مات قال وممن شرب الخمر صرفا حتى مات عمرو بن كلثوم التغلبي وأبو براء عامر بن مالك ملاعب الأسنة قال هشام عاش هبل بن عبد الله جد زهير بن جناب ستمائة سنة وسبعين وهو القائل\n(يا رب يوم قد غني فيه هبل ... له نوال ودرور وجذل)\n(كأنه في العز عوف أو حجل ... )","topic":"أخبار زهير بن جناب ونسبه","topicNo":247,"sp":3,"spl":"بلغ عمرا طويلا فكان يخرج تائها","partial":1},
{"id":"b247-5","bab":"الجزء 19","sec":"بلغ عمرا طويلا فكان يخرج تائها","page":"ج19 ص25","text":"ال عوف وحجل قبيلتان من كلب وقال أبو عمرو الشيباني كان الجلاح بن عوف السحمي قد وطأ لزهير بن جناب وأنزله معه فلم يزل في جناحه حتى كثر ماله وولده وكانت أخت زهير متزوجة في بني القين بن جسر فجاء رسولها إلى زهير ومعه برد فيه صرار رمل وشوكة قتاد فقال زهير لأصحابه أتتكم شوكة شديدة وعدد كثير فاحتملوا\nفقال له الجلاح أنحتمل لقول امرأة والله لا نفعل فقال زهير\n(أما الجلاح فإنني فارقته ... لا عن قلى ولقدتشط بنا النوى)\n(فلئن ظعنت لأصبحن مخيما ... ولئن أقمت لأظعنن على هوى)","topic":"أخبار زهير بن جناب ونسبه","topicNo":247,"sp":4,"spl":"بلغ عمرا طويلا فكان يخرج تائها — حارب الجيش وقتل رئيسا منهم"},
{"id":"b247-6","bab":"الجزء 19","sec":"حارب الجيش وقتل رئيسا منهم","page":"ج19 ص30","text":"قال فأقام الجلاح وظعن زهير وصبحهم الجيش فقتل عامة قوم الجلاح وذهبوا بماله قال واسم الجلاح عامر بن عوف بن بكر بن عوف بن عامر بن عوف ابن عذرة ومضى زهير لوجهه حتى اجتمع مع عشيرته من بني جناب وبلغ الجيش خبره فقصدوه فحاربهم وثبت لهم فهزمهم وقتل رئيسا منهم فانصرفوا عنه خائبين فقال زهير\n(أمن آل سلمى ذا الخيال المؤرق ... وقد يمق الطيف الغريب المشوق)\n(وأنى اهتدت سلمى لوجه محلنا ... وما دونها من مهمه الأرض يخفق)\n(فلم تر إلا هاجعا عند حرة ... على ظهرها كور عتيق ونمرق)\n(ولما رأتني والطليح تبسمت ... كما انهل أعلى عارض يتألق)\n(فحييت عنا زودينا تحية ... لعل بها العاني من الكبل يطلق)\n(فردت سلاما ثم ولت بحاجة ... ونحن لعمري يابنة الخير أشوق)\n(فيا طيب ما ريا ويا حسن منظر ... لهوت به لو أن رؤياك تصدق)\n(ويوم أثالى قد عرفت رسومها ... فعجنا إليها والدموع ترقرق)\n(وكادت تبين القول لما سألتها ... وتخبرني لو كانت الدار تنطق)\n(فيا دار سلمى هجت للعين عبرة ... فماء الهوى يرفض أو يترقرق)\nقال زهير في هذه القصيدة يذكر خلاف الجلاح عليه\n(أيا قومنا إن تقبلوا الحق فانتهوا ... وإلا فأنياب من الحرب تحرق)\n(فجاؤوا إلى رجراجة مكفهرة ... يكاد المدير نحوها الطرف يصعق)\n(سيوف وأرماح يأيدي أعزة ... وموضونة مما أفاد محرق)\n(فما برحوا حتى تركنا رئيسهم ... وقد مار فيه المضرحي المذلق)\n(وكائن ترى من ماجدوابن ماجد ... له طعنة نجلاء للوجه يشهق)\nقال زهير في ذلك أيضا\n(سائل أميمة عني هل وفيت لها ... أم هل منعت من المخزاة جيرانا)\n(لا يمنع الضيف إلا ماجد بطل ... إن الكريم كريم أينما كانا)\n(لما أبى جيرتي إلا مصممة ... تكسو الوجوه من المخزاة ألوانا)\n(ملنا عليهم بورد لا كفاء له ... يفلقن بالبيض تحت النقع أبدانا)\n(إذا ارجحنوا علونا هامهم قدما ... كأنما نختلي بالهام خطبانا)\n(كم من كريم هوى للوجه منعفرا ... قد اكتسى ثوبه في النقع ألوانا)\n(ومن عميد تناهى بعد عثرته ... تبدو ندامته للقوم خزيانا)","topic":"أخبار زهير بن جناب ونسبه","topicNo":247,"sp":4,"spl":"بلغ عمرا طويلا فكان يخرج تائها — حارب الجيش وقتل رئيسا منهم"},
{"id":"b247-7","bab":"الجزء 19","sec":"نماذج من أولاده الشعراء","page":"ج19 ص32","text":"وأما الشعراء من ولد زهير فمنهم مصاد بن أسعد بن جنادة بن صهبان بن امرئ القيس بن زهير بن جناب وهو القائل\n(تمنيت أن تلقى لقاح ابن محرز ... وقبلك شامتها العيون النواظر)\n(ممنحة في الأقربين مناخة ... وللضيف فيها والصديق معاقر)\n(فهلا بني عيناء عاينت جمعهم ... بحالة إذ سدت عليك المصادر)\nمنهم حريث بن عامر بن الحارث بن امرئ القيس بن زهير بن جناب وهو القائل\n(أرى قومي بني قطن أرادوا ... بألا يتركوا بيدي مالا)\n(فإن لم أجزهم غيظا بغيظ ... وأوردهم على عجل شلالا)\n(فليت التغلبية لم تلدني ... ولا أغنت بما ولدت قبالا)\nومنهم الحزنبل بن سلامة بن زهير بن أسعد بن صهبان بن امرئ القيس\nابن زهير بن جناب وهو القائل\n(عبثت بمنخرق القميص كأنه ... وضح الهلال على الخمور معذل)\n(يا سلم ويحك والخليل معاتب ... أزمعت أن تصلي سواي وتبخلي)\n(لما رأيت بعارضي ولمتي ... غير المشيب على الشباب المبدل)\n(صرمت حبل فتى يهش إلى الندى ... لو تطلبين نداه لم يتعلل)\n(إنا لنصبر عند معترك الوغى ... ونبذ مكرمة الكريم المفضل)\nومنهم غرير بن أبي جابر بن زهير بن جناب وهو القائل\n(أبلغ أبا عمرو وأنت ... علي ذو النعم الجزيله)\n(أنا منعنا أن تذل ... بلادكم وبنو جديله)\n(وطرقتهم ليلا أخبرهم ... بهم ومعي وصيله)\n(فصدقتهم خبري فطاروا ... في بلادهم الطويله)\nمنهم عرفجة بن جنادة بن أبي بن النعمان بن زهير بن جناب وهو القائل\n(عفا أبرق العزاف من أم جابر ... فمنعرج الوادي عفا فحفير)\n(فروض ثوير عن يمين روية ... كأن لم تربعه أوانس حور)\n(رقاق الثنايا والوجوه كأنها ... ظباء الفلا في لحظهن فتور)\nمنهم المسيب بن رفل بن حارثة بن جناب بن قيس بن امرئ القيس ابن أبي جابر بن زهير بن جناب وهو القائل\n(قتلنا يزيد بن المهلب بعد ما ... تمنتم أن يغلب الحق باطله)\n(وما كان منكم في العراق منافق ... عن الدين إلا من قضاعة قاتله)\n(تجلله قحل بأبيض صارم ... حسام جلا عن شفرتيه صياقله)\nعني بالقحل ابن عياش بن شمر بن أبي شراحيل بن غرير بن أبي جابر بن زهير بن جناب وهو الذي قتل يزيد بن المهلب ومن بني زهير شعراء كثير ذكرت منهم الفحول دون غيرهم صوت\n(تدعي الشوق إن نأت ... وتجنى إذا دنت)\n(سرني لو صبرت عنها ... فتجزى بما جنت)\n(إن سلمى لو اتقت ... ربها في أنجزت)\n(زرعت في الحشا الهوى ... وسقته حتى نبت)\nالشعر لمسلم بن الوليد والغناء لعريب خفيف ثقيل وقيل إنه لأبي العبيس بن حمدون وذكر الهشامي أن لإسحاق في إن سلمى وما بعده لحنا من الثقيل الأول بالبنصر","topic":"أخبار زهير بن جناب ونسبه","topicNo":247,"sp":5,"spl":"نماذج من أولاده الشعراء"},
{"id":"b248-1","bab":"الجزء 19","sec":"نسب مسلم بن الوليد وأخباره","page":"ج19 ص35","text":"وهو مسلم بن الوليد أبوه الوليد مولى الأنصار ثم مولى أبي أمامة أسعد بن زرارة الخزرجي يلقب صريع الغواني شاعر متقدم من شعراء الدولة العباسية منشؤه ومولده الكوفة وهو فيما زعموا أول من قال الشعر المعروف بالبديع هو لقب هذا الجنس البديع واللطيف وتبعه فيه جماعة وأشهرهم فيه أبو تمام الطائي فإنه جعل شعره كله مذهبا واحدا فيه ومسلم كان متفننا متصرفا في شعره أخبرني علي بن سليمان الأخفش قال قال أبو العباس محمد بن يزيد كان مسلم شاعرا حسن النمط جيد القول في الشراب وكثير من الرواة يقرنه بأبي نواس في هذا المعنى وهو أول من عقد هذه المعاني الظريفة واستخرجها حدثنا أحمد بن عبيد الله بن عمار قال حدثنا محمد بن القاسم بن مهرويه قال سمعت أبي يقول أول من أفسد الشعر مسلم بن الوليد جاء بهذا الذي سماه الناس البديع ثم جاء الطائي بعده فتفنن فيه","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":0,"spl":"نسب مسلم بن الوليد وأخباره — مسلم ويزيد بن مزيد"},
{"id":"b248-2","bab":"الجزء 19","sec":"مسلم ويزيد بن مزيد","page":"ج19 ص36","text":"أخبرني إبراهيم بن أيوب عن عبد الله بن مسلم الدينوري قال\nكان مسلم بن الوليد وأخوه سليمان منقطعين إلى يزيد بن مزيد ومحمد ابن منصور بن زياد ثم الفضل بن سهل بعد ذلك وقلد الفضل مسلما المظالم بجرجان فمات بها أخبرني علي بن سليمان قال حدثنا محمد بن يزيد قال كان السبب في قول مسلم\n(تدعي الشوق إن نأت ... وتجنى إذا دنت)\nنه علق جارية ذات ذكر وشرف وكان منزلها في مهب الشمال من منزله وفي ذلك يقول صوت\n(أحب الريح ما هبت شمالا ... وأحسدها إذا هبت جنوبا)\n(أهابك أن أبوح بذات نفسي ... وأفرق إن سألتك أن أخيبا)\n(وأهجر صاحبي حب التجني ... عليه إذا تجنيت الذنوبا)\n(كأني حين أغضي عن سواكم ... أخاف لكم على عيني رقيبا)\nغنى عبد الله بن العباس الربيعي في هذه الأبيات هزجا بالبنصر عن الهشامي قال وكانت له جارية يرسلها إليها ويبثها سره وتعود إليه بأخبارها ورسائلها فطال ذلك بينهما حتى أحبتها الجارية التي علقها مسلم ومالت إليها وكلتاهما في نهاية الحسن والكمال وكان مسلم يحب جاريته هذه محبة شديدة ولم يكن يهوى تلك إنما كان يريد الغزل والمجون والمراسلة وأن يشيع له حديث بهواها وكان يرى ذلك من الملاحة والظرف والأدب فلما رأى مودة تلك لجاريته هجر جاريته مظهرا لذلك وقطعها عن الذهاب إلى تلك وذلك قوله\n(وأهجر صاحبي حب التجني ... عليه إذا تجنيت الذنوبا)\nراسلها مع غير جاريته الأولى وذلك قوله\n(تدعي الشوق إن نأت ... وتجنى إذا دنت)\n(واعدتنا وأخلفت ... ثم ساءت فأحسنت)\n(سرني لو صبرت عنها فتجزى بما جنت ... )\n(إن سلمى لو أتقت ... ربها في أنجزت)\n(زرعت في الحشا الهوى ... وسقته حتى نبت)","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":0,"spl":"نسب مسلم بن الوليد وأخباره — مسلم ويزيد بن مزيد","partial":1},
{"id":"b248-3","bab":"الجزء 19","sec":"مسلم يختلف مع أبي نواس في الشعر","page":"ج19 ص38","text":"أخبرني الحسين بن يحي ومحمد بن يزيد قالا حدثنا حماد بن إسحاق عن أبيه قال\nلقي مسلم بن الوليد أبا نواس فقال له ما أعرف لك بيتا إلا فيه سقط قال فما تحفظ من ذلك قال قل أنت ما شئت حتى أريك سقطه فيه فأنشده\n(ذكر الصبوح سحيرة فارتاحا ... وأمله ديك الصباح صياحا)\nقال له مسلم فلم أمله وهو الذي أذكره وبه ارتاح فقال أبو نواس فأنشدني شيئا من شعرك ليس فيه خلل فأنشده مسلم\n(عاصى الشباب فراح غير مفند ... وأقام بين عزيمة وتجلد)\nقال له أبو نواس قد جعلته رائحا مقيما في حال واحدة وبيت واحد فتشاغبا وتسابا ساعة وكلا البيتين صحيح المعنى أخبرني جعفر بن قدامة قال قال لي محمد بن عبد الله بن مسلم حدثني أبي قال اجتمع أصحاب المأمون عنده يوما فأفاضوا في ذكر الشعر والشعراء فقال له بعضهم أين أنت يا أمير المؤمنين عن مسلم بن الوليد قال حيث يقول ماذا قال حيث يقول وقد رثى رجلا\n(أرادوا ليخفوا قبره عن عدوه ... فطيب تراب القبر دل على القبر)\nحيث مدح رجلا بالشجاعة فقال\n(يجود بالنفس إذ ضن الجواد بها ... والجود بالنفس أقصى غاية الجود)\nهجا رجلا بقبح الوجه والأخلاق فقال\n(قبحت مناظره فحين خبرته ... حسنت مناظره لقبح المخبر)\n(وتغازل فقال ... )\n(هوى يجد وحبيب يلعب ... أنت لقى بينهما معذب)\nقال المأمون هذا أشعر من خضتم اليوم في ذكره أخبرني محمد بن عمران الصيرفي والحسن بن علي الخفاف قالا حدثنا الحسن بن عليل العنزي قال حدثني قعنب بن المحرز وابن النطاح عن القحذمي قال قال يزيد بن مزبد أرسل إلى الرشيد يوما في وقت لا يرسل فيه إلى مثلي فأتيته لابسا سلاحي مستعدا لأمر إن أراده فلما رآني ضحك إلي ثم قال يا يزيد خبرني من الذي يقول فيك\n(تراه في الأمن في درع مضاعفة ... لا يأمن الدهر أن يدعى على عجل)\n(صافي العيان طموح العين همته ... فك العناة وأسر الفاتك الخطل)\n(لله من هاشم في أرضه جبل ... وأنت وابنك ركنا ذلك الجبل)\nقلت لا أعرفه يا أمير المؤمنين قال سوءة لك من سيد قوم يمدح\nبمثل هذا الشعر ولا تعرف قائله وقد بلغ أمير المؤمنين فرواه ووصل قائله وهو مسلم بن الوليد فانصرفت فدعوت به ووصلته ووليته","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":1,"spl":"مسلم يختلف مع أبي نواس في الشعر","partial":1},
{"id":"b248-4","bab":"الجزء 19","sec":"يزيد بن مزيد يأمر له بجائزة","page":"ج19 ص41","text":"أخبرني محمد بن عمران الصيرفي والحسن بن علي الخفاف قالا حدثنا الحسن بن عليل العنزي قال حدثني أبو عبد الله أحمد بن محمد بن سليمان الحنفي ذو الهدمين قال حدثني أبي قال دخل يزيد بن مزيد على الرشيد فقال له يا يزيد من الذي يقول فيك\n(لا يعبق الطيب خديه ومفرقه ... ولا يمسح عينيه من الكحل)\n(قد عود الطير عادات وثقن بها ... فهن يتبعنه في كل مرتحل)\nقال لا أعرف قائله يا أمير المؤمنين فقال له هارون أيقال فيك مثل هذا الشعر ولا تعرف قائله فخرج من عنده خجلا فلما صار إلى منزله دعا حاجبه فقال له من بالباب من الشعراء قال مسلم بن الوليد فقال وكيف حجبته عني فلم تعلمني بمكانه قال أخبرته أنك مضيق وأنه ليس في يديك شيء تعطيه إياه وسألته الإمساك والمقام أياما إلى أن تتسع قال فأنكر ذلك عليه وقال أدخله إلي فأدخله إليه فأنشده قوله\n(أجررت حبل خليع في الصبا غزل ... وشمرت همم العذال في عذلي)\n(رد البكاء على العين الطموح هوى ... مفرق بين توديع ومرتحل)\n(أما كفى البين أن أرمى بأسهمه ... حتى رماني بلحظ الأعين النجل)\n(مما جنت لي وإن كانت منى صدقت ... صبابة خلس التسلبم بالمقل)\nقال له قد أمرنا لك بخمسين ألف درهم فاقبضها واعذر فخرج\nالحاجب فقال لمسلم قد أمرني أن أرهن ضيعة من ضياعه على مائة ألف درهم خمسون ألفا لك خمسون ألفا لنفقته وأعطاه إياها وكتب صاحب الخبر بذلك إلى الرشيد فأمر ليزيد بمائتي ألف درهم وقال أقض الخمسين الألف التي أخذها الشاعر وزده مثلها وخذ مائة ألف لنفقتك فافتك ضيعته وأعطى مسلما خمسين ألفا أخرى أخبرني الحسن بن علي الخفاف قال حدثنا محمد بن القاسم بن مهرويه قال حدثني علي بن عبيد الكوفي وعلي بن الحسن كلاهما قال أخبرني علي بن عمرو قال حدثني مسلم بن الوليد المعروف بصريع الغوائي قال كنت يوما جالسا في دكان خياط بإزاء منزلي إذ رأيت طارقا ببابي فقمت إليه فإذا هو صديق لي من أهل الكوفة قد قدم من قم فسررت به وكأن إنسانا لطم وجهي لأنه لم يكن عندي درهم واحد أنفقه عليه فقمت فسلمت عليه وأدخلته منزلي وأخذت خفين كانا لي أتجمل بهما فدفعتهما إلي جاريتي وكتبت معهما رقعة إلى بعض معارفي في السوق أسأله أن يبيع الخفين ويشتري لي لحما وخبزا بشيء سميته فمضت الجارية وعادت إلي وقد اشترى لها ما قد حددته له وقد باع الخفين بتسعة دراهم فكأنها إنما جاءت بخفين جديدين فقعدت أنا وضيفي نطبخ وسألت جارا لي أن يسقينا قارورة نبيذ فوجه بها إلي وأمرت الجارية بأن تغلق باب الدار مخافة طارق يجيء فيشركنا فيما نحن فيه ليبقى لي وله ما نأكله إلى أن ينصرف فإنا لجالسان نطبخ حتى طرق الباب طارق فقلت لجاريتي انظري من هذا فنظرت من شق الباب فإذا رجل عليه سواد وشاشية ومنطقة ومعه شاكري فخبرتني بموضعه فأنركت أمره ثم رجعت إلى نفسي فقلت لست بصاحب دعارة ولا للسلطان على سبيل ففتحت الباب وخرجت إليه فنزل عن دابته وقال أأنت مسلم بن الوليد قلت نعم فقال كيف لي بمعرفتك قلت الذي دلك على منزلي يصحح لك معرفتي فقال لغلامه\nامض إلى الخياط فسله عنه فمضى فسأله عني فقال نعم هو مسلم بن الوليد فأخرج إلي كتابا من خفه وقال هذا كتاب الأمير يزيد بن مزيد إلي يأمرني ألا أفضه إلا عند لقائك فإذا فيه أذا لقيت مسلم بن الوليد فادفع إليه هذه العشرة آلاف درهم التي أنفذتها تكون له في منزله وادفع ثلاثة آلاف درهم نفقة ليتحمل بها إلينا فأخذت الثلاثة والعشرة ودخلت إلى منزلي والرجل معي فأكلنا ذلك الطعام وازددت فيه وفي الشراب واشتريت فاكهة واتسعت ووهبت لضيفي من الدراهم ما يهدي به هدية لعياله وأخذت في الجهاز ثم ما زلت معه حتى صرنا إلى الرقة إلى باب يزيد فدخل الرجل وإذا هو أحد حجابه فوجده في الحمام فخرج إلي فجلس معي قليلا ثم خبر الحاجب بأنه قد خرج من الحمام فأدخلني إليه وإذا هو على كرسي جالس وعلى رأسه وصيفة بيدها غلاف مرآة وبيده هو مرآة ومشط يسرح لحيته فقال لي يا مسلم ما الذي بطأ بك عنا فقلت أيها الأمير قلة ذات اليد قال فأنشدني فأنشدته قصيدتي التي مدحته فيها\n(أجررت حبل خليع في الصبا غزل ... وشمرت همم العذال في عذلي)\nلما صرت إلى قولي لا يعبق الطيب خديه ومفرقه ... ولا يمسح عينيه من الكحل","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":2,"spl":"يزيد بن مزيد يأمر له بجائزة"},
{"id":"b248-5","bab":"الجزء 19","sec":"يزيد بن مزيد يأمر له بجائزة","page":"ج19 ص41","text":"وضع المرآة في غلافها وقال للجارية انصرفي فقد حرم علينا مسلم الطيب فلما فرغت من القصيدة قال لي يا مسلم أتدري ما الذي حداني إلى أن وجهت إليك فقلت لا والله ما أدري قال كنت عند الرشيد منذ ليال أغمز رجليه إذ قال لي يا يزيد من القائل فيك\n(سل الخليفة سيفا من بني مطر ... يمضي فيخترم الأجساد والهاما)\n(كالدهر لا ينثني عما يهم به ... قد أوسع الناس إنعاما وإرغاما)\nقلت لا والله ما أدري فقال لي الرشيد يا سبحان الله أنت مقيم على أعرابيتك يقال فيك مثل هذا الشعر ولا تدري من قائله فسألت عن قائله فأخبرت أنك أنت هو فقم حتى أدخلك على أمير المؤمنين","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":3,"spl":"يزيد بن مزيد يأمر له بجائزة"},
{"id":"b248-6","bab":"الجزء 19","sec":"الرشيد يجيزه ويحذره","page":"ج19 ص44","text":"ثم قام فدخل على الرشيد فما علمت حتى خرج علي الإذن فأذن فدخلت على الرشيد فأنشدته ما لي فيه من الشعر فأمر لي بمائتي ألف درهم فلما انصرفت إلى يزيد أمر لي بمائة وتسعين ألفا وقال لا يجوز لي أن أعطيك مثل ما أعطاك أمير المؤمنين وأقطعني إقطاعات تبلغ غلتها مائتي ألف درهم قال مسلم ثم أفضت بي الأمور بعد ذلك إلى أن أغضبني فهجوته فشكاني إلى الرشيد فدعاني وقال أتبيعني عرض يزيد فقلت نعم يا أمير المؤمنين فقال لي بكم فقلت برغيف خبز فغضب حتى خفته على نفسي وقال قد كنت علي أن أشتريه منك بمال جسيم ولست أفعل ولا كرامة فقد علمت إحسانه إليك وأنا نفي من أبي ووالله ثم والله لئن بلغني أنك هجوته لأنزعن لسانك من بين فكيك فأمسكت عنه بعد ذلك وما ذكرته بخير ولا شر\nأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني محمد بن عبد الله اليعقوبي قال حدثني البيدق الراوية وكان من أهل نصيبين قال دخلت دار يزيد بن مزيد يوما وفيها الخلق وإذا فتى شاب جالس في أفناء الناس ولم يكن يزيد عرفه بعد وإذا هو مسلم بن الوليد فقال لي ما في نفسي أن أقول شعرا أبدا فقلت ولم قال لأني قد مدحت هذا الرجل بشعر ما مدح بمثله قط ولست أجد من يوصله فقلت له أنشدني بعضه فأنشدني منه\n(موف على مهج في يوم ذي رهج ... كأنه أجل يسعى إلى أمل)\n(يقري السيوف نفوس الناكثين به ... ويجعل الروس تيجان القنا الذبل)\n(لا يعبق الطيب خديه ومفرقه ... ولا يمسح عينيه من الكحل)\n(إذا انتضى سيفه كانت مسالكه ... مسالك الموت في الأجسام والقلل)\n(وإن خلت بحديث النفس فكرته ... عاش الرجاء ومات الخوف من وجل)\n(كالليث إن هجته فالموت راحته ... لا يستريح إلى الأيام والدول)\n(لله من هاشم في أرضه جبل ... وأنت وابنك ركنا ذلك الجبل)\n(صدقت ظني وصدقت الظنون به ... وحط جودك عقد الرحل عن جملي)\nال فأخذت منها بيتين ثم قلت له أنشدني أيضا ما لك فيه فأنشدني قصيدة أخرى ابتداؤها\n(طيف الخيال حمدنا منك إلماما ... داويت سقما وقد هيجت أسقاما)\nقول فيها\n(كالدهر لا ينثني عما يهم به ... قد أوسع الناس إنعاما وإرغاما)\nقال فأنشدت هذه الأبيات يزيد بن مزيد فأمر له بخمسمائة درهم ثم ذكرته بالرقة فقلت له هذا الشاعر الذي قد مدحك فأحسن يقتصر به على خمسمائة درهم فبعث إليه بخمسمائة درهم أخرى قال فقال لي مسلم جاءتني وقد رهنت طيلساني على رؤوس الإخوان فوقعت مني أحسن موقع أخبرني محمد بن عمران قال حدثنا العنزي عن محمد بن بدر العجلي عن إبراهيم بن سالم عن أبي فرعون مولى يزيد بن مزيد قال ركب يزيد يوما إلى الرشيد فتغلف بغالية ثم لم يلبث أن عاد فدعا بطست فغسل الغالية وقال كرهت أن أكذب قول مسلم بن الوليد\n(لا يعبق الطيب خديه ومفرقه ... ولا يمسح عينيه من الكحل)\nخبرني جعفر بن قدامة قال حدثني عبد الله بن أبي سعد قال حدثني أبو توبة قال كان مسلم بن الوليد جالسا بين يدي يزيد بن مزيد فأتاه كتاب فيه مهم له فقرأه سرا ووضعه ثم أعاد قراءته ووضعه ثم أراد القيام فقال له مسلم بن الوليد\n(الحزم تحريقه إن كنت ذا حذر ... وإنما الحزم سوء الظن بالناس)\n(لقد أتاك وقد أدى أمانته ... فاجعل صيانته في بطن أرماس)\nقال فضحك يزيد وقال صدقت لعمري وخرق الكتاب وأمر بإحراقه\nحدثني عمي وجحظة قالا حدثنا علي بن الحسين بن عبد الأعلى قال حدثني أبو محلم وحدثني عمي قال حدثني عبد الله بن أبي سعد قال حدثني أبو توبة قال كان مسلم بن الوليد صديقا ليزيد بن مزيد ومداحا له فلما مات انقطع إلى ابنه محمد بن يزيد ومدحه كما مدح أباه فلم يصنع له خيرا ولم يرضه ما فعله به فهجره وانقطع عنه فكتب إليه يستحفيه ويلومه على انقطاعه عنه ويذكره حقوق أبيه عليه فكتب إليه مسلم\n(لبست عزاء عن لقاء محمد ... وأعرضت عنه منصفا وودودا)\n(وقلت لنفس قادها الشوق نحوه ... فعوضها حب اللقاء صدودا)\n(هبيه امرأ قد كان أصفاك وده ... فمات وإلا فاحسبيه يزيدا)\nعمري لقد ولى فلم ألق بعده ... وفاء لذي عهد يعد حميدا","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":4,"spl":"الرشيد يجيزه ويحذره"},
{"id":"b248-7","bab":"الجزء 19","sec":"رثاؤه يزيد بن مزيد","page":"ج19 ص47","text":"أخبرني محمد بن القاسم الأنباري قال حدثني أبي قال حدثني أحمد ابن محمد بن أبي سعد قال أهديت إلى يزيد بن مزيد جارية وهو يأكل فلما رفع الطعام من بين يديه وطئها فلم ينزل عنها إلا ميتا وهو ببرذعة فدفن في مقابر برذعة\nوكان مسلم معه في صحابته فقال يرثيه\n(قبر ببرذعة استسر ضريحه ... خطرا تقاصر دونه الأخطار)\n(أبقى الزمان على ربيعة بعده ... حزنا كعمر الدهر ليس يعار)\n(سلكت بك العرب السبيل إلى العلا ... حتى إذا بلغوا المدى بك حاروا)\nيروى\n(حتى إذا سبق الردى بك حاروا ... )\nكذا أنشده الأخفش\n(نفضت بك الأحلاس نفض إقامة ... واسترجعت روادها الأمصار)\n(فاذهب كما ذهبت غوادي مزنة ... أثنى عليها السهل والأوعار)\nسخت من كتاب جدي يحي بن محمد بن ثوابة حدثني الحسن بن سعيد عن أبيه قال كان داود بن يزيد بن حاتم المهلبي يجلس للشعراء في السنة مجلسا واحدا فيقصدونه لذلك اليوم وينشدونه فوجه إليه بن الوليد روايته بشعره الذي يقول فيه\n(جعلته حيث ترتاب الرياح به ... وتحسد الطير فيه أضبع البيد)\nفقدم عليه يوم جلوسه للشعراء ولحقه بعقب خروجهم عنه فتقدم إلى\nالحاجب وحسر لثامه عن وجهه ثم قال له استأذن لي على الأمير قال ومن أنت قال شاعر قال قد انصرم وقتك وانصرف الشعراء وهو على القيام فقال له ويحك قد وفدت على الأمير بشعر ما قالت العرب مثله قال وكان مع الحاجب أدب يفهم به ما يسمع فقال هات حتى أسمع فإن كان الأمر كما ذكرت أوصلتك إليه فأنشده بعض القصيدة فسمع شيئا يقصر الوصف عنه فدخل على داود فقال له قد قدم على الأمير شاعر بشعر ما قيل فيه مثله فقال أدخل قائلة فأدخله فلما مثل بين يديه سلم وقال قدمت على الأمير أعزه الله بمدح يسمعه فيعلم به تقدمي على غيري ممن امتدحه فقال هات فلما افتتح القصيدة وقال\n(لا تدع بي الشوق إني غير معمود ... نهى النهى عن هوى البيض الرعاديد)\nستوى جالسا وأطرق حتى أتى الرجل على آخر الشعر ثم رفع رأسه إليه ثم قال أهذا شعرك قال نعم أعز الله الأمير قال في كم قلته يا فتى قال في أربعة أشهر أبقاك الله قال لو قلته في ثمانية أشهر لكنت محسنا وقد اتهمتك لجودة شعرك وخمول ذكرك فإن كنت قائل هذا الشعر فقد أنظرتك أربعة أشهر في مثله وأمرت بالإجراء عليك فإن جئتنا بمثل هذا الشعر وهبت لك مائة ألف درهم وإلا حرمتك فقال أو الإقالة أعز الله الأمير قال أقلتك قال الشعر لمسلم بن الوليد وانا راويته الوافد عليك بشعره فقال أنا ابن حاتم إنك لما افتتحت شعره فقلت\n(لا تدع بي الشوق إني غير معمود ... )\nسمع كلام مسلم يناديني فأجبت نداءه واستويت جالسا ثم قال يا غلام أعطه عشرة آلاف درهم واحمل الساعة إلى مسلم مائة ألف درهم أخبرني الحسين بن القاسم الكوكبي قال حدثنا عبد الله بن أبي سعد قال حدثني مسعود بن عيسى العبدي قال أخبرني موسى بن عبد الله التميمي قال","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":5,"spl":"رثاؤه يزيد بن مزيد","partial":1},
{"id":"b248-8","bab":"الجزء 19","sec":"الفضل بن سهل يوليه جرجان","page":"ج19 ص50","text":"دخل مسلم بن الوليد الأنصاري على الفضل بن سهل لينشده شعرا فقال له أيها الكهل إني أجلك عن الشعر فسل حاجتك قال بلى تستتم اليد عندي بأن تسمع فأنشده\n(دموعها من حذار البين تنسكب ... وقلبها مغرم من حرها يجب)\n(جد الرحيل به عنها ففارقها ... لبينه اللهو واللذات والطرب)\n(يهوى المسير إلى مرو ويحزنه ... فراقها فهو ذو نفسين يرتقب)\nقال له الفضل إني لأجلك عن الشعر قال فأغني بما أحببت من عملك فولاه البريد بجرجان أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني الحسين بن أبي السري وأخبرني بهذه الأخبار محمد بن خلف بن المرزبان قال حدثني إبراهيم بن محمد الوراق عن الحسين بن أبي السري قال قيل لمسلم بن الوليد أي شعرك أحب إليك قال إن في شعري لبيتا أخذت معناه من التوراة وهو قولي\n(دلت على عيبها الدنيا وصدقها ... ما استرجع الدهر مما كان أعطاني)\nال الحسين وحدثني جماعة من أهل جرجان أن راوية مسلم جاء إليه بعد أن تاب ليعرض عليه شعره فتغافله مسلم ثم أخذ منه الدفتر الذي في يده فقذف به البحر فلهذا قل شعره فليس في أيدي الناس منه إلا ما كان بالعراق وما كان في أيدي الممدوحين من مدائحهم قال الحسين وحدثني الحسين بن دعبل قال قال أبي لمسلم ما معنى قولك\n(لا تدع بي الشوق إني غير معمود ... )\nقال لا تدعني صريع الغواني فلست كذلك وكان يلقب هذا اللقب وكان له كارها أخبرني محمد بن خلف بن المرزبان قال حدثنا حماد بن إسحاق عن أبيه قال عتب عيسى بن داود على مسلم بن الوليد فهجره وكان إليه محسنا فكتب إليه مسلم\n(شكرتك للنعمى فلما رميتني ... بصدك تأديبا شكرتك في الهجر)\n(فعندي للتأديب شكر وللندى ... وإن شئت كان العفو أدعى إلى الشكر)\n(إذا ما اتقاك المستليم بعذره ... فعفوك خير من ملام على عذر)\nال فرضي عنه وعاد إلى حاله","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":6,"spl":"الفضل بن سهل يوليه جرجان","partialRef":{"sid":"b248-7","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b248-9","bab":"الجزء 19","sec":"دعبل يقول كان مسلم من أبخل الناس","page":"ج19 ص51","text":"أخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني محمد بن الأشعث قال حدثني دعبل بن علي قال كان مسلم بن الوليد من أبخل الناس فرأيته يوما وقد استقبل الرضا عن غلام بعد موجدة فقال له قد رضيت عنك وأمرت لك بدرهم\nأخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني محمد بن عمرو بن سعيد قال خرج دعبل إلى خراسان لما بلغه خطوة مسلم بن الوليد عند الفضل بن سهل فصار إلى مرو وكتب إلى الفضل بن سهل\n(لا تعبأن بابن الوليد فإنه ... يرميك بعد ثلاثة بملال)\n(إن الملول وإن تقادم عهده ... كانت مودته كفيء ظلال)\nال فدفع الفضل إلى مسلم الرقعة وقال له انظر يا أبا الوليد إلى رقعة دعبل فيك فلما قرأها قال له هل عرفت لقب دعبل وهو غلام أمرد وهو يفسق به قال لا قال كان يلقب بمياس ثم كتب إليه\n(مياس قل لي أين أنت من الورى ... لا أنت معلوم ولا مجهول)\n(أما الهجاء فدق عرضك دونه ... والمدح عنك كما علمت جليل)\n(فاذهب فأنت طليق عرضك إنه ... عرض عززت به وأنت ذليل)\nخبرني محمد بن الحسين الكندي الكوفي مؤدبي قال حدثني أزهر بن محمد قال حدثني الحسين بن دعبل قال سمعت أبي يقول بينا أنا جالس بباب الكرخ إذ مرت بي جارية لم أر أحسن منها وجها ولا قدا تتثنى في مشيها وتنظر في أعطافها فقلت متعرضا لها\n(دموع عييني بها انبساط ... ونوم عيني به انقباض)\nأجابتني بسرعة فقالت\n(وذا قليل لمن دهته ... بلحظها الأعين المراض)\nفأدهشتني وعجبت منها فقلت\n(فهل لمولاي عطف قلب ... وللذي في الحشا انقراض)\nأجابتني غير متوقفة فقالت\n(إن كنت تهوى الوداد منا ... فالود في ديننا قراض)\nال فما دخل أذني كلام قط أحلى من كلامها ولا رأيت أنضر وجها منها فعدلت بها عن ذلك الشعر وقلت\n(أترى الزمان يسرنا بتلاق ... ويضم مشتاقا إلى مشتاق)\nأجابتني بسرعة فقالت\n(ما للزمان وللتحكم بيننا ... أنت الزمان فسرنا بتلاق)\nقال فمضيت أمامها أؤم بها دار مسلم بن الوليد وهي تتبعني فصرت إلى منزله فصادفته على عسرة فدفع إلي منديلا وقال اذهب فبعه وخذ لنا ما نحتاج إليه وعد فمضيت مسرعا فلما رجعت وجدت مسلما قد خلا بها في سرداب فلما أحس بي وثب إلي وقال عرفك الله يا أبا علي جميل ما فعلت ولقاك ثوابه وجعله أحسن حسنة لك فغاظني قوله وطنزه وجعلت أفكر أي شيء أعمل به فقال بحياتي يا أبا علي أخبرني من الذي يقول\n(بت في درعها وبات رفيقي ... جنب القلب طاهر الأطراف)\nقلت\n(من له في حر أمه ألف قرن ... قد أنافت على علو مناف)\nوجعلت أشتمه وأثب عليه فقال لي يا أحمق منزلي دخلت ومنديلي بعت ودراهمي أنفقت على من تحرد أنت وأي شيء سبب حردك يا قواد فقلت له مهما كذبت علي فيه من شيء فما كذبت في الحمق والقيادة","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":7,"spl":"دعبل يقول كان مسلم من أبخل الناس"},
{"id":"b248-10","bab":"الجزء 19","sec":"نماذج من هجائه","page":"ج19 ص54","text":"أخبرني الحسن بن علي قال حدثني ابن مهرويه والعنزي عن محمد ابن عبد الله العبدي قال هجا مسلم بن الوليد سعيد بن سلم ويزيد بن مزيد وخزيمة بن خازم فقال\n(ديونك لا يقضى الزمان غريمها ... وبخلك بخل الباهلي سعيد)\n(سعيد بن سلم أبخل الناس كلهم ... وما قومه من بخله ببعيد)\n(يزيد له فضل ولكن مزيدا ... تدارك فينا بخله بيزيد)\n(خزيمة لا عيب له غير أنه ... لمطبخه قفل وباب حديد)\nخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل تينة قال حدثنا الأصمعي قال قال لي سعيد بن سلم قدمت علي امرأة من باهلة من اليمامة فمدحتني\nبأبيات ما تم سروري بها حتى نغصنيها مسلم بن الوليد بهجاء بلغني أنه هجاني به فقلت ما الأبيات التي مدحت بها فأنشدني\n(قتيبة قيس ساد قيسا وسلمها ... فلما تولى ساد قيسا سعيدها)\n(وسيد قيس سيد الناس كلهم ... وإن مات من رغم وذل حسودها)\n(هم رفعوا كفيك بالمجد والعلا ... ومن يرفع الأبناء إلا جدودها)\n(إذا مد للعليا سعيد يمينه ... ثنت كفه عنها أكفا تريدها)\nال الأصمعي فقلت له فبأي شيء نغصها عليك مسلم فضحك وقال كلفتني شططا ثم أنشد\n(وأحببت من حبها الباخلين ... حتى ومقت ابن سلم سعيدا)\n(إذا سيل عرفا كسا وجهه ... ثيابا من النقع صفرا وسودا)\n(يغار على المال فعل الجواد ... وتأبى خلائقه أن يجودا)\nخبرني عمي قال حدثنا الكراني قال حدثني النوشجاني الخليل بن أسد قال حدثني علي بن عمرو قال وقف بعض الكتاب على مسلم بن الوليد وهو ينشد شعرا في محفل فأطال ثم انصرف وقال لرجل كان معه ما أدري أي شيء أعجب الخليفة والخاصة من شعر هذا فوالله ما سمعت منه طائلا فقال مسلم ردوا علي الرجل فرد إليه فأقبل عليه ثم قال\n(أمأ الهجاء فدق عرضك دونه ... والمدح عنك كما علمت جليل)\n(فاذهب فأنت طليق عرضك إنه ... عرض عززت به وأنت ذليل)","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":8,"spl":"نماذج من هجائه"},
{"id":"b248-11","bab":"الجزء 19","sec":"دعبل يأخذ عن مسلم ويستقي من بحره","page":"ج19 ص56","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني إبراهيم بن محمد الوراق قال حدثني الحسين بن أبي السري قال كان مسلم بن الوليد أستاذ دعبل وعنه أخذ ومن بحره استقى وحدثني دعبل أنه كان لا يزال يقول الشعر فيعرضه على مسلم فيقول له إياك أن يكون أول ما يظهر لك ساقطا فتعرف به ثم لو قلت كل شيء جيدا كان الأول أشهر عنك وكنت أبدا لا تزال تعير به حتى قلت\n(أين الشباب وأية سلكا ... )\nلما سمع هذه قال لي أظهر الآن شعرك كيف شئت قال الحسين وحدثني أبو تمام الطائي قال ما زال دعبل متعصبا لمسلم مائلا إليه معترفا بأستاذيته حتى ورد عليه جرجان فجفاه مسلم وهجره دعبل فكتب إليه\n(أبا مخلد كنا عقيدي مودة ... هوانا وقلبانا جميعا معا معا)\n(أحوطك بالغيب الذي أنت حائطي ... وأجزع إشفاقا بأن تتوجعا)\n(فصيرتني بعد انتكاثك متهما ... لنفسي عليها أرهب الخلق أجمعا)\n(غششت الهوى حتى تداعت أصوله ... بنا وابتذلت الوصل حتى تقطعا)\n(وأنزلت من بين الجوانح والحشا ... ذخيرة ود طال ما قد تمنعا)\n(فلا تلحيني ليس فيك مطمع ... تخرقت حتى لم أجد لك مرقعا)\n(فهبك يميني استأكلت فقطعتها ... وجشمت قلبي صبره فتشجعا)\nال ثم تهاجرا بعد ذلك فما التقيا حتى ماتا أخبرني عمي قال حدثنا أحمد بن أبي طاهر قال أخبرني أحمد بن أبي\nأمية قال لقي أخي محمد بن أمية مسلم بن الوليد وهو يتثنى ورواته مع بعض أصحابه فسلم عليه ثم قال له قد حضرني شيء فقال هاته قال على أنه مزاح ولا تغضب قال هاته ولو كان شتما فأنشدته\n(من رأى فيما خلارجلا ... تيهه أربى على جدته)\n(يتمشى راجلا وله ... شاكري في قلنسيته)\nسكت عنه مسلم ولم يجبه وضحك ابن أبي أمية وافترقا قال وكان لمحمد برذون يركبه فنفق فلقيه مسلم وهو راجل فقال ما فعل برذونك قال نفق قال فنجازيك إذا على ما أسلفتناه ثم أنشده\n(قل لابن مي لا تكن جازعا ... لن يرجع البرذون بالليت)\n(طامن أحشاءك فقدانه ... وكنت فيه عالي الصوت)\n(وكنت لا تنزل عن ظهره ... ولو من الحش إلى البيت)\n(ما مات من سقم ولكنه ... مات من الشوق إلى الموت)\nخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني أحمد بن سعيد الحريري أن أبا تمام حلف ألا يصلي حتى يحفظ شعر مسلم وأبي نواس فمكث شهرين كذلك حتى حفظ شعرهما قال ودخلت عليه فرأيت شعرهما بين يديه فقلت له ما هذا فقال اللات والعزى وأنا أعبدهما من دون الله أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني سمعان بن عبد الصمد قال حدثني دعبل بن علي قال كان أبو نواس يسألني أن أجمع بينه وبين مسلم بن الوليد وكان مسلم\nيسألني أن أجمع بينه وبين أبي نواس وكان أبو نواس إذا حضر تخلف مسلم وإذا حضر مسلم تخلف أبو نواس إلى أن اجتمعا فأنشده أبو نواس\n(أجارة بيتينا أبوك غيور ... وميسور ما يرجى لديك عسير)\nأنشده مسلم\n(لله من هاشم في أرضه جبل ... وأنت وابنك ركنا ذلك الجبل)\nقلت لأبي نواس كيف رأيت مسلما فقال هو أشعر الناس بعدي وسألت مسلما وقلت كيف رأيت أبا نواس فقال هو أشعر الناس وأنا بعده أخبرني الحسن قال حدثنا ابن مهرويه قال حدثني إبراهيم بن عبد الخالق الأنصاري من ولد النعمان بن بشير قال حدثني مسلم بن الوليد قال وجه إلي ذو الرياستين فحملت إليه فقال أنشدني قولك\n(بالغمر من زينب أطلال ... مرت بها بعدك أحوال)\nأنشدته إياها حتى انتهيت إلى قولي\n(وقائل ليست له همة ... كلا ولكن ليس لي مال)\n(وهمة المقتر أمنية ... هم مع الدهر وأشغال)\n(لا جدة أنهض عزمي بها ... والناس سؤال وبخال)\n(فاقعد مع الدهر إلى دولة ... ترفع فيها حالك الحال)\nال فلما أنشدته هذا البيت قال هذه والله الدولة التي ترفع حالك وأمر لي بمال عظيم وقلدني أوقال قبلني جوز جرجان","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":9,"spl":"دعبل يأخذ عن مسلم ويستقي من بحره","partialRef":{"sid":"b194-2","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b248-12","bab":"الجزء 19","sec":"الرشيد يهدده بسبب الهجاء","page":"ج19 ص59","text":"حدثني جحظة قال حدثني ميمون ين هارون قال كان مسلم بن الوليد قد انحرف عن معن بن زائدة بعد مدحه إياه لشيء أوحشه منه فسأله يزيد بن مزيد أن يهبه له فوعده ولم يفعل فتركه يزيد خوفا منه فهجاه هجاء كثيرا حتى حلف له الرشيد إن عاود هجاءه قطع لسانه فمن ذلك قوله فيه\n(يا معن إنك لم تزل في خزية ... حتى لففت أباك في الأكفان)\n(فاشكر بلاء الموت عندك إنه ... أودى بلؤم الحي من شيبان)\nال وهجا أيضا يزيد بن مزيد بعد مدحه إياه فقال\n(أيزيد يا مغرور ألأم من مشى ... ترجو الفلاح وأنت نطفة مزيد)\n(إن كنت تنكر منطقي فاصرخ به ... يوم العروبة عند باب المسجد)\n(في من يزيد فإن أصبت بمزيد ... فلسا فهاك على مخاطرة يدي)\nكذا روى جحظة في هذا الخبر والشعران جميعا في يزيد بن مزيد فالأول منهما أوله\n(أيزيد إنك لم تزل في خزية ... )\nهكذا هو في شعر مسلم ولم يلق مسلم معن بن زائدة ولا له فيه مدح ولا هجاء أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثنا محمد بن عبد الله بن جشم قال كان يزيد بن مزيد قد سأل مسلم بن الوليد عما يكفيه ويكفي عياله فأخبره فجعله جراية له ثم قال ليس هذا مما تحاسب به بدلا من جائزة أو ثواب مديح فكان يبعث به إليه في كل سنة فلما مات يزيد رثاه مسلم فقال\n(أحقا أنه أودى يزيد ... تبين أيها الناعي المشيد)\n(أتدري من نعيت وكيف دارت ... به شفتاك دار بها الصعيد)\n(أحامي المجد والإسلام أودى ... فما للأرض ويحك لا تميد)\n(تأمل هل ترى الإسلام مالت ... دعائمه وهل شاب الوليد)\n(وهل شيمت سيوف بني نزار ... وهل وضعت عن الخيل اللبود)\n(وهل تسقي البلاد عشار مزن ... بدرتها وهل يخضر عود)\n(أما هدت لمصرعه نزار ... بلى وتقوض المجد المشيد)\n(وحل ضريحه إذ حل فيه ... طريف المجد والحسب التليد)\n(أما والله ما تنفك عيني ... عليك بدمعها أبدا تجود)\n(وإن تجمد دموع لئيم قوم ... فليس لدمع ذي حسب جمود)\n(أبعد يزيد تختزن البواكي ... دموعا أو تصان لها خدود)\n(لتبكك قبة الإسلام لما ... وهت أطنابها ووهى العمود)\n(ويبكك شاعر لم يبق دهر ... له نشبا وقد كسد القصيد)\n(فإن يهلك يزيد فكل حي ... فريس للمنية أو طريد)\nكذا في الخبر والقصيدة للتيمي","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":10,"spl":"الرشيد يهدده بسبب الهجاء","partial":1},
{"id":"b248-13","bab":"الجزء 19","sec":"يمدح الفضل بن سهل ثم يرثيه","page":"ج19 ص61","text":"أخبرني محمد بن يحي الصولي قال حدثنا الهشامي قال حدثني\nعبد الله بن عمرو قال حدثني موسى بن عبد الله التميمي قال دخل مسلم بن الوليد على الفضل بن سهل فأنشده قوله فيه\n(لو نطق الناس أو أنبوا بعلمهم ... ونبهت عن معالي دهرك الكتب)\n(لم يبلغوا منك أدنى ما تمت به ... إذا تفاخرت الأملاك وانتسبوا)\nأمر له عن كل بيت من هذه القصيدة بألف درهم ثم قتل الفضل فقال يرثيه\n(ذهلت فلم أنقع غليلا بعبرة ... وأكبرت أن ألقى بيومك ناعيا)\n(فلما بدا لي أنه لاعج الأسى ... وأن ليس إلا الدمع للحزن شافيا)\n(أقمت لك الأنواح ترتد بينها ... مآتم تندبن الندى والمعاليا)\n(وما كان منعى الفضل منعاة واحد ... ولكن منعى الفضل كان مناعيا)\n(أللبأس أم للجود أم لمقاوم ... من الملك يزحمن الجبال الرواسيا)\n(عفت بعدك الأيام لا بل تبدلت ... وكن كأعياد فعدن مباكيا)\n(فلم أر إلا قبل يومك ضاحكا ... ولم أر إلا بعد يومك باكيا)\nخبرني الحسين بن القاسم الكوكبي قال حدثنا محمد بن عجلان قال حدثنا يعقوب بن السكيت قال أخبرني محمد بن المهنأ قال كان العباس بن الأحنف مع إخوان له على شراب فذكروا مسلم بن\nالوليد فقال بعضهم صريع الغواني فقال العباس ذاك ينبغي أن يسمى صريع الغيلان لا صريع الغواني وبلغ ذلك مسلما فقال يهجوه\n(بنو حنيفة لا يرضى الدعي بهم ... فاترك حنيفة واطلب غيرها نسبا)\n(فاذهب فأنت طليق الحلم مرتهن ... بسورة الجهل ما لم أملك الغضبا)\n(اذهب إلى عرب ترضى بنسبتهم ... إني أرى لك خلقا يشبه العربا)\n(منيت مني وقد جد الجراء بنا ... بغاية منعتك الفوت والطلبا)\nخبرني محمد بن يزيد قال حدثنا حماد بن إسحاق عن أبيه عن جده قال قلت لمسلم بن الوليد ويحك أما استحييت من الناس حين تهجو خزيمة بن خازم ولا استحييت منا ونحن إخوانك وقد علمت أنا نتولاه وهو من تعرف فضلا وجودا فضحك وقال لي يا أبا إسحاق لغيرك الجهل أما تعلم أن الهجاء آخذ بضبع الشاعر وأجدي عليه من المديح المضرع وما ظلمت مع ذلك منهم أحدا وما مضى فلا سبيل إلى رده ولكن قد وهبت لك عرض خزيمة بعد هذا قال ثم أنشدني قوله في سعيد بن سلم\n(ديونك لا يقضى الزمان غريمها ... وبخلك بخل الباهلي سعيد)\n(سعيد بن سلم أبخل الناس كلهم ... وما قومه من بخله ببعيد)\nقلت له وسعيد بن سلم صديقي أيضا فهبه لي فقال إن أقبلت على ما يعنيك وإلا رجعت فيما وهبت لك من خزيمة فأمسكت عنه راضيا بالكفاف","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":11,"spl":"يمدح الفضل بن سهل ثم يرثيه"},
{"id":"b248-14","bab":"الجزء 19","sec":"يمدح محمد بن يزيد بن مزيد ثم الفضل بن يحيى","page":"ج19 ص64","text":"أخبرني جبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني عبد الله بن محمد بن موسى بن عمر بن حمزة بن بزيع قال حدثني عبد الله بن الحسن اللهبي قال كان مسلم بن الوليد مداحا ليزيد بن مزيد وكان يؤثره ويقدمه ويجزل صلته فلما مات وفد على ابنه محمد فمدحه وعزاه عن أبيه وأقام ببابه أياما فلم ير منه ما يحب فانصرف عنه وقال فيه\n(لبست عزاء عن لقاء محمد ... وأعرضت عنه منصفا وودودا)\n(وقلت لنفس قادها الشوق نحوه ... فعوضها منه اللقاء صدودا)\n(هبيبه امرأ قد كان أصفاك وده ... ومات وإلا فاحسبيه يزيدا)\n(لعمري لقد ولى فلم ألق بعده ... وفاء لذي عهد يعد حميدا)\nخبرني حبيب بن نصر قال حدثنا عبد الله بن أبي سعد قال حدثني أحمد بن إبراهيم بن إسماعيل بن داود قال دخل مسلم بن الوليد يوما على الفضل بن يحيى وقد كان أتاه خبر مسيره فجلس للشعراء فمدحوه وأثابهم ونظر في حوائج الناس فقضاها وتفرق الناس عنه وجلس للشرب ومسلم غير حاضر لذلك وإنما بلغه حين انقضى المجلس فجاءه فأدخل إليه فاستأذن في الإنشاد فأذن له فأنشده وقوله فيه\n(أتتك المطايا تهتدي بمطية ... عليها فتى كالنصل مؤنسه النصل)\nيقول فيها\n(وردت رواق الفضل آمل فضله ... فحط الثناء الجزل نائله الجزل)\n(فتى ترتعي الآمال مزنة جوده ... إذا كان مرعاها الأماني والمطل)\n(تساقط يمناه الندى وشماله الردى ... وعيون القول منطقه الفصل)\n(ألح على الأيام يفري خطوبها ... على منهج ألفى أباه به قبل)\n(أناف به العلياء يحيى وخالد ... فليس له مثل ولا لهما مثل)\n(فروع أصابت مغرسا متمكنا ... وأصلا فطابت حيث وجهها الأصل)\n(بكف أبي العباس يستمطر الغنى ... وتستنزل النعمى ويسترعف النصل)\nال فطرب الفضل طربا شديدا وأمر بأن تعد الأبيات فعدت فكانت ثمانين بيتا فأمر له بثمانين ألف درهم وقال لولا أنها أكثر ما وصل به الشعراء لزدتك ولكنه شأو لا يمكنني أن أتجاوزه يعني أن الرشيد رسمه لمروان ابن أبي حفصة وأمره بالجلوس معه والمقام عنده لمنادمته فأقام عنده وشرب معه وكانت على رأس الفضل وصيفة تسقيه كأنها لؤلؤة فلمح الفضل مسلما ينظر إليها فقال قد وحياتي يا أبا الوليد أعجبتك فقل فيها أبياتا حتى أهبها لك فقال\n(إن كنت تسقين غير الراح فاسقيني ... كأسا ألذ بها من فيك تشفيني)\n(عيناك راحي وريحاني حديثك لي ... ولون خديك لون الورد يكفيني)\n(إذا نهاني عن شرب الطلا حرج ... فخمر عينيك يغنيني ويجزيني)\n(لولا علامات شيب لو أتت وعظت ... لقد صحوت ولكن سوف تأتيني)\n(أرضي الشباب فإن أهلك فعن قدر ... وإن بقيت فإن الشيب يشقيني)\nقال له خذها بورك لك فيها وأمر بتوجيهها مع بعض خدمها إليه","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":12,"spl":"يمدح محمد بن يزيد بن مزيد ثم الفضل بن يحيى"},
{"id":"b248-15","bab":"الجزء 19","sec":"يتنسك بعد موت زوجته","page":"ج19 ص66","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني أحمد بن إبراهيم قال كانت لمسلم بن الوليد زوجة من أهله كانت تكفيه أمره وتسره فيما تليه له منه فماتت فجزع عليها جزعا شديدا وتنسك مدة طويلة وعزم على ملازمة ذلك فأقسم عليه بعض إخوانه ذات يوم أن يزوره ففعل فأكلوا وقدموا الشاب فامتنع منه فسلم وأباه وأنشأ يقول\n(بكاء وكأس كيف يتفقان ... سبيلاهما في القلب مختلفان)\n(دعاني وإفراط البكاء فإنني ... أرى اليوم فيه غير ما تريان)\n(غدت والثرى أولى بها من وليها ... إلى منزل ناء لعينك دان)\n(فلا حزن حتى تذرف العين ماءها ... وتعترف الأحشاء للخفقان)\n(وكيف بدفع اليأس للوجد بعدها ... وسهماهما في القلب يعتلجان)\nخبرني حبيب بن نصر قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الصباح قال حدثني مالك بن إبراهيم قال كان مسلم بن الوليد يهاجي الحكم بن قنبر المازني فغلب عليه ابن قنبر\nمدة وأخرسه ثم أثاب مسلم بعد أن انخزل وأفحم فهتك ابن قنبر حتى كف عن مناقضته فكان يهرب منه فإذا لقيه مسلم قبض عليه وهجاه وأنشده ما قاله فيه فيمسك عن إجابته ثم جاءه ابن قنبر إلى منزله واعتذر إليه مما سلف وتحمل عليه بأهله وسأله الإمساك فوعده بذلك فقال فيه\n(حلم ابن قنبر حين أقصر جهله ... هل كان يحلم شاعر عن شاعر)\n(ما أنت بالحكم الذي سميته ... غالتك حلمك هفوة من قاهر)\n(لو لا اعتذارك لارتمى بك زاخر ... مرح العباب يفوت طرف الناظر)\n(لا ترتعن لحمي لسانك بعدها ... إني أخاف عليك شفرة جازر)\n(واستغنم العفو الذي أوتيته ... لا تأمنن عقوبة من قادر)\nخبرني الحسن بن علي قال حدثنا محمد بن ا لقاسم بن مهرويه قال حدثني محمد بن عبد الله أبو بكر العبدي قال رأيت مسلم بن الوليد وابن قنبر في مسجد الرصافة في يوم جمعة وكل واحد منهما بإزاء صاحبه وكانا يتهاجيان فبدأ مسلم فقال\n(أنا النار في أحجارها مستكنة ... فإن كنت ممن يقدح النار فاقدح)\nأجابه ابن قنبر فقال\n(قد كنت تهوي وما قوسى بموترة ... فكيف ظنك بي والقوس في الوتر)\nال فوثب إليه مسلم وتواخزا وتواثبا وحجز الناس بينهما فتفرقا أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني علي بن عبيد الكوفي قال حدثني علي بن عمروس الأنصاري قال جاء رجل من الأنصار ثم من الخزرج إلى مسلم بن الوليد فقال له ويلك\nما لنا ولك قد فضحتنا وأخزيتنا تعرضت لابن قنبر فهاجيته حتى إذا أمكنته من أعراضنا انخزلت عنه وأرعيته لحومنا فلا أنت سكت ووسعك ما وسع غيرك ولا أنت لما انتصرت انتصفت فقال له مسلم فما أصنع فأنا أصبر عليه فإن كف وإلا تحملت عليه بإخوانه فإن كف وإلا وكلته إلى بغيه ولنا شيخ يصوم الدهر ويقوم الليل فإن أقام على ما هو عليه سألته أن يسهر له ليلة يدعو الله عليه فيها فإنها تهلكه فقال له الأنصاري سخنت عينيك أو بهذا تنتصف ممن هجاك ثم قال له\n(قد لاذ من خوف ابن قنبر مسلم ... بدعاء والده مع الأسحار)\n(ورأيت شر وعيده أن يشتكي ... ما قد عراه إلى أخ أو جار)\n(ثكلتك أمك قد هتكت حريمنا ... وفضحت أسرتنا بني النجار)\n(عممت خزرجنا ومعشر أوسنا ... خزيا جنيت به على الأنصار)\n(فعليك من مولى وناصر أسرة ... وعشيرة غضب الإله الباري)\nال فكاد مسلم أن يموت غما وبكاء وقال له أنت شر علي من ابن قنبر ثم أثاب رحمي فهتك ابن قنبر ومزقه حتى تركه وتحمل عليه بابنه وأهله حتى أعفاه من المهاجاة ونسخت هذا الخبر من كتاب جدي يحي بن محمد بن ثوابة بخطه قال حدثني الحسن بن سعيد قال حدثني منصور بن جمهور قال لما هجا ابن قنبر مسلم بن الوليد أمسك عنه مسلم بعد أن أشلى عليه لسانه قال فجاءه عم له فقال له يا هذا الرجل إنك عند الناس فوق ابن قنبر في عمود الشعر وقد بعث عليك لسانه ثم أمسكت عنه فإما أن قارعته أو سالمته فقال له مسلم إن لنا شيخا وله مسجد يتهجد فيه وله بين ذلك\nدعوات يدعو بهن ونحن نسأله أن يجعله من بعض دعواته فإنا نكفاه فأطرق الرجل ساعة ثم قال\n(غلب ابن قنبر واللئيم مغلب ... لما اتقيت هجاءه بدعاء)\n(ما زال يقذف بالهجاء ولذعه ... حتى اتقوه بدعوة الآباء)","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":13,"spl":"يتنسك بعد موت زوجته"},
{"id":"b248-16","bab":"الجزء 19","sec":"يتنسك بعد موت زوجته","page":"ج19 ص66","text":"ال فقال له مسلم والله ما كان ابن قنبر يبلغ مني هذا كله فأمسك لسانك عني وتعرف خبره بعد هذا قال فأمسك لسانك عني وتعرف خبره بعد هذا قال فبعث والله عليه من لسان مسلم ما أسكته هكذا جاء في الأخبار وقد حدثني بخبر مناقضته ابن قنبر جماعة ذكروا قصائدهما جميعا فوجدت في الشعر الفضل لابن قنبر عليه لأن له عدة قصائد لا نقائض لها يذكر فيها تعريده عن الجواب وقصائد يذكر فيها أن مسلما فخر على قريش وعلى النبي بأشياء تبيح دمه فكف مسلم عن مناقضته خوفا منها وجحد أشياء كان قالها فيه فممن أخبرني بذلك هاشم بن محمد الخزاعي قال حدثني عبد الله بن عمرو بن أبي سعد قال حدثني محمد بن عبد الله بن الوليد مولى الأنصار وكان عالما بشعر مسلم بن الوليد وأخباره قال","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":14,"spl":"يتنسك بعد موت زوجته — سبب المهاجاة بينه وبين ابن قنبر"},
{"id":"b248-17","bab":"الجزء 19","sec":"سبب المهاجاة بينه وبين ابن قنبر","page":"ج19 ص69","text":"كان سبب المهاجاة بين مسلم بن الوليد والحكم بن قنبر أن الطرماح بن\nحكيم قد كان هجا بني تميم بقصيدته التي يقول فيها\n(لا عز نصر امرئ أضحى له فرس ... على تميم يريد النصر من أحد)\n(إذا دعا بشعار الأزد نفرهم ... كما ينفر صوت الليث بالنقد)\n(لو حان ورد تميم ثم قيل لهم ... حوض الرسول عليه الأزد لم ترد)\n(أو أنزل الله وحيا أن يعذبها ... إن لم تعد لقتال الأزد لم تعد)\nهي قصيدة طويلة وكان الفرزدق أجاب الطرماح عنها ثم إن ابن قنبر المازني قال بعد خبر طويل يرد على الطرماح\n(يا عاويا هاج ليثا بالعواء له ... شثن البراثن ورد اللون ذا لبد)\n(أي الموارد هابت جم غمرته ... بنو تميم على حال فلم ترد)\n(ألم ترد يوم قندابيل معلمة ... بالخيل تضبر نحو الأزد كالأسد)\n(بفتية لم تنازعها فتطبعها ... بلؤمها طيئ ثديا ولم تلد)\n(خاضت إلى الأزد بحرا ذا غوارب من ... سمر طوال وبحرا من قنا قصد)\n(فأوردتها مناياها بمرهفة ... ملس المضارب لم تفلل ولم تكد)\nوهي قصيدة طويلة وقد كان الطرماح قال أيضا\n(تميم بطرق اللؤم أهدى من القطا ... ولو سلكت طرق المكارم ضلت)\n(أرى الليل يجلوه النهار ولا أرى ... عظام المخازي عن تميم تجلت)\nقد كان الفرزدق أيضا أجابه عنها فقال ابن قنبر ينقضها\n(لعمرك ما ضلت تميم ولا جرت ... على إثر أشياخ عن المجد ضلت)\n(ولا جبنت بل أقدمت يوم كسرت ... لها الأزد أغماد السيوف وسلت)\n(بغائط قندابيل والموت خائض ... عليها بآجال لها قد أظلت)\n(فما برحت تسقى كؤوس حمامها ... إذا نهلت كروا عليها فعلت)\n(إلى أن أبادتهم تميم وأكذبت ... أماني للشيطان عنها اضمحلت)\n(وحان فراق منهم كل خدلة ... مفارقة بعلا به قد تملت)\nوهي أيضا طويلة قال فبلغ مسلم بن الوليد هجاء ابن قنبر للأزد وطيء ورده على الطرماح بعد موته فغضب من ذلك وقال ما المعنى في مناقضة رجل ميت وإثارة الشر بذكر القبائل لا سيما وقد أجابه الفرزدق عن قوله فأبى ابن قنبر إلا تماديا في مناقضته فقال مسلم قصيدته التي أولها\n(آيات أطلال برامة درس ... هجن الصبابة إذ ذكرت معرسي)\n(أوحت إلى درر الدموع فأسبلت ... واستفهمتها غير أن لم تنبس)\nيقول فيها يصف الخمر\n(صفراء من حلب الكروم كسوتها ... بيضاء من حلب الغيوم البجس)\n(طارت ولاوذها الحباب فحاكها ... فكأن حليتها جني النرجس)\nيقول فيها يصف السيوف\n(وتفارق الأغماد تبدو تارة ... حمرا وتخفى تارة في الأرؤس)\n(حرب يكون وقودها أبناءها ... لقحت على عقر ولما تنفس)\n(من هارب ركب النجاء ومقعص ... جثمت منيته على المتنفس)\n(غصبته أطراف الأسنة نفسه ... فثوى فريسةولغ أو نهس)\n(إن كنت نازلة اليفاع فنكبي ... دار الرباب وخزرجي أو أوسي)\n(وتجنبي الجعراء إن سيوفهم حدث وإن قناتهم لم تضرس ... )\n(هل طيء الأجبال شاكرة امرئ ... ذاد القوافي عن حماها مردس)\n(أحمي أبا نفر عظام حفيرة ... درست وباقي غرسها لم يدرس)\n(كافأت نعمتها بضعف بلائها ... ثم انفردت بمنصب لم يدنس)\n(وإذا افتخرت عددت سعي مآثر ... قصرت على الإغضاء طرف الأشوس)\n(رفعت بنو النجار حلفي فيهم ... ثم انفردت فأفسحوا عن مجلسي)\n(فاعقل لسانك عن شتائم قومنا ... لا يعلقنك خادر من مأنس)\n(أخلفت فخرك من أبيك وجئتني ... بأب جديد بعد طول تلمس)\n(أخذت عليه المحكمات طريقها ... فغدا يهاجي أعظما في مرمس)\nال فلم يجبه ابن قنبر عن هذه بشيء ثم التقيا فتعاتبا واعتذر كل واحد منهما إلى صاحبه فقال مسلم يهجوه\n(حلم ابن قنبر حين قصر شعره ... هل كان يحلم شاعر عن شاعر)","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":14,"spl":"يتنسك بعد موت زوجته — سبب المهاجاة بينه وبين ابن قنبر","partial":1},
{"id":"b248-18","bab":"الجزء 19","sec":"مسلم يهجو قريشا ويفخر بالأنصار","page":"ج19 ص73","text":"وقد مضت هذه الأبيات متقدما قال ومكث ابن قنبر حينا لا يجيبه عن هذا ولا عن غيره بشيء طلبا للكفاف ثم هجا مسلم قريشا وفخر بالأنصار فقال\n(قل لمن تاه إذ بنا عز جهلا ... ليس بالتيه يفخر الأحرار)\n(فتناهوا وأقصروا فلقد جارت ... عن القصد فيكم الأنصار)\n(أيكم حاط ذا جوار بعز ... قبل أن تحتويه منا الدار)\n(أو رجا أن يفوت قوما بوتر ... لم تزل تمتطيهم الأوتار)\n(لم يكن ذاك فيكم فدعوا الفخر ... بما لا يسوغ فيه افتخار)\n(ونزارا ففاخروا تفضلوهم ... ودعوا من له عبيدا نزار)\n(فبنا عز منكم الذل والدهر ... عليكم بريبة كرار)\n(حاذروا دولة الزمان عليكم ... إنه بين أهله أطوار)\n(فتردوا ونحن للحالة الأولى ... وللأوحد الأذل الصغار)\n(فاخرتنا لما بسطنا لها الفخر ... قريش وفخرها مستعار)\n(ذكرت عزها وما كان فيها ... قبل أن يستجيرنامستجار)\n(إنما كان عزها في جبال ... ترتقيها كما ترقى الوبار)\n(أيها الفاخرون بالعز والعز ... لقوم سواهم والفخار)\n(أخبرونا من الأعز أألمنصور ... حتى اعتلى أم الأنصار)\n(فلنا العز قبل عز قريش ... وقريش تلك الدهور تجار)\nال فانبرى له ابن قنبر يجيبه فقال\n(ألا امثل أمير المؤمنين بمسلم ... وأفلق به الأحشاء من كل مجرم)\n(ولا ترجعن عن قتله باستتابة ... فما هو عن شتم النبي بمحرم)\n(ولا عن مساواة له ولقومه ... قريش بأصداء لعاد وجرهم)\n(ويفخر بالأنصار جهلا على الذي ... بنصرته فازوا بحظ ومغنم)\n(وسموا به الأنصار لا عز قائل ... أراد قريشا بالمقال المذمم)\n(ومنهم رسول الله أزكى من انتمى ... إلى نسب زاك ومجد مقدم)\n(وما كانت الأنصار قبل اعتصامها ... بنصر قريش في المحل المعظم)\n(ولا بالألى يعلون أقدار قومهم ... صداء وخولان ولخم وسلهم)\n(ولكنهم بالله عاذوا ونصرهم ... قريشا ومن يستعصم الله يعصم)\n(فعزوا وقد كانوا وفطيون فيهم ... من الذل في باب من العز مبهم)\n(يسومهم الفطيون ما لا يسامه ... كريم ومن لا ينكر الظلم يظلم)\n(وإن قريشا بالمآثر فضلت ... على الخلق طرا من فصيح وأعجم)\n(فما بال هذا العلج ضل ضلاله ... يمد إليهم كف أجذم أعسم)\n(يسامي قريشا مسلم وهم هم ... بمولى يماني وبيت مهدم)\n(إذا قام فيه غيرهم لم يكن له ... مقام به من لؤم مبنى ومدعم)\n(جعاسيس أشباه القرود لو أنهم ... يباعون ما ابتيعوا جميعا بدرهم)\n(وما مسلم من هؤلاء ولا ألى ... ولكنه من نسل علج ملكم)\n(تولى زمانا غيرهم ثمت ادعى ... إليهم فلم يكرم ولم يتكرم)\n(فإن يك منهم فالنضير ولفهم ... مواليه لا من يدعي بالتزعم)\n(وإن تدعه الأنصار مولى أسمهم ... بقافية تستكره الجلد بالدم)\n(عقابا لهم في إفكهم وادعائهم ... لأقلف منقوش الذراع موشم)\n(فلا تدعوه وانتفوا منه تسلموا ... بنفيكموه من مقام ومأثم)\n(وإلا فغضوا الطرف وانتظروا الردى ... إذا اختلفت فيكم صوارد أسهمي)\n(ولم تجدوا منها مجنا يجنكم ... إذا طلعت من كل فج ومعلم)\nوأنتم بنو أذناب من أنتم له ... ولستم بأبناء السنام المقدم ولا ببني الرأس الرفيع محله ... فيسمو بكم مولى مسام وينتمي\nكيف رضيتم أن يسامى نبيكم ... بيتكم الرث القصير المهدم سأحطم من سامى النبي تطاولا ... عليه وأكوي منتماه بميسم أيعدل بيت يثربي بكعبة ... ثوتها قريش في المكان المحرم قريش خيار الله والله خصهم ... بذلك فاقعس أيها العلج وارغم ومن يدعي منه الولاء مؤخر ... إذا قيل للجاري إلى المجد أقدم","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":15,"spl":"مسلم يهجو قريشا ويفخر بالأنصار"},
{"id":"b248-19","bab":"الجزء 19","sec":"مسلم يهجو تميما وابن قنبر يهجوه","page":"ج19 ص76","text":"قال وكان مسلم قال هذه القصيدة في قريش وكتمها فوقعت إلى ابن قنبر وأجابه عنها واستعلى عليه وهتكه وأغرى به السلطان فلم يكن عند مسلم في هذا جواب أكثر من الانتفاء منها ونسبتها إلى قنبر والادعاء عليه أنه ألصقها به ونسبها إليه ليعرضه للسلطان وخافه فقال ينتفي من هذه القصيدة ويهجو تميما\n(دعوت أمير المؤمنين ولم تكن ... هناك ولكن من يخف يتجشم)\n(وإنك إذ تدعوا الخليفة ناصرا ... لكالمترقي في السماء بسلم)\n(كذاك الصدى تدعوه من حيث لا ترى ... وإن تتوهمه تمت في التوهم)\n(هجوت قريشا عامدا ونحلتني ... رويدك يظهر ما تقول فيعلم)\n(إذا كان مثلي في قبيل فإنه ... على ابني لؤي قصرة غير متهم)\n(سيكشفك التعديل عما قرفتني ... به فتأخر عارفا أو تقدم)\n(فإن قريشا لا تغير ودها ... ولا يستمال عهدها بالتزعم)\n(مضى سلف منهم وصلى بعقبهم ... لنا سلف في الأول المتقدم)\n(جروا فجرينا سابقين بسبقهم ... كما اتبعت كف نواشر معصم)\n(وإن الذي يسعى ليقطع بيننا ... كملتمس اليربوع في جحر أرقم)\n(أضلك قدع الآبدات طريقها ... فأصبحت من عميائها في تهيم)\n(وخانتك عند الجري لما اتبعتها ... تميم فحاولت العلا بالتقحم)\n(فأصبحت ترميني بسهمي وتتقي ... يدي بيدي أصليت نارك فاضرم)\nال ثم هجاه ابن قنبر بقصيدة أولها\n(قل لعبد النضير مسلم الوغد ... الدني اللئيم شيخ النصاب)\n(أخس يا كلب إذ نبحت فإني ... لست ممن يجيب نبح الكلاب)\n(أفأرضى ومنصبي منصب العز ... وبيتي في ذروة الأحساب)\n(أن أحط الرفيع من سمك بيتي ... بمهاجاة أوشب الأوشاب)\n(من إذا سيل من أبوه بدا منه ... حياء يحميه رجع الجواب)\n(وإذا قيل حين يقبل من أنت ... ومن تعتزيه في الأنساب)\n(قلت هاجي ابن قنبر فتسربلت ... بذكري فخرا لدى النساب)\nهي قصيدة فلم يجبه مسلم عنها بشيء فقال فيه ابن قنبر أيضا\n(لست أنفيك إن سواي نفاكا ... عن أبيك الذي له منتماكا)\n(ولماذا أنفيك يا بن وليد ... من أب إن ذكرته أخزاكا)\n(ولو أني طلبت ألأم منه ... لم أجده إن لم تكن أنت ذاكا)\n(لو سواه أباك كان جعلنا ... إن الناس طاوعونا أباكا)\n(حاك دهرا بغير حذق لبرد ... وتحوك الأشعار أنت كذاكا)\nهي طويلة فلم يجبه مسلم عنها بشيء فقال ابن قنبر أيضا يهجوه\n(فخر العبد عبد قن اليهود ... بضعيف من فخره مردود)\n(فاخر الغر من قريش بإخوان ... خنازير من يثرب والقرود)\n(يتولى بني النضير ويدعو ... بهم الفخر من مكان بعيد)\n(وبني الأوس والخزارج أهل الذل ... في سالف الزمان التليد)\n(إذ رضوا بافتضاض فطيون منهم ... كل بكر ريا الروادف رود)\n(وبنو عمها شهود لما يفعل ... فطيون قبحوا من شهود)\n(خلف باب الفطيون والبعل منهم ... لا بذي غيرة ولا بنجيد)\n(فإذا ما قضى اليهودي منها ... نحبه قنعوا بخزي جديد)\nال فلما أفحش في هذه القصيدة وفي عدة قصائد قالها ومسلم لا يجيبه مشى إليه قوم من مشيخة الأنصار واستعانوا بمشيخة من قراء تميم وذوي العلم والفضل منهم فمشوا معهم إليه فقالوا له ألا تستحي من أن تهجو من لا يجيبك أنت بدأت الرجل فأجابك ثم عدت فكف وتجاوزت ذلك إلى ذكر أعراض\nالأنصار التي كان رسول الله يحميها ويذب عنها ويصونها لغير حال أحلت لك ذلك منهم فما زالوا يغطونه ويقولون له كل قول حتى أمسك عن المناقضة لمسلم فانقطعت صوت\n(ثلاثة تشرق الدنيا ببهجتهم ... شمس الضحى وأبو إسحاق والقمر)\n(يحكي أفاعيله في كل نائبة ... الغيث والليث والصمصامة الذكر)\nلشعر لمحمد بن وهيب والغناء لعلويه ثقيل أول بالوسطى وفيه لإبراهيم بن المهدي ثقيل أول آخر عن الهشامي","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":16,"spl":"مسلم يهجو تميما وابن قنبر يهجوه — أخبار محمد بن وهيب"},
{"id":"b248-20","bab":"الجزء 19","sec":"أخبار محمد بن وهيب","page":"ج19 ص79","text":"محمد بن وهيب الحميري صليبة شاعر من أهل بغداد من شعراء الدولة العباسية وأصله من البصرة وله أشعار كثيرة يذكرها فيها ويتشوقها ويصف إيطانه إياها ومنشأه بها وكان يستمنح الناس بشعره ويتكسب بالمديح ثم توسل إلى الحسن ابن سهل بالحسن بن رجاء بن أبي الضحاك ومدحه فأوصله إليه وسمع شعره فأعجب به واقتطعه إليه وأوصله إلى المأمون حتى مدحه وشفع له فأسنى جائزته ثم لم يزل منقطعا إليه حتى مات وكان يتشيع وله مراث في أهل البيت وهو متوسط من شعراء طبقته وفي شعره أشياء نادرة فاضلة وأشياء متكلفة","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":16,"spl":"مسلم يهجو تميما وابن قنبر يهجوه — أخبار محمد بن وهيب"},
{"id":"b248-21","bab":"الجزء 19","sec":"المعتصم يسمعه ويجيزه","page":"ج19 ص80","text":"أخبرنا محمد بن خلف وكيع قال زعم أبو محلم وأخبرني عمي عن علي بن الحسين بن عبد الأعلى عن أبي محلم قال اجتمع الشعراء على باب المعتصم فبعث إليهم محمد بن عبد الملك\nالزيات أن أمير المؤمنين يقول لكم من كان منكم يحسن أن يقول مثل قول النمري في الرشيد\n(خليفة الله إن الجود أودية ... أحلك الله منها حيث تجتمع)\n(من لم يكن بأمين الله معتصما ... فليس بالصلوات الخمس ينتفع)\n(إن أخلف القطر لم تخلف مخايله ... أو ضاق أمر ذكرناه فيتسع)\nليدخل وإلا فلينصرف فقام محمد بن وهيب فقال فينا من يقول مثله قال وأي شيء قلت فقال\n(ثلاثة تشرق الدنيا ببهجتهم ... شمس الضحى وأبو إسحاق والقمر)\n(تحكي أفاعيله في كل نائبة ... الغيث والليث والصمصامة الذكر)\nأمر بإدخاله وأحسن جائزته أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن محمد بن مروان أبو موسى قال حدثني محمد بن وهيب الشاعر قال\nلما تولى الحسن بن رجاء بن أبي الضحاك الجبل قلت فيه شعرا وأنشدته أصحابنا دعبل بن علي وأبا سعد المخزومي وأبا تمام الطائي فاستحسنوا الشعر وقالوا هذا لعمري من الأشعار التي تلقى بها الملوك فخرجت إلى الجبل فلما صرت إلى همذان أخبره الحاجب بمكاني فأذن لي فأنشدته الشعر فاستحسن منه قولي\n(أجارتنا إن التعفف بالياس ... وصبرا على استدرار دنيا بإبساس)\n(حريان ألا يقذفا بمذلة ... كريما وألا يحوجاه إلى الناس)\n(أجارتنا إن القداح كواذب ... وأكثر أسباب النجاح مع الياس)\nأمر حاجبه بإضافتي فأقمت بحضرته كلما دخلت إليه لم أنصرف إلا بحملان أو خلعة أو جائزة حتى انصرم الصيف فقال لي يا محمد إن الشتاء عندنا علج فأعد يوما للوداع فقلت خدمة الأمير أحب إلي فلما كاد الشتاء أن يشتد قال لي هذا أوان الوداع فأنشدني الثلاثة الأبيات فقد فهمت الشعر كله فلما أنشدته\n(أجارتنا إن القداح كواذب ... وأكثر أسباب النجاح مع الياس)\nال صدقت ثم قال عدوا أبيات القصيدة فأعطوه لكل بيت ألف درهم فعدت فكانت اثنين وسبعين بيتا فأمر لي باثنين وسبعين ألف درهم وكان فيما أنشدته في مقامي واستحسنه قولي صوت\n(دماء المحبين لا تعقل ... أما في الهوى حكم يعدل)\n(تعبدني حور الغانيات ... ودان الشباب له الأخطل)\n(ونظرة عين تعللتها ... غرارا كما ينظر الأحول)\n(مقسمة بين وجه الحبيب ... وطرف الرقيب متى يغفل)\nي هذه الأبيات هزج طنبوري سمعته من جحظة فذكر أنه يراه للمسدود ولم يحقق صانعه قال الأصبهاني وهذه الأبيات له في المطلب بن عبد الله بن مالك الخزاعي قال محمد بن وهيب وأهدي إلى الحسن بن رجاء غلام فأعجب به فكتبت إليه\n(ليهنك الزائر الجديد ... جرى به الطائر السعيد)\n(جاء مشوق إلى مشوق ... فذا ودود وذا ودود)\n(يوم نعيم ويوم لهو ... خصصت فيه بما تريد)\n(إلف مشوق أتاه إلف ... فمستفاد ومستفيد)\nدثني أحمد بن عبد الله بن عمار بهذا الحديث عن يعقوب بن إسرائيل قرقارة عن محمد بن محمد بن مروان بن موسى عن محمد بن وهيب فذكر مثل الذي قبله وزاد فيه فلم يزل يستعيدني\n(أجارتنا إن القداح كواذب ... وأكثر أسباب النجاح مع الياس)\nوأنا أعيده عليه فانصرفت من عنده بأكثر مما كنت أؤمل","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":17,"spl":"المعتصم يسمعه ويجيزه"},
{"id":"b248-22","bab":"الجزء 19","sec":"أبو دلف يعجب به ويعظمه","page":"ج19 ص83","text":"حدثني علي بن صالح بن الهيثم الأنباري الكاتب قال حدثني أبو هفان\nقال حدثني خالي قال كنت عند أبي دلف القاسم بن عيسى فدخل عليه محمد بن وهيب الشاعر فأعظمه جدا فلما انصرف قال له أخوه معقل يا أخي قد فعلت بهذا ما لم يستحقه ما هو في بيت من الشرف ولا في كمال من الأدب ولا بموضع من السلطان فقال بلى يا أخي إنه لحقيق بذلك أو لا يستحقه وهو القائل صوت\n(يدل على أنني عاشق ... من الدمع مستشهد ناطق)\n(ولي مالك أنا عبد له ... مقر بأني له وامق)\n(إذا ما سموت إلى وصله ... تعرض لي دونه عائق)\n(وحاربني فيه ريب الزمان ... كأن الزمان له عاشق)\nي هذه الأبيات رمل طنبوري أظنه لجحظة حدثني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال لما قدم المطلب بن عبد الله بن مالك من الحج لقيه محمد بن وهيب مستقبلا مع من تلقاه ودخل إليه مهنئا بالسلامة بعد استقراره وعاد إليه في الثالثة فأنشده قصيدة طويلة مدحه بها يقول فيها\n(وما زلت أسترعي لك الله غائبا ... وأظهر إشفاقا عليك وأكتم)\n(وأعلم أن الجود ما غبت غائب ... وأن الندى في حيث كنت مخيم)\n(إلى أن زجرت الطير سعدا سوانحا ... وحم لقاء بالسعود ومقدم)\n(وظل يناجيني بمدحك خاطر ... وليلي ممدود الرواقين أدهم)\n(وقال طواه الحج فاخشع لفقده ... ولا عيش حتى يستهل المحرم)\n(سيفخر ما ضم الحطيم وزمزم ... بمطلب لو أنه يتكلم)\n(وما خلقت إلا من الجود كفه ... على أنها والبأس خدنان توأم)\n(أعدت إلى أكناف مكة بهجة ... خزاعية كانت تجل وتعظم)\n(ليالي سمار الحجون إلى الصفا ... خزاعة إذ خلت لها البيت جرهم)\n(ولو نطقت بطحاؤها وحجونها ... وخيف منى والمأزمان وزمزم)\n(إذا لدعت أجزاء جسمك كلها ... تنافس في أقسامه لو تحكم)\n(ولو رد مخلوق إلى بدء خلقه ... إذا كنت جسما بينهن تقسم)\n(سما بك منها كل خيف فأبطح ... نما بك منه الجوهر المتقدم)\n(وحن إليك الركن حتى كأنه ... وقد جئته خل عليك مسلم)\nال فوصله صلة سنية وأهدى له هدية حسنة من طرف ما قدم به وحمله والله أعلم","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":18,"spl":"أبو دلف يعجب به ويعظمه"},
{"id":"b248-23","bab":"الجزء 19","sec":"يمدح الحسن بن سهل فيطربه","page":"ج19 ص86","text":"أخبرني جعفر بن قدامة قال حدثني الحسن بن الحسن بن رجاء عن أبيه وأهله قالوا كان محمد بن وهيب الحميري لما قدم المأمون من خراسان مضاعا مطرحا إنما يتصدى للعامة وأوساط الكتاب والقواد بالمديح ويسترفدهم فيحظى باليسير فلما هدأت الأمور واستقرت واستوسقت جلس أبو محمد الحسن بن سهل يوما منفردا بأهله وخاصته وذوي مودته ومن يقرب من أنسه فتوسل إليه محمد بن وهيب بأبي حتى أوصله مع الشعراء فلما انتهى إليه القول استأذن في الإنشاد فأذن له فأنشده قصيدته التي أولها\n(ودائع أسرار طوتها السرائر ... وباحت بمكتوماتهن النواظر)\n(ملكت بها طي الضمير وتحته ... شبا لوعة عضب الغرارين باتر)\n(فأعجم عنها ناطق وهو معرب ... وأعربت العجم الجفون العواطر)\n(ألم تغذني السراء في ريق الهوى ... غريرا بما تجني علي الدوائر)\n(تسللني الأيام في عنفوانه ... ويكلؤني طرف من الدهر ناظر)\nتى انتهى إلى قوله\n(إلى الحسن الباني العلا يممت بنا ... عوالي المنى حيث الحيا المتظاهر)\n(إلى الأمل المبسوط والأجل الذي ... بأعدائه تكبو الجدود العواثر)\n(ومن أنبعت عين المكارم كفه ... يقوم مقام القطر والروض داثر)\n(تعصب تاج الملك في عنفوانه ... وأطت به عصر الشباب المنابر)\n(تعظمه الأوهام قبل عيانه ... ويصدر عنه الطرف والطرف حاسر)\n(به تجتدى النعمى وتستدرك المنى ... وتستكمل الحسنى وترعى الأواصر)\n(أصات بنا داعي نوالك مؤذنا ... بجودك إلا أنه لا يحاور)\n(قسمت صروف الدهر بأسا ونائلا ... فمالك موتور وسيفك واتر)\n(ولما رأى الله الخلافة قد وهت ... دعائمها والله بالأمر خابر)\n(بنى بك أركانا عليك محيطة ... فأنت لها دون الحوادث سائر)\n(وأرعن فيه للسوابغ جنة ... وسقف سماء أنشأته الحوافر)\nعني أن على الدروع من الغبار ما قد غشيها فصار كالجنة لها\n(لها فلك فيه الأسنة أنجم ... ونقع المنايا مستطير وثائر)\n(أجزت قضاء الموت في مهج العدا ... ضحى فاستباحتها المنايا الغوادر)\n(لك اللحظات الكالئات قواصدا ... بنعمىوبالبأساء وهي شوازر)\n(ولم لم تكن إلا بنفسك فاخرا ... لما انتسبت إلا إليك المفاخر)\nقال فطرب أبو محمد حتى نزل عن سريره إلى الأرض وقال أحسنت والله وأجملت ولو لم تقل قط ولا تقول في باقي دهرك غير هذا لما احتجت إلى القول وأمر له بخمسة آلاف دينار فأحضرت واقتطعه إلى نفسه فلم يزل في جنبته أيام ولايته وبعد ذلك إلى أن مات ما تصدى لغيره","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":19,"spl":"يمدح الحسن بن سهل فيطربه"},
{"id":"b248-24","bab":"الجزء 19","sec":"يهجو علي بن هشام","page":"ج19 ص88","text":"حدثني أحمد بن جعفر جحظة قال حدثني ميمون بن هارون قال كان محمد بن وهيب الحميري الشاعر قد مدح علي بن هشام وتردد إليه وإلى بابه دفعات فحجبه ولقيه يوما فعرض له في طريقه وسلم عليه فلم يرفع إليه طرفه وكان فيه تيه شديد فكتب إليه رقعة يعاتبه فيها فلما وصلت إليه خرقها وقال أي شيء يريد هذا الثقيل السيء الأدب فقيل له ذلك فانصرف مغضبا وقال والله ما أردت ماله وإنما أردت التوسل بجاهه وسيغني الله جل وعز عنه أما والله ليذمن مغبة فعله وقال يهجوه\n(أزرت بجود علي خيفة العدم ... فصد منهزما عن شأو ذي الهمم)\n(لو كان من فارس في بيت مكرمة ... أو كان من ولد الأملاك في العجم)\n(أو كان أوله أهل البطاح أو الركب ... الملبون إهلالا إلى الحرم)\n(أيام تتخذ الأصنام آلهة ... فلا ترى عاكفا إلا على صنم)\n(لشجعته على فعل الملوك لهم ... طبائع لم ترعها خيفة العدم)\n(لم تند كفاك من بذل النوال كما ... لم يند سيفك مذ قلدته بدم)\n(كنت امرأ رفعته فتنة فعلا ... أيامها غادرا بالعهد والذمم)\n(حتى إذا انكشفت عنا عمايتها ... ورتب الناس بالأحساب والقدم)\n(مات التخلق وارتدتك مرتجعا ... طبيعة نذلة الأخلاق والشيم)\n(كذاك من كان لا رأسا ولا ذنبا ... كز اليدين حديث العهد بالنعم)\n(هيهات ليس بحمال الديات ولا ... معطي الجزيل ولا المرهوب ذي النقم)\nقال فحدثني بعض بني هاشم أن هذه الأبيات لما بلغت علي بن هشام ندم على ما كان منه وجزع لها وقال لعن الله اللجاج فإنه شر خلق تخلقه الناس ثم أقبل على أخيه الخليل بن هشام فقال الله يعلم أني لا أدخل على الخليفة وعلي السيف إلا وأنا مستح منه أذكر قول ابن وهيب في\n(لم تند كفاك من بذل النوال كما ... لم يند سيفك مذ قلدته بدم)\nدثني محمد بن يحي الصولي قال حدثني ميمون بن هارون قال من سمع ابن الأعرابي يقول أهجى بيت قاله المحدثون قول محمد بن وهيب\n(لم تند كفاك من بذل النوال كما ... لم يند سيفك مذ قلدته بدم)\nخبرني محمد بن خلف بن المرزبان قال حدثني محمد بن مرزوق البصري قال حدثني محمد بن وهيب قال جلست بالبصرة إلى عطار فإذا أعرابيه سوداء قد جاءت فاشترت من العطار خلوقا فقلت له تجدها اشترته لابنتها وما ابنتها\nإلا خنفساء فالتفتت إلى متضاحكة ثم قالت لا والله لكن مهاة جيداء إن قامت فقناة وإن قعدت فحصاة وإن مشت فقطاة أسفلها كثيب وأعلاها قضيب لا كفتياتكم اللواتي تسمنونهن بالفتوت ثم انصرفت وهي تقول\n(إن الفتوت للفتاة مضرطه ... يكربها في البطن حتى تثلطه)\nلا أعلمني ذكرتها إلا أضحكني ذكرها حدثني عيسى بن الحسين الوراق قال حدثنا أبو هفان قال كان محمد بن وهيب يتردد إلى مجلس يزيد بن هارون فلزمه عدة مجالس يملي فيها كلها فضائل أبي بكر وعمر وعثمان رضي الله عنهم لا يذكر شيئا من فضائل علي عليه السلام فقال فيه ابن وهيب\n(آتي يزيد بن هارون أدالجه ... في كل يوم ومالي وابن هارون)\n(فليت لي بيزيد حين أشهده ... راحا وقصفا وندمانا يسليني)\n(أغدو إلى عصبة صمت مسامعهم ... عن الهدى بين زنديق ومأفون)\n(لا يذكرون عليا في مشاهدهم ... ولا بنيه بني البيض الميامين)\n(الله يعلم أني لا أحبهم ... كما هم بيقين لا يحبوني)\n(لو يستطيعون عن ذكري أبا حسن ... وفضله)\n(ولست أترك تفضيلي له أبدا ... حتى الممات على رغم الملاعين)","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":20,"spl":"يهجو علي بن هشام"},
{"id":"b248-25","bab":"الجزء 19","sec":"مذهبه من شعره","page":"ج19 ص91","text":"أخبرني محمد بن خلف بن المزربان قال حدثني إسحاق بن محمد الكوفي قال حدثني محمد بن القاسم بن يوسف وأخبرني به الحسن بن علي قال حدثنا أحمد بن القاسم قال حدثني إسحاق عن محمد بن القاسم بن يوسف قال كان محمد بن وهيب يأتي أبي فقال له أبي يوما إنك تأتينا وقد عرفت مذاهبنا فنحب أن تعرفنا مذهبك فنوافقك أو نخالفك فقال له في غد أبين لك أمري ومذهبي فلما كان من غد كتب إليه\n(أيها السائل قد بينت ... إن كنت ذكيا)\n(أحمد الله كثيرا ... بأياديه عليا)\n(شاهدا أن لا إله ... غيره ما دمت حيا)\n(وعلى أحمد بالصدق ... رسولا ونبيا)\n(ومنحت الود قرباه ... وواليت الوصيا)\n(وأتاني خبر مطرح ... لم يك شيا)\n(أن على غير اجتماع ... عقدوا الأمر بديا)\n(فوقفت القوم تيما ... وعديا وأميا)\n(غير شتام ولكني ... توليت عليا)\nدثني جحظة قال حدثني علي بن يحيى المنجم قال بلغ محمد بن وهيب أن دعبل بن علي قال أنا ابن قولي\n(لا تعجبي يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nوإن أبا تمام قال أنا ابن قولي\n(نقل فؤادك حيث شئت من الهوى ... ما الحب إلا للحبيب الأول)\nقال محمد بن وهيب وأنا ابن قولي\n(ما لمن تمت محاسنه ... أن يعادي طرف من رمقا)\nك أن تبدي لنا حسنا ... ولنا أن نعمل الحدقا\nال أبو الفرج الأصبهاني وهذا من جيد شعره ونادره وأول هذه الأبيات قوله\n(نم فقد وكلت بي الأرقا ... لاهيا تغري بمن عشقا)\n(إنما أبقيت من جسدي ... شبحا غير الذي خلقا)\n(وفتى ناداك من كثب ... أسعرت أحشاؤه حرقا)\n(غرقت في الدمع مقلته ... فدعا إنسانها الغرقا)\n(إنما عاقبت ناظره ... أن أعاد اللحظ مسترقا)\n(ما لمن تمت محاسنه ... أن يعادي طرف من رمقا)\n(لك أن تبدي لنا حسنا ... ولنا أن نعمل الحدقا)\n(قدحت كفاك زند هوى ... في سواد القلب فاحترقا)\nدثني عمي قال حدثني أبو عبد الله الهشامي عن أبيه قال دخل محمد بن وهيب على أحمد بن هشام يوما وقد مدحه فرأى بين يديه\nغلمانا روقة مردا وخدما بيضا فرها في نهاية الحسن والكمال والنظافة فدهش لما رأى وبقي متبلدا لا ينطق حرفا فضحك أحمد منه وقال له ما لك ويحك تكلم بما تريد فقال\n(قد كانت الأصنام وهي قديمة ... كسرت وجدعهن إبراهيم)\n(ولديك أصنام سلمن من الأذى ... وصفت لهن غضارة ونعيم)\n(وبنا إلى صنم نلوذ بركنه ... فقر وأنت إذا هززت كريم)\nقال له اختر من شئت فاختار واحدا منهم فأعطاه إياه فقال يمدحه\n(فضلت مكارمه على الأقوام ... وعلا فحاز مكارم الأيام)\n(وعلته أبهة الجلال كأنه ... قمر بدا لك من خلال غمام)\n(إن الأمير على البرية كلها ... بعد الخليفة أحمد بن هشام)\nأخبرني جعفر بن قدامة في خبره الذي ذكرته آنفا عنه عن الحسين بن الحسن بن رجاء عن أبيه قال لما قدم المأمون لقيه أبو محمد الحسن بن سهل فدخلا جميعا فعارضهما ابن وهيب وقال\n(اليوم جددت النعماء والمنن ... فالحمد لله حل العقدة الزمن)\n(اليوم أظهرت الدنيا محاسنها ... للناس لما التقى المأمون والحسن)\nقال فلما جلسنا سأله المأمون عنه فقال هذا رجل من حمير شاعر مطبوع اتصل بي متوسلا إلى أمير المؤمنين وطالبا الوصول مع نظرائه فأمر\nالمأمون بإيصاله مع الشعراء فلما وقف بين يديه وأذن له في الإنشاد أنشده قوله\n(طللان طل عليهما الأمد ... دثرا فلا علم ولا نضد)\n(لبسا البلى فكأنما وجدا ... بعد الأحبة مثل ما أجد)\n(حييتما طللين حالهما ... بعد الأحبة غير ما عهدوا)\n(إما طواك سلو غانية ... فهواك لا ملل ولا فند)\n(إن كنت صادقة الهوى فردي ... في الحب منهلي الذي أرد)\n(أدمي هرقت وأنت آمنة ... أم ليس لي عقل ولا قود)\n(إن كنت فت وخانني سبب ... فلربما يخطىء مجتهد)\nتى انتهى إلى قوله في مدح المأمون\n(يا خير منتسب لمكرمة ... في المجد حيث تبحبح العدد)\n(في كل أنملة لراحته ... نوء يسح وعارض حشد)\n(وإذا القنا رعفت أسنته ... علقا وصم كعوبها قصد)\nكأن ضوء جبينه قمر ... وكأنه في صولة أسد\n(وكأنه روح تدبرنا ... حركاته وكأننا جسد)\nاستحسنها المأمون وقال لأبي محمد احتكم له فقال أمير المؤمنين أولى بالحكم ولكن إن أذن لي في المسألة سألت له فأما الحكم فلا فقال سل فقال يلحقه بجوائز مروان بن أبي حفصة فقال ذلك والله أردت وأمر بأن تعد أبيات قصيدته ويعطى لكل بيت ألف درهم فعدت فكانت خمسين فأعطي خمسين ألف درهم","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":21,"spl":"مذهبه من شعره"},
{"id":"b248-26","bab":"الجزء 19","sec":"من مدائحه للمأمون والمطلب بن عبد الله","page":"ج19 ص95","text":"قال الأصبهاني وله في المأمون والحسن بن سهل خاصة مدائح شريفة نادرة من عيونها قوله في المأمون في قصيدة أولها\n(العذر إن أنصفت متضح ... وشهيد حبك أدمع سفح)\n(فضحت ضميرك عن ودائعه ... إن الجفون نواطق فصح)\n(وإذا تكلمت العيون على ... إعجامها فالسر مفتضح)\n(ربما أبيت معانقي قمر ... للحسن فيه مخايل تضح)\n(نشر الجمال على محاسنه ... بدعا وأذهب همه الفرح)\n(يختال في حلل الشباب به ... مرح وداؤك أنه مرح)\n(ما زال يلثمني مراشفه ... ويعلني الإبريق والقدح)\n(حتى استرد الليل خلعته ... ونشا خلال سواده وضح)\n(وبدا الصباح كأن غرته ... وجه الخليفة حين يمتدح)\nقول فيها\n(نشرت بك الدنيا محاسنها ... وتزينت بصفاتك المدح)\n(وكأن ما قد غاب عنك له ... بإزاء طرفك عارضا شبح)\n(وإذا سلمت فكل حادثة ... جلل فلا بؤس ولا ترح)\nخبرني هاشم بن محمد الخزاعي قال حدثني أهلنا أن محمد بن وهيب قصد المطلب بن عبد الله بن مالك الخزاعي عم أبي وقد ولي الموصل وكان له صديقا حفيا وكان كثير الرفد له والثواب على مدائحه فأنشده قوله فيه صوت\n(دماء المحبيين لا تعقل ... أما في الهوى حاكم يعدل)\n(تعبدني حور الغانيات ... ودان الشباب له الأخطل)\n(ونظرة عين تلافيتها ... غرارا كما ينظر الأحول)\n(مقسمة بين وجه الحبيب ... وطرف الرقيب متى يغفل)\n(أذم على غربات النوى ... إليك السلو ولا أذهل)\n(وقالوا عزاؤك بعد الفراق ... إذا حم مكروهه أجمل)\n(أقيدي دما سفكته العيون ... بإيماض كحلاء لا تكحل)\n(فكل سهامك لي مقصد ... وكل مواقعها مقتل)\n(سلام على المنزل المستحيل ... وإن ضن بالمنطق المنزل)\n(وعضب الضريبة يلقى الخطوب ... بجد عن الدهر لا ينكل)\n(تغلغل شرقا إلى مغرب ... فلما تبدت له الموصل)\n(ثوى حيث لا يستمال الأريب ... ولا يولف القين الحول)\n(لدى ملك قابلته السعود ... وجانبه الأنجم الأفل)\n(لأيامه سطوات الزمان ... وإنعامه حين لا موئل)\n(سما مالك بك للباهرات ... وأوحدك المربأ الأطول)\n(وليس بعيدا بأن تحتذي ... مذاهب آسادها الأشبل)\nال فوصله وأحسن جائزته وأقام عنده مدة ثم استأذنه في الانصراف فلم يأذن له وزاد في ضيافته وجراياته وجدد له صلة فأقام عنده برهة أخرى ثم دخل عليه فأنشده\n(ألا هل إلى ظل العقيق وأهله ... إلى قصر أوس فالحزير معاد)\n(وهل لي بأكناف المصلى فسفحه ... إلى السور مغدى ناعم ومراد)\n(فلم تنسني نهر الأبلة نية ... ولا عرصات المربدين بعاد)\n(هنالك لا تبني الكواعب خيمة ... ولا تتهادى كلثم وسعاد)\n(أجدي لا ألقى النوى مطمئنة ... ولا يزدهيني مضجع وجهاد)\nقال له أبيت إلا الوطن والنزاع إليه ثم أمر له بعشرة آلاف درهم وأوقر له زورقا من طرف الموصل وأذن له حدثني محمد بن يحي الصولي قال حدثني أبو عبد الله الماقطاني عن علي بن الحسين بن عبد الأعلى عن سعيد بن وهيب قال كان المأمون كثيرا ما يتمثل إذا كربه الأمر\n(ألا ربما ضاق الفضاء بأهله ... وأمكن من بين الأسنة مخرج)","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":22,"spl":"من مدائحه للمأمون والمطلب بن عبد الله"},
{"id":"b248-27","bab":"الجزء 19","sec":"قصيدته في ابن عباد","page":"ج19 ص98","text":"قال الأصبهاني وهذا الشعر لمحمد بن وهيب يقوله في ابن عباد وزير المأمون وكان له صديقا فلما ولي الوزارة اطرحه لانقطاعه إلى الحسن بن سهل فقال فيه قصيدة أولها\n(تكلم بالوحي البنان المخضب ... ولله شكوى معجم كيف يعرب)\n(أإيماء أطراف البنان ووجهها ... أبانا له كيف الضمير المغيب)\n(وقد كان حسن الظن أنجب مرة ... فأحمد عقبى أمره المتعقب)\n(فلما تدبرت الظنون مراقبا ... تقلب حاليها إذا هي تكذب)\n(بدأت بإحسان فلما شكرته ... تنكرت لي حتى كأني مذنب)\n(وكل فتى يلقى الخطوب بعزمه ... له مذهب عمن له عنه مذهب)\n(وهل يصرع الحب الكريم وقلبه ... عليم بما يأتي وما يتجنب)\n(تأنيت حتى أوضح العلم أنني ... مع الدهر يوما مصعد ومصوب)\n(وألحقت أعجاز الأمور صدورها ... وقومها غمز القداح المقلب)\n(وأيقنت أن البأس للعرض صائن ... وأن سوف أغضي للقذى حين أرغب)\n(أغادرتني بين الظنون مميزا ... شواكل أمر بينهن مجرب)\n(يقربني من كنت أصفيك دونه ... بودي وتنأى بي فلا أتقرب)\n(فلله حظي منك كيف أضاعه ... سلوك عني والأمور تقلب)\n(أبعدك أستسقي بوارق مزنة ... وإن جاد هطال من المزن هيدب)\n(إذا ما رأيت البرق أغضيت دونه ... وقلت إذا ما لاح ذا البرق خلب)\n(وإن سنحت لي فرصة لم أسامها ... وأعرضت عنها خوف ما أترقب)\n(تأدبت عن حسن الرجاء فلن أرى ... أعود له إن الزمان مؤدب)\nقال له أيضا\n(هل الهم إلا كربة تتفرج ... لها معقب تحدى إليه وتزعج)\n(وما الدهر إلا عائد مثل سالف ... وما العيش إلا جده ثم تنهج)\n(وكيف أشيم البرق والبرق خلب ... ويطمعني ريعانه المتبلج)\n(وكيف أديم الصبر لا بي ضراعة ... ولا الرزق محظور ولا أنا محرج)\n(ألا ربما كان التصبر ذلة ... وأدنى إلى الحال التي هي أسمج)\n(وهل يحمل الهم الفتى وهو ضامن ... سرى الليل رحال العشيات مدلج)\n(ولا صبر ما أعدى على الدهر مطلب ... وأمكن إدلاج واصحر منهج)\n(ألا ربما ضاق الفضاء بأهله ... وأمكن من بين الأسنة مخرج)\n(وقد يركب الخطب الذي هو قاتل ... إذا لم يكن إلا عليه معرج)","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":23,"spl":"قصيدته في ابن عباد"},
{"id":"b248-28","bab":"الجزء 19","sec":"مدحه الأفشين","page":"ج19 ص100","text":"حدثني بعض أصحابنا عن أحمد بن أبي كامل قال كان محمد بن وهيب تياها شديد الذهاب بنفسه فلما قدم الأفشين وقد قتل بابك مدحه بقصيدته التي أولها\n(طلول ومغانيها ... تناجيها وتبكيها)\nقول فيها\n(بعثت الخيل والخير ... عقيد في نواصيها)\nوهي من جيد شعره فأنشدناها ثم قال ما لها عيب سوى أنها لا أخت لها قال وأمر المعتصم للشعراء الذين مدحوا الأفشين بثلاثمائة ألف درهم جرت تفرقتها على يد ابن أبي داود فأعطى منها محمد بن وهيب ثلاثين ألفا وأعطى أبا تمام عشرة آلاف درهم قال ابن أبي كامل فقلت لعلي بن يحي المنجم ألا تعجب من هذا الحظ يعطى أبو تمام عشرة آلاف وابن وهيب ثلاثين الفا وبينهما كما بين السماء والأرض فقال لذلك علة لا تعرفها كان ابن وهيب مؤدب الفتح بن خاقان فلذلك وصل إلى هذه الحال أخبرني محمد بن يحي الصولي قال حدثني ابو زكوان قال حدثني من دخل إلى محمد بن وهيب يعوده وهو عليل قال فسألته عن خبره فتشكى ما به ثم قال\n(نفوس المنايا بالنفوس تشعب ... وكل له من مذهب الموت مذهب)\n(نزاع لذكر الموت ساعة ذكره ... وتعترض الدنيا فنلهو ونلعب)\n(وآجالنا في كل يوم وليلة ... إلينا على غراتنا تتقرب)\n(أأيقن أن الشيب ينعى حياته ... مدرلأخلاف الخطيئة مذنب)\n(يقين كأن الشك أغلب أمره ... عليه وعرفان إلى الجهل ينسب)\n(وقد ذمت الدنيا إلي نعيمها ... وخاطبني إعجامها وهو معرب)\n(ولكنني منها خلقت لغيرها ... وما كنت منه فهو عندي محبب)\nخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أحمد بن أبي كامل قال كنا في مجلس ومعنا أبو يوسف الكندي وأحمد بن أبي فنن فتذاكرنا شعر محمد بن وهيب فطعن عليه ابن أبي فنن وقال هو متكلف حسود وإذا أنشد شعرا لنفسه قرظه ووصفه في نصف يوم وشكا أنه مظلوم منحوس الحظ وأنه لا تقصر به عن مراتب القدماء حال فإذا أنشد شعر غيره حسده وإن كان على نبيذ عربد عليه وإن كان صاحيا عاداه واعتقد فيه كل مكروه فقلت له كلاكما لي صديق وما أمتنع من وصفكما جميعا بالتقدم وحسن الشعر فأخبرني عما أسألك عنه إخبار منصف أو يعد متكلفا من يقول\n(أبى لي إغضاء الجفون على القذى ... يقيني أن لا عسر إلا مفرج)\n(ألا ربما ضاق الفضاء بأهله ... وأمكن من بين الأسنة مخرج)\nو يعد متكلفا من يقول\n(رأت وضحا من مفرق الرأس راعها ... شريحين مبيض به وبهيم)\nفأمسك ابن أبي فنن واندفع الكندي فقال كان ابن وهيب ثنويا فقلت له من أين علمت ذاك أكلمك على مذهب الثنوية قط قال لا ولكني استدللت من شعره على مذهبه فقلت حيث يقول ماذا فقال حيث يقول\n(طللان طال عليهما الأمد ... )\nحيث يقول\n(تفتر عن سمطين من ذهب ... )\nلى غير ذلك مما يستعمله في شعره من ذكر الإثنين فشغلني والله الضحك عن جوابه وقلت له يا أبا يوسف مثلك لا ينبغي أن يتكلم فيما لم ينفذ فيه علمه أخبرني أحمد بن عبيد الله بن عمار قال حدثني أحمد بن سليمان بن أبي شيخ عن أبيه قال سأل محمد بن وهيب محمد بن عبد الملك الزيات حاجة فأبطأ فيها فوقف عليه ثم قال له\n(طبع الكريم على وفائه ... وعلى التفضل في إخائه)\n(تغني عنايته الصدي ... ق عن التعرض لاقتضائه)\n(حسب الكريم حياؤه ... فكل الكريم إلى حيائه)\nقال له حسبك فقد بلغت إلى ما أحببت والحاجة تسبقك إلى منزلك ووفى له بذلك صوت\n(وددت على ما كان من سرف الهوى ... وغي الأماني أن ما شئت يفعل)\n(فترجع أيام تقضت ولذة ... تولت وهل يثنى من الدهر أول)\nلشعر لمزاحم العقيلي والغناء لمقاسمة بن ناصح خفيف رمل بالبنصر عن الهشامي قال الهشامي وفيه لأحمد بن يحيى المكي رمل","topic":"نسب مسلم بن الوليد وأخباره","topicNo":248,"sp":24,"spl":"مدحه الأفشين","partial":1},
{"id":"b249-1","bab":"الجزء 19","sec":"أخبار مزاحم ونسبه","page":"ج19 ص104","text":"هو مزاحم بن عمرو بن الحارث بن مصرف بن الأعلم بن خويلد بن عوف ابن عامر بن عقيل بن كعب بن ربيعة بن عامر بن صعصعة بن معاوية بن بكر بن هوازن وقيل مزاحم بن عمرو بن مرة بن الحارث بن مصرف بن الأعلم وهذا القول عندي أقرب إلى الصواب بدوي شاعر فصيح إسلامي صاحب قصيد ورجز كان في زمن جرير والفرزدق وكان جرير يصفه ويقرظه ويقدمه أخبرني محمد بن خلف بن المرزبان قال حدثني الفضل بن محمد اليزيدي عن إسحاق الموصلي قال قال لي عمارة بن عقيل كان جرير يقول ما من بيتين كنت أحب أن أكون سبقت إليهما غير بيتين من قول مزاحم العقيلي\n(وددت على ما كان من سرف الهوى ... وغي الأماني أن ماشئت يفعل)\n(فترجع أيام مضين ولذة ... تولت وهل يثنى من العيش اول)\nال المفضل قال إسحاق سرف الهوى خطؤه ومثله قول جرير\n(أعطوا هنيدة تحدوها ثمانية ... ما في عطائهم من ولا سرف)\nراد أنهم يحفظون مواضع الصنائع لا أنه وصفهم بالاقتصاد والتوسط في الجود قال إسحاق وواعدني زياد الأعرابي موضعا من المسجد فطلبته فيه فلم أجده فقلت له بعد ذلك طلبتك لموعدك فلم أجدك فقال أين طلبتني فقلت في موضع كذا وكذا فقال هناك والله سرفتك أي أخطأتك أخبرني محمد بن مزيد بن أبي الأزهر قال أنشدني حماد عن أبيه لمزاحم العقيلي قال وكان يستجيدها ويستحسنها\n(لصفراء في قلبي من الحب شعبة ... حمى لم تبحه الغانيات صميم)\n(بها حل بيت الحب ثم ابتنى بها ... فبانت بيوت الحي وهو مقيم)\n(بكت دارهم من نأيهم فتهللت ... دموعي فأي الجازعين ألوم)\n(أمستعبرا يبكي من الحزن والجوى ... أم آخر يبكي شجوه فيهيم)\n(تضمنه من حب صفراء بعد ما ... سلا هيضات الحب فهو كليم)\n(ومن يتهيض حبهن فؤاده ... يمت أو يعش ما عاش وهو سقيم)\n(كحران صاد ذيد عن برد مشرب ... وعن بللات الريق فهو يحوم)\nخبرني علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري قال\nأخبرنا محمد بن حبيب عن ابن أبي الدنيا العقيلي قال ابن حبيب وهو صاحب الكسائي وأصحابنا قال كان مزاحم العقيلي خطب ابنة عم له دنية فمنعه أهلها لإملاقه وقلة ماله وانتظروا بها رجلا موسرا في قومها كأن يذكرها ولم يحقق وهو يومئذ غائب فبلغ ذلك مزاحما من فعلهم فقال لعمه يا عم أتقطع رحمي وتختار علي غيري لفضل أباعر تجوزها وطفيف من الحظ تحظى به وقد علمت أني أقرب إليك من خاطبها الذي تريده وأفصح منه لسانا وأجود كفا وأمنع جانبا وأغنى عن العشيرة فقال له لا عليك فإنها إليك صائرة وإنما أعلل أمها بهذا ثم يكون أمرها لك فوثق به وأقاموا مدة ثم ارتحلوا ومزاحم غائب وعاد الرجل الخاطب لها فذاكروه أمرها فرغب فيها فأنكحوه إياها فبلغ ذلك مزاحما فأنشأ يقول\n(نزلت بمفضى سيل حرسين والضحى ... يسيل بأطراف المخارم آلها)\n(بمسقية الأجفان أنفذ دمعها ... مقاربة الألاف ثم زيالها)\n(فلما نهاها اليأس أن تونس الحمى ... حمى البئر جلى عبرة العين جالها)\n(أياليل إن تشحط بك الدار غربة ... سوانا ويعيي النفس فيك احتيالها)\n(فكم ثم كم من عبرة قد ردتها ... سريع على جيب القميص انهلالها)\n(خليلي هل من حيلة تعلمانها ... يقرب من ليلى إلينا احتيالها)\n(فإن بأعلى الأخشبين أراكة ... عدتني عنها الحرب دان ظلالها)\n(وفي فرعها لو تستطاع جنابها ... جنى يجتنبيه المجتني لو ينالها)\n(هنيئا لليلى مهجة ظفرت بها ... وتزويج ليلى حين حان ارتحالها)\n(فقد حبسوها محبس البدن وابتغى ... بها الربح أقوام تساخف مالها)\n(فإن مع الركب الذين تحملوا ... غمامة صيف زعزعتها شمالها)","topic":"أخبار مزاحم ونسبه","topicNo":249,"sp":0,"spl":"أخبار مزاحم ونسبه"},
{"id":"b249-2","bab":"الجزء 19","sec":"حبس طويلا ثم هرب من السجن","page":"ج19 ص107","text":"وقال محمد بن حبيب في خبره قال ابن الأعرابي وقع بين مزاحم العقيلي وبين رجل من بني جعدة لحاء في ماء فتشاتما وتضاربا بعصيهما فشجه مزاحم شجة أمته فاستعدت بنو جعدة على مزاحم فحبس حبسا طويلا ثم هرب من السجن فمكث في قومه مدة وعزل ذلك الوالي وولي غيره فسأله ابن عم لمزاحم يقال له مغلس أن يكتب أمانا لمزاحم فكتبه له وجاء مغلس والأمان معه فنفر مزاحم منه وظنها حيلة من السلطان فهرب وقال في ذلك\n(أتاني بقرطاس الأمير مغلس ... فأفزع قرطاس الأمير فؤاديا)\n(فقلت له لا مرحبا بك مرسلا ... إلي ولا لي من أميرك داعيا)\nأليست جبال القهر قعسا مكانها ... وعروى وأجبال الوحاف كما هيا أخاف ذنوبي أن تعد ببابه ... وما قد أزل الكاشحون أماميا ولا أستريم عقبة الأمر بعدما ... تورط في بهماء كعبي وساقيا\nخبرني محمد بن مزيد وأحمد بن جعفر جحظة قالا حدثنا حماد بن إسحاق عن أبيه قال كان مزاحم العقيلي يهوى امرأة من قومه يقال لها مية فتزوجت رجلا كان أقرب إليها من مزاحم فمر عليها بعد أن دخل بها زوجها فوقف عليها ثم قال\n(أيا شفتي مي أما من شريعة ... من الموت إلا أنتما توردانيا)\n(ويا شفتي مي أمالي إليكما ... سبيل وهذا الموت قد حل دانيا)\n(ويا شفتي مي أما تبذلان لي ... بشيء وإن أعطيت أهلي وماليا)\nقالت أعزز علي يا بن عم بأن تسأل ما لا سبيل إليه وهذا أمر قد حيل\nدونه فاله عنه فانصرف أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد النحوي قال حدثني عمارة بن عقيل قال قال لي أبي قال عبد الملك بن مروان لجرير يا أبا حرزة هل تحب أن يكون لك بشيء من شعرك شيء من شعر غيرك قال لا ما أحب ذلك إلا أن غلاما ينزل الروضات من بلاد بني عقيل يقال له مزاحم العقيلي يقول حسنا من الشعر لا يقدر أحد أن يقول مثله كنت أحب أن يكون لي بعض شعره مقايضة ببعض شعري أخبرني محمد بن الحسن بن دريد قال حدثني عمي عن العباس بن هشام عن أبيه قال كان مزاحم العقيلي يهوى امرأة من قومه يقال لها ليلى فغاب غيبة عن بلاده ثم عاد وقد زوجت فقال في ذلك\n(أتاني بظهر الغيب أن قد تزوجت ... فظلت بي الأرض الفضاء تدور)\n(وزايلني لبي وقد كان حاضرا ... وكاد جناني عند ذاك يطير)\n(فقلت وقد أيقنت أن ليس بيننا ... تلاق وعيني بالدموع تمور)\n(أيا سرعة الأخبار حين تزوجت ... فهل يأتيني بالطلاق بشير)\n(ولست بمحص حب ليلى لسائل ... من الناس إلا أن أقول كثير)\nصوت لها في سواد القلب تسعة أسهم ... وللناس طرا من هواي عشير\nقال ابن الكلبي ومن الناس من يزعم أن ليلى هذه التي يهواها مزاحم العقيلي هي التي كان يهواها المجنون وأنهما اجتمعا هو ومزاحم في حبها قال الأصبهاني وقد أخبرني بشرح هذا الخبر الحسن بن علي قال حدثنا عبد الله بن أبي سعد عن علي بن الصباح عن ابن الكلبي قال كان مزاحم بن مرة العقيلي يهوى امرأة من قشير يقال لها ليلى بنت موازر ويتحدث إليها مدة حتى شاع أمرهما وتحدثت جواري الحي به فنهاه أهلها عنها وكانوا متجاورين وشكوه إلى الأشياخ من قومه فنهوه واشتدوا عليه فكان يتفلت إليها في أوقات الغفلات فيتحدثان ويتشاكيان ثم انتجعت بنو قشير في ربيع لهم ناحية غير تلك قد نضرها غيث وأخصبها فبعد عليه خبرها واشتاقها فكان يسأل عنها كل وارد ويرسل إليها بالسلام مع كل صادر حتى ورد عليه يوما راكب من قومها فسأله عنها فأخبره أنها خطبت فزوجت فوجم طويلا ثم أجهش باكيا وقال\n(أتاني بظهر الغيب أن قد تزوجت ... فظلت بي الأرض الفضاء تدور)\nذكر الأبيات الماضية وقد أنشدني هذه القصيدة لمزاحم ابن أبي الأزهر عن حماد عن أبيه فأتى بهذه الأبيات وزاد فيها\n(وتنشر نفسي بعد موتي بذكرها ... مرارا فموت مرة ونشور)\n(عججت لربي عجة ما ملكتها ... وربي بذي الشوق الحزين بصير)\n(ليرحم ما ألقى ويعلم أنني ... له بالذي يسدي إلي شكور)\n(لئن كان يهدي برد أنيابها العلا ... لأحوج مني إنني لفقير)","topic":"أخبار مزاحم ونسبه","topicNo":249,"sp":1,"spl":"حبس طويلا ثم هرب من السجن"},
{"id":"b249-3","bab":"الجزء 19","sec":"مكانته عند الشعراء","page":"ج19 ص111","text":"حدثني عمي قال حدثني أبو أيوب المديني قال قال أبو عدنان أخبرنا تميم بن رافع قال حدثت أن الفرزدق دخل على عبد الملك بن مروان أو بعض بنيه فقال له يا فرزدق أتعرف أحدا أشعر منك قال لا إلا غلاما من بني عقيل يركب أعجاز الإبل وينعت الفلوات فيجيد ثم جاءه جرير فسأله عن مثل ما سأل عنه الفرزدق فأجابه بجوابه فلم يلبث أن جاءه ذو الرمة فقال له أنت أشعر الناس قال لا ولكن غلام من بني عقيل يقال له مزاحم يسكن الروضات يقول وحشيا من الشعر لا يقدر على مثله فقال فأنشدني بعض ما تحفظ من ذلك فأنشده قوله\n(خليلي عوجا بي على الدار نسأل ... متى عهدها بالظاعن المترحل)\n(فعجت وعاجوا فوق بيداء مورت ... بها الريح جولان التراب المنخل)\nتى أتى على آخرها ثم قال ما أعرف أحدا يقول قولا يواصل هذا\nصوت\n(أكذب طرفي عنك في كل ما أرى ... أسمع أذني منك ما ليس تسمع)\n(فلا كبدي تبلى ولا لك رحمة ... ولا عنك إقصار ولا فيك مطمع)\n(لقيت أمورا فيك لم ألق مثلها ... وأعظم منها فيك ما أتوقع)\n(فلا تسأليني في هواك زيادة ... فأيسره يجزي وأدناه يقنع)\nالشعر لبكر بن النطاح والغناء لحسين بن محرز ثقيل أول بالوسطى عن الهشامي","topic":"أخبار مزاحم ونسبه","topicNo":249,"sp":2,"spl":"مكانته عند الشعراء"},
{"id":"b250-1","bab":"الجزء 19","sec":"أخبار بكر بن النطاح ونسبه","page":"ج19 ص112","text":"بكر بن النطاح الحنفي يكنى أبا وائل هكذا أخبرنا وكيع عن عبد الله بن شبيب وذكر غيره أنه عجلي من بني سعد بن عجل واحتج من ذكر أنه عجلي بقوله\n(فإن يك جد القوم فهر بن مالك ... فجدي عجل قرم بكر بن وائل)\nأنكر ذلك من زعم أنه حنفي وقال بل قال\n(فجدي لجيم قرم بكر بن وائل ... )\nعجل بن لجيم وحنيفة بن لجيم أخوان وكان بكر بن النطاح صعلوكا يصيب الطريق ثم أقصر عن ذلك فجعله أبو دلف من الجند وجعل له رزقا سلطانيا وكان شجاعا بطلا فارسا شاعرا حسن الشعر والتصرف فيه كثير الوصف لنفسه بالشجاعة والإقدام","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":0,"spl":"أخبار بكر بن النطاح ونسبه — قصته مع أبي دلف والرشيد","partial":1},
{"id":"b250-2","bab":"الجزء 19","sec":"قصته مع أبي دلف والرشيد","page":"ج19 ص113","text":"فأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبي قال\nقال بكر بن النطاح الحنفي قصيدته التي يقول فيها\n(هنيئا لإخواني ببغذاد عيدهم ... وعيدي بحلوان قراع الكتائب)\nأنشدها أبا دلف فقال له إنك لتكثر الوصف لنفسك بالشجاعة وما رأيت لذلك عندك أثرا قط ولا فيك فقال له أيها الأمير وأي غناء يكون عند الرجل الحاسر الأعزل فقال أعطوه فرسا وسيفا وترسا ودرعا ورمحا فأعطوه ذلك أجمع فأخذه وركب الفرس وخرج على وجهه فلقيه مال لأبي دلف يحمل من بعض ضياعه فأخذه وخرج جماعة من غلمانه فمانعوه عنه فجرحهم جميعا وقطعهم وانهزموا وسار بالمال فلم ينزل إلا على عشرين فرسخا فلما اتصل خبره بأبي دلف قال نحن جنينا على أنفسنا وقد كنا أغنياء عن إهاجة أبي وائل ثم كتب إليه بالأمان وسوغه المال وكتب إليه صر إلينا فلا ذنب لك لأنا نحن كنا سبب فعلك بتحريكنا إياك وترحيضنا فرجع ولم يزل معه يمتدحه حتى مات أخبرني الحسن بن علي قال حدثني محمد بن موسى قال حدثني الحسن ابن إسماعيل عن ابن الحفصي قال قال يزيد بن مزيد وجه إلي الرشيد في وقت يرتاب فيه البرىء فلما مثلت بين يديه قال يا يزيد من الذي يقول\n(ومن يفتقر منا يعيش بحسامه ... ومن يفتقر من سائر الناس يسأل)\nفقلت له والذي شرفك وأكرمك بالخلافة ما أعرفه قال فمن الذي يقول\n(وإن يك جد القوم فهر بن مالك ... فجدي لجيم قرم بكر بن وائل)\nلت لا والذي أكرمك وشرفك يا أمير المؤمنين ما أعرفه قال والذي كرمني وشرفني إنك لتعرفه أتظن يا يزيد أني إذا أوطأتك بساطي وشرفتك بصنيعتي أني أحتملك على هذا أو تظن أني لا أراعي أمورك وأتقصاها وتحسب أنه يخفى على شيء منها والله إن عيوني لعليك في خلواتك ومشاهدك هذا جلف من أجلاف ربيعة عدا طوره وألحق قريشا بربيعة فأتني به فانصرفت وسألت عن قائل الشعر فقيل لي هو بكر بن النطاح وكان أحد أصحابي فدعوته وأعلمته ما كان من الرشيد فأمرت له بألفي درهم وأسقطت اسمه من الديوان وأمرته ألا يظهر ما دام الرشيد حيا فما ظهر حتى مات الرشيد فلما مات ظهر فألحقت اسمه وزدت في عطائه أخبرني محمد بن خلف وكيع قال حدثني محمد بن حمزة العلوي قال حدثني أبو غسان دماذ قال حضرت بكر بن النطاح الحنفي في منزل بعض الحنفيين وكانت للحنفي جارية يقال لها رامشنة فقال فيها بكر بن النطاح\n(حيتك بالرامشن رامشنة ... أحسن من رامشنة الآس)\n(جارية لم يقتسم بضعها ... ولم تبت في بيت نخاس)\n(أفسدت إنسانا على أهله ... يا مفسد الناس على الناس)\nقال فيها\n(أكذب طرفي عنك والطرف صادق ... وأسمع أذني منك ما ليس تسمع)\n(ولم أسكن الأرض التي تسكنينها ... لكي لا يقولوا صابر ليس يجزع)\n(فلا كبدي تبلى ولا لك رحمة ... ولا عنك إقصار ولا فيك مطمع)\n(لقيت أمورا فيك لم ألق مثلها ... وأعظم منها منك ما أتوقع)\n(فلا تسأليني في هواك زيادة ... فأيسره يجزي وأدناه يقنع)","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":0,"spl":"أخبار بكر بن النطاح ونسبه — قصته مع أبي دلف والرشيد"},
{"id":"b250-3","bab":"الجزء 19","sec":"المأمون يعطي رأيه بشعره وسلوكه","page":"ج19 ص116","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه عن علي ابن الصباح وأظنه مرسلا وأن بينه وبينه ابن أبي سعد أو غيره لأنه لم يسمع من علي بن الصباح قال حدثني أبو الحسين الرواية قال لي المأمون أنشدني أشجع بيت وأعفه وأكرمه من شعر المحدثين فأنشدته\n(ومن يفتقر منا يعش بحسامه ... ومن يفتقر من سائر الناس يسال)\n(وإنا لنلهو بالسيوف كما لهت ... عروس بعقد أوسخاب قرنفل)\nفقال ويحك من يقول هذا فقلت بكر بن النطاح فقال أحسن والله ولكنه قد كذب في وقوله فما باله يسأل أبا دلف ويمتدحه وينتجعه هلا أكل خبزه بسيفه كما قال أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أبو الحسن الكسكري قال\nبلغني أن أبا دلف لحق أكرادا قطعوا الطريق في عمله وقد أردف منهم فارس رفيقا له خلفه فطعنهما جميعا فأنفذهما فتحدث الناس بأنه نظم بطعنة واحدة فارسين على فرس فلما قدم من وجهه دخل إليه بكر بن النطاح فأنشده صوت\n(قالوا وينظم فارسين بطعنة ... يوم اللقاء ولا يراه جليلا)\n(لا تعجبوا فلو أن طول قناته ... ميل إذا نظم الفوارس ميلا)\nقال فأمر له أبو دلف بعشرة آلاف درهم فقال بكر فيه\n(له راحة لو أن معشار جودها ... على البركان البر أندى من البحر)\n(ولو أن خلق الله في جسم فارس ... وبارزه كان الخلي من العمر)\n(أبا دلف بوركت في كل بلدة ... كما بوركت في شهرها ليلة القدر)\nخبرني أحمد بن عبيد الله بن عمار وعيسى بن الحسين قالا حدثنا يعقوب بن إسرائيل قال حدثني أبو زائدة قال كان بكر بن النطاح الحنفي يتعشق غلاما نصرانيا ويجن به وفيه يقول\n(يا من إذا درس الإنجيل كان له ... قلب التقي عن القرآن منصرفا)\n(إني رأيتك في نومي تعانقني ... كما تعانق لام الكاتب الألفا)\nخبرني محمد بن القاسم الأنباري قال حدثني الحسن بن عبد الرحمن الربعي قال كان بكر بن النطاح يأتي أبا دلف في كل سنة فيقول له إلى جنب أرضي أرض تباع وليس يحضرني ثمنها فيأمر له بخمسة آلاف درهم ويعطيه ألفا لنفقته\nفجاءه في بعض السنين فقال له مثل ذلك فقال له أبو دلف ما تفنى هذه الأرضون التي إلى جانب ضيعتك فغضب وانصرف عنه وقال\n(يا نفس لا تجزعي من التلف ... فإن في الله أعظم الخلف)\n(إن تقنعي باليسير تغتبطي ... ويغنك الله عن أبي دلف)\nال وكان بكر بن النطاح يأتي قرة بن محرز الحنفي بكرمان فيعطيه عشرة آلاف درهم ويجري عليه في كل شهر يقيم عنده ألف درهم فاجتاز به قرة يوما وهو ملازم في السوق وغرماؤه يطالبونه بدين فقال له ويحك أما يكفيك ما أعطيك حتى تستدين وتلازم في السوق فغضب عليه وانصرف عنه وأنشأ يقول\n(ألا يا قر لاتك سامريا ... فتترك من يزورك في جهاد)\n(أتعجب أن رأيت علي دينا ... وقد أودى الطريف مع التلاد)\n(ملأت يدي من الدنيا مرارا ... فما طمع العواذل في اقتصادي)\n(ولا وجبت علي زكاة مال ... وهل تجب الزكاة على جواد)\nخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال كنت يوما عند علي بن هشام وعنده جماعة فيهم عمارة بن عقيل فحدثته أن بكر بن النطاح دخل إلى أبي دلف وأنا عنده فقال لي أبو دلف يا أبا محمد أنشدني مديحا فاخرا تستطرفه فبدر إليه بكر وقال أنا أنشدك أيها الأمير بيتين\nقلتهما فيك طريقي هذا إليك وأحكمك فقال هات فإن شهد لك أبو محمد رضينا فأنشده\n(إذا كان الشتاء فأنت شمس ... وإن حضر المصيف فأنت ظل)\n(وما تدري إذا أعطيت مالا ... أتكثر في سماحك أم تقل)\nفقلت له أحسن والله ما شاء ووجبت مكافأته فقال أما إذ رضيت فأعطوه عشرة آلاف درهم فحملت إليه وانصرفت إلى منزلي فإذا أنا بعشرين ألفا قد سبقت إلي وجه بها أبو دلف قال فقال عمارة لعلي بن هشام فقد قلت أنا في قريب من هذه القصة\n(ولا غيب فيهم غير أن أكفهم ... لأموالهم مثل السنين الحواطم)\n(وأنهم لا يورثون بذيهم ... وإن ورثوا خيرا كنوز الدراهم)","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":1,"spl":"المأمون يعطي رأيه بشعره وسلوكه"},
{"id":"b250-4","bab":"الجزء 19","sec":"ابن النطاح يرثي معقل بن عيسى","page":"ج19 ص119","text":"أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني أبو توبة قال كان معقل بن عيسى صديقا لبكر بن النطاح وكان بكر فاتكا صعلوكا فكان لا يزال قد أحدث حادثة في عمل أبي دلف أو جنى جناية فيهم به فيقوم دونه معقل حتى يتخلصه فمات معقل فقال بكر بن النطاح يرثيه بقوله\n(وحدث عنه بعض من قال إنه ... رأت عينه فيما ترى عين حالم)\n(كأن الذي يبكي على قبر معقل ... ولم يره يبكي على قبر حاتم)\n(ولا قبر كعب إذ يجود بنفسه ... ولا قبر حلف الجود قيس بن عاصم)\n(فأيقنت أن الله فضل معقلا ... على كل مذكور بفضل المكارم)\nأخبرني عمي قال حدثنا الكراني قال حدثني العمري قال كان بكر بن النطاح الحنفي أبو وائل بخيلا فدخل عليه عباد بن الممزق يوما فقدم إليه خبزا يابسا قليلا بلا أدم ورفعه من بين يديه قبل أن يشبع فقال عباد يهجوه\n(من يشتري مني أبا وائل ... بكر بن نطاح بفلسين)\n(كأنما الآكل من خبزه ... يأكله من شحمه العين)\nال وكان عباد هذا هجاء ملعونا وهو القائل\n(أنا الممزق أعراض اللئام كما ... كان الممزق أعراض اللئام أبي)\nأخبرني عمي قال حدثنا أبو هفان قال كان بكر بن النطاح قصد مالك بن طوق فمدحه فلم يرض ثوابه فخرج من عنده وقال يهجوه\n(فليت جدا مالك كله ... وما يرتجى منه من مطلب)\n(أصبت بأضعاف أضعافه ... ولم أنتجعه ولم أرغب)\n(أسأت أختياري منك الثواب ... لي الذنب جهلا ولم تذنب)\nكتبها في رقعة وبعث إليه فلما قرأها وجه جماعة من أصحابه في طلبه\nوقال لهم الويل لكم إن فاتكم بكر بن النطاح ولا بد أن تنكفئوا على أثره ولو صار إلى الجبل فلحقوه فردوه إليه فلما دخل داره ونظر إليه قام فتلقاه وقال يا أخي عجلت علينا وما كنا نقتصر بك على ما سلف وإنما بعثنا إليك بنفعه وعولنا بك على ما يتلوها واعتذر كل واحد منهما إلى صاحبه ثم أعطاه حتى أرضاه فقال بكر بن النطاح يمدحه\n(أقول لمرتاد ندى غير مالك ... كفى بذل هذا الخلق بعض عداته)\n(فتى جاد بالأموال في كل جانب ... وأنهبها في عوده وبداته)\n(فلو خذلت أمواله بذل كفه ... لقاسم من يرجوه شطر حياته)\n(ولو لم يجد في العمر قسمة ماله ... وجاز له الإعطاء من حسناته)\n(لجاد بها من غير كفر بربه ... وشاركهم في صومه وصلاته)\nوصله صلة ثانية لهذه الأبيات وانصرف عنه راضيا هكذا ذكر أبو هفان في خبره وأحسبه غلطا لأن أكثر مدائح بكر بن النطاح في مالك بن علي الخزاعي وكان يتولى طريق خراسان وصار إليه بكر بن النطاح بعد وفاة أبي دلف ومدحه فأحسن تقبله وجعله في جنده وأسنى له الرزق فكان معه إلى أن قتله الشراة بحلوان فرشاه بكر بعدة قصائد هي من غرر شعره وعيونه","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":2,"spl":"ابن النطاح يرثي معقل بن عيسى"},
{"id":"b250-5","bab":"الجزء 19","sec":"ابن النطاح يرثي مالك الخزاعي","page":"ج19 ص121","text":"فحدثني عمي قال حدثني أحمد بن أبي طاهر عن أبي وائلة السدوسي قال عاثت الشراة بالجبل عيثا شديدا وقتلوا الرجال والنساء والصبيان فخرج إليهم مالك بن علي الخزاعي وقد وردوا حلوان فقاتلهم قتالا شديدا فهزمهم\nعنها وما زال يتبعهم حتى بلغ بهم قرية يقال لها حدان فقاتلوه عندها قتالا شديدا وثبت الفريقان إلى الليل حتى حجز بينهم وأصابت مالكا ضربة على رأسه أثبتته وعلم أنه ميت فأمر برده إلى حلوان فما بلغها حتى مات فدفن على باب حلوان وبنيت لقبره قبة على قارعة الطريق وكان معه بكر بن النطاح يومئذ فأبلى بلاء حسنا وقال بكر يرثيه\n(يا عين جودي بالدموع السجام ... على الأمير اليمني الهمام)\n(على فتى الدنيا وصنديدها ... وفارس الدين وسيف الإمام)\n(لا تدخري الدمع على هالك ... أيتم إذ أودى جميع الأنام)\n(طاب ثرى حلوان إذ ضمنت ... عظامه سقيا لها من عظام)\n(أغلقت الخيرات أبوابها ... وامتنعت بعدك يا بن الكرام)\n(أغلقت الخيرات أبوبها ... وامتنعت بعدك يا بن الكرام)\n(وأصبحت خيلك بعد الوجا ... والغزو تشكو منك طول الجمام)\n(ارحل بنا نقرب إلى مالك ... كيما نحيي قبره بالسلام)\n(كان لأهل الأرض في كفه ... غنى عن البحر وصوب الغمام)\n(وكان في الصبح كشمس الضحى ... وكان في الليل كبدر الظلام)\n(وسائل يعجب من موته ... وقد رآه وهو صعب المرام)\n(قلت له عهدي به معلما ... يضربهم عند ارتفاع القتام)\n(والحرب من طاولها لم يكد ... يفلت من وقع صقيل حسام)\n(لم ينظر الدهر لنا إذ عدا ... على ربيع الناس في كل عام)\n(لن يستقيلوا أبدا فقده ... ما هيج الشجو دعاء الحمام)\nال وقال أيضا يرثيه\n(أي امرىء خضب الخوارج ثوبه ... بدم عشية راح من حلوان)\n(يا حفرة ضمت محاسن مالك ... ما فيك من كرم ومن إحسان)\n(لهفي على البطل المعرض خده ... وجبينه لأسنة الفرسان)\n(خرق الكتيبة معلما متكنبا ... والمرهفات عليه كالنيران)\n(ذهبت بشاشة كل شيء بعده ... فالأرض موحشة فلا عمران)\n(هدم الشراة غداة مصرع مالك ... شرف العلا ومكارم البنيان)\n(قتلوا فتى العرب الذي كانت به ... تقوى على اللزبات في الأزمان)\n(حرموا معدا ما لديه وأوقعوا ... عصبية في قلب كل يماني)\n(تركوه في رهج العجاج كأنه ... أسد يصول بساعد وبنان)\n(هوت الجدود عن السعود لفقده ... وتمسكت بالنحس والدبران)\n(لا يبعدن أخو خزاعة إذ ثوى ... مستشهدا في طاعة الرحمن)\n(عز الغواة به وذلت أمة ... محبوة بحقائق الإيمان)\n(وبكاه مصحفة وصدر قناته ... والمسلمون ودولة السلطان)\n(وغدت تعقر خيله وتقسمت ... أدراعه وسوابغ الأبدان)\n(أفتحمد الدنيا وقد ذهبت بمن ... كان المجير لنا من الحدثان)","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":3,"spl":"ابن النطاح يرثي مالك الخزاعي"},
{"id":"b250-6","bab":"الجزء 19","sec":"تشوقه بغداد وهو بالجبل","page":"ج19 ص124","text":"أخبرني هاشم بن محمد الخزاعي قال أنشدني أبو غسان دماذ لبكر بن النطاح يتشوق بغداد وهو بالجبل يومئذ\n(نسيم المدام وبرد السحر ... هما هيجا الشوق حتى ظهر)\n(تقول اجتنب دارنا بالنهار ... وزرنا إذا غاب ضوء القمر)\n(فإن لنا حرسا إن رأوك ... ندمت وأعطوا عليك الظفر)\n(وكم صنع الله بغداد من بلدة ... وساكن بغداد صوب المطر)\n(ونبئت أن جواري القصور ... صيرن ذكري حديث السمر)\n(ألا رب سائلة بالعراق ... عني وأخرى تطيل الذكر)\n(تقول عهدنا أبا وائل ... كظبي الفلاة المليح الحور)\n(ليالي كنت أزور القيان ... كأن ثيابي بهار الشجر)\nدثني جعفر بن قدامة قال حدثني ميمون بن هارون قال كان بكر بن النطاح يهوى جارية من جواري القيان وتهواه وكانت لبعض الهاشميين يقال لها درة وهو يذكرها في شعره كثيرا وكان يجتمع معها في منزل رجل من الجند من أصحاب أبي دلف يقال له الفرز فسعى به إلى مولاها وأعلمه أنه قد أفسدها وواطأها على أن تهرب معه إلى الجبل فمنعه من لقائها\nوحجبه عنها إلى أن خرج الكرج مع أبي دلف فقال بكر بن النطاح في ذلك\n(أهل دار بين الرصافة والجسر ... أطالوا غيظي بطول الصدود)\n(عذبوني ببعدهم وابتلوا قلبي ... بحزنين طارف وتليد)\n(ما تهب الشمال إلا تنفت ... وقال الفؤاد للعين جودي)\n(قل عنهم صبري ولم يرحموني ... فتحيرت كالطريد الشريد)\n(وكلتني الأيام فيك إلى نفسي ... فأعييت وانتهى مجهودي)\nقال فيها أيضا وفيه غناء من الرمل الطنبوري\n(العين تبدي الحب والبغضا ... وتظهر الإبرام والنقضا)\n(درة ما أنصفتني في الهوى ... ولا رحمت الجسد المنضى)\n(مرت بنا في قرطق أخضر ... يعشق منها بعضها بعضا)\n(غضبى ولا والله يا أهلها ... لا أشرب البارد أو ترضى)\n(كيف أطاعتكم بهجري وقد ... جعلت خدي لها أرضا)\nقال فيها أيضا وفيه رمل طنبوري\n(صدت فأمسى لقاؤها حلما ... واستبدل الطرف بالدموع دما)\n(وسلطت حبها على كبدي ... فأبدلتني بصحة سقما)\n(وصرت فردا أبكي لفرقتها ... وأقرع السن بعدها ندما)\n(شق عليها قول الوشاة لها ... أصبحت في أمر ذا الفتى علما)\n(ولولا شقائي وما بليت به ... من هجرها ما استثرت ما اكتتما)\n(كم حاجة في الكتاب بحت بها ... أبكيت منها القرطاس والقلما)\nقال فيها أيضا وفيه رمل لأبي الحسن أحمد بن جعفر جحظة\n(بعدت عني فتغيرت لي ... وليس عندي لك تغيير)\n(فجددي ما رث من وصلنا ... وكل ذنب لك مغفور)\n(أطيب النفس بكتمان ما ... سارت به من غدوك العير)\n(وعدك يا سيدتي غرني ... منك ومن يعشق مغرور)\n(يحزنني علمي بنفسي إذا ... قال خليلي أنت مهجور)\n(ياليت من زين هذا لها ... جارت لنا فيه المقادير)\n(ساقي الندامى سقها صاحبي ... فإنني ويحك معذور)\n(أأشرب الخمر على هجرها ... إني إذا بالهجر مسرور)\nفيها يقول وقد خرج مع أبي دلف إلىأصبهان\n(يا ظبية السيب التي أحببتها ... ومنحتها لطفي ولين جناحي)\n(عيناي باكيتان بعدك للذي ... أودعت قلبي من ندوب جراح)\n(سقيا لأحمد من أخ ولقاسم ... فقدا غدوي لاهيا ورواحي)\n(وترددي من بيت فرز آمنا ... من قرب كل مخالف وملاحي)\n(أيام تغبطني الملوك ولا أرى ... أحدا له كتدللي ومراحي)\n(تصف القيان إذا خلون مجانتي ... ويصفن للشرب الكرام سماحي)\nمما يغنى فيه من شعر بكر بن النطاح في هذه الجارية قوله صوت\n(هل يبتلى أحد بمثل بليتي ... أم ليس لي في العالمين ضريب)\n(قالت عنان وأبصرتني شاحبا ... يا بكر مالك قد علاك شحوب)\n(فأجبتها يا أخت لم يلق الذي ... لاقيت إلا المبتلى أيوب)\n(قد كنت أسمع بالهوى فأظنه ... شيئا يلذ لأهله ويطيب)\n(حتى ابتليت بحلوه وبمره ... فالحلو منه للقلوب مذيب)\n(والمر يعجز منطقي عن وصفه ... للمر وصف يا عنان عجيب)\n(فأنا الشقي بحلوه وبمره ... وأنا المعنى الهائم المكروب)\n(يا در حالفك الجمال فماله ... في وجه إنسان سواك نصيب)\n(كل الوجوه تشابهت وبهرتها ... حسنا فوجهك في الوجوه غريب)\n(والشمس يغرب في الحجاب ضياؤها ... عنا ويشرق وجهك المحجوب)\nومما يغنى فيه من شعره فيها أيضا\n(غضب الحبيب علي في حبي له ... نفسي الفداء لمذنب غضبان)\n(مالي بما ذكر الرسول يدان بل ... إن تم رأيك ذا خلعت عناني)\n(يا من يتوق إلى حبيب مذنب ... طاوعته فجزاك بالعصيان)\n(هلا انتحرت فكنت أول هالك ... إن لم يكن لك بالصدود يدان)","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":4,"spl":"تشوقه بغداد وهو بالجبل"},
{"id":"b250-7","bab":"الجزء 19","sec":"تشوقه بغداد وهو بالجبل","page":"ج19 ص124","text":"(كنا وكنتم كالبنان وكفها ... فالكف مفردة بغير بنان)\n(خلق السرور لمعشر خلقوا له ... وخلقت للعبرات والأحزان)\nوت\n(ليت شعري أأول الهرج هذا ... أم زمان من فتنة غير هرج)\n(إن يعش مصعب فنحن بخير ... قد أتانا من عيشنا ما نرجي)\n(ملك يطعم الطعام ويسقي ... لبن البخت في عساس الخلنج)\n(جلب الخيل من تهامة حتى ... بلغت خيله قصور زرنج)\n(حيث لم تأت قبله خيل ذي الأعتاف ... يوجفن بين قف ومرج)\nروضه من الخفيف الشعر لعبيد الله بن قيس الرقيات والغناء ليونس الكاتب ماخوري بالبنصر وفيه لمالك ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":5,"spl":"تشوقه بغداد وهو بالجبل — مقتل مصعب بن الزبير"},
{"id":"b250-8","bab":"الجزء 19","sec":"مقتل مصعب بن الزبير","page":"ج19 ص129","text":"وهذا الشعر يقوله عبيد الله بن قيس لمصعب بن الزبير لما حشد للخروج عن الكوفة لمحاربة عبد الملك بن مروان وكان السبب في ذلك فيما أجاز لنا الحرمي بن أبي العلاء روايته عنه عن الزبير بن بكار عن المدائني قال لما كانت سنة اثنتين وسبعين استشار عبد الملك بن مروان عبد الرحمن ابن الحكم في المسير إلى العراق ومناجزة مصعب فقال يا أمير المؤمنين قد واليت بين عامين تغزو فيهما وقد خسرت خيلك ورجالك وعامك هذا عام حارد فأرح نفسك ورجلك ثم ترى رأيك فقال إني أبادر ثلاثة أشياء وهي أن الشام أرض بها المال قليل فأخاف أن ينفد ما عندي وأشراف أهل العراق قد كاتبوني يدعونني إلى أنفسهم وثلاثة من أصحاب رسول الله كبروا ونفدت\nأعمارهم وأنا أبادر بهم الموت أحب أن يحضروا معي ثم دعا يحي بن الحكم وكان يقول من أراد أمرا فليشاور يحي بن الحكم فإذا أشار عليه بأمر فليعمل بخلافه فقال ما ترى في المسير إلى العراق قال أرى أن ترضى بالشام وتقيم بها وتدع مصعبا بالعراق فلعن الله العراق فضحك عبد الملك ودعا عبد الله بن خالد بن أسيد فشاوره فقال يا أمير المؤمنين قد غزوت مرة فنصرك الله ثم غزوت ثانية فزادك الله بها عزا فأقم عامك هذا فقال لمحمد بن مروان ما ترى قال أرجو أن ينصرك الله أقمت أم غزوت فشمر فإن الله ناصرك فأمر الناس فاستعدوا للمسير فلما أجمع عليه قالت عاتكة بنت يزيد بن معاوية زوجته يا أمير المؤمنين وجه الجنود وأقم فليس الرأي أن يباشر الخليفة الحرب بنفسه فقال لو وجهت أهل الشام كلهم فعلم مصعب أني لست معهم لهلك الجيش كله ثم تمثل\n(ومستخبر عنا يريد بنا الردى ... ومستخبرات والعيون سواكب)\nم قدم محمد بن مروان ومعه عبد الله بن خالد بن أسيد وبشر بن مروان ونادى مناديه إن أمير المؤمنين قد استعمل عليكم سيد الناس محمد بن مروان وبلغ مصعب بن الزبير مسير عبد الملك فأراد الخروج فأبى عليه أهل البصرة\nوقالوا عدونا مطل علينا يعنون الخوارج فأرسل إليهم بالمهلب وهو بالموصل وكان عامله عليها فولاه قتال الخوارج وخرج مصعب فقال بعض الشعراء\n(أكل عام لك باجميرا ... تغزو بنا ولا تفيد خيرا)","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":5,"spl":"تشوقه بغداد وهو بالجبل — مقتل مصعب بن الزبير"},
{"id":"b250-9","bab":"الجزء 19","sec":"مصعب وعبد الملك","page":"ج19 ص131","text":"قال وكان مصعب كثيرا ما يخرج إلى باجميرا يريد الشام ثم يرجع فأقبل عبد الملك حتى نزل الأخنونيه ونزل مصعب بمسكن إلى جنب أوانا وخندق خندقا ثم تحول ونزل دير الجاثليق وهو بمسكن وبين العسكرين ثلاثة فراسخ ويقال فرسخان فقدم عبد الملك محمدا وبشرا أخويه وكل واحد منهما على جيش والأمير محمد وقدم مصعب إبراهيم بن الأشتر ثم كتب عبد الملك إلى أشراف أهل الكوفة والبصرة يدعوهم إلى نفسه ويمنيهم فأجابوه وشرطوا عليه شروطا وسألوه ولايات وسأله ولاية أصبهان أربعون رجلا منهم فقال عبد\nالملك لمن حضره ويحكم ما أصبهان هذه تعجبا ممن يطلبها وكتب إلى إبراهيم بن الأشتر لك ولاية ما سقى الفرات إن تبعتني فجاء إبراهيم بالكتاب إلى مصعب فقال هذا كتاب عبد الملك ولم يخصصني بهذا دون غيري من نظرائي ثم قال فأطعني فيهم قال أصنع ماذا قال تدعوهم فتضرب أعناقهم قال أقتلهم على ظن ظننته قال فأوقرهم حديدا وابعث بهم إلى أرض المدائن حتى تنقضي الحرب قال إذا تفسد قلوب عشائرهم ويقول الناس عبث مصعب بأصحابه قال فإن لم تفعل فلا تمدني بهم فإنهم كالمومسة تريد كل يوم خليلا وهم يريدون كل يوم أميرا أرسل عبد الملك إلى مصعب رجلا يدعوه إلى أن يجعل الأمر شورى في الخلافة فأبى مصعب فقدم عبد الملك أخاه محمدا ثم قال اللهم انصر محمدا ثلاثا ثم قال اللهم أنصر أصلحنا وخيرنا لهذه الأمة قال وقدم مصعب إبراهيم بن الأشتر فالتقت المقدمتان وبين عسكر مصعب وعسكر ابن الأشتر فرسخ ودنا عبد الملك حتى قرب من عسكر محمد فتناوشوا فقتل رجل على مقدمة محمد يقال له فراس وقتل صاحب لواء بشر وكان يقال له أسيد فأرسل محمد إلى عبد الملك أن بشرا قد ضيع لواءه فصرف عبد الملك الأمر كله إلى محمد وكف الناس وتواقفوا وجعل أصحاب ابن الأشتر يهمون بالحرب ومحمد بن مروان يكف أصحابه فأرسل عبد الملك إلى محمد ناجزهم فأبى فأوفد إليه رسولا آخر وشتمه فأمر محمد رجلا فقال له قف خلفي في ناس من أصحابك فلا تدعن أحدا يأتيني من قبل عبد الملك وكان قد دبر تدبيرا سديدا في تأخير المناجزة إلى وقت رآه فكره أن يفسد عبد الملك تدبيره عليه فوجه إليه عبد الملك عبد الله بن خالد بن أسيد فلما رأوه أرسلوا إلى محمد بن مروان هذا عبد الله بن خالد بن أسيد فقال ردوه بأشد مما رددتم من جاء قبله فلما قرب المساء أمر محمد بن مروان أصحابه بالحرب وقال حركوهم قليلا فتهايج\nالناس ووجه مصعب عتاب بن ورقاء الرياحي يعجز إبراهيم فقال له قد قلت لا تمدني بأحد من أهل العراق فلم يقبل واقتتلوا وأرسل إبراهيم بن الأشتر إلى أصحابه بحضرة الرسول ليرى خلاف أهل العراق عليه في رأيه ألا تنصرفوا عن الحرب حتى ينصرف أهل الشام عنكم فقالوا ولم لا ننصرف فانصرفوا وانهزم الناس حتى أتوا مصعبا وصبر إبراهيم بن الأشتر فقاتل حتى قتل فلما أصبحوا أمر محمد بن مروان رجلا فقال انطلق إلى عسكر مصعب فانظر كيف تراهم بعد قتل ابن الأشتر قال لا أعرف موضع عسكرهم فقال له إبراهيم ابن عدي الكناني انطلق فإذا رأيت النخل فاجعله منك موضع سيفك فمضى الرجل حتى أتى عسكر مصعب ثم رجع إلى محمد فقال رأيتهم منكسرين وأصبح مصعب فدنا منه ودنا محمد بن مروان حتى التقوا فترك قوم من أصحاب مصعب مصعبا وأتوا محمد بن مروان فدنا إلى مصعب ثم ناداه فداك أبي وأمي إن القوم خاذلوك ولك الأمان فأبى قبول ذلك فدعا محمد بن مروان ابنه عيسى ابن مصعب فقال له أبوه انظر ما يريد محمد فدنا منه فقال له إني لكم ناصح إن القوم خاذلوكم ولك ولأبيك الأمان وناشده فرجع إلى أبيه فأخبره فقال إني أظن القوم سيفون فإن أحببت أن تأتيهم فأتهم فقال والله لا تتحدث نساء قريش أني خذلتك ورغبت بنفسي عنك قال فتقدم حتى أحتسبك فتقدم وتقدم ناس معه فقتل وقتلوا وترك أهل العراق مصعبا حتى بقي في سبعة","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":6,"spl":"مصعب وعبد الملك"},
{"id":"b250-10","bab":"الجزء 19","sec":"مقتل مصعب","page":"ج19 ص133","text":"وجاء رجل من أهل الشام ليحتز رأس عيسى فشد عليه مصعب فقتله ثم شد على الناس فانفرجوا ثم رجع فقعد على مرفقة ديباج ثم جعل يقوم عنها\nويحمل على أهل الشأم فيفرجون عنه ثم يرجع فيقعد على المرفقة حتى فعل ذلك مرارا وأتاه عبيد الله بن زياد بن ظبيان فدعاه إلى المبارزة فقال له أعزب يا كلب وشد عليه مصعب فضربه على البيضة فهشمها وجرحه فرجع عبيد الله فعصب رأسه وجاء ابن أبي فروة كاتب مصعب فقال له جعلت فداك قد تركك القوم وعندي خيل مضمرة فاركبها وانج بنفسك فدفع في صدره وقال ليس أخوك بالعبد ورجع ابن ظبيان إلى مصعب فحمل عليه وزرق زائدة بن قدامة مصعبا ونادى يا لثارات المختار فصرعه وقال عبيد الله لغلام له احتز رأسه فنزل فاحتز رأسه فحمله إلى عبد الملك فقال إنه لما وضعه بين يديه سجد قال ابن ظبيان فهممت والله أن أقتله فأكون أفتك العرب قتلت ملكين من قريش في يوم واحد ثم وجدت نفسي تنازعني إلى الحياة فأمسكت قال وقال يزيد بن الرقاع العاملي أخو عدي بن الرقاع وكان شاعر أهل الشام\n(نحن قتلنا ابن الحواري مصعبا ... أخا أسد والمذحجي اليمانيا)\nعني ابن الأشتر قال\n(ومرت عقاب الموت منا بمسلم ... فأهوت له ظفرا فأصبح ثاويا)\nال الزبير ويروى هذا الشعر للبعيث اليشكري ومسلم الذي عناه هو مسلم بن عمرو الباهلي","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":7,"spl":"مقتل مصعب — مصعب وسكينة بنت الحسين"},
{"id":"b250-11","bab":"الجزء 19","sec":"مقتل مسلم بن عمرو الباهلي","page":"ج19 ص135","text":"حدثنا محمد بن العباس اليزيدي قال حدثنا سليمان بن أبي شيخ قال حدثنا محمد بن الحكم عن عوانة قال كان مسلم بن عمرو الباهلي على ميسرة إبراهيم بن الأشتر فطعن وسقط فارثت فلما قتل مصعب أرسل إلى خالد بن يزيد بن معاوية أن يطلب له الأمان من عبد الملك فأرسل إليه ما تصنع بالأمان وأنت بالموت قال ليسلم لي مالي ويأمن ولدي قال فحمل على سرير فأدخل على عبد الملك بن مروان فقال عبد الملك لأهل الشام هذا أكفر الناس لمعروف ويحك أكفرت معروف يزيد بن معاوية عندك فقال له خالد تؤمنه يا أمير المؤمنين فأمنه ثم حمل فلم يبرح الصحن حتى مات فقال الشاعر\n(نحن قتلنا ابن الحواري مصعبا ... أخا أسد والمذحجي اليمانيا)\nدثنا محمد بن العباس قال حدثنا أحمد بن الحارث الخراز عن المدائني قال قال رجل لعبيد الله بن زياد بن ظبيان بماذا تحتج عند الله عز و جل من قتلك لمصعب قال إن تركت أحتج رجوت أن أكون أخطب من صعصعة بن صوحان","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":7,"spl":"مقتل مصعب — مصعب وسكينة بنت الحسين"},
{"id":"b250-12","bab":"الجزء 19","sec":"مصعب وسكينة بنت الحسين","page":"ج19 ص136","text":"وقال مصعب الزبيري في خبره قال الماجشون فلما كان يوم قتل مصعب دخل إلى سكينة بنت الحسين عليهما السلام فنزع عنه ثيابه ولبس غلالة وتوشح بثوب وأخذ سيفه فعلمت سكينة أنه لا يريد أن يرجع فصاحت من خلفه واحزناه عليك يا مصعب فالتفت إليها وقد كانت تخفي ما في قلبها منه فقال أوكل هذا لي في قلبك فقالت أي والله وما كنت أخفي أكثر فقال لو كنت أعلم أن هذا كله لي عندك لكانت لي ولك حال ثم خرج ولم يرجع قال مصعب وحدثني مصعب بن عثمان أن مصعب بن الزبير لما قدمت عليه سكينة أعطى أخاها علي بن الحسين عليهم السلام وهو كان حملها إليه أربعين ألف دينار قال مصعب وحدثني معاوية بن بكر الباهلي قال قالت سكينة دخلت على مصعب وأنا أحسن من النار الموقدة قال وكانت قد ولدت منه بنتا فقال لها سميها زبراء فقالت بل أسميها باسم بعض أمهاتي فسمتها الرباب قال فحدثني محمد بن سلام عن شعيب بن صخر عن أمه سعدة بنت\nعبد الله بن سالم قالت لقيت سكينة بنت الحسين بين مكة ومنى فقالت قفي يا بنت عبد الله ثم كشفت عن ابنتها فإذا هي قد أثقلتها باللؤلؤ فقالت والله ما ألبستها إياه إلا لتفضحه قال فلما قتل مصعب ولي أمر ماله عروة بن الزبير فزوج ابنه عثمان بن عروة ابنة أخيه من سكينة وهي صغيرة فماتت قبل أن تبلغ فورث عثمان بن عروة منها عشرة آلاف دينار قال ولما دخلت سكينة الكوفة بعد قتل مصعب خطبها عبد الملك فقالت والله لا يتزوجني بعده قاتله أبدا وتزوجت عبد الله بن عثمان بن عبد الله بن حكيم بن حزام ودخلت بينها وبينه رملة بنت الزبير أخت مصعب حتى تزوجها خوفا من أن تصير إلى عبد الملك فولدت منه ابنا فسمته عثمان وهو الذي يلقب بقرين وربيحه ابني عبد الله بن عثمان فتزوج ربيخة العباس بن الوليد بن عبد الملك","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":7,"spl":"مقتل مصعب — مصعب وسكينة بنت الحسين"},
{"id":"b250-13","bab":"الجزء 19","sec":"ابن قيس الرقيات يرثي مصعبا","page":"ج19 ص137","text":"ثم مات عبد الله بن عثمان عنها فتزوجها زيد بن عمرو بن عثمان بن عفان فقال عبيد الله بن قيس الرقيات يرثي مصعبا صوت\n(إن الرزية يوم مسكن ... والمصيبة والفجيعه)\n(يابن الحواري الذي ... لم يعده يوم الوقيعه)\n(غدرت به مضر العراق ... وأمكنت منه ربيعه)\n(تالله لو كانت له ... بالدير يوم الدير شيعه)\n(لوجدتموه حين يدلج ... لا يعرس بالمضيعه)\nغناه يونس الكاتب من كتابه ولحنه خفيف رمل بالوسطى وفيه لموسى شهوات خفيف رمل بالبنصر عن حبش وقيل بل هو هذا اللحن وغلط من نسبه إلى موسى وقال عدي بن الرقاع العاملي يذكر مقتله\n(لعمري لقد أصحرت خيلنا ... بأكناف دجلة للمصعب)\n(يهزون كل طويل القناة ... معتدل النصل والثعلب)\n(فداؤك أمي وأبناؤها ... وإن شئت زدت عليهم أبي)\n(وما قلتها رهبة إنما ... يحل العقاب على المذنب)\n(إذا شئت دافعت مستقتلا ... أزاحم كالجمل الأجرب)\n(فمن يك منا يبت آمنا ... ومن يك من غيرنا يهرب)\nناه معبد من رواية إسحاق ثاني ثقيل بالسبابة في مجرى الوسطى\nوقال ابن قيس يرثي مصعبا\n(لقد أورث المصرين خزيا وذلة ... قتيل بدير الجاثليق مقيم)\n(فما قاتلت في الله بكربن وائل ... ولا صبرت عند اللقاء تميم)\n(ولكنه رام القيام ولم يكن ... لها مضري يوم ذاك كريم)","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":8,"spl":"ابن قيس الرقيات يرثي مصعبا — مصعب يسأل عن قتل الحسين"},
{"id":"b250-14","bab":"الجزء 19","sec":"مصعب يسأل عن قتل الحسين","page":"ج19 ص139","text":"قال الزبير وكان مصعب لما قدم الكوفة يسأل عن الحسين بن علي عليهما السلام وعن قتله فجعل عروة بن المغيرة يحدثه عن ذلك فقال متمثلابقول سليمان بن قتة\n(فإن الألى بالطف من آل هاشم ... تأسوا فسنوا للكرام التأسيا)\nال عروة فعلمت أن مصعبا لا يفر أبدا قال الزبير وقال أبو الحكم بن خلاد بن قرة السدوسي حدثني أبي قال لما كان يوم السبخة حين عسكر الحجاج بإزاء شبيب الشاري قال له الناس لو تنحيت أيها الأمير عن هذه السبخة فقال لهم ما تنحوني والله إليه أنتن وهل ترك مصعب لكريم مفرا ثم تمثل قول الكلحبة\n(إذا المرء لم يغش المكاره أوشكت ... حبال الهوينى بالفتى أن تقطعا)\nال الزبير وحدثني المدائني عن عوانة والشرقي بن القطامي عن أبي جناب قال لما أتى عبد الله بن الزبير قتل مصعب أضرب عن ذكره أياما حتى تحدثت به\nإماء مكة في الطريق ثم صعد المنبر فجلس عليه مليا لا يتكلم فنظرت إليه والكآبة على وجهه وجبينه يرشح عرقا فقلت لآخر إلى جنبي ما له لا يتكلم أتراه يهاب المنطق فوالله إنه لخطيب فما تراه يهاب قال أراه يريد أن يذكر قتل مصعب سيد العرب فهو يفظع لذكره وغير ملوم فقال الحمد لله الذي له الخلق والأمر ومالك الدنيا والآخرة يعز من يشاء ويذل من يشاء ألا إنه يذل والله من كان الحق معه وإن كان مفردا ضعيفا ولم يعز من كان الباطل معه وإن كان في العدة والعدد والكثرة ثم قال إنه قد أتانا خبر من العراق بلد الغدر والشقاق فساءنا وسرنا أتانا أن مصعبا قتل رحمة الله عليه ومغفرته فأما الذي أحزننا من ذلك فإن لفراق الحميم لذعة يجدها حميمه عند المصيبة ثم يرعوي من بعد ذو الرأي والدين إلى جميل الصبر وأما الذي سرنا منه فإنا قد علمنا أن قتله شهادة له وأن الله عز و جل جاعل لنا وله ذلك خيرة إن شاء الله تعالى أن أهل العراق أسلموه وباعوه بأقل ثمن كانوا يأخذونه منه وأخسره أسلموه إسلام النعم المخطم فقتل ولئن قتل أبوه وعمه وأخوه وكانوا الخيار الصالحين إنا والله ما نموت حتف أنوفنا ما نموت إلا قتلا قعصا بين قصد الرماح وتحت ظلال السيوف وليس كما يموت بنو مروان والله ما قتل رجل منهم في جاهلية ولا إسلام قط وإنما الدنيا عارية من الملك القهار الذي لا يزول سلطانه ولا يبيد ملكه فإن تقبل الدنيا علي لا آخذها أخذ الأشر البطر وإن تدبر عني لا أبك عليها بكاء الخرف المهتر ثم نزل وقال رجل من بني أسد بن عبد العزى يرثي مصعبا\n(لعمرك إن الموت منا لمولع ... بكل فتى رحب الذراع أريب)\n(فإن يك أمسى مصعب نال حتفه ... لقد كان صلب العود غير هيوب)\n(جميل المحيا يوهن القرن غربه ... وإن عضه دهر فغير رهوب)\n(أتاه حمام الموت وسط جنوده ... فطاروا شلالا واستقى بذنوب)\n(ولو صبروا نالوا حبا وكرامة ... ولكنهم ولوا بغير قلوب)","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":8,"spl":"ابن قيس الرقيات يرثي مصعبا — مصعب يسأل عن قتل الحسين"},
{"id":"b250-15","bab":"الجزء 19","sec":"عبد الملك لجلسائه مصعب أشجع الناس","page":"ج19 ص141","text":"قال وقال عبد الملك يوما لجلسائه من أشجع الناس فأكثروا في هذا المعنى فقال أشجع الناس مصعب بن الزبير جمع بين عائشة بنت طلحة وسكينة بنت الحسين وأمه الحميد بنت عبد الله بن عاصم وولي العراقين ثم زحف إلى الحرب فبذلت له الأمان والحباء والولاية والعفو عما خلص في يده فأبى قبول ذلك واطرح كل ما كان مشغوفا به من ماله وأهله وراء ظهره وأقبل بسيفه قرما يقاتل وما بقي معه إلا سبعة نفر حتى قتل كريما أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال لما ولي مصعب بن الزبير العراق أقر عبد العزيز بن عبد الله بن عامر على سجستان وأمده بخيل فقال ابن قيس الرقيات\n(ليت شعري أأول الهرج هذا ... أم زمان من فتنة غير هرج)\n(إن يعش مصعب فنحن بخير ... قد أتانا من عيشنا ما نرجي)\n(أعطي النصر والمهابة في الأعداء ... حتى أتوه من كل فج)\n(حيث لم تأت قبله خيل ذي الأكتاف ... يوجفن بين قف ومرج)\n(ملك يطعم الطعام ويسقي ... لبن البخت في عساس الخلنج)\nال الزبير حدثني عمي مصعب أن عبيد الله بن قيس كان عند عبد الملك فأقبل غلمان له معهم عساس خلنج فيها لبن البخت فقال عبد الملك يا بن قيس أين هذا من عساس مصعب التي تقول فيها\n(ملك يطعم الطعام ويسقي ... لبن البخت في عساس الخلنج)\nقال لا أين يا أمير المؤمنين لو طرحت عساسك هذه في عس من عساس مصعب لوسعها وتغلغلت في جوفه فضحك عبد الملك ثم قال قاتلك الله يا بن قيس فإنك تأبى إلا كرما ووفاء","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":9,"spl":"عبد الملك لجلسائه مصعب أشجع الناس — يونس الكاتب والوليد بن يزيد"},
{"id":"b250-16","bab":"الجزء 19","sec":"يونس الكاتب والوليد بن يزيد","page":"ج19 ص142","text":"حدثني عمي قال حدثني أحمد بن الطيب قال قال لي أحمد بن إبراهيم ابن إسماعيل بن داود خرج يونس الكاتب من المدينة يريد الشام بتجارة فبلغ الوليد بن يزيد مكانه فأتته رسله وهو في الخان وذلك في خلافة هشام والوليد يومئذ أمير فقالوا له أجب الأمير قال فذهبت معهم فأدخلوني عليه ولا أدري من هو إلا أنه حسن الوجه نبيل فسلمت عليه فأمرني بالجلوس فجلست ودعا بالشراب والجواري فكنا يومنا وليلتنا في أمر عجيب وغنيته فأعجبه لغنائي وكان مما أعجبه\n(ليت شعري أأول الهرج هذا ... أم زمان من فتنة غير هرج)\nلم يزل يستعيده إلى الصبح ثم اصطبح عليه ثلاثة أيام فقلت أيها الأمير أنا رجل تاجر قدمت هذا البلد في تجارة لي وقد ضاعت فقال تخرج غدا غدوة وقد ربحت أكثر من تجارتك وتمم شربه فلما أردت الانصراف لحقني غلام من غلمانه بثلاثة آلاف دينار فأخذتها ومضيت فلما أفضت الخلافة إليه أتيته فلم أزل مقيما عنده حتى قتل\nقال أحمد بن الطيب وذكر مصعب الزبيري أن يونس قال كنت أشرب مع أصحاب لي فأردت أن أبول فقمت وجلست أبول على كثيب رمل فخطر ببالي قول ابن قيس\n(ليت شعري أأول الهرج هذا ... )\nفغنيت فيه لحنا استحسنه وجاء عجبا من العجب فألقيته على جاريتي عاتكة ورددته حتى أخذته وشاع لي في الناس فكان أول صوت شاع لي وارتفع به قدري وقرنت بالفحول من المغنين وعاشرت الخلفاء من أجله وأكسبني مالا جليلا صوت\n(ألا ناد جيراننا يقصدوا ... فنقضي اللبانة أو نعهد)\n(كأن على كبدي جمرة ... حذارا من البين ما تبرد)\nلشعر لكثير والغناء لأشعب المعروف بالطمع ثاني ثقيل بالوسطى وفي البيت الثاني لابن جامع لحن من الثقيل الأول بالبنصر عن حبش","topic":"أخبار بكر بن النطاح ونسبه","topicNo":250,"sp":9,"spl":"عبد الملك لجلسائه مصعب أشجع الناس — يونس الكاتب والوليد بن يزيد","partialRef":{"sid":"b250-7","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b251-1","bab":"الجزء 19","sec":"ذكر أشعب وأخباره","page":"ج19 ص144","text":"هو أشعب بن جبير واسمه شعيب وكنيته أبو العلاء كان يقال لأمه أم الخلندج وقيل بل أم جميل وهي مولاة أسماء بنت أبي بكر واسمها حميدة وكان أبوه خرج مع المختار بن أبي عبيد وأسره مصعب فضرب عنقه صبرا وقال تخرج علي وأنت مولاي ونشأ أشعب بالمدينة في دور آل أبي طالب وتولت تربيته وكفلته عائشة بنت عثمان عفان وحكي عنه أنه حكى عن أمه أنها كانت تغري بين أزواج النبي زنت فحلقت وطيف بها وكانت تنادي على نفسها من رآني فلا يزنين فقالت لها امرأة كانت تطلع عليها يا فاعلة نهانا الله عز و جل عنه فعصيناه أو نطيعك وأنت مجلودة محلوقة راكبة على جمل وذكر رضوان بن أحمد الصيدلاني فيما أجاز لي روايته عنه عن يوسف بن الداية عن إبراهيم بن المهدي أن عبيدة بن أشعب أخبره وقد سأله عن أولهم وأصلهم أن أباه وجده كانا موليي عثمان وأن أمه كانت مولاة لأبي سفيان بن حرب وأن ميمونة أم المؤمنين أخذتها معها لما تزوجها النبي تدخل إلى أزواج النبي ثم إنها فارقت ذلك وصارت تنقل أحاديث بعضهن إلى بعض وتغري\nبينهن فدعا النبي فماتت وذكروا أنه كان مع عثمان رضي الله عنه في الدار فلما حصر جرد مماليكه السيوف ليقاتلوا فقال لهم عثمان من أغمد سيفه فهو حر قال أشعب فلما وقعت والله في أذني كنت أول من أغمد سيفه فأعتقت أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني إسحاق الموصلي قال حدثني الفضل بن الربيع قال كان أشعب عند أبي سنة أربع وخمسين ومائة ثم خرج إلى المدينة فلم يلبث أن جاء نعيه وهو أشعب بن جبير وكان أبوه مولى لآل الزبير فخرج مع المختار فقتله مصعب صبرا مع من قتل أخبرني الجوهري قال حدثنا ابن مهرويه قال حدثنا أحمد بن إسماعيل اليزيدي قال حدثني التوزي عن الأصمعي قال قال أشعب نشأت أنا وأبو الزناد في حجر عائشة بنت عثمان فلم يزل يعلو وأسفل حتى بلغنا هذه المنزلة أخبرني أحمد بن عبد العزيز قال حدثني محمد بن القاسم بن مهرويه قال حدثنا الزبير بن بكار قال حدثنا عبيد الله بن الحسن والي المأمون على المدينة قال حدثني محمد بن عثمان بن عفان قال قلت لأشعب لي إليك حاجة\nفحلف بالطلاق لابنه وردان لا سألته حاجة إلا قضاها فقلت له أخبرني عن سنك فأنشد ذلك عليه حتى ظننت أنه سيطلق فقلت له على رسلك وحلفت له إني لا أذكر سنه ما دام حيا فقال لي أما إذ فعلت فقد هونت علي أنا والله حيث حصر جدك عثمان بن عفان أسعى في الدار ألتقط السهام قال الزبير وأدركه أبي أخبرني أحمد قال حدثني محمد بن القاسم بن مهرويه قال حدثني محمد بن عبد الله اليعقوبي عن الهيثم بن عدي قال قال أشعب كنت ألتقط السهام من دار عثمان يوم حوصر وكنت في شيبتي ألحق الحمر الوحشية عدوا","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":0,"spl":"ذكر أشعب وأخباره"},
{"id":"b251-2","bab":"الجزء 19","sec":"بغت أمه فطيف بها","page":"ج19 ص146","text":"أخبرني أحمد قال حدثني محمد بن القاسم بن مهرويه قال حدثنا عبد الرحمن بن الجهم أبو مسلم وأحمد بن إسماعيل قالا أخبرنا المدائني قال كان أشعب الطامع واسمه شعيب مولى لآل الزبير من قبل أبيه وكانت أمه مولاة لعائشة بنت عثمان بن عفان وكانت بغت فضربت وحلقت وطيف بها وهي تنادي من رآني فلا يزنين فأشرفت عليها امرأة فقالت يا فاعلة نهانا الله عز و جل عن الزنا فعصيناه ولسنا ندعه لقولك وأنت محلوقة مضروبة يطاف بك أخبرني أحمد قال حدثنا أحمد بن مهرويه قال كتب إلي ابن أبي خيثمة يخبرني أن مصعب بن عبد الله أخبره قال اسم أشعب شعيب ويكنى أبا العلاء ولكن الناس قالوا أشعب فبقيت\nعليه وهو شعيب بن جبير مولى آل الزبير وهم يزعمون اليوم أنهم من العرب فزعم أشعب أن أمه كانت تغري بين أزواج النبي وامرأة أشعب بنت وردان ووردان الذي بنى قبر النبيحين بنى عمر بن عبد العزيز المسجد أخبرني أحمد قال حدثني محمد بن القاسم قال وكتب إلي ابن أبي خيثمة يخبرني أن مصعب بن عبد الله أخبره قال كان أشعب من القراء للقرآن وكان قد نسك وغزا وكان حسن الصوت بالقرآن وربما صلى بهم القيام أخبرني أحمد بن عبد العزيز قال حدثني محمد بن القاسم قال حدثني أحمد بن يحي قال أخبرنا إسحاق بن إبراهيم قال كان أشعب مع ملاحته ونوادره يغني أصواتا فيجيدها وفيه يقول عبد الله بن مصعب الزبيري صوت\n(إذا تمززت صراحية ... كمثل ريح المسك أو أطيب)\n(ثم تغنى لي بأهزاجه ... زيد أخو الأنصار أو أشعب)\n(حسبت أني ملك جالس ... حفت به الأملاك والموكب)\n(وما أبالي وإله الورى ... أشرق العالم أم غربوا)\nنى في هذه الأبيات زيد الأنصاري خفيف رمل بالبنصر وقد روى أشعب الحديث عن جماعة من الصحابة أخبرني عمي قال حدثني عبد الله بن أبي سعد أن الربيع بن ثعلب حدثهم قال حدثني أبو البختري\nحدثني أشعب عن عبد الله بن جعفر قال قال رسول الله دعيت إلى ذراع لأجبت ولو أهدي إلي كراع لقبلت","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":1,"spl":"بغت أمه فطيف بها"},
{"id":"b251-3","bab":"الجزء 19","sec":"أشعب وسالم بن عبد الله","page":"ج19 ص148","text":"قال ابن أبي سعد وروي عن محمد بن عباد بن موسى عن عتاب بن إبراهيم عن أشعب الطامع قال عتاب وإنما حملت هذا الحديث عنه لأنه عليه قال دخلت إلى سالم بن عبد الله بستانا له فأشرف علي وقال يا أشعب ويلك لا تسأل فإني سمعت أبي يقول سمعت رسول الله صلى الله عليه وآله وسلم يقول ليأتين أقوام يوم القيامة ما في وجوههم مزعة لحم قد أخلقوها بالمسألة ويروى عن يزيد بن موهب الرملي عن عثمان بن محمد عن أشعب عن عبد الله بن جعفر أن النبي في يمينه أخبرني أحمد قال حدثني عمر بن شبة قال حدثني الأصمعي عن أشعب قال استنشدني ابن لسالم بن عبد الله بن عمر غناء الركبان بحضرة أبيه سالم فأنشدته ورأس أبيه سالم في بت فلم ينكر ذلك أخبرني أحمد بن عبد العزيز قال حدثني محمد بن القاسم بن مهرويه قال حدثني أبو مسلم عن عبد الرحمن بن الحكم عن المدائني قال دفعت عائشة بنت عثمان أشعب في البزازين فقالت له بعد حول أتوجهت لشيء قال\nنعم تعلمت نصف العمل وبقي نصفه قالت وما تعلمت قال تعلمت النشر وبقي الطي قال المدائني وقال أشعب تعلقت بأستار الكعبة فقلت اللهم أذهب عني الحرص والطلب إلى الناس فمررت بالقرشيين وغيرهم فلم يعطني أحد شيئا فجئت إلى أمي فقالت مالك قد جئت خائبا فأخبرتها فقالت لا والله لا تدخل حتى ترجع فتستقيل ربك فرجعت فقلت يا رب أقلني ثم رجعت فلم أمر بمجلس لقريش وغيرهم إلا أعطوني ووهب لي غلام فجئت إلى أمي بحمار موقر من كل شيء فقالت ما هذا الغلام فخفت أن أخبرها بالقصة فتموت فرحا فقلت وهبوا لي قالت أي شيء قلت غين قالت أي شيء غين قلت لام قالت وأي شيء لام قلت ألف قالت وأي شيء ألف قلت ميم قالت وأي شيء ميم قلت غلام فغشي عليها ولو لم أقطع الحروف لماتت الفاسقة فرحا أخبرني أحمد قال حدثني محمد بن القاسم قال حدثني العباس بن ميمون قال سمعت الأصمعي يقول سمعت أشعب يقول سمعت الناس يموجون في أمر عثمان قال الأصمعي ثم أدرك المهدي أخبرني أحمد قال حدثني محمد بن القاسم قال حدثني يحي بن\nالحسن بن عبد الخالق بن سعيد الربيعي قال حدثني هند بن حمدان الأرقمي المخزومي قال أخبرني أبي قال كان أشعب أزرق أحول أكشف أقرع قال وسمعت الأرقمي يقول كان أشعب يقول كنت أسقي الماء في فتنة عثمان بن عفان والله أعلم أخبرني أحمد قال حدثني محمد بن القاسم قال حدثنا عيسى بن موسى قال حدثنا الأصمعي قال أصاب أشعب دينارا بالمدينة فاشترى به قطيفة ثم خرج إلى قباء يعرفها ثم أقبل علي فيما أحسب شك أبو يحي فقال أتراها تعرف قال أحمد وحدثناه أبو محمد بن سعد قال حدثني أحمد بن معاوية بن بكر قال حدثني الواقدي قال كنت مع أشعب نريد المصلى فوجد دينارا فقال لي يا بن واقد قلت ما تشاء قال وجدت دينار فما أصنع به قال قلت عرفه قال أم العلاء إذا طالق قال قلت فما تصنع به إذا قال أشتري به قطيفة أعرفها قال وحدثني محمد بن القاسم قال وحدثنيه محمد بن عثمان الكريزي عن الأصمعي أن أشعب وجد دينارا فتحرج من أخذه دون أن يعرفه فاشترى به قطيفة ثم قام على باب المسجد الجامع فقال من يتعرف الوبدة أخبرني أحمد الجوهري قال حدثني محمد بن القاسم قال سألت العنزي فقال الوبد من كل شيء الخلق وبد الثوب وومد إذا أخلق","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":2,"spl":"أشعب وسالم بن عبد الله"},
{"id":"b251-4","bab":"الجزء 19","sec":"أشعب وسالم بن عبد الله","page":"ج19 ص148","text":"أخبرنا أحمد قال حدثني محمد بن القاسم قال حدثنا عيسى بن موسى قال حدثنا الأصمعي قال رأيت أشعب يغني وكأن صوته صوت بلبل أخبرنا أحمد بن عبد العزيز قال حدثنا محمد بن القاسم بن عبد الله في رفقة فيها ألف محمل وكان ثم قاص عليهم فجئت فأخذت في أغنية من الرقيق فتركوه وأقبلوا إلي فجاء يشكوني إلى سالم فقال إن هذا صرف وجوه الناس عني قال وأتيت سالما وأحسبه قال والقاسم فسألتهما بوجه الله العظيم فأعطياني وكانا يبغضانني أو أحدهما يبغضني في الله قال قلنا لا تجعل هذا في الحديث قال بلى حدثنا أحمد قال حدثنا محمد بن القاسم قال وحدثناه قعنب بن محرز الباهلي قال أخبرنا الأصمعي عن أشعب قال قدم علينا قاص كوفي يقص في رفقته وفيها ألف بعير فخرجنا وأحرمنا من الشجرة بالتلبية فأقبل الناس إلي وتركوه قال ابن أم حميد فجاء إلي عبد الله بن عمرو بن عثمان بن عفان فقال إن مولاك هذا قد ضيق علي معيشتي أخبرنا أحمد قال حدثنا محمد بن القاسم قال أخبرنا أبو مسلم عبد الرحمن بن الجهم عن المدائني قال تغدى أشعب مع زياد بن عبد الله الحارثي فجاؤوا بمضيرة فقال أشعب لخباز ضعها بين يدي فوضعها بين يديه فقال زياد من يصلي بأهل السجن قال ليس لهم إمام قال أدخلوا أشعب يصلي بهم قال أشعب أو غير ذلك أصلح الله الأمير قال وما هو قال أحلف ألا آكل مضيرة أبدا\nأخبرنا أحمد قال حدثنا محمد بن القاسم قال حدثني قعنب بن المحرز قال حدثنا الأصمعي قال ولى المنصور زياد بن عبد الله الحارثي مكة والمدينة قال أشعب فلقيته بالجحفة فسلمت عليه قال فحضر الغداء وأهدي إليه جدي فطبخه مضيرة وحشيت القبة قال فأكلت أكلا أتملح به وأنا أعرف صاحبي ثم أتي بالقبة فشققتها فصاح الطباخ إنا لله شق القبة قال فانقطعت فلما فرغت قال يا أشعب هذا رمضان قد حضر ولا بد أن تصلي بأهل السجن قلت والله ما أحفظ من كتاب الله إلا ما أقيم به صلاتي قال لا بد منه قال قلت أو لا آكل جديا مضيرة قال وما أصنع به وهو في بطنك قال قلت الطريق بعيد أريد أن أرجع إلى المدينة قال يا غلام هات ريشة ذنب ديك قال أشعب والجحفة أطول بلاد الله ريشة ذنب ديك قال فأدخلت في حلقي فتقيأت ما أكلت ثم قال لي ما رأيك قال قلت لا أقيم ببلدة يصاح فيها شق القبة قال لك وظيفة على السلطان وأكره أن أكسرها عليك فقل ولا تشطط قال قلت نصف درهم كراء حمار يبلغني المدينة قال أنصفت وأعطانيه","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":3,"spl":"أشعب وسالم بن عبد الله"},
{"id":"b251-5","bab":"الجزء 19","sec":"من طرائف أشعب","page":"ج19 ص153","text":"أخبرنا أحمد قال حدثنا محمد بن القاسم قال أخبرني أبو مسلم عن المدائني قال أتي أشعب بفالوذجة عند بعض الولاة فأكل منها فقيل له كيف تراها يا أشعب قال امرأته طالق إن لم تكن عملت قبل أن يوحي الله عز و جل إلى النحل أخبرنا أحمد قال حدثنا محمد بن القاسم قال حدثنا عبد الله بن شعيب الزبيري عن عمه قال أبو بكر وحدثني ابن أبي سعد قال حدثني عبد الله بن شعيب وهو أتم من هذا وأكثر كلاما قال جاء أشعب إلى أبي بكر بن يحي من آل الزبير فشكا إليه فأمر له بصاع من تمر وكانت حال أشعب رثة فقال له أبو بكر بن يحي ويحك يا أشعب أنت في سنك وشهرتك تجيء في هذه الحال فتضع نفسك فتعطى مثل هذا اذهب فادخل الحمام فاخضب لحيتك قال أشعب ففعلت ثم جئته فألبسني ثياب صوف له وقال اذهب الآن فاطلب قال فذهبت إلى هشام بن الوليد صاحب البغلة من آل أبي ربيعة وكان رجلا شريفا موسرا فشكا إليه فأمر له بعشرين دينارا فقبضها أشعب وخرج إلى المسجد وطفق كلما جلس في حلقة يقول أبو بكر بن يحي جزاه الله عني خيرا أعرف الناس بمسألة فعل بي وفعل فيقص قصته فبلغ ذلك أبا بكر فقال يا عدو نفسه فضحتني في الناس أفكان هذا جزائي أخبرنا أحمد قال قال حدثني محمد بن القاسم قال أخبرني محمد بن الحسين بن عبد الحميد قال حدثني شيخ أنه نظر إلى أشعب بموضع يقال له الفرع يبكي وقد خضب\nبالحناء فقالوا يا شيخ ما يبكيك قال لغربة هذا الجناح وكان على دار واحدة ليس بالفرع غيره أخبرنا أحمد قال حدثنا محمد بن القاسم بن مهرويه قال أخبرني محمد ابن الحسين قال حدثني ابي قال نظرت إلى أشعب يسلم على رسول الله قال وهو يدعو ويتضرع قال فأدمت نظري إليه فكلما أدمت النظر إليه كلح وبث أصابعه في يده بحذائي حتى هربت فسألت عنه فقالوا هذا أشعب أخبرني أحمد قال حدثني محمد بن القاسم قال حدثني محمد بن الحسين قال حدثني إسحاق بن إبراهيم بن عجلان الفهري قال إن أشعب مر برش قد رش من الليل في بعض نواحي المدينة فقال كأن هذا الرش كساء برنكاني فلما توسطه قال أظنني والله قد صدقت وجلس يلمس الأرض أخبرنا أحمد قال حدثنا محمد بن القاسم قال حدثني محمد بن الحسين قال حدثنا بعض المدنيين قال كان لأشعب خرق في بابه فينام ويخرج يده من الخرق ويطمع أن يجيء إنسان فيطرح في يديه شيئا من الطمع أخبرني أحمد قال حدثني محمد بن القاسم قال حدثنا الزبير قال حدثني عبد الرحمن بن عبد الله الزهري قال صلى أشعب يوما إلى جانب مروان بن أبان بن عثمان وكان مروان عظيم\nالخلق والعجيزة فأفلتت منه ريح عند نهوضه لها صوت فانصرف أشعب من الصلاة فوهم الناس أنه هو الذي خرجت منه الريح فلما انصرف مروان إلى منزله جاءه أشعب فقال له الدية فقال دية ماذا فقال دية الضرطة التي تحملتها عنك والله وإلا شهرتك فلم يدعه حتى أخذ منه شيئا صالحا أخبرنا أحمد قال حدثنا محمد بن القاسم قال حدثني إبراهيم بن الجنيد قال حدثني سوار بن عبد الله قال حدثني مهدي بن سليمان المنقري مولى لهم عن أشعب قال دخلت على القاسم بن محمد وكان يبغضني في الله وأحبه فيه فقال ما أدخلك علي اخرج عني فقلت أسألك بالله لما جددت عذقا قال يا غلام جد له عذقا فإنه سأل بمسألة لا يفلح من ردها أبدا أخبرنا أحمد قال حدثني محمد بن القاسم قال حدثنا الرياشي قال حدثني أبو سلمة أيوب بن عمر عن المحرزي وهو أيوب بن عباية أبو سليمان قال كان لأشعب علي في كل سنة دينار قال فأتاني يوما ببطحان فقال عجل لي ذلك الدنيار ثم قال لقد رأيتني أخرج من بيتي فلا أرجع شهرا مما آخذ من هذا وهذا وهذا أخبرنا أحمد قال حدثني محمد بن القاسم قال حدثني علي بن محمد النوفلي قال سمعت أبي يحكي عن بعض المدنيين قال","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":4,"spl":"من طرائف أشعب"},
{"id":"b251-6","bab":"الجزء 19","sec":"من طرائف أشعب","page":"ج19 ص153","text":"كبر أشعب فمله الناس وبرد عندهم ونشأ ابنه فتغنى وبكى وأندر فاشتهى الناس ذلك فأخصب وأجدب أبوه فدعاه يوما وجلس هو وعجوزه وجاء ابنه وامرأته فقال له بلغني أنك تغنيت وأندرت وحظيت وأن الناس قد مالوا إليك فهلم حتى أخايرك قال نعم فتغنى أشعب فإذا هو قد انقطع وأرعد وتغنى ابنه فإذا هو حسن الصوت مطرب وانكسر أشعب ثم أندر فكان الأمر كذلك ثم خطبا فكان الأمر كذلك فاحترق أشعب فقام فألقى ثيابه ثم قال نعم فمن أين لك مثل خلقي من لك بمثل حديثي قال وانكسر الفتى فنعرت العجوز ومن معها عليه أخبرني أحمد قال حدثني عبد الله بن عمرو بن أبي سعد قال حدثني علي بن الحسين بن هارون قال حدثني محمد بن عباد بن موسى قال حدثني محمد بن عبد الله بن جعفر بن سليمان وكان جارنا هنا قال حدثني محمد بن حرب الهلالي وكان على شرطة محمد بن سليمان قال دخلت على جعفر بن سليمان وعنده أشعب يحدثه قال كانت بنت حسين بن علي عند عائشة بنت عثمان تربيها حتى صارت امرأة وحج الخليفة فلم يبق في المدينة خلق من قريش إلا وافى الخليفة إلا من لا يصلح لشيء فماتت بنت حسين بن علي فأرسلت عائشة إلى محمد بن عمرو بن حزم وهو والي المدينة وكان عفيفا حديدا عظيم اللحية له جارية موكلة بلحيته إذا ائتزر لا يأتزر عليها وكان إذا جلس للناس جمعها ثم أدخلها تحت فخذه فأرسلت عائشة يا أخي قد ترى ما دخل علي من المصيبة بابنتي وغيبة أهلي وأهلها وأنت الوالي فأما ما يكفي النساء من النساء فأنا أكفيكه بيدي وعيني\nوأما ما يكفي الرجال من الرجال فاكفنيه مر بالأسواق أن ترفع وأمر بتجويد عمل نعشها ولا يحملها إلا الفقهاء الألباء من قريش بالوقار والسكينة وقم على قبرها ولا يدخله إلا قرابتها من ذوي الحجا والفضل فأتى ابن حزم رسولها حين تغدى ودخل ليقيل فدخل عليه فأبلغه رسالتها فقال ابن حزم لرسولها أقرئ ابنة المظلوم السلام وأخبرها أني قد سمعت الواعية وأردت الركوب إليها فأمسكت عن الركوب حتى أبرد ثم أصلي ثم أنفذ كل ما أمرت به وأمر حاجبه وصاحب شرطته برفع الأسواق ودعا الحرس وقال خذوا السياط حتى تحولوا بين الناس وبين النعش إلا ذوي قرابتها بالسكينة والوقار ثم نام وانتبه وأسرج له واجتمع كل من كان بالمدينة وأتى باب عائشة حين أخرج النعش فلما رأى الناس النعش التقفوه فلم يملك ابن حزم ولا الحرس منه شيئا وجعل ابن حزم يركض خلف النعش ويصيح بالناس من السفلة والغوغاء اربعوا أي ارفقوا فلم يسمعوا حتى بلغ بالنعش القبر فصلى عليها ثم وقف على القبر فنادى من هاهنا من قريش فلم يحضره إلا مروان بن أبان بن عثمان وكان رجلا عظيم البطن بادنا لا يستطيع أن ينثني من بطنه سخيف العقل فطلع وعليه سبعة قمص كأنها درج بعضها أقصر من بعض ورداء عدني يثمن ألفي درهم فسلم وقال له ابن حزم أنت لعمري قريبها ولكن القبر ضيق لا يسعك فقال أصلح الله الأمير إنما تضيق الأخلاق قال ابن حزم إنا لله ما ظننت أن هذا هكذا كما أرى فأمر أربعة فأخذوا بضبعه حتى أدخلوه في القبر ثم أتى خراء الزنج وهو عثمان بن عمرو ابن عثمان فقال السلام عليك أيها الأمير ورحمة الله ثم قال واسيدتاه وابنت أختاه فقال ابن حزم تالله لقد كان يبلغني عن هذا أنه مخنث فلم أكن أرى أنه بلغ هذا كله دلوه فإنه عورة هو والله أحق بالدفن منها فلما أدخلا قال مروان","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":5,"spl":"من طرائف أشعب"},
{"id":"b251-7","bab":"الجزء 19","sec":"من طرائف أشعب","page":"ج19 ص153","text":"لخراء الزنج تنح إليك شيئا فقال له خراء الزنج الحمد لله رب العالمين جاء الكلب الإنسي يطرد الكلب الوحشي فقال لهما ابن حزم اسكتا قبحكما الله وعليكما لعنته أيكما الإنسي من الوحشي والله لئن لم تسكتا لآمرن بكما تدفنان ثم جاء خال للجارية من الخاطبيين وهو ناقة من مرض لو أخذ بعوضة لم يضبطها فقال أنا خالها وأمي سودة وأمها حفصة ثم رمى بنفسه في القبر فأصاب ترقوة خراء الزنج فصاح أوه أصلح الله الأمير دق والله عرقوبي فقال ابن حزم دق الله عرقوبك وترقوتك اسكت ويلك ثم أقبل على أصحابه فقال ويحكم إني خبرت أن الجارية بادن ومروان لا يقدر أن ينثني من بطنه وخراء الزنج مخنث لا يعقل سنة ولا دفنا وهذا الحاطبي لو أخذ عصفورا لم يضبطه لضعفه فمن يدفن هذه الجارية والله ما أمرتني بهذا بنت المظلوم فقال له جلساؤه لا والله ما بالمدينة خلق من قريش ولو كان في هؤلاء خير لما بقوا فقال من هاهنا من مواليهم فإذا أبو هانئ الأعمى وهو ظئر لها فقال ابن حزم من أنت رحمك الله قال أنا أبو هانئ ظئر عبد الله بن عمرو بن عثمان وأنا أدفن أحياءهم وأمواتهم فقال أنا في طلبك ادخل رحمك الله فادفن هؤلاء الأحياء حتى يدلى عليك الموتى ثم أقبل على أصحابه فقال إنا لله وهذا أيضا أعمى لا يبصر فنادوا من هاهنا من مواليهم فإذا برجل يزيدي يقال له أبو موسى قد جاء فقال له ابن حزم من أنت أيضا قال أنا أبو موسى صالمين وأنا ابن السميط سميطين والسعيد سعيدين والحمد لله رب العالمين فقال ابن حزم والله العظيم لتكونن لهم خامسا رحمك الله يا بنت رسول الله فما اجتمع على جيفة خنزير ولا كلب ما اجتمع على جثتك فإنا لله وإنا إليه راجعون وأظنه سقط رجل آخر أخبرني أحمد قال حدثني محمد بن القاسم قال حدثني اليعقوبي محمد ابن عبد الله قال حدثني أبو بكر الزلال الزبيري قال حدثني من رأى أشعب وقد\nعلق رأس كلبه وهو يضربه ويقول له تنبح الهدية وتبصبص للضيف","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":6,"spl":"من طرائف أشعب"},
{"id":"b251-8","bab":"الجزء 19","sec":"أشعب يرضع جديا لبن زوجته","page":"ج19 ص159","text":"أخبرنا أحمد قال حدثني عبد الله بن عمرو بن أبي سعد قال حدثني محمد بن محمد الزبيري أبو الطاهر قال حدثني يحي بن محمد بن أبي قتيلة قال غذا أشعب جديا بلبن زوجته وغيرها حتى بلغ الغاية قال ومن مبالغته في ذلك أن قال لزوجته أي ابنة وردان إني أحب أن ترضعيه بلبنك قال ففعلت قال ثم جاء به إلى إسماعيل بن جعفر بن محمد فقال بالله إنه لابني قد رضع بلبن زوجتي وقد حبوتك به ولم أر أحدا يستأهله سواك قال فنظر إسماعيل إلى فتنة من الفتن فأمر به فذبح وسمط فأقبل عليه أشعب فقال المكافأة فقال ما عندي والله اليوم شيء ونحن من تعرف وذلك غير فائت لك فلما يئس منه قام من عنده فدخل على أبيه جعفر بن محمد ثم اندفع يشهق حتى التقت أضلاعه ثم قال أخلني قال ما معنا أحد يسمع ولا عين عليك قال وثب ابنك إسماعيل على ابني فذبحه وأنا أنظر إليه قال فارتاع جعفر وصاح ويلك وفيم وتريد ماذا قال أما ما أريد فوالله ما لي في إسماعيل حيلة ولا يسمع هذا سامع أبدا بعدك فجزاه خيرا وأدخله منزله وأخرج إليه مائتي دينار وقال له خذ هذه ولك عندنا ما تحب قال وخرج إلى إسماعيل لا يبصر ما يطأ عليه فإذا به مترسل في مجلسه فلما رأى وجه أبيه نكره وقام إليه فقال يا إسماعيل أو فعلتها بأشعب قتلت ولده قال فاستضحك وقال جاءني بجدي من صفته كذا وخبره الخبر فأخبره أبوه ما كان منه وصار إليه قال فكان جعفر يقول لأشعب رعبتني رعبك الله فيقول روعة ابنك والله إياي في الجدي أكبر من روعتك أنت في المائتي الدينار أخبرنا أحمد قال حدثنا عبد الله بن عمرو بن أبي سعد قال حدثني محمد بن إسحاق المسيبي قال حدثني عمير بن عبد الله بن أبي بكر بن سليمان\nابن أبي خيثمة قال وعمير لقب واسمه عبد الرحمن عن أشعب قال أتيت خالد بن عبد الله بن عمرو بن عثمان بن عفان ليلة أسأله فقال لي أنت على طريقة لا أعطي على مثلها قلت بلى جعلت فداءك فقال قم فإن قدر شيء فسيكون قال فقمت فإني لفي بعض سكك المدينة إذ لقيني رجل فقال يا أشعب إن كان الله قد ساق إليك رزقا فما أنت صانع قلت أشكرالله وأشكر من فعله قال كم عيالك فأخبرته قال قد أمرت أن أجري عليك وعلى عيالك ما كنت حيا قال من أمرك قال لا أخبرك ما كانت هذه فوق هذه يريد السماء وأشار إليها قال قلت إن هذا معروف يشكر قال الذي أمرني لم يرد شكرك وهو يتمنى ألا يصل مثلك قال فمكثت آخذ ذلك إلى أن توفي خالد بن عبد الله بن عمرو بن عثمان قال فشهدته قريش وحفل له الناس قال فشهدته فلقيني ذلك الرجل فقال يا أشعب انتف رأسك ولحيتك هذا والله صاحبك الذي كان يجري عليك ما كنت أعطيك وكان والله يتمنى مباعدة مثلك قال فحمله والله الكرم إذ سألته أن فعل بك ما فعل قال عمير قال أشعب فعملت بنفسي والله حينئذ ما حل وحرم أخبرني أحمد قال حدثني محمد بن القاسم بن مهرويه قال حدثنا الزبير ابن بكار قال كان أشعب يوما في المسجد يدعو وقد قبض وجهه فصيره كالصبرة المجموعة فرآه عامر بن عبد الله بن الزبير فحصبه وناداه يا أشعب إذا تناجي ربك فناجه بوجه طلق قال فأرخى لحيه حتى وقع على زوره قال فأعرض عنه عامر وقال ولا كل هذا\nأخبرني أحمد بن عبد العزيز قال حدثني محمد بن القاسم قال حدثني الزبير قال حدثني مصعب قال جز أشعب لحيته فبعث إليه نافع بن ثابت بن عبد الله بن الزبير ألم أقل لك إن البطال أملح ما يكون إذا طالت لحيته فلا تجزر لحيتك","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":7,"spl":"أشعب يرضع جديا لبن زوجته"},
{"id":"b251-9","bab":"الجزء 19","sec":"طرائف من طمع أشعب وبخله","page":"ج19 ص161","text":"أخبرني أحمد قال حدثني محمد بن القاسم قال حدثنا أبو الحسن أحمد ابن يحي قال أخبرنا أبو الحسن المدائني قال وقف أشعب على امرأة تعمل طبق خوص فقال لتكبريه فقالت لم أتريد أن تشتريه قال لا ولكن عسى أن يشتريه إنسان فيهدي إلي فيه فيكون كبيرا خير من أن يكون صغيرا أخبرني أحمد بن عبد العزيز قال حدثني محمد بن القاسم قال أخبرنا أحمد بن يحي قال أخبرنا المدائني قال صديقة أشعب لأشعب هب لي خاتمك أذكرك به قال اذكريني أني منعتك إياه فهو أحب إلي أخبرني أحمد قال حدثني محمد بن القاسم بن مهرويه قال أخبرنا أبو مسلم قال أخبرنا المدائني قال قال أشعب مرة للصبيان هذا عمرو بن عثمان يقسم مالا فمضوا فلما أبطأوا عنه اتبعهم يحسب أن الأمر قد صار حقا كما قال أخبرنا أحمد قال حدثنا محمد بن القاسم قال أخبرنا أحمد بن يحي قال أخبرنا المدائني قال دعا زياد بن عبد الله أشعب فتغدى معه فضرب بيده إلى جدي بين يديه\nوكان زياد أحد البخلاء بالطعام فغاظه ذلك فقال لخدمه أخبروني عن أهل السجن ألهم إمام يصلي بهم وكان أشعب من القراء لكتاب الله تعالى قالوا لا قال فأدخلوا أشعب فصيروه إماما لهم قال أشعب أو غير ذلك قالو وما هو قال أحلف لك أصلحك الله ألا أذوق جديا أبدا فخلاه أخبرنا أحمد قال حدثنا محمد بن القاسم قال أخبرنا أبو مسلم قال أخبرنا المدائني قال رأيت أشعب بالمدينة يقلب مالا كثيرا فقلت له ويحك ما هذا الحرص ولعلك أن تكون أيسر ممن تطلب منه قال إني قد مهرت في هذه المسألة فأنا أكره أن أدعها فتنفلت مني أخبرنا أحمد قال حدثنا محمد بن القاسم قال أخبرنا أبو مسلم قال أخبرنا المدائني قال قيل لأشعب ما بلغ من طمعك قال ما رأيت اثنين يتساران قط إلا كنت أراهما يأمران لي بشيء أخبرنا أحمد قال حدثنا محمد بن القاسم قال حدثنا أبو مسلم قال أخبرنا المدائني قال قال أشعب لأمه رأيتك في النوم مطلية بعسل وأنا مطلي بعذرة فقالت يا فاسق هذا عملك الخبيث كساكه الله عز و جل قال إن في الرؤيا شيئا آخر قالت ما هو قال رأيتني ألطعك وأنت تلطعيني قالت لعنك الله يا فاسق أخبرنا أحمد قال حدثني محمد بن القاسم قال أخبرنا أبو مسلم قال\nأخبرنا المدائني قال كان أشعب يتحدث إلى امرأة بالمدينة حتى عرف ذلك فقالت لها جاراتها يوما لو سألته شيئا فإنه موسر فلما جاء قالت إن جاراتي ليقلن لي ما يصلك بشيء فخرج نافرا من منزلها فلم يقربها شهرين ثم إنه جاء ذات يوم فجلس على الباب فأخرجت إليه قدحا ملآن ماء فقالت اشرب هذا من الفزع فقال اشربيه أنت من الطمع أخبرنا أحمد بن عبد العزيز قال حدثني محمد بن القاسم قال أخبرنا أبو مسلم وأحمد بن يحي واللفظ لأحمد قال أخبرنا المدائني عن جهم بن خلف قال حدثني رجل قال قلت لأشعب لو تحدثت عندي العشية فقال أكره أن يجيء ثقيل قال قلت ليس غيرك وغيري قال فإذا صليت الظهر فأنا عندك فصلى وجاء فلما وضعت الجارية الطعام إذا بصديق لي يدق الباب فقال ألا ترى قد صرت إلى ما أكره قال قلت إن عندي فيع عشر خصال قال فما هي قال أولها أنه لا يأكل ولا يشرب قال التسع الخصال لك أدخله قال أبو مسلم إن كرهت واحدة منها لم أدخله أخبرنا أحمد قال حدثنا محمد بن القاسم بن مهرويه قال أخبرنا أبو مسلم قال أخبرنا المدائني قال دخل أشعب يوما على الحسين بن علي وعنده أعرابي قبيح المنظر مختلف الخلقة فسبح أشعب حين رآه وقال للحسين عليه السلام بأبي أنت وأمي أتأذن لي أن أسلح عليه فقال الأعرابي ما شئت ومع الأعرابي قوس وكنانة ففوق له سهما وقال والله لئن فعلت لتكونن آخر سلحة سلحتها قال أشعب للحسين جعلت فداءك قد أخذني القولنج","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":8,"spl":"طرائف من طمع أشعب وبخله"},
{"id":"b251-10","bab":"الجزء 19","sec":"طرائف من طمع أشعب وبخله","page":"ج19 ص161","text":"أخبرنا أحمد بن عبد العزيز قال حدثني محمد بن القاسم قال أخبرنا أبو مسلم قال أخبرنا المدائني قال ذكر أشعب بالمدينة رجلا قبيح الإسم فقيل له يا أبا العلاء أتعرف فلانا قال ليس هذا من الأسماء التي عرضت على آدم وجدت في بعض الكتب عن أحمد بن الحارث الخراز عن المدائني قال توضأ أشعب فغسل رجله اليسرى وترك اليمنى فقيل له لم تركت غسل اليمنى قال لأن النبي قال أمتي غر محجلون من آثار الوضوء وأنا أحب أن أكون أغر محجلا مطلق اليمنى وأخبرت بهذا الإسناد قال سمع أشعب حبى المدينية تقول اللهم لا تمتني حتى تغفر لي ذنونبي فقال لها يا فاسقة أنت لم تسألي الله المغفرة إنما سألته عمر الأبد يريد أنه لا يغفر لها أبدا أخبرنا أحمد بن عبد العزيز الجوهري قال حدثني محمد بن القاسم قال أخبرنا المدائني عن فليح بن سليمان قال ساوم أشعب رجلا بقوس عربية فقال الرجل لا أنقصها عن دينار قال أشعب أعتق ما أملك لو أنها إذا رمي بها طائر في جو السماء ووقع مشويا بين رغيفين مأخذتها بدينار أخبرنا أحمد قال حدثنا محمد بن القاسم قال أخبرنا مسلم قال أخبرنا المدائني قال أهدى رجل من بني عامر بن لؤي إلى إسماعيل الأعرج بن جعفر بن\nمحمد فالوذجة وأشعب حاضر قال كل يا أشعب فلما أكل منها قال كيف تجدها يا أشعب قال أنا برىء من الله ورسوله إن لم تكن عملت قبل أن يوحي الله عز و جل إلى النحل أي ليس فيها من الحلاوة شيء أخبرنا أحمد قال حدثنا محمد بن القاسم قال أخبرنا أبو مسلم قال أخبرنا المدائني قال سأل سالم بن عبد الله أشعب عن طعمه قال قلت لصبياني مرة هذا سالم قد فتح باب صدقة عمر فانطلقوا يعطكم تمرا فمضوا فلما أبطأوا ظننت أن الأمر كما قلت فاتبعتهم أخبرني أحمد بن عبد العزيز قال حدثني محمد بن القاسم قال أخبرنا أبو مسلم قال أخبرني المدائني قال بينا أشعب يوما يتغدى إذ دخلت جارة له ومع أشعب امرأته تأكل فدعاها ليتغدى فجاءت الجارة فأخذت العرقوب بما عليه قال وأهل المدينة يسمونه عرقوب رب البيت قال فقام أشعب فخرج ثم عاد فدفق الباب فقالت له أمرأته يا سخين العين مالك قال أدخل قالت أتستأذن أنت وأنت رب البيت قال لو كنت رب البيت ما كانت العرقوب بين يدي هذه أخبرني بعض أصحابنا قال حدثنا أحمد بن سعيد الدمشقي قال حدثنا الزبير قال حدثني مصعب قال قال لي ابن كليب حدثت مرة أشعب بملحة فبكى فقلت ما يبكيك قال أنا بمنزلة شجرة الموز إذا نشأت ابنتها قطعت وقد نشأت أنت في موالي وأنا الآن أموت فإنما أبكي على نفسي أخبرني أحمد بن عبد العزيز قال حدثنا ابن مهرويه قال حدثنا الزبير بن بكار قال كان أشعب الطمع يغني وله أصوات قد حكيت عنه وكان ابنه عبيدة يغنيها فمن أصواته هذه\n(أروني من يقوم لكم مقامي ... إذا ما الأمر جل عن الخطاب)\n(إلى من تفزعون إذا حثوتم ... بأيديكم علي من التراب)","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":9,"spl":"طرائف من طمع أشعب وبخله"},
{"id":"b251-11","bab":"الجزء 19","sec":"أشعب وسكينة بنت الحسين","page":"ج19 ص166","text":"أخبرني الحسن بن علي الحفاف قال حدثنا أحمد بن سعيد الدمشقي قال حدثنا الزبير بن بكار قال حدثنا شعيب بن عبيدة بن أشعب عن أبيه عن جده قال كانت سكينة بنت الحسين بن علي عليهم السلام عند زيد بن عمرو بن عثمان بن عفان قال وقد كانت أحلفته ألا يمنعها سفرا ولا مدخلا ولا مخرجا فقالت اخرج بنا إلى حمران من ناحية عسفان فخرج بها فأقامت ثم قالت له اذهب بنا نعتمر فدخل بها مكة فأتاني آت فقال تقول لك ديباجة الحرم وهي امرأة من ولد عتاب بن أسيد لك عشرون دينارا إن جئتني بزيد ابن عمرو الليلة في الأبطح قال أشعب وأنا أعرف سكينة وأعلم ما هي ثم غلب علي طباع السوء والشره فقلت لزيد فيما بيني وبينه إن ديباجة الحرم\nأرسلت إلي بكيت وكيت فقال عدها الليلة بالأبطح فأرسلت إليها فواعدتها الأبطح وإذا الديباجة قد افترشت بساطا في الأبطح وطرحت النمارق ووضعت حشايا وعليها أنماط فجلست عليها فلما طلع زيد قامت إليه فتلقته وسلمت عليه ثم رجعت إلى مجلسها فلم ننشب أن سمعنا شحيج بغلة سكينة فلما استبانها زيد قام فأخذ بركابها واختبأت ناحية فقامت الديباجة إلى سكينة فتلقتها وقبلت بين عينيها وأجلستها على الفراش وجلست هي على بعض النمارق فقالت سكينة أشعب والله صاحب هذا الأمر ولست لأبي إن لم يأت يصيح صياح الهرة لن يقوم لي بشيء أبدا فطلعت على أربع أصيح صياح الهرة ثم دعت جارية معها مجمر كبير فحفنت منه وأكثرت وصبت في حجر الديباجة وحفنت لمن معها فصبته في حجورهن وركبت وركب زيد وأنا معهم فلما صارت إلى منزلها قالت لي يا أشعب أفعلتها قلت جعلت فداءك إنما جعلت لي عشرين دينارا وقد عرفت طمعي وشرهي والله لو جعلت لي العشرين دينارا على قتل أبوي لقتلتهما قال فأمرت بالرحيل إلى الطائف فأقامت بالطائف وحوطت من ورائها بحيطان ومنعت زيدا أن يدخل عليها قال ثم قالت لي يوما قد أثمنا في زيد وفعلنا ما لا يحل لنا ثم أمرت بالرحيل إلى المدينة وأذنت لزيد فجاءها قال الزبير وحدثني عبد الله بن محمد بن أبي سلمة قال جاء أشعب إلى مجلس أصحابنا فجلس فيه فمرت جارية لأحدهم بحزمة عراجين من صدقة عمر فقال له أشعب فديتك أنا محتاج إلى حطب فمر لي بهذه الحزمة قال لا ولكن أعطيك نصفها على أن تحدثني بحديث ديباجة\nالحرم فكشف أشعب ثوبه عن استه واستوفز وجعل يخنس ويقول إن لهذا زمانا وجلعت خصيتاه تخطان الأرض ثم اقل أعطاني والله فلان في حديث ديباجة الحرم عشرين دينارا وأعطاني فلان كذا وأعطاني فلان كذا حتى عد أموالا وأنت الآن تطلبها مني بنصف حزمة عراجين ثم قام فانصرف وفي ديباجة الحرم يقول عمر بن أبي ربيعة صوت\n(ذهبت ولم تلم بديباجة الحرم ... وقد كنت منها في عناء وفي سقم)\n(جننت بها لما سمعت بذكرها ... وقد كنت مجنونا بجاراتها القدم)\n(إذا أنت لم تعشق ولم تدر ما الهوى ... فكن حجرا بالحزن من حرة أصم)\nناه مالك بن أبي السمح من رواية يونس عن حبيش قال الزبير وحدثني شعيب بن عبيدة عن أبيه قال دخل رجل من قريش على سكينة بنت الحسين عليهما السلام قال فإذا أنا بأشعب متفحج جالس تحت السرير فلما رآني جعل يقرقر مثل الدجاجة فجعلت أنظر إليه وأعجب فقالت مالك تنظر إلى هذا قلت إنه لعجب قالت إنه لخبيث قد أفسد علينا أمورنا بغباوته فحضنته بيض دجاج ثم أقسمت أنه لا يقوم عنه حتى ينفق وهذا الخبر عندنا غير مشروح ولكن هذا ما سمعناه ونسخته على الشرح من أخبار إبراهيم بن المهدي التي رواها عنه يوسف ابن إبراهيم وقد ذكر في أخبار سكينة\nوروى عن أحمد بن الحسن البزار وجدت بخط ابن الوشاء عن أبي الوشاء عن الكديمي عن أبي عاصم قال قيل لأشعب الطامع أرأيت أحدا قط أطمع منك قال نعم كلبا يتبعني أربعة أميال على مضغ العلك أخبرني الحرمي بن أبي العلاء وعمي عبد العزيز بن أحمد وحبيب بن نصر المهلبي قالوا حدثنا الزبير بن بكار قال حدثني مصعب عن عثمان بن المنذر عن عبيد الله بن أبي بشر بن عثمان بن المغيرة قال سمعت جلبة شديدة مقبلة من البلاط وأسرعت فإذا جماعة مقبلة وإذا امرأة قد فرعتهم طولا وإذا أشعب بين أيديهم بكفه دف وهو يغني به ويرقص ويحرف استه ويحركها ويقول\n(ألا حي التي خرجت ... قبيل الصبح فاختمرت)\n(يقال بعينها رمد ... ولا والله ما رمدت)","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":10,"spl":"أشعب وسكينة بنت الحسين"},
{"id":"b251-12","bab":"الجزء 19","sec":"أشعب وسكينة بنت الحسين","page":"ج19 ص166","text":"فإذا تجاوز في الرقص الجماعة رجع إليهم يخالطهم ويستقبل المرأة فيغني في وجهها وهي تبسم وتقول حسبك الآن فسألت عنها فقالوا هذه جارية صريم المغنية استلحقها صريم عند موته واعترف بأنهها بنته فحاكمت ورثته إلى السلطان فقامت لها البينة فألحقها به وأعطاها الميراث منه وكانت أحسن خلق الله غناء كان يضرب بها المثل في الحجاز فيقال أحسن من غناء الصريمية أخبرني الحسن بن علي قال حدثنا الدمشقي قال حدثنا الزبير بن بكار قال وحدثني أبي قال اجتازت جنازة الصريمية بأشعب وهو جالس في وقوم من قريش فبكى عليها\nثم قال ذهب اليوم الغناء كله وعلى أنها الزانية كانت لا رحمها الله شر خلق الله فقيل يا أشعب ليس بين بكائك عليها ولعنك إياها فصل في كلامك قال نعم كنا نجيئها الفاجرة بكبش فيطبخ لنا في دارها ثم لا تعشينا يشهد الله إلا بسلق","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":11,"spl":"أشعب وسكينة بنت الحسين"},
{"id":"b251-13","bab":"الجزء 19","sec":"أشعب والغاضري","page":"ج19 ص170","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال قال حدثنا مصعب بلغ أشعب أن الغاضري قد أخذ في مثل مذهبه ونوادره وأن جماعة قد استطابوه فرقبه حتى علم أنه في مجلس من مجالس قريش يحادثهم ويضحكهم فصار إليه ثم قال له قد بلغني أنك قد نحوت نحوي وشغلت عني من كان يألفني فإن كنت مثلي فافعل كما أفعل ثم غضن وجهه وعرضه وشنجه حتى صار عرضه أكثر من طوله وصار في هيئة لم يعرفه أحد بها ثم أرسل وجهه وقال له افعل هكذا وطول وجهه حتى كاد ذقنه يجوز صدره وصار كأنه وجه الناظر في سيفه ثم نزع ثيابه وتحادب فصار في ظهره حدبة كسنام البعير وصار طوله مقدار شبر أو أكثر ثم نزع سراويله وجعل يمد جلد خصييه حتى حك بهما الأرض ثم خلاهما من يده ومشى وجعل يخنس وهما يخطان الأرض ثم قام فتطاول وتمدد وتمطى حتى صار أطول ما يكون من الرجال فضحك والله القوم حتى أغمي عليهم وقطع الغاضري فما تكلم بنادرة ولا زاد على أن يقول يا أبا العلاء لا أعاود ما تكره إنما أنا تلميذك وخريجك ثم أنصرف أشعب وتركه أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم عن إبراهيم بن المهدي عن عبيدة بن أشعب عن أبيه أنه كان مولده في سنة تسع\nمن الهجرة وأن أباه كان من مماليك عثمان وأن أمه كانت تنقل كلام أزواح النبي بعضهن إلى بعض فتلقي بينهن الشر فتأذى رسول الله فدعا الله عز و جل عليها فأماتها وعمر ابنها أشعب حتى هلك في أيام المهدي وكان في أشعب خلال منها أنه كان أطيب أهل زمانه عشرة وأكثرهم نادرة ومنها أنه كان أحسن الناس أداء لغناء سمعه ومنها أنه أقوم أهل دهره بحجج المعتزلة وكان أمرأ منهم قال إبراهيم بن المهدي فحدثني عبيدة بن أشعب عن أبيه قال بلغني أن عبد الله بن عمر كان في مال له يتصدق بثمرته فركبت ناضحا ووافيته في ماله فقلت يا بن أمير المؤمنين ويا بن الفاروق أوقر لي بعيري هذا تمرا فقال لي أمن المهاجرين أنت قلت اللهم لا قال فمن الأنصار أنت فقلت اللهم لا قال أفمن التابعين بإحسان فقلت أرجو فقال إلى أن يحقق رجاؤك قال أفمن أبناء السبيل أنت قلت لا قال فعلام أوقر لك بعيرك تمرا قلت لأني سائل وقد قال رسول الله ( إن أتاك سائل على فرس فلا ترده\nفقال لو شئنا أن نقول لك إنه قال لو أتاك على فرس ولم يقل أتاك على ناضح بعير لقلنا ولكني أمسك عن ذلك لاستغنائي عنه لأني قلت لأبي عمر بن الخطاب إذا أتاني سائل على فرس يسألني أعطيته فقال إني سألت رسول الله عما سألتني عنه فقال لي نعم إذا لم تصب راجلا ونحن أيها الرجل نصيب رجالة فعلام أعطيك وأنت على بعير فقلت له بحق أبيك الفاروق وبحق الله عز و جل وبحق رسول الله صلى الله علية وآله وسلم لما أوقرته لي تمرا فقال لي عبد الله أنا موقره لك تمرا ووحق الله ووحق رسوله لئن عاودت استحلافي لا أبررت لك قسمك ولو أنك اقتصرت على استحلافي بحق\nأبي علي في تمرة أعطيكها لما أنفذت قسمك لأني سمعت أبي يقول إن رسول الله صلى الله عليه وآله وسلم قال لا تشد الرحال إلى مسجد لرجاء الثواب إلا إلى المسجد الحرام ومسجدي بيثرب ولا يبر امرؤ قسم مستحلفه إلا أن يستحلفه بحق الله وحق رسوله ثم قال للسودان في تلك الحال أوقروا له بعيره تمرا قال ولما أخذ السودان في حشو الغرائر قلت إن السودان أهل طرب وإن أطربتهم أجادوا حشو غرائري فقلت يا بن الفاروق أتأذن لي في الغناء فأغنيك فقال لي أنت وذلك فاندفعت في النصب فقال لي هذا الغناء الذي لم نزل نعرفه ثم غنيته صوتا آخر لطويس المغني وهو\n(خليلي ما أخفي من الحب ناطق ... ودمعي بما قلت الغداة شهيد)\nقال لي عبد الله يا هناه لقد حدث في هذا المعنى ما لم نكن نعرفه قال ثم غنيته لابن سريج\n(يا عين جودي بالدموع السفاح ... وابكي على قتلى قريش البطاح)\nقال يا أشعب ويحك هذا يحيق الفؤاد أراد يحرق الفؤاد لأنه كان ألثغ لا يبين بالراء ولا باللام قال أشعب وكان بعد ذلك لا يراني إلا استعادني هذا الصوت","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":12,"spl":"أشعب والغاضري"},
{"id":"b251-14","bab":"الجزء 19","sec":"أشعب والغاضري","page":"ج19 ص170","text":"أخبرني الحرمي بن أبي العلاء حدثنا الزبير بن بكار قال حدثني عمي قال لقي أشعب صديق لأبيه فقال له ويحك يا أشعب كان أبوك ألحى وأنت أثط فإلى من خرجت قال إلى أمي أخبرني الحسن بن علي قال أخبرنا أحمد بن أبي خيثمة قال حدثنا مصعب بن عبد الله عن مصعب بن عثمان قال لقي أشعب سالم بن عبد لله بن عمر فقال يا أشعب هل لك في هريس قد أعد لنا قال نعم بأبي أنت وأمي قال فصر إلي فمضى إلى منزله فقالت له امرأته قد وجه إليك عبد الله بن عمرو بن عثمان يدعوك قال ويحك إن لسالم بن عبد الله هريسة قد دعاني إليها وعبد الله بن عمرو في يدي متى شئت وسالم إنما دعوته للناس فلتة وليس لي بد من المضي إليه قالت إذا يغضب عبد الله قال آكل عنده ثم أصير إلى عبد الله فجاء إلى سالم وجعل يأكل أكل متعالل فقال له كل يا أشعب وابعث ما فضل عنك إلى منزلك قال ذاك أردت بأبي أنت وأمي فقال يا غلام احمل هذا إلى منزله فحمله ومضى معه فجاء به امرأته فقالت له ثكلتك أمك قد حلف عبد الله أن لا يكلمك شهرا قال دعيني وإياه هاتي شيئا من زعفران فأعطته ودخل الحمام يمسح على وجهه ويديه وجلس في الحمام حتى صفره ثم خرج متكئا على عصا يرعد حتى أتى دار عبد الله بن عمرو فلما رآه حاجبه قال ويحك بلغت بك العلة ما أرى ودخل وأعلم صاحبه فأذن له فلما دخل عليه إذا سالم بن عبد الله عنده فجعل يزيد في الرعدة ويقارب الخطو فجلس وما يقدر أن يستقل فقال عبد الله ظلمناك يا أشعب في غضبنا عليك فقال له سالم مالك ويلك ألم\nتكن عندي آنفا وأكلت هريسة فقال له وأي أكل ترى بي قال ويلك ألم أقل لك كيت وكيت وتقل لي كيت وكيت قال له شبه لك قال لا حول ولا قوة إلا بالله والله إني لأظن الشيطان يتشبه بك ويلك أجاد أنت قال علي وعلي إن كنت خرجت منذ شهر فقال له عبد الله أعزب ويحك أتبهته لا أم لك قال ما قلت إلا حقا قال بحياتي اصدقني وأنت آمن من غضبي قال لا وحياتك لقد صدق ثم حدثه بالقصة فضحك حتى استلقى على قفاه","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":13,"spl":"أشعب والغاضري"},
{"id":"b251-15","bab":"الجزء 19","sec":"ابنه عبد الله يذكر بعض طرائفه","page":"ج19 ص174","text":"أخبرني رضوان بن أحمد بن يوسف بن إبراهيم عن إبراهيم بن المهدي أن الرشيد لما ولاه دمشق بعث إليه عبد الله بن أشعب وكان يقدم عليه من الحجاز إذا أراد أن يطرب قال إبراهيم وكان يحدثني من حديث أبيه بالطرائف عادلته يوما وأنا خارج من دمشق في قبة على بغل لألهو بحديثه فأصابنا في الطريق برد شديد فدعوت بدواج سمور لألبسه فأتيت به فلما لبسته أقبلت على ابن اشعب فقلت حدثني بشيء من طمع ابيك فقال لي مالك ولأبي ها أنا إذ دعوت بالدواج فما شككت والله في أنك إنما جئت به لي فضحكت من قوله ودعوت بغيره فلبسته وأعطيته إياه ثم قلت له ألأبيك ولد غيرك فقال كثير فقلت عشرة قال أكثر قلت فخمسون قال أكثر كثير قلت مائة قال دع المئين وخذ الألوف فقلت ويلك أي شيء تقوله أشعب أبوك ليس بينك وبينه أب فكيف يكون له ألوف\nمن الولد فضحك ثم قال لي في هذا خبر ظريف فقلت له حدثني به فقال كان أبي منقطعا إلى سكينة بنت الحسين وكانت متزوجة بزيد بن عمرو بن عثمان بن عفان وكانت محبة له فكان لا يستقر معها تقول له أريد الحج فيخرج معها فإذا أفضوا إلى مكة تقول أريد الرجوع إلى المدينة فإذا عاد إلى المدينة قالت أريد العمرة فهو معها في سفر لا ينقضي قال عبد الله فحدثني أبي قال كانت قد حلفته بما لا كفارة له ألا يتزوج عليها ولا يتسرى ولا يلم بنسائه وجواريه إلا بإذنها وحج الخليفة في سنة من السنين فقال لها قد حج الخليفة ولا بد لي من لقائه قالت فاحلف بأنك لا تدخل الطائف ولا تلم بجواريك على وجه ولا سبب فحلف لها بما رضيت به من الأيمان على ذلك ثم قالت له احلف بالطلاق فقال لا أفعل ولكن ابعثي معي بثقتك فدعتني وأعطتني ثلاثين دينارا وقالت لي اخرج معه وحلفتني بطلاق بنت وردان زوجتي ألا اطلق له الخروج إلى الطائف بوجه ولا سبب فحلفت لها بما أثلج صدرها فأذنت له فخرج وخرجت معه فلما حاذينا الطائف قال لي يا أشعب أنت تعرفني وتعرف صنائعي عندك وهذه ثلاثمائة دينار خذها بارك الله لك فيها وأذن لي ألم بجواري فلما سمعتها ذهب عقلي ثم قلت يا سيدي هي سكينة فالله الله في فقال أو تعلم سكينة الغيب فلم يزل بي حتى أخذتها وأذنت له فمضى وبات عند جواريه فلما أصبحنا رأيت أبيات قوم من العرب قريبة منا فلبست حلة وشيء كانت لزيد قيمتها ألف دينار وركبت فرسه وجئت إلى النساء فسلمت فرددن ونسبنني فانتسبت نسب زيد فحادثني وأنسن بي وأقبل رجال الحي وكلما جاء رجل سأل عن نسبي فخبر به هابني وسلم علي وعظمني وانصرف إلى أن أقبل شيخ كبير منكر مبطون فلما خبر بي وبنسبي شال حاجبيه عن عينه ثم نظر إلي وقال وأبي ما هذه خلقة قرشي ولا شمائله وما هو إلا عبد لهم ناد وعلمت أنه يريد شرا فركبت الفرس ثم مضيت ولحقني فرماني بسهم فما أخطأ قربوس\nالسرج وما شككت أنه يلحقني بآخر يقتلني فسلحت يعلم الله في ثيابي فلوثها ونفذ إلى الحلة فصيرها شهرة وأتيت رحل زيد بن عمرو فجلست أغسل الحلة وأجففها وأقبل زيد بن عمرو فرأى ما لحق الحلة والسرج فقال لي ما القصة ويلك فقلت يا سيدي الصدق أنجى وحدثته الحديث فاغتاظ ثم قال لي ألم يكفك أن تلبس حلتي وتصنع بها ما صنعت وتركب فرسي وتجلس إلى النساء حتى انتسبت بنسبي وفضحتني وجعلتني عند العرب ولاجا جماشا وجرى عليك ذل نسب إلي أنا نفي من أبي ومنسوب إلى أبيك إن لم أسؤك وأبلغ في ذلك ثم لقي الخليفة وعاد ودخلنا إلى سكينة فسألته عن خبره كله فخبرها حتى انتهى إلى ذكر جواريه فقالت إيه وما كان من خبرك قي طريقك هل مضيت إلى جواريك بالطائف فقال لها لا أدري سلي ثقتك فدعتني فسألتني وبدأت فحلفت لها بكل يمين محرجة أنه ما مر بالطائف ولا دخلها ولا فارقني فقال لها اليمين التي حلف بها لازمة لي إن لم أكن دخلت الطائف وبت عند جواري وغسلتهن جميعا وأخذ مني ثلاثمائة دينار وفعل كذا وكذا وحدثها الحديث كله وأراها الحلة والسرج فقالت لي أفعلتها يا أشعب أنا نفية من أبي إن أنفقتها إلا فيما يسوءك ثم أمرت بكبس منزلي وإحضارها الدنانير فأحضرت","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":14,"spl":"ابنه عبد الله يذكر بعض طرائفه"},
{"id":"b251-16","bab":"الجزء 19","sec":"ابنه عبد الله يذكر بعض طرائفه","page":"ج19 ص174","text":"فاشترت بها خشبا وبيضا وسرجينا وعملت من الخشب بيتا فحبستني فيه وحلفت ألا أخرج منه ولا أفارقه حتى أحضن البيض كله إلى أن ينقب فمكثت أربعين يوما أحضن لها البيض حتى نقب وخرج منه فراريج كثيرة فربتهن وتناسلن فكن بالمدينة يسمين بنات أشعب ونسل أشعب فهؤلاء إلى الآن بالمدينة نسل يزيد على الألوف كلهن أهلي وأقاربي قال إبراهيم فضحكت والله من قوله ضحكا ما أذكر أني ضحكت مثله قط ووصلته ولم يزل عندي زمانا حتى خرج إلى المدينة وبلغني أنه مات هناك أخبرني أحمد قال حدثنا مصعب بن عبد الله بن عثمان قال قال رجل لأشعب إن سالم بن عبد الله قد مضى إلى بستان فلان ومعه طعام كثير فبادر حتى لحقه فأغلق الغلام الباب دونه فتسور عليه فصاح به سالم بناتي ويلك بناتي فناداه أشعب ( لقد علمت مالنا في بناتك من حق وإنك لتعلم ما نريد\nفأمر بالطعام فأخرج إليه منه ما كفاه","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":15,"spl":"ابنه عبد الله يذكر بعض طرائفه — أشعب يقوقئ مثل الدجاجة"},
{"id":"b251-17","bab":"الجزء 19","sec":"أشعب يقوقئ مثل الدجاجة","page":"ج19 ص177","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن سعيد قال حدثنا الزبير بن بكار قال حدثني عمي قال بعثت سكينة إلى أبي الزناد فجاءها تستفتيه في شيء فاطلع أشعب عليه من بيت وجعل يقوقئ مثل ما تقوقئ الدجاجة قال فسبح أبو الزناد وقال ما هذا فضحكت وقالت إن هذا الخبيث أفسد علينا بعض أمرنا فحلفت أن يحضن بيضا في هذا البيت ولا يفارقه حتى ينقب فجعل أبو الزناد يعجب من فعلها\nوقد أخبرني محمد بن جعفر النحوي بخبر سكينة الطويل على غير هذه الرواية وهو قريب منها وقد ذكرته في أخبار سكينة بنت الحسين مفردا عن أخبار أشعب هذه في أخبارها مع زيد بن عمرو بن عثمان بن عفان أخبرني الحسن بن علي قال حدثنا أحمد بن أبي خيثمة قال حدثنا مصعب قال حدثني بعض المدنيين قال كان لأشعب خرق في بابه فكان ينام ثم يخرج يده من الخرق يطمع في أن يجيء إنسان يطرح في يده شيئا من شدة الطمع فبعث إليه بعض من كان يعبث به من مجان آل الزبير بعبد له فسلح في يده فلم يعد بعدها إلى أن يخرج يده وأخبرني به الجوهري عن ابن مهرويه عن محمد بن الحسن عن مصعب عن بعض المدنيين فذكر نحوه ولم يذكر ما فعل به الماجن أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن محمد الزبيري أبو طاهر قال حدثنا يحي بن محمد بن أبي قتيلة قال حدثني إسماعيل بن جعفر بن محمد الأعرج أن أشعب حدثه قال جاءني فتية من قريش فقالوا إنا نحب أن تسمع سالم بن عبد الله بن عمر صوتا من الغناء وتعلمنا ما يقول لك وجعلوا لي على ذلك جعلا فتنني فدخلت على سالم فقلت يا أبا عمر إن لي مجالسة وحرمة ومودة وسنا وأنا مولع بالترنم قال وما الترنم قلت الغناء قال في أي وقت قلت في الخلوة ومع الإخوان في المنزه فأحب ان أسمعك فإن كرهته أمسكت عنه وغنيته فقال ما أرى بأسا فخرجت فأعلمتهم قالوا وأي شيء غنيته قلت غنيته\n(قربا مربط النعامة مني ... لقحت حرب وائل عن حيالي)\nقالوا هذا بارد ولا حركة فيه ولسنا نرضى فلما رأيت دفعهم إياي وخفت ذهاب ما جعلوه لي رجعت فقلت يا أبا عمر آخر فقال مالي ولك فلم أملكه كلامه حتى غنيت فقال ما رأى بأسا فخرجت إليهم فأعلمتهم فقالوا وأي شيء غنيته فقلت غنيته قوله\n(لم يطيقوا أن ينزلوا ونزلنا ... وأخو الحرب من أطاق النزالا)\nفقالوا ليس هذا بشيء فرجعت إليه فقال مه قلت وآخر فلم أملكه أمره حتى غنيت\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nقال نهلا نهلا فقلت لا والله إلا بذاك السداك وفيه تمر عجوة من صدقة عمر فقال هو لك فخرجت به عليهم وأنا أخطر فقالوا مه فقلت غنيت الشيخ\n(غيضن من عبراتهن وقلن لي ... . . . .)\nطرب وفرض لي فأعطاني هذا وكذبتهم والله ما أعطانيه إلا استكفافا حتى صمت قال ابن أبي سعد السداك الزبيل الكبير وفرض لي أي نقطني يعني ما يهبه الناس للمغنين ويسمونه النقط","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":15,"spl":"ابنه عبد الله يذكر بعض طرائفه — أشعب يقوقئ مثل الدجاجة"},
{"id":"b251-18","bab":"الجزء 19","sec":"أشعب المغني","page":"ج19 ص180","text":"حدثني الجوهري قال حدثنا محمد بن القاسم قال حدثني قعنب بن المحرز عن الأصمعي قال حدثني جعفر بن سليمان قال قدم أشعب أيام أبي جعفر فأطاف به فتيان بني هاشم وسألوه أن يغنيهم فغنى فإذا ألحانه مطربة وحلقه على حاله فقال له جعفر بن المنصور لمن هذا الشعر والغناء\n(لمن طلل بذات الجيش ... أمسى دارسا خلقا)\nقال له أخذت الغناء عن معبد وهو للدلال ولقد كنت آخذ اللحن عن معبد فإذا سئل عنه قال عليكم بأشعب فإنه أحسن تأدية له مني أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن عبد الله بن مصعب قال قدم جرير المدينة فاجتمع إليه الناس يستنشدونه ويسألونه عن شعره فينشدهم ويأخذون عنه وينصرفون ولزمه أشعب من بينهم فلم يفارقه فقال له جرير أراك أطولهم جلوسا وأكثرهم سؤالا وإني لأظنك ألأمهم حسبا فقال له يا أبا حزرة أنا والله أنفعهم قال وكيف ذلك قال أنا آخذ شعرك فأحسنه وأجوده قال كيف تحسنه وتجوده قال فاندفع فغناه في شعره والغناء لابن سريج صوت يا أخت ناجية السلام عليكم ... قبل الرحيل وقبل لوم العذل\n(لو كنت أعلم أن آخر عهدكم ... يوم الرحيل فعلت ما لم أفعل)\nال فطرب جرير حتى بكى وجعل يزحف إليه حتى لصقت ركبته بركبته وقال أشهد أنك تحسنه وتجوده فأعطاه من شعره ما أراد ووصله بدنانير وكسوة حدثني أحمد بن عبد العزيز قال حدثنا محمد بن القاسم قال حدثني أبي قال الهيثم بن عدي لقيت أشعب فقلت له كيف ترى أهل زمانك هذا قال يسألونك عن أحاديث الملوك ويعطون إعطاء العبيد حدثني أحمد قال حدثني محمد بن القاسم حدثنا أحمد بن يحي قال أخبرنا مصعب قال حجت أم عمر بنت مروان فاستحجبت أشعب وقالت له أنت أعرف الناس بأهل المدينة فأذن لهم على مراتبهم وجلست لهم مليا ثم قامت فدخلت القائلة فجاء طويس فقال لأشعب استأذن لي على أم عمر فقال ما زالت جالسة وقد دخلت فقال له يا أشعب ملكت يومين فلم تفت بعرتين ولم تقطع شعرتين فدق أشعب الباب ودخل إليها فقال لها أنشدك الله يا بنة مروان هذا طويس بالباب فلا تتعرضي للسانه ولا تعرضيني فأذنت له فلما دخل إليها قال لها والله لئن كان بابك غلقا لقد كان باب أبيك فلقا ثم أخرج دفه ونقر به وغنى\n(ما تمنعني يقظى فقد تؤتينه ... في النوم غير مصرد محسوب)\n(كان المنى بلقائها فلقيتها ... فلهوت من لهو امرئ مكذوب)\nقالت أيهما أحب إليك العاجل أم الآجل فقال عاجل وآجل فأمرت له بكسوة أخبرني الجوهري قال حدثني ابن مهرويه عن أبي مسلم عن المدائني قال حدث رجل من أهل المدينة أشعب بحديث أعجبه فقال له في حديثك هذا شيء قال وما هو تقلبيه على الرأس","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":16,"spl":"أشعب المغني"},
{"id":"b251-19","bab":"الجزء 19","sec":"أشعب والوليد بن يزيد","page":"ج19 ص182","text":"أخبرني الجوهري قال حدثني ابن مهرويه قال أخبرنا أبو مسلم قال حدثنا المدائني قال بعث الوليد بن يزيد إلى أشعب بعدما طلق امرأته سعدة فقال له يا أشعب لك عندي عشرة آلاف درهم على أن تبلغ رسالتي سعدة فقال له أحضر المال حتى انظر إليه فأحضر الوليد بدرة فوضعها أشعب على عنقه ثم قال هات رسالتك يا أمير المؤمنين قال قل لها يقول لك\n(أسعدة هل إليك لنا سبيل ... وهل حتى القيامة من تلاقي)\n(بلى ولعل دهرا أن يواتي ... بموت من حليلك أو طلاق)\n(فأصبح شامتا وتقر عيني ... ويجمع شملنا بعد افتراق)\nقال فأتى أشعب الباب فأخبرت بمكانه فأمرت ففرشت لها فرش وجلست فأذنت له فدخل فأنشدها ما أمره فقالت لخدمها خذوا الفاسق فقال يا سيدتي إنها بعشرة آلاف درهم قالت والله لأقتلنك أو تبلغه كما بلغتني قال وما تهبين لي قالت بساطي الذي تحتي قال قومي عنه فقامت فطواه ثم قال هاتي رسالتك جعلت فداءك قالت قل له\n(أتبكي على لبنى وأنت تركتها ... فقد ذهبت لبنى فما أنت صانع)\nأقبل أشعب فدخل على الوليد فأنشده البيت فقال أوه قتلتني والله ما تراني صانعا بك يا بن الزانية اختر إما أن أدليك منكسا في بئر أو أرمي بك من فوق القصر منكسا أو أضرب رأسك بعمودي هذا ضربة فقال ما كنت فاعلا بي شيئا من ذلك قال ولم قال لأنك لم تكن لتعذب رأسا فيه عينان قد نظرتا إلى سعدة فقال صدقت يا بن الزانية اخرج عني وقد أخبرني بهذا الخبر محمد بن مزيد عن حماد عن أبيه عن الهيثم ابن عدي أن سعدة لما أنشدها أشعب قوله\n(أسعدة هل إليك لنا سبيل ... وهل حتى القيامة من تلاقي)\nالت لا والله لا يكون ذلك ابدا فلما أنشدها\n(بلى ولعل دهرا أن يواتي ... بموت من حليلك أو طلاق)\nالت كلا إن شاء الله بل يفعل الله ذلك به فلما أنشدها\n(فأصبح شامتا وتقر عيني ... ويجمع شملنا بعد افتراق)\nالت بل تكون الشماتة به وذكر باقي الخبر مثل حديث الجوهري عن ابن مهرويه أخبرني عمي قال حدثنا محمد بن سعد الكراني قال حدثنا العمري عن الهيثم بن عدي قال\nكتب الوليد بن يزيد في إشخاص أشعب من الحجاز إليه وحمله على البريد فحمل إليه فلما دخل أمر بأن يلبس تبانا ويجعل فيه ذنب قرد ويشد في رجليه أجراس وفي عنقه جلاجل ففعل به ذلك فدخل وهو عجب من العجب فلما رآه ضحك منه وكشف عن أيره قال أشعب فنظرت إليه كأنه ناي مدهون فقال لي اسجد للأصم ويلك يعني أيره فسجدت ثم رفعت رأسي وسجدت أخرى فقال ما هذا قلت الأولى للأصم والثانية لخصيتيك فضحك وأمر بنزع ما كان ألبسنيه ووصلني ولم أزل من ندمائه حتى قتل أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال قال رجل لأشعب إنه أهدي إلى زياد بن عبد الحارثي قبة أدم قيمتها عشرة آلاف درهم فقال امرأته الطلاق لو أنها قبة الإسلام ما ساوت ألف درهم فقيل له إن معها جبة وشي حشوها قز قيمتها عشرون ألف دينار فقال أمه زانية لو أن حشوها زغب أجنحة الملائكة ما ساوت عشرين دينارا أخبرني عمي قال حدثني أبو أيوب المدائني قال حدثني مصعب بن عبد الله الزبيري عن أبيه قال حدثني أشعب قال ولي المدينة رجل من ولد عامر بن لؤي وكان أبخل الناس وأنكدهم وأغراه الله بي يطلبني في ليله ونهاره فإن هربت منه هجم على منزلي بالشرط وإن كنت في موضع بعث إلى من أكون معه أو عنده يطلبني منه فيطالبني بأن أحدثه وأضحكه ثم لا أسكت ولا ينام ولا يطعمني ولا يعطيني فلقيت منه جهدا عظيما وبلاء شديدا وحضر الحج فقال لي يا أشعب كن معي فقلت بأبي أنت وأمي أنا عليل وليست لي نية في الحج فقال عليه وعليه","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":17,"spl":"أشعب والوليد بن يزيد"},
{"id":"b251-20","bab":"الجزء 19","sec":"أشعب والوليد بن يزيد","page":"ج19 ص182","text":"وقال إن الكعبة بيت النار لئن لم تخرج معي لأودعنك حيث أقدم فخرجت معه مكرها فلما نزلنا المنزل أظهر أنه صائم ونام حتى تشاغلت ثم أكل ما في سفرته وأمر غلامه أن يطعمني رغيفين بملح فجئت وعندي أنه صائم ولم أزل أنتظر المغرب أتوقع إفطاره فلما صليت المغرب قلت لغلامه ما ينتظر بالأكل قال قد أكل منذ زمان قلت أو لم يكن صائما قال لا قلت أفأطوي أنا قال قد أعد لك ما تأكله فكل وأخرج إلي الرغيفين والملح فأكلتها وبت ميتا جوعا وأصبحت فسرنا حتى نزلنا المنزل فقال لغلامه ابتع لنا لحما بدرهم فابتاعه فقال كبب لي قطعا ففعل فأكله ونصب القدر فلما أغبرت قال اغرف لي منها قطعا ففعل فأكلها ثم قال لي اطرح فيها دقة وأطعمني منها ففعل ثم قال ألق توابلها وأطعمني منها ففعل وأنا جالس أنظر إليه لا يدعوني فلما استوفى اللحم كله قال يا غلام أطعم أشعب ورمى إلي برغيفين فجئت إلى القدر وإذا ليس فيها إلا مرق وعظام فأكلت الرغيفين وأخرج له جرابا فيه فاكهة يابسة فأخذ منها حفنة فأكلها وبقي في كفه كف لوز بقشره ولم يكن له فيه حيلة فرمى به إلي وقال كل هذا يا أشعب فذهبت أكسر واحدة منها فإذا بضرسي قد انكسرت منه قطعة فسقطت بين يدي وتباعدت أطلب حجرا أكسره به فوجدته فضربت به لوزة فطفرت يعلم الله مقدار رمية حجر وعدوت في طلبها فبينما أنا في ذلك إذ أقبل بنو مصعب يعني ابن ثابت وإخوته يلبون بتلك الحلوق الجهورية فصحت بهم الغوث الغوث العياذ بالله وبكم يا آل الزبير الحقوني وأدركوني فركضوا إلي فلما رأوني قالوا أشعب مالك ويلك قلت خذوني معكم تخلصوني من الموت فحملوني معهم فجعلت أرفرف بيدي كما يفعل الفرخ إذا طلب الزق من أبويه فقالوا مالك ويلك قلت ليس هذا وقت الحديث زقوني مما معكم فقد مت ضرا وجوعا منذ ثلاث قال فأطعموني حتى تراجعت نفسي وحملوني معهم في محمل ثم قالوا أخبرنا بقصتك فحدثتهم وأريتهم ضرسي المكسورة فجعلوا يضحكون ويصفقون وقالوا ويلك من أين وقعت على هذا هذا من أبخل خلق الله\nوأدنئهم نفسا فحلفت بالطلاق أني لا أدخل المدينة ما دام له بها سلطان فلم أدخلها حتى عزل أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال حدثنا إبراهيم بن المهدي قال حدثني عبيدة بن أشعب قال كان الغاضري منذر أهل المدينة ومضحكهم قبل أبي فأسقطه أبي واطرح وكان الغاضري حسن الوجه ماد القامة عبلا فخما وكان أبي قصيرا دميما قليل اللحم إلا أنه كان يتضرم ويتوقد ذكاء وحدة وخفة روح وكان الغاضري يحسده إلا أنهما متساويان وكان الغاضري لقيطا منبوذا لا يعرف له أب فمر يوما ومعه فتية من قريش بأبي في المسجد وقد تأذى بثيابه فنزعها وتجرد وجلس عريانا فقال لهم الغاضري أنشدتكم الله هل رأيتم أعجب من هذه الخلقة يريد خلقة أبي فقال له أبي إن خلقتي لعجيبة وأعجب منها أنه زفني فصرت نضوا وزفك فصرت بختيا قال وأهل المدينة يسمون المهلوس من الفراخ النضو والمسرول البختي فغضب الغاضري عند ذلك وشتمه فسقط واستبرد وترك النوادر بعد ذلك وغلب أبي على أهل المدينة واستطابوه وكان هذا سببه","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":18,"spl":"أشعب والوليد بن يزيد"},
{"id":"b251-21","bab":"الجزء 19","sec":"أشعب وزياد بن عبد الله الحارثي","page":"ج19 ص186","text":"أخبرني جعفر بن قدامة قال حدثنا حماد بن إسحاق عن أبيه قال\nكان زياد بن عبد الله الحارثي أبخل خلق الله فأولم وليمة لطهر بعض أولاده وكان الناس يحضرون ويقدم الطعام فلا يأكلون منه إلا تعللا وتشعثا لعلمهم به فقدم فيما قدم جدي فلم يعرض له أحد وجعل يردده على المائدة ثلاثة أيام والناس يجتنبونه إلى أن انقضت الوليمة فأصغى أشعب إلى بعض من كان هناك فقال امرأته الطلاق إن لم يكن هذا الجدي بعد أن ذبح وشوي أطول عمرا وأمد حياة منه قبل أن يذبح فضحك الرجل وسمعها زياد فتغافل أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك بن إسحاق قال حدثني إبراهيم بن المهدي عن عبيدة بن أشعب قال غضبت سكينة على أبي في شيء خالفها فيه فحلفت لتحلقن لحيته ودعت بالحجام فقالت له احلق لحيته فقال له الحجام انفخ شدقيك حتى أتمكن منك فقال له يا بن البظراء أمرتك أن تحلق لحيتي أو تعلمني الزمر خبرني عن امرأتك إذا أردت أن تحلق حرها تنفخ أشداقه فغضب الحجام وحلف ألا يحلق لحيته وانصرف وبلغ سكينة الخبر وما جرى بينهما فضحكت وعفت عنه أخبرني محمد بن خلف بن المرزبان قال حدثني أبو العيناء عن الأصمعي قال أهدى كاتب لزياد بن عبد الله الحارثي إليه طعاما فأتي به وقد تغدى فغضب\nوقال ما أصنع به وقد أكلت ادعوا أهل الصفة يأكلونه فبعث إليهم وسأل كاتبه فيم دعا أهل الصفة فعرف فقال الكاتب عرفوه أن في السلال أخبصة وحلواء ودجاجا وفراخا فأخبر بذلك فأمر بكشفها فلما رآها أمر برفعها فرفعت وجاء أهل الصفة فأعلم فقال اضربوهم عشرين عشرين درة واحبسوهم فإنهم يفسون في مسجد رسول الله المصلين فكلم فيهم فقال حلفوهم ألا يعاودوا وأطلقوهم","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":19,"spl":"أشعب وزياد بن عبد الله الحارثي"},
{"id":"b251-22","bab":"الجزء 19","sec":"أشعب وأبان بن عثمان والأعرابي","page":"ج19 ص188","text":"أخبرني محمد بن مزيد قال حدثنا عمر بن شبة قال حدثنا ابن زبالة قال حدثنا ابن زنبج راوية ابن هرمة عن أبيه قال كان أبان بن عثمان من أهزل الناس وأعبثهم وبلغ من عبثه أنه كان يجيء بالليل إلى منزل رجل في أعلى المدينة له لقب يغضب منه فيقول له أنا فلان بن فلان ثم يهتف بلقبه فيشتمه أقبح شتم وأبان يضحك فبينما نحن ذات يوم عنده وعنده أشعب إذ أقبل أعرابي ومعه جمل له والأعرابي أشقر أزرق أزعر غضوب يتلظى كأنه أفعى ويتبين الشر في وجهه ما يدنو منه أحد إلا شتمه ونهره فقال أشعب لأبان هذا والله من البادية ادعوه فدعي وقيل له إن الأمير أبان بن عثمان يدعوك فأتاه فسلم عليه فسأله ابان عن نسبه فانتسب له فقال حياك الله يا\nخالي حبيب ازداد حبا فجلس فقال له إني في طلب جمل مثل جملك هذا منذ زمان فلم أجده كما أشتهي بهذه الصفة وهذه القامة واللون والصدر والورك والأخفاف فالحمد لله الذي جعل ظفري به من عند من أحبه أتبيعه فقال نعم أيها الأمير فقال فإني قد بذلت لك به مائة دينار وكان الجمل يساوي عشرة دنانير فطمع الأعرابي وسر وانتفخ وبان السرور والطمع في وجهه فأقبل أبان على أشعب ثم قال له ويلك يا أشعب إن خالي هذا من أهلك وأقاربك يعني في الطمع فأوسع له مما عندك فقال له نعم بأبي أنت وزيادة فقال له أبان يا خالي إنما زدتك في الثمن على بصيرة وإنما الجمل يساوي ستين دينارا ولكن بذلت لك مائة لقلة النقد عندنا وإني أعطيك بها عروضا تساوي مائة فزاد طمع الأعرابي وقال قد قبلت ذلك أيها الأمير فأسر إلى أشعب فأخرج شيئا مغطى فقال له أخرج ما جئت به فأخرج جرد عمامة خز خلق تساوي أربعة دراهم فقال له قومها يا أشعب فقال له عمامة الأمير تعرف به ويشهد فيها الأعياد والجمع ويلقى فيها الخلفاء خمسون دينارا فقال ضعها بين يديه وقال لابن زبنج أثبت قيمتها فكتب ذلك ووضعت العمامة بين يدي الأعرابي فكاد يدخل بعضه في بعض غيظا ولم يقدر على الكلام ثم قال هات قلنسوتي فأخرج قلنسوة طويلة خلقة قد علاها الوسخ والدهن وتخرقت تساوي نصف درهم فقال قوم فقال قلنسوة الأمير تعلو هامته ويصلي فيها الصلوات الخمس ويجلس للحكم ثلاثون دينارا قال أثبت فأثبت ذلك ووضعت القلنسوة بين يدي الأعرابي فتربد وجهه وجحظت عيناه وهم بالوثوب ثم تماسك وهو متقلقل ثم قال لأشعب هات ما عندك فأخرج خفين خلقين قد نقبا وتقشرا\nوتفتقا فقال له قوم فقال خفا الأمير يطأ بهما الروضة ويعلو بهما منبر النبي دينارا فقال ضعهما بين يديه فوضعهما ثم قال للأعرابي اضمم إليك متاعك وقال لبعض الأعوان اذهب فخذ الجمل وقال لآخر امض مع الأعرابي فاقبض منه ما بقي لنا عليه من ثمن المتاع وهو عشرون دينارا فوثب الأعرابي فأخذ القماش فضرب به وجوه القوم لا يألو في شدة الرمي به ثم قال له أتدري أصلحك الله من أي شيء أموت قال لا قال لم أدرك أباك عثمان فأشترك والله في دمه إذ ولد مثلك ثم نهض مثل المجنون حتى أخذ برأس بعيره وضحك أبان حتى سقط وضحك كل من كان معه وكان الأعرابي بعد ذلك إذا لقي أشعب يقول له هلم إلي يا بن الخبيثة حتى أكافئك على تقويمك المتاع يوم قوم فيهرب أشعب منه أخبرني جعفر بن قدامة قال حدثنا أحمد بن الحارث عن المدائني قال حدثني شيخ من أهل المدينة قال كانت بالمدينة عجوز شديدة العين لا تنظر إلى شيء تستحسنه إلا عانته فدخلت على أشعب وهو في الموت وهو يقول لبنته يا بنية إذا مت فلا تندبيني والناس يسمعونك فتقولين واأبتاه أندبك للصوم والصلوات واأبتاه أندبك للفقه والقراءة فيكذبك الناس ويلعنوني والتفت أشعب فرأى المرأة فغطى وجهه بكمه وقال لها يا فلانة بالله إن كنت استحسنت شيئا مما أنا فيه فصل على النبي تهلكيني فغضبت المرأة وقالت سخنت عينك في أي شيء أنت مما يستحسن أنت في آخر رمق قال قد علمت ولكن قلت لئلا تكوني قد استحسنت خفة الموت علي وسهولة النزع فيشتد ما أنا فيه وخرجت من عنده وهي تشتمه وضحك كل من كان حوله من كلامه ثم مات","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":20,"spl":"أشعب وأبان بن عثمان والأعرابي"},
{"id":"b251-23","bab":"الجزء 19","sec":"نماذج من طرائفه","page":"ج19 ص191","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن أبي طاهر قال حدثنا أبو أيوب المديني عن مصعب قال لاعب أشعب رجلا بالنرد فأشرف على أن يقمره إلا بضرب دويكين ووقع الفصان في يد ملاعبه فأصابه زمع وجزع فضرب يكين وضرط مع الضربة فقال له أشعب امرأته طالق إن لم أحسب لك الضرطة بنقطة حتى يصير لك اليكان دو ويك وتقمر وسلم له القمر بسبب الضرطة أخبرني الحسن قال حدثنا أحمد قال حدثني أبو أيوب عن حماد عن ابن إسحاق عن أبيه قال قال رجل لأشعب كان أبوك ألحى وأنت أثط فإلى من خرجت قال إلى أمي فمر الرجل وهو يعجب من جوابه وكان رجلا صالحا أخبرني هاشم بن محمد الخزاعي قال حدثني الرياشي قال سمعت أبا عاصم النبيل يقول رأيت أشعب وسأله رجل ما بلغ من طمعك قال ما زفت عروس بالمدينة إلى زوجها قط إلا فتحت بابي رجاء أن تهدى إلي أخبرني حبيب بن نصر المهلبي قال حدثنا الزبير بن بكار عن عمه قال تظلمت امرأة أشعب منه إلى أبي بكر محمد بن عمرو بن حزم وقالت لا يدعني أهدأ من كثرة الجماع فقال له أشعب أتراني أعلف ولا أركب لتكف ضرسها لأكف أيري\nقال وشكا خال لأشعب إليه امرأته وأنها تحزنه في ماله فقال له فديتك لا تأمنن قحبة ولو أنها أمك فانصرف عنه وهو يشتمه أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني قعنب بن المحرز عن الأصمعي عن جعفر بن سليمان قال قدم علينا أشعب أيام أبي جعفر فأطاف به فتيان بني هاشم وسألوه أن يغني فغناهم فإذا ألحانه مطربة وحلقه على حاله فسألوه لمن هذا اللحن\n(لمن طلل بذات الجيش وأمسى دارسا خلقا ... )\nقال للدلال وأخذته عن معبد ولقد كنت آخذ عنه الصوت فإذا سئل عنه قال عليكم بأشعب فإنه أحسن أداء له مني","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":21,"spl":"نماذج من طرائفه","partial":1},
{"id":"b251-24","bab":"الجزء 19","sec":"أشعب والحسن بن الحسن بن علي","page":"ج19 ص192","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال ذكر الزبير بن بكار عن شعيب بن عبيدة بن أشعب عن أبيه قال كان الحسن بن الحسن بن علي بن أبي طالب عليهم السلام يعبث بأبي أشد عبث وربما أراه في عبثه أنه قد ثمل وأنه يعربد عليه ثم يخرج إليه بسيف مسلول ويريه أنه يريد قتله فيجري بينهما في ذلك كل مستمع فهجره أبي مدة طويلة ثم لقيه يوما فقال له يا أشعب هجرتني وقطعتني ونسيت عهدي فقال له بأبي أنت وأمي لو كنت تعربد بغير السيف ما هجرتك ولكن ليس مع السيف لعب فقال له فأنا أعفيك من هذا فلا تراه مني أبدا وهذه عشرة دنانير ولك حماري الذي تحتي أحملك عليه وصر إلي ولك الشرط ألا ترى في داري\nسيفا قال لا والله أو تخرج كل سيف في دارك قبل أن نأكل ذلك لك قال قال فجاءه أبي ووفى له بما قال من الهبة وإخراج السيوف وخلف عنده سيفا في الدار فلما توسط الأمر قام إلى البيت فأخرج السيف مشهورا ثم قال يا أشعب إنما أخرجت هذا السيف لخير أريده بك قال بأبي أنت وأمي فأي خير يكون مع السيف ألست تذكر الشرط بيننا قال له فاسمع ما أقول لك لست أضربك به ولا يلحقك منه شيء تكرهه وإنما أريد أن أضجعك وأجلس على صدرك ثم آخذ جلدة حلقك بإصبعي من غير أن أقبض على عصب ولا ودج ولا مقتل فأحزها بالسيف ثم أقوم عن صدرك وأعطيك عشرين دينارا فقال نشدتك الله يا بن رسول الله ألا تفعل بي هذا وجعل يصرخ ويبكي ويستغيث والحسن لا يزيده على الحلف له أنه لا يقتله ولا يتجاوز به أن يحز جلده فقط ويتوعده مع ذلك بأنه إن لم يفعله طائعا فعله كارها حتى إذا طال الخطب بينهما واكتفى الحسن من المزح معه أراه أنه يتغافل عنه وقال له أنت لا تفعل هذا طائعا ولكن أجيء بحبل فأكتفك به ومضى كأنه يجيء بحبل فهرب أشعب وتسور حائطا بينه وبين عبد الله بن حسن أخيه فسقط إلى داره فانفكت رجله وأغمي عليه فخرج عبد الله فزعا فسأله عن قصته فأخبره فضحك منه وأمر له بعشرين دينارا وأقام في منزله يعالجه ويعوله إلى أن صلحت حاله قال وما رآه الحسن بن الحسن بعدها أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي قال\nدعا حسن بن حسن بن علي عليهم السلام أشعب فأقام عنده فقال لأشعب يوما أنا اشتهي كبد هذه الشاة لشاة عنده عزيزة عليه فارهه فقال له أشعب بأبي أنت وأمي أعطنيها وأنا أذبح لك أسمن شاة بالمدينة فقال أخبرك أني اشتهي كبد هذه وتقول لي أسمن شاة بالمدينة اذبح يا غلام فذبحها وشوى له من كبدها وأطايبها فأكل ثم قال لأشعب من الغد يا أشعب أنا أشتهي من كبد نجيبي هذا لنجيب كان عنده ثمنه ألوف دراهم فقال له أشعب يا سيدي في ثمن هذا والله غناي فأعطينه وأنا والله أطعمك من كبد كل جزور بالمدينة فقال أخبرك أني أشتهي من كبد هذا وتطعمني من غيره يا غلام انحر فنحر النجيب وشوى كبده فأكلا فلما كان اليوم الثالث قال له يا أشعب أنا والله أشتهي أن آكل من كبدك فقال له سبحان الله أتأكل من أكباد الناس قال قد أخبرتك فوثب أشعب فرمى بنفسه من درجة عالية فانكسرت رجله فقيل له ويلك أظننت أنه يذبحك فقال والله لو أن كبدي وجميع أكباد العالمين جميعا اشتهاها لأكلها وإنما فعل حسن بالشاة والنجيب ما فعل توطئة للعبث بأشعب تمت أخباره صوت\n(ألمت خناس وإلمامها ... أحاديث نفس وأحلامها)\n(يمانية من بني مالك ... تطاول في المجد أعمامها)\nلشعر لعويف القوافي الفزاري والغناء للهذلي رمل بالوسطى عن\nعمرو وذكر حماد بن إسحاق عن أبيه أن فيه لحنا لجميلة ولم يذكر طريقته وفيه لأبي العبيس بن حمدون خفيف ثقيل مطلق في مجرى الوسطى","topic":"ذكر أشعب وأخباره","topicNo":251,"sp":22,"spl":"أشعب والحسن بن الحسن بن علي"},
{"id":"b252-1","bab":"الجزء 19","sec":"أخبار عويف ونسبه","page":"ج19 ص196","text":"هو عويف بن معاوية بن عقبة بن حصن وقيل ابن عقبة بن عيينة بن حصن بن حذيفة بن بدر بن عمرو بن جؤية بن لوذان بن ثعلبة بن عدي بن فزارة ابن ذبيان بن بغيض بن ريث بن غطفان بن سعد بن قيس بن عيلان بن مضر بن نزار وعويف القوافي شاعر مقل من شعراء الدولة الأموية من ساكني الكوفة وبيته أحد البيوت المقدمة الفاخرة في العرب قال أبو عبيدة حدثني أبو عمرو بن العلاء أن العرب كانت تعد البيوتات المشهورة بالكبر والشرف من القبائل بعد بيت هاشم بن عبد مناف في قريش ثلاثة بيوت ومنهم من يقول أربعة أولها بيت آل حذيفة بن بدر الفزاري بيت قيس وبيت آل زرارة بن عدس الدارميين بيت تميم وبيت آل ذي الجدين بن عبد الله بن همام بيت شيبان وبيت بني الديان من بني الحارث بن كعب بيت اليمن وأما كندة فلا يعدون من أهل البيوتات إنما كانوا ملوكا وقال ابن الكلبي قال كسرى للنعمان هل في العرب قبيلة تشرف على قبيلة قال نعم قال بأبي شيء قال من كانت له ثلاثة آباء متوالية رؤساء ثم اتصل ذلك بكمال الرابع والبيت من قبيلته فيه قال فاطلب لي ذلك فطلبه\nفلم يصبه إلا في آل حذيفة بن بدر بيت قيس بن عيلان وآل حاجب بن زرارة بيت تميم وآل ذي الجدين ببيت شيبان وآل الأشعث بن قيس بيت كندة قال فجمع هؤلاء الرهط ومن تبعهم من عشائرهم فاقعد لهم الحكام العدول فأقبل من كل قوم منهم شاعرهم وقال لهم ليتكلم كل رجل منكم بمآثر قومه وفعالهم وليقل شاعرهم فيصدق فقام حذيفة بن بدر وكان أسن القوم وأجرأهم مقدما فقال لقد علمت معد أن منا الشرف الأقدم والعز الأعظم ومأثرة الصنيع الأكرم فقال من حوله ولم ذاك يا أخا فزارة فقال ألسنا الدعائم التي لا ترام والعز الذي لا يضام قيل له صدقت ثم قام شاعرهم فقال\n(فزارة بيت العز والعز فيهم ... فزارة قيس حسب قيس نضالها)\n(لها العزة القعساء والحسب الذي ... بناه لقيس في القديم رجالها)\n(فمن ذا إذا مد الأكف إلى العلا ... يمد بأخرى مثلها فينالها)\n(فهيهات قد أعيا القرون التي مضت ... مآثر قيس مجدها وفعالها)\n(وهل أحد إن مد يوما بكفه ... إلى الشمس في مجرى النجوم ينالها)\n(وإن يصلحوا يصلح لذاك جميعنا ... وإن يفسدوا يفسد على الناس حالها)\nم قام الأشعث بن قيس وإنما أذن له أن يقوم قبل ربيعة وتميم لقرابته\nبالنعمان فقال لقد علمت العرب أنا نقاتل عديدها الأكثر وقديم زحفها الأكبر وأنا غياث اللزبات فقالوا لم يا أخا كندة قال لأنا ورثنا ملك كندة فاستظللنا بأفيائه وتقلدنا منكبه الأعظم وتوسطنا بحبوحه الأكرم ثم قام شاعرهم فقال\n(إذا قست أبيات الرجال ببيتنا ... وجدت له فضلا على من يفاخر)\n(فمن قال كلا أو أتانا بخطة ... ينافرنا يوما فنحن نخاطر)\n(تعالوا فعدوا يعلم الناس أينا ... له الفضل فيما أورثته الأكابر)\nم قام بسطام بن قيس فقال لقد علمت ربيعة أنا بناة بيتها الذي لا يزول ومغرس عزها الذي لا ينقل قالوا ولم يا أخا شيبان قال لأنا أدركهم للثأر وأقتلهم للملك الجبار وأقولهم للحق وألدهم للخصم ثم قام شاعرهم فقال\n(لعمري لبسطام أحق بفضلها ... وأولى ببيت العز عز القبائل)\n(فسائل أبيت اللعن عن عز قومنا ... إذا جد يوم الفخر كل مناضل)\n(ألسنا أعز الناس قوما وأسرة ... وأضربهم للكبش بين القبائل)\n(فيخبرك الأقوام عنها فإنها ... وقائع ليست نهزة للقبائل)\n(وقائع عز كلها ربعية ... تذل لهم فيها رقاب المحافل)\n(إذا ذكرت لم ينكر الناس فضلها ... وعاذ بها من شرها كل قائل)\n(وإنا ملوك الناس في كل بلدة ... إذا نزلت بالناس إحدى الزلازل)\nم قام حاجب بن زرارة فقال لقد علمت معد أنا فرع دعامتها وقادة زحفها فقالوا له بم ذاك يا أخا بني تميم قال لأنا أكثر الناس إذا نسبنا عددا وأنجبهم ولدا وأنا أعطاهم للجزيل وأحملهم للثقيل ثم قام شاعرهم فقال\n(لقد عملت أبناء خندف أننا ... لنا العز قدما في الخطوب الأوائل)\n(وأنا هجان أهل مجد وثروة ... وعز قديم ليس بالمتضائل)\n(فكم فيهم من سيد وابن سيد ... أغر نجيب ذي فعال ونائل)\n(فسائل أبيت اللعن عنا فإننا ... دعائم هذا الناس عند الجلائل)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":0,"spl":"أخبار عويف ونسبه"},
{"id":"b252-2","bab":"الجزء 19","sec":"أخبار عويف ونسبه","page":"ج19 ص196","text":"ثم قام قيس بن عاصم فقال لقد علم هؤلاء أنا أرفعهم في المكرمات دعائم وأثبتهم في النائبات مقاوم قالوا ولم ذاك يا أخا بني سعد قال لأنا أمنعهم للجار وأدركهم للثأر وأنا لا ننكل إذ حملنا ولا نرام إذا حللنا ثم قام شاعرهم فقال\n(لقد علمت قيس وخندف كلها ... وجل تميم والجموع التي ترى)\n(بأنا عماد في الأمور وأننا ... لنا الشرف الضخم المركب في الندى)\n(وأنا ليوث الناس في كل مأزق ... إذا اجتر بالبيض الجماجم والطلى)\n(وأنا إذا داع دعانا لنجدة ... أجبنا سراعا في العلا ثم من دعا)\n(فمن ذا ليوم الفخر يعدل عاصما ... وقيسا إذا مد الأكف إلى العلا)\n(فهيهات قد أعيا الجميع فعالهم ... وفاتوا بيوم الفخر مسعاة من سعى)\nفلما سمع كسرى ذلك منهم قال ليس منهم إلا سيد يصلح لموضعه فأثنى حباءهم","topic":"أخبار عويف ونسبه","topicNo":252,"sp":1,"spl":"أخبار عويف ونسبه — سبب تسميته عويف القوافي"},
{"id":"b252-3","bab":"الجزء 19","sec":"سبب تسميته عويف القوافي","page":"ج19 ص200","text":"وإنما قيل لعويف عويف القوافي لبيت قاله نسخت خبره في ذلك من كتاب محمد بن الحسن بن دريد ولم أسمعه منه قال أخبرنا السكن بن سعيد عن محمد بن عباد عن ابن الكلبي قال أقبل عويف القوافي وهو عويف بن معاوية بن عقبة لن حصن بن حذيفة الفزاري وإنما قيل له عويف القوافي كما حدثني عمار بن أبان بن سعيد بن عيينة ببيت قاله\n(سأكذب من قد كان يزعم أنني ... إذا قلت قولا لا أجيد القوافيا)\nال فوقف على جرير بن عبد الله البجلي وهو في مجلسه فقال\n(أصب على بجيلة من شقاها ... هجائي حين أدركني المشيب)\nقال له جرير ألا أشتري منك أعراض بجيلة قال بلى قال بكم قال بألف درهم وبرذون فأمر له بما طلب فقال\n(لولا جرير هلكت بجيله ... نعم الفتى وبئست القبيله)\nقال جرير ما أراهم نجوا منك بعد نسخت من كتاب أبي سعيد السكري في كتاب من قال بيتا فلقب به قال أخبرني محمد بن حبيب قال وإنما قيل لعويف عويف القوافي لقوله\nوقد كان بعض الشعراء عيره بأنه لا يجيد الشعر فقال أبياتا منها\n(سأكذب من قد كان يزعم أنني ... إذا قلت شعرا لا أجيد القوافيا)\nسمي عويف القوافي","topic":"أخبار عويف ونسبه","topicNo":252,"sp":1,"spl":"أخبار عويف ونسبه — سبب تسميته عويف القوافي"},
{"id":"b252-4","bab":"الجزء 19","sec":"عويف وعبد الملك بن مروان","page":"ج19 ص201","text":"أخبرنا محمد بن خلف وكيع قال حدثني أحمد بن إسحاق عن أبيه قال حدثني عزيز بن طلحة بن عبد الله بن عثمان بن الأرقم المخزومي قال حدثني غير واحد من مشيخة قريش قالوا لم يكن رجل من ولاة أولاد عبد الملك بن مروان كان أنفس على قومه ولا أحسد لهم من الوليد بن عبد الملك فأذن يوما للناس فدخلوا عليه وأذن للشعراء فكان أول من بدر بين يديه عويف القوافي الفزاري فاستأذنه في الإنشاد فقال ما بقيت لي بعد ما قلت لأخي بني زهرة قال وما قلت له مع ما قلت لأمير المؤمنين قال ألست الذي تقول\n(يا طلح أنت أخو الندى وحليفه ... إن الندى من بعد طلحة ماتا)\n(إن الفعال إليك أطلق رحله ... فبحيث بت من المنازل باتا)\nو لست الذي تقول\n(إذا ما جاء يومك يا بن عوف ... فلا مطرت على الأرض السماء)\n(ولا سار البشير بغنم جيش ... ولا حملت على الطهر النساء)\n(تساقى الناس بعدك يا بن عوف ... ذريع الموت ليس له شفاء)\nألم تقم علينا الساعة يوم قامت عليه لا والله لا أسمع منك شيئا ولا أنفعك بنافعة أبدا أخرجوه عني فلما أخرج قال له القرشيون والشاميون وما الذي أعطاك طلحة حين استخرج هذا منك قال أما والله لقد أعطاني غيره أكثر من عطيته ولكن لا والله ما أعطاني أحد قط أحلى في قلبي ولا أبقى شكرا ولا أجدر ألا أنساها ما عرفت الصلات من عطيته قالوا وما أعطاك قال قدمت المدينة ومعي بضيعة لي لا تبلغ عشرة دنانير أريد أن أبتاع قعودا من قعدان الصدقة فإذا برجل في صحن السوق على طنفسة قد طرحت له وإذا الناس حوله وإذا بين يديه إبل معلوفة له فظننت أنه عامل السوق فسلمت عليه فأثبتني وجهلته فقلت أي رحمك الله هل أنت معيني ببصرك على قعود من هذه القعدان تبتاعه لي فقال نعم أو معك ثمنه فقلت نعم فأهوى بيده إلي فأعطيته بضيعتي فرفع طنفسته وألقاها تحتها ومكث طويلا ثم قمت إليه فقلت أي رحمك الله انظر في حاجتي فقال ما منعني منك إلا النسيان أمعك حبل قلت نعم قال هكذا أفرجوا فأفرجوا عنه حتى استقبل الإبل التي بين يديه فقال اقرن هذه وهذه وهذه فما برحت حتى أمر لي بثلاثين بكرة أدنى بكرة منها ولا دنية فيها خير من بضاعتي ثم رفع طنفسته فقال وشأنك ببضاعتك فاستعن بها على من ترجع إليه فقلت أي رحمك الله أتدري ما تقول فما بقي عنده إلا من نهرني وشتمني ثم بعث معي نفرا فأطردوها حتى أطلعوها من رأس الثنية فوالله لا أنساه ما دمت حيا أبدا وهذا الصوت المذكور تمثل به إبراهيم بن عبد الله بن حسن بن حسن بن علي يوم مقتله\nحدثني ابن عبيد الله بن عمار قال حدثني ميسرة بن سيار أبو محمد قال حدثني إبراهيم بن علي الرافقي عن المفضل الضبي وحدثنا يحي ابن علي بن يحي المنجم وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال حدثني عبد الملك بن سليمان عن علي بن الحسن عن المفضل الضبي ورواية ابن عمار أتم من هذه الرواية ونسخت هذا الخبر أيضا من بعض الكتب عن أبي حاتم السجستاني عن أبي عثمان اليقطري عن أبيه عن المفضل وهو أتم الروايات وأكثر اللفظ له قال قال المفضل خرجت مع إبراهيم بن عبد الله بن حسن بن حسن فلما صار بالمربد وقف على رأس سليمان بن علي فأخرج إليه صبيان من ولده فضمهم إليه وقال هؤلاء والله منا ونحن منهم إلا أن آباءهم فعلوا بنا وصنعوا وذكر كلاما يعتد عليهم فيه بالإساءة ثم توجه لوجهه وتمثل\n(مهلا بني عمنا ظلامتنا ... إن بنا سورة من القلق)\n(لمثلكم نحمل السيوف ولا ... تغمز أحسابنا من الدقق)\n(إني لأنمي إذا انتميت إلى ... عز عزيز ومعشر صدق)\n(بيض سباط كأن أعينهم ... تكحل يوم الهياج بالعلق)\nقلت ما أفحل هذه الأبيات فلمن هي قال لضرار بن الخطاب الفهري قالها يوم الخندق وتمثل بها علي بن أبي طالب عليه السلام يوم صفين والحسين بن علي يوم قتل وزيد بن علي عليهم السلام ولحق القوم ثم مضى إلى باخمرى فلما قرب منها أتاه نعي أخيه محمد فتمثل\n(نبئت أن بني ربيعة أجمعوا ... أمرا خلالهم لتقتل خالدا)\n(إن يقتلوني لا تصب أرماحهم ... ثأري ويسعى القوم سعيا جاهدا)\n(أرمي الطريق وإن صددت بضيقه ... وأنازل البطل الكمي الجاحدا)\nقلت لمن هذه الأبيات فقال للأحوص بن جعفر بن كلاب تمثل بها يوم شعب جبلة وهو اليوم الذي لقيت فيه قيس تميما قال وأقبلت عساكر أبي جعفر فقتل من أصحابه وقتل من القوم وكاد أن يكون الظفر له","topic":"أخبار عويف ونسبه","topicNo":252,"sp":2,"spl":"عويف وعبد الملك بن مروان"},
{"id":"b252-5","bab":"الجزء 19","sec":"عويف وعبد الملك بن مروان","page":"ج19 ص201","text":"قال ابن عمار في حديثه قال المفضل فقال لي حركني بشيء فأنشدته هذه الأبيات\n(ألا أيها الناهي فزارة بعد ما ... أجدت بسير إنما أنت حالم)\n(أبى كل حر أن يبيت بوتره ... ويمنع منه النوم إذا أنت نائم)\n(أقول لفتيان العشي تروحوا ... على الجرد في أفواههن الشكائم)\n(قفوا وقفة من يحي لا يخز بعدها ... ومن يخترم لا تتبعه اللوائم)\n(وهل أنت إن باعدت نفسك منهم ... لتسلم فيما بعد ذلك سالم)\nقال لي أعد فتنبهت وندمت فقلت أو غير ذلك فقال لا أعدها فأعدتها فتمطى في ركابيه حتى خلته قد قطعهما ثم خمل فكان آخر العهد به هذه رواية ابن عمار وفي الرواية الأخرى فحمل فطعن رجلا وطعنه آخر فقلت أتباشر الحرب بنفسك والعسكر منوط بك فقال إليك يا أخا بني ضبة كأن عويفا أخا بني فزارة نظر في يومنا هذا حيث يقول\n(ألمت خناس وإلمامها ... أحاديث نفس وأحلامها)\n(يمانية من بني مالك ... تطاول في المجد أعمامها)\n(وإن لنا أصل جرثومة ... ترد الحوادث أيامها)\n(ترد الكتيبة مغلولة ... بها أفنها وبها آمها)\nال وجاءه السهم العائر فشغله عني","topic":"أخبار عويف ونسبه","topicNo":252,"sp":3,"spl":"عويف وعبد الملك بن مروان — عويف وعمر بن عبد العزيز"},
{"id":"b252-6","bab":"الجزء 19","sec":"عويف وعمر بن عبد العزيز","page":"ج19 ص206","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني محمد بن معاوية الأسدي قال حدثني أصحابنا الأسديون عن أبي بردة بن أبي موسى الأشعري قال حضرت مع عمر بن عبد العزيز جنازة فلما انصرف انصرفت معه وعليه عمامة قد سدلها من خلفه فما علمت به حتى اعترضه رجل على بعير فصاح به\n(أجبني أبا حفص لقيت محمدا ... على حوضه مستبشرا ورآكا)\nقال له عمر لبيك وقف ووقف الناس معه ثم قال له فمه فقال\n(فأنت امرؤ كلتا يديك مفيدة ... شمالك خير من يمين سواكا)\nقال ثم مه فقال\n(بلغت مدى المجرين قبلك إذ جروا ... ولم يبلغ المجرمون بعد مداكا)\n(فجداك لا جدين أكرم منهما ... هناك تناهى المجد ثم هناكا)\nقال له عمر ألا أراك شاعرا مالك عندي من حق قال لا ولكني سائل وابن سبيل وذو سهمة فالتفت عمر إلى قهرمانه فقال أعطه فضل نفقتي\nقال وإذا هو عويف القوافي الفزاري أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال لما كان يوم ابن جرح واقتتلت بنو مرة وبنو حن بن عذرة قال عويف القوافي لبني مرة يهجوهم ويوبخهم بتركهم نصرهم\n(كنا لكم يا مر أما حفية ... وكنتم لنا يا مر بوا مجلدا)\n(وكنتم لنا سيفا وكنا وعاءه ... إذا نحن خفنا أن يكل فيغمدا)\nأجابه عقيل بن علفة بقصيدته التي أولها\n(أماوي إن الركب مرتحل غدا ... وحق ثوي نازل أن يزودا)\nقول فيها يخاطب عويفا\n(إذا قلت قد سامحت سهما ومازنا ... أبى النسب الداني وكفرهم اليدا)\n(وقد أسلموا أسناههم لقبيلة ... قضاعية يدعون حنا وأصيدا)\n(فما كنت أما بل جعلتك لي أخا ... وقد كنت في الناس الطريد المشردا)\n(عويف استها قد رمت ويلك مجدنا ... قديما فلم تعد الحمار المقيدا)\n(ولو أنني يوم ابن جرح لقيتهم ... لجردت في الأعداء عضبا مهندا)\nأبيات عويف هذه يقولها يوم مرج راهط وهي الحرب التي كانت بين قيس وكلب","topic":"أخبار عويف ونسبه","topicNo":252,"sp":3,"spl":"عويف وعبد الملك بن مروان — عويف وعمر بن عبد العزيز"},
{"id":"b252-7","bab":"الجزء 19","sec":"يوم مرج راهط","page":"ج19 ص208","text":"أخبرني بالسبب فيه أحمد بن عبد العزيز الجوهري قال أخبرني سليمان بن أيوب بن أعين أبو أيوب المديني قال حدثنا المدائني قال كان بدء حرب قيس وكلب في فتنة ابن الزبير ما كان من وقعة مرج راهط وكان قصة المرج أن مروان بن الحكم بن أبي العاص قدم بعد هلاك يزيد بن معاوية والناس يموجون وكان سعيد بن بحدل الكلبي على قنسرين فوثب عليه زفر بن الحارث فأخرجه منها وبايع لابن الزبير فلما قعد زفر على المنبر قال الحمد لله الذي أقعدني مقعد الغادر الفاجر وحصر فضحك الناس من قوله وكان النعمان بن بشير على حمص فبايع لابن الزبير وكان حسان بن بحدل على فلسطين والأردن فاستعمل على فلسطين روح بن زنباع الجذامي ونزل هو الأردن فوثب نابل بن قيس الجذامي على روح بن زنباع فأخرجه من فلسطين وبايع لابن الزبير\nوكان الضحاك بن قيس الفهري عاملا ليزيد بن معاوية على دمشق حتى هلك فجعل بقدم رجلا ويؤخر أخرى إذا جاءته اليمانية وشيعة بني أمية أخبرهم أنه أموي وإذا جاءته القيسية أخبرهم أنه يدعو إلى ابن الزبير فلما قدم مروان قال له الضحاك هل لك أن تقدم على ابن الزبير ببيعة أهل الشام قال نعم وخرج من عنده فلقيه عمرو بن سعيد بن العاص ومالك بن هبيرة وحصين بن نمير الكنديان وعبيد الله بن زياد فسألوه عما أخبره به الضحاك فأخبرهم فقالوا له أنت شيخ بني أمية وأنت عم الخليفة هلم نبايعك فلما فشا ذلك أرسل الضحاك إلى بني أمية يعتذر إليهم ويذكر حسن بلائهم عنده وأنه لم يرد شيئا يكرهونه فاجتمع مروان بن الحكم وعمرو بن سعيد بن العاص وخالد وعبد الله ابنا يزيد بن معاوية وقال لهم اكتبوا إلى حسان بن بحدل فليسر من الأردن حتى ينزل الجابية ونسير من ها هنا حتى نلقاه فيستخلف رجلا\nترضونه فكتبوا إلى حسان فأقبل في أهل الأردن وسار الضحاك بن قيس وبنو أمية في أهل دمشق فلما استقلت الرايات من جهة دمشق قالت القيسية للضحاك دعوتنا لبيعة ابن الزبير وهو رجل هذه الأمة فلما تابعناك خرجت تابعا لهذا الأعرابي من كلب تبايع لابن أخته تابعا له قال فتقولون ماذا قالوا نقول أن تنصرف وتظهر بيعة ابن الزبير ونظهرها معك فأجابهم إلى ذلك وسار حتى نزل مرج راهط وأقبل حسان حتى لقي مروان بن الحكم فسار حتى دخل دمشق فأتته اليمانية تشكر بلاء بني أمية فساروا مع مروان حتى نزلوا المرج على الضحاك وهم نحو سبعة آلفا والضحاك في نحو من ثلاثين ألاف فلقوا الضحاك فقتل الضحاك وقتل معه أشراف من قيس فأقبل زفر هاربا من وجهه ذاك حتى دخل قرقيسيا وأقام عمير بن الحباب شيئا على طاعة بني مروان ثم أقبل حتى دخل فرقيسيا على زفر فأقام معه وذلك بعد يوم خازر حين قتل عبيد الله بن زياد وأقبل زفر يبكي قتلى المرج ويقول\n(لعمري لقد أبقت وقيعة راهط ... لمروان صدعا بيننا متنائيا)\n(أتذهب كلب لم تنلها رماحنا ... ويترك قتلى راهط هي ماهيا)\n(فقد ينبت المرعى على دمن الثرى ... وتبقى حزازات النفوس كما هيا)\n(أبعد ابن صفر وابن عمرو تتابعا ... ومصرع همام أمني الأمانيا)\nقال ابن المخلاة الكلبي يجيبه\n(لعمري لقد أبقت وقيعة راهط ... على زفر داء من الداء باقيا)\n(تبكي على قتلى سليم وعامر ... وذبيان مغرورا وتبكي البواكيا)\nقال ابن المخلاة في يوم المرج\n(ويوم ترى الرايات فيه كأنها ... حوائم طير مستدير وواقع)\n(مضى أربع بعد اللقاء وأربع ... وبالمرج باق من دم القوم نافع)\n(طعنا زيادا في اسنته وهو مدبر ... وثور أصابته السيوف القواطع)\n(ونجى حبيشا ملهب ذو علالة ... وقد جذ من يمنى يديه الأصابع)\nقد شهد الصفين عمرو بن محرز ... فضاق عليه المرج والمرج واسع\nقال رجل من بني عذرة\n(سائل بني مروان أهل العج ... رهط النبي وولاة الحج)\n(عنا وعن قيس غداة المرج ... إذ يثقفون ثقفا بنج)\n(تسديس أطراف القنا المعوج ... إذ أخلف الضحاك ما يرجي)\n(مذ تركوا من بعد طول هرج ... لحم ابن قيس للضباع العرج)\nقال جواس بن القعطل الكلابي في يوم المرج\n(هم قتلوا براهط جد قيس ... سليما والقبائل من كلاب)\n(وهم قتلوا بني بدر وعبسا ... وألصق حر وجهك بالتراب)\n(تذكرت الدخول فلن تقضى ... ذحولك أو تساق إلى الحساب)\n(إذا سارت قبائل من جناب ... وعوف أشحنوا شم الهضاب)\n(وقد حاربتنا فوجدت حربا ... تغصك حين تشرب بالشراب)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":4,"spl":"يوم مرج راهط"},
{"id":"b252-8","bab":"الجزء 19","sec":"يوم مرج راهط","page":"ج19 ص208","text":"أقبل عمير يخطر فخرج من قرقيسيا يتطرف بوادي كلب فيغير عليها وعلى من أصاب من قضاعة وأهل اليمن ويخص كلبا ومعشر تغلب قبل أن تقع الحرب بين قيس وتغلب فجعل أهل البادية ينتصفون من أهل القرار كلهم فلما رأت كلب ما لقي أصحابهم وأنهم لا يمتنعون من خيل الحاضرة اجتمعوا إلى حميد بن حريث بن بحدل فسار بهم حتى نزلوا تدمر وبه بنو نمير وقد كان بين النميريين خاصة وبين الكلبيين الذين بتدمر عقد مع ابن بحدل بن بعاج الكلبي فأرسلت بنو نمير رسلا إلى حميد يناشدونه الحرمة فوثب عليهم ابن بعاج الكلبي فذبحهم وأرسلوا إليهم إنا قد قطعنا الذي بيننا وبينكم فالحقوا بما يسعكم من الأرض فالتقوا فقتل ابن بعاج وظفر بالنميريين فقتلوا قتلا ذريعا وأسروا فقال راعي الإبل في قتل ابن بعاج ولم يذكر غيره من الكلبيين\n(تجيء ابن بعاج نسور كأنها ... مجالس تبغي بيعة عند تاجر)\n(تطيف بكلبي عليه جدية ... طويل القرا يقذفنه في الحناجر)\n(يقول له من كان يعلم علمه ... كذاك انتقام الله من كل فاجر)\nقد كان زفر بن الحارث لما أغار عمير بن الحباب على الكلبيين قال يعيرهم بقوله\n(يا كلب قد كلب الزمان عليكم ... وأصابكم مني عذاب مرسل)\n(إن السماوة لا سماوة فالحقي ... بمنابت الزيتون وابني بحدل)\nبأرض عك والسواحل إنها ... أرض تذوب باللقاح وتهزل","topic":"أخبار عويف ونسبه","topicNo":252,"sp":5,"spl":"يوم مرج راهط"},
{"id":"b252-9","bab":"الجزء 19","sec":"حميد بن بحدل يغير على بوادي قيس","page":"ج19 ص213","text":"فجمع لهم حميد بن الحريث بن بحدل ثم خرج يريد الغارة على بوادي قيس فانتهى إلى ماء لبني تغلب فإذا النساء والصبيان يبكون فقالت لهم النساء وهن يحسبنهم قيسا ويحكم ما ردكم إلينا فقد فعلتم بنا بالأمس ما فعلتم فقالت لهم كلب ومالكم قالوا أغار علينا بالأمس عمير بن الحباب فقتل رجالنا واستاق أموالنا ولم يشككن أن الخيل خيل قيس وأن عميرا عاد إليهن فقال بعض كلب لحميد ما تريد من نسوة قد أغير عليهن وحربن وصبية يتامى وتدع عميرا فاتبعوه فبينا هم يسيرون إذ أ خذوا رجلا ربيئة للقوم فسألوه فقال لهم هذا الجيش هاهنا والأموال وقد خرج عمير في فوارس يريد الغارة على أهل بيت من بني زهير بن جناب أخبر عنهم مخبر فأقام حميد حتى جن عليه الليل ثم بيت القوم بياتا وقال حميد لأصحابه شعاركم نحن عباد الله حقا فأصابوا عامة ذلك العسكر ونجا فيمن نجا رجل عريان قذف ثوبه وجلس على فرس عري فلما انتهى إلى عمير قال عمير قد كنت أسمع بالنذير\nالعريان فلم أره فهو هذا ويلك مالك قال لا أدري غير أنه لقينا قوم فقتلوا من قتلوا وأخذوا العسكر فقال أفتعرفهم قال لا فقصد عمير القوم وقال لأصحابه إن كانت الأعاريب فسيسارعون إلينا إذا رأونا وإن كانت خيول أهل الشام فستقف وأقبل عمير فقال حميد لأصحابه لا يتحركن منكم أحد وانصبوا القنا فحمل عمير حملة لم تحركهم ثم حمل فلم يتحركوا فنادى مرارا ويحكم من أنتم فلم يتكلموا فنادى عمير أصحابه ويلكم خيل بني بحدل والأمانة انصرف على حاميته فحمل عليه فوارس من كلب يطلبونه ولحقه مولى لكلب يقال له شقرون فاطعنا فجرح عمير وهرب حتى دخل قرقيسيا إلى زفر ورجع حميد إلى من ظفر به من الأسرى والقتلى فقطع سبالهم وأنفهم فجلعها في خيط ثم ذهب بها إلى الشام وقال قائل بل بعث بها إلى عمير وقال كيف ترى أوقعي أم وقعك فقال في ذلك سنان بن جابر الجهني\n(لقد طار في الآفاق أن ابن بحدل ... حميدا شفى كلبا فقرت عيونها)\n(وعرف قيسا بالهوان ولم تكن ... لتنزع إلا عند أمر يهينها)\n(فقلت له قيس بن عيلان إنه ... سريع إذا ما عضت الحرب لينها)\n(سما بالعتاق الجرد من مرج راهط ... وتدمر ينوي بذلها لا يصونها)\n(فكان لها عرض السماوة ليلة ... سواء عليها سهلها وحزونها)\n(فمن يحتمل في شأن كلب ضغينة ... علينا إذا ما حان في الحرب حينها)\n(فإنا وكلبا كاليدين متى تضع ... شمالك في شي تعنها يمينها)\n(لقد تركت قتلى حميد بن بحدل ... كثيرا ضواحيها قليلا دفينها)\n(وقيسية قد طلقتها رماحنا ... تلفت كالصيداء أودى جنينها)\nقال سنان أيضا في هذا الأمر بعد ما أوقع ببني فزارة\n(يا أخت قيس سلي عنا علانية ... كي تخبري من بيان العلم تبيانا)\n(إنا ذوو حسب مال ومكرمة ... يوم الفخار وخير الناس فرسانا)\n(منا ابن مرة عمرو قد سمعت به ... غيث الأرامل لا يردين ما كانا)\n(والبحدلي الذي أردت فوارسه ... قيسا غداة اللوى من رمل عدنانا)\n(فغادرت حلبسا منها بمعترك ... والجعد منعفرا لم يكس أكفانا)\n(كائن تركنا غداة العاه من جزر ... للطير منهم ومن ثكلى وثكلانا)\n(ومن غوان تبكي لا حميم لها ... بالعاه تدعو بني عم وإخوانا)\nلما انتهى الخبر إلى عبد الملك بن مروان وعبد الله ومصعب يومئذ حيان وعند عبد الملك حسان بن مالك بن بحدل وعبد الله بن مسعدة بن\nحكم الفزاري وجيء بالطعام فقال عبد الملك لابن مسعدة ادن فقال ابن مسعدة لا والله لقد أوقع حميد بسليم وعامر وقعة لا ينفعني بعدها طعام حتى يكون لها غير فقال له حسان أجزعت أن كان بيني وبينكم في الحاضرة على الطاعة والمعصية فأصبنا منكم يوم المرج وأغار أهل قرقيسا بالحاضرة على البادية بغير ذنب فلما رأى حميد ذلك طلب بثأر قومه فأصاب بعض ما أصابهم فجزعت من ذلك وبلغ حميدا قول ابن مسعدة فقال والله لأشغلنه بمن هو أقرب إليه من سليم وعامر فخرج حميد في نحو من مائتي فارس ومعه رجلان من كلب دليلان حتى انتهى إلى بني فزارة أهل العمود لخمس عشرة مضت من شهر رمضان فقال بعثني عبد الملك بن مروان مصدقا فابعثوا إلى كل من يطيق أن يلقانا ففعلوا فقتلهم أو من استطاع منهم وأخذ أموالهم فبلغ قتلاهم نحوا من مائة ونيف فقال عويف القوافي\n(منا الله أن ألقى حميد بن بحدل ... بمنزلة فيها إلى النصف معلما)\n(لكيما نعاطيه ونبلو بيننا ... سريجية يعجمن في الهام معجما)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":6,"spl":"حميد بن بحدل يغير على بوادي قيس"},
{"id":"b252-10","bab":"الجزء 19","sec":"حميد بن بحدل يغير على بوادي قيس","page":"ج19 ص213","text":"(ألا ليت أني صادفتني منيتي ... ولم أر قتلى العام يا أم أسلما)\n(ولم أر قتلى لم تدع لي بعدها ... يدين فما أرجو من العيش أجذما)\n(وأقسم ما ليث بخفان خادر ... بأشجع من جعد جنانا ومقدما)\nعني الجعد بن عمران بن عيينة وقتل يومئذ","topic":"أخبار عويف ونسبه","topicNo":252,"sp":7,"spl":"حميد بن بحدل يغير على بوادي قيس"},
{"id":"b252-11","bab":"الجزء 19","sec":"أسماء بن خارجة يشكو حميدا إلى عبد الملك","page":"ج19 ص217","text":"فلما رجع عبد الملك من الكوفة وقتل مصعب لحقه أسماء بن خارجة بالنخيلة فكلمه فيما أتى حميد به إلى أهل العمود من فزارة وقال حدثنا أنه مصدقك وعاملك فأجبناك وبك عذنا فعليك وفي ذمتك ما على الحر في ذمته فأقدنا من قضاعي سكير فأبى عبد الملك وقال أنظر في ذلك وأستشير وحميد يجحد وليست لهم بينة فوداهم ألف ألف ومائتي ألف وقال إني حاسبها في أعطيات قضاعة فقال في ذلك عمرو بن مخلاة الكلبي صوت\n(خذوها يا بني ذبيان عقلا ... على الأجياد واعتقدوا الخداما)\n(دراهم من بني مروان بيضا ... ينجمها لكم عاما فعاما)\n(وأيقن أنه يوم طويل ... على قيس يذيقهم السماما)\n(ومختب أمام القوم يسعى ... كسرحان التنوفة حين ساما)\n(رأى شخصا على بلد بعيد ... فكبر حين أبصره وقاما)\n(وأقبل يسأل البشرى إلينا ... فقال رأيت إنسا أو نعاما)\n(وقال لخيله سيرى حميد ... فإن لكل ذي أجل حماما)\n(فما لاقيت من سجح وبدر ... ومرة فاتركي حطبا حطاما)\n(بكل مقلص عبل شواه ... يدق بوقع نابيه اللجاما)\n(وكل طمرة مرطى سبوح ... إذا ما شد فارسها الحزاما)\n(وقائلة على دهش وحزن ... وقد بلت مدامعها اللثاما)\n(كأن بني فزارة لم يكونوا ... ولم يرعوا بأرضهم الثماما)\n(ولم أر حاضرا منهم بشاء ... ولا من يملك النعم الركاما)\nال فلما أخذوا الدية انطلقت فزارة فاشترت خيلا وسلاحا ثم استتبعت سائر قبائل قيس ثم أغارت على ماء يدعى بنات قين يجمع بطونا من بطون كلب كثيرة وأكثر من عليه بنو عبد ود وبنو عليم بن جناب وعلى قيس يومئذ سعيد ابن عيينة بن حصن بن حذيفة بن بدر وحلحلة بن قيس بن الأشيم بن يسار أحد بني العشراء فلما أغاروا نادوا بني عليم إنا لا نطلبكم بشيء وإنما نطلب بني عبد ود بما صنع الدليلان اللذان حملا حميدا وهما المأمور ورجل آخر اسمه أبو أيوب فقتل من العبديين تسعة عشر رجلا ثم مالوا على العليميين فقتلوا منهم خمسين رجلا وساقوا أموالا\nفبلغ الخبر عبد الملك فأمهل حتى إذا ولي الحجاج العراق كتب إليه يبعث إليه سعيد بن عيينة وحلحلة بن قيس ومعهما نفر من الحرس فلما قدم بهما عليه قذفهما في السجن وقال لكلب والله لئن قتلتم رجلا لأهريقن دماءكم فقدم عليه من بني عبد ود عياض ومعاوية ابنا ورد ونعمان بن سويد وكان سويد أبوه ابن مالك يومئذ أشرف من قتل يوم بنات قين وكان شيخ بني عبد ود فقال له النعمان دماءنا يا أمير المؤمنين فقال له عبد الملك إنما قتل منكم الصبي الصغير والشيخ الفاني فقال النعمان قتل منا والله من لو كان أخا لأبيك لاختير عليك في الخلافة فغضب عبد الملك غضبا شديدا فقال له معاوية وعياض يا أمير المؤمنين شيخ كبير موتور فأعرض عنه عبد الملك وعرض الدية وجعل خالد بن يزيد بن معاوية ومن ولدته كلب يقولون القتل ومن كانت أمه قيسية من بني أمية يقولون لا بل الدية كما فعل بالقوم حتى ارتفع الكلام بينهم بالمقصورة فأخرجهم عبد الملك ودفع حلحلة إلى بعض بني عبد ود ودفع سعيد بن عيينة إلى بعض بني عليم وأقبل عليهما عبد الملك فقال ألم تأتياني تستعدياني فأعديتكما وأعطيتكما الدية ثم انطلقتما فأخفرتما ذمتي وصنعتما ما صنعتما فكلمه سعيد بكلام يستعطفه به ويرققه فضرب حلحلة صدره وقال أترى خضوعك لابن الزرقاء نافعك عنده فغضب عبد الملك وقال اصبر حلحلة فقال له أصبر من عود بجنبيه جلب فقتلا وشق ذلك على قيس وأعظمه أهل البادية منهم والحاضرة فقال في ذلك علي بن الغدير الغنوي\n(لحلحلة القتيل ولابن بدر ... وأهل دمشق أنجبة تبين)\n(فبعد اليوم أيام طوال ... وبعد خمود فتنتكم فتون)\n(وكل صنيعة رصد ليوم ... تحل به لصاحبها الزبون)\n(خليفة أمة قسرت عليه ... تخمط واستخف بمن يدين)\n(فقد أتيا حميد ابن المنايا ... وكل فتى ستشعبه المنون)\nقال رجل من بني عبد ود\n(نحن قتلنا سيدهم بشيخنا ... سويد فما كانا وفاء به دما)\nقال حلحلة وهو في السجن\n(لعمري لئن شيخا فزارة أسلما ... لقد خزيت قيس وما ظفرت كلب)\nقال أرطاة بن سهية يحرض قيسا\n(أيقتل شيخنا ويرى حميد ... رخي البال منتشيا خمورا)\n(فإن دمنا بذاك وطال عمر ... بنا وبكم و لم نسمع نكيرا)\n(فناكت أمها قيس جهارا ... وعضت بعدها مضر الأيورا)\nقالت عميرة بنت حسان الكلبية تفخر بفعل حميد في قيس\n(سمت كلب إلى قيس بجمع ... يهد مناكب الأكم الصعاب)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":8,"spl":"أسماء بن خارجة يشكو حميدا إلى عبد الملك"},
{"id":"b252-12","bab":"الجزء 19","sec":"أسماء بن خارجة يشكو حميدا إلى عبد الملك","page":"ج19 ص217","text":"(بذي لجب يدق الأرض حتى ... تضايق من دعا بهلا وهاب)\n(نفين إلى الجزيرة فل قيس ... إلى بق بها وإلى ذباب)\n(وألفينا هجين بني سليم ... يفدي المهر من حب الإياب)\n(فلولا عدوة المهر المفدى ... لأبت وأبت وأنت منخرق الإهاب)\n(ونجاه حثيث الركض منا ... أصيلانا ولون الوجه كابي)\n(وآض كأنه يطلى بورس ... ودق هوى كاسرة عقاب)\n(حمدت الله إذ لقي سليما ... على دهمان صقر بني جناب)\n(تركن الروق من فتيات قيس ... أيامى قد يئسن من الخضاب)\n(فهن إذا ذكرن حميد كلب ... نعقن برنة بعد انتحاب)\n(متى تذكر فتى كلب حميدا ... تر القيسي يشرق بالشراب)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":9,"spl":"أسماء بن خارجة يشكو حميدا إلى عبد الملك — عويف يمدح عيينة بن اسماء"},
{"id":"b252-13","bab":"الجزء 19","sec":"عويف يمدح عيينة بن اسماء","page":"ج19 ص221","text":"أخبرني محمد بن الحسن بن دريد قال أخبرني عبد الرحمن ابن أخي الأصمعي عن عمه قال أنشدني رجل من بني فزارة لعويف القوافي وهو عويف بن معاوية بن عقبة ابن حصن بن حذيفة الفزاري وكانت أخته عند عيينة بن أسماء بن خارجة فطلقها فكان عويف مراغما لعيينة وقال الحرة لا تطلق بغير ما بأس فلما حبس الحجاج عيينة وقيده قال عويف\n(منع الرقاد فما يحس رقاد ... خبر أتاك ونامت العواد)\n(خبر أتاني عن عيينة موجع ... ولمثله تتصدع الأكباد)\n(بلغ النفوس بلاؤها فكأننا ... موتى وفينا الروح والأجساد)\n(ساء الأقارب يوم ذاك فأصبحوا ... بهجين قد سروا به الحساد)\n(يرجون عثرة جدنا ولو أنهم ... لا يدفعون بنا المكاراه بادوا)\n(لما أتاني عن عيينة أنه ... عان تظاهر فوقه الأقياد)\n(نخلت له نفسي النصيحة إنه ... عند الشدائد تذهب الأحقاد)\n(وذكرت أي فتى يسد مكانه ... بالرفد حين تقاصر الأرفاد)\n(أم من يهين لنا كرائم ماله ... ولنا إذا عدنا إليه معاد)\n(لو كان من حضن تضاءل ركنه ... أو من نضاد بكت عليه نضاد)\nأخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال قال العتبي سأل عويف القوافي في حمالة فمر به عبد الرحمن بن محمد بن مروان\nوهو حديث السن فقال له لا تسأل أحدا وصر إلي أكفك فأتاه فاحتملها جمعاء له فقال عويف يمدحه\n(غلام رماه الله بالخير يافعا ... له سيمياء لا تشق على البصر)\n(كأن الثريا علقت في جبينه ... وفي حده الشعرى وفي جيده القمر)\n(ولما رأى المجد استعيرت ثيابه ... تردى رداء واسع الذيل واتزر)\n(إذا قيلت العوراء أغضى كأنه ... ذليل بلا ذل ولو شاء لا نتصر)\n(رآني فآساني ولو صد لم ألم ... على حين لا باد يرجى ولا حضر)\nقال أبو زيد هذه الأبيات لابن عنقاء الفزاري يقولها في ابن أخ له كان قوم من العرب أغاروا على نعم ابن عنقاء فاستاقوها حتى لم يبق له منها شيء فأتى ابن أخيه فقال له يا بن أخي إنه نزل بعمك ما ترى فهل من حلوبة قال نعم يا عم يروح المال وأبلغ مرادك فلما راح ماله قاسمه إياه وأعطاه شطره فقال ابن عنقاء\n(رآني على ما بي عميلة فاشتكى ... إلى ماله حالي أسر كما جهر)\nذكر بعد هذا البيت باقى الأبيات قال أبو زيد وإنما تمثلها عويف","topic":"أخبار عويف ونسبه","topicNo":252,"sp":9,"spl":"أسماء بن خارجة يشكو حميدا إلى عبد الملك — عويف يمدح عيينة بن اسماء"},
{"id":"b252-14","bab":"الجزء 19","sec":"عويف يمدح عمر بن عبد العزيز ويرثي سليمان بن عبد الملك","page":"ج19 ص223","text":"أخبرني محمد بن خلف وكيع والحسن بن علي قالا حدثنا الغلابي قالا حدثنا محمد بن عبيد الله عن عطاء بن مصعب عن عاصم بن الحدثان قال لما مات سليمان بن عبد الملك وولي عمر بن عبد العزيز الخلافة وفد\nحذف\nإليه عويف القوافي وقال شعرا رثى به سليمان ومدح عمر فيه فلما دخل إليه أنشده\n(لاح سحاب فرأينا برقه ... ثم تدانى فسمعنا صعقه)\n(وراحت الريح تزجي بلقه ... ودهمه ثم تزجي ورقه)\n(ذاك سقى قبرا فروى ودقه ... قبر امرىء عظم ربي حقه)\n(قبر سليمان الذي من عقه ... وجحد الخير الذي قد بقه)\n(في المسلمين جلة ودقه ... فارق في الجحود منه صدقه)\n(قد ابتلى الله بخير خلقه ... ألقى إلى خير قريش وسقه)\n(يا عمر الخير الملقى وفقه ... سميت بالفاروق فافرق فرقه)\n(وأرزق عيال المسلمين رزقه ... واقصد إلى الجود ولا توقه)\n(بحرك عذب الماء ما اعقه ... ربك فالمحروم من لم يسقه)\nقال له عمر لسنا من الشعر في شيء ومالك في بيت المال حق فألح عويف يسأله فقال يا مزاحم انظر فيما بقي من أرزاقنا فشاطره إياه ولنصبر على الضيق إلى وقت العطاء فقال له عبد الرحمن بن سليمان بن عبد الملك بل توفر يا أمير المؤمنين وعلي رضا الرجل فقال ما أولاك بذلك فأخذ بيده وانصرف به إلى منزله وأعطاه حتى رضي صوت\n(صفراء يطويها الضجيع لصلبها ... طي الحمالة لين مثناها)\n(نعم الضجيع إذا النجوم تغورت ... بالغور أولاها على أخراها)\n(عذب مقبلها وثير ردفها ... عبل شواها طيب مجناها)\n(يا دار صهباء التي لا أنتهي ... عن حبها أبدا ولا أنساها)\nلشعر لعبد الله بن جحش الصعاليك والغناء فيه لعلي بن هشام ثقيل أول بالوسطى من كتاب أحمد بن المكي","topic":"أخبار عويف ونسبه","topicNo":252,"sp":10,"spl":"عويف يمدح عمر بن عبد العزيز ويرثي سليمان بن عبد الملك — أخبار عبد الله بن جحش"},
{"id":"b252-15","bab":"الجزء 19","sec":"أخبار عبد الله بن جحش","page":"ج19 ص226","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا عمر بن شبة قال حدثني محمد بن يحيى أبو غسان عن غسان بن عبد الحميد قال كان بالمدينة امرأة يقال لها صهباء من أحسن الناس وجها وكانت من هذيل فتزوجها ابن عم لها فمكث حينا معها لا يقدر عليها من شدة ارتتاقها فأبغضته وطالبته بالطلاق فطلقها ثم أصاب الناس مطر شديد في الخريف فسال العقيق سيلا عظيما وخرج أهل المدينة وخرجت صهباء معهم فصادفت عبد الله بن جحش وأصحابه في نزهة فرآها وافترقا ثم مضت إلى أقصى الوادي فاستنقعت في الماء وقد تفرق الناس وخفوا فاجتاز بها ابن جحش فرآها فتهالك عليها وهام بها وكان بالمدينة امرأة تدل على النساء يقال لها قطنة كانت تداخل القرشيات وغيرهن فلقيها ابن جحش فقال لها اخطبي علي صهباء فقالت قد خطبها عيسى بن طلحة بن عبيد الله وأجابوه ولا أراهم يختارونك عليه فشتمها ابن جحش وقال لها كل مملوك له\nفهو حر لئن لم تحتالي فيها حتى أتزوجها لأضربنك ضربة بالسيف وكان مقداما جسورا ففرقت منه فدخلت على صهباء وأهلها فتحدثت معهم ثم ذكرت ابن عمها فقالت لعمة صهباء ما باله فارقها فأخبرتها خبرها وقالت لم يقدر عليها وعجز عنها فقالت لها وأسمعت صهباء إن هذا ليعتري كثيرا من الرجال فلا ينبغي أن تتقدموا في أمرها إلا على من تختبرونه وأما والله لو كان ابن جحش لصهباء لثقبها ثقب اللؤلؤ ولو رتقت بحجر ثم خرجت من عندهم فأرسلت إليها صهباء مري ابن جحش فليخطبني فلقيته قطنة فأخبرته الخبر فمضى فخطبها فأنعمت له وأبى أهلها إلا عيسى بن طلحة وأبت هي إلا ابن جحش فتزوجته ودخل بها وافتضها وأحب كل واحد منهما صاحبه فقال فيها\n(نعم الضجيع إذا النجوم تغورت ... بالغور أولاها على أخراها)\n(عذب مقبلها وثير ردفها ... عبل شواها طيب مجناها)\n(صفراء يطويها الضجيع لجنبها ... طي الحمالة لين متناها)\n(لو يستطيع ضجيعها لأجنها ... في الجوف حب نسميها ونشاها)\n(يا دار صهباء التي لا أنتهي ... عن ذكرها أبدا ولا أنساها)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":10,"spl":"عويف يمدح عمر بن عبد العزيز ويرثي سليمان بن عبد الملك — أخبار عبد الله بن جحش"},
{"id":"b252-16","bab":"الجزء 19","sec":"عبد الملك بن مروان يعجب بشعره","page":"ج19 ص227","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني عبد الرحيم بن أحمد بن زيد بن الفرج قال حدثني محمد بن عبد الله قال كان عبد الملك بن مروان معجبا بشعر عبد الله بن جحش فكتب إليه يأمره بالقدوم عليه فورد كتابه وقد توفي فقال إخوانه لابنه\nلو شخصت إلى أمير المؤمنين عن إذنه لأبيك لعله كان ينفعك ففعل فبينا هو في طريقه إذ ضاع منه كتاب الإذن فهم بالرجوع ثم مضى لوجهه فلما قدم على عبد الملك سأله عن أبيه فأخبره بوفاته ثم سأله عن كتابه فأخبره بضياعه فقال له أنشدني قول أبيك صوت\n(هل يبلغنها السلام أربعة ... مني وإن يفعلوا فقد نفعوا)\n(على مصكين من جمالهم ... وعنتريسين فيهما سطع)\n(حرب جيراننا جمالهم ... صبحا فأضحوا بها قد انتجعوا)\n(ما كنت أدري بوشك بينهم ... حتى رأيت الحداة قد طلعوا)\n(قد كاد قلبي والعين تبصرهم ... لما تولى بالقوم ينصدع)\n(ساروا وخلفت بعدهم دنفا ... أليس بالله بئس ما صنعوا)\nال لا والله يا أمير المؤمنين ما أرويه قال لا عليك فأنشدني قول أبيك صوت\n(أجد اليوم جيرتك الغيارا ... رواحا أم أرادوه ابتكارا)\n(بعينك كان ذاك وإن يبينوا ... يزدك البين صدعا مستطارا)\n(بلى أبقت من الجيران عندي ... أناسا ما أوافقهم كثارا)\n(وماذا كثرة الجيران تغني ... إذا ما بان من أهوى فسارا)\nال لا والله ما أرويه يا أمير المؤمنين قال ولا عليك فأنشدني قول أبيك\n(دار لصهباء التي لا ينثني ... عن ذكرها قلبي ولا أنساها)\n(صفراء يطويها الضجيع لصلبها ... طي الحمالة لين متناها)\n(لو يستطيع ضجيعها لأجنها ... في القلب شهوة ريحها ونشاها)\nقال لا والله يا أمير المؤمنين ما أرويه وإن صهباء هذه لأمي قال ولا عليك قد يبغض الرجل أن يشبب بأمه ولكن إذا نسب بها غير أبيه فأف لك ورحم الله أباك فقد ضيعت أدبه وعققته إذ لم ترو شعره اخرج فلا شيء لك عندنا صوت\n(أماطت كساء الخز عن حر وجهها ... وأدنت على الخدين بردا مهلهلا)\n(من اللاء لم يحججن يبغين حسبة ... ولكن يقتلن البريء المغفلا)\n(رأتني خضيب الرأس شمرت مئزري ... وقد عهدتني أسود الرأس مسبلا)\n(خطوا إلى اللذات أجررت مئزري ... كإجرارك الحبل الجواد المحجلا)\n(صريع الهوى لا يبرح الحب قائدي ... بشر فلم أعدل عن الشر معدلا)\n(لدى الجمرة القصوى فريعت وهللت ... ومن ريع في حج من الناس هللا)\nالشعر للعرجي والغناء لعبد الله بن العباس الربيعي ثقيل أول في الأول والثاني والخامس والسادس من هذه الأبيات وهو من جيد الغناء وفاخر الصنعة ويقال إنه أول شعر صنعه ولعزار المكي في الثالث وما بعده ثاني ثقيل عن يحي المكي وغيره وفيه خفيف ثقيل ينسب إلى معبد وإلى ابن سريج وإلى\nالغريض وفيه لإبراهيم لحن من كتابه غير مجنس وأنا ذاكر هاهنا أخبارا لهذا الشعر من أخبار العرجي إذ كان أكثر أخباره قد مضى سوى هذه","topic":"أخبار عويف ونسبه","topicNo":252,"sp":11,"spl":"عبد الملك بن مروان يعجب بشعره"},
{"id":"b252-17","bab":"الجزء 19","sec":"بعض أخبار للعرجي","page":"ج19 ص231","text":"أخبرني محمد بن خلف وكيع قال حدثنا إسماعيل بن مجمع عن المدائني عن عبد الله بن سليم قال قال عبيد الله بن عمر العمري خرجت حاجا فرأيت امرأة جميلة تتكلم بكلام رفثت فيه فأدنيت ناقتي منها ثم قلت لها يا أمة الله ألست حاجة أما تخافين الله فسفرت عن وجه يبهر الشمس حسنا ثم قالت تأمل يا عمي فإني ممن عنى العرجي بقوله\n(من اللاء لم يحججن يبغين حسبة ... ولكن ليقتلن البريء المغفلا)\nال فقلت لها فإني أسأل الله ألا يعذب هذا الوجه بالنار قال وبلغ ذلك سعيد بن المسيب فقال أما والله لو كان من بعض بغضاء أهل العراق لقال لها\nاعزبي قبحك الله ولكنه ظرف عباد الحجاز وقد رويت هذه الحكاية عن أبي حازم بن دينار أخبرني به وكيع قال حدثنا أحمد بن زهير قال حدثنا مصعب الزبيري قال حدثني عبد الرحمن بن أبي الحسن وقد روى عنه ابن أبي ذئب قال بينا أبو حازم يرمي الجمار إذ هو بامرأة متشعبذة يعني حاسرة فقال لها أيتها المرأة استتري فقالت إني والله من اللواتي قال فيهن الشاعر قوله\n(من اللاء لم يحججن يبغين حسبة ... ولكن ليقتلن البريء المغفلا)\n(وترمي بعينيها القلوب ولا ترى ... لها رمية لم تصم منهن مقتلا)\nقال أبو حازم لأصحابه ادعوا الله لهذه الصورة الحسنة ألا يعذبها بالنار وأبو حازم هذا هو أبو حازم بن دينار من وجوه التابعين قد روى عن سهل بن سعد وأبي هريرة وروى عنه مالك وابن أبي ذئب ونظراؤهما حدثني عمي قال حدثني الكراني قال حدثني العمري عن العتبي عن الحكم بن صخر قال انصرفت من منى فسمعت زفنا من بعض المحامل ثم ترنمت جارية فتغنت\n(من اللاء لم يحججن يبغين حسبة ... ولكن ليقتلن البريء المغفلا)\nفقلت لها أهذا مكان هذا يرحمك الله فقالت نعم وإياك أن تكونه","topic":"أخبار عويف ونسبه","topicNo":252,"sp":12,"spl":"بعض أخبار للعرجي — شعره مطبوع وهو مغن جيد الصنعة"},
{"id":"b252-18","bab":"الجزء 19","sec":"أخبار عبد الله بن العباس الربيعي","page":"ج19 ص233","text":"عبد الله بن العباس بن الفضل بن الربيع والربيع على ما يدعيه أهله ابن يونس بن أبي فروة وقيل إنه ليس ابنه وآل أبي فروة يدفعون ذلك ويزعمون أنه لقيط وجد منبوذا فكفله يونس بن أبي فروة ورباه فلما خدم المنصور ادعى إليه وأخباره مذكورة مع أخبار ابنه الفضل في شعر يغنى به من شعر الفضل وهو\n(كنت صبا وقلبي اليوم سالي ... )\nيكنى عبد الله بن العباس أبا العباس","topic":"أخبار عويف ونسبه","topicNo":252,"sp":12,"spl":"بعض أخبار للعرجي — شعره مطبوع وهو مغن جيد الصنعة","partial":1},
{"id":"b252-19","bab":"الجزء 19","sec":"شعره مطبوع وهو مغن جيد الصنعة","page":"ج19 ص234","text":"وكان شاعرا مطبوعا ومغنيا محسنا جيد الصنعة نادرها حسن الرواية حلو الشعر ظريفه ليس من الشعر الجيد الجزل ولا من المرذول ولكنه شعر مطبوع ظريف مليح المذهب من أشعار المترفين وأولاد النعم حدثني أبو القاسم الشيربابكي وكان نديما لجدي يحي بن محمد عن يحي بن حازم قال حدثني عبد الله بن العباس الربيعي قال\nدخل محمد بن عبد الملك الزيات عن الواثق وأنا بين يديه أغنيه وقد استعادني صوتا فاستحسنه فقال له محمد بن عبد الملك هذا والله يا أمير المؤمنين أولى الناس بإقبالك عليه واستحسانك له واصطناعك إياه فقال أجل هذا مولاي وابن مولاي وابن موالي لا يعرفون غير ذلك فقال له ليس كل مولى يا أمير المؤمنين بولي لمواليه ولا كل مولى متجمل بولائه يجمع ما جمع عبد الله من ظرف وأدب وصحة عقل وجودة شعر فقال الحسن له صدقت يا محمد فلما كان من الغد جئت محمد بن عبد الملك شاكرا لمحضره فقلت له في أضعاف كلامي وأفرط الوزير أعزه الله في وصفي وتقريظي بكل شيء حتى وصفني بجودة الشعر وليس ذلك عندي وإنما أعبث بالبيتين والثلاثة ولو كان عندي أيضا شيء بعد ذلك لصغر عن أن يصفه الوزير ومحله في هذا الباب المحل الرفيع المشهور فقال والله يا أخي لو عرفت مقدار شعرك وقولك\n(يا شادنا رام إذ مر ... في السعانين قتلي)\n(يقول لي كيف أصبحت ... كيف يصبح مثلي)\nما قلت هذا القول والله لو لم يكن لك شعر في عمرك كله إلا قولك كيف يصبح مثلي لكنت شاعرا مجيدا حدثني جحظة قال حدثني أحمد بن الطيب قال حدثني حماد بن إسحاق قال\nسمعت عبد الله بن العباس الربيعي يقول أنا أول من غنى بالكنكلة في الإسلام ووضعت هذا الصوت عليها\n(أتاني يؤامرني في الصبوح ... ليلا فقلت له غادها)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":12,"spl":"بعض أخبار للعرجي — شعره مطبوع وهو مغن جيد الصنعة"},
{"id":"b252-20","bab":"الجزء 19","sec":"سبب تعلمه الغناء","page":"ج19 ص236","text":"حدثني جعفر بن قدامة قال حدثناعلي بن يحي المنجم قال حدثني عبد الله بن العباس الربيع يقال كان سبب دخولي في الغناء وتعلمي إياه أني كنت أهوى جارية لعمتي رقية بنت الفضل بن الربيع فكنت لا أقدر على ملازمتها والجلوس معها خوفا من أن يظهر ما لها عندي فيكون ذلك سبب منعي منها فأظهرت لعمتي أنني أشتهي أن أتعلم الغناء ويكون ذلك في ستر عن جدي وكان جدي وعمتي في حال من الرقة علي والمحبة لي لا نهاية وراءها لأن أبي توفي في حياة جدي الفضل فقالت يا بني وما دعاك إلى ذلك فقلت شهوة غلبت على قلبي إن منعت منها مت غما وكان لي في الغناء طبع قوي فقالت لي أنت أعلم وما تختاره والله ما أحب منعك من شيء وإني لكارهة أن تحذق ذلك وتشهر به فتسقط ويفتضح أبوك وجدك فقلت لا تخافي ذلك فإنما آخذ منه مقدار ما ألهو به ولا زمت الجارية لمحبتي إياها بعلة الغناء فكنت آخذ عنها وعن صواحباتها حتى تقدمت الجماعة حذقا وأقررن لي بذلك وبلغت ما كنت أريد من أمر الجارية وصرت ألازم مجلس جدي فكان يسر بذلك ويظنه تقربا مني إليه وإنما كان وكدي فيه أخذ الغناء فلم يكن يمر لإسحاق ولا لابن جامع ولا للزبير بن دحمان ولا لغيرهم صوت إلا أخذته فكنت سريع الأخذ وإنما كنت أسمعه مرتين أو ثلاثا وقد صح\nلي وأحسست من نفسي قوة في الصناعة فصنعت أول صوت صنعته في شعر العرجي\n(أماطت كساء الخز عن حر وجهها ... وأدنت على الخدين بردا مهلهلا)\nم صنعت في\n(أقفر من بعد خلة سرف ... فالمنحنى فالعقيق فالجرف)\nعرضتهما على الجارية التي كنت أهواها وسألتها عما عندها فيهما فقالت لا يجوز أن يكون في الصنعة شيء فوق هذا وكان جواري الحارث بن بسخنر وجواري ابنه محمد يدخلن إلى دارنا فيطرحن على جواري عمتي\nوجواري جدي ويأخذن أيضا مني ما ليس عندهن من غناء دارنا فسمعنني ألقي هذين الصوتين على الجارية فأخذنهما مني وسألن الجارية عنهما فأخبرتهن أنهما من صنعتي فسألنها أن تصححهما لهن ففعلت فأخذنهما عنها ثم اشتهر حتى غني الرشيد بهما يوما فاستظرفهما وسأل إسحاق هل تعرفهما فقال لا وإنهما لمن حسن الصنعة وجيدها ومتقنها ثم سأل الجارية عنهما فتوقفت خوفا من عمتي وحذرا أن يبلغ جدي أنها ذكرتني فانتهرها الرشيد فأخبرته بالقصة فوجه من وقته فدعا بجدي فلما أحضره قال له يا فضل يكون لك ابن يغني ثم يبلغ في الغناء المبلغ الذي يمكنه معه أن يصنع صوتين يستحسنهما إسحاق وسائر المغنين ويتداولهما جواري القيان ولا تعلمني بذلك كأنك رفعت قدره عن خدمتي في هذا الشأن فقال له جدي وحق ولائك يا أمير المؤمنين ونعمتك وإلا فأنا نفي منهما برىء من بيعتك وعلي العهد والميثاق والعتق والطلاق إن كنت علمت بشيء من هذا قط إلا منك الساعة فمن هذا من ولدي قال عبد الله ابن العباس هو فأحضرنيه الساعة فجاء جدي وهو يكاد أن ينشق غيظا فدعاني فلما خرجت إليه شتمني وقال يا كلب بلغ من أمرك ومقدارك أن تجسر على أن تتعلم الغناء بغير إذني ثم زاد ذلك حتى صنعت ولم تقنع بهذا حتى ألقيت صنعتك على الجواري في داري ثم تجاوزتهن إلى جواري الحارث بن بسخنر فاشتهرت وبلغ أمرك أمير المؤمنين فتنكر لي ولا مني وفضحت آباءك في قبورهم وسقطت الأبد إلا من المغنين وطبقة الخنياكرين فبكيت غما بما جرى وعلمت أنه قد صدق فرحمني وضمني إليه وقال قد صارت الآن مصيبتي في أبيك مصيبتين إحداهما به وقد مضى وفات والأخرى بك وهي موصولة بحياتي ومصيبة باقية العار علي وعلى أهلي بعدي وبكى وقال عز علي يا بني أن أراك أبدا ما بقيت على غير ما أحب وليست لي في هذا الأمر حيلة لأنه أمر قد خرج عن يدي ثم قال جئني بعود حتى أسمعك وأنظر كيف أنت فإن كنت\nتصلح للخدمة في هذه الفضيحة وإلا جئته بك منفردا وعرفته خبرك واستعفيته لك فأتيته بعود وغنيته غناء قديما فقال لا بل غن صوتيك اللذين صنعتهما فغنيته إياهما فاستحسنهما وبكى ثم قال بطلت والله يا بني وخاب أملي فيك فواحزني عليك وعلى أبيك فقلت له يا سيدي ليتني مت من قبل أنكرته أو خرست ومالي حيلة ولكني وحياتك يا سيدي وإلا فعلي عهد الله وميثاقه والعتق والطلاق وكل يمين يحلف بها حالف لازمة لي لا غنيت أبدا إلا لخليفة أو ولي عهد فقال قد أحسنت فيما نبهت عليه من هذا","topic":"أخبار عويف ونسبه","topicNo":252,"sp":13,"spl":"سبب تعلمه الغناء"},
{"id":"b252-21","bab":"الجزء 19","sec":"الرشيد يطرب له ويجيزه","page":"ج19 ص239","text":"ثم ركب وأمرني فأحضرت فوقفت بين يدي الرشيد وأنا أرعد فاستدناني حتى صرت أقرب الجماعة إليه ومازحني وأقبل علي وسكن مني وأمر جدي بالانصراف وأمر الجماعة فحدثوني وسقيت أقداحا وغنى المغنون جميعا فأومأ إلي إسحاق الموصلي بعينه أن أبدأ فغن إذا بلغت النوبة إليك قبل أن تؤمر بذلك ليكون ذلك أصلح وأجود بك فلما جاءت النوبة إلي أخذت عودا ممن كان إلى جنبي وقمت قائما واستأذنت في الغناء فضحك الرشيد وقال غن جالسا فجلست وغنيت لحني الأول فطرب واستعاده ثلاث مرات وشرب عليه ثلاثة أنصاف ثم غنيت الثاني فكانت هذه حاله وسكر فدعا بمسرور فقال له احمل الساعة مع عبد الله عشرة آلاف دينار وثلاثين ثوبا من فاخر ثيابي وعيبة مملوءة طيبا فحمل ذلك أجمع معي\nقال عبد الله ولم أزل كلما أراد ولي عهد أن يعلم من الخليفة بعد الخليفة الوالي أهو أم غيره دعاني فأمرني بأن أغني فأعرفه بيميني فيستأذن الخليفة في ذلك فإن أذن لي في الغناء عنده عرف أنه ولي عهد وإلا عرف أنه غيره حتى كان آخرهم الواثق فدعاني في أيام المعتصم وسأله أن يأذن لي في الغناء فأذن لي ثم دعاني من الغد فقال ما غناؤك إلا سببا لظهور سري وسر الخلفاء قبلي ولقد هممت أن آمر بضرب رقبتك لا يبلغني أنك امتنعت من الغناء عند أحد فوالله لئن بلغني لأقتلنك فأعتق من كنت تملكه يوم حلفت وطلق من كان يوجد عندك من الحرائر واستبدل بهن وعلي العوض من ذلك وأرحنا من يمينك هذه المشؤومة فقمت وأنا لا أعقل خوفا منه فأعتقت جميع من كان بقي عندي من مماليكي الذين حلفت يومئذ وهم في ملكي وتصدقت بجملة واستفتيت في يميني أبا يوسف القاضي حتى خرجت منها وغنيت بعد ذلك إخواني جميعا حتى اشتهر أمري وبلغ المعتصم خبري فتخلصت منه ثم غضب علي الواثق لشيء أنكره وولي الخلافة وهو ساخط علي فكتبت إليه\n(أذكر أمير المؤمنين وسائلي ... أيام أرهب سطوة السيف)\n(أدعو إلهي أن أراك خليفة ... بين المقام ومسجد الخيف)\nدعاني ورضي عني حدثني سليمان بن أبي شيخ قال دخلت على العباس بن الفضل بن الربيع ذات يوم وهو مختلط مغتاظ\nوابنه عبد الله عنده فقلت له مالك أمتع الله بك قال لا يفلح والله ابني عبد الله أبدا فظننته قد جنى جناية وجعلت أعتذر إليه فقال ذنبه أعظم من ذلك وأشنع فقلت وما ذنبه قال جاءني بعض غلمان فحدثني أنه رآه بقطربل يشرب نبيذ الداذي بغير غناء فهل هذا فعل من يفلح فقلت له وأنا أضحك سهلت علي القصة قال لا تقل ذاك فإن هذا من ضعة النفس وسقوط الهمة فكنت إذا رأيت عبد الله بعد ذلك في جملة المغنين وشاهدت تبذله في هذه الحال وانخفاضه عن مراتب أهله تذكرت قول أبيه فيه قال وسمعته يوما يغني بصنعته في شعر أبي العتاهية صوت\n(أنا عبد لها مقر وما يملك ... غيرها من الناس رقا)\n(ناصح مشفق وإن كنت ما أرزق ... منها والحمد لله عتقا)\n(ليتني مت فاسترحت فإني ... أبدا ما حييت منها ملقى)\nحن عبد الله بن العباس في هذا الشعر رمل أخبرني جعفر بن قدامة قال حدثني علي بن يحي وأحمد بن حمدون عن أبيه وأخبرني جحظة عن أبي عبد الله الهاشمي أن إسحاق الموصلي دخل يوما إلى الفضل بن الربيع وابن ابنه عبد الله بن العباس في حجره قد أخرج إليه وله نحو السنتين وأبوه العباس واقف بين يديه فقال إسحاق للوقت\n(مد لك الله الحياة مدا ... حتى يكون ابنك هذا جدا)\n(مؤزرا بمجده مردى ... ثم يغدى مثل ما تفدى)\n(أشبه منك سنة وخدا ... وشيما محمودة ومجدا)\n(كأنه أنت إذا تبدى ... )\nال فاستحسن الفضل الأبيات وصنع فيها إسحاق لحنه المشهور وقال جحظة في خبره عن الهاشمي وهو رمل ظريف من حسن الأرمال ومختارها فأمر له الفضل بثلاثين ألف درهم أخبرني جعفر بن قدامة قال حدثني عبد الله بن عمر قال حدثني محمد ابن عبد الله بن مالك قال حدثني بعض ندماء الفضل بن الربيع قال كنا عند الفضل بن الربيع في يوم دجن والسماء ترش وهو أحسن يوم وأطيبه وكان العباس يومئذ قد أصبح مهموما فجهدنا أن ينشط فلم تكن لنا في ذلك حيلة فبينا نحن كذلك إذ دخل عليه بعض الشعراء إما الرقاشي وإما غيره من طبقته فسلم وأخذ بعضادتي الباب ثم قال\n(ألا انعم صباحا يا أبا الفضل واربع ... على مربع القطربلي المشعشع)\n(وعلل نداماك العطاش بقهوة ... لها مصرع في القوم غير مروع)\n(فإنك لاق كلما شئت ليلة ... ويوما يغصان الجفون بأدمع)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":14,"spl":"الرشيد يطرب له ويجيزه","partialRef":{"sid":"b52-89","gi":3,"vi":3,"side":0},"partial":1},
{"id":"b252-22","bab":"الجزء 19","sec":"الرشيد يطرب له ويجيزه","page":"ج19 ص239","text":"ال فبكى العباس وقال صدقت والله إن الإنسان ليلقى ذلك متى يشاء ثم دعا بالطعام فأكل ث دعا بالشراب فشرب ونشط ومر لنا يوم حسن طيب حدثني عمي قال حدثني أحمد بن المرزبان قال جاءني عبد الله بن العباس في خلافة المنتصر وقد سألني عرض رقعة عليه فأعلم أني نائم وقد كنت شربت بالليل شربا كثيرا فصليت الغداة ونمت فلما انتبهت إذا رقعة عند رأسي وفيها مكتوب\n(أنا بالباب واقف منذ أصبحت ... على السرج ممسك بعناني)\n(وبعين البواب كل الذي بي ... ويراني كأنه لا يراني)\nفأمرت بإدخاله فدخل فعرفته خبري واعتذرت إليه وعرضت رقعته على المنتصر وكلمته حتى قضى حاجته","topic":"أخبار عويف ونسبه","topicNo":252,"sp":15,"spl":"الرشيد يطرب له ويجيزه — عبد الله وإسحاق"},
{"id":"b252-23","bab":"الجزء 19","sec":"عبد الله وإسحاق","page":"ج19 ص243","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق قال دعا عبد الله بن العباس الربيعي يوما أبي وسأله أن يبكر إليه ففعل فلما دخل بادر إليه عبد الله بن العباس ملتقيا وفي يده العود وغناه\n(قم نصطبح يفديك كل مبخل ... عاب الصبوح لحبه للمال)\n(من قهوة صفراء صرف مزة ... قد عتقت في الدن مذ أحوال)\nقال وقدم الطعام فأكلنا واصطبحنا واقترح أبي هذا الصوت عليه بقية يومه قال وأتيته في داره بالمطيرة عائدا فوجدته في عافية فجلسنا نتحدث فأنشدته لذي الرمة\n(إذا ما امرؤ حاولن أن يقتتلنه ... بلا إحنة بين النفوس ولا ذحل)\n(تبسمن عن نور الأقاحي في الثرى ... وفترن عن أبصار مكحولة نجل)\n(وكشفن عن أجياد غزلان رملة ... هجان فكان القتل أو شبهة القتل)\n(وإنا لنرضى حين نشكو بخلوة ... إليهن حاجات النفوس بلا بذل)\n(وما الفقر أزرى عندهن بوصلنا ... ولكن جرت أخلاقهن على البخل)\nال فأنشدني هو\n(أنى اهتدت لمناخنا جمل ... ومن الكرى لعيوننا كحل)\n(طرقت أخا سفر وناجية ... خرقاء عرفني بها الرحل)\n(في مهمه هجع الدليل به ... وتعللت بصريفها البزل)\n(فكأن أحدث من ألم به ... درجت على آثاره النمل)\nال إسحاق فقال لي عبد الله بن العباس كل ما يملك في سبيل الله إن\nفارقتك ولم نصطبح على هذين الشعرين وأنشدك وتنشدني ففعلنا ذلك وما غنينا ولا غنينا أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال لقيت عبد الله بن العباس يوما في الطريق فقلت له ما كان خبرك أمس فقال اصطبحت فقلت على ماذا ومع من فقال مع خادم صالح بن عجيف وأنت به عارف وبخبري معه ومحبتي له عالم فاصطبحنا على زنا بنت الخس لما حملت من زنا وقد سئلت ممن حملت فقالت\n(أشم كغصن البان جعد مرجل ... شغفت به ولو كان شيئا مدانيا)\n(ثكلت أبي إن كنت ذقت كريقه ... سلافا ولا عذبا من الماء صافيا)\n(وأقسم لو خيرت بين فراقه ... وبين أبي لاخترت أن لا أبا ليا)\n(فإن لم أوسد ساعدي بعد هجعة ... غلاما هلاليا فشلت بنانيا)\nقلت له أقمت على لواط وشربت على زنا والله ماسبقك إلى هذا أحد أخبرني محمد بن العباس اليزيدي قال أخبرني ميمون بن هارون قال كان محمد بن راشد الخناق عند عبد الله بن العباس بن الفضل بن الربيع على القاطول في أيام المعتصم وكان لمحمد بن راشد غلام يقال له فائز يغني غناء حسنا فأظلتهم سحابة وهم يشربون فقال عبد الله بن العباس\n(محمد قد جادت علينا بمائها ... سحابة مزن برقها يتهلل)\n(ونحن من القاطول في متربع ... ومنزلنا فيه المنابت مبقل)\n(فمر فائزا يشدو إذا ما سقيتني ... أعن ظعن الحي الألى كنت تسأل)\n(ولا تسقني إلا حلالا فإنني ... أعاف من الأشياء مالا يحلل)\nال فأمر محمد بن راشد غلامه فائزا فغناه بهذا الصوت وشرب عليه حتى سكر قال وكان أبو أحمد بن الرشيد قد عشق فائزا فاشتراه من محمد بن راشد بثلاثمائة ألف درهم فبلغ ذلك المأمون فأمر بأن يضرب محمد بن راشد ألف سوط ثم سئل فيه فكف عنه وارتجع منه نصف المال وطالبه بأكثر فوجده قد أنفقه وقضى دينه ثم حجر على أبي أحمد بن الرشيد فلم يزل محجورا عليه طوال أيام المأمون وكان أمر ماله مردودا إلى مخلد بن أبان","topic":"أخبار عويف ونسبه","topicNo":252,"sp":15,"spl":"الرشيد يطرب له ويجيزه — عبد الله وإسحاق"},
{"id":"b252-24","bab":"الجزء 19","sec":"يشرب الخمر حتى في رمضان","page":"ج19 ص246","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال أخبرني ابن الجرجاني قال اتفق يوم النيروز في شهر رمضان فشرب عبد الله بن العباس بن الفضل في تلك الليلة إلى أن بدأ الفجر أن يطلع وقال في ذلك وغنى فيه قوله\n(استعيني صفراء صافية ... ليلة النيروز والأحد)\n(حرم الصوم اصطباحكما ... فتزود شربها لغد)\nخبرني عمي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني\nإبراهيم بن المدبر قال قال لي محمد بن الفضل الجرجاني أنشدت عبد الله بن العباس الربيعي للمعلى الطائي\n(باكر صبوحك صبحة النيروز ... واشرب بكأس مترع وبكوز)\n(ضحك الربيع إليك عن نواره ... آس ونسرين ومرماحوز)\nفاستعادنيهما فأعدتهما عليه وسألني أن أمليهما وصنع فيهما لحنا غنى به الواثق في يوم نيروز فلم يستعد غيره يومئذ وأمر له بثلاثين ألف درهم أخبرني جعفر بن قدامة قال حدثني علي بن يحي قال أنشدني عبد الله بن العباس بن الفضل بن الربيع لجميل وأنشدنيه وهو يبكي ودموعه تنحدر على لحيته صوت\n(فمالك لما خبر الناس أنني ... غدرت بظهر الغيب لم تسليني)\n(فأحلف بتا أو أجيء بشاهد ... من الناس عدل إنهم ظلموني)\nال وله فيه صنعة من خفيف الثقيل وخفيف الرمل أخبرني عمي قال حدثني عبيد الله بن محمد بن عبد الملك الزيات قال حدثنا نافذ مولانا قال كان عبد الله بن العباس صديقا لأبيك وكان يعاشره كثيرا وكان عبد الله ابن العباس مضطبحا دهره لا يفوته ذلك إلا في يوم جمعة أو صوم شهر رمضان وكان يكثر المدح للصبوح ويقول الشعر فيه ويغني فيما يقوله قال عبيد الله\nفأنشدني نافذ مولانا وغيره من أصحابنا في ذلك منهم حماد بن إسحاق صوت\n(ومستطيل على الصهباء باكرها ... في فتية باصطباح الراح حذاق)\n(فكل شيء رآه خاله قدحا ... وكل شخص رآه خاله الساقي)\nال ولحنه فيه خفيف رمل ثقيل قال حماد وكان أبي يستجيد هذا الصوت من صنعته ويستحسن شعره ويعجب من قوله\n(فكل شيء رآه خاله قدحا ... وكل شخص رآه خاله الساقي)\nويعجب من قوله\n(ومستطيل على الصهباء باكرها ... )\nيقول وأي شيء تحته من المعاني الظريفة قال وسمعه أبي يغنيه فقال له كأنك والله يا عبد الله خطيب يخطب على المنبر قال عبد الله بن محمد فأنشدني حماد له في الصبوح\n(لا تعذلن في صبوحي ... فالعيش شرب الصبوح)\n(ما عاب مصطبحا قط ... غير وغد شحيح)\nال عمي قال عبيد الله دخل يوما عبد الله بن العباس الربيعي على أبي مسلما فلما استقر به المجلس وتحادثا ساعة قال له أنشدني شيئا من شعرك فقال إنما أعبث ولست ممن يقدم عليك بإنشاد شعره فقال أتقول هذا وأنت القائل\n(يا شادنا رام إذ مر في السعانين قتلي ... )\n(تقول لي كيف أصبحت كيف يصبح مثلي ... )\nأنت والله أعزك الله أغزل الناس وأرقهم شعرا ولو لم تقل غير هذا البيت\nالواحد لكفاك ولكنت شاعرا أخبرني عمي والحسين بن القاسم الكوكبي قالا حدثنا أحمد بن أبي طاهر قال حدثني أحمد بن الحسين الهشامي أبو عبد الله قال حدثني عبد الله بن العباس بن الفضل بن الربيع قال كنت جالسا على دجلة في ليلة من الليالي وأخذت دواة وقرطاسا وكتبت شعرا حضرني وقلته في ذلك الوقت صوت\n(أخلغك الدهر ما تنظره ... فاصبر فذا جل أمر ذا القدر)\n(لعلنا أن نديل من زمن ... فرقنا والزمان ذو غير)\nال ثم أرتج علي فلم أدر ما أقول حتى يئست من أن يجيئني شيء فالتفت فرأيت القمر وكانت ليلة تتمته فقلت\n(فانظر إلى البدر فهو يشبهه ... إن كان قد ضن عنك بالنظر)\nم صنعت فيه لحنا من الثقيل الثاني قال أبو عبد الله الهشامي وهو والله صوت حسن أخبرني جحظة عن ابن حمدون وأخبرني به الكوكبي عن علي بن محمد ابن نصر عن خالد بن حمدون قال كنا عند الواثق في يوم دجن فلاح برق واستطار فقال لو في هذا شيء فبدرهم عبد الله بن العباس بن الفضل بن الربيع فقال هذين البيتين\n(أعني على لا مع بارق ... خفي كلمحك بالحاجب)\n(كأن تألقه في السماء ... يدا كاتب أو يدا حاسب)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":16,"spl":"يشرب الخمر حتى في رمضان","partial":1},
{"id":"b252-25","bab":"الجزء 19","sec":"يشرب الخمر حتى في رمضان","page":"ج19 ص246","text":"صنع فيه لحنا شرب فيه الواثق بغية يومه واستحسن شعره ومعناه وصنعته ووصل عبد الله بصلة سنية حدثني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن محمد بن مروان قال حدثني الحسين بن الضحاك قال كنت عند عبد الله بن العباس بن الفضل بن الربيع وهو مصطبح وخادم له قائم يسقيه فقال لي يا أبا علي قد استحسنت سقي هذا الخادم فإن حضرك شيء في قصتنا هذه فقل فقلت\n(أحيت صبوحي فكاهة اللاهي ... وطاب يومي بقرب أشباهي)\n(فاستثر اللهو من مكامنه ... من قبل يوم منغص ناهي)\n(بابنة كرم من كف منتطق ... مؤتزر بالمجون تياه)\n(يسقيك من طرفه ومن يده ... سقي لطيف مجرب داهي)\n(وطاسا وكاسا كأن شاربها ... حيران بين الذكور والساهي)\nاستحسنه عبد الله وغنى فيه لحنا مليحا وشربنا عليه بقية يومنا أخبرني عمي قال حدثنا أبو عبد الله أحمد بن المرزبان بن الفيرزان قال حدثني شيبة بن هشام قال\nكان عبد الله بن العباس بن الفضل بن الربيع قد علق جارية نصرانية قد رآها في بعض أعياد النصارى فكان لا يفارق البيع في أعيادهم شغفا بها فخرج في عيد ما سرجيس فظفر بها في بستان إلى جانب البيعة وقد كان قبل ذلك يراسلها ويعرفها حبه لها فلا تقدر على مواصلته ولا على لقائه إلا على الطريق فلما ظفر بها التوت عليه وأبت بعض الإباء ثم ظهرت له وجلست معه وأكلوا وشربوا وأقام معها ومع نسوة كن معها أسبوعا ثم انصرفت في يوم خميس فقال عبد الله بن العباس في ذلك وغنى فيه\n(رب صهباء من شراب المجوس ... قهوة بابلية خندريس)\n(قد تجليتها بناي وعود ... قبل ضرب الشماس بالناقوس)\n(وغزال مكحل ذي دلال ... ساحر الطرف سامري عروس)\n(قد خلونا بطيبه نجتليه ... يوم سبت إلى صباح الخميس)\n(بين ورد وبين آس جني ... وسط بستان دير ما سرجيس)\n(يتثنى بحسن جيد غزال ... وصليب مفضض آبنوسي)\n(كم لثمت الصليب في الجيد منها ... كهلال مكلل بشموس)\nخبرني عمي قال حدثني أحمد بن المرزبان عن شيبة بن هشام قال كان عبد الله بن العباس يوما جالسا ينتظر هذه النصرانية التي كان يهواها وقد وعدته بالزيارة فهو جالس ينتظرها ويتفقدها إذ سقط غراب على برادة داره فنعب مرة واحدة ثم طار فتطير عبد الله من ذلك ولم يزل ينتظرها يومه فلم يرها فأرسل رسوله عشاء يسأل عنها فعرف أنها قد انحدرت مع أبيها إلى بغداد\nفتنغص عليه يومه وتفرق من كان عنده ومكث مدة لا يعرف لها خبرا فبينا هو جالس ذات يوم مع أصحابه إذ سقط هدهد على برادته فصاح ثلاثة أصوات وطار فقال عبد الله بن العباس وأي شيء أبقى الغراب للهدهد علينا وهل ترك لنا أحدا يؤذينا بفراقه وتطير من ذلك فما فرغ من كلامه حتى دخل رسولها يعلمه أنها قد قدمت منذ ثلاثة أيام وأنها قد جاءته زائرة على إثر رسولها فقال في ذلك من وقته\n(سقاك الله يا هدهد ... وسيميا من القطر)\n(كما بشرت بالوصل ... وما أنذرت بالهجر)\n(فكم ذا لك من بشرى ... أتتني منك في ستر)\n(كما جاءت سليمان ... فأوفت منه بالنذر)\n(ولا زال غراب البين ... في قفاعة الأسر)\n(كما صرح بالبين ... وما كنت به أدري)\nلحنه في هذا الشعر هزج","topic":"أخبار عويف ونسبه","topicNo":252,"sp":17,"spl":"يشرب الخمر حتى في رمضان"},
{"id":"b252-26","bab":"الجزء 19","sec":"عبد الله والمتوكل والمنتصر","page":"ج19 ص252","text":"حدثني عمي قال حدثني ميمون بن هارون قال قال إسحاق بن إبراهيم ابن مصعب قال لي عبد الله بن العباس الربيعي لما صنعت لحني في شعري\n(ألا أصبحاني يوم السعانين ... من قهوة عتقت بكر كين)\n(عند أناس قلبي بهم كلف ... وإن تولوا دينا سوى ديني)\n(قد زين الملك جعفر وحكى ... جود أبيه وبأس هارون)\n(وأمن الخائف البريء كما ... أخاف أهل الإلحاد في الدين)\nعاني المتوكل فلما جلست في مجلس المنادمة غنيت هذا الصوت فقال لي يا عبد الله أين غناؤك في هذا الشعر في أيامي هذه من غنائك في\n(أماطت كساء الخز عن حر وجهها ... وأدنت على الخدين بردا مهلهلا)\nمن غنائك في\n(أقفر من بعد خلة سرف ... فالمنحنى فالعقيق فالجرف)\nمن سائر صنعتك المتقدمة التي استفرغت محاسنك فيها فقلت له يا أمير المؤمنين إني كنت أتغني في هذه الأصوات ولي شباب وطرب وعشق ولو رد علي لغنيت مثل ذلك الغناء فأمر لي بجائزة واستحسن قولي حدثني عمي قال حدثنا أحمد بن المرزبان قال حدثني أبي قال ذكر المنتصر يوما عبد الله بن العباس وهو في قراح النرجس مصطبح فأحضره وقال له يا عبد الله اصنع لحنا في شعري الفلاني وغنني به وكان عبد الله حلف لا يغني في شعره فأطرق مليا ثم غنى في شعر قاله للوقت وهو\n(يا طيب يومي في قراح النرجس ... في مجلس ما مثله من مجلس)\n(تسقى مشعشعة كأن شعاعها ... نار تشب لبائس مستقبس)\nال فجهد أبي بالمنتصر يوما واحتال عليه بكل حيلة أن يصله بشيء فلم يفعل حدثني عمي قال حدثني أحمد بن المرزبان قال حدثني أبي فقال غضبت قبيحة على المتوكل وهاجرته فجلس ودخل الجلساء والمغنون\nوكان فيهم عبد الله بن العباس الربيعي وكان قد عرف الخبر فقال هذا الشعر وغنى فيه\n(لست مني ولست منك فدعني ... وامض عني مصاحبا بسلام)\n(لم تجد علة تجنى بها الذنب ... فصارت تعتل بالأحلام)\n(فإذا ما شكوت ما بي قالت ... قد رأينا خلاف ذا في المنام)\nال فطرب المتوكل وأمر له بعشرين ألف درهم وقال له إن في حياتك يا عبد الله لأنسا وجمالا وبقاء للمروءة والظرف أخبرني عمي قال حدثني أحمد بن المرزبان قال حدثني أبي قال حدثني عبد الله بن العباس الربيعي قال كنت في بعض العساكر فأصابتنا السماء حتى تأذينا فضربت لي قبة تركية وطرح لي فيها سريران فخطر بقلبي قول السليك صوت\n(قرب النحام واعجل يا غلام ... واطرح السرج عليه واللجام)\n(أبلغ الفتيان أني خائض ... غمرة الضرب فمن شاء أقام)\nغنيت فيه لحني المعروف وغدونا فدخلت مدينة فإذا أنا برجل يغني به ووالله ما سبقني إليه أحد ولا سمعه مني أحد فما أدري من الرجل ولا من أين كان له وما أرى إلا أن الجن أوقعته في لسانه","topic":"أخبار عويف ونسبه","topicNo":252,"sp":18,"spl":"عبد الله والمتوكل والمنتصر"},
{"id":"b252-27","bab":"الجزء 19","sec":"محمد بن الجهم يحتمل خراجه سنة كاملة","page":"ج19 ص255","text":"حدثني عمي قال حدثني أحمد بن المرزبان قال حدثني أبي قال حدثني عبد الله بن العباس الربيعي قال كنت عند محمد بن الجهم البرمكي بالأهواز وكانت ضيعتي في يده فغنيته في يوم مهرجان وقد دعانا للشرب صوت\n(المهرجان ويوم الاثنين ... يوم سرور قد حف بالزين)\n(ينقل من وغرة المصيف إلى ... برد شتاء ما بين فصلين)\n(محمد يا بن الجهم ومن بنى ... للمجد بيتا من خير بيتين)\n(عش ألف نيروز ومهرج فرحا ... في طيب عيش وقرة العين)\nال فسر بذلك واحتمل خراجي في تلك السنة وكان مبلغه ثلاثين ألف درهم أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني ابن أبي سعد قال حدثني أبو توبة القطراني عن محمد بن حسين قال كنا عند أبي عيسى بن الرشيد في زمن الربيع ومعنا مخارق وعلويه وعبد الله بن العباس الربيعي ومحمد بن الحارث بن بسخنر ونحن مصطبحون في طارمة مضروبة على بستانه وقد تفتح فيه ورد وياسمين وشقائق والسماء\nمتغيمة غيما مطبقا وقد بدأت ترش رشا ساكبا فنحن في أكمل نشاط وأحسن يوم إذ خرجت قيمة دار أبي عيسى فقالت يا سيدي قد جاءت عساليج فقال لتخرج إلينا فليس بحضرتنا من تحتشمه فخرجت إلينا جارية شكلة حلوة حسنة العقل والهيئة الأدب في يدها عود فسلمت فأمرها أبو عيسى بالجلوس فجلست وغنى القوم حتى انتهى الدور إليها وظننا أنها لا تصنع شيئا وخفنا أن تهابنا فتحصر فغنت غناء حسنا مطربا متقنا ولم تدع أحدا من حضر إلا غنت صوتا من صنعته وأدته على غاية الإحكام فطربنا واستحسنا غناءها وخاطبناها بالاستحسان وألح عبد الله بن العباس من بيننا بالاقتراح عليها والمزاح معها والنظر إليها فقال له أبو عيسى عشقتها وحياتي يا عبد الله قال لا والله يا سيدي وحياتك ما عشقتها ولكني استحسنت كل ما شاهدت منها من منظر وشكل وعقل وعشرة وغناء فقال له أبو عيسى فهذا والله هو العشق وسببه ورب جد جره اللعب وشربنا فلما غلب النبيذ على عبد الله غنى أهزاجا قديمة وحديثة وغنى فيما غنى بينهما هزجا في شعر قاله فيها لوقته فما فطن له إلا أبو عيسى وهو صوت\n(نطق السكر بسري فبدا ... كم يرى المكتوم يخفى لا يضح)\n(سحر عينيك إذا مارنتا ... لم يدع ذا صبوة أو يفتضح)\n(ملكت قلبا فأمسى غلقا ... عندها صبا بها لم يسترح)\n(بجمال وغناء حسن ... جل عن أن ينتقيه المقترح)\n(أورث القلب هموما ولقد ... كنت مسرورا بمرآه فرح)\n(ولكم مغتبق هما وقد ... بكر اللهو بكور المصطبح)\nلغناء لعبد الله بن العباس هزج فقال له أبو عيسى فعلتها والله يا عبد الله وطار طربا وشرب على الصوت وقال له صح والله قولي لك في عساليج وأنت\nتكابرني حتى فضحك السكر فجحد وقال هذا غناء كنت أرويه فحلف أبو عيسى أنه ما قاله ولا غناه إلا في يومه وقال له احلف بحياتي أن الأمر ليس هو كذلك فلم يفعل فقال له أبو عيسى والله لوكانت لي لوهبتها لك ولكنها لآل يحيى بن معاذ والله لئن باعوها لأملكنك إياها ولو بكل ما أملك ووحياتي لتنصرفن قبلك إلى منزلك ثم دعا بحافظتها وخادم من خدمه فوجه بها معهما إلى منزله والتوى عبد الله قليلا وتجلد وجاحدنا أمره ثم انصرف واتصل الأمر بينهما بعد ذلك فاشترتها عمته رقية بنت الفضل بن الربيع من آل يحيى بن معاذ وكانت عندهم حتى ماتت فحدثني جعفر بن قدامة بن زياد عن بعض شيوخه سقط عني اسمه قال قالت بذل الكبيرة لعبد الله بن العباس قد بلغني أنك عشقت جارية يقال لها عساليج فاعرضها علي فإما أن عذرتك وإما أن عذلتك فوجه إليها فحضرت وقال لبذل هذه هي ياستي فانظري واسمعي ثم مريني بما شئت أطعك فأقبلت عليه عساليج وقالت يا عبد الله أتشاور في فو الله ما شاورت فيك لما صاحبتك فنعرت بذل وصاحت إيه أحسنت والله يا صبية ولو لم تحسني شيئا ولا كانت فيك خصلة تحمد لوجب أن تعشقي لهذه الكلمة أحسنت والله ثم قالت لعبد الله ما ضيعت احتفظ بصاحبتك","topic":"أخبار عويف ونسبه","topicNo":252,"sp":19,"spl":"محمد بن الجهم يحتمل خراجه سنة كاملة"}]);
window.__BOOK__['p10'].push([{"id":"b252-28","bab":"الجزء 19","sec":"عبد الله يغني الواثق فيجيزه","page":"ج19 ص257","text":"حدثني عمي قال حدثني محمد بن المرزبان عن أبيه عن عبد الله بن العباس قال دعانا الواثق في يوم نوروز فلما دخلت عليه غنيته في شعر قلته وصنعت فيه لحنا وهو\n(هي للنيروز جاما ... ومداما وندامى)\n(يحمدون الله والواثق ... هارون الإماما)\n(ما رأى كسرى أنوشر ... وان مثل العام عاما)\n(نرجسا غضا ووردا ... وبهارا وخزامى)\nال فطرب واستحسن الغناء وشرب عليه حتى سكر وأمر لي بثلاثين ألف درهم حدثني عمي قال حدثني أحمد بن المرزبان قال حدثني شيبة بن هشام قال ألقت متيم على جوارينا هذا اللحن وزعمت أنها أخذته من عبد الله بن العباس والصنعة له صوت\n(إني اتخذت عدوة ... فسقى الإله عدوتي)\n(وفديتها بأقاربي ... وبأسرتي وبجيرتي)\n(واستيقنت أن الفؤاد ... يحبها فأدلت)\nال ثم حدثتنا متيم أن عبد الله بن العباس كان يتعشق مصابيح جارية الأحدب المقين وأنه قال هذا الشعر فيها وغنى فيه هذا اللحن بحضرتها فأخذته عنه هكذا ذكر شيبة بن هشام من أمر مصابيح وهي مشهورة من جواري\nآل يحيى بن معاذ ولعلها كانت لهذا المقين قبل أن يملكها آل يحيى وقبل أن تصل إلى رقية بنت الفضل بن الربيع وحدثنا أيضا عمي قال حدثنا أحمد بن المرزبان عن شيبة بن هشام قال كان عبد الله بن العباس يتعشق جارية الأحدب المقين ولم يسمها في هذا الخبر فغاضبها في شيء بلغه عنها ثم رام بعد ذلك أن يترضاها فأبت وكتب إليها رقعة يحلف لها على بطلان ما أنكرته ويدعو الله على من ظلم فلم تجبه عن شيء مما كتب به ووقعت تحت دعائه آمين ولم تجب عن شيء مما تضمنته الرقعة بغير ذلك فكتب إليها\n(أما سروري بالكتاب ... فليس يفنى ما بقينا)\n(وأتى الكتاب وفيه لي ... آمين رب العالمينا)\nال وزارته في ليلة من ليالي شهر رمضان وأقامت عنده ساعة ثم انصرفت وأبت أن تبيت وتقيم ليلتها عنده فقال هذا الشعر وغنى فيه هزجا وهو مشهور من أغانيه وهو صوت\n(يا من لهم أمسى يؤرقني ... حتى مضى شطر ليلة الجهني)\n(عني ولم أدر أنها حضرت ... كذاك من كان حزنه حزني)\n(إني سقيم موله دنف ... أسقمني حسن وجهك الحسن)\n(جودي له بالشفاء منيته ... لا تهجري هائما عليك ضني)\nال وليلة الجهني ليلة تسع عشرة من شهر رمضان قال رجل من جهينة إنه رأى فيها ليلة القدر فيما يرى النائم فسميت ليلة الجهني أخبرني عمي قال حدثنا أحمد بن المرزبان قال حدثني شيبة بن هشام\nقال دعانا محمد بن حماد بن دنقش وكان له ستارة في نهاية الوصف وحضر معنا عبد الله بن العباس فقال عبد الله وغنى فيه\n(دع عنك لومي فإني غير منقاد ... إلى الملام وإن أحببت إرشادي)\n(فلست أعرف لي يوما سررت به ... كمثل يومي في دار ابن حماد)\nخبرني يحي بن علي بن يحي قال حدثني أبو أيوب المديني قال حدثني ابن المكي عن عبد الله بن العباس قال لما صنعت لحني في شعري صوت\n(يا ليلة ليس لها صبح ... وموعدا ليس له نجح)\n(من شادن مر على وعده الميلاد ... والسلاق والذبح)\nذه أعياد النصارى غنيته الواثق فقال ويلكم أدركوا هذا لا يتنصر وتمام هذا الشعر\n(وفي السعانين لو أني به ... وكان أقصى الموعد الفصح)\n(فالله أستعدي على ظالم ... لم يغن عنه الجود والشح)\nسخت من كتاب أبي سعد السكري قال أبو العتاهية وفيه لعبد الله بن العباس غناء حسن\n(أنا عبد لها مقر وما يملك ... لي غيرها من الناس رقا)\n(ناصح مشفق وإن كنت ما أرزق ... منها والحمد لله عتقا)\n(ومن الحين والشقاء تعلقت ... مليكا مستكبرا حين يلقى)\n(إن شكوت الذي لقيت إليه ... صد عني وقال بعدا وسحقا)\nأخبرني عمي قال حدثني علي بن محمد بن نصر عن جده حمدون بن إسماعيل قال\nدخلت يوما إلى عبد الله بن العباس الربيعي وخادم له يسقيه وبيده عوده وهو يغني هذا الصوت\n(إذا اصطبحت ثلاثا ... وكان عودي نديمي)\n(والكأس تغرب ضحكا ... من كف ظبي رخيم)\n(فما علي طريق ... لطارقات الهموم)\nال فما رأيت أحسن مما حكى حاله في غنائه ولا سمعت أحسن مما غنى أخبرني الحسين بن القاسم الكوكبي قال حدثنا عبد الله بن أبي سعد قال حدثني دوسر الخراساني قال اشترى حزام خادم المعتصم خادما نظيفا كان عبد الله بن العباس بن الفضل بن الربيع يتعشقه فسأله هبته له أو بيعه منه فأبى فقال عبد الله أبياتا وصنع فيها غناء وهي قوله\n(يوم سبت فصرفا لي المداما ... واسقياني لعلني أن أناما)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":20,"spl":"عبد الله يغني الواثق فيجيزه"},
{"id":"b252-29","bab":"الجزء 19","sec":"عبد الله يغني الواثق فيجيزه","page":"ج19 ص257","text":"(شرد النوم حب ظبي غرير ... ما أراه يرى الحرام حراما)\n(اشتراه يوما بعلفة يوم ... أصبحت عنده الدواب صياما)\nاتصلت الأبيات وخبرها بحزام فخشي أن تشتهر ويسمعها المعتصم فيأتي عليه فبعث بالغلام إلى عبد الله وسأله أن يمسك عن الأبيات ففعل حدثني الصولي قال حدثني الحسين بن يحي قال قلت لعبد الله بن العباس إنه بلغني لك خبر مع الرشيد أول ما شهرت بالغناء فحدثني به قال نعم أول صوت صنعته\n(أتاني يؤامرني في الصبوح ... ليلا فقلت له غادها)\nفلما تأتى لي وضربت عليه بالكنكلة عرضته على جارية لنا يقال لها راحة فاستحسنته وأخذته عني وكانت تختلف إلى إبراهيم الموصلي فسمعها يوما تغنيه وتناغي به جارية من جواريه فاستعادها إياه وأعادته عليه فقال لها لمن هذا فقالت صوت قديم فقال لها كذبت لو كان قديما لعرفته وما زال يداريها ويتغاضب عليها حتى اعترفت له بأنه من صنعتي فعجب من ذلك ثم غناه يوما بحضرة الرشيد فقال له لمن هذا اللحن يا إبراهيم فأمسك عن الجواب وخشي أن يكذبه فينمى الخبر إليه من غيره وخاف من جدي أن يصدقه فقال له مالك لا تجيبني فقال لا يمكنني يا أمير المؤمنين فاستراب بالقصة ثم قال والله وتربة المهدي لئن لم تصدقني لأعاقبنك عقوبة موجعة وتوهم أنه لعلية أو لبعض حرمه فاستطير غضبا فلما رأى إبراهيم الجد منه صدقه فيما بينه وبينه سرا فدعا لوقته الفضل بن الربيع ثم قال له أيصنع ولدك غناء ويرويه الناس ولا تعرفني فجزع وحلف بحياته وبيعته أنه ما عرف ذلك قط ولا سمع به إلا في وقته ذلك فقال له ابن ابنك عبد الله بن العباس أحضرنيه الساعة فقال أنا أمضي وأمتحنه فإن كان يصلح للخدمة أحضرته وإلا كان أمير المؤمنين أولى من ستر عورتنا فقال لا بد من إحضاره فجاء جدي فأحضرني وتغيظ علي فاعتذرت وحلفت له أن هذا شيء ما تعمدته وإنما غنيت لنفسي وما أدري من أين خرج فأمر بإحضار عود فأحضر وأمرني فغنيته الصوت فقال قد عظمت مصيبتي فيك يا بني فحلفت له بالطلاق والعتاق ألا أقبل على الغناء رفدا أبدا\nولا أغني إلا خليفة أو ولي عهد ومن لعله أن يكون حاضرا مجالسهم فطابت نفسه فأحضرني فغنيت الرشيد الصوت فطرب وضرب عليه أقداحا وأمرني بالملازمة مع الجلساء وجعل لي نوبة وأمر بحمل عشرة آلاف دينار إلى جدي وأمره أن يبتاع ضيعة لي بها فابتاع لي ضيعتي بالأهواز ولم أزل ملازما للرشيد حتى خرج إلى خراسان وتأخرت عنه وفرق الموت بيننا","topic":"أخبار عويف ونسبه","topicNo":252,"sp":21,"spl":"عبد الله يغني الواثق فيجيزه"},
{"id":"b252-30","bab":"الجزء 19","sec":"الواثق يقترض مالا ليعطيه له","page":"ج19 ص263","text":"قال ابن المرزبان فكان عبد الله بن العباس سببا لمعرفة أولياء العهود برأي الخلفاء فيهم فكان منهم الواثق فإنه أحب أن يعرف هل يوليه المعتصم العهد بعده أم لا فقال له عبد الله أنا أدلك على وجه تعرف به ذلك فقال وما هو فقال تسأل أمير المؤمنين أن يأذن للجلساء والمغنين أن يصيروا إليك فإذا فعل ذلك فاخلع عليهم وعلي معهم فإني لا أقبل خلعتك لليمين التي علي ألا أقبل رفدا إلا من خليفة أو ولي عهد فقعد الواثق ذات يوم وبعث إلى المعتصم وسأله الإذن إلى الجلساء فأذن لهم فقال له عبد الله بن العباس قد علم أمير المؤمنين يميني فقال له أمض إليه فإنك لا تحنث فمضى إليه وأخبره الخبر فلم يصدقه وظن أنه يطيب نفسه فخلع عليه وعلى الجماعة فلم يقبل عبد الله خلعته وكتب إلى المعتصم يشكوه فبعث إليه اقبل الخلعة فإنه ولي عهدي ونمى إليه الخبر أن هذا كان حيلة من عبد الله فنذر دمه ثم عفا عنه وسر الواثق بما جرى وأمر إبراهيم بن رياح فاقترض له ثلثمائة ألف درهم فغرقها على الجلساء ثم عرف غضب المعتصم على عبد الله بن العباس واطراحه إياه فاطرحه هو أيضا فلما ولي الخلافة استمر على جفائه فقال عبد الله\n(مالي جفيت وكنت لا أجفى ... أيام أرهب سطوة السيف)\n(أدعو إلهي أن أراك خليفة ... بين المقام ومسجد الخيف)\nودس من غناه الواثق فلما سمعه سأل عنه فعرف قائله فتذمم ودعا عبد الله فبسطه ونادمه إلى أن مات وذكر العتابي عن ابن الكلبي أن الواثق كان يشتهي على عبد الله بن العباس\n(أيها العاذل جهلا تلوم ... قبل أن ينجاب عنه الصريم)\nأنه غناه يوما فأمر بأن يخلع عليه خلعة فلم يقبلها ليمينه فشكاه إلى المعتصم فكاتبه في الوقت فكتب إليه مع مسرور سمانة اقبل خلع هارون فإنك لا تحنث فقبلها وعرف الواثق أنه ولي عهد حدثني عمي قال حدثني أحمد بن المرزبان قال حدثني شيبة بن هشام قال كان عبد الله بن العباس يهوى جارية نصرانية لم يكن يصل إليها ولا يراها إلا إذا خرجت إلى البيعة فخرجنا يوما معه إلى السعانين فوقف حتى إذا جاءت فرآها ثم أنشدنا لنفسه وغنى فيه بعد ذلك صوت\n(إن كنت ذا طب فداويني ... ولا تلم فاللوم يغريني)\n(يا نظرة أبقت جوى قائلا ... من شادن يوم السعانين)\n(ونظرة من ربرب عين ... خرجن في أحسن تزيين)\n(خرجن يمشين إلى نزهة ... عواتقا بين البساتين)\n(مزنرات بهمايينها ... والعيش ما تحت الهمايين)\nحن عبد الله بن العباس في هذا الشعر هزج أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا محمد بن عمر الجرجاني ومحمد بن حماد كاتب راشد قالا كتب عبد الله بن العباس الربيعي في يوم نيروز واتفق في يوم الشك بين شهري رمضان وشعبان إلى محمد بن الحارث بن بسخنر يقول\n(اسقني صفراء صافية ... ليلة النيروز والأحد)\n(حرم الصوم اصطباحكما ... فتزود شربها لغد)\n(وأتنا أو فادعنا عجلا ... نشترك في عيشة رغد)\nال فجاءه محمد بن الحارث بن بسخنر فشربا ليلتهما أخبرني يحيى بن علي بن يحيى قال حدثنا أبو أيوب المديني قال حدثنا أحمد بن المكي قال حدثنا عبد الله بن العباس الربيعي قال جمع الواثق يوما المغنين ليصطبح فقال بحياتي إلا صنعت هزجا حتى أدخل وأخرج إليكم الساعة ودخل إلى جواريه فقلت هذه الأبيات وغنيت فيها هزجا قبل أن يخرج وهي صوت\n(بأبي زور أتاني بالغلس ... قمت إجلالا له حتى جلس)\n(فتعانقنا جميعا ساعة ... كادت الأرواح فيها تختلس)\n(قلت يا سؤلي ويا بدر الدجى ... في ظلام الليل ماخفت العسس)\n(قال قد خفت ولكن الهوى ... آخذ بالروح مني والنفس)\n(زارني يخطر في مشيته ... حوله من نور خديه قبس)\nال فلما خرج من دار الحرم قال لي يا عبد الله ما صنعت فاندفعت فغنيته فشرب حتى سكر وأمر لي بخمسة آلاف درهم وأمرني بطرحه على الجواري فطرحته عليهن أخبرني يحيى بن علي بن يحيى قال حدثنا أبو أيوب المديني عن حماد قال من مليح صنعة عبد الله بن العباس الربيعي والشعر ليوسف بن الصيقل ولحنه هزج صوت\n(أبعد المواثيق لي ... وبعد السؤال الحفي)\n(وبعد اليمين التي ... حلفت على المصحف)\n(تركت الهوى بيننا ... كضوء سراج طفي)\n(فليتك إذ لم تفي ... بوعدك لم تخلفي)","topic":"أخبار عويف ونسبه","topicNo":252,"sp":22,"spl":"الواثق يقترض مالا ليعطيه له"},
{"id":"b252-31","bab":"الجزء 19","sec":"الواثق يقترض مالا ليعطيه له","page":"ج19 ص263","text":"دثني الصولي قال حدثني يزيد بن محمد المهلبي قال كان الواثق قد غضب على فريدة لكلام أخفته إياه فأغضبته وعرفنا ذلك وجلس في تلك الأيام للصبوح فغناه عبد الله بن العباس صوت\n(لا تأمني الصرم مني أن تري كلفي ... وإن مضى لصفاء الود أعصار)\n(ما سمي القلب إلا من تقلبه ... والرأي يصرف والأهواء أطوار)\n(كم من ذوي مقة قبلي وقبلكم ... خانوا فأضحوا إلى الهجران قد صاروا)\nاستعاده الواثق مرارا وشرب عليه وأعجب به وأمر لعبد الله بألف دينار وخلع عليه الشعر للأحوص والغناء لعبد الله بن العباس هزج بالوسطى عن عمرو","topic":"أخبار عويف ونسبه","topicNo":252,"sp":23,"spl":"الواثق يقترض مالا ليعطيه له"},
{"id":"b252-32","bab":"الجزء 19","sec":"المتوكل يفضله على سائر المغنين","page":"ج19 ص267","text":"وأخبرني جعفر بن قدامة قال حدثنا حماد بن إسحاق قال حدثني عبد الله بن العباس بن الفضل بن الربيع قال\n(غنيت المتوكل ذات يوم ... )\n(أحب إلينا منك دلا وما يرى ... له عند فعلي من ثواب ولا أجر)\nطرب وقال أحسنت والله يا عبد الله أما والله لو رآك الناس كلهم كما أراك لما ذكروا مغنيا سواك أبدا نسخت من كتاب لأبي العباس بن ثوابة بخطه حدثني أحمد بن إسماعيل\nابن حاتم قال قال لي عبد الله بن العباس الربيعي دخلت على المعتصم أودعه وأنا أريد الحج فقبلت يده وودعته فقال يا عبد الله إن فيك لخصالا تعجبني كثر الله في موالي مثلك فقبلت رجله والأرض بين يديه وأحسن محمد بن عبد الملك الزيات محضري وقال له إن له يا أمير المؤمنين أدبا حسنا وشعرا جيدا فلما خرجت قلت له أيها الوزير ما شعري أنا في الشعر تستحسنه وتشيد بذكره بين يدي الخليفة فقال دعنا منك تنتفي من الشعر وأنت الذي تقول\n(يا شاديا مر إذا رام ... في السعانين قتلي)\n(يقول لي كيف أصبحت ... كيف يصبح مثلي)\nأحسنت والله في هذا ولو لم تقل غير هذا لكنت شاعرا أخبرني عمي قال حدثنا أحمد بن المرزبان قال قال أبي قال عبد الله ابن العباس الربيعي لقيني سوار بن عبد الله القاضي وهو سوار الأصغر فأصغى إلي وقال إن لي إليك حاجة فأتني في خفي فجئته فقال لي إليك حاجة قد أنست بك فيها لأنك لي كالولدفإن شرطت لي كتمانها أفضيت بها إليك فقلت ذلك للقاضي علي شرط واجب فقال إني قلت أبياتا في جارية لي أميل إليها وقد قلتني وهجرتني وأحببت أن تصنع فيها ولحنا وتسمعينه وإن أظهرته وغنيته بعد ألا يعلم أحد أنه شعري فلست أبالي أتفعل ذلك قلت نعم حبا وكرامة فأنشدني\nصوت\n(سلبت عظامي لحمها فتركتها ... عواري في أجلادها تتكسر)\n(وأخليت منها مخها فكأنها ... أنابيب في أجوافها الريح تصفر)\n(إذا سمعت باسم الفراق ترعدت ... مفاصلها من هول ما تتحذر)\n(خذي بيدي ثم اكشفي الثوب فانظري ... بلى جسدي لكنني أتستر)\n(وليس الذي يجري من العين ماؤها ... ولكنها روح تذوب فتقطر)\nللحن الذي صنعه عبد الله بن العباس في هذا الشعر ثقيل أول قال عبد الله فصنعت فيه لحنا ثم عرفته خبره في رقعة كتبتها إليه وسألته وعدا يعدني به للمصير إليه فكتب إلي نظرت في القصة فوجدت هذا لا يصلح ولا ينكتم علي حضورك وسماعي إياك وأسأل الله أن يسرك ويبقيك فغنيت الصوت وظهر حتى تغنى به الناس فلقيني سوار يوما فقال لي يا بن أخي قد شاع أمرك في ذلك الباب حتى سمعناه من بعد كأنا لم نعرف القصة فيه وجعلنا جميعا نضحك أخبرني عمي قال حدثني أحمد بن المرزبان قال كان بشر خادم صالح بن عجيف عليلا ثم برئ فدخل إلى عبد الله بن العباس فلما رآه فتلقاه وأجلسه وشرب سرورا بعافيته وصنع لحنا من الثقيل الأول هو من جيد صنعته صوت\n(مولاي ليس لعيش لست حاضره ... قدر ولا قيمة عندي ولا ثمن)\n(ولا فقدت من الدنيا ولذتها ... شيئا إذا كان عندي وجهك الحسن)\nحدثني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق قال حدثنا عبد الله بن العباس الربيعي قال\nجمعنا الواثق يوما بعقب علة غليظة كان فيها فعوفي وصح جسمه فدخلت إليه مع المغنين وعودي في يدي فلما وقعت عيني عليه من بعيد وصرت بحيث يسمع صوتي ضربت وغنيت في شعر قلته في طريقي إليه وصنعت فيه لحنا وهو صوت\n(اسلم وعمرك الإله لأمة ... بك أصبحت قهرت ذوي الإلحاد)\n(لو تستطيع وقتك كل أذية ... بالنفس والأموال والأولاد)\nضحك وسر وقال أحسنت يا عبد الله وسررتني وتيمنت بابتدائك ادن مني فدنوت منه حتى كنت أقرب المغنين إليه ثم استعادني الصوت فأعدته ثلاث مرات وشرب عليه ثلاثة أقداح وأمر لي بعشرة آلاف درهم وخلعة من ثيابه حدثني الصولي قال حدثني عون بن محمد الكندي قال كان عبد الله بن العباس بن الفضل بن الربيع يهوى جارية نصرانية فجاءته يوما تودعه فأعلمته أن أباها يريد الانحدار إلى بغداد والمضي بها معه فقال في ذلك وغنى فيه صوت\n(أفدي التي قلت لها ... والبين منا قد دنا)\n(فقدك قد أنحل جسمي ... وأذاب البدنا)\n(قالت فماذا حيلتي ... كذاك قد ذبت أنا)\n(باليأس بعدي فاقتنع ... قلت إذا قل الغنا)\nدثني الصولي قال حدثني عون بن محمد قال حدثني علي بن عيسى ابن جعفر الهاشمي قال","topic":"أخبار عويف ونسبه","topicNo":252,"sp":24,"spl":"المتوكل يفضله على سائر المغنين","partial":1},
{"id":"b252-33","bab":"الجزء 19","sec":"المتوكل يفضله على سائر المغنين","page":"ج19 ص267","text":"دخل علي عبد الله بن العباس في يوم النصف من شعبان وهو يوم سبت وقد عزمت على الصوم فأخد بعضادتي باب مجلسي ثم قال يا أميري\n(تصبح في السبت غير نشوان ... وقد مضى عنك نصف شعبان)\nقلت قد عزمت على الصوم فقال أفعليك وزر إن أفطرت اليوم لمكاني وسررتني بمساعدتك لي وصمت غدا وتصدقت مكان إفطارك فقلت أفعل فدعوت بالطعام فأكلت وبالنبيذ فشربنا وأصبح من غد عندي فاصطبح وساعدته فلما كان اليوم الثالث انتبهت سحرا وقد قال هذا الشعر وغنى فيه\n(شعبان لم يبق منه ... إلا ثلاث وعشر)\n(فباكر الراح صرفا ... لا يسبقنك فجر)\n(فإن بغتك اصطباح ... فلا يفوتنك سكر)\n(ولا تنادم فتى وقت ... شربه الدهر عصر)\nقال فأطربني واصطبحت معه في اليوم الثالث فلما كان من آخر النهار سكر وانصرف وما شربنا يومنا كله إلى على هذا الصوت حدثني عمي قال حدثني ابن دهقانة النديم قال دخل عبد الله بن العباس إلى المتوكل في آخر شعبان فأنشده\n(عللاني نعمتما بمدام ... واسقياني من قبل شهر الصيام)\n(حرم الله في الصيام التصابي ... فتركناه طاعة للإمام)\n(أظهر العدل فاستنار به الدين ... وأحيا شرائع الإسلام)\nأمر المتوكل بالطعام فأحضر وبالنديم وبالجلساء فأتي بذلك فاصطبح وغناه عبد الله في هذه الأبيات فأمر له بعشرة آلاف درهم","topic":"أخبار عويف ونسبه","topicNo":252,"sp":25,"spl":"المتوكل يفضله على سائر المغنين — قصته مع المرابين"},
{"id":"b252-34","bab":"الجزء 19","sec":"قصته مع المرابين","page":"ج19 ص272","text":"أخبرني الحسن بن علي قال حدثنا يزيد بن محمد المهلبي قال حدثني عبد الله بن العباس قال كنت مقيما بسر من رأى وقد ركبني دين ثقيل أكثر عينة وربا فقلت في المتوكل\n(أسقياني سحرا بالكبرة ... ما قضى الله فغيه الخيره)\n(أكرم الله الإمام المرتضى ... وأطال الله فينا عمره)\n(إن أكن أقعدت عنه هكذا ... قدر الله رضينا قدره)\n(سره الله وأبقاه لنا ... ألف عام وكفانا الفجره)\nبعثت بالأبيات إليه وكنت مستترا من الغرماء فقال لعبيد الله بن يحيى وقع إليه من هؤلاء الفجرة الذين استكفيت الله شرهم فقلت المغنيون الذين قد ركبني لهم أكثر مما أخذت منهم من الدين بالربا فأمر عبيد الله أن يقضي ديني وأن يحتسب لهم رؤوس أموالهم ويسقط الفضل وينادي بذلك في سر من رأى حتى لا يقضي أحد أحدا إلا رأس ماله وسقط عني وعن الناس من الأرباح زهاء مائة ألف دينار كانت أبياتي هذه سببها\nحدثني الصولي قال حدثني عون بن محمد الكندي قال حدثني أبي قال مرض عبد الله بن العباس بسر من رأى في قدمة قدمها إليها فتأخر عنه من كان يثق به فكتب إليهم\n(ألا قل لمن بالجانبين بأنني ... مريض عداني عن زيارتهم مابي)\n(فلو بهم بعض الذي بي لزرتهم ... وحاش لهم من طول سقمي وأوصابي)\n(وإن أقشعت عني سحابة علتي ... تطاول عتبي إن تأخر إعتابي)\nال فما بقي أحد من إخوانه إلا جاءه عائدا معتذرا أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن محمد بن موسى قال سمعت عبد الله بن العباس يغني ونحن مجتمعون عند علوية بشعر في النصرانية التي كان يهواها والصنعة له صوت\n(إن في القلب من الظبي كلوم ... فدع اللوم فإن اللوم لوم)\n(حبذا يوم السعانين وما ... نلت فيه من نعيم لو يدوم)\n(إن يكن أعظمت أن همت به ... فالذي تركب من عذلي عظيم)\n(لم أكن أول من سن الهوى ... فدع اللوم فذا داء قديم)\nلغناء لعبد الله هزج بالوسطى\nحدثي أبو بكر الربيعي قال حدثتني عمتي وكانت ربيت في دار عمها عبد الله بن العباس قالت كان عبد الله لا يفارق الصبوح أبدا إلا في يوم جمعة أو شهر رمضان وإذا حج وكانت له وصيفة يقال لها هيلانة قد رباها وعلمها الغناء فأذكره يوما وقد اصطبح وأنا في حجره جالسة والقدح في يده اليمنى وهو يلقي على الصبية صوتا أوله\n(صدع البين الفؤادا ... إذ به الصائح نادى)\nهو يردده ويومىء بجميع أعضائه إليها يفهمها نغمه ويوقع بيده على كتفي مرة وعلى فخذي أخرىوهو لا يدري حتى أوجعني فبكيت وقلت قد أوجعتني مما تضربني وهيلانة لا تأخذ الصوت وتضربني أنا فضحك حتى استلقى واستملح قولي فوهب لي ثوب قصب أصفر وثلاثة دنانير جددا فما أنسى فرحي بذلك وقيامي به إلى أمي وأنا أعدو إليها وأضحك فرحا به","topic":"أخبار عويف ونسبه","topicNo":252,"sp":25,"spl":"المتوكل يفضله على سائر المغنين — قصته مع المرابين"},
{"id":"b252-35","bab":"الجزء 19","sec":"نسبة هذا الصوت","page":"ج19 ص274","text":"صوت\n(صدع البين الفؤادا ... إذ به الصائح نادى)\n(بينما الأحباب مجموعون ... إذ صاروا فرادى)\n(فأتى بعض بلادا ... وأتى بعض بلادا)\n(كلما قلت تناهى ... حدثان الدهر عادا)\nالشعر والغناء لعبد الله هزج بالوسطى عن عمرو صوت\n(حضر الرحيل وشدت الأحداج ... وغدا بهن مشمر مزعاج)\nللشوق نيران قدحن بقلبه ... حتى استمر به الهوى الملجاج أزعج هواك إلى الذين تحبهم ... إن المحب يسوقه الإزعاج لن يدنينك للحبيب ووصله ... إلا السرى والبازل الهجهاج\nالشعر لسلم الخاسر والغناء لهاشم بن سليمان ثقيل أول بالوسطى","topic":"أخبار عويف ونسبه","topicNo":252,"sp":26,"spl":"نسبة هذا الصوت"},
{"id":"b253-1","bab":"الجزء 19","sec":"أخبار سلم الخاسر ونسبه","page":"ج19 ص276","text":"سلم بن عمر ومولى بن تيم بن مرة ثم مولى أبي بكر الصديق رضوان الله عليه بصري شاعر مطبوع متصرف في فنون الشعر من شعراء الدولة العباسية وهو راوية بشار بن برد وتلميذه وعنه أخذ ومن بحره اغترف وعلى مذهبه ونمطه قال الشعر ولقب سلم بالخاسر فيما تعال لأنه ورث من أبيه مصحفا فباعه واشترى بثمنه طنبورا وقيل بل خلف له أبوه مالا فأنفقه على الأدب والشعر فقال له بعض أهله إنك لخاسر الصفقة فلقب بذلك وكان صديقا لإبراهيم الموصلي ولأبي العتاهية خاصة من الشعراء والمغنين ثم فسد ما بينه وبين أبي العتاهية وكان سلم منقطعا إلى البرامكة وإلى الفضل بن يحي خصوصا من بينهم وفيه يقول أبو العتاهية\n(إنما الفضل لسلم وحده ... ليس فيه لسوى سلم درك)\nكان هذا أحد الأسباب في فساد ما بينه وبين أبي العتاهية ولسلم يقول أبو العتاهية وقد حج مع عتبة\n(والله والله ما أبالي متى ... مامت يا سلم بعد ذا السفر)\nأليس قد طفت حيث طافت وقبلت ... الذي قبلت من الحجر وله يقول أبو العتاهية وقد حبس إبراهيم الموصلي\n(سلم يا سلم ليس دونك سر ... حبس الموصلي فالعيش مر)\n(ما استطاب اللذات مذ سكن المطبق ... رأس اللذات والله حر)\n(ترك الموصلي من خلق الله ... جميعا وعيشهم مقشعر)","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":0,"spl":"أخبار سلم الخاسر ونسبه — باع مصحفه ليشتري طنبورا"},
{"id":"b253-2","bab":"الجزء 19","sec":"سلم ولقبه","page":"ج19 ص276","text":"أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني علي بن الحسن الواسطي قال حدثني أبو عمرو سعيد بن الحسن الباهلي الشاعر قال لما مات عمرو أبو سلم الخاسر اقتسموا ميراثه فوقع في قسط سلم مصحف فرده وأخذ مكانه دفاتر شعر كانت عند أبيه فلقب الخاسر بذلك أخبرني الحسن قال حدثني محمد بن القاسم بن مهرويه قال حدثني محمد بن عمر الجرجاني قال ورث سلم الخاسر أباه مائة ألف درهم فأنفقها على الأدب وبقي لا شيء عنده فلقبه الجيران ومن يعرفه بسلم الخاسر وقالوا أنفق ماله على ما لا ينفعه ثم مدح المهدي أو الرشيد وقد كان بلغه اللقب الذي لقب به فأمر له بمائة ألف درهم وقال له كذب بهذا المال جيرانك فجاءهم بها وقال لهم هذه المائة الألف التي أنفقتها وربحت الأدب فأنا سلم الرابح لا سلم الخاسر","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":0,"spl":"أخبار سلم الخاسر ونسبه — باع مصحفه ليشتري طنبورا"},
{"id":"b253-3","bab":"الجزء 19","sec":"باع مصحفه ليشتري طنبورا","page":"ج19 ص277","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي عن أبيه قال\nإنما لقب سلم الخاسر لأنه ورث عن أبيه مصحفا فباعه واشترى بثمنه طنبورا أخبرني محمد بن العباس اليزيدي قال حدثني عمر الفضل قال قال لي الجماز سلم الخاسر خالي لحا فسألته لم لقب الخاسر فضحك ثم قال إنه قد كان نسك مدة يسيرة ثم رجع إلى أقبح ما كان عليه وباع مصحفا له ورثه عن أبيه وكان لجده قبله واشترى بثمنه طنبورا فشاع خبره وافتضح فكان يقال له ويلك هل فعل أحد ما فعلت فقال لم أجد شيئا أتوسل به إلى إبليس هو أقر لعينه من هذا أخبرني عمي قال أنبأنا عبد الله بن أبي سعد قال حدثني أحمد بن صالح المؤدب وأخبرنا يحيى بن علي بن يحيى إجازة قال حدثني أبي عن أحمد بن صالح قال قال بشار بن برد صوت\n(لا خير في العيش إن دمنا كذا أبدا ... لا نلتقي وسبيل الملتقى نهج)\n(قالوا حرام تلاقينا فقلت لهم ... ما في التلاقي ولا في غيره حرج)\n(من راقب الناس لم يظفر بحاجته ... وفاز بالطيبات الفاتك اللهج)\nال فقال سلم الخاسر أبياتا ثم أخذ معنى هذا البيت فسلخه وجعله في قوله\n(من راقب الناس مات غما ... وفاز باللذة الجسور)","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":0,"spl":"أخبار سلم الخاسر ونسبه — باع مصحفه ليشتري طنبورا"},
{"id":"b253-4","bab":"الجزء 19","sec":"سرق معنى بيت لبشار فغضب عليه","page":"ج19 ص278","text":"فبلغ بيته بشارا فغضب واستشاط وحلف ألا يدخل إليه ولا يفيده ولا\nينفعه مادام حيا فاستشفع إليه بكل صديق له وكل من يثقل عليه رده فكلموه فيه فقال أدخلوه إلي فأدخلوه إليه فاستدناه ثم قال إيه يا سلم من الذي يقول\n(من راقب الناس لم يظفر بحاجته ... وفاز بالطيبات الفاتك اللهج)\nال أنت يا أبا معاذ قد جعلني الله فداءك قال فمن الذي يقول\n(من راقب الناس مات غما ... وفاز باللذة الجسور)\nال تلميذك وخريجك وعبدك يا أبا معاذ فاجتذبه إليه وقنعه بمخصرة كانت في يده ثلاثا وهو يقول لا أعود يا أبا معاذ إلى ما تنكره ولا آتي شيئا تذمه إنما أنا عبدك وتلميذك وصنيعتك وهو يقول له يا فاسق أتجيء إلى معنى قد سهرت له عيني وتعب فيه فكري وسبقت الناس إليه فتسرقه ثم تختصره لفظا تقربه به لتزري علي وتذهب بيتي وهو يحلف له إلا يعود والجماعة يسألونه فبعد لأي وجهد ما شفعهم فيه وكف عن ضربه ثم رجع له ورضي عنه أخبرني أحمد بن عبيد الله بن عمار قال أخبرني يعقوب بن إسرائيل مولى المنصور قال حدثني عبد الوهاب بن مرار قال حدثني أبو معاذ النميري رواية بشار قال قد كان بشار قال قصيدة فيها هذا البيت\n(من راقب الناس لم يضفر بحاجته ... وفاز بالطيبات الفاتك اللهج)\nال فقلت له يا أبا معاذ قد قال سلم الخاسر بيتا هو أحسن وأخف على الألسن من بيتك هذا قال وما هو فقلت\n(من راقب الناس مات غما ... وفاز باللذة الجسور)\nفقال بشار ذهب والله بيتنا أما والله لوددت أنه ينتمي في غير ولاء أبي بكر رضي الله عنه وأني مغرم ألف دينار محبة مني لهتك عرضه وأعراض مواليه قال فقلت له ما أخرج هذا القول منك إلا غم قال أجل فو الله لا طعمت اليوم طعاما وصمت\nأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني ابن إسحاق بن محمد النخعي قال قال أبو معاذ النميري قال بشار قصيدة وقال فيها\n(من راقب الناس لم يظفر بحاجته ... وفاز بالطيبات الفاتك اللهج)\n... فعرفته أن سلما قد قال\n(من راقب الناس مات غما ... وفاز باللذة الجسور)\nلما سمع بشار هذا البيت قال سار والله بيت سلم وخمل بيتنا قال وكان كذلك لهج الناس ببيت سلم ولم ينشد بيت بشار أحد أخبرني محمد بن عمران الصيرفي قال حدثني الحسن بن عليل العنزي قال حدثني أبو مالك محمد بن موسى اليماني قال لما بنى صالح بن المنصور قصره بدجلة قال فيه سلم الخاسر\n(يا صالح الجود الذي مجده ... أفسد مجد الناس بالجود)\n(بنيت قصرا مشرفا عاليا ... بطائري سعد ومسعود)\n(كأنما يرفع بنيانه ... جن سليمان بن داود)\n(لازلت مسرورا به سالما ... على اختلاف البيض والسود)\nيعني الأيام والليالي فأمر له صالح بألف درهم أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني بعض آل ولد حمدون بن إسماعيل وكان ينادم المتوكل عن أبيه قال كان سلم الخاسر من غلمان بشار فلما قال بشار قصيدته الميمية في عمر بن العلاء وهي التي يقول فيها\n(إذا نبهتك صعاب الأمور ... فنبه لها عمرا ثم نم)\n(فتى لا يبيت على دمنة ... ولا يشرب الماء إلا بدم)\nعث بها مع سلم الخاسر إلى عمر بن العلاء فوافاه فأنشده إياها فأمر لبشار بمائة ألف درهم فقال له سلم إن خادمك يعني نفسه قد قال في طريقه فيك قصيدة قال فإنك لهناك قال تسمع ثم تحكم ثم قال هات فأنشده صوت قد عزني الداء فمالي دواء ... مما ألاقي من حسان النساء قلب صحيح كنت أسطو به ... أصبح من سلمى بداء عياء أنفاسها مسك وفي طرفها ... سحر ومالي غيرها من دواء وعدتني وعدا فأوفي به ... هل تصلح الخمرة إلا بماء\nويقول فيها\n(كم كربة قد مسني ضرها ... ناديت فيها عمر بن العلاء)\nال فأمر له بعشرة آلاف درهم فكانت أول عطية سنية وصلت إليه","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":1,"spl":"سرق معنى بيت لبشار فغضب عليه"},
{"id":"b253-5","bab":"الجزء 19","sec":"سلم وعاصم بن عتبة","page":"ج19 ص282","text":"أخبرني الحسن بن علي قال حدثني ابن مهرويه قال وجدت في كتاب بخط الفضل بن مروان وكان عاصم بن عتبة الغساني جد أبي السمراء الذي كان مع عبد الله بن طاهر صديقا لسلم الخاسر كثير البر به والملاطفة له وفيه يقول سلم\n(الجود في قحطان ... ما بقيت غسان)\n(اسلم ولا أبالي ... ما فعل الإخوان)\nا ضر مرتجيه ... ما فعل الزمان من غاله مخوف ... فعاصم أمان\nكانت سبعين بيتا فأعطاه عاصم سبعين ألف درهم وكان مبلغ ما وصل إلى سلم من عاصم خمسائة الف درهم فلما حضرته الوفاة دعا عاصما فقال له إني ميت ولا ورثة لي وإن مالي مأخوذ فأنت أحق به فدفع إليه خمسائة ألف درهم ولم يكن لسلم وارث قال وكان عاصم هذا جوادا أخبرني محمد بن خلف وكيع قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن طهمان قال أخبرني القاسم بن موسى بن مزيد\nأن يزيد بن مزيد قال ما حسدت أحدا قط على شعر مدح به إلا عاصم بن عتبة الغساني فإني حسدته على قول سلم الخاسر فيه\n(لعاصم سماء ... عارضها تهتان)\n(أمطارها اللجين ... والدر والعقيان)\n(وناره تنادي ... إذ خبت النيران)\n(الجود في قحطان ... ما بقيت غسان)\n(اسلم ولا أبالي ... ما فعل الإخوان)\n(صلت له المعالي ... والسيف والسنان)\nخبرني أحمد بن عبيد الله بن عمار قال حدثنا يعقوب بن نعيم عن محمد ابن القاسم بن مهرويه وأخبرني به الحسن بن علي عن أبن مهرويه عن الغريبي عن محمد بن عمر الجرجاني قال كان سلم تلميذ بشار إلا أنه كان تباعد ما بينهما فكان سلم يقدم أبا العتاهية ويقول هو أشعر الجن والإنس إلى أن قال أبو العتاهية يخاطب سلما\n(تعالى الله يا سلم بن عمرو ... أذل الحرص أعناق الرجال)\n(هب الدنيا تصير إليك عفوا ... أليس مصير ذاك إلى زوال)\nال وبلغ الرشيد هذا الشعر فاستحسنه وقال لعمري إن الحرص لمفسدة لأمر الدين والدنيا وما فتشت عن حريص قط مغيبه إلا انكشف لي عما أذمه وبلغ ذلك سلما فغضب على أبي العتاهية وقال ويلي على الجرار ابن الفاعلة الزنديق زعم أني حريص وقد كنز البدور وهو يطلب وأنا في ثوبي\nهذين لا أملك غيرهما وانحرف عن أبي العتاهية بعد ذلك","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":2,"spl":"سلم وعاصم بن عتبة"},
{"id":"b253-6","bab":"الجزء 19","sec":"خبره مع أبي العتاهية","page":"ج19 ص284","text":"أخبرني محمد بن يحيى الصولي حدثنا محمد بن موسى قال أخبرني محمد بن إسماعيل السدوسي قال حدثني جعفر العاصمي وأخبرني عمي عن أحمد بن أبي طاهر عن القاسم بن الحسن عن زكريا بن يحيى المدائني عن علي بن المبارك القضاعي عن سلم الخاسر أن أبا العتاهية لما قال هذا الشعر فيه كتب إليه\n(ما أقبح التزهيد من واعظ ... يزهد الناس ولا يزهد)\n(لو كان في تزهيده صادقا ... أضحى وأمسى بيته المسجد)\n(ورفض الدنيا ولم يلقها ... ولم يكن يسعى ويسترفد)\n(يخاف أن تنفد أرزاقه ... والرزق عند الله لا ينفد)\n(الرزق مقسوم على من ترى ... يناله الأبيض والأسود)\n(كل يوفى رزقه كاملا ... من كف عن جهد ومن يجهد)\nخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أبو العسكر المسمعي وهو محمد بن سلميان قال حدثني العباس بن عبد الله بن سنان بن عبد الملك بن مسمع قال كنا عند قثم بن جعفر بن سليمان وهو يومئذ أمير البصرة وعنده أبو العتاهية ينشده شعره في الزهد فقال لي قثم يا عباس اطلب لي الجماز الساعة حيث كان فجئني به ولك سبق فطلبته فوجدته جالسا ناحية عند ركن دار جعفر بن سليمان فقلت له أجب الأمير فقام معي حتى أتى قثم فجلس في\nناحية مجلسه وأبو العتاهية ينشده ثم قام إليه الجماز فواجهه وأنشد قول سلم الخاسر فيه\n(ما أقبح التزهيد من واعظ ... يزهد الناس ولا يزهد)\n(لو كان في تزهيده صادقا ... أضحى وأمسى بيته المسجد)\nذكر الأبيات كلها فقال أبو العتاهية من هذا أعز الله الأمير قال هذا الجماز وهو ابن أخت سلم الخاسر انتصر لخاله منك حيث قلت له\n(تعالى الله يا سلم بن عمرو ... أذل الحرص أعناق الرجال)\nال فقال أبو العتاهية للجماز يا بن أخي إني لم أذهب في شعري الأول حيث ذهب خالك ولا أردت أن أهتف به ولا ذهبت أيضا في حضوري وإنشادي حيث ذهبت من الحرص على الرزق والله يغفر لكما ثم قام فانصرف أخبرني عمي عن أحمد بن أبي طاهر عن أبي هفان قال وصل إلى سلم الخاسر من آل برمك خاصة سوى ما وصل إليه من غيرهم عشرون ألف دينار ووصل إليه من الرشيد مثلها أخبرني محمد بن العباس اليزيدي قال حدثني عماي عبيد الله والفضل عن أبيهما عن أبي محمد اليزيدي أنه حضر مجلس عيسى بن عمر وحضر سلم الخاسر فقال له يا أبا محمد اهجني على روي قصيدة امرىء القيس\n(رب رام من بني ثعل ... مخرج كفيه في ستره)\nال فقلت له ما دعاك إلى هذا قال كذا أريد فقلت له يا هذا أنا وأنت أغنى الناس عما تستدعيه من الشر فلتسعك العافية فقال إنك لتحتجز\nمني نهاية الإحتجاز وأراد أن يوهم عيسى أني مفحم عيبي لا أقدر على ذلك فقال لي عيسى أسألك يا أبا محمد بحقي عليك إلا فعلت فقلت\n(رب مغموم بعاقبة ... غمط النعمة من أشره)\n(وامرىء طالت سلامته ... فرماه الدهر من غيره)\n(بسهام غير مشوية ... نقضت منه قوى مرره)\n(وكذاك الدهر منقلب ... بالفتى حالين من عصره)\n(يخلط العسر بميسرة ... ويسار المرء في عسره)\n(عق سلم أمه صغرا ... وأبا سلم على كبره)\n(كل يوم خلفه رجل ... رامح يسعى على أثره)\n(يولج الغرمول سبته ... كولوج الضب في جحره)\nال فاغتم سلم وندم وقال هكذا تكون عاقبة البغي والتعرض للشر فضحك عيسى وقال له قد جهد الرجل أن تدعه وصيانته ودينه فأبيت إلا أن يدخلك في حر أمك","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":3,"spl":"خبره مع أبي العتاهية"},
{"id":"b253-7","bab":"الجزء 19","sec":"ترفهه عندما يأتي المهدي","page":"ج19 ص286","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني علي بن محمد النوفلي قال سمعت أبي يقول\nكان المهدي يعطي مروان وسلما الخاسر عطية واحدة فكان سلم يأتي باب المهدي على البرذون الفأره قيمته عشرة آلاف درهم بسرج ولجام مفضضين ولباسه الخز والوشي وما أشبه ذلك من الثياب الغالية الأثمان ورائحة المسك والطيب والغالية تفوح منه ويجيء مروان بن أبي حفصة عليه فرو كبل وقميص كرابيس وعمامة كرابيس وخفا كبل وكساء غليظ وهو منتن الرائحة وكان لا يأكل اللحم حتى يقرم إليه بخلا فإذا قرم أرسل غلامه فاشترى له رأسا فأكله فقال له قائل أراك لا تأكل إلا الرأس قال نعم أعرف سعره فآمن خيانة الغلام ولا أشتري لحما فيطبخه فيأكله منه والرأس آكل من ه ألوانا آكل منه عينيه لونا ومن غلصمته لونا ومن دماغه لونا أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا يحيى بن الحسن الربيعي قال أخبرني أبي قال كان سلم الخاسر قد بلي بالكيمياء فكان يذهب بكل شيء له باطلا فلما أراد الله عز و جل أن يصنع له عرف أن بباب الشام صاحب كيمياء عجيبا وأنه لا يصل إليه أحد إلا ليلا فسأل عنه فدلوه عليه قال فدخلت إليه إلى موضع معور فدققت الباب فخرج إلي فقال\nمن أنت عافاك الله فقلت رجل معجب بهذا العلم قال فلا تشهرني فإني رجل مستور إنما أعمل للقوت قال قلت إني لا أشهرك إنما أقتبس منك قال فاكتم ذلك قال وبين يديه كوز شبه صغير فقال لي اقلع عروته فقلعتها فقال اسبكها في البوطقة فسبكتها فأخرج شيئا من تحت مصلاه فقال ذره عليه ففعلت فقال أفرغه فأفرغته فقال دعه معك فإذا أصبحت فاخرج فبعه وعد إلي فأخرجته إلى باب الشام فبعت المثقال بأحد وعشرين درهما ورجعت إليه فأخبرته فقال اطلب الآن ما شئت قلت تفيدني قال بخمسمائة درهم على أن لا تعلمه أحدا فأعطيته وكتب لي صفة فامتحنتها فإذا هي باطلة فعدت إليه فقيل لي قد تحول وإذا عروة الكوز المشبه من ذهب مركبة عليه والكوز شبه ولذلك كان يدخل إليه من يطلبه ليلا ليخفي عليه فانصرفت وعلمت أن الله عز و جل أراد بي خيرا وأن هذا كله باطل أخبرني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثني أبو مالك اليماني قال حدثني أبو كعب قال لما ماتت البانوكة بنت المهدي رثاها سلم الخاسر بقوله\n(أودى ببانوكة ريب الزمان ... مؤنسة المهدي والخيزران)\n(لم تنطو الأرض على مثلها ... مولودة حن لها الوالدان)\n(بانوك يا بنت إمام الهدى ... أصبحت من زينة أهل الجنان)\n(بكت لك الأرض وسكانها ... في كل أفق بين إنس وجان)\nخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني علي بن الحسن الشيباني قال حدثني أبو المستهل الأسدي وهو عبد الله بن تميم بن\nحمزة قال كان سلم الخاسر يهاجي والبة بن الحباب فأرسلني إليه سلم وقال قل له\n(يا والب بن الحباب يا حلقي ... لست من أهل الزناء فانطلق)\n(تدخل فيه الغرمول تولجه ... مثل ولوج المفتاح في الغلق)\nال فأتيت والبة فقلت له ذلك فقال لي قل له يا بن الزانية سل عنك ريعان التميمي يعني أنه ناكه قال وكان ريعان لوطيا آفة من الآفات وكان علامة ظريفا قال فحدثني جعفر بن قدامة عن محمد العجلي عن أحمد بن معاوية الباهلي قال سمعت ريعان يقول نكت الهيثم بن عدي فمن ترونه يفلت مني بعده وأخبرني أحمد بن العباس العسكري قال حدثنا العنزي قال حدثني أبو مالك محمد بن موسى اليماني قال كان سلم الخاسر مدح بعض العلويين فبلغ ذلك المهدي فتوعده وهم به فقال سلم فيه\n(إني أتتني على المهدي معتبة ... تكاد من خوفها الأحشاء تضطرب)\n(اسمع فداك بنو حواء كلهم ... وقد يجوز برأس الكاذب الكذب)\n(فقد حلفت يمينا غير كاذبة ... يوم المغيبة لم يقطع لها سبب)\n(ألا يحالف مدحي غيركم أبدا ... ولو تلاقى علي الغرض والحقب)\n(ولو ملكت عنان الريح أصرفها ... في كل ناحية ما فاتها الطلب)\n(مولاك مولاك لا تشمت أعاديه ... فما وراءك لي ذكر ولا نسب)\nفعفا عنه","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":4,"spl":"ترفهه عندما يأتي المهدي"},
{"id":"b253-8","bab":"الجزء 19","sec":"سلم يحسن الرثاء لا المدح","page":"ج19 ص290","text":"وأخبرني أحمد بن العباس وأحمد بن عبيد الله بن عمار قالا حدثنا العنزي قال حدثني العباس بن عبد الواحد بن جعفر بن سليمان قال حدثني موسى بن عبد الله بن شهاب المسمعي قال سمعت أبا عبيدة معمر بن المثنى يقول كان سلم الخاسر لا يحسن أن يمدح ولكنه كان يحسن أن يرثي ويسأل أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني علي بن الحسن الشيباني قال حدثني أبو المستهل قال دخلت يوما على سلم الخاسر وإذا بين يديه قراطيس فيها أشعار يرثي وببعضها أم جعفر وبعضها جارية غير مسماة وببعضها أقواما لم يموتوا وأم جعفر يومئذ باقية فقلت له ويحك ما هذا فقال تحدث الحوادث فيطالبوننا بأن نقول فيها ويستعجلوننا ولا يجمل بنا أن نقول غير الجيد فنعد لهم هذا قبل كونه فمتى حدث حادث أظهرنا ما قلناه فيه قديما على أنه قيل في الوقت\nأخبرني محمد بن مزيد وعيسى بن الحسين قالا حدثنا الزبير بن بكار قال قال عبد الله بن الحسن الكاتب أنشد المأمون قول أبي العتاهية\n(تعالى الله يا سلم بن عمرو ... أذل الحرص أعناق الرجال)\nفقال المأمون صدق لعمر الله إن الحرص لمفسدة للدين والمروءة والله ما رأيت من رجل قط حرصا ولا شرها فرأيت فيه مصطنعا فبلغ ذلك سلما الخاسر فقال ويلي على ابن الفاعلة بياع الخزف كنز البدور بمثل ذلك الشعر المفكك الغث ثم تزهد بعد أن استغنى وهو دائبا يهتف بي وينسبني إلى الحرص وأنا لا أملك إلا ثوبي هذين","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":5,"spl":"سلم يحسن الرثاء لا المدح"},
{"id":"b253-9","bab":"الجزء 19","sec":"سلم وأبو الشمقمق","page":"ج19 ص291","text":"أخبرني عمي والحسن بن علي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثنا زكريا بن مهران قال طالب أبو الشمقمق سلما الخاسر بأن يهب له شيئا وقد خرجت لسلم جائزة فلم يفعل فقال أبو الشمقمق يهجوه\n(يا أم سلم هداك الله زورينا ... كيما ننيكك فردا أو تنيكينا)\n(ما إن ذكرتك إلا هاج لي شبق ... ومثل ذكراك أم السلم يشجينا)\nقال فجاءه سلم فأعطاه خمسة دنانير وقال أحب أن تعفيني من استتزارتك أمي وتأخذ هذه الدنانير فتنفقها أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني يحيى بن الحسن بن عبد الخالق قال حدثني محمد بن القاسم بن الربيع عن أبيه قال دخل الربيع على المهدي وأبو عبيد الله جالس يعرض كتبا فقال له أبو عبيد الله مر هذا أن يتنحى يعني الربيع فقال له المهدي تنح فقال لا أفعل فقال كأنك تراني بالعين الأولى فقال لا بل أراك بالعين التي أنت بها قال فلم لا تتنحى إذ أمرتك فقال له أنت ركن الإسلام وقد قتلت ابن هذا فلا آمن أن يكون معه حديدة يغتالك بها فقام المهدي مذعورا وأمر بتفتيشه فوجدوا بين جوربه وخفه سكينا فردت الأمور كلها إلى الربيع وعزل أبو عبيد الله وولي يعقوب بن داود فقال سلم الخاسر فيه\n(يعقوب ينظر في الأمور ... وأنت تنظر ناحيه)\n(أدخلته فعلا عليك ... كذاك شؤم الناصيه)\nال وكان بلغ المهدي من جهة الربيع أن ابن عبيد الله زنديق فقال له المهدي هذا حسد منك فقال افحص عن هذا فإن كنت مبطلا بلغت مني الذي يلزم من كذبك فأتى بابن عبيد الله فقرره تقريرا خفيا فأقر بذلك فاستتابه فأبى أن يتوب فقال لأبيه اقتله فقال لا تطيب نفسي بذلك فقتله وصلبه على باب أبي عبيد الله\nقال وكان ابن أبي عبيد الله هذا من أحمق الناس وهب له المهدي وصيفة ثم سأله بعد ذلك عنها فقال ما وضعت بيني وبين الأرض حشية قط أوطأ منها حاشا سامع فقال المهدي لأبيه أتراه يعنيني أو يعنيك قال بل يعني أمه الزانية لا يكني أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني يحيى بن الحسن قال حدثني أبي قال كنت أنا والربيع نسير قريبا من محمل المنصور حين قال للربيع رأيت كأن الكعبة تصدعت وكأن رجلا جاء بحبل أسود فشددها فقال له الربيع من الرجل فلم يجبه حتى إذا اعتل قال للربيع أنت الرجل الذي رأيته في نومي شدد الكعبة فأي شيء تعمل بعدي قال ما كنت أعمل في حياتك فكان من أمره في أخذ البيعة للمهدي ما كان فقال سلم الخاسر في الفضل بن الربيع\n(يا بن الذي جبر الإسلام يوم وهى ... واستنقذ الناس من عمياء صيخود)\n(قالت قريش غداة انهاض ملكهم ... أين الربيع وأعطوا بالمقاليد)\n(فقام بالأمر مئناس بوحدته ... ماضي العزيمة ضراب القماحيد)\n(إن الأمور إذا ضاقت مسالكها ... حلت يد الفضل منها كل معقود)\n(إن الربيع وإن الفضل قد بنيا ... رواق مجد على العباس ممدود)\nال فوهب له الفضل خمسة آلاف دينار أخبرني عمي قال حدثنا أبو هفان قال حدثني سعيد أبو هريم وأبو دعامة قالا لما قال سلم الخاسر في الرشيد حين عقد لابنه محمد الأمين\n(قد بايع الثقلان في مهد الهدى ... لمحمد بن زبيدة ابنة جعفر)\n(وليته عهد الأنام وأمرهم ... فدمغت بالمعروف رأس المنكر)\nعطته زبيدة مائة ألف درهم أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن عمرو قال حدثني أحمد بن علي الخراساني عن يحيى بن الحسن بن عبد الخالق عن أبيه قال قال سلم الخاسر في المهدي قصيدته التي يقول فيها\n(له شيمة عند بذل العطاء ... لا يعرف الناس مقدارها)\n(ومهدي أمتنا والذي ... حماها وأدرك أوتارها)\nفأمر له المهدي بخمسمائة ألف درهم أخبرنا وكيع قال حدثنا عبد الله بن سليمان قال حدثنا منصور بن أبي مزاحم قال شهدت المهدي وقد أمر لمروان بن أبي حفصة بأربعين ألف درهم وفرض له على أهل بيته وجلسائه ثلاثين ألف درهم وأمر الرشيد بعد ذلك لما ولى الخلافة لسلم الخاسر وقد مدحه بسبعين ألف درهم فقال له يا أمير المؤمنين إن أكثر ما أعطى المهدي مروان ألف درهم فزدني وفضلني عليه ففعل ذلك وأعطاه تتمة ثمانين ألف درهم فقال سلم\n(ألا قل لمروان أتتك رسالة ... لها نبأ لا ينثني عن لقائكا)\n(حباني أمير المؤمنين بنفحة ... مشهرة قد طأطأت من حبائكا)\n(ثمانين ألفا حزت من صلب ماله ... ولم يك قسما من أولى وأولائكا)\nفأجابه مروان فقال","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":6,"spl":"سلم وأبو الشمقمق"},
{"id":"b253-10","bab":"الجزء 19","sec":"سلم وأبو الشمقمق","page":"ج19 ص291","text":"(أسلم بن عمرو قد تعاطيت غاية ... تقصر عنها بعد طول عنائكا)\n(فأقسم لولا ابن الربيع ورفده ... لما ابتلت الدلو التي في رشائكا)\n(وما نلت مذ صورت إلا عطية ... تقوم بها مصرورة في ردائكا)","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":7,"spl":"سلم وأبو الشمقمق — مات سلم فوهب الرشيد تركته"},
{"id":"b253-11","bab":"الجزء 19","sec":"مات سلم فوهب الرشيد تركته","page":"ج19 ص295","text":"حدثني وسواسة بن الموصلي وهو محمد بن أحمد بن إسماعيل بن إبراهيم قال حدثني حماد عن أبيه قال استوهب أبي من الرشيد تركة سلم الخاسر وكان قد مات عن غير وارث فوهبها له قبل أن يتسلمها صاحب المواريث فحصل منها خمسين ألف دينار أخبرني عمي قال حدثني أبو هفان عن سعيد بن هديم وأبي دعامة أنه رفع إلى الرشيد أن سلما الخاسر قد توفي وخلف مما أخذه منه خاصة ومن زبيدة ألف ألف وخمسمائة ألف درهم سوى ما خلفه من عقار وغيره مما اعتقده قديما فقبضه الرشيد وتظلم إليه مواليه من آل أبي بكر الصديق رضوان الله عليه فقال هذا خادمي ونديمي والذي خلفه من مالي فأنا أحق به فلم يعطهم إلا شيئا يسيرا من قديم أملاكه أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل عن القحذمي قال كان مالك وشهاب ابنا عبد الملك بن مسمع ومعن بن زائدةمتواخين لا يكادون يفترقون وكان سلم الخاسر ينادمهم ويمدحهم ويفضلون عليه ولا يحوجونه إلى غيرهم فتوفي مالك ثم أخوه ثم معن في مدة متقاربة فقال سلم يرثيهم\n(عين جودي بعبرة تهتان ... واندبي من أصاب ريب الزمان)\n(وإذا ما بكيت قوما كراما ... فعلى مالك أبي غسان)\n(أين معن أبو الوليد ومن كان ... غياثا للهالك الحيران)\n(طرقتك المنون لا واهي مثل الحبل ... ولا عاقدا بحلف يمان)\n(وشهاب وأين مثل شهاب ... عند بذل الندى وحر الطعان)\n(رب خرق رزئته من بني قيس وخرق رزئت من شيبان ... )\n(در در الأيام ماذا أجنت ... منهم في لفائف الكتان)\n(ذاك معن ثوى ببست رهينا ... وشهاب ثوى بأرض عمان)\n(وهما ما هما لبذل العطايا ... وللف الأقران بالأقران)\n(يسبقان المنون طعنا وضربا ... ويفكان كل كبل وعان)\nخبرني وكيع قال حدثني يزيد بن محمد المهلبي قال حدثني عبد الصمد بن المعذل قال لما أنشد سلم الخاسر الرشيد قصيدته فيه\n(حضر الرحيل وشدت الأحداج ... )\nمر له بمائة ألف درهم حدثني جحظة قال حدثني ميمون بن هارون قال\nدخل سلم الخاسر على الفضل بن يحي في يوم نيروز والهدايا بين يديه فأنشده\n(أمن ربع تسائله ... وقد أقوت منازله)\n(بقلبي من هوى الأصلال ... حب ما يزايله)\n(رويدكم عن المشغوف ... إن الحب قاتله)\n(بلابل صدره تسرى ... وقد نامت عواذله)\n(أحق الناس بالتفضيل ... من ترجى فواضله)\n(رأيت مكارم الأخلاق ... ما ضنت حمائله)\n(فلست أرى فتى في الناس ... إلا الفضل فاضله)\n(يقول لسانه خيرا ... فتفعله أنامله)\n(ومهما يرج من خير ... فإن الفضل فاعله)\nكان إبراهيم الموصلي وابنه إسحاق حاضرين فقال لإبراهيم كيف ترى وتسمع قال أحسن مرئي ومسموع وفضل الأمير أكثر منه فقال خذوا جميع ما أهدي إلي اليوم فاقتسموه بينكم أثلاثا إلا ذلك التمثال فإني أريد أن أهديه اليوم إلى دنانير ثم قال لا والله ما هكذا تفعل الأحرار يقوم وندفع إليهم ثمنه ثم نهديه فقوم بألفي دينار فحملها إلى القوم من بيت ماله واقتسموا جميع الهدايا بينهم\nأخبرني هاشم بن محمد الخزاعي قال حدثني عيسى بن إسماعيل تينة قال حدثني القحذمي قال قيل لمعن بن زائدة ما أحسن ما مدحت به من الشعر عندك قال قول سلم الخاسر\n(أبلغ الفتيان مألكة ... أن خير الود ما نفعا)\n(أن قرما من بني مطر ... أتلفت كفاه ما جمعا)\n(كلما عدنا لنائله ... عاد في معروفه جذعا)\nخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني أبو توبة وأخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه عن أبي توبة قال حدث في أيام الرشيد أمر فاحتاج فيه إلى الرأي فأشكل وكان الفضل بن يحي غائبا فورد في ذلك الوقت فأخبروه بالقصة فأشار بالرأي في وقته وأنفذ الأمر على مشورته فحمد ما جرى فيه فدخل عليه سلم الخاسر فأنشده\n(بديهته وفكرته سواء ... إذا ما نابه الخطب الكبير)\n(وأحزم ما يكون الدهر رأيا ... إذا عي المشاور والمشير)\nأمر له بعشرة آلاف درهم","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":7,"spl":"سلم وأبو الشمقمق — مات سلم فوهب الرشيد تركته","partialRef":{"sid":"b152-4","gi":7,"vi":0,"side":0},"partial":1},
{"id":"b253-12","bab":"الجزء 19","sec":"اشترى سكوت أبي الشمقمق عن هجائه","page":"ج19 ص298","text":"أخبرني جعفر بن قدامة قال حدثني أبو العيناء قال حدثني الجماز أن أبا الشمقمق جاء إلى سلم الخاسر يستميحه فمنعه فقال له اسمع إذا ما قلته وأنشده\n(حدثوني أن سلما ... يشتكي جارة أيره)\n(فهو لا يحسد شيئا ... غير أير في أست غيره)\n(وإذا سرك يوما ... يا خليلي نيل خيره)\n(قم فمر راهبك الأصلع ... يقرع باب ديره)\nضحك سلم وأعطاه خمسة دنانير وقال له أحب جعلت فداك أن تصرف راهبك الأصلع عن باب ديرنا أخبرنا الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أحمد بن أبي كامل قال حدثني أبو دعامة قال دخل سلم الخاسر على الرشيد فأنشده\n(حي الأحبة بالسلام ... )\nقال الرشيد\n(حياهم الله بالسلام ... )\nقال\n(على وداع أم مقام ... )\nقال الرشيد حياهم الله على أي ذلك كان فأنشده\n(لم يبق منك ومنهم ... غير الجلود على الطعام)\nقال له الرشيد بل منك وأمر بإخراجه وتطير منه ومن قوله فلم يسمع منه باقي الشعر ولا أثابه بشيء\nأخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال أتت وفاة المهدي إلى موسى الهادي وهو بجرجان فبويع له هناك فدخل عليه\nسلم الخاسر مع المهنئين فهنأه بخلافة الله ثم أنشده\n(لما أتت خير بني هاشم ... خلافة الله بجرجان)\n(شمر للحزم سرابيله ... برأي لاغمر ولا وان)\n(لم يدخل الشورى على رأيه ... والحزم لا يمضيه رأيان)\nأخبرني الحسن بن علي وعمي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثني صالح بن عبد الرحمن عن أبيه قال دخل سلم الخاسر على الرشيد وعنده العباس بن محمد وجعفر بن يحي فأنشده قوله فيه\n(حضر الرحيل وشدت الأحداج ... )\nلما انتهى إلى قوله\n(إن المنايا في السيوف كوامن ... حتى يهيجها فتى هياج)\nقال الرشيد كان ذلك معن بن زائدة فقال صدق أمير المؤمنين ثم أنشد حتى انتهى إلى قوله\n(ومدجج يغشى المضيق بسيفه ... حتى يكون بسيفه الإفراج)\nقال الرشيد ذلك يزيد بن مزيد فقال صدق أمير المؤمنين فاغتاظ\nجعفر بن يحي وكان يزيد بن مزيد عدوا للبرامكة مصافيا للفضل بن الربيع فلما انتهى إلى قوله\n(نزلت نجوم الليل فوق رؤوسهم ... ولكل قوم كوكب وهاج)\nال له جعفر بن يحي من قلة الشعر حتى تمدح أمير المؤمنين بشعر قيل في غيره هذا لبشار في فلان التميمي فقال الرشيد ما تقول يا سلم قال صدق يا سيدي وهل أنا إلا جزء من محاسن بشار وهل أنطق إلا بفضل منطقه وحياتك يا سيدي إني لأروي له تسعة آلاف بيت ما يعرف أحد غيري منها شيئا فضحك الرشيد وقال ما أحسن الصدق امض في شعرك وأمر له بمائة ألف درهم ثم قال للفضل بن الربيع هل قال أحد غير سلم في طينا المنازل شيئا وكان الرشيد قد انصرف من الحج وطوى المنازل فوصف ذلك فقال الفضل نعم يا أمير المؤمنين النمري فأمر سلما أن يثبت قائما حتى يفرغ النمري من إنشاده فأنشده النمري قوله\n(تخرق سربال الشباب مع البرد ... وحالت لنا أم الوليد عن العهد)\nقال الرشيد للعباس بن محمد أيهما أشعر عندك يا عم قال كلاهما شاعر ولو كان كلام يستفحل لجودته حتى يؤخذ منه نسل لاستفحلت كلام النمري فأمر له بمائة ألف درهم أخرى أخبرني عمي قال أنشدني أحمد بن أبي طاهر لأشجع السلمي يرثي سلما ومات سلم قبله\n(يا سلم إن أصبحت في حفرة ... موسدا تربا وأحجارا)\n(فرب بيت حسن قلته ... خلفته في الناس سيارا)\n(قلدته ربا وسيرته ... فكان فخرا منك أو عارا)\n(لو نطق الشعر بكى بعده ... عليه إعلانا وإسرارا)\nصوت\n(يا ويح من لعب الهوى بحياته ... فأماته من قبل حين مماته)\n(من ذا كذا كان الشقي بشادن ... هاروت بين لسانه ولهاته)\n(وحياة من أهوى فإني لم أكن ... يوما لأحلف كاذبا بحياته)\n(لأخالفن عواذلي في لذتي ... ولأسعدن أخي على لذاته)\nلشعر لبعض شعراء الحجازيين ولم يقع إلينا اسمه والغناء لأبي صدقة رمل بالبنصر","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":8,"spl":"اشترى سكوت أبي الشمقمق عن هجائه","partialRef":{"sid":"b152-4","gi":7,"vi":0,"side":0},"partial":1},
{"id":"b253-13","bab":"الجزء 19","sec":"أخبار أبي صدقة","page":"ج19 ص303","text":"اسمه مسكين بن صدقة من أهل المدينة مولى لقريش وكان مليح الغناء طيب الصوت كثير الرواية صالح الصنعة من أكثر الناس نادرة وأخفهم روحا وأشدهم طمعا وألحهم في مسألة وكان له ابن يقال له صدقة يغني وليس من المعدودين وابن ابنه أحمد بن صدقة الطنبوري أحد المحسنين من الطنبوريين وله صنعة جيدة وكان أشبه الناس بجده في المزح والنوادر وأخباره تذكر بعد أخبار جده وأبو صدقة من المغنين الذي أقدمهم هارون الرشيد من الحجاز في أيامه أخبرني علي بن عبد العزيز عن عبيد الله بن عبد الله قال قيل لأبي صدقة ما : أكثر سؤالك وأشد إلحاحك فقال وما يمنعني من ذلك واسمي مسكين وكنيتي أبو صدقة وامرأتي فاقة وابني صدقة أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال حدثنا أبو إسحاق إبراهيم بن المهدي أن الرشيد قال للحارث بن بسخنر قد اشتهيت أن أرى ندمائي ومن يحضر مجلسي من المغنين جميعا في مجلس واحد يأكلون ويشربون ويتبذلون منبسطين على غير هيبة ولا احتشام بل يفعلون ما يفعلون في منازلهم وعند نظرائهم وهذا لا يتم إلا بأن أكون بحيث لا يرونني عن غير علم منهم برؤيتي إياهم فأعد لي مكانا أجلس فيه أنا وعمي سليمان وإخوتي إبراهيم بن المهدي وعيسى بن جعفر وجعفر بني يحيى\nفإنا مغلسون عليك غداة غد واستزر أنت محمد بن خالد بن برمك وخالدا أخا مهرويه والخضر بن جبريل وجميع المغنين وأجلسهم بحيث نراهم ولا يروننا وابسط الجميع وأظهر برهم واخلع عليهم ولا تدع من الإكرام شيئا إلى فعلته بهم ففعل ذلك الحارث وقدم إليهم الطعام فأكلوا والرشيد ينظر إليهم ثم دعا لهم بالنبيذ فشربوا وأحضرت الخلع وكان ذلك اليوم يوما شديد البرد فخلع على ابن جامع جبة خز طاروني مبطنة بسمور صيني وخلع على إبراهيم الموصلي جبة وشيء كوفي مرتفع مبطنة بفنك وخلع على أبي صدقة دراعة ملحم خراساني محشوة بقز ثم تغنى ابن جامع وتغنى بعده إبراهيم وتلاهما أبو صدقة فغنى لابن سريج\n(ومن أجل ذات الخال أعملت ناقتي ... أكلفها سير الكلال مع الظلع)\nفأجاده واستعاده الحارث ثلاثا وهو يعيده فقال له الحارث أحسنت والله يا أبا صدقة قال له هذا غنائي وقد قرصني البرد فكيف تراه فديتك كان يكون لو كان تحت دراعتي هذه شعيرات يعني الوبر والرشيد يسمع ذلك فضحك فأمر بأن يخلع عليه دراعة ملحم مبطنة بفنك ففعلوا ثم تغنى الجماعة وغنى أبو صدقة لمعبد\n(بان الخليط على بزل مخيسة ... هدل المشافر أدنى سيرها الرمل)\nم تغنى بعده لمعبد أيضا\n(بان الخليط ولو طووعت ما بانا ... وقطعوا من حبال الوصل أقرانا)\nأقام فيهما جميعا القيامة فطرب الرشيد حتى كاد أن يخرج إلى المجلس طربا فقال له الحارث أحسنت والله يا أبا صدقة فديتك وأجملت فقال أبو صدقة فكيف ترى فديتك الحال تكون لو كانت على هذه الدراعة نقيطات يعني الوشي فضحك الرشيد حتى ظهر ضحكه وعلموا بموضعه وعرف علمهم بذلك فأمر بإدخالهم إليه وأمر بأن يخلع على أبي صدقة دراعة أخرى مبطنة فخلعت عليه أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال سأل الحسن بن سليمان أخو عبيد الله بن سليمان الطفيلي الفضل وجعفرا\nابني يحي أن يقيما عنده يوما فأجاباه فواعد عدة من المغنين فيهم أبو صدقة المدني فقال لأبي صدقة إنك تبرم بكثرة السؤال فصادرني على شيء أدفعه إليك ولا تسأل شيئا غيره فصادره على شيء أعطاه إياه فلما جلسوا وغنوا أعجبوا بغناء أبي صدقة واقترحوا عليه أصواتا من غناء ابن سريج ومعبد وابن محرز وغيرهم فغناهم ثم غنى والصنعة له رمل\n(يا ويح من لعب الهوى بحياته ... فأماته من قبل حين مماته)\n(من ذا كذا كان الشقي بشادن ... هاروت بين لسانه ولهاته)\nذكر الأبيات الأربعة المتقدم ذكرها قال فأجاد وأحسن ما شاء وطرب جعفر فقال له أحسنت وحياتي وكان عليه دواج خز مبطن بسمور جيد فلما قال له ذلك شرهت نفسه وعاد إلى طبعه فقال لو أحسنت ما كان هذا الدواج عليك ولتخلعنه علي فألقاه عليه ثم غنى أصواتا من القديم والحديث وغنى بعدها من صناعته في الرمل\n(لم يطل العهد فتنساني ... ولم أغب عنك فتنعاني)\n(بدلت بي غيري وباهتني ... ولم تكن صاحب بهتان)\n(لا وثقت نفسي بإنسان ... بعدك في سر وإعلان)\n(أعطيتني ما شئت من موثق ... منك ومن عهد وأيمان)","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":9,"spl":"أخبار أبي صدقة"},
{"id":"b253-14","bab":"الجزء 19","sec":"أخبار أبي صدقة","page":"ج19 ص303","text":"قال له الفضل أحسنت وحياتي فقال لو أحسنت لخلعت علي جبة تكون شكلا لهذا الدواح فنزع جبته وخلعها عليه وسكروا وانصرفوا فوثب الحسن بن سليمان فقال له قد وافقتك على ما أرضاك ودفعته إليك على ألا تسأل أحدا شيئا فلم تف وقد أخذت مالك والله لا تركت عليك شيئا مما أخذته ثم انتزعته منه كرها وصرفه فشكاه أبو صدقة إلى الفضل وجعفر فضحكا منه وأخلفا عليه ما ارتجعه الطفيلي منه من خلعهما","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":10,"spl":"أخبار أبي صدقة — أسباب إلحاحه"},
{"id":"b253-15","bab":"الجزء 19","sec":"نسبة ما مضى في هذه الأخبار من الغناء","page":"ج19 ص307","text":"صوت\n(بان الخليط على بزل مخيسة ... هدل المشافر أدنى سيرها الرمل)\n(من كل أعيس نضاح القفا قطم ... ينفي الزمام إذا ما حنت الإبل)\nلغناء لابن عائشة خفيف ثقيل أول بالوسطى عن عمرو والهشامي وقال الهشامي خاصة فيه لابن محرز هزج ولإسحاق ثقيل أول ووافقه ابن المكي وما وجدت لمعبد فيه صنعة في شيء من الروايات إلا في المذكور وأما\n(بان الخليط ولو طووعت ما بانا ... )\nفقد مضى في المائة المختارة ونسب هناك وذكرت أخباره","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":10,"spl":"أخبار أبي صدقة — أسباب إلحاحه","partialRef":{"sid":"b253-13","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b253-16","bab":"الجزء 19","sec":"أسباب إلحاحه","page":"ج19 ص308","text":"أخبرني رضوان بن أحمد قال حدثنا يوسف بن إبراهيم قال حدثني أبو إسحاق إبراهيم بن المهدي قال كان أبو صدقة أسأل خلق الله وألحهم فقال له الرشيد ويلك ما أكثر سؤالك فقال وما يمنعني من ذلك واسمي مسكين وكنيتي أبو صدقة واسم أبني صدقة وكانت أمي تلقب فاقة واسم أبي صدقة فمن أحق مني بهذا وكان الرشيد يعبث به عبثا شديدا فقال ذات يوم لمسرور قل لابن جامع وإبراهيم الموصلي وزبير بن دحمان وزلزل وبرصوصا وابن أبي مريم المديني إذا رأيتموني قد طابت نفسي فليسألني كل واحد منهم حاجة مقدارها مقدار صلته وذكر لكل واحد منهم مقدار ذلك وأمرهم أن يكتموا أمرهم عن أبي صدقة فقال لهم مسرور ما أمره به ثم أذن لأبي صدقة قبل إذنه لهم فلما جلس قال له يا أبا صدقة قد أضجرتني بكثرة مسألتك وأنا في هذا اليوم ضجر وقد أحببت أن أتفرج وأفرح ولست آمن أن تنغص علي مجلسي بمسألتك فإما أن أعفيتني من أن تسألني اليوم حاجة وإلا فانصرف فقال له يا سيدي لست أسألك في هذا اليوم ولا إلى شهر حاجة فقال له الرشيد أما إذ شرطت لي هذا على نفسك فقد اشتريت منك حوائجك بخمسمائة دينار وها هي ذه فخذها هنيئة\nمعجلة فإن سألتني شيئا بعدها في هذا اليوم فلا لوم علي إن لم أصلك سنة بشيء فقال له نعم وسنتين فقال له الرشيد زدني في الوثيقة فقال قد جعلت أمر أم صدقة في يدك فطلقها متى شئت إن شئت واحدة وإن شئت ألفا إن سألتك في يومي هذا حاجة وأشهد الله ومن حضر على ذلك فدفع إليه المال ثم أذن للجلساء والمغنين فحضروا وشرب القوم فلما طابت نفس الرشيد قال له ابن جامع يا أمير المؤمنين قد نلت منك ما لم تبلغه أمنيتي وكثر إحسانك إلي حتى كبت أعدائي وقتلتهم وليست لي بمكة دار تشبه حالي فإن رأى أمير المؤمنين أن يأمر لي بمال أبني به دارا وأفرشها بباقيه لأفقأ عيون أعدائي وأزهق نفوسهم فعل فقال وكم قدرت لذلك قال أربعة آلاف دينار فأمر له بها ثم قام إبراهيم الموصلي فقال له قد ظهرت نعمتك علي وعلى أكابر ولدي وفي أصاغرهم من قد بلغ وأريد تزويجه ومن أصاغرهم من أحتاج إلى أن أطهره ومنهم صغار أحتاج إلى أن أتخذ لهم خدما فإن رأى أمير المؤمنين أن يحسن معونتي على ذلك فعل فأمر له بمثل ما أمر لابن جامع وجعل كل واحد منهم يقول فيقول من الثناء ما يحضره ويسأل حاجة على قدر جائزته وأبو صدقة ينظر إليهم وإلى الأموال تفرق يمينا وشمالا فوثب على رجليه قائما وقال للرشيد يا سيدي أقلني أقال الله عثرتك فقال له الرشيد لا أفعل فجعل يستحلفه ويضطرب ويلح والرشيد يضحك ويقول ما إلى ذلك سبيل الشرط أملك فلما عيل صبره أخذ الدنانير فرمى بها بين يدي الرشيد وقال له هاكها قد رددتها عليك وزدتك فرج أم صدقة فطلقها إن شئت واحدة وإن شئت ألفا وإن لم تلحقني بجوائز القوم فألحقني بجائزة هذا البارد ابن الباردة عمرو الغزال وكانت صلته ألف دينار فضحك الرشيد حتى استلقى ثم رد عليه الخمسمائة الدينار وأمر له بألف دينار معها وكان ذلك أكثر ما أخذه منه مذ يوم خدمه إلى أن مات فانصرف يومئذ بألف وخمسمائة دينار","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":10,"spl":"أخبار أبي صدقة — أسباب إلحاحه"},
{"id":"b253-17","bab":"الجزء 19","sec":"جعفر بن يحي والرشيد يعبثان به","page":"ج19 ص310","text":"أخبرني رضوان بن أحمد قال حدثني يوسف بن إبراهيم قال حدثني أبو إسحاق قال مطرنا ونحن مع الرشيد بالرقة مطرا مع الفجر واتصل إلى غد ذلك اليوم وعرفنا خبر الرشيد وأنه مقيم عند أم ولده المسماة بسحر فتشاغلنا في منازلنا فلما كان من غد جاءنا رسول الرشيد فحضرنا جميعا وأقبل يسأل واحدا واحدا عن يومه الماضي ما صنع فيه فيخبره إلى أن انتهى إلى جعفر بن يحي فسأله عن خبره فقال كان عندي أبو زكار الأعمى وأبو صدقة فكان أبو زكار كلما غنى صوتا لم يفرغ منه حتى يأخذه أبو صدقة فإذا انتهى الدور إليه أعاده وحكى أبا زكار فيه وفي شمائله وحركاته ويفطن أبو زكار لذلك فيجن ويموت غيظا ويشتم أبا صدقة كل شتم حتى يضجر وهو لا يجيبه ولا يدع العبث به وأنا أضحك من ذلك إلى أن توسطنا الشراب وسئمنا من العبث به فقلت له دع هذا وغن غناءك فغنى رملا ذكر أنه من صنعته طربت له والله يا أمير المؤمنين طربا ما أذكر أني طربت مثله منذ حين هو صوت\n(فتنتني بفاحم اللون جعد ... وبثغر كأنه نظم در)\n(وبوجه كأنه طلعة البدر ... وعين في طرفها نفث سحر)\nفقلت له أحسنت والله يا أبا صدقة فلم أسكت عن هذه الكلمة حتى قال لي إني قد بنيت دارا حتى أنفقت عليها حريبتي وما أعددت لها فرشا فافرشها لي نجد الله لك في الجنة ألف قصر فتغافلت عنه وعاود الغناء\nفتعمدت أن قلت له أحسنت ليعاود مسألتي وأتغافل عنه فسألني وتغافلت فقال لي يا سيدي هذا التغافل متى حدث ذلك سألتك بالله وبحق أبيك عليك إلا أجبتني عن كلامي ولو بشتم فأقبلت عليه وقلت له أنت والله بغيض اسكت يا بغيض واكفف عن هذه المسألة الملحة فوثب من بين يدي وظننت أنه خرج لحاجة وإذا هو قد نزع ثيابه وتجرد منها خوفا من أن تبتل ووقف تحت السماء لا يواريه منها شيء والمطر يأخذه ورفع رأسه وقال يا رب أنت تعلم أني مله ولست نائحا وعبدك هذا الذي رفعته وأحوجتني إلى خدمته يقول لي أحسنت لا يقول لي أسأت وأنا منذ جلست أقول له بنيت لم أقل هدمت فيحلف بك جرأة عليك أني بغيض فاحكم بيني وبينه يا سيدي فأنت خير الحاكمين فغلبني الضحك وأمرت به فتنحى وجهدت به أن يغني فامتنع حتى حلفت له بحياتك يا أمير المؤمنين أني أفرش له داره وخدعته فلم أسم له ما أفرشها به فقال الرشيد طيب والله الآن تم لنا به اللهو وهو ذا أدعو به فإذا رآك فسوف يقتضيك الفرش لأنك حلفت له بحياتي فهو ينتجز ذلك بحضرتي ليكون أوثق له فقل له أنا أفرشها لك بالبواري وحاكمه إليه ثم دعا به فأحضر فما استقر في مجلسه حتى قال لجعفر بن يحي الفرش الذي حلفت لي بحياة أمير المؤمنين أنك تفرش به داري تقدم فيه فقال له جعفر اختر إن شئت فرشتها لك بالبواري وإن شئت بالبردي من الحصر فضج واضطرب فقال له الرشيد وكيف كانت القصة فأخبره فقال له أخطأت يا أبا صدقة إذ لم تسم النوع ولا حددت القيمة فإذا فرشها لك بالبواري أو بالبردي أو بما دون ذلك فقد وفى يمينه وإنما خدعك ولم تفطن له أنت ولا توثقت وضيعت حقك فسكت وقال نوفر البردي والبواري عليه أيضا أعزه الله وغنى المغنون حتى انتهى إليه الدور فأخذ يغني غناء الملاحين والبنائين\nوالسقائين وما جرى مجراه من الغناء فقال له الرشيد أيش هذا الغناء ويلك قال من فرشت داره بالبواري والبردي فهذا الغناء كثير منه وكثير أيضا لمن هذه صلته فضحك الرشيد والله وطرب وصفق ثم أمر له بألف دينار من ماله وقال له افرش دارك من هذه فقال وحياتك لا آخذها يا سيدي أو تحكم لي على جعفر بما وعدني وإلا مت والله أسفا لفوات ما حصل في طمعي ووعدت به فحكم له على جعفر بخمسمائة دينار فقبلها جعفر وأمر له بها","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":11,"spl":"جعفر بن يحي والرشيد يعبثان به"},
{"id":"b253-18","bab":"الجزء 19","sec":"سبب وصوله إلى السلطان","page":"ج19 ص312","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال كان سبب وصول أبي صدقة إلى السلطان أن أبي لما حج مر بالمدينة فاحتاج إلى قطع ثياب فالتمس خياطا حاذقا فدل على أبي صدقة ووصف له بالحذق في الخياطة والحذق في الغناء وخفة الروح فأحضره فقطع له ما أراد وخاطه وسمع غناءه فأعجبه وسأله عن حاله فشكا إليه الفقر فخلف لعياله نفقة سابغة لسنة ثم أخذه معه وخلطه بالسلطان قال حماد فقال أبو صدقة يوما لأبي قد اقتصرت بي على صنعة أبي إسحاق أبيك رحمه الله عندي وأنت لا رب ذلك بشيء فقال له هذه الصينية الفضة التي بين يدي لك إذا انصرفت فشكره وسر بذلك ولم يزل يغنيه بقية يومه فلما أخذ النبيذ فيه قام قومه ليبول فدعا أبي بصينية رصاص فحول قنينته وقدحه فيها ورفع الصينية الفضة فلما أراد أبو صدقة الانصراف شد أبي الصينية في منديل ودفعها إلى غلامه وقال له بت الليلة عندي واصطبح غدا واردد دابتك فقال إني إذا لأحمق أدفع إلى غلامي صينية فضة فيأخذها ويطمع فيها أو يبيعها ويركب الدابة ويهرب ولكني أبيت عندك فإذا انصرفت غدا أخذتها معي وبات وأصبح عندنا مصطبحا فلما كان وقت انصرافه أخذها\nومضى فلم يلبث من غد أن جاءنا والصينية معه فإذا هو قد وجه بها لتباع فعرفوه أنها رصاص فلما رآه أبي من بعيد ضحك وعرف القصة وتماسك فقال له أبو صدقة نعم الخلافة خلفت أباك وما أحسن ما فعلت بي قال وأي شيء فعلت بك قال أعطيتني صينية رصاص فقال له أبي سخنت عينك سخرت امرأتك بك وأنا من أين لي صينية رصاص فتشكك ساعة ثم قال أظن والله أن ذلك كذلك فقام فقال له أبي إلى أين قال أضع والله عليها السوط فأضربها به حتى ترد الصينية فلما رأى أبي الجد منه قال له اجلس يا أبا صدقة فإنما مزحت معك وأمر له بوزنها دراهم صوت\n(إن من يملك رقي ... مالك رق الرقاب)\n(لم يكن يا أحسن العالم ... هذا في حسابي)\nلشعر لفضل الشاعرة والغناء لعريب خفيف ثقيل بالوسطى عن ابن المعتز","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":12,"spl":"سبب وصوله إلى السلطان — أخبار فضل الشاعرة"},
{"id":"b253-19","bab":"الجزء 19","sec":"أخبار فضل الشاعرة","page":"ج19 ص314","text":"كانت فضل جارية مولدة من مولدات البصرة وكانت أمها من مولدات اليمامة بها ولدت ونشأت في دار رجل من عبد القيس وباعها بعد أن أدبها وخرجها فاشتريت وأهديت إلى المتوكل وكانت هي تزعم أن الذي باعها أخوها وأن أباها وطىء أمها فولدتها منه فأدبها وخرجها معترفا بها وأن بنيه من غير أمها تواطأوا على بيعها وجحدها ولم تكن تعرف بعد أن أعتقت إلا بفضل العبدية وكانت حسنة الوجه والجسم والقوام أديبة فصيحة سريعة البديهة مطبوعة في قول الشعر ولم يكن في نساء زمانها أشعر منها أخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن أبي طاهر قال كانت فضل الشاعرة لرجل من النخاسين بالكرخ يقال له حسنويه فاشتراها محمد بن الفرج أخو عمر بن الفرج الرخجي وأهداها إلى المتوكل فكانت تجلس للرجال ويأتيها الشعراء فألقى عليها أبو دلف القاسم بن عيسى\n(قالوا عشقت صغيرة فأجبتهم ... أشهى المطي إلي ما لم يركب)\n(كم بين حبة لؤلؤ مثقوبة ... نظمت وحبة لؤلؤ لم تثقب)\nقالت فضل مجيبة له\n(إن المطية لا يلذ ركوبها ... ما لم تذلل بالزمام وتركب)\n(والدر ليس بنافع أصحابه ... حتى يؤلف للنظام بمثقب)","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":12,"spl":"سبب وصوله إلى السلطان — أخبار فضل الشاعرة"},
{"id":"b253-20","bab":"الجزء 19","sec":"شعرها في المتوكل","page":"ج19 ص315","text":"حدثني عمي ومحمد بن خلف قالا حدثنا أبو العيناء قال لما دخلت فضل الشاعرة على المتوكل يوم أهديت إليه قال لها أشاعرة أنت قالت كذا زعم من باعني واشتراني فضحك وقال أنشدينا شيئا من شعرك فأنشدته\n(استقبل الملك إمام الهدى ... عام ثلاث وثلاثينا)\nعني سنة ثلاث وثلاثين ومائتين من سني الهجرة\n(خلافة أفضت إلى جعفر ... وهو ابن سبع بعد عشرينا)\n(إنا لنرجو يا إمام الهدى ... أن تملك الناس ثمانينا)\n(لا قدس الله امرأ لم يقل ... عند دعائي لك آمينا)\nاستحسن الأبيات وأمر لها بخمسة آلاف درهم وأمر عريب فغنت فيها حدثني عمي قال حدثني أبو عبد الله أحمد بن حمدون قال عرضت على المعتمد جارية تباع في خلافة المتوكل وهو يومئذ حديث السن فاشتط مولاها في السوم فلم يشترها وخرج بها إلى ابن الأغلب فبيعت هناك فلما\nولي المعتمد الخلافة سأل عن خبرها وقد ذكرها فأعلم أنها بيعت وأولدها مولاها فقال لفضل الشاعرة قولي فيها شيئا فقالت\n(علم الجمال تركتني ... في الحب أشهر من علم)\n(ونصبتني يا منيتي ... غرض المظنة والتهم)\n(فارقتني بعد الدنو ... فصرت عندي كالحلم)\n(فلو أن نفسي فارقت ... جسمي لفقدك لم تلم)\n(ما كان ضرك لو وصلت ... فخف عن قلبي الألم)\n(برسالة تهدينها ... أو زورة تحت الظلم)\n(أولا فطيفي في المنام ... فلا أقل من اللمم)\n(صلة المحب حبيبه ... الله يعلمه كرم)","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":13,"spl":"شعرها في المتوكل"},
{"id":"b253-21","bab":"الجزء 19","sec":"نماذج من شعرها","page":"ج19 ص316","text":"حدثني محمد بن العباس اليزيدي قال كتب بعض أهلنا إلى فضل الشاعرة\n(أصبحت فردا هائم العقل ... إلى غزال حسن الشكل)\n(أضنى فؤادي طول عهدي به ... وبعده مني ومن وصلي)\n(منية نفسي في هوى فضل ... أن يجمع الله بها شملي)\n(أهواك يا فضل هوى خالصا ... فما لقلبي عنك من شغل)\nال فأجابته\nصوت\n(الصبر ينقص والسقام يزيد ... والدار دانية وأنت بعيد)\n(أشكوك أم أشكو إليك فإنه ... لا يستطيع سواهما المجهود)\n(إني أعوذ بحرمتي بك في الهوى ... من أن يطاع لديك في حسود)\nي هذه الأبيات رمل طنبوري وأظنه لجحظة أخبرني محمد بن خلف بن المرزبان قال حدثني الحسن بن عيسى الكوفي قال حدثنا أبو دهمان وأخبرني أيضا به عبد الله بن نصر المروزي قالا كانت فضل الشاعرة من أحسن الناس وجها وخلقا وخلقا وأرقهم شعرا فكتب إليها بعض من كان يجمعه وإياها مجلس الخليفة ولا تطلعه على حبها له\n(ألا ليت شعري فيك هل تذكرينني ... فذكراك في الدنيا إلي حبيب)\n(وهل لي نصيب في فؤادك ثابت ... كما لك عندي في الفؤاد نصيب)\n(ولست بموصول فأحيا بزورة ... ولا النفس عند اليأس عنك تطيب)\nال فكتبت إليه\n(نعم وإلهي إنني بك صبة ... فهل أنت يا من لا عدمت مثيب)\n(لمن أنت منه في الفؤاد مصور ... وفي العين نصب العين حين تغيب)\n(فثق بوداد أنت مظهر مثله ... على أن بي سقما وأنت طبيب)\nخبرني جعفر بن قدامة قال حدثني يحي بن علي بن يحي المنجم قال حدثني الفضل بن العباس الهاشمي قال حدثتني بنان الشاعرة قالت اتكأ المتوكل على يدي ويد فضل الشاعرة وجعل يمشي بيننا ثم قال أجيزا لي قول الشاعر\n(تعلمت أسباب الرضا خوف عتبها ... وعلمها حبي لها كيف تغضب)\nفقالت له فضل\n(تصد وأدنو بالمودة جاهدا ... وتبعد عني بالوصال وأقرب)\nقلت أنا\n(وعندي لها العتبى على كل حالة ... فما منه لي بد ولا عنه مذهب)\nخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن أبي طاهر قال ألقى بعض أصحابنا على فضل الشاعرة\n(ومستفتح باب البلاء بنظرة ... تزود منها قلبه حسرة الدهر)\nقالت\n(فوالله ما يدري أتدري بما جنت ... على قلبه أو أهلكته وما تدري)\nخبرني محمد بن خلف قال حدثني أحمد بن أبي طاهر قال ألقيت أنا على فضل الشاعرة\n(علم الجمال تركتني ... بهواك أشهر من علم)\nقالت على البديهة\n(وأبحتني يا سيدي ... سقما يجل عن السقم)\n(وتركتني غرضا فديتك ... للعواذل والتهم)\n(صلة المحب حبيبه ... الله يعلمه كرم)\nخبرني محمد بن خلف قال حدثني محمد بن الوليد قال سمعت علي بن الجهم يقول كنت يوما عند فضل الشاعرة فلحظتها لحظة استرابت بها فقالت\n(يارب رام حسن تعرضه ... يرمي ولا يشعر أني غرضه)\nقلت\n(أي فتى لحظك ليس يمرضه ... وأي عقد محكم لا ينقضه)\nضحكت وقالت خذ في غير هذا الحديث حدثني عمي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني إبراهيم بن المدبر قال كتبت فضل الشاعرة إلى سعيد بن حميد أيام كانت بينهما محبة وتواصل\n(وعيشك لو حرحت باسمك في الهوى ... لأ قصرت عن أشياء في الهزل والجد)\n(ولكنني أبدي لهذا مودتي ... وذاك وأخلو فيك بالبث والوجد)\n(مخافة أن يغري بنا قول كاشح ... عدوا فيسعى بالوصال إلى الصد)\nكتب إليها سعيد\n(تنامين عن ليلى وأسهره وحدي ... وأنهى جفوني أن تبثك ما عندي)\n(فإن كنت لا تدرين ما قد فعلته ... بنا فانظري ماذا على قاتل العمد)\nقال عمي هكذا ذكر ابن مهرويه وحدثني به علي بن الحسين بن عبد الأعلى فذكر أن بيتي سعيد كانا الابتداء وأن أبيات فضل كانت الجواب وذكر لهما خبرا في عتاب عاتبها به ولم أحفظه وإنما سمعته يذكره ثم أخرج إلي كتابا بعد ذلك فيه أخبار عن علي ابن الحسين فوجدت هذا الخبر فيه فقرأته عليه قال علي بن الحسين بن عبد الأعلى حضر سعيد بن حميد مجلسا حضرته فضل الشاعرة وبنان وكان سعيد يهواها وتظهر له هوى ويتهمها مع ذلك ببنان فرأى فيها إقبالا شديدا على بنان فغضب وانصرف فكتبت إليه فضل بالأبيات الأول وأجابها بالبيتين الآخرين فاتفقت رواية ابن مهرويه وعلي بن الحسين في هذا الخبر أخبرني محمد بن خلف بن المرزبان قال حدثني أبو يوسف بن الدقاق الضرير قال صرت أنا وأبو منصور الباخرزي إلى منزل فضل الشاعرة فحجبنا عنها وانصرفنا وما علمت بنا ثم بلغها مجيئنا وانصرافنا فكرهت ذلك وغمها فكتبت إلينا تعتذر","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":14,"spl":"نماذج من شعرها"},
{"id":"b253-22","bab":"الجزء 19","sec":"نماذج من شعرها","page":"ج19 ص316","text":"(وما كنت أخشى أن تروا لي زلة ... ولكن أمر الله ما عنه مذهب)\n(أعوذ بحسن الصفح منكم وقبلنا ... بصفح وعفو ما تعوذ مذنب)\nكتب إليها أبو منصور الباخرزي\n(لئن أهديت عتباك لي ولإخوتي ... فمثلك يا فضل الفضائل يعتب)\n(إذا اعتذر الجاني محا العذر ذنبه ... وكل امرئ لا يقبل العذر مذنب)\nدثني علي بن هارون بن علي بن يحي المنجم قال حدثني عمي عن جدي قال\nقال لي المتوكل يوما وفضل واقفة بين يديه يا علي كان بيني وبين فضل موعد فشربت شربا فيه فضل فسكرت ونمت وجاءتني للموعد فحركتني بكل ما ينتبه به النائم من قرص وتحريك وغمز وكلام فلم أنتبه فلما علمت أنه لا حيلة لها في كتبت رقعة ووضعتها على مخدتي فانتبهت فقرأتها فإذا فيها\n(قد بدا شبهك يا مولاي ... يحدو بالظلام)\n(قم بنا نقض لبنات ... التزام والتثام)\n(قبل أن تفضحنا عودة ... أرواح النيام)\nخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن أبي طاهر قال كانت فضل الشاعرة تهاجي خنساء جارية هشام المكفوف وكانت شاعرة وكان أبو شبل عاصم بن وهب يعاون فضلا عليها ويهجوها مع فضل وكان القصيدي والحفصي يعينان خنساء على فضل وأبي شبل فقال أبو شبل على لسان فضل\n(خنساء طيري بجناحين ... أصبحت معشوقة نذلين)\n(من كان يهوى عاشقا واحدا ... فأنت تهوين عشيقين)\n(هذا القصيدي وهذا الفتىالحفصي ... قد زاراك فردين)\n(نعمت من هذا وهذا كما ... ينعم خنزير بحشين)\nقالت خنساء تجيبها\n(ماذا مقال لك يا فضل بل ... مقال خنزيرين فردين)\n(يكنى أبا الشبل ولو أبصرت ... عيناه شبلا راث كرين)\nوقالت فضل في خنساء\n(إن خنساء لا جعلت فداها ... اشتراها الكسار من مولاها)\n(ولها نكهة يقول محاذيها ... أهذا حديثها أم فساها)\nقالت خنساء في فضل وأبي شبل\n(تقول له فضل إذا ما تخوفت ... ركوب قبيح الذل في طلب الوصل)\n(حرام فتى لم يلق في الحب ذلة ... فقلت لها لا بل حرام أبي الشبل)\nقالت خنساء تهجو أبا شبل\n(ما ينقضي فكري وطول تعجبي ... من نعجة تكنى أبا الشبل)\n(لعب الفحول بسفلها وعجانها ... فتمردت كتمرد الفحل)\n(لما اكتنيت بما اكتنيت به ... وتسمت النقصان بالفضل)\n(كادت بنا الدنيا تميد ضحى ... ونرى السماء تذوب كالمهل)\nال فغضب أبو شبل لذلك ولم يجبها وقال يهجو مولاها هشاما\n(نعم مأوى العزاب بيت هشام ... حين يرمي اللثام باغي اللثام)\n(من أراد السرور عند حبيب ... لينال السرور تحت الظلام)\n(فهشام نهاره ودجى الليل ... سواء نفسي فداء هشام)\n(ذاك حر دواته ليس تخلو ... أبدا من تخرق الأقلام)","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":15,"spl":"نماذج من شعرها"},
{"id":"b253-23","bab":"الجزء 19","sec":"فضل وسعيد بن حميد","page":"ج19 ص323","text":"حدثني عمي قال حدثني ميمون بن هارون قال زارت فضل الشاعرة سعيد بن حميد ليلة على موعد سبق بينهما فلما حصلت عنده جاءتها جاريتها مبادرة تعلمها أن رسول الخليفة قد جاء يطلبها فقامت مبادرة فمضت فلما كان من غد كتب إليها سعيد\n(ضن الزمان بها فلما نلتها ... ورد الفراق فكان أقبح وارد)\n(والدمع ينطق للضمير مصدقا ... قول المقر مكذبا للجاحد)\nدثني الحسن بن علي قال حدثنا ابن أبي الدنيا قال حدثني ميسرة ابن محمد قال حدثني عبيد بن محمد قال قلت لفضل الشاعرة للشاعرة ماذا نزل بكم البارحة قال وذلك في صبيحة قتل المنتصر المتوكل فقالت وهي تبكي\n(إن الزمان بذحل كان يطلبنا ... ما كان أغفلنا عنه وأسهانا)\n(ما لي وللدهر قد أصبحت همته ... ما لي وللدهر ما للدهر لا كانا)\nخبرني محمد بن خلف بن المرزبان قال حدثني محمد بن الفضل قال حدثني أبو هفان قال حدثني أحمد بن أبي فنن قال خرجت قبيحة إلى المتوكل يوم نيروز وبيدها كأس بلور بشراب صاف فقال لها ما هذا فديتك قالت هديتي لك في هذا اليوم عرفك الله بركته فأخذه من يدها وإذا على خدها جعفر مكتوبا بالمسك فشرب الكأس وقبل خدها وكانت فضل الشاعرة واقفة على رأسه فقالت\nصوت\n(وكاتبة بالمسك في الخد جعفرا ... بنفسي سواد المسك من حيث أثرا)\n(لئن أثرت بالمسك سطرا بخدها ... لقد أودعت قلبي من الحزن أسطرا)\n(فيا من مناها في السريرة جعفر ... سقى الله من سقيا ثناياك جعفرا)\nلغناء لعريب خفيف رمل قال وأمر عريب فغنت فيه وقالت فضل في ذلك أيضا\n(سلافة كالقمر الباهر ... في قدح كالكوكب الزاهر)\n(يديرها خشف كبدر الدجى ... فوق قضيب أهيف ناضر)\n(على فتى أروع من هاشم ... مثل الحسام المرهف الباتر)\nوقد رويت الأبيات الأول لمحبوبة شاعرة المتوكل ولها أخبار وأشعار كثيرة قد ذكرت بعضها في موضع آخر من هذا الكتاب أخبرني محمد بن خلف قال أخبرني أبو الفضل المروروذي قال كتبت فضل الشاعرة إلى سعيد بن حميد\n(بثثت هواك في بدني وروحي ... فألف فيهما طمعا بياس)\nأجابها سعيد في رقعتها\n(كفانا الله شر اليأس إني ... لبغض اليأس أبغض كل آسي)","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":16,"spl":"فضل وسعيد بن حميد"},
{"id":"b253-24","bab":"الجزء 19","sec":"فضل وبنان","page":"ج19 ص324","text":"حدثني عمي قال حدثني ابن أبي المدور الوراق قال\nكنت عند سعيد بن حميد وكان قد ابتدأ ما بينه وبين فضل الشاعرة يتشعب وقد بلغه ميلها إلى بنان وهو بين المصدق والمكذب بذلك فأقبل على صديق له فقال أصبحت والله من أمر فضل في غرور أخادع نفسي بتكذيب العيان وأمنيها ما قد حيل دونه والله إن إرسالي إليها بعد ما قد لاح من تغيرها لذل وإن عدولي عنها وفي أمرها شبهه لعجز وإن تصبري عنها لمن دواعي التلف ولله در محمد بن أمية حيث يقول\n(يا ليت شعري ما يكون جوابي ... أما الرسول فقد مضى بكتابي)\n(وتعجلت نفسي الظنون وأشعرت ... طمع الحريص وخيفة المرتاب)\n(وتروعني حركات كل محرك ... والباب يقرعه وليس ببابي)\n(كم نحو باب الدار لي من وثبة ... أرجو الرسول بمطمع كذاب)\n(والويل لي من بعد هذا كله ... إن كان ما أخشاه رد جوابي)\nدثني جحظة قال حدثني علي بن يحيى المنجم قال غضب بنان على فضل الشاعرة في أمر أنكره عليها فاعتذرت إليه فلم يقبل معذرتها فأنشدتني لنفسها في ذلك\n(يا فضل صبرا إنها ميتة ... يجرعها الكاذب والصادق)\n(ظن بنان أنني خنته ... روحي إذا من بدني طالق)\nخبرني محمد بن خلف بن المرزبان قال حدثني أبو العباس المروزي قال قال المتوكل لعلي بن الجهم قل بيتا وطالب فضل الشاعرة بأن تجيزه فقال علي أجيزي يا فضل\n(لاذ بها يشتكي إليها ... فلم يجد عندها ملاذا)\nال فأطرقت هنيهة ثم قالت\n(فلم يزل ضارعا إليها ... تهطل أجفانه رذاذا)\n(فعاتبوه فزاد عشقا ... فمات وجدا فكان ماذا)\nطرب المتوكل وقال أحسنت وحياتي يا فضل وأمر لها بمائتي دينار وأمر عريب فغنت في الأبيات قال مؤلف هذا الكتاب أعرف في هذه الأبيات هزجا لا أدري أهو هذا اللحن أم غيره ولم أره في أغاني عريب ولعله شذ عنها صوت\n(أمامة لا أراك الله ... ذل معيشة أبدا)\n(ألا تستصلحين فتى ... وقاك السوء قد فسدا)\n(غلام كان أهلك مرة ... يدعونه ولدا)\nلشعر لعبد الله بن محمد بن سالم الخياط والغناء للرطاب الجدي ثاني ثقيل بالوسطى عن عمرو وفيه ليحيى المكي ثاني ثقيل بالخنصر في مجرى البنصر عن إسحاق وأحمد بن المكي وذكر عبد الله بن موسى بن محمد بن إبراهيم الإمام عن قلم الصالحية\nأنها أخذت اللحن المنسوب إلى الرطاب عن تينة وسألته عن صانعه فأخبرها أنه له","topic":"أخبار سلم الخاسر ونسبه","topicNo":253,"sp":17,"spl":"فضل وبنان"},
{"id":"b254-1","bab":"الجزء 20","sec":"بسم الله الرحمن الرحيم نسب ابن الخياط وأخباره","page":"ج20 ص5","text":"هو عبد الله بن محمد بن سالم بن يونس بن سالم ذكر الزبير بن بكار أنه مولى لقريش وذكر غيره أنه مولى لهذيل وهو شاعر ظريف ماجن خليع هجاء خبيث مخضرم من شعراء الدولة الأموية والعباسية وكان منقطعا إلى آل الزبير بن العوام مداحا لهم وقدم على المهدي مع عبد الله بن مصعب فأوصله إليه وتوصل له إلى أن سمع شعره وأحسن صلته\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني يونس بن عبد الله بن سالم الخياط قال دخل أبي على المهدي فمدحه فأمر له بخمسين ألف درهم فقال يمدحه\n(أخذت بكفي كفه أبتغي الغنى ... ولم أدر أن الجود من كفه يعدي)\n(فلا أنا منه ما أفاد ذوو الغنى ... أفدت وأعداني فأتلفت ما عندي)\nال فبلغ المهدي خبره فأضعف جائزته وأمر بحملها إليه إلى منزله قال الزبير بن بكار سرق ابن الخياط هذا المعنى من ابن هرمة أخبرني الحسن بن علي الخفاف قال حدثنا أحمد بن أبي خيثمة قال حدثني مصعب بن عبد الله قال سمعت أبي يقول لم يبرح هذه الثنية قط أحد يقذف أعراض الناس ويهجوهم قلت مثل من قال الحزين الكناني والحكم بن عكرمة الدؤلي وعبد الله بن يونس الخياط وابنه يونس وأبو الشدائد","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":0,"spl":"بسم الله الرحمن الرحيم نسب ابن الخياط وأخباره"},
{"id":"b254-2","bab":"الجزء 20","sec":"عقوق ابنه يونس","page":"ج20 ص6","text":"أخبرني محمد بن مزيد قال حدثنا الزبير بن بكار قال\nكان يونس بن الخياط عاقا لأبيه فقال أبوه فيه\n(يونس قلبي عليك يلتهف ... والعين عبرى دموعها تكف)\n(تلحفني كسوة العقوق فلا ... برحت منها ما عشت تلتحف)\n(أمرت بالخفض للجناح وبالرفق ... فأمسى يعوقك الأنف)\n(وتلك والله من زبانية ... إن سلطوا في عذابهم عنفوا)\nأجابه ابنه يونس فقال\n(أصبح شيخي يزري به الخرف ... ما إن له حرمة ولا نصف)\n(صفاتنا في العقوق واحدة ... ما خلتنا في العقوق نختلف)\n(لحفته سالفا أباك فقد ... أصبحت مني كذاك تلتحف)\nخبرني محمد بن خلف وكيع قال حدثني طلحة بن عبد الله قال حدثني أحمد بن إبراهيم بن إسماعيل بن داود قال مر ابن الخياط بدار رجل كان يعرفه قبل ذلك بالضعة وخساسة الحال وقد شيد بابها وطرمح بناءها فقال\n(أطله فما طول البناء بنافع ... إذا كان فرع الوالدين قصيرا)\nخبرني وكيع قال أخبرني إبراهيم بن إسحاق بن إبراهيم بن صالح قال أخبرني العامري قال\nهجا ابن الخياط موسى بن طلحة بن بلال التيمي فقال\n(عجب الناس للعجيب المحال ... حاض موسى بن طلحة بن بلال)\n(زعموه يحيض في كل شهر ... ويرى صفرة لكل هلال)\nال فلقيه موسى فقال يا هذا وأي شيء عليك نعم حضت وحملت وولدت وأرضعت فقال له ابن الخياط أنشدك الله ألا يسمع هذا منك أحد فيجترئ على شعري الناس فلا يكون شيئا ولن يبلغك عني ما تكره بعد هذا فتكافا أخبرني الحرمي قال حدثني الزبير قال حدثني مصعب بن عثمان قال ما رأيت بريق صلع الأشراف في سوق الرقيق أكثر منها يوم رحب القتيلية جارية إبراهيم بن أبي قتيلة وكان يعشقها وبيعت في دين عليه فبلغت خمسمائة دينار فقال المغيرة بن عبد الله لابن أبي قتيلة ويحك اعتقها فتقوم عليك فتتزوجها ففعل فرفع ذلك إلى أبي عمران وهو القاضي يومئذ فقال أخطأ الذي أشار عليه في الحكومة أما نحن في الحكومة فقد عرفنا أن قد بلغت خمسمائة دينار فاذهبوا فقوموها فإن بلغت القيمة أكثر من هذا ألزمناه وإلا فخذوا منه خمسمائة دينار فاستحسن هذا الرأي وليس عليه الناس قبلنا فقال ابن الخياط يذكر ذلك من أمر ابن أبي قتيلةوما كان من أمر جاريته\n(يا معشر العشاق من لم يكن ... مثل القتيلي فلا يعشق)\n(لما رأى السوام قد أحدقوا ... وصيح في المغرب والمشرق)\n(واجتمع الناس على درة ... نظيرها في الخلق لم يخلق)\n(وأبدت الأموال أعناقها ... وطاحت العسرة للمملق)\n(قلب فيه الرأي في نفسه ... يدير ما يأتي وما يتقي)\n(أعتقها والنفس في شدقها ... للمعتق المن على المعتق)\n(وقال للحاكم في أمرها ... إن افترقنا فمتى نلتقي)\nأخبرني بهذا الخبر وكيع قال قال الزبير بن بكار وذكر مثل ما ذكره الحرمي وزاد فيه فكان فيهم يعني فيمن حضر لابتياعها موسى بن جعفر بن محمد ومحمد بن زيد بن علي والقاسم بن إسحاق بن عبد الله بن جعفر وغيرهم قال فرأيتهم قياما في الشمس يتزايدون فيها وقال في خبره ابن أبي قتيلة بالتاء أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني يونس بن عبد الله بن سالم الخياط قال كنت ذات عشية في مسجد رسول الله وقت العصر في أيام الحاج فإذا أنا برجل جميل عليه مقطعات خز وإذا معه جماعة فوقف إلى جنبي فصلى ركعتين ثم أقبل علي وكان ذلك من أسباب الرزق فقال يا فتى أتعرف عبد الله بن سالم الخياط فقلت نعم فلما صلينا قال امض بنا إليه فمضيت به فاستخرجت له أبي من منزله فقال الرجل بلغني أنك قلت شعرا في أمر العصبية فقال له أبي ومن أنت بأبي أنت وأمي فقال أنا خزيم بن أبي الهيذام فقال له أبي نعم قد قلته وأنشده\n(اسقياني من صرف هذي المدام ... ودعاني وأقصرا من ملامي)\n(واشربا حيث شئتما إن قيسا ... قد علا عزها فروع الأنام)\n(ليس والله بالشآم يمان ... فيه روح ولابغير الشآم)\n(يطعم النوم حين تكتحل الأعين ... بالنوم عند وقت المنام)\n(حذرا من سيوف ضرغامة عاد ... على الهول باسل مقدام)\n(من بني مرة الأطايب يكنى ... عند دسر الرماح بالهيذام)","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":1,"spl":"عقوق ابنه يونس"},
{"id":"b254-3","bab":"الجزء 20","sec":"يونس ينافس أباه على جائزة","page":"ج20 ص10","text":"قال فأشرع الفتى يده إليه بشيء وجزاه خيرا قال يونس فبادرت فأخذت بيد المري وقلت له لا تعجل فإني قد قلت شعرا أجود من شعره قال أبي ويلك يا يونس يا عاض بظر أمه تحرمني فقلت دع هذا عنك فوالله لا تجوع امرأتي وتشبع امرأتك فقلت ليونس ومن كانت امرأة أبيك يومئذ فقال أمي وجمعت والله عقوقهما فقال لي المري أنشد فأنشدته\n(اسقياني يا صاحبي اسقياني ... ودعاني من الملام دعاني)\n(اسقياني هديتما من كميت ... بنت عشر مشمولة اسقياني)\n(فض عنها ختامها إذ سباها ... واضح الخد من بني عدنان)\n(نتحايا بالكأس أربعة في الدور ... هذان ناعمان وذان)\n(ذا لهذا ريحانة مثل هذاك ... لهذا من طيب الريحان)\n(فنهضنا لموعد كان منا ... إذ سمعنا تجاوب البكمان)\n(فنعمنا حولين بهرا وعشنا ... بين دف ومسمع ودنان)\n(ثم هجنا للحرب إذ شبت الحرب ... ففرزنا فيها بسبق الرهان)\n(إن قيسا في كل شرق وغرب ... خارج سهمها على السهمان)\n(منع الله ضيمنا بأبي الهيذام ... حلف السماح والإحسان)\n(واليمانون يفخرون أما يدرون ... أن النبي غير يمان)\nال فقال الفتى لأبي قد وجب علينا من حقه مثل ما وجب علينا من معك يا شيخ واستظرف ما جرى بيني وبين أبي وقسم الدنانير بيننا وكانت خمسين دينارا أخبرني الحسن بن علي قال حدثنا محمد بن موسى بن حماد قال حدثني الزبير قال مر رجل بيونس بن عبد الله بن الخياط وهو يعصر حلق أبيه وكان عاقا به فقال له ويلك أتفعل هذا بأبيك وخلصه من يده ثم أقبل على الأب يعزيه ويسكن منه فقال له الأب يا أخي لا تلمه واعلم أنه ابني حقا والله لقد خنقت أبي في هذا الموضع الذي خنقني فيه فانصرف عنه الرجل وهو يضحك","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":2,"spl":"يونس ينافس أباه على جائزة — يشكو حاله إلى محمد بن سعيد"},
{"id":"b254-4","bab":"الجزء 20","sec":"يشكو حاله إلى محمد بن سعيد","page":"ج20 ص11","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد بن سليمان النوفلي عن عمه عيسى قال شكا عبد الله بن يونس الخياط إلى محمد بن سعيد بن المغيرة بن\nنوفل بن الحارث بن عبد المطلب حاله وضيقا قد ناله فأمر له بدنانير وكسوة وتمر فقال يمدحه\n(يا بن سعيد يا عقيد الندى ... يا بارع الفضل على المفضل)\n(حللت في الذروة من هاشم ... وفي يفاع من بني نوفل)\n(فطاب في الفرعين هذا وذا ... ما اعتم من منصبك الأطول)\n(قد قلت للدهر وقد نالني ... بالناب والمخلب والكلكل)\n(قد عذت من ضرك مستعصما ... بهاشمي ماجد نوفلي)\n(فقال لي أهلا وسهلا معا ... فزت ولم يمنع ولم يبخل)\n(الدهر شقان فيتق له ... لين وشق خشن المنزل)\n(وأخشن الشقين عني نفى ... وشقه الألين ما عاش لي)\n(فقال لهذا الدهر ما عاش لا ... تبق ولا ترع ولا تأتلي)\nخبرني محمد بن مزيد قال حدثنا الزبير بن بكار قال أخذ أبي لما ولي الحجاز عبد الله بن يونس الخياط بأن يصلي الصلوات الخمس مع الجماعة في مسجد رسول الله فجاءني هو ومحمد بن الضحاك وجعفر بن الحسين اللهبي فوقف بين يدي ثم أنشدني\n(قل للأمير يا كريم الجنس ... يا خير من بالغور أو بالجلس)\n(وعدتي لولدي ونفسي ... شغلتني بالصلوات الخمس)\nفقلت له ويلك أتريد أن أستعفيه لك من الصلاة والله ما يعفيك وإن ذلك ليبعثه على اللجاج في أمرك ثم يضرك عنده فمضى وقال نصبر إذن حتى يفرج الله تعالى أخبرني محمد قال حدثنا الزبير بن بكار قال حدثنا يونس بن الخياط قال كان لأبي صديق وكان يدعوه ليشرب معه فإذا سكر خلع عليه قميصه فإذا صحا من غد بعث إليه فأخذه منه فقال أبي فيه\n(كساني قميصا مرتين إذا انتشى ... وينزعه مني إذا كان صاحيا)\n(فلي فرحة في سكره بقميصه ... وروعاته في الصحو حصت شواتيا)\n(فيا ليت حظي من سروري وروعتي ... تكون كفافا لا علي ولا ليا)","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":2,"spl":"يونس ينافس أباه على جائزة — يشكو حاله إلى محمد بن سعيد"},
{"id":"b254-5","bab":"الجزء 20","sec":"العقوق المتبادل","page":"ج20 ص13","text":"أخبرنا وكيع قال حدثنا محمد بن الحسن بن مسعود الزرقي قال قال يونس بن عبد الله الخياط لأبيه وكان عاقا به\n(مازال بي مازال بي ... طعن أبي في النسب)\n(حتى تريبت وحتى ... ساء ظني بأبي)\nال ونشأ ليونس ابن يقال له دحيم فكان أعق الناس به فقال يونس فيه\n(جلا دحيم عماية الريب ... والشك مني والطعن في النسب)\n(ما زال بي الظن والتشكك حتى ... عقني مثل ما عققت أبي)\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني يونس بن الخياط قال أنشدت سعيد بن عمرو الزبيري\n(لو فاح ريح حبيبة من حبها ... فاحت رياح حبيبتي من ريحي)\nال فقال لي سعيد بن عمرو والله إني لأقول النسيب فلا أقدر على مثل هذا فقلت له ومن أين تقدر على مثل هذا يا أبا عثمان لا تقدر والله على مثله حتى يسوء الثناء عليك أخبرني الحرمي قال حدثنا الزبير قال حدثني يونس بن الخياط قال لما أعطي المهدي المغيرة بن حبيب ألف فريضة يضعها حيث شاء جاءه أبي عبد الله بن سالم وقال له\n(ألف تدور على يد لممدح ... ما سوق مادحه لديه بكاسد)\n(الظن مني لو فرضت لواحد ... في الأعجمين خصصتني بالواحد)\nقال فقال له المغيرة أيهما أحب إليك أأفرض لك أم لابنك يونس فقال له أنا شيخ كبير هامة اليوم أو غد افرض لابني يونس ففرض لي في خمسين دينارا فلما خرجت الأعطية الثلاثة في زمن الرشيد على يدي بكار بن عبد الله قال لي خليفته وخليفة أيوب بن أبي سمير وهما يعرضان أهل ديوان العطاء أنت من هذيل ونراك قد صرت من آل الزبير فنردك إلى فرائض هذيل خمسة عشر دينارا فقال لهما بكار إنما جعلتما لتتبعا ولا\nتبتدعا أمضياه فأعطياني مائة وخمسين دينارا أخبرني محمد بن خلف وكيع قال حدثني محمد بن الحسن بن مسعود الزرقي قال حدثنا ابن أبي قباحة الزهري قال لما عزل ابن عمران وهو عبد الله بن محمد بن عمران التيمي عن القضاء واستعمل هشام بن عبد الله بن عكرمة المخزومي جزع ابن عمران من ذلك فقال بعض أصحابه ليونس بن عبد الله الخياط اهج هشاما بما يغض منه فقال\n(كم تغنى لي هشام ... ذلك الجلف الطويل)\n(بعد وهن وهو في المجلس ... سكران يميل)\n(هل إلى نار بسلع ... آخر الدهر سبيل)\n(قلت للندمان لما ... دارت الراح الشمول)\n(بأبي مال هشام ... فكما مال فميلوا)\nال وشهرها في الناس وبلغ ذلك هشاما فقال لعنه الله إن كان لكاذبا فقال ابن أبي قباحة فقلت لابن الخياط كذبت أما والله إنه لأمر من ذلك أخبرنا وكيع قال حدثنا محمد بن الحسن بن مسعود قال قال يونس بن عبد الله بن الخياط\nجئت يوما إلى أبي وهو جالس وعنده أصحاب له فوقفت عليهم لأغيظه وقلت ألا أنشدكم شعرا قلته بالأمس قالوا بلى فأنشدتهم\n(يا سائلي من أنا أو من يناسبني ... أنا الذي ما له أصل ولا نسب)\n(الكلب يختال فخرا حين يبصرني ... والكلب أكرم مني حين ينتسب)\n(لو قال لي الناس طرا أنت ألأمنا ... ما وهم الناس في ذاكم ولا كذبوا)\nال فوثب إلي ليضربني وعدوت من بين يديه فجعل يشتمني وأصحابه يضحكون","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":3,"spl":"العقوق المتبادل"},
{"id":"b254-6","bab":"الجزء 20","sec":"عبد الله بن الخياط يجلد الحد","page":"ج20 ص16","text":"أخبرني وكيع قال حدثنا محمد بن الحسن بن مسعود أن مالك بن أنس جلد يونس بن عبد الله بن سالم الخياط حدا في الشراب قال وولي ابن سعيد القضاء بالمدينة فقال يونس فيه\n(بكتني الناس لأن ... جلدت وسط الرحبه)\n(وأنني أزني وقد ... غنيت في المجتسبه)\n(أعزف فيهم بعصا ... مالك المقتضبه)\n(فقلت لما أكثروا ... علي فيم الجلبه)\n(ذا ابن سعيد قد قضى ... وحالنا مقتربه)\n(لا بل له التفضيل فيما ... لم أنل والغلبه)\n(بحسن صوت مطرب ... وزوجة مغتصبه)\nخبرني الحرمي ابن أبي العلاء ووكيع قال الحرمي قال الزبير وقال وكيع قال الزبير بن بكار أرسل إلي ابن الخياط يقول إني عليل منذ كذا وكذا ومنزلي على طريقك إذا صدرت إلى الثنية وأنا أحب أن أجدد بك عهدا قال فجعلته على طريقي فوجدته على فرش مضربة وحوله وسائد وهو مسجى فكشف ابنه الثوب عن وجهه وقال له فديتك هذا أبو عبد الله فقال له أجلسني فأجلسه وأسنده إلى صدره فجعل يقول بنفس منقطع بأبي أنت وأمي أموت منذ بضع عشرة ليلة ما دخل علي قرشي غيرك وغير الزبير بن هشام وإبراهيم بن المنذر ومحمد بن عبد الله البكري ولا والله ما أعلم أحدا أحب قريشا كحبي قال زبير وذكر رجلا كان بيني وبينه خلاف فقال لو كنت شابا لفعلت بأمه كذا وكذا لا يكنى ثم قال\n(والله لو عادت بني مصعب ... حليلتي قلت لها بيني)\n(أو ولدي عن حبسهم قصروا ... ضغطتهم بالرغم والهون)\n(أو نظرت عيني خلافا لهم ... فقأتها عمدا بسكين)\nم أقبل على ابنه فقال يا بني أقول لك في أبي عبد الله ما قال ابن\nهرمه لابنه في الحسن بن زيد\n(الله جارعتي دعوة شفقا ... من الزمان وشر الأقرب الوالي)\n(من كل أحيد عنه لا يقربه ... وسط النجي ولا في المجلس الخالي)\nال الزبير حدثني محمد بن عبد الله البكري أنه دخل إليه بعدي في اليوم الذي مات فيه قال فقال لي يا أبا عبد الله أنا أجود بنفسي منذ كذا وكذا ولا تخرج ما هكذا كانت نفس عبيد ولا لبيد ولا الحطيئة ما هي إلا نفس كلب قال فخرجت فما أبعدت حتى سمعت الواعية عليه صوت\n(بأبي مالك عني ... مائل الطرف كليلا)\n(وأرى برك نزرا ... وتحفيك قليلا)\n(وتسميني عدوا ... وأسميك خليلا)\n(أتعلمت سلوا ... أم تبدلت بديلا)\n(أحمد الله فما أغنى ... الرجا فيك فتيلا)\nلشعر لعلي بن جبلة والغناء لزرزور غلام المارقي خفيف رمل\nبالبنصر من روايتي الهشامي وعبد الله بن موسى وفيه لعريب هزج وفيه ثقيل أول من جيد الغناء ينسب إليها وإلى علويه وهو بغنائها أشبه منه بغناء علويه","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":4,"spl":"عبد الله بن الخياط يجلد الحد"},
{"id":"b254-7","bab":"الجزء 20","sec":"أخبار علي بن جبلة","page":"ج20 ص20","text":"هو علي بن جبلة بن عبد الله الأبناوي ويكنى أبا الحسن ويلقب بالعكوك من أبناء الشيعة الخراسانية من أهل بغداد وبها نشأ وولد بالحربية من الجانب الغربي وكان ضريرا فذكر عطاء الملط أنه كان أكمه وهو الذي يولد ضريرا وزعم أهله أنه عمي بعد أن نشأ وهو شاعر مطبوع عذب اللفظ جزله لطيف المعاني مداح حسن التصرف واستنفد شعره في مدح أبي دلف القاسم بن عيسى العجلي وأبي غانم حميد بن عبد الحميد الطوسي وزاد في تفضيلهما وتفضيل أبي دلف خاصة فضل من أجله ربيعة على مضر وجاوز الحد في ذلك\nفيقال إن المامون طلبه حتى ظفر به فسل لسانه من قفاه ويقال بل هرب ولم يزل متواريا منه حتى مت ولم يقدر عليه وهذا هو الصحيح من القولين والآخر شاذ أخبرني أحمد بن عبيد الله بن عمار الثقفي قال حدثني الحسين بن عبد الله بن جبلة بن علي بن جبلة قال كان لجدي أولاد وكان علي أصغرهم وكان الشيخ يرق عليه فجدر فذهبت إحدى عينيه في الجدري ثم نشأ فأسلم في الكتاب فحذق بعض ما يحذقه الصبيان فحمل على دابة ونثر عليه اللوز فوقعت على عينيه الصحيحة لوزة فذهبت فقال الشيخ لولده أنتم لكم أرزاق من السلطان فإن أعنتموني على هذا الصبي وإلا صرفت بعض أرزاقكم إليه فقلنا وما تريد قال تختلفون به إلى مجالس الذب قال فكنا نأتي به مجالس العلم ونتشاغل نحن بما يلعب به الصبيان فما أتى عليه الحول حتى برع وحتى كان العالم إذا رآه قال لمن حوله أوسعوا للبغوي وكان ذكيا مطبوعا فقال الشعر وبلغه أن الناس يقصدون أبا دلف لجوده وما كان يعطي الشعراء فقصده وكان يسمى العكوك فامتدحه بقصيدته التي أولها\n(ذاد ورد الغي عن صدره ... وارعوى واللهو من وطره)\nقول فيها في مدحه\n(يا دواء الأرض إن فسدت ... ومديل اليسر من عسره)\n(كل من في الأرض من عرب ... بين باديه إلى حضره)\n(مستعير منك مكرمة ... يكتسيها يوم مفتخره)\n(إنما الدنيا أبو دلف ... بين مبداه ومحتضره)\n(فإذا ولى أبو دلف ... ولت الدنيا على أثره)","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":5,"spl":"أخبار علي بن جبلة"},
{"id":"b254-8","bab":"الجزء 20","sec":"امتحنوه فقال قصيدة في وصف الفرس","page":"ج20 ص22","text":"فلما وصل إلى أبي دلف وعنده من الشعراء وهم لا يعرفونه استرابوه بها فقال له قائده إنهم قد اتهموك وظنوا أن الشعر لغيرك فقال أيها الأمير إن المحنة تزيل هذا قال صدقت فامتحنوه فقالوا له صف فرس الأمير وقد أجلناك ثلاثا قال فاجعلوا معي رجلا تثقون به يكتب ما أقول فجعلوا معه رجلا فقال هذه القصيدة في ليلته وهي\n(ريعت لمنشور على مفرقه ... ذم لها عهد الصبا حين انتسب)\n(أهداب شيب جدد في رأسه ... مكروهة الجدة أنضاء العقب)\n(أشرقن في أسود أزراين به ... كان دجاه لهوى البيض سبب)\n(واعتقن أيام الغواني والصبا ... عن ميت مطلبه حي الأدب)\n(لم يزدجر مرعويا حين ارعوى ... لكن يد لم تتصل بمطلب)\n(لم أر كالشيب وقارا يجتوى ... وكالشباب الغض ظلا يستلب)\n(فنازل لم يبتهج بقربه ... وذاهب أبقى جوى حين ذهب)\n(كان الشباب لمة أزهى بها ... وصاحبا حرا عزيز المصطحب)\n(إذ أنا أجري سادرا في غيه ... لا أعتب الدهر إذا الدهر عتب)\n(أبعد شأو اللهو في إجرائه ... وأقصد الخود وراء المحتجب)\n(وأذعر الربرب عن أطفاله ... بأعوجي دلفي المنتسب)\n(تحسبه من مرح العز به ... مستنفرا بروعة أو ملتهب)\n(مرتهج يرتج من أقطاره ... كالماء جالت فيه ريح فاضطرب)\n(تحسبه أقعد في استقباله ... حتى إذا استدبرته قلت أكب)\n(وهو على إرهاقه وطيه ... يقصر عنه المحزمان واللبب)\n(تقول فيه حنب إذا انثنى ... وهو كمتن القدح ما فيه حنب)\n(يخطو على عوج تناهبن الثرى ... لم يتواكل عن شظى ولا عصب)\n(تحسبها ناتئة إذا خطت ... كأنها واطئة على الركب)\n(شتا وقاظ برهتيه عندنا ... لم يؤت من بر به ولا حدب)\n(يصان عصرى حره وقره ... وتقصر الخور عليه بالحلب)\n(حتى إذا تمت له أعضاؤه ... لم تنحبس واحدة على عتب)\n(رمنا به الصيد فرادينا به ... أوابد الوحش فأجدى واكتسب)\n(مجذم الجري يباري ظله ... ويعرق الأحقب في شوط الخبب)\n(إذا تظنينا به صدقنا ... وإن تظنى فوته العير كذب)\n(لا يبلغ الجهد به راكبه ... ويبلغ الريح به حيث طلب)\n( لا يبلغ الجهد به ركبه ... ويبلغ الريح به حيث طلب ثم انقضى ذاك كأن لم يعنه ... وكل بقيا فإلى يوم عطب وخلف الدهر على أبنائه ... بالقدح فيهم وارتجاع ما وهب فحمل الدهر ابن عيسى قاسما ... ينهض به أبلج فراج الكرب كرونق السيف انبلاجا بالندى ... وكغراريه على أهل الريب ما وسنت عين رأت طلعته ... فاستيقظت بنوبة من النوب لولا ابن عيسى القرم كنا هملا ... لم يؤتثل مجد ولم يرع حسب ولم يقم في يوم بأس وندى ... ولا تلاقى سبب إلى سبب تكاد تبدي الأرض ما تضمره ... إذا تداعت خيله هلا وهب ويستهل أملا وخيفة ... جانبها إذا استهل أو قطب وهو وإن كان ابن فرعي وائل ... فبسماعيه يوافي في الحسب وبعلاه وعلا آبائه ... تحوى غداة السبق أخطار القصب\n(يا زهرة الدنيا ويا باب الندى ... ويا مجير الرعب من يوم الرهب)\n(لولاك ما كان سدى ولا ندى ... ولا قريش عرفت ولا العرب)\n(خذها إليك من مليء بالثنا ... لكنه غير مليء بالنشب)\n(فاثو في الأرض أو استفزز بها ... أنت عليها الرأس والناس الذنب)\nال فلما غدا عليه بالقصيدة وأنشده إياها استحسنها من حضر وقالوا نشهد أن قائل هذه قائل تلك فأعطاه ثلاثين ألف درهم وقد قيل إن أبا دلف أعطاه مائة ألف درهم ولكن أراها في دفعات لأنه قصده مرارا كثيرة ومدحه بعدة قصائد","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":6,"spl":"امتحنوه فقال قصيدة في وصف الفرس"},
{"id":"b254-9","bab":"الجزء 20","sec":"قصيدته في أبي دلف","page":"ج20 ص25","text":"أخبرني الحسن بن علي الخفاف قال حدثني محمد بن موسى بن حماد قال حدثني أحمد بن أبي فنن قال قال عبد الله بن مالك قال المأمون يوما لبعض جلسائه أقسم على من حضر ممن يحفظ قصيدة علي بن جبلة الأعمى في القاسم بن عيسى إلا أنشدنيها فقال له بعض الجلساء قد أقسم أمير المؤمنين ولا بد من إبرار قسمه وما أحفظها ولكنها مكتوبة عندي قال قم فجئني بها فمضى وأتاه بها فأنشده إياها وهي\n(ذاد ورد الغي عن صدره ... وارعوى واللهو من وطره)\n(وأبت إلا البكاء له ... ضحكات الشيب في شعره)\n(ندمي أن الشباب مضى ... لم أبلغه مدى أشره)\n(وانقضت أيامه سلما ... لم أجد حولا على غيره)\n(حسرت عني بشاشته ... وذوى المحمود من ثمره)\n(ودم أهدرت من رشاء ... لم يرد عقلا على هدره)\n(فأتت دون الصبا هنة ... فليت فوقي على وتره)\n(جارتا ليس الشباب لمن ... راح محنيا على كبره)\n(ذهبت أشياء كنت لها ... صارها حلمي إلى صوره)\n(دع جدا قحطان أو مضر ... في يمانيه وفي مضره)\n(وامتدح من وائل رجلا ... عصر الآفاق في عصره)\n(المنايا في مناقبه ... والعطايا في ذرا حجره)\n(ملك تندى أنامله ... كانبلاج النوء من مطره)\n(مستهل عن مواهبه ... كابتسام الروض عن زهره)\n(جبل عزت مناكبه ... أمنت عدنان في ثغره)\n(إنما الدنيا أبو دلف ... بين مبداه و محتضره)\n(فإذا ولى أبو دلف ... ولت الدنيا على أثره)\n(لست أدري ما أقول له ... غير أن الأرض في خفره)\n(يا دواء الأرض إن فسدت ... ومديل اليسر من عسره)\n(كل من في الأرض من عرب ... بين باديه إلى حضره)\n(مستعير منك مكرمة ... يكتسيها يوم مفتخره)\nقول فيها\n(وزحوف في صواهله ... كصياح الحشر في أثره)\n(قدته والموت مكتمن ... في مذاكيه ومشتجره)\n(فرمت جيلويه منه يد ... طوت المنشور من نظره)\n(زرته والخيل عابسة ... تحمل البؤس على عقره)\n(خارجات تحت رايتها ... كخروج الطير من وكره)\n(وعلى النعمان عجت به ... عوجة ذادته عن صدره)\n(غمط النعمان صفوتها ... فرددت الصفو في كدره)\n(ولقرقور أدرت رحا ... لم تكن ترتد في فكره)\n(قد تأنيت البقاء له ... فأبى المحتوم من قدره)\n(وطغى حتى رفعت له ... خطة شنعاء من ذكره)\nال فغضب المأمون واغتاظ وقال لست لأبي إن لم أقطع لسانه أو أسفك دمه قال ابن أبي فنن وهذه القصيدة قالها علي بن جبلة وقصد بها أبا دلف بعد قتله الصعلوك المعروف بقرقور وكان من أشد الناس بأسا وأعظمهم\nفكان يقطع هو وغلمانه على القوافل وعلى القرى وأبو دلف يجتهد في أمره فلا يقدر عليه فبينا أبو دلف خرج ذات يوم يتصيد وقد أمعن في طلب الصيد وحده إذا بقرقور قد طلع عليه وهو راكب فرسا يشق الأرض بجريه فأيقن أبو دلف بالهلاك وخاف أن يولي عنه فيهلك فحمل عليه وصاح يا فتيان يمنة يمنة يوهمه أن معه خيلا قد كمنها له فخافه قرقور وعطف على يساره هاربا ولحقه أبو دلف فوضع رمحه بين كتفيه فأخرجه من صدره ونزل فاحتز رأسه وحمله على رمحه حتى أدخله الكرج قال فحدثني من رأى رمح قرقور وقد أدخل بين يديه يحمله أربعة نفر فلما أنشده علي بن جبلة هذه القصيدة استحسنها وسر بها وأمر له بمائة ألف درهم أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد الأزدي\nقال أخبرني إبراهيم بن خلف قال بينا أبو دلف يسير مع أخيه معقل وهما إذ ذاك بالعراق إذ مرا بأمرأتين تتماشيان فقالت إحداهما لصاحبتها هذا أبو دلف قالت ومن أبو دلف قالت الذي يقول فيه الشاعر\n(إنما الدنيا أبو دلف ... بين باديه ومحتضره)\n(فإذا ولى أبو دلف ... ولت الدنيا على أثره)\nال فاستعبر أبو دلف حتى جرى دمعه قال له معقل مالك يا أخي تبكي قال لأني لم أقض حق علي بن جبلة قال أو لم تعطه مائة ألف درهم لهذه القصيدة قال والله يا أخي ما في قلبي حسرة تقارب حسرتي على أني لم أكن أعطيته مائة ألف دينار والله لو فعلت ذلك لما كنت قاضيا حقه حدثني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني عبد الله بن محمد بن جرير قال أنشدت أبا تمام قصيدة علي بن جبلة البائية فلما بلغت إلى قوله\n(ورد البيض والبيض ... إلى الأغماد والحجب)\nهتز أبو تمام من فرقه إلى قدمه ثم قال أحسن والله لوددت أن لي هذا البيت بثلاث قصائد من شعري يتخيرها وينتخبها مكانه أخبرني عمي قال حدثني أحمد بن أبي طاهر قال حدثني أبو نزار","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":7,"spl":"قصيدته في أبي دلف"},
{"id":"b254-10","bab":"الجزء 20","sec":"قصيدته في أبي دلف","page":"ج20 ص25","text":"الضبي الشاعر قال قال لي علي بن جبلة قلت لحميد بن عبد الحميد الطوسي يا أبا غانم إني قد مدحت أمير المؤمنين بمدح لا يحسن مثله أحد من أهل الأرض فاذكرني له قال فأنشدني فأنشدته قال أشهد أنك صادق ما يحسن أحد أن يقول هكذا وأخذ المديح فأدخله إلى المأمون فقال له يا حميد الجواب في هذا واضح إن شاء عفونا عنه وجعلنا ذلك ثوابا لمديحه وإن شاء جمعنا بين شعره فيك وفي أبي دلف وبين شعره فينا فإن كان الذي قاله فيكما أجود ضربنا ظهره وأطلنا حبسه وإن كان الذي قاله فينا أجود أعطيناه لكل بيت ألف درهم وإن شاء أقلناه فقلت له يا سيدي ومن أنا ومن أبو دلف حتى يمدحنا بأجود من مديحك فقال ليس هذا الكلام من الجواب في شيء فاعرض ما قلت لك على الرجل فقال أفعل قال علي بن جبلة فقال لي حميد ما ترى فقلت الإقالة أحب إلي فأخبر المأمون بذلك فقال هو أعلم ثم قال لي حميد يا أبا الحسن أي شيء يعني من مدائحك لي ولأبي دلف فقلت قولي فيك\n(لولا حميد لم يكن ... حسب يعد ولا نسب)\n(يا واحد العرب الذي ... عزت بعزته العرب)\nقولي في أبي دلف\n(إنما الدنيا أبو دلف ... بين بادية ومحتضره)\n(فإذا ولى أبو دلف ... ولت الدنيا على أثره)\nال فأطرق حميد ثم قال لقد انتقد عليك أمير المؤمنين فأجاد وأمر لي بعشرة الآف درهم وخلعة وفرس وخادم وبلغ ذلك أبا دلف فأضعف لي العطية وكان ذلك في ستر منهما ما علم به أحد خوفا من المأمون حتى حدثتك به يا أبا نزار","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":8,"spl":"قصيدته في أبي دلف — أبو دلف يبره ويفرط"},
{"id":"b254-11","bab":"الجزء 20","sec":"أبو دلف يبره ويفرط","page":"ج20 ص31","text":"أخبرني علي بن سليمان قال حدثني محمد بن يزيد قال حدثني علي بن القاسم قال قال لي علي بن جبلة زرت أبا دلف فكنت لا أدخل إليه إلا تلقاني ببره وأفرط فلما أكثر قعدت عنه حياء منه فبعث إلي بمعقل أخيه فأتاني فقال لي يقول لك الأمير لم هجرتنا لعلك استبطأت بعض ما كان مني فإن كان الأمر كذلك فإني زائد فيما كنت أفعله حتى ترضى فدعوت من كتب لي وأمللت عليه هذه الأبيات ثم دفعتها إلى معقل وسألته أن يوصلها وهي\n(هجرتك لم أهجرك من كفر نعمة ... وهل يرتجى نيل الزيادة بالكفر)\n(ولكنني لما أتيتك زائرا ... فأفرطت في بري عجزت عن الشكر)\n(فهأنا لا آتيك إلا مسلما ... أزورك في الشهرين يوما وفي الشهر)\n(فإن زدتني برا تزايدت جفوة ... ولم تلقني طول الحياة إلى الحشر)\nقال فلما سمعها معقل استحسنها جدا وقال جودت والله أما أن الأمير ليعجب بمثل هذه الأبيات فلما أوصلها إلى أبي دلف قال لله دره ما أشعره وما أرق معانيه ثم دعا بدواة فكتب إلي\n(ألا رب ضيف طارق قد بسطته ... وآنسته قبل الضيافة بالبشر)\n(أتاني يرجيني فما حال دونه ... ودون القرى من نائلي عنده ستري)\n(وجدت له فضلا علي بقصده ... إلي وبرا يستحق به شكري)\n(فلم أعد أن أدنيته وابتدأته ... ببشر وإكرام وبر علي بر)\n(وزودته مالا قليل بقاؤه ... وزودني مدحا يدوم على الدهر)\nم وجه بهذه الأبيات مع وصيف يحمل كيسا فيه ألف دينار فذلك حيث قلت له\n(إنما الدنيا أبو دلف ... بين باديه ومحتضره)\nخبرني عمي قال حدثني أحمد بن أبي طاهر قال حدثني أمد بن القاسم قال حدثني نادر مولانا أن علي بن جبلة خرج إلى عبد الله بن طاهر والي خراسان وقد امتدحه فلما وصل إليه قال له ألست القائل\n(إنما الدنيا أبو دلف ... بين بادية ومحتضره)\n(فإذا ولى أبو دلف ... ولت الدنيا على أثره)\nال بلى قال فما الذي جاء بك إلينا وعدل بك عن الدنيا التي زعمت أرجع من حيث جئت فارتحل ومر بأبي دلف وأعلمه الخبر فأعطاه حتى أرضاه قال نادر فرأيته عند مولاي القاسم بن يوسف وقد سأله عن خبره فقال\n(أبو دلف إن تلقه تلق ماجدا ... جوادا كريما راجح الحلم سيدا)\n(أبو دلف الخيرات أنداهم يدا ... وأبسط معروفا وأكرم محتدا)\n(تراث أبيه عن أبيه وجده ... وكل امرىء يجري على ما تعودا)\n(ولست بشاك غيره لنقيصة ... ولكنما الممدوح من كان أمجدا)","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":8,"spl":"قصيدته في أبي دلف — أبو دلف يبره ويفرط"},
{"id":"b254-12","bab":"الجزء 20","sec":"علي بن جبلة وحميد الطوسي","page":"ج20 ص33","text":"قال مؤلف هذا الكتاب والأبيات التي فيها الغناء المذكورة بذكرها أخبار أبي الحسن علي بن جبلة من قصيدة له مدح بها حميدا الطوسي ووصف قصره على دجلة وقال فيها بعد الأبيات التي فيها الغناء\n(ليس لي ذنب سوى أني ... أسميك خليلا)\n(وأناديك عزيزا ... وتناديني ذليلا)\n(أنا أهواك وحاليك ... صروما ووصولا)\n(ثق بود ليس يفنى ... وبعهد لن يحولا)\n(جعل الله حميدا ... لبني الدنيا كفيلا)\n(ملك لم يجعل الله ... فيهم عديلا)\n(فأقاموا في ذراه ... مطمئنين حلولا)\n(لا ترى فيهم مقلا ... يسأل المثري فضولا)\n(جاد بالأموال حتى ... علم الجود البخيلا)\n(وبنى الفخر على الفخر ... بناء مستطيلا)\n(صار للخائف أمنا ... وعلى الجود دليلا)\nولما مات حميد الطوسي رثاه بقصيدته العينية المشهورة وهي من نادر الشعر وبديعه وفي أولها غناء من الثقيل الأول يقال إنه لأبي العبيس ويقال إنه للقاسم بن زرزور\n(أللدهر تبكي أم على الدهر تجزع ... وما صاحب الأيام إلا مفجع)\n(ولو سهلت عنك الأسا كان في الأسا ... عزاء معز للبيب ومقنع)\n(تعر بما عزيت غيرك إنها ... سهام المنايا حائمات ووقع)\n(أصبنا بيوم في حميد لو أنه ... أصاب عروش الدهر ظلت تضعضع)\n(وأدبنا ما أدب الناس قبلنا ... ولكنه لم يبق للصبر موضع)\n(ألم تر للأيام كيف تصرمت ... به وبه كانت تذاد وتدفع)\n(وكيف التقى مثوى من الأرض ضيق ... على جبل كانت به الأرض تمنع)\n(ولما انقضت أيامه انقضت العلا ... وأضحى به أنف الندى وهو أجدع)\n(وراح عدو الدين جذلان ينتحي ... أماني كانت في حشاه تقطع)\n(وكان حميد معقلا ركعت به ... قواعد ما كانت على الضيم تركع)\n(وكنت أراه كالرزايا رزئتها ... ولم أدر أن الخلق يبكيه أجمع)\n(حمام رماه من مواضع أمنه ... حمام كذاك الخطب بالخطب يقدع)\n(وليس بغزو أن تصيب منية ... حمى أختها أو أ ن يذل الممنع)\nقد أدركت فينا المنايا بثارها ... وحلت بخطب وهيه ليس يرقع نعاء حميدا للسرايا إذا غدت ... تذاد بأطراف الرماح وتوزع وللمرهق المكروب ضاقت بأمره ... فلم يدر في حوماتها كيف يصنع\n(وللبيض خلتها البعول ولم يدع ... لها غيره داعي الصباح المفزع)\n(كأن حميدا لم يقد جيش عسكر ... إلى عسكر أشياعه لا تروع)\n(ولم يبعث الخيل المغيرة بالضحا ... مراحا ولم يرجع بها وهي ظلع)\n(رواجع يحملن النهاب ولم تكن ... كتائبه إلا على النهب ترجع)\n(هوى جبل الدنيا المنيع وغيثها المريع ... وحاميها الكمي المشيع)\n(وسيف أمير المؤمنين ورمحه ... ومفتاح باب الخطب والخطب أفظع)\n(فأقنعه من ملكه ورباعه ... ونائله قفر من الأرض بلقع)\n(على أي شجو تشتكي النفس بعده ... إلى شجوه أو يذخر الدمع مدمع)\n(ألم تر أن الشمس حال ضياؤها ... عليه وأضحى لونها وهو أسفع)\n(وأوحشت الدنيا وأودى بهاؤها ... وأجدب مرعاها الذي كان يمرع)\n(وقد كانت الدنيا به مطمئنة ... فقد جعلت أوتادها تتقلع)\n(بكى فقده روح الحياة كما بكى ... نداة الندى وابن السبيل المدفع)\n(وفارقت البيض الخدور وأبرزت ... عواطل حسرى بعده لا تقنع)\n(وأيقظ أجفانا وكان لها الكرى ... ونامت عيون لم تكن قبل تهجع)\n(ولكنه مقدار يوم ثوى به ... لكل امرىء منه نهال ومشرع)\n(وقد رأب الله الملا بمحمد ... وبالأصل ينمي فرعه المتفرع)\n(أغر على أسيافه ورماحه ... تقسم أنفال الخميس وتجمع)\n(حوى عن أبيه بذل راحته الندى ... وطعن الكلى والزاعبية شرع)\nإنما ذكرت هذه القصيدة على طولها لجودتها وكثرة نادرتها وقد أخذ البحتري أكثر معانيها فسلخه وجعله في قصيدتيه اللتين رثى بهما أبا سعيد الثغري\n(انظر إلى العلياء كيف تضام ... )\n(بأي أسى تثني الدموع الهوامل ... )\nقد أخذ الطائي أيضا بعض معانيها ولولا كراهة الإطالة لشرحت المواضع المأخوذة وإذا تأمل ذلك منتقد بصير عرفه أخبرني عمي قال حدثنا أحمد بن أبي طاهر قال حدثني أبو وائلة قال قال رجل لعلي بن جبلة ما بلغت في مديح أحد ما بلغته في مديحك حميدا الطوسي فقال وكيف لا أفعل وأدنى ما وصل إلي منه أني أهديت له قصيدة في يوم نيروز فسر بها وأمر أن يحمل إلي كل ما أهدي له فحمل إلي ما قيمته مائتا ألف درهم وأهديت له قصيدة في يوم عيد فبعث إلي بمثل ذلك قال أبو وائلة وقد كان حميد ركب يوم عيد في جيش عظيم لم ير مثله فقال علي بن جبلة يصف ذلك","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":9,"spl":"علي بن جبلة وحميد الطوسي","partial":1},
{"id":"b254-13","bab":"الجزء 20","sec":"علي بن جبلة وحميد الطوسي","page":"ج20 ص33","text":"(غدا بأمير المؤمنين ويمنه ... أبو غانم غدو الندى والسحائب)\n(وضاقت فجاج الأرض عن كل موكب ... أحاط به مستعليا للمواكب)\n(كأن سمو النقع والبيض فوقهم ... سماوة ليل فرنت بالكواكب)\nفكان لأهل العيد عيد بنسكهم ... وكان حميد عيدهم بالمواهب ولولا حميد لم تبلج عن الندى ... يمين ولم يدرك غنى كسب كاسب ولو ملك الدنيا لما كان سائل ... ولا اعتام فيها صاحب فضل صاحب له ضحكة تستغرق المال بالندى ... على عبسة تشجي القنا بالترائب ذهبت بأيام العلا فاردا بها ... وصرمت عن مسعاك شأو المطالب وعدلت ميل الأرض حتى تعدلت ... فلم ينأ منها جانب فوق جانب بلغت بأدنى الحزم أبعد قطرها ... كأنك منها شاهد كل غائب\nال والتي أهداها له يوم النيروز قصيدته التي فيها\n(حميد يا قاسم الدنيا بنائله ... وسيفه بين أهل النكث والدين)\n(أنت الزمان الذي يجري تصرفه ... على الأنام بتشديد وتليين)\n(لو لم تكن كانت الأيام قد فنيت ... والمكرمات ومات المجد مذ حين)\n(صورك الله من مجد ومن كرم ... وصور الناس من ماء ومن طين)\nسخت من كتاب بخط محمد بن العباس اليزيدي\nقال أحمد بن إسماعيل الخصيب الكاتب دخل علي بن جبلة يوما إلى أبي دلف فقال له هات يا علي ما معك فقال إنه قليل فقال هاته فكم من قليل أجود من كثير فأنشده\n(الله أجرى من الأرزاق أكثرها ... على يديك فشكرا يا أبا دلف)\n(أعطى أبو دلف والريح عاصفة ... حتى إذا وقفت أعطى ولم يقف)\nال فأمر له بعشرة آلاف درهم فلما كان بعد مدة دخل إليه فقال له هات ما معك فأنشده\n(من ملك الموت إلى قاسم ... رسالة في بطن قرطاس)\n(يا فارس الفرسان يوم الوغى ... مرني بمن شئت من الناس)\nال فأمر له بألفي درهم وكان قد تطير من ابتدائه في هذا الشعر فقال ليست هذه من عطاياك أيها الأمير فقال بلغ بها هذا المقدار ارتياعنا من تحملك رسالة ملك الموت إلينا أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني محمد بن عبد الله قال حدثني علي بن جبلة العكوك المروزي قال جاءني أبو يعقوب الخزيمي فقال لي إن لي إليك حاجة قلت وما هي قال تهجو لي الهيثم بن عدي فقلت ومالك أنت لا تهجوه وأنت\nشاعر فقال قد فعلت فما جاءني شيء كما أريد فقلت له كيف أهجو رجلا لم يتقدم إلي منه إساءة ولا له إلي جرم يحفظني فقال تقرضني فإني ملي بالقضاء قلت نعم فأمهلني اليوم فمضى وغدوت عليه فأنشدته\n(للهيثم بن عدي نسبة جمعت ... آباءه فأراحتنا من العدد)\n(أعدد عديا فلو مد البقاء له ... ما عمر الناس لم ينقص ولم يزد)\n(نفسي فداء بني عبد المدان وقد تلثوه للوجه واستعلوه بالعمد ... )\n(حتى أزالوه كرها عن كريمتهم ... وعرفوه بدل أين أصل عدي)\n(يا بن الخبيثة من أهجو فأفضحه ... إذا هجوت وما تنمى إلى أحد)\nال وكان الهيثم قد تزوج إلى بني الحارث بن كعب فركب محمد بن زياد بن عبيد الله بن عبد المدان الحارثي أخو يحيى بن زياد ومعه جماعة من أصحاب الحارثيين إلى الرشيد فسألوه أن يفرق بينهما فقال الرشيد أليس هو الذي يقول فيه الشاعر\n(إذا نسبت عديا في بني ثعل ... فقدم الدال قبل العين في النسب)\nالوا بلى يا أمير المؤمنين قال فهذا الشعر من قاله قالوا هو لرجل من أهل الكوفة من بني شيبان يقال له ذهل بن ثعلبة فأمر الرشيد داود بن يزيد أن يفرق بينهما فأخذوه فأدخلوه دارا وضربوه بالعصي حتى طلقها","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":10,"spl":"علي بن جبلة وحميد الطوسي","partial":1},
{"id":"b254-14","bab":"الجزء 20","sec":"علي بن جبلة وعبد الله بن طاهر","page":"ج20 ص40","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن الحسن بن الخصيب قال شخص علي بن جبلة إلى عبد الله بن طاهر والي خراسان وقد مدحه فأجزل صلته واستأذنه في الرجوع فسأله أن يقيم عنده وكان بره يتصل عنده فلما طال مقامه اشتاق إلى أهله فأنشده\n(راعه الشيب إذ نزل ... وكفاه من العذل)\n(وانقضت مدة الصبا ... فانقضى اللهو والغزل)\n(قد لعمري دملته ... بخضاب فما اندمل)\n(فابك للشيب إذ بدا ... لا على الربع والطلل)\n(وصل الله للأمير ... عرا الملك فاتصل)\n(ملك عزمه الزمان ... وأفعاله الدول)\n(كسروي بمجده ... يضرب الضارب المثل)\n(وإلى ظل عزه ... يلجأ الخائف الوجل)\n(كل خلق سوى الإمام ... لإنعامه خول)\n(ليته حين جاد لي ... بالغنى جاد بالقفل)\nقال فضحك وقال أبيت إلا أن توحشنا وأجزل صلته وأذن له\nأخبرني الحسن بن علي قال حدثني أحمد بن أبي طاهر قال حدثني أبو وائلة السدوسي قال دخل علي بن جبلة العكوك على حميد الطوسي في أول يوم من شهر رمضان فأنشده\n(جعل الله مدخل الصوم فوزا ... لحميد ومتعة في البقاء)\n(فهو شهر الربيع للقراء ... وفراق الندمان والصهباء)\n(وأنا الضامن الملي لمن عاقرها ... مفطرا بطول الظماء)\n(وكأني أرى الندامى على الخسف ... يرجون صبحهم بالمساء)\n(قد طوى بعضهم زيارة بعض ... واستعاضوا مصاحفا بالغناء)\nقول فيها\n(بحميد وأين مثل حميد ... فخرت طيئ على الأحياء)\n(جوده أظهر السماحة في الأرض ... وأغنى المقوي عن الإقواء)\n(ملك يأمل العباد نداه ... مثل ما يأملون قطر السماء)\n(صاغه الله مطعم الناس في الأرض ... وصاغ السحاب للإسقاء)\nال فأمر له بخمسة آلاف درهم وقال استعن بهذه على نفقة صومك ثم دخل إليه ثاني شوال فأنشده\n(عللاني بصفو ما في الدنان ... واتركا ما يقوله العاذلان)\n(واسبقا فاجع المنية بالعيش ... فكل على الجديدين فاني)\n(عللاني بشربة تذهب الهم ... وتنفي طوارق الأحزان)\n(وانفثا في مسامع سدها الصوم ... رقى الموصلي أو دحمان)\n(قد أتانا شوال فاقتبل العيش ... وأعدى قسرا على رمضان)\n(نعم عون الفتى على نوب الدهر ... سماع القيان والعيدان)\n(وكؤوس تجري بماء كروم ... ومطي الكؤوس أيدي القيان)\n(من عقار تميت كل احتشام ... وتسر الندمان بالندمان)\n(وكأن المزاج يقدح منها ... شرارا في سبائك العقيان)\n(فاشرب الراح واعص من لام فيها ... إنها نعم عدة الفتيان)\n(واصحب الدهر بارتحال وحل ... لا تخف ما يجره الحادثان)\n(حسب مستظهرعلى الدهر ركنا ... بحميد رداءا من الحدثان)\n(ملك يقتني المكارم كنزا ... وتراه من أكرم الفتيان)\n(خلقت راحتاه للجود والبأس ... وأمواله لشكر اللسان)\n(ملكته على العباد معد ... وأقرت له بنو قحطان)\n(أريحي الندى جميل المحيا ... يده والسماح معتقدان)\n(وجهه مشرق إلى معتفيه ... ويداه بالغيث تنفجران)\n(جعل الدهر بين يوميه قسمين ... بعرف جزل وحر طعان)\n(فإذا سار بالخميس لحرب ... كل عن نص جريه الخافقان)\n(وإذا ما هززته لنوال ... ضاق عن رحب صدره الأفقان)\n(غيث جدب إذا أقام ربيع ... يتغشى بالسيب كل مكان)\n(يا أبا غانم بقيت على الدهر ... وخلدت ما جرى العصران)\n(ما نبالي إذا عدت المنايا ... من أصابت بكلكل وجران)\n(قد جعلنا إليك بعث المطايا ... هربا من زماننا الخوان)\n(وحملنا الحاجات فوق عتاق ... ضامنات حوائج الركبان)\n(ليس جود وراء جودك ينتاب ... ولا يعتفي لغيرك عاني)\nأمر له بعشرة آلاف درهم وقال تلك كانت للصوم فخففت وخففنا وهذه للفطر فقد زدتنا وزدناك أخبرني عمي قال حدثنا أحمد بن الطيب السرخسي قال حدثنا ابن أخي علي بن جبلة العكوك قال أحمد وكان علي جارنا بالربض هو وأهله وكان أعمى وبه وضح وكان يهوى جارية أديبة ظريفة شاعرة وكانت تحبه هي أيضا على قبح وجهه وما به من الوضح حدثني بذلك عمرو بن بحر الجاحظ قال عمرو وحدثني العكوك أن هذه الجارية زارته يوما وأمكنته من نفسها حتى افتضها قال وذلك عنيت في قولي\n(ودم أهدرت من رشإ ... لم يرد عقلا على هدره)\nوهي القصيدة التي مدح بها أبا دلف يعني بالدم دم البضع قال ثم قصدت حميدا بقصيدتي التي مدحته بها فلما استؤذن لي عليه أبى أن يأذن لي وقل قولوا له أي شيء أبقيت لي بعد قولك في أبي دلف\n(إنما الدنيا أبو دلف ... بين مبداه ومحتضره)","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":11,"spl":"علي بن جبلة وعبد الله بن طاهر"},
{"id":"b254-15","bab":"الجزء 20","sec":"علي بن جبلة وعبد الله بن طاهر","page":"ج20 ص40","text":"(فإذا ولى أبو دلف ... ولت الدنيا على أثره)\nقلت للحاجب قل له الذي قلت فيك أحسن من هذا فإن وصلتني سمعته فأمر بإيصالي فأنشدت قولي فيه\n(إنما الدنيا حميد ... وأياديه الجسام)\n(فإذا ولى حميد ... فعلى الدنيا السلام)\nأمر لي بمائتي دينار فنثرتها في حجر عشيقتي ثم جئته بقصيدتي التي أقول فيها\n(دجلة تسقي وأبو غانم ... يطعم من تسقي من الناس)\nأمر لي بمائتي دينار حدثني عمي قال حدثني أحمد بن الطيب قال حدثني ابن أخي علي بن جبلة أيضا أن عمه عليا كان يهوى جارية وهي هذه القينة وكانت له مساعدة ثم غضبت عليه وأعرضت عنه فقال فيها\n(تسيء ولا تستنكر السوء إنها ... تدل لما تبلوه عندي وتعرف)\n(فمن أين ما استعطفتها لم ترق لي ... ومن أين ما جربت صبري يضعف)\nأخبرني حبيب بن نصر قال حدثنا عمر بن شبة قال تذاكرنا يوما أقبح ما هجي به الناس في ترك الضيافة وإضاعة الضيف فأنشدنا علي بن جبلة لنفسه\n(أقاموا الديدبان على يفاع ... وقالوا لا تنم للديدبان)\n(فإن آنست شخصا من بعيد ... فصفق بالبنان على البنان)\n(تراهم خشية الأضياف خرسا ... ويأتون الصلاة بلا أذان)\nخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهروية قال حدثني أبي قال حدثني وهب بن سعيد المروزي كاتب حميد الطوسي قال جئت حميدا في أول يوم من شهر رمضان فدفع إلي كيسا فيه ألف دينار وقال تصدقوا بهذه وجاءه ابنه أصرم فسلم عليه ودعا له ثم قال له خادمك علي بن جبلة بالباب فقال وما أصنع به جئتني به يا بني تقابلني بوجهه في أول يوم من هذا الشهر فقال إنه يجيد فيك القول قال فأنشدني بيتا مما تستجيد له فأنشده قوله\n(حيدي حياد فإن غزوة جيشه ... ضمنت لجائلة السباع عيالها)\nقال أحسن ائذنوا له فدخل فسلم ثم أنشده قوله\n(إن أبا غانم حميدا ... غيث على المعتفين هامي)\n(صوره الله سيف حتف ... وباب رزق على الأنام)\n(يا مانع الأرض بالعوالي ... والنعم الجمة العظام)\n(ليس من السوء في معاذ ... من لم يكن منك في ذمام)\n(وما تعمدت فيك وصفا ... إلا تقدمته أمامي)\n(فقد تناهت بك المعالي ... وانقطعت مدة الكلام)\n(أجد شهرا وأبل شهرا ... واسلم على الدهر ألف عام)\nال فالتفت إلي حميد وقال أعطه ذلك الألف الدينار حتى يخرج للصدقة غيره حدثني عمي قال حدثني يعقوب بن إسرائيل قال حدثني أبو سهيل بن سالم مولى حميد الطوسي قال جاء علي بن جبلة إلى حميد الطوسي مستشفعا به إلى أبي دلف وقد كان غضب عليه وجفاه فركب إلى أبي دلف شافعا وسأله في أمره فأجابه واتصل الحديث بينهما وعلي بن جبلة محجوب فأقبل على رجل إلى جانبه وقال اكتب ما أقول لك فكتب\n(لا تتركني بباب الدار مطرحا ... فالحر ليس عن الأحرار يحتجب)\n(هبنا بلا شافع جئنا ولا سبب ... ألست أنت إلى معروفك السبب)\nال فأمر بإيصاله إليه ورضي عنه ووصله أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أحمد بن مروان قال حدثني أبو سعيد المخزومي قال دخلت على حميد الطوسي فأنشدته قصيدة مدحته بها وبين يديه رجل\nضرير فجعل لا يمر ببيت إلا قال أحسن قاتله الله أحسن ويحه أحسن لله أبوه أحسن أيها الأمير فأمر لي حميد ببدرة فلما خرجت قام إلي البوابون فقلت كم أنتم عرفوني أولا من هذا المكفوف الذي رأيته بين يدي الأمير فقالوا علي بن جبلة العكوك فارفضضت عرقا ولو علمت أنه علي بن جبلة لما جسرت على الإنشاد بين يديه","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":12,"spl":"علي بن جبلة وعبد الله بن طاهر"},
{"id":"b254-16","bab":"الجزء 20","sec":"المأمون يدخل علي ولكن بشرط","page":"ج20 ص47","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا أحمد بن عبيد بن ناصح قال كلم حميد الطوسي المأمون في أن يدخل عليه علي بن جبلة فيسمع منه مديحا مدحه به فقال وأي شيء يقوله في بعد قوله في أبي دلف\n(إنما الدنيا أبو دلف ... بين مغزاه ومحتضره)\n(فإذا ولى أبو دلف ... ولت الدنيا على أثره)\nبعد قوله فيك\n(يا واحد العرب الذي ... عزت بعزته العرب)\nحسن أحواله أن يقول في مثل ما قاله في أبي دلف فيجعلني نظيرا له هذا إن قدر على ذلك ولم يقصر عنه فخيروه بين أن أسمع منه فإن كان مدحه إياي أفضل من مدحه أبا دلف وصلته وإلا ضربت عنقه أو قطعت لسانه وبين أن أقيله وأعفيه من هذا وذا فخيروه بذلك فاختار الإقالة ثم مدح حميدا الطوسي فقال له وما عساك أن تقول في بعدما قلته في أبي دلف فقال قد قلت فيك خيرا من ذلك قال هات فأنشده\n(دجلة تسقي وأبو غانم ... يطعم من تسقي من ا لناس)\n(الناس جسم وإمام الهدى ... رأس وأنت العين في الراس)\nقال له حميد قد أجدت ولكن ليس هذا مثل ذلك ووصله قال أحمد بن عبيد ثم مات حميد الطوسي فرثاه علي بن جبلة فلقيته فقلت له أنشدني مرثيتك حميدا فأنشدني\n(نعاء حميدا للسرايا إذا غدت ... تذاد بأطراف الرماح وتوزع)\nتى أتى على آخرها فقلت له ما ذهب على النحو الذي نحوته يا أبا الحسن وقد قاربته وما بلغته فقال وما هو فقلت أردت قول الخريمي في مرثيته أبا الهيذام\n(وأعددته ذخرا لكل ملمة ... وسهم المنايا بالذخائر مولع)\nقال صدقت والله أما والله لقد نحوته وأنا لا أطمع في اللحاق به لا والله ولا أمرؤ القيس لو طلبه وأراده ما كان يطمع أن يقاربه في هذه القصيدة","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":13,"spl":"المأمون يدخل علي ولكن بشرط — هروبه من المأمون"},
{"id":"b254-17","bab":"الجزء 20","sec":"هروبه من المأمون","page":"ج20 ص48","text":"أخبرني عمي قال حدثنا أحمد بن أبي طاهر قال حدثني ابن أبي حرب الزعفراني قال لما بلغ المأمون قول علي بن جبلة لأبي دلف\n(كل من في الأرض من عرب ... بين باديه إلى حضره)\n(مستعير منك مكرمة ... يكتسيها يوم مفتخره)\nضب من ذلك وقال اطلبوه حيث كان فطلب فلم يقدر عليه\nوذلك أنه كان بالجبل فلما اتصل به الخبر هرب إلى الجزيرة وقد كانوا كتبوا إلى الآفاق في طلبه فهرب من الجزيرة أيضا وتوسط الشام فظفروا به فأخذوه وحملوه إلى المأمون فلما صارإليه قال له يابن اللخناء أنت القائل للقاسم بن عيسى\n(كل من في الأرض من عرب ... بين باديه إلى حضره)\n(مستعير منك مكرمة ... يكتسيها يوم مفتخرة)\nعلتنا ممن يستعير المكارم منه فقال له يا أمير المؤمنين أنتم أهل بيت لا يقاس بكم أحد لأن الله جل وعز فضلكم على خلقه واختاركم لنفسه وإنما عنيت بقولي في القاسم أشكال القاسم وأقرانه فقال والله ما استثنيت أحدا عن الكل سلوا لسانه من قفاه أخبرني الحسن بن علي قال حدثنا محمد بن موسى قال وحدثني أحمد بن أبي فنن أن المأمون لما أدخل عليه علي بن جبلة قال له إني لست استحل دمك لتفضيلك أبا دلف على العرب كلها وإدخالك في ذلك قريشا وهم آل رسول الله وعترته ولكني أستحله بقولك في شعرك وكفرك حيث تقول القول الذي أشركت فيه\n(أنت الذي تنزل الأيام منزلها ... وتنقل الدهر من حال إلى حال)\n(وما مددت مدى طرف إلى أحد ... إلا قضيت بأرزاق وآجال)\nكذبت يا ماص بظر أمه ما يقدر على ذلك أحد إلا الله عز و جل الملك الواحد القهار سلوا لسانه من قفاه صوت\n(لا بد من سكرة على طرب ... لعل روحا يدال من كرب)\nيروى\n(لعل روحا يديل من كرب ... )\nوهو أصوب\n(فعاطنيها صهباء صافية ... تضحك من لؤلؤ على ذهب)\n(خليفة الله أنت منتخب ... لخير أم من هاشم وأب)\n(أكرم بأصلين أنت فرعهما ... من الإمام المنصور في النسب)\nلشعر للتيمي والغناء لسليم بن سلام خفيف ثقيل أول بالبنصر عن عمرو وفيها لنظم العمياء خفيف رمل بالبنصر عن الهشامي","topic":"نسب ابن الخياط وأخباره","topicNo":254,"sp":13,"spl":"المأمون يدخل علي ولكن بشرط — هروبه من المأمون","partial":1},
{"id":"b255-1","bab":"الجزء 20","sec":"أخبار التيمي ونسبه","page":"ج20 ص51","text":"هو عبد الله بن أيوب ويكنى أبا محمد مولى بني تيم ثم مولى بني سليم ذكر ذلك ابن النطاح وكان له أخ يقال له أبو التيجان وكلاهما كان شاعرا وهما من أهل الكوفة وهما من شعراء الدولة العباسية أحد الخلعاء المجان الوصافين للخمر وكان صديقا لإبراهيم الموصلي وابنه إسحاق ونديما لهما ثم اتصل بالبرامكة ومدحهم واتصل بيزيد بن مزيد فلم يزل منقطعا إليه حتى مات يزيد واستنفذ شعره أو أكثره في وصفه الخمر وهو الذي يقول\n(شربت من الخمر يوم الخميس ... بالكأس والطاس والقنقل)\n(فما زالت الكأس تغتالنا ... وتذهب بالأول الأول)\n(إلى أن توافت صلاة العشا ... ونحن من السكر لم نعقل)\n(فمن كان يعرف حق الخميس ... وحق المدام فلا يجهل)\n(وما إن جرت بيننا مزحة ... تهيج مراء على السلسل)\nهو القائل\n(ولن أنتهي عن طيب الراح أو يرى ... بوادي عظامي في ضريحي لاحد)\n(أضعت شبابي في الشراب تلذذا ... وكنت امرأ غر الشباب أكابد)\nخبرني محمد بن يحيى الصولي قال حدثني أبو العيناء عن محمد بن عمر قال أبو محمد التيمي اسمه عبد الله بن أيوب مولى بني تيم أخبرني أحمد بن عبيد الله بن عمار عن محمد بن داود بن الجراح قال قال دعبل كان للتيمي أبي محمد ابن يقال له حبان مات وهو حديث السن فجزع عليه وقال يرثيه صوت\n(أودى بحبان ما لم يترك الناسا ... فامنح فؤادك من أحبابك الياسا)\n(لما رمته المنايا إذ قصدن له ... أصبن مني سواد القلب والراسا)\n(وإذ يقول لي العواد إذ حضروا ... لاتأس أبشر أبا حبان لا تاسى)\n(فبت أرعى نجوم الليل مكتئبا ... إخال سنته في الليل قرطاسا)\nنى في الأول والرابع من هذه الأبيات حكم الوادي ولحنه رمل مطلق في مجرى البنصر عن إسحاق وأول هذه القصيدة\n(يا دير هند لقد أصبحت لي انسا ... وما عهدتك لي يا دير مئناسا)\nهي مشهورة من شعره أخبرني حبيب بن نصر المهلبي قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني حماد بن إسحاق عن أبيه قال قلت\n(وصف الصد لمن أهوى فصد ... )\nثم أجبلت فمكثت عدة ليال لا يستوي لي تمامه فدخل علي التيمي فرآني مفكرا فقال ما قصتك فأخبرته فقال\n(وبدا يمزح بالهجر فجد ... )\nم أتممتها فقلت\n(ما له يعدل عني وجهه ... وهو لا يعدله عندي أحد)\nخرجت إلى مدح الفضل بن الربيع فقلت\n(قد أرادوا غرة الفضل وهل ... تطلب الغرة في خيس الأسد)\n(ملك ندفع ما نخشى به ... وبه يصلح منا ما فسد)\n(يفعل الناس إذا ما وعدوا ... وإذا ما فعل الفضل وعد)\nإسحاق في هذا الشعر صنعة ونسبتها صوت\n(وصف الصد لمن نهوى فصد ... وبدا يمزح بالهجر فجد)\n(ما له يعدل عني وجهه ... وهو لا يعدله عندي أحد)\nلشعر والغناء لإسحاق خفيف رمل بالبنصر وله فيه أيضا ثقيل أول وفيه لزكريا بن يحيي بن معاذ هزج بالبنصر عن الهشامي وغيره قال الهشامي وقيل إن الهزج لإسحاق وخفيف الرمل لزكريا أخبرني جحظة عن علي بن يحيي المنجم عن إسحاق قال\nاشتركت أنا وأبو محمد التيمي في هذا الشعر\n(وصف الصد لمن نهوى فصد ... )\nذكر البيتين","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":0,"spl":"أخبار التيمي ونسبه","partial":1},
{"id":"b255-2","bab":"الجزء 20","sec":"الرشيد يطلب سماع قصيدته في رثاء يزيد بن مزيد","page":"ج20 ص55","text":"أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن طهمان قال حدثني محمد الراوية الذي يقال له البيذق وكان يقرأ شعر المحدثين على الرشيد قال قال لي الرشيد يوما أنشدني مرثية مروان بن أبي حفصة في معن بن زائدة التي يقول فيها\n(كأن الشمس يوم أصيب معن ... من الإظلام ملبسه جلالا)\n(هو الجبل الذي كانت معد ... تهد من العدو به الجبالا)\n(أقمنا باليمامة بعد معن ... مقاما لا نريد به زيالا)\n(وقلنا أين نذهب بعد معن ... وقد ذهب النوال فلا نوالا)\nال فأنشدته إياها ثم قال لي أنشدني قصيدة أبي موسى التيمي في مرثية يزيد بن مزيد فهي والله أحب إلي من هذه فأنشدته\n(أحق أنه أودى يزيد ... تبين أيها الناعي المشيد)\n(أتدري من نعيت وكيف فاهت ... به شفتاك كان بك الصعيد)\n(أحامي المجد والإسلام أودى ... فما للأرض ويحك لا تميد)\n(تأمل هل ترى الإسلام مالت ... دعائمه وهل شاب الوليد)\n(وهل شيمت سيوف بني نزار ... وهل وضعت عن الخيل اللبود)\n(وهل تسقي البلاد عشار مزن ... بدرتها وهل يخضر عود)\n(أما هدت لمصرعه نزار ... بلى وتقوض المجد المشيد)\n(وحل ضريحه إذ حل فيه ... طريف المجد والحسب التليد)\n(أما والله ما تنفك عيني ... عليك بدمعها أبدا تجود)\n(فإن تجمد دموع لئيم قوم ... فليس لدمع ذي حسب جمود)\n(أبعد يزيد تختزن البواكي ... دموعا أو تصان لها خدود)\n(لتبكك قبة الإسلام لما ... وهت أطنابها ووهى العمود)\n(ويبكك شاعر لم يبق دهر ... له نشبا وقد كسد القصيد)\n(فمن يدعو الإمام لكل خطب ... ينوب وكل معضلة تؤود)\n(ومن يحمي الخميس إذا تعايا ... بحيلة نفسه البطل النجيد)\n(فإن يهلك يزيد فكل حي ... فريس للمنية أو طريد)\n(ألم تعجب له أن المنايا ... فتكن به وهن له جنود)\n(قصدن له وهن يحدن عنه ... إذا ما الحرب شب لها وقود)\n(لقد عزى ربيعة أن يوما ... عليها مثل يومك لا يعود)\nقال فبكى هارون الرشيد بكاء اتسع فيه حتى لو كانت بين يديه سكرجة لملأها من دموعه أخبرني محمد بن يحيى قال حدثنا أبو العيناء قال حدثنا محمد بن عمر قال\nخرج كوثر خادم محمد الأمين ليرى الحرب فأصابته رجمة في وجهه فجلس يبكي فوجه محمد من جاءه به وجعل يمسح الدم عن وجهه وقال\n(ضربوا قرة عيني ... ومن أجلي ضربوه)\n(أخذ الله لقلبي ... من أناس أحرقوه)\nال وأراد زيادة في الأبيات فلم يواته فقال للفضل بن الربيع من ها هنا من الشعراء فقال الساعة رأيت عبد الله بن أيوب التيمي فقال علي به فلما أدخل أنشده محمد هذين البيتين وقال أجزهما فقال\n(ما لمن أهوى شبيه ... فبه الدنيا تتيه)\n(وصله حلو ولكن ... هجره مركريه)\n(من رأى الناس له الفضل ... عليهم حسدوه)\n(مثل ما قد حسد القائم ... بالملك أخوه)\nفقال محمد أحسنت هذا والله خير مما أردنا بحياتي عليك يا عباسي إلا نظرت فإن جاء على الظهر ملأت أحمال ظهره دراهم وإن كان جاء في زورق ملأته فأوقرت له ثلاثة أبغل دراهم","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":1,"spl":"الرشيد يطلب سماع قصيدته في رثاء يزيد بن مزيد"},
{"id":"b255-3","bab":"الجزء 20","sec":"الفضل بن سهل يتوسط له فيعفو عنه المأمون","page":"ج20 ص58","text":"قال محمد بن يحيي فحدثني الحسن بن عليل العنزي قال حدثني محمد بن إدريس قال لما قتل محمد الأمين خرج أبو محمد التيمي إلى المأمون وامتدحه فلم يأذن له فصار إلى الفضل بن سهل ولجأ إليه وامتدحه فأوصله إلى\nالمأمون فلما سلم عليه قال له المأمون إيه يا تيمي\n(مثل ما قد حسد القائم ... بالملك أخوه)\nقال التيمي بل أنا الذي أقول يا أمير المؤمنين\n(نصر المأمون عبدالله ... لما ظلموه)\n(نقضوا العهد الذي كانوا ... قديما أكدوه)\n(لم يعامله أخوه ... بالذي أوصى أبوه)\nم أنشده قصيدة له امتدحه بها أولها\n(جزعت ابن تيم أن أتاك مشيب ... وبان الشباب والشباب حبيب)\nال فلما أنشده إياها وفرغ منها قال قد وهبتك لله عز و جل ولأخي العباسي يعني الفضل بن سهل وأمرت لك بعشرة آلاف درهم أخبرني محمد بن يحيي قال حدثني عون بن محمد الكندي قال حدثني عباد بن محمد الكاتب عن أبي محمد التيمي الشاعر قال أنشدت الأمين محمدا أول ما ولي الخلافة قولي\n(لا بد من سكرة على طرب ... لعل روحا يديل من كرب)\nلأبيات المذكورة في الغناء قال فأمر لي بمائتي ألف درهم صالحوني منها على مائة ألف درهم وأخبرني جعفر بن قدامة قال حدثني محمد بن يحيي المنجم قال وحدثني حسين بن الضحاك قال قال لي أبو محمد التيمي\nدخلت على محمد الأمين أول ما ولي الخلافة فقال يا تيمي وددت أنه قيل في مثل قول طريح بن إسماعيل في الوليد بن يزيد\n(طوبى لفرعيك من هنا وهنا ... طوبى لأعراقك التي تشج)\nفإني والله أحق بذلك منه فقلت أنا أقول ذلك يا أمير المؤمنين ثم دخلت إليه من غد فأنشدته قصيدتي\n(لا بد من سكرة على طرب ... لعل روحا يديل من كرب)\nتى انتهيت إلى قولي\n(أكرم بفرعين يجريان به ... إلى الإمام المنصور في النسب)\nتبسم ثم قال لي يا تيمي قد أحسنت ولكنه كما قيل مرعى ولا كالسعدان ثم التفت إلى الفضل بن الربيع فقال بحياتي أوقر له زورقه مالا فقال نعم يا سيدي فلما خرجت طالبت الفضل بذلك فقال أنت مجنون من أين لنا ما يملأ زورقك ثم صالحني على مائة ألف درهم","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":2,"spl":"الفضل بن سهل يتوسط له فيعفو عنه المأمون"},
{"id":"b255-4","bab":"الجزء 20","sec":"التيمي يمدح الفضل بن يحيى","page":"ج20 ص61","text":"أخبرني وكيع قال حدثني ابن اسحاق قال حدثني أبي قال\nكنت على باب الفضل بن يحيى فأتاني التيمي الشاعر بقصيدة في قرطاس وسألني أن أوصلها إلى الفضل فنظرت فيها ثم خرقت القرطاس فغضب أبو محمد وقال لي أما كفاك أن استخففت بحاجتي منعتني أن أدفعها إلى غيرك فقلت له أنا خير لك من القرطاس ثم دخلت إلى الفضل فلما تحدثنا قلت له معي هدية وصاحبها بالباب وأنشدته فقال كيف حفظتها قلت الساعة دفعها إلي على الباب فحفظتها فقال دع ذا الآن فقلت له فأدخله فأدخل فسأله عن القصة فأخبره فقال أنشدني شيئا من شعرك ففعل وجعلت أردد أبياته وجعلت أشيعها بالاستحسان ثم خرج التيمي فقلت خذ في حاجة الرجل فقال أما إذ عنيت به فقد أمرت له بخمسة آلاف درهم فقلت له أما إذ أقللتها فعجلها فأمر بها فأحضرت فقلت له أليس لإعناتك إياي ثمن قال نعم قلت فهاته قال لا أبلغ بك في الإعنات ما بلغت بالشاعر في المديح فقلت فهات ما شئت فأمر بثلاثة آلاف درهم فضممتها إلى الخمسة الآلاف ووجهت بها إليه\n(وذكر أحمد بن طاهر عن أبي هفان عن إسحاق قال كان التيمي ... )\nوأخوه أبو التيحان وابن عم له يقال له قبيصة يشربون في حانة حتى سكروا وانصرفوا من غد فقال التيمي يذكر ذلك ويتشوق مثله صوت\n(هل إلى سكرة بناحية الحيرة ... شنعاء يا قبيص سبيل)\n(وأبو التيحان في كفه القرعة ... والرأس فوقه إكليل)\n(وغرار كأنه بيذق الشطرنج ... يفتن فيه قال وقيل)\nلشعر للتيمي والغناء لمحمد بن الأشعث رمل بالوسطى أخبرني الحسن بن علي قال حدثنا أبو العيناء عن أبي العالية قال أمر محمد الأمين لعبد الله بن أيوب بجائزة عشرة آلاف دينار ثوابا عن بعض مدائحه فاشترى بها ضيعة بالبصرة وقال بعد ابتياعه إياها\n(إني اشتريت بما وهبت ليه ... أرضا أمون بها قرابتيه)\n(فبحسن وجهك حين أسأل قل ... يابن الربيع احمل إليه ميه)\nغني بها الأمين فقال للفضل بحياتي يا عباسي أحمل إليه مائة ألف فدعا به فأعطاه خمسين ألفا وقال له الخمسون الأخر لك علي إذا اتسعت أيدينا أخبرني الحسن قال حدثني أبو العيناء عن أبي العالية قال عشق التيمي جارية لبعض النخاسين فشكا وجده بها إلى أبي عيسى بن الرشيد فقال أبو عيسى للمأمون يا أمير المؤمنين إن التيمي يجد\nبجارية لبعض النخاسين وقد كتب إلي بيتين يسألني فيهما ثمنها فقال وما هما فقال\n(يا أبا عيسى إليك المشتكى ... وأخو الصبر إذا عيل شكا)\n(ليس لي صبر على فقدانها ... وأعاف المشرب المشتركا)\nال فأمر له بثلاثين ألف درهم فاشتراها بها أخبرني الحسن قال حدثني أبو العيناء عن أبي العالية قال دخل التيمي إلى الفضل بن الربيع في يوم عيد فأنشده\n(ألا إنما آل الربيع ربيع ... وغيث حيا للمرملين مريع)\n(إذا ما بدا آل الربيع رأيتهم ... لهم درج فوق العباد رفيع)\nأمر له بعشرة آلاف درهم أخبرني عيسى بن الحسن قال حدثنا أحمد بن أبي خيثمة قال حدثنا الزبير بن بكار قال مدح أبو محمد التيمي الفضل بن يحيى بثلاث أبيات ودفعها إلى إسحاق الموصلي فعرضها على الفضل بن يحي فأمر له بثلاثة آلاف درهم والأبيات\n(لعمرك ما الأشراف في كل بلدة ... وإن عظموا للفضل إلا صنائع)\n(ترى عظماء الناس للفضل خشعا ... إذا ما بدا والفضل لله خاشع)\n(تواضع لما زاده الله رفعة ... وكل جليل عنده متواضع)\nخبرني جحظة قال حدثني علي بن يحيي المنجم قال حدثني إسحاق الموصلي عن محمد بن سلام قال\nكتب الحجاج إلى قتيبة بن مسلم إني قد نظرت في سني فإذا أنا ابن ثلاث وخمسين سنة وأنا وأنت لدة عام وإن امرأ قد سار إلى منهل خمسين سنة لقريب أن يرده والسلام فسمع هذا أبو محمد التيمي مني فقال\n(إذاذهب القرن الذي أنت فيهم ... وخلفت في قرن فأنت غريب)\n(وإن امرأ قد سار خمسين حجة ... إلى منهل من ورده لقريب)\nدثني عمي قال حدثني أحمد بن أبي طاهر قال حدثني أبو دعامة علي بن يزيد قال حدثني التيمي أبو محمد قال دخلت على الحسن بن سهل فأنشدته مديحا في المأمون ومديحا فيه وعنده طاهر بن الحسين فقال له طاهر هذا والله أيها الأمير الذي يقول في محمد المخلوع\n(لا بد من سكرة على طرب ... لعل روحا يديل من كرب)\n(خليفة الله خير منتخب ... لخير أم من هاشم وأب)\n(خلافة الله قد توارثها ... آباؤه في سوالف الكتب)\n(فهي له دونكم مورثة ... عن خاتم الأنبياء في الحقب)","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":3,"spl":"التيمي يمدح الفضل بن يحيى","partial":1},
{"id":"b255-5","bab":"الجزء 20","sec":"التيمي يمدح الفضل بن يحيى","page":"ج20 ص61","text":"(يابن الذرا من ذوائب الشرف الأقدم ... أنتم دعائم العرب)\nقال الحسن عرض والله ابن اللخناء بأمير المؤمنين والله لأعلمنه وقام إلى المأمون فأخبره فقال المأمون وما عليه في ذلك رجل أمل رجلا فمدحه والله لقد أحسن بنا وأساء إليه إذا لم يتقرب إليه إلا بشرب الخمر ثم دعاني فخلع علي وحملني وأمر لي بخمسة آلاف درهم أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني أبو الشبل البرجمي عن أبيه قال قال لي أبو محمد التيمي أول شعر به فشاع فيه ذكري ووصلت به إلى الخليفة قولي صوت\n(طاف طيف في المنام ... بمحب مستهام)\n(زورة أبقت سقاما ... وشفت بعض السقام)\n(لم يكن ما كان فيها ... من حرام بحرام)\n(لم تكن إلا فواقا ... وهي في ليل التمام)\nلغناء لإسحاق فقال فصنع فيها إسحاق لحنا وغنى به الرشيد فسأله عن قائل الشعر فقال له صديق لي شاعر ظريف يعرف بالتيمي فطلبت\nوأمرت بالحضور فسألت عن السبب الذي دعيت له فعرفته فأتممت الشعر وجعلته قصيدة مدحت بها هارون ودخلت إليه فأنشدته إياها فأمر له بثلاثين ألف درهم وصرت في جملة من يدخل إليه بنوبة وأمر أن يدون شعري","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":4,"spl":"التيمي يمدح الفضل بن يحيى"},
{"id":"b255-6","bab":"الجزء 20","sec":"التيمي وإسحاق الموصلي","page":"ج20 ص66","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق قال حدثني عمي طياب بن إبراهيم الموصلي قال حدثني أبو محمد التيمي الشاعر قال اجتزت يوما بأخيك إسحاق فقال ادخل حتى أطعمك طعاما صرفاوأسقيك شرابا صرفا وأغنيك غناء صرفا فدخلت إليه فأطعمني لحما مكببا وشواء حارا وباردا مبزرا وأسقاني شرابا عتيقا صدفا وغناني وحده مرتجلا\n(ولو أن أنفاسي أصابت بحرها ... حديدا إذا كاد الحديد يذوب)\n(ولو أن عيني أطلقت من وكائها ... لما كان في عام الجدوب جدوب)\n(ولو أن سلمى تطلع الشمس دونها ... وأمسي وراء الشمس حين تغيب)\n(لحدثت نفسي أن تريع بها النوى ... وقلت لقلبي إنها لقريب)\nفلم تزل تلك حالي حتى حملت من بيته سكران أخبرني جحظة قال حدثنا حماد بن إسحاق عن أبيه قال دخلت يوما على عمرو بن مسعدة فإذا أبو محمد التيمي واقف بين يديه\nيستأذنه في الإنشاد فقال ذاك إلى أبي محمد يعنيني وكان على التيمي عاتبا فكره أن يمنعه لعلمه بما بيننا من المودة فقلت له أنشد إذ جعل الأمر إلي فأرجو أن يجعل أمر الجائزة أيضا إلي فتبسم عمرو وأنشده التيمي\n(يا أبا الفضل كيف تغفل عني ... أم تخلى عند الشدائد مني)\n(أنسيت الإخاء والعهد والود ... حديثا ما كان ذلك ظني)\n(أنا من قد بلوت في سالف الدهر ... مضت شرتي ولم تفن سني)\n(فاصطنعني لما ينوب به الدهر ... فإني أجوز في كل فن)\n(أنا ليث على عدوك سلم ... لك في الحرب فابتذلني وصلني)\n(أنا سيف يوم الوغى وسنان ... ومجن إن لم تثق بمجن)\n(أنا طب في الرأي في موضع الرأي ... معين على الخصيم المعن)\n(وأمين على الودائع والسر ... إذا ما هويت أن تأتمني)\nال فأقبل علي عمرو وهو يضحك وقال أتعلم هذا الغناء منك أم كان يعلمه قديما فقلت له لم يكذب أعزك الله فقال أفي هذا وحده أو في الجميع فقلت أما في هذا فأنا أحق كذبة والله أعلم بالباقي ثم أنشده\n(وإذا ما أردت حجا فرحال ... دليل إن نام كل ضفن)\nقال له إذا عزمنا على الحج امتحناك في هذا فإني أراك تصلح له ثم أنشده\n(ولبيب على مقال أبي العباس ... إني أرى به مس جن)\nقال ما أراه أبعد فقال\n(وهو الناصح الشفيق ولكن ... خاف هيج الزمان فازور عني)\n(ظريف عند المزاح خفيف ... في الملاهي وفي الصبا متثن)\n(كيف باعدت أو جفوت صديقا ... لا ملولا لالا ولا متجن)\n(صرت بعد الإكرام والأنس أرضى ... منك بالترهات ما لم تهني)\n(لم تخني ولم أخنك ولا والله ... ربي لا خنت من لم يخني)\n(إن أكن تبت أو هجرت الملاهي ... وسلافا يجنها بطن دن)\n(فحديثي كالدر فصل بالياقوت ... يجري في جيد ظبي أغن)\nأمر له بخمسة آلاف درهم فقال له هذا شيء تطوعت به فأين موضع حكمي فقال مثلها فانصرف بعشرة آلاف درهم أخبرني عمي قال حدثني محمد بن الحسن بن مسعود قال حدثني علي بن عمرو قال مر التيمي بالحيرة على خمار كان يألفه وقد أسن التيمي وأرعش وترك النبيذ فقال له الخمار ويحك أبلغ بك الأمر إلى ما أرى فقال نعم والله لولا ذلك لأكثرت عندك ثم أنشأ يقول صوت\n(هل إلى سكرة بناحية الحيرة ... يوما قبل الممات سبيل)\n(وأبو التيحان في كفه القرعة ... والرأس فوقه الإكليل)\n(وعرار كأنه بيذق الشطرنج ... يفتن فيه قال وقيل)\nفي هذه الأبيات لمحمد بن الأشعث رمل بالوسطى عن الهشامي أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل قال كان أبو محمد التيمي يهوى غلاما وكان الغلام يهوى جارية من جواري القيان فكان بها مشغولا عنه وكانت القينة تهوي الغلام أيضا فلا تفارقه فقال التيمي\n(ويلي على أغيد ممكور ... وساحر ليس بمسحور)\n(تؤثره ألحور علينا كما ... نؤثره نحن على الحور)\n(علق من علق فيه هوى ... منتظم الألفة مغمور)\n(وكل من تهواه في أمره ... مقلب صفقة مقمور)\nأخبرني الحسن بن علي قال حدثنا ابن أبي سعد قال حدثني أحمد بن محمد الفارسي قال حدثنا غسان بن عبد الله عن أبي محمد التيمي قال لما أنشدت الأمين قولي فيه\n(خليفة الله خير منتخب ... لخير أم من هاشم وأب)\n(أكرم بعرقين يجريان به ... إلى الإمام المنصور في النسب)\nرب ثم قال للفضل بن الربيع بحياتي أوقر له زورقه دراهم فقال نعم يا سيدي فلما خرجنا طالبته بذلك فقال أمجنون أنت من أين لنا ما يملأ زورقك ثم صالحني على مائة ألف درهم فقبضتها أخبرني حبيب بن نصر المهلبي قال حدثني محمد بن عبد الله","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":5,"spl":"التيمي وإسحاق الموصلي"},
{"id":"b255-7","bab":"الجزء 20","sec":"التيمي وإسحاق الموصلي","page":"ج20 ص66","text":"المدني قال حدثني عبد الله بن أحمد التيمي ابن أخت أبي محمد التيمي الشاعر قال أنشدني خالي لنفسه قوله\n(لا تخضعن لمخلوق على طمع ... فإن ذاك مضر منك بالدين)\n(وارغب إلى الله مما في خزائنه ... فإنما هو بين الكاف والنون)\n(أما ترى كل من ترجو وتأمله ... من الخلائق مسكين ابن مسكين)\nوت\n(ألم تر أنني أفنيت عمري ... بمطلبها ومطلبها عسير)\n(فلما لم أجد سبباإليها ... يقربني وأعيتني الأمور)\n(حججت وقلت قد حجت جنان ... فيجمعني وإياها المسير)\nلشعر لأبي نواس والغناء للزبير بن دحمان رمل بالوسطى من رواية أحمد بن المكي وبذل وغناني محمد بن إبراهيم قريض الجرحي رحمه الله فيه لحنا من خفيف الثقيل فسألته عن صانعه فلم يعرف","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":6,"spl":"التيمي وإسحاق الموصلي"},
{"id":"b255-8","bab":"الجزء 20","sec":"أخبار أبي نواس وجنان خاصة","page":"ج20 ص71","text":"إذا كانت أخباره قد أ فردت خاصة كانت جنان هذه جارية آل عبد الوهاب بن عبد المجيد الثقفي المحدث الذي كان ابن مناذر يصحب ابنه عبد المجيد ورثاه بعد وفاته وقد مضت أخبارهما وكانت حلوة جميلة المنظر أديبة ويقال إن أبا نواس لم يصدق في حبه امرأة غيرها أخبرني محمد بن خلف بن المرزبان قال حدثني إسحاق بن محمد عن أبي هفان عن أصحاب أبي نواس قالوا كانت جنان جارية حسناء أديبة عاقلة ظريفة تعرف الأخبار وتروي\nالأشعار قال اليؤيؤ خاصة وكانت لبعض الثقفيين بالبصرة فرآها أبو نواس فاستحلاها وقال فيها أشعارا كثيرة فقلت له يوما إن جنان قد عزمت على الحج فكان هذا سبب حجه وقال أما والله لا يفوتني المسير معها والحج عامي هذا إن أقامت على عزيمتها فظننته عابثا مازحا فسبقها والله إلى الخروج بعد أن علم أنها خارجة وما كان نوى الحج ولا أحدث عزمه له إلا خروجها وقال وقد حج وعاد\n(ألم تر أنني أفنيت عمري ... بمطلبها ومطلبها عسير)\n(فلما لم أجد سببا إليها ... يقربني وأعيتني الأمور)\n(حججت وقلت قد حجت جنان ... فيجمعني وأياها المسير)\nال اليؤيؤ فحدثني من شهده لما حج مع جنان وقد أحرم فلما جنه الليل جعل يلبي بشعر ويحدو به ويطرب فغنى به كل من سمعه وهو قوله\n(إلهنا ما أعد لك ... مليك كل من ملك)\n(لبيك قد لبيت لك ... لبيك إن الحمد لك)\n(والملك لا شريك لك ... والليل لما أن حلك)\n(والسابحات في الفلك ... على مجاري المنسلك)\n(ما خاب عبد أملك ... أنت له حيث سلك)\n(لولاك يا رب هلك ... كل نبي وملك)\n(وكل من أهل لك ... سبح أو لبى فلك)\n(يا مخطئا ما أغفلك ... عجل وبادر أجلك)\n(واختم بخير عملك ... لبيك إن الملك لك)\n(والحمد والنعمة لك ... والعز لاشريك لك)\nأخبرني أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري\nقالا حدثنا عمر بن شبة قال كانت جنان التي يذكرها أبو نواس جارية لآل عبد الوهاب بن عبد المجيد الثقفي وفيها يقول\n(جفن عيني قد كاد يسقط ... من طول ما اختلج)\n(وفؤادي من حرء حبك ... والهجر قد نضج)\n(خبريني فدتك نفسي ... وأهلي متى الفرج)\n(كان ميعادنا خروج ... زياد فقد خرج)\n(أنت من قتل عائذ ... بك في أضيق الحرج)\nأخبرني أحمد بن عبيد الله بن عمار قال حدثني إسحاق بن محمد النخعي قال حدثني الجماز قال ابن عمار وحدثني به قليب بن عيسى قال كانت جنان قد شهدت عرسا في جوار أبي نواس فانصرفت منه وهو جالس معنا فرآها فأنشدنا بديها قوله\n(شهدت جلوة العروس جنان ... فاستمالت بحسنها النظارة)\n(حسبوها العروس حين رأوها ... فإليها دون العروس الإشارة)\n(قال أهل العروس حين رأوها ... ما دهانا بها سواك عمارة)\nال وعمارة زوج عبد الرحمن الثقفي وهي مولاة جنان\nأخبرني محمد بن يحيي الصولي ومحمد بن خلف قالا حدثنا يزيد بن محمد المهلبي عن محمد بن عمر قال غضبت جنان من كلام كلمها به أبو نواس فأرسل يعتذر إليها فقالت للرسول قل له لا برح الهجران ربعك ولا بلغت أملك من أحبتك فرجع إليه فسأله عن جوابها فلم يخبره فقال\n(فديتك فيم عتبك من كلام ... نطقت به على وجه جميل)\n(وقولك للرسول عليك غيري ... فليس إلى التواصل من سبيل)\n(فقد جاء الرسول له انكسار ... وحال ما عليها من قبول)\n(ولو ردت جنان مرد خير ... تبين ذاك في وجه الرسول)\nال أبو خالد يزيد بن محمد وكان أبو نواس صادقا في محبته جنان من بين من كان ينسب به من النساء ويداعبه ورأيت أصحابنا جميعا يصححون ذاك عنه وكان لها محبا ولم تكن تحبه فمما عاتبها به حتى استمالها بصحة حبه لها فصارت تحبه بعد نبوها عنه قوله\n(جنان إن جدت يا مناي بما ... آمل لم تقطر السماء دما)\n(وإن تمادي ولا تماديت في ... منعك أصبح بقفرة رمما)\n(علقت من لو أتى على أنفس الماضيين ... والغابرين ما ندما)\n(لو نظرت عينه إلى حجر ... ولد فيه فتورها سقما)","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":7,"spl":"أخبار أبي نواس وجنان خاصة"},
{"id":"b255-9","bab":"الجزء 20","sec":"أخبار أبي نواس وجنان خاصة","page":"ج20 ص71","text":"أخبرني محمد بن جعفر النحوي صهر المبرد قال حدثني محمد بن القاسم عن أبي هفان عن الجماز و أخبرني محمد بن يحيى الصولي قال حدثني عون بن محمد قال حدثني الجماز قال كنت عند أبي نواس جالسا إذ مرت بنا امرأة ممن يداخل الثقفيين فسألها عن جنان وألحف في المسألة واستقصى فأخبرته خبرها وقالت قد سمعتها تقول لصاحبة لها من غير أن تعلم أني أسمع ويحك قد آذاني هذا الفتى وأبرسني وأحرج صدري وضيق علي الطرق بحدة نظره وتهتكه فقد لهج قلبي بذكره والفكر فيه من كثرة فعله لذلك حتى رحمته ثم التفتت فأمسكت عن الكلام فسر أبو نواس بذلك فلما قامت المرأة أنشأ يقول\n(يا ذا الذي عن جنان ظل يخبرنا ... بالله قل وأعد يا طيب الخبر)\n(قال اشتكتك وقالت ما ابتليت به ... أراه من حيثما أقبلت في أثري)\n(ويعمل الطرف نحوي إن مررت به ... حتى ليخجلني من حدة النظر)\n(وإن وقفت له كيما يكلمني ... في الموضع الخلو لم ينطق من الحصر)\n(ما زال يفعل بي هذا ويدمنه ... حتى لقد صار من همي ومن وطري)\nخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي وأحمد بن سليمان بن أبي شيخ قالا قال ابن عائشة وأخبرني الحسن بن علي وابن عمار عن الغلابي عن ابن عائشة قال ابن عمار وحدثت به عن\nالجماز وذكره لي محمد بن داود الجراح عن إسحاق النخعي عن أحمد بن عمير أن محمد بن حفص بن عمر التميمي وهو أبو ابن عائشة انصرف من المسجد وهو يتولى القضاء فرأى أبا نواس قد خلا بأمرأة يكلمها وقال أحمد بن عمير في خبره وكانت المرأة قد جاءته برسالة جنان جارية عمارة امرأة عبد الوهاب بن عبد المجيد فمر به عمر بن عثمان التيمي وهو قاضي البصرة هكذا ذكر أحمد بن عمير وحده وذكر الباقون جميعا أنه محمد بن حفص قال الجماز وكانت عليه ثياب بياض وعلى رأسه قلنسوة مضربة فقال له اتق الله قال إنها حرمتي قال فصنها عن هذا الموضع وانصرف عنه فكتب إليه أبو نواس صوت\n(إن التي أبصرتها ... بكرا أكلمها رسول)\n(أدت إلي رسالة ... كادت لها نفسي تسيل)\n(من ساحر العينين يجذب ... خصره ردف ثقيل)\n(متقلد قوس الصبا ... يرمي وليس له رسيل)\n(فلو أن أذنك بيننا ... حتى تسمع ما تقول)\n(لرأيت ما استقبحت من ... أمري هو الأمر الجميل)\nي هذه الأبيات لحنان من الرمل و خفيفه كلاهما لأبي العبيس بن حمدون\nقال ابن عمير ثم وجه بها فألقيت في الرقاع بين يدي القاضي فلما رآها ضحك وقال إن كانت رسولا فلا بأس وقال ابن عائشة في خبره فجاءني برقعة فيها هذه الأبيات وقال لي ادفعها إلى أبيك فأوصلتها إليه ووضعتها بي يديه فلما قرأها ضحك وقال قل له إني لا أتعرض للشعراء حدثني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال كان أبو عثمان أخا مولى جنان وكان مولاها أبو مية زوج عمارة وهي مولاتها وكانت له بحكمان ضيعة كان ينزلها وهو ابن عم له يقال له أبو مية فقال أبو نواس فيه قوله\n(أسأل القادمين من حكمان ... كيف خلفتما أبا عثمان)\n(وأبا مية المهذب والماجد ... والمرتجى لريب الزمان)\n(فيقولان لي جنان كما سرك ... في حالها فسل عن جنان)\n(ما لهم لا يبارك الله فيهم ... كيف لم يغن عندهم كتماني)","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":8,"spl":"أخبار أبي نواس وجنان خاصة"},
{"id":"b255-10","bab":"الجزء 20","sec":"لم تكن جنان في موضع عشق","page":"ج20 ص77","text":"فأخبرني ابن عمار قال حدثني محمد بن القاسم بن مهرويه قال حدثني محمد بن عبد الملك بن مروان الكاتب قالا كنت جالسا بسر من رأى في شارع أبي احمد فأنشدني قول أبي نواس\n(أسأل المقبلين من حكمان ... كيف خلفتما أبا عثمان)\nإلى جانبي شيخ جالس فضحك فقلت له لقد ضحكت من أمر فقال أجل أنا أبو عثمان الذي قال أبو نواس فيه هذا الشعر وأبو مية ابن عمي وجنان جارية أخي ولم تكن في موضع عشق ولا كان مذهب أبي نواس النساء ولكنه عبث خرج منه أخبرني علي بن سليمان قال قال لي أبو العباس محمد بن يزيد قال النابغة الجعدي\n(أكني بغير اسمها وقد علم الله ... خفيات كل مكتتم)\nهو سبق الناس إلى هذا المعنى وأخذوه جميعا منه وأحسن من أخذه أبو نواس حيث يقول\n(أسأل المقبلين من حكمان ... كيف خلفتما أبا عثمان)\n(فيقولان لي جنان كما سرك ... في حالها فسل عن جنان)\n(مالهم لا يبارك الله فيهم ... كيف لم يغن عندهم كتماني)\nخبرني أحمد بن عبيد الله بن عمار قال أنشدني أحمد بن محمد بن صدقة الأنباري لأبي نواس يذكر مأتما بالبصرة وحضرته جنان\n(يا منسي المأتم أشجانه ... لما أتاهم في المعزينا)\n(سرت قناع الوشي عن صورة ... ألبسها الله التحاسينا)\n(فاستفتنتهن بتمثالها ... فهن للتكليف يبكينا)\n(حق لذلك الوجه أن يزدهي ... عن حزنه من كان محزونا)\nخبرني عمي قال حدثني إسحاق بن محمد النخعي قال حدثنا عبد الملك بن عمر بن أبان النخعي وكان صديقا لأبي نواس أن أبا نواس أشرف من دار على منزل عبد الوهاب الثقفي وقد مات بعض أهله وعندهم مأتم وجنان واقفة مع النساء تلطم وجهها وفي يدها خضاب فقال\n(يا قمرا أرزه مأتم ... يندب شجوا بين أتراب)\n(يبكي فيذري الدر من عينه ... ويلطم الورد بعناب)\n(لا تبك ميتا حل في حفرة ... وابك قتيلا لك بالباب)\n(أبرزه المأتم لي كارها ... برغم دايات وحجاب)\n(لا زال موتا دأب أحبابه ... ولا تزل رؤيته دابي)\nحدثني أحمد بن عبيد الله بن عمار قال حدثني محمد بن القاسم حدثني محمد بن عائشة قال قال لي سفيان بن عيينة لقد أحسن بصريكم هذا أبو نواس حيث يقول وشدد الواو وفتح النون\n(يا قمرا أبصرت في مأتم ... يندب شجوا بين أتراب)\n(يبكي فيذري الدر من عينه ... ويلطم الورد بعناب)\nقال وجعل يعجب من قوله ويلطم الورد بعناب وأخبرني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن محمد قال حدثني حسين بن الضحاك قال أنشد ابن عيينة قول أبي نواس\n(يبكي فيذري الدر من طرفه ... ويلطم الورد بعناب)\nعجبت منه وقال آمنت بالذي خلقه وقد قيل إن أبا نواس قال هذا الشعر في غير جنان أخبرني بذلك الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني بعض الصيارف بالكرخ وسماه قال كان حارس درب عون يقال له المبارك وكان يلبس ثيابا نظيفة سرية ويركب حمارا فيطوف عليه السوق بالليل ويكريه بالنهار فإذا رآه من لا يعرفه ظن أنه من بعض التجار وكان يصل إليه في كل شهر من السوق ما يسعه ويفضل عنه وكانت له بنت من أجمل النساء فمات مبارك وحضره الناس فلما أخرجت جنازته خرجت بنته هذه حاسرة بين يديه فقال أبو نواس فيها\n(يا قمرا أبززه مأتم ... يندب شجوا بين أتراب)\nذكر الأبيات كلها أخبرني محمد بن جعفر قال حدثني أحمد بن القاسم عن أبي هفان\nعن الجماز واليؤيؤ وأصحاب أبي نواس أن جنان وجهت إليه قد شهرتني فاقطع زيارتك عني أياما لينقطع بعض القالة ففعل وكتب إليها\n(إنا أهتجرنا للناس إذ فطنوا ... وبيننا حين نلتقي حسن)\n(ندافع الأمر وهو مقتبل ... فشب حتى عليه قد مرنوا)\n(فليس يقذي عينا معاينة ... له وما إن لمجه أذن)\n(ويح ثقيف ماذا يضرهم ... أن كان لي في ديارهم سكن)\n(أريب ما بيننا الحديث فإن ... زدنا فزيدوا وما لذا ثمن)\nأخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني ابن أبي سعد قال بلغني أن أبا نواس كتب إلى جنان من بغداد\n(كفى حزنا ألا أرى وجه حيلة ... أزور بها الأحباب في حكمان)\n(وأقسم لولا أن تنال معاشر ... جنانا بما لا أشتهي لجنان)\n(لأصبحت منها داني الدار لاصقا ... ولكن ما أخشى فديت عداني)\n(فواحزنا حزنا يؤدي إلى الردى ... فأصبح مأثورا بكل لسان)\n(أراني انقصت أيام وصلي منكم ... وآذن فيكم بالوداع زماني)","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":9,"spl":"لم تكن جنان في موضع عشق"},
{"id":"b255-11","bab":"الجزء 20","sec":"لم تكن جنان في موضع عشق","page":"ج20 ص77","text":"خبرني الحسن قال حدثنا ابن مهرويه عن يحيى بن محمد عن الخزيمي قال بلغ أبا نواس أن امرأة ذكرت لجنان عشقه لها فشتمته جنان وتنقصته وذكرته أقبح الذكر فقال\n(وابأبي من إذا ذكرت له ... وطول وجدي به تنقصني)\n(لو سألوه عن وجه حجته ... في سبه لي لقال يعشقني)\n(نعم إلى الحشر والتناد نعم ... أعشقه أو ألف في كفني)\n(أصيح جهرا لا أستسربه ... عنفني)\n(يا معشر الناس فاسمعوه وعوا ... أن جنانا صديقة الحسن)\nبلغها ذلك فهجرته وأطالت هجره فرآها ليلة في منامه وأنها قد صالحته فكتب إليها\n(إذا التقى في النوم طيفانا ... عاد لنا الوصل كما كانا)\n(يا قرة العين فما بالنا ... نشقى ويلتذخيالانا)\n(لو شئت إذ أحسنت لي في الكرى ... أتممت إحسانك يقطانا)\n(يا عاشقين اصطلحا في الكرى ... وأصبحا غضبى وغضبانا)\n(كذلك الأحلام غدارة ... وربما تصدق أحيانا)\nلغناء في هذه الأبيات لابن جامع ثقيل أول بالوسطى عن عمرو وقال الخزيمي ورآها يوما في ديار ثقيف فجبهته بما كره فغضب وهجرها مدة فأرسلت إليه رسولا تصالحه فرده ولم يصالحها ورآها في النوم تطلب صلحه فقال\n(دست له طيفها كيما تصالحه ... في النوم حين تأبى الصلح يقظانا)\n(فلم يجد عند طيفي طيفها فرجا ... ولا رثى لتشكيه ولا لانا)\n(حسبت أن خيالي لا يكون لما ... أكون من أجله غضبان غضبانا)\n(جنان لا تسأليني الصلح سرعة ذا ... فلم يكن هينا منك الذي كانا)\nأنشدني علي بن سليمان الأخفش لأبي نواس في جنان\n(أما يفنى حديثك عن جنان ... ولا تبقي على هذا اللسان)\n(أكل الدهر قلت لها وقالت ... فكم هذا أما هذا بفان)\n(جعلت الناس كلهم سواء ... إذا حدثت عنها في البيان)\n(عدوك كالصديق وذا كهذا ... سواء والأباعد كالأداني)\n(إذا حدثت عن شأن توالت ... عجائبه أتيتهم بشان)\n(فلو موهت عنها باسم أخرى ... علمنا إذ كنيت من أنت عان)\nخبرني الحسن بن علي قال حدثني يحي بن محمد السلمي قال جدثني أبو عكرمة الضبي أن رجلا قدم البصرة فاشترى جنان من مواليها ورحل بها فقال أبو نواس في ذلك\n(أما الديار فقلما لبثوا بها ... بين استياق العيس والركبان)\n(وضعوا سياط السوق في أعناقها ... حتى اطلعن بهم على الأوطان)\nخبرني عيسى بن الحسين الوراق قال حدثني محمد بن سعد الكراني قال حدثني أبو عثمان الأشنانداني قال كتب أبو نواس إلى جنان\n(أكثري المحو في كتابك وامحيه ... إذا محوته باللسان)\n(وأمري بالمحاء بين ثناياك ... العذاب المفلجات الحسان)\n(إنني كلما مررت بسطر ... فيه محو لطعته بلساني)\n(تلك تقبيلة لكم من بعيد ... أهديت لي وما برحت مكاني)\nصوت\n(تجنى علينا آل مكتوبة الذنبا ... وكانوا لنا سلما فأضحوا لنا حربا)\n(يقولون عز القلب بعد ذهابه ... فقلت ألا طوباي لو أن لي قلبا)\nروضه من الطويل الشعر لابن أبي عيينة والغناء لسليمان أخي جحظة رمل بالوسطى عن عمرو بن بانة","topic":"أخبار التيمي ونسبه","topicNo":255,"sp":10,"spl":"لم تكن جنان في موضع عشق"},
{"id":"b256-1","bab":"الجزء 20","sec":"نسب ابن أبي عيينة وأخباره","page":"ج20 ص85","text":"أبو عيينة فيما أخبرنا به علي بن سليمان الأخفش عن محمد بن يزيد اسمه وكنيته أبو المنهال قال وكل من يدعى ابا عيينة من آل المهلب فأبو عيينة اسمه وكنيته أبو المنهال وكل من يدعى أبارهم من بني سدوس فكنيته أبو محمد وابن أبي عيينة هو محمد بن أبي عيينة بن المهلب بن أبي صفرة وقال أبو خالد الأسلمي هو أبو عيينة بن المنجاب بن أبي عيينة وهو الذي كان يهجو ابن عمه خالدا واسم أبي صفرة ظالم بن سراق وقيل غالب بن إسراق بن صبح بن كندي بن عمرو بن عدي بن وائل بن الحارث بن العتيك بن الأسد بن عمران بن الوضاح بن عمرو بن مزيقياء بن حارثة الغطريف بن امرىء القيس البطريق بن ثعلبة البهلول بن مازن زاد الراكب بن الأزد هذا النسب الذي عليه آل المهلب وذكر غيرهم أن أصلهم من عجم عمان وأنهم تولوا الأزد فلما سار المهلب وشرف وعلا ذكره استلحقوه\nوممن ذكر ذلك الهيثم بن عدي وأبو عبيدة وابن مزروع وابن الكلبي وسائر من جمع كتابا في المثالب وهجتهم به الشعراء فأكثرت أخبرني محمد بن عمران الصيرفي قال أخبرني الحسن بن عليل العنزي قال حدثني أبو عبد الله أحمد بن محمد بن حميد بن سليمان العدوي قال أخبرني الهيثم بن عدي عن عبد الله بن عياش الهمذاني قال وفد ابن الجلندى في الأزد أزد عمان ومواليهم وأحلافهم فكان فيمن وفد منهم أبو صفرة وكان يلقب بذلك لأنه كان يصفر لحيته فدخل على عمر مع ابن الجلندي ولحيته مخضوبة مصفرة فقال عمر لابن الجلندي أكل من معك عربي قال لا فينا العربي وفينا غير ذلك فالتفت عمر رحمه الله إلى أبي صفرة فقال له أعربي أنت قال لا أنا ممن من الله عليه بالإسلام قال وقدم الحكم بن أبي العاص الثقفي أخو عثمان بأعلاج من شهرك في خلافة عمر قد أسلموا فأمر عمر عثمان بن أبي العاص\nأن يختنهم وقد كان أبو صفرة حاضرا فقال ما لهؤلاء يطهرون ليصلوا قال إنهم يختنون قال إنا والله هكذا مثلهم قال فسمع ذلك عثمان بن أبي العاص فأمر بأبي صفرة فأجلس على جفنة فختن وإنه لشيخ أشمط فكان بها من قال لسنا نشك في أن زوجته كذلك فأحضرت وهي عجوز أدماء فأمر بها القابلة فنظرت إليها وكشفتها وإذا هي غير مختونة وذلك منها قد أحشف فأمر بها فخفضت وقال في ذلك زياد الأعجم وقد غضب على المهلب\n(نحن قطعنا من أبي صفرة ... قلفته كي يدخل البصره)\n(لما رأى عثمان غر موله ... أتن على قلفته الشفره)\nليس هذا من الأقوال المعول عليها لأن أصل المثالب زياد لعنه الله فإنه لما ادعي إلى أبي سفيان وعلم أن العرب لا تقر له بذلك مع علمها بنسبه ومع سوء آثاره فيهم عمل كتاب المثالب فألصق بالعرب كلها كل عيب وعار وحق وباطل ثم بنى على ذلك الهيثم بن عدي وكان دعيا فأراد أن يعر أهل البيوتات تشفيا منهم وفعل ذلك أبو عبيدة معمر بن\nالمثنى وكان أصله يهوديا أسلم جده على يدي بعض آل أبي بكر الصديق رضي الله عنه فانتمى إلى ولاء بني تيم فجدد كتاب زياد وزاد فيه ثم نشأ غيلان الشعوبي لعنه الله وكان زنديقا ثنويا لا يشك فيه عرف في حياته بعض مذهبه وكان يورى عنه في عوراته للإسلام بالتشعب والعصبية ثم انكشف أمره بعد وفاته فأبدع كتابا عمله لطاهر بن الحسين وكان شديد التشعب والعصبية خارجا عن الإسلام بأفاعيله فبدأ فيه بمثالب بني هاشم وذكر مناكحهم وأمهاتهم وصنائعهم وبدأ منهم بالطيب الطاهر رسول الله وذكره ثم والى بين أهل بيته الأذكياء النجباء عليهم السلام ثم ببطون قريش على الولاء ثم بسائر العرب فألصق بهم كل كذب وزور ووضع عليهم كل خبر باطل وأعطاه طاهر على ذلك مائتي ألف درهم فيما بلغني وإنما جر هذا القول ذكر المهلب وما قيل فيه وأني ذكرته فلم أجد بدا من ذكر ما روي فيه وفيما مر على أهل النسب ثم قلت ما عندي","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":0,"spl":"نسب ابن أبي عيينة وأخباره — عبد الملك يأمر بإحراق كتاب المثالب"},
{"id":"b256-2","bab":"الجزء 20","sec":"عبد الملك يأمر بإحراق كتاب المثالب","page":"ج20 ص88","text":"أخبرني حبيب بن نصر قال أخبرني عمر بن شبة قال حدثني\nمحمد بن يحيي أبو عثمان عن أبيه قال دخل بعض الناس على عبد الملك بن مروان فقال له هل عندك كتاب زياد في المثالب فتلكأ فقال له لا بأس عليك وبحقي إلا جئتني به فمضى فجاء به فقال له اقرأ علي فقرأه وجعل عبد الملك يتغيظ ويعجب مما فيه من الأباطيل ثم تمثل قول الشاعر\n(وأجرأ من رأيت بظهر غيب ... على عيب الرجال أولو العيوب)\nم أمر بالكتاب فأحرق","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":0,"spl":"نسب ابن أبي عيينة وأخباره — عبد الملك يأمر بإحراق كتاب المثالب"},
{"id":"b256-3","bab":"الجزء 20","sec":"رجع الخبر إلى سياقه أخبار ابن أبي عيينة","page":"ج20 ص89","text":"وهو شاعر مطبوع ظريف غزل هجاء وأنفد أكثر أشعاره في هجاء ابن عمه خالد وأخبارهما تذكر على أثر هذا الكلام وما يصلح تصدير أخباره به وكان من شعراء الدولة العباسية من ساكني البصرة حدثني عمي والصولي قالا حدثنا أحمد بن يزيد المهلبي قال حدثني أبي قال أبو عيينة اسمه كنيته وهو ابن محمد بن أبي عيينة بن المهلب بن أبي صفرة وأخبرني محمد بن عمران الصيرفي قال حدثني العنزي قال حدثني أبو خالد الأسلمي قال أبو عيينة الشاعر هو أبو عيينة بن المنجاب بن أبي عيينة بن المهلب وكان محمد بن أبي عيينة أبو أبي عيينة الشاعر يتولى الري لأبي جعفر المنصور ثم قبض عليه وحبسه وغرمه\nوأخبرني محمد بن خلف بن المرزبان قال حدثني يزيد بن محمد المهلبي قال قال وهب بن جرير رأيت في منامي كأن قائلا يقول لي\n(ما يلقى أبو حرب ... تعالى الله من كرب)\nفلم ألبث أن أخذ المنصور أبا حرب محمد بن أبي عيينة المهلبي فحبسه وكان ولاه الري فأقام بها سنين أخبرني عيسى بن الحسين الوراق ومحمد بن يحيي الصولي وعمي قالوا حدثنا الحزنبل الأصبهاني قال حدثني الفيض بن مخلد مولى أبي عيينة بن المهلب قال كان أبو عيينة بن محمد بن أبي عيينة يهوى فاطمة بنت عمر بن حفص الملقب هزار مرد وكانت امرأة نبيلة شريفة وكان يخاف أهلها أن يذكرها تصريحا ويرهب زوجها عيسى بن سليمان فكان يقول الشعر في جارية لها يقال لها دنيا وكانت قيمة دارها ووالية أمورها كلها وأنشدنا لابن أبي عيينة فيها ويكني باسم دنيا هذه\n(ما لقلبي أرق من كل قلب ... ولحبي أشد من كل حب)\n(ولدنيا على جنوني بدنيا ... أشتهي قربها وتكره قربي)\n(نزلت بي بلية من هواها ... والبلايا تكون من كل ضرب)\n(قل لدنيا إن لم تجبك لما بي ... رطبة من دموع عيني كتبي)\n(فعلام انتهرت بالله رسلي ... وتهددتهم بحبس وضرب)\n(أي ذنب أذنبته ليت شعري ... كان هذا جزاءه أي ذنب)\nخبرني علي بن سليمان قال حدثني محمد بن يزيد قال كان أبو عيينة من أطبع الناس وأقربهم مأخذا من غير أدب موصوف ولا رواية كثيرة وكان يقرب البعيد ويحذف الفضول ويقل التكلف وكان أصغر من أخيه عبد الله ومات قبله وقيل لعبد الله أنت أشعر أم أخوك فقال لو كان له علمي لكان أشعر مني وكان يتعشق فاطمة بنت عمر بن حفص هزار مرد التي تزوجها علي بن سليمان ويسر عشقها ويلقبها دنيا كتمانا لأمرها وكانت امرأة جليلة نبيلة سرية من النساء وكان أبوها من أشد الفرسان وشجعانهم فذكر عيسى بن جعفر أن عيسى بن موسى قال للمهلب بن المغيرة بن المهلب أكان يزيد بن خالد أشجع أم عمر بن حفص هزار مرد فقال المهلب لم أشهد من يزيد ما شهدته من عمر بن حفص وذلك أني رأيته يركض في طلب حمار وحشي حتى إذا حازاه جميع جراميزه وقفز فصار على ظهره فقمص الحمار وجعل عمر بن حفص يحز معرفته إما بسيف وإما بسكين معه حتى قتله قال محمد بن يزيد وحدثت عن محمد بن المهلب أنه أنكر أن يكون\nأبو عيينة يهوى فاطمة وقال إنما كان جنديا في عداد الشطار وكانت فاطمة من أنبل النساء وأسراهن وإنما كان يتعشق جارية لها وهذه الأبيات التي فيها الغناء من قصيدة جيدة مشهورة من شعره يقولها في فاطمة هذه أو جاريتها ويكنى عنها بدنيا فمما اختير منها قوله\n(وقالوا تجنبنا فقلت أبعد ما ... غلبتم عن قلبي بسلطانكم غصبا)\n(غضاب وقد ملوا وقوفي ببابهم ... ولكن دنيا لا ملولا ولا غضبى)\n(وقد أرسلت في السر أني برية ... ولم تر لي فيما ترى منهم ذنبا)\n(وقالت لك العتبى وعندي لك الرضا ... وما إن لهم عندي رضاء ولا عتبى)\n(ونبئتها تلهو إذا اشتد شوقها ... بشعري كما تلهي المغنية الشربا)\n(فأحببتها حبا يقر بعينها ... وحبي أحببت لا يشبه الحبا)\n(فيا حسرتا نغصت قرب ديارها ... فلا زلفة منها أرجي ولا قربا)\n(لقد شمت الأعداء أن حيل بينها ... وبيني ألا للشامتين بنا العقبى)\nمما قاله فيها وغني فيه صوت\n(ضيعت عهد فتى لعهدك حافظ ... في حفظه عجب وفي تضييعك)\n(ونأيت عنه فما له من حيلة ... إلا الوقوف إلى أوان رجوعك)\n(متخشعا يذري عليك دموعه ... أسفا ويعجب من جمود دموعك)\n(إن تقتليه وتذهبي بفؤاده ... فبحسن وجهك لا بحسن صنيعك)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":1,"spl":"رجع الخبر إلى سياقه أخبار ابن أبي عيينة"},
{"id":"b256-4","bab":"الجزء 20","sec":"رجع الخبر إلى سياقه أخبار ابن أبي عيينة","page":"ج20 ص89","text":"روضه من الكامل الغناء في هذه الأبيات من الثقيل الأول بالوسطى ذكر عمرو بن بانة أنه له وذكر الهشامي أنه لمحمد بن الحارث بن بسخنر وذكر عبد الله بن موسى بن محمد بن إبراهيم الإمام أنه لإبراهيم الموصلي فذكر العتابي ومحمد بن الحسن جميعا أن محمد بن أحمد بن يحيي المكي حدثهما قال حدثني عمرو بن بانة قال ركبت يوما إلى دار صالح بن الرشيد فاجتزت بمحمد بن جعفر بن موسى الهادي وكان معاقرا للصبوح فألفيته في ذلك اليوم خاليا منه فسألته عن السبب في تعطيله إياه فقال نيران علي غضبى يعني جارية لبعض النخاسين ببغداد وكانت إحدى المحسنات وكانت بارعة الجمال ظريفة اللسان وكان قد أفرط في حبها حتى عرف به فقلت له فما تحب قال تجعل طريقك على مولاها فإنه يستخرجها إليك فإذا فعل دفعت رقعتي هذه إليها ودفع إلي رقعة فيها\n(ضيعت عهد فتى لعهدك حافظ ... في حفظه عجب وفي تضييعك)\n(إن سمته أن تذهبي بفؤاده ... فبحسن وجهك لا بحسن صنيعك)\nقلت له نعم أنا أتحمل هذه الرسالة وكرامة على ما فيها حفظا لروحك عليك فإني لا آمن أن يتمادى بك هذا الأمر فأخذت الرقعة وجعلت طريقي على منزل النخاس فبعثت إلى الجارية أخرجي فخرجت فدفعت إليها\nالرقعة وأخبرتها بخبري فضحكت ورجعت إلى الموضع الذي أقبلت منه فجلست جلسة خفيفة ثم إذا بها قد وافتني ومعها رقعة فيها صوت\n(وما زلت تعصيني وتغري بي الردى ... وتهجرني حتى مرنت على الهجر)\n(وتقطع أسبابي وتنسى مودتي ... فكيف ترى يا مالكي في الهوى صبري)\n(فأصبحت لا أدري أيأسا تصبري ... على الهجر أم جد البصيرة لا أدري)\nنى في هذه الأبيات عمرو بن بانة ولحنه ثقيل أول بالبنصر و لمقاسة بن ناصح فيها ثقيل آخر بالوسطى لحن عمرو في الأول والثالث بغير نشيد قال فأخذت الرقعة منها وأوصلتها إليه وصرت إلى منزلي فصنعت في بيتي محمد بن جعفر لحنا وفي أبياتها لحنا ثم صرت إلى الأمير صالح بن الرشيد فعرفته ما كان من خبري وغنيته الصوتين فأمر بإسراج دوابه فأسرجت وركب فركبت معه إلى النخاس مولى نيران فما برحنا حتى اشتراها منه بثلاثة آلاف دينار وحملها إلى دار محمد بن جعفر فوهبها له فأقمنا يومنا عنده أخبرنا محمد بن يحيى الصولي قال حدثني يزيد بن محمد المهلبي قال دخلت على الواثق يوما وهو خليفة و رباب في حجره جالسة وهي\nصبية وهو يلقي عليها قوله\n(ضيهت عهد فتى لعهدك حافظ ... في حفظه عجب وفي تضييعك)\nهي تغنيه ويردده عليها فما سمعت غناء قط أحسن من غنائهما جميعا وما زال يردده عليها حتى حفظته","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":2,"spl":"رجع الخبر إلى سياقه أخبار ابن أبي عيينة"},
{"id":"b256-5","bab":"الجزء 20","sec":"رجع الخبر إلى حديث أبي عيينة","page":"ج20 ص95","text":"أخبرني علي بن سليمان قال حدثنا محمد بن يزيد قال قال عبد الله بن محمد بن أبي عيينة أخو أبي عيينة في فاطمة التي كان يشبب بها أخوه بنت عمر بن حفص لما تزوجها عيسى بن سليمان بن علي وكان عيسى مبخلا وكانت له محابس يحبس فيها البياح ويبيعه وكانت له ضيعة تعرف بدالية عيسى يبيع منها البقول والرياحين وكان أول من جمع السماد بالبصرة وباعه فقال فيه أبو الشمقمق\n(إذا رزق العباد فإن عيسى ... له رزق من أستاه العباد)\nلما تزوج عيسى فاطمة بنت عمر بن حفص قال عبد الله بن محمد بن أي عيينة في ذلك\n(أفاطم قد زوجت عيسى فأبشري ... لديه بذل عاجل غير آجل)\n(فإنك قد زوجت عن غير خبرة ... فتى من بني العباس ليس بعاقل)\n(فإن قلت من رهط النبي فإنه ... وإن كان حر الأصل عبد الشمائل)\n(وقد قال فيه جعفر ومحمد ... أقاويل حتى قالها كل قائل)\n(وما قلت ما قالا لأنك أختنا ... وفي البيت منا والذرا والكواهل)\n(ولعمري لقد أثبته في نصابه ... بأن صرت منه في محل الحلائل)\n(إذا ما بنو العباس يوما تنازعوا ... عرا المجد واختاروا كرام الخصائل)\n(رأيت أبا العباس يسمو بنفسه ... إلى بيع بياحاته والمباقل)\nال مؤلف هذا الكتاب وكان عبد الله أخو أبي عيينة شاعرا وكان يقدم على أخيه فأخبرني جحظة قال حدثني علي بن يحيى المنجم قال قال إسحاق الموصلي شعر عبد الله بن أبي عيينة أحب إلي من شعر أبيه وأخيه قال وكان عبد الله صديقا لإسحاق قال محمد بن يزيد ومما قاله في فاطمة وصرح بذكر القرابة بينهما وحقق على نفسه أنه يعنيها قوله\n(دعوتك بالقرابة والجوار ... دعاء مصرح بادي السرار)\n(لأني عنك مشغول بنفسي ... ومحترق عليك بغير نار)\n(وأنت توقرين وليس عندي ... على نار الصبابة من وقار)\n(فأنت لأن ما بك دون ما بي ... تدارين العدو ولا أداري)\n(ولو والله تشتاقين شوقي ... جمحت إلى مخالعة العذار)\n(ألا يا وهب فيم فضحت دنيا ... وبحت بسرها بين الجواري)\n(أما والراقصات بكل واد ... غواد نحو مكة أو سواري)\n(لقد فضلتك دنيا في فؤادي ... كفضل يدي اليمين على اليسار)\n(فقولي ما بدا لك أن تقولي ... فإني لا ألومك أن تضاري)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":3,"spl":"رجع الخبر إلى حديث أبي عيينة"},
{"id":"b256-6","bab":"الجزء 20","sec":"نماذج من جيد شعره في فاطمة","page":"ج20 ص97","text":"قال وقال فيها وهو من ظريف أشعاره\n(رق قلبي لك يا نور عيني ... وأبى قلبك لي أن يرقا)\n(فأراك الله موتي فإني ... لست أرضى أن تموتي وأبقى)\n(أنا من وجدبدنياي منها ... ومن العذال فيها ملقى)\nصوت\n(زعموا أني صديق لدنيا ... ليت ذا الباطل قد صار حقا)\nي هذا البيت ثم الذي قبله ثم الأول لإبراهيم لحن ماخوري بالوسطى عن الهشامي قال وقال فيها أيضا في هذا الوزن وفيه غناء محدث رمل طنبوري\n(عيشها حلو وعيشك مر ... ليس مسرور كمن لا يسر)\n(كمد في الحب تسخن فيه ... عينه أكثر مما تقر)\n(قلت للائم فيها اله عنها ... لا يقع بيني وبينك شر)\n(أتراني مقصرا عن هواها ... كل مملوك إذا لي حر)\nقال فيها أيضا وأنشدناه الأخفش عن المبرد وأنشدناه محمد بن العباس اليزيدي قال أنشدني عمي عبيد الله لأبي عيينة\n(حين قالت دنيا علام نهارا ... زرت هلا انتظرت وقت المساء)\n(إن تكن معجبا برأيك لا تفرق ... فاستحي يا قليل الحياء)\n(ذاك إذ روحها وروحي مزاجان ... كأصفى خمر بأعذب ماء)\nال محمد بن يزيد وقد أخذ هذا المعنى غيره منه ولم يسمه وهو البحتري فقال صوت\n(جعلت حبك من قلبي بمنزلة ... هي المصافاة بين الماء والراح)\n(تهتز مثل اهتزاز الغصن حركه ... مرور غيث من الوسمي سحاح)\nلغناء في هذين البيتين لرذاذثقيل أول مطلق في مجرى البنصر ومما قاله أبو عيينة في فاطمة هذه وكنى فيه بدنيا قوله صوت\n(ألم تنه قلبك أن يعشقا ... ومالك والعشق لولا الشقا)\n(أمن بعد شربك كأس النهى ... وشمك ريحان أهل التقى)\n(عشقت فأصبحت في العالمين ... أشهر من فرس أبلغا)\n(أدنياي من غمر بحر الهوى ... خذي بيدي قبل أن أغرقا)\n(أنا ابن المهلب ما مثله ... لو أن الخلد لي مرتقى)\nغنى فيه أبو العبيس بن حمدون ولحنه ثاني ثقيل مطلق وفيه لعريب ثقيل أول رواه أبو العببيس عنها وهذه قصيدة طويلة يذكر فيها دنيا ويفخر بعقب النسيب بأبيه ويذكر مآثر المهلب بالعراق ولكن مما قاله في دنيا منها قوله\n(أدنياي من غمر بحر الهوى ... خذي بيدي قبل أن أغرقا)\n(أنا لك عبد فكوني كمن ... إذا سره بعده أعتقا)\n(ألم أخدع الناس عن وصلها ... وقد يخدع العاقل الأحمقا)\n(بلى فسبقتهم إنني ... أحب إلى الخير أن أسبقا)\n(ويوم الجنازة إذ أرسلت ... على رقعة أن جز الخندقا)\n(وعج ثم فانظر لنا مجلسا ... برفق وإياك أن تخرقا)\n(فجئنا كغصنين من بانة ... قرينين خدنين قد أورقا)\n(فقالت لأخت لها استنشديه ... من شعره المحكم المنتقى)\n(فقلت أمرت بكتمانه ... وحذرت إن شاع أن يسرقا)\n(فقالت بعيشك قولي له ... تمنع لعلك أن تنفقا)\nمن مشهور قوله في دنيا وهو مما تهتك فيه وصرح وأفحش وهي من جيد قوله قصيدته التي يقول فيها\n(أنا الفارغ المشغول والشوق آفتي ... فلا تسألوني عن فراغي وعن شغلي)\n(عجبت لترك الحب دنيا خلية ... وإعراضه عنها وإقباله قبلي)\n(وما بالها لما كتبت تهاونت ... بكتبي وقد أرسلت فانتهزت رسلي)\n(وقد حلفت ألا تخط بكفها ... إلى قابل خطا إلي ولا تملي)\n(أبخلا علينا كل ذا وقطيعة ... قضيت لدينا بالقطيعة والبخل)\n(سلوا قلب دنيا كيف أطلقه الهوى ... فقد كان في غل وثيق وفي كبل)\n(فإن جحدت فاذكر لها قصر معبد ... بمنصف ما بين الأبلة والحبل)\n(وملعبنا في النهر والماء زاخر ... قرينين كالغصنين فرعين في أصل)\n(ومن حولنا الريحان غضا وفوقنا ... ظلال من الكرم المعرش والنخل)\n(إذا شئت مالت بي إليها كأنني ... إلى غصن بان بين دغضين من رمل)\n(ليالي ألقاني الهوى فاستضفتها ... فكانت ثناياها بلا حشمة نزلي)\n(وكم لذة لي في هواها وشهوة ... وركضي إليها راكبا وعلى رجل)\n(وفي مأتم المهدي زاحمت ركنها ... بركني وقد وطنت نفسي على القتل)\n(وبتنا على خوف أسكن قلبها ... بيسراي واليمنى عضلى قائم النصل)\n(فيا طيب طعم العيش إذ هي جارة ... وإذ نفسها نفسي وإذ أهلها أهلي)\n(وإذ هي لا تعتل عني برقبة ... ولا خوف عين من وشاةولا بعل)\n(فقد عفت الأثار بيني وبينها ... وقد أوحشت مني إلى دارها سبلي)\n(ولما بلوت الحب بعد فراقها ... قضيت على أم المحبين بالثكل)\n(وأصبحت معزولا وقد كنت واليا ... وشتان ما بين الولاية والعزل)\nومما قاله فيها وفيه غناء صوت\n(ألا في سبيل الله ما حل بي منك ... وصبرك عني لا صبر لي عنك)\n(وتركك جسمي بعد أخذك مهجتي ... ضئيلا فهلا كان من قبل ذا تركي)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":4,"spl":"نماذج من جيد شعره في فاطمة"},
{"id":"b256-7","bab":"الجزء 20","sec":"نماذج من جيد شعره في فاطمة","page":"ج20 ص97","text":"(فهل حاكم في الحب يحكم بيننا ... فيأخذ لي حقي وينصفني منك)\nسليم في هذه الأبيات هزج مطلق في مجرى الوسطى وفي هذه القصيدة يقول يصف قصرا كانوا فيه وهي من عجيب شعره\n(لقد كنت يوم القصر مما ظننت بي ... بريئا كما أني بريء من الشرك)\n(يذكرني الفردوس طورا فأرعوي ... وطورا يواتيني إلى القصف والفتك)\n(بغرس كأبكار الجواري وتربة ... كأن ثراها ماء ورد على مسك)\n(وسرب من الغزلان يرتعن حوله ... كما استل منظوم من الدر من سلك)\n(وورقاء تحكي الموصلي إذا غدت ... بتغريدها أحبب بها ويمن ولا تحكي)\n(فيا طيب ذاك القصر قصرا ومنزلا ... بأفيح سهل غير وعر ولا ضنك)\n(كأن قصور القوم ينظرن حوله ... إلى ملك موف على منبر الملك)\n(يدل عليها مستطيلا بظله ... فيضحك منها وهي مطرقة تبكي)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":5,"spl":"نماذج من جيد شعره في فاطمة"},
{"id":"b256-8","bab":"الجزء 20","sec":"الفضل بن الربيع إنه أشعر أهل زماننا","page":"ج20 ص102","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن عمرو الأنصاري قال سمعت الأصمعي يذكر أن الفضل بن الربيع قال لجلسائه من أشعر أهل عصرنا فقالوا فأكثروا فقال الفضل بن الربيع أشعر أهل زماننا الذي يقول في قصر عيسى بن جعفر بالخريبة يعني أبا عيينة\n(زر وادي القصر والوادي ... وحبذا أهله من حاضر بادي)\n(ترفا قراقيره والعيس واقفة ... والضب والنون والملاح والحادي)\nخبرني الحسن بن علي قال حدثنا محمد بن مجمع قال تزوج\nسعيد بن عباد بن حبيب بن المهلب بنت سفيان بن معاوية بن المهلب وقد كان تزوجها قبله رجلان فدفنتهما فكتب إليه أبو عيينة\n(رأيت أثاثها فرغبت فيه ... وكم نصبت لغيرك بالأثاث)\n(إلى دار المنون فجهزتهم ... تحثهم بأربعة حثاث)\n(فصير أمرها بيدي أبيها ... وعيشك من حبالك بالثلاث)\n(وإلا فالسلام عليك مني ... سأبدأ من غد لك بالمراثي)\nخبرني محمد بن مزيد الصولي قال حدثنا حماد بن إسحاق عن أبيه قال كان علي بن هشام قد دعاني ودعا أبا عيينة وتأخرت عنه حتى اصطحبنا شديدا وتشاغلت برجل كان عندي من الأعراب وكان فصيحا لأكتب عنه وكان عنده بعض من يعاديني قال حماد كأنه يومئ بهذا القول إلى إبراهيم بن المهدي فسأل ابا عيينة أن يعاتبني بشعر ينسبني فيه إلى الخلف فكتب إلى الخلف فكتب إلى\n(يا مليئا بالوعد والخلف والمطل ... بطيئا عن دعوة الأصحاب)\n(لهجا بالأعراب إن لدينا ... بعض من تشتهي من الأعراب)\n(قد عرفنا الذي شغلت به عنا ... وإن كان غير ما في الكتاب)\nقال فكتبت إلى الذي حمل أبا عيينة على هذا يعني إبراهيم بن المهدي\n(قد فهمت الكتاب أصلحك الله ... وعندي إليك رد الجواب)\n(ولعمري ما تنصفون ولا كان ... الذي جاء منكم في حسابي)\n(لست آتيك فاعلمن ولا لي ... فيك حظ من بعد هذا الكتاب)\nخبرني عيسى بن الحسين الوراقي قال حدثني عبد الله بن أبي سعدقال حدثني إبراهيم بن إسحاق العمري قال حدثنا أبو هاشم الإسكندراني عن ابن أبي لهيعة قال\n(حفر حفر في بعض أفنية مكة فوجد فيه حجر عليه منقوش ... )\n(ما لا يكون فلا يكون بحيلة ... أبدا وما هو كائن فيكون)\n(سيكون ما هو كائن في وقته ... وأخو الجهالة متعب محزون)\n(يسعى القوي فلا ينال بسعيه ... حظا ويحظى عاجز ومهين)\nال ابن أبي سعد هكذا في الحديث وقد أنشدني هذه الأبيات جماعة لأبي عيينة حدثني عمي قال حدثني عمر بن محمد بن عبد الملك قال حدثني علي بن عمروس الأنصاري عن الأصمعي قال قال لي الفضل بن الربيع يا أصمعي من أشعر أهل زمانك فقلت أبو نواس قال حيث يقول ماذا قلت حيث يقول\n(أما ترى الشمس حلت الحملا ... وقام وزن الزمان فاعتدلا)\nقال والله إنه لذهن فطن وأشعر عندي منه أبو عيينة حدثني عمي قال حدثني فضل اليزيدي اليزيد عن إسحاق أنه أنشده لأبي\nعيينة في دنيا التي كان يشبب لها وقد زوجت وبلغه أنها تهدى إلى زوجها وكان إسحاق يستحسن هذا الشعر ويستجيده\n(أرى عهدها كالورد ليس بدائم ... ولا خير فيمن لا يدوم له عهد)\n(وعهدي لها كالآس حسنا وبهجة ... له نضرة تبقى إذا ما انقضى الورد)\n(فما وجد العذري إذ طال وجده ... بعفراء حتى سل مهجته الوجد)\n(كوجدي غداة البين عند التفاتها ... وقد شف عنها دون أترابها البرد)\n(فقلت لأصحابي هي الشمس ضوءها ... قريب ولكن في تناولها بعد)\n(وإني لمن تهدى إليه لحاسد ... جرى طائري نحسا وطائره سعد)\nأخبرني عمي قال حدثني أحمد بن يزيد المهلبي قال سألت أبي عن دنيا التي ذكرها أبو عيينة بن محمد بن أبي عينة في شعره وقلت إن قوما يقولون إنها كانت أمة لبعض مغني البصرة فقال لا يا بني هي فاطمة بنت عمر بن حفص هزار مرد بن عثمان قبيصة أخي المهلب وكان عيسى بن سليمان بن علي أخو جعفر ومحمد ابني سليمان\nتزوجها وهجاه عبد الله بن محمد بن أبي عيينة أخو أبي عيينة فقال\n(أفاطم قد زوجت عيسى فأبشري ... لديه بذل عاجل غير آجل)\n(فإنك قد زوجت عن غير خبرة ... فتى من بني العباس ليس بعاقل)\nذكر باقي الأبيات وقد مضت متقدما قال أحمد بن يزيد ثم أنشدني أبي لأبي عيينة يصرح بنسبه الجامع له ولفاطمة من أبيات له\n(ولأنت إن مت المصابة بي ... فتجنبي قتلي بلا وتر)\n(فلئن هلكت لتلطمن جزعا ... خديك قائمة على قبري)\nال أحمد وأنشدني أبي أيضا في تصديق ذلك وأنه كان يكني بدنيا عن غيرها","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":6,"spl":"الفضل بن الربيع إنه أشعر أهل زماننا","partial":1},
{"id":"b256-9","bab":"الجزء 20","sec":"الفضل بن الربيع إنه أشعر أهل زماننا","page":"ج20 ص102","text":"(ما لدنيا تجفوك والذنب منها ... إن هذا منها لخب ومكر)\n(عرفت ذنبها إلي فقالت ... ابدأوا القوم با لصياح يفروا)\n(قد أمرت الفؤاد بالصبر عنها ... غير أن ليس لي مع الحب أمر)\n(وكتمت اسمها حذارا من الناس ... ومن شرهم وفي الناس شر)\n(ويقولون بح لنا باسم دنيا ... واسم دنيا سر على الناس ذخر)\n(ثم قالوا ليعلموا ذات نفسي ... أعوان دنياك أم هي بكر)\n(فتنفست ثم قلت أبكر ... شب يا إخوتي عن الطوق عمرو)\nأخبرني جعفر بن قدامة قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني أبو خالد الأسلمي قال كان ابن أبي عيينة المهلبي صديقي وهو أبو عيينة بن المنجاب بن أبي عيينة فجاءه رجل من جيرانه كان يستثقله فسأله حاجة فقضاها ثم سأله أخرى فوعده بها ثم سأله ثالثة فقال\n(خفف على إخوانك المؤنا ... إن شئت أن تبقى لهم سكنا)\n(لا تلحفن إذا سألت ففي الإجحاف ... إجحاف بهم وعنا)\nقام الرجل وانصرف","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":7,"spl":"الفضل بن الربيع إنه أشعر أهل زماننا"},
{"id":"b256-10","bab":"الجزء 20","sec":"ابن أبي عيينة وأمير البصرة","page":"ج20 ص107","text":"أخبرني أبو دلف هاشم بن محمد قال حدثني المبرد قال وفد ابن أبي عيينة إلى طاهر بن الحسين يسأله أن يعزل أمير البصرة وكان من قبله فدافعه وعرض عليه عوضا خطيرا من حاجته ووعده أن يستصلح له ذلك الأمير ويزيله عما كرهه فأبى عزله وأجزل صلته فقال ابن أبي عيينة فيه\n(يا ذا اليمينين قد أوقرتني مننا ... تترى هي الغاية القصوى من المنن)\n(ولست أسطيع من شكر أجيء به ... إلا استطاعة ذي روح وذي بدن)\n(لو كنت أعرف فوق الشكر منزلة ... أوفى من الشكر عند الله في الثمن)\n(أخلصتها لك من قلبي مهذبة ... حذوا على مثل ما أوليت من حسن)\nخبرني محمد بن القاسم الأنباري قال حدثني أبي عن أبي عكرمة عامر بن عمران وأخبرني به عمي عن أحمد بن يزيد المهلبي عن أبيه قال كان إسماعيل بن سليمان واليا على البصرة خليفة لطاهر بن الحسين فأساء مجاورة ابن أبي عيينة حتى تباعد بينهما وقبح وأظهر إسماعيل تنقصه وعيبه فخرج إلى طاهر ليشكو إسماعيل ويسعى في عزله عن البصرة فبعد ذلك عليه بعض البعد وسافر طاهر بن الحسين إلى وجه أمر بالخروج إليه فصحبه ابن أبي عيينة في سفره فتذمم من ذلك وأمر بإيصاله إليه فلما دخل ابن أبي عيينة إليه سأله عن حوائجه وأدناه وأمره برفعها فأنشده\n(من أوحشته البلاد لم يقم ... فيها ومن آنسته لم يرم)\n(ومن يبت والهموم قادحة ... في صدره بالزناد لم ينم)\n(ومن ير النقص من مواطئه ... يزل عن النقص موطىء القدم)\n(والقرب ممن ينأى بجانبه ... صدع على الشعب غير ملتئم)\n(ورب أمر يعيا اللبيب به ... يظل منه في حيرة الظلم)\n(صبر عليه كظم على مضض ... وتركه من مواقع الندم)\n(ياذا اليمينين لم أزرك ولم ... آتك من خلة ومن عدم)\n(إني من الله في مراح غنى ... ومغتذى واسع وفي نعم)\n(زارتك بي همة منازعة ... إلى العلا من كرائم اللهمم)\n(وإنني للجميل محتمل ... في القدر من منصبي ومن شيمي)\n(وقد تعلقت منك بالذمم الكبرى ... التي لا تخيب في الذمم)\n(فإن أنل بغيتي فأنت لها ... في الحق حق الرجاء والرحم)\n(وإن يعق عائق فلست على ... جميل رأي عندي بمتهم)\n(في قدر الله ما أحمله ... تعويق أمري في اللوح والقلم)\n(لم يضق الصبر والفجاج على ... حر كريم بالصبر معتصم)\n(ماض كحد السنان في طرف العامل ... أو حد مصلت خذم)\n(إذا ابتلاه الزمان كشفه ... عن ثوب حرية وعن كرم)\n(ما ساء ظني إلا بواحدة ... في الصدر محصورة عن الكلم)\n(ليهن قوم جزت المدى بهم ... ولم تقصر فيهم ولم تلم)\n(وليس كل الدلاء راجعة ... بالنصف من ملئها إلى الوذم)\n(ترجع بالحمأة القليلة أحيانا ... ورنق الصبابة الأمم)\n(ما تنبت الأرض كل زهرتها ... ولا تعم السماء بالديم)\n(ما في نقص عن كل منزلة ... شريفة والأمور بالقسم)\nأجابه طاهر\n(من تستضفه الهموم لم ينم ... إلا كنوم المريض ذي السقم)\n(ولا يزل قلبه يكابد ما ... تولد فيه الهموم من ألم)\n(وقد سمعت الذي هتفت به ... وما بأذني عنك من صمم)\n(وقد علمنا أن لست تصحبنا ... لفاقة فيك لا ولا عدم)\n(إلا لحق وحرمة وعلى ... مثلك رعي الحقوق والحرم)\n(أنت امرؤ لا تزول عن كرم ... إلا إلى مثله من الكرم)\n(وأنت من أسرة جحا جة ... فازوا بحسن الفعال والشيم)\n(فما ترم من جسيم منزلة ... فالحكم فيه إليك فاحتكم)\n(إن كنت مستسقيا سماحتنا ... منا تجدك اليدان بالديم)\n(أو ترم في بحرنا بدلوك لا ... نعدمك ملئا لها إلى الوذم)\n(إنا أناس لنا صنائعنا ... في العرب معروفة وفي العجم)\n(مغتنمو كسب كل محمدة ... والكسب للحمد غير مغتنم)\nاحتكم عليه أبو عيينة في عزل إسماعيل بن جعفر عن البصرة فعزله عنها وأمر له بمائة ألف درهم فقال أبو عيينة في عزله إسماعيل بن جعفر عن إمارة البصرة\n(لا تعدم العزل يا أبا الحسن ... ولا هزالا في دولة السمن)\n(ولا انتقالا من دار عافية ... إلى ديار البلاء والمحن)\n(أنا الذي إن كفرت نعمته ... أذاب ما في جنبيك من عكن)\nحدثني عيسى بن الحسين قال حدثني محمد بن عبد الله الحزنبل الأصبهاني قال كان ابن أبي عيينة قد هجا نزارا بقصيدة له مشهورة وفضل عليها قحطان فقال ابن زعبل يهجوه ويردد عليه واسمه عمرو بن زعبل\n(بني أبي عيينة ما ... نطقت به من اللغط)\n(على ما أنت ملتحف ... من الأوجاع في الوسط)\n(لما في الدبر من نغل ... وما في العرض من سقط)\n(أتتنا الخمس والمائتان ... بالنعماء والغبط)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":8,"spl":"ابن أبي عيينة وأمير البصرة"},
{"id":"b256-11","bab":"الجزء 20","sec":"ابن أبي عيينة وأمير البصرة","page":"ج20 ص107","text":"(أمير من هلال مستطيل ... الباع منبسط)\n(شريف ليس بالمدخول ... في عرض ولا رهط)\n(أظنك من يديه واقعالا ... شك في ورط)\n(ووالي الخرج فياض اليدين ... بنائل سبط)\n(له نعم حباك بها ... فلم تحفظ ولم تحط)\n(وقاض من أمير المؤمنين ... يقوم بالقسط)\n(يسرك أنه من آل ... قحطان على شحط)\n(وأنك إن ذكرت يقال ... شيخ فاسق الشمط)\n(اعبد من عبيد عمان ... عاب مناقب السبط)\n(وتهجو الغر من مضر ... كفى هذا من الشطط)\n(تيمم في مقيرة ... مسيرا غير مغتبط)\n(مجوفة مزينة ... بودع لاح كالرقط)\n(بنوك تجرها بالقلس ... مؤتزرين بالفوط)\n(متى غمسوا مراديهم ... لجد السير تحتلط)\n(وأنت بموضع السكان ... يمسكه بلا غلط)\n(عليك عباءة مشكوكة ... بالشوك لم تخط)\n(فطيب ريح بلدتنا ... فرارك خيفة الشرط)\n(وأنك قد عرفت بكثرة ... التخليط والغلط)\n(ترى الخسران إن لم تزن ... في يوم ولم تلط)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":9,"spl":"ابن أبي عيينة وأمير البصرة"},
{"id":"b256-12","bab":"الجزء 20","sec":"يفر إلى عمان خوفا من المأمون","page":"ج20 ص112","text":"قال وكان ابن أبي عيينة لما هجا نزارا بلغ شعره المأمون فنذر دمه فهرب من البصرة وركب البحر إلى عمان فلم يزل بها متواريا في نواحي الأزد حتى مات المأمون أخبرني أحمد بن عبيد الله بن عمار قال حدثني ابن مهرويه عن أبيه بقصة ابن أبي عيينة مع ابن زعبل فذكر نحو الخبر المتقدم حدثني عمي قال حدثني أحمد بن يزيد المهلبي قال حدثني أبي قال كان ابن عيينة يشبب بوهبه جارية القروي وهي التي يقول فيها فروج الزنى قوله\n(يا وهب لم يبق لي شيء أسر به ... إلا الجلوس فتسقيني وأسقيك)\nثم عدل عن التشبيب بها إلى دنيا وذكرهما جميعا في شعره فقال\n(أرسلت وهبة لما رأتني ... بعد سقم من هواها مفيقا)\n(أتغيرت كأن لم تكن لي ... قبل أن تعرف دنيا صديقا)\n(قد لعمري كان ذاك ولكن ... قطعت دنيا عليك الطريقا)\nخبرني عمي قال حدثني أحمد بن يزيد عن أبيه قال لما ولي عمر بن حفص هزار مرد البصرة قال ابن أبي عيينة في ذلك وفي دنيا يكنى بها عن فاطمة بنت عمر بن حفص صاحبته\n(هنيئا لدنيا هنيئا لها ... قدوم أبيها على البصره)\n(على أنها أظهرت نخوة ... وقالت لي الملك والقدره)\n(فيا نور عيني كذا عاجلا ... علي تطاولت بالإمره)\nال وهذا دليل على أنه كان يكنى عن فاطمة بدنيا لا أنه يهوى جاريتها دنيا قال أحمد بن يزيد وفيها يقول أيضا\n(يا حسنها يوم قالت لي مودعة ... لا تنس ما قلت من فيها إلى أذني)\n(كأنني لم أصل دنيا علانية ... ولم أزر أهل دنيا زورة الختن)\n(جسمي معي غير أن الروح عندكم ... فالروح في وطن والجسم في وطن)\n(فليعجب الناس مني أن لي جسدا ... لا روح فيه ولي روح بلا بدن)\nفي هذه الأبيات هزج طنبوري محدث أخبرني عمي قال حدثني أحمد بن يزيد عن أبيه قال ورد على ابن أبي عيينة كتاب من بعض أهله بأن أخاه داود خرج إليه ببريد فمات بهمذان فقال ابن أبي عيينة عند ذلك يرثيه\n(أنائحة الحمام قفي فنوحي ... على داود رهنا في ضريح)\n(لدى الأجيال من همذان راحت ... به الأيام للموت المريح)\n(لم يشهد جنازته البواكي ... فتبكيه بمنهل سفوح)\n(وكوني مثله إذ كان حيا ... جوادا بالغبوق وبالصبوح)\n(أنائحة الحمام فلا تشحي ... عليه فليس بالرجل الشحيح)\n(ولا بمثمر مالا لدنيا ... ولا فيها بمغمار طموح)\n(يبيع كثير ما فيها بباق ... ثمين من عواقبه ربيح)\n(ومن آل المهلب في لباب ... لباب الخالص المحض الصريح)\n(همو أبناء آخرة ودنيا ... وأهداف المراثي والمديح)\nخبرني عمي قال حدثنا أحمد بن يزيد عن أبيه قال قدم أبو عيينة إلى الكوفة في بعض حوائجه فعاشره جماعة من وجوه أهلها وأقام بها مدة وألف فيها قينة كان يعاشرها وأحبها حبا شديدا فقال فيها\n(لعمري لقد أعطيت بالكوفة المنى ... وفوق المنى بالغانيات النواعم)\n(ونادمت أخت الشمس حسنا فوافقت ... هواي ومثلي مثلها فلينادم)\n(وأنشدتها شعري بدنيا فعر بدت ... وقالت ملول عهده غير دائم)\n(فقلت لها يا ظبية الكوفة اغفري ... فقد تبت مما قلت توبة نادم)\n(فقالت قد استوجبت منا عقوبة ... ولكن سنرعى فيك روح ابن حاتم)\nقال أحمد بن يزيد قال لي أبي\nكان لابن أبي عيينة بستان وضيعة في بعض قطائع المهلب بالبصرة فأوطنها وصيرها منزلة وأقام بها وفيها يقول\n(يا جنة فاقت الجنان فما ... تبلغها قيمة ولا ثمن)\n(ألفتها فاتخذتها وطنا ... إن فؤادي لأهلها وطن)\n(زوج حيتانها الضباب بها ... فهذه كنة وذا ختن)\n(فانظر وفكر فيما نطقت به ... إن الأريب المفكر الفطن)\n(من سفن كالنعام مقبلة ... ومن نعام كأنها سفن)\nخبرني عيسى بن الحسين قال حدثنا الزبير بن بكار قال حدثنا إسحاق بن إبراهيم الموصلي أن أبا عيينة أنشده لنفسه صوت\n(لا يكن منك ما بدا لي بعينيك ... من اللحظ حيلة واختداعا)\n(إن يكن في الفؤاد شيء وإلا ... فدعيني لا تقتليني ضياعا)\n(فلعلي إذا قربت تباعدت ... وأظهرت جفوة وامتناعا)\n(حين نفسي لا تستطيع لما قد ... وقعت فيه من هواها ارتجاعا)\nي هذه الأبيات رمل مطلق محدث أخبرني عمي قال حدثني أحمد بن يزيد قال حدثني أبي قال كان عبد الله بن محمد بن أبي عيينة أخو أبي عيينة شاعرا وهو القائل يعاتب محمد بن يحيى بن خالد البرمكي بأبيات رائية أولها\n(اسلم وإن كان فيك عني ... قبض لكفيك وازورار)\n(تلحظني عابسا قطوبا ... كأنما بي إليك ثار)\n(لو كان أمر عتبت فيه ... يجوز منه لي اعتذار)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":10,"spl":"يفر إلى عمان خوفا من المأمون"},
{"id":"b256-13","bab":"الجزء 20","sec":"يفر إلى عمان خوفا من المأمون","page":"ج20 ص112","text":"(أو كنت سآلة حريصا ... لحان مني لك الفرار)\n(أو كنت نذلا عديم عقل ... لا منصب لي ولا نجار)\n(أو لم أكن حاملا بنفسي ... ما تحمل الأنفس الكبار)\n(وأنني من خيار قومي ... وكل أهلي فتى خيار)\n(عذرت إن نالني جفاء ... منك وإن نالني ضرار)\n(لكن ذنبي إليك أني ... قحطان لي الجد لا نزار)\n(عليك مني السلام هذا ... أوان ينأى بي المزار)\n(ما كنت إلا كلحم ميت ... دعا إلى أكله اضطرار)\n(راحت على الناس لابن يحيى ... محمد ديمة غزار)\n(ولم يكن ما أنلت منه ... بقدر ما ينجلي الغبار)\n(قد أصبح الناس في زمان ... أعلامه السفلة الشرار)\n(يستأخر السابق المذكى ... فيه ويستقدم الحمار)\n(وليس للمرء ما تمنى ... يوما وما إن له اختيار)\n(ما قدر الله فهو آت ... وفي مقاديره الخيار)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":11,"spl":"يفر إلى عمان خوفا من المأمون — يهجو قبيصة بن روح المهلبي"},
{"id":"b256-14","bab":"الجزء 20","sec":"يهجو قبيصة بن روح المهلبي","page":"ج20 ص116","text":"أخبرني عمي قال حدثنا أبو هفان قال كان ابن أبي عيينة قد قصد ربيعة بن قبيصة بن روح بن حاتم المهلبي واستماحه فلم يجد عنده ما قدر فيه فانصرف مغاضبا فوجه إليه داود بن مزيد بن حاتم بن قبيصة فترضاه وبلغ ما أحبه ورضيه من بره ومعونته فقال يمدحه ويهجو قبيصة\n(أقبيص لست وإن جهدت بمدرك ... سعي ابن عمك ذي العلا داود)\n(شتان بينك يا قبيص وبينه ... إن المذمم ليس كالمحمود)\n(اختار داود بناء محامد ... واخترت أكل شبارق وثريد)\n(قد كان مجد أبيك لو أحببته ... روح أبي خلف كمجد يزيد)\n(لكن جرى داود جري مبرز ... فحوى المدى وجريت جري بليد)\n(داود محمود وأنت مذمم ... عجبا لذاك وانتما من عود)\n(ولرب عود قد يشق لمسجد ... نصفا وسائره لحش يهود)\n(فالحش أنت له وذاك لمسجد ... كم بين موضع مسلح وسجود)\n(هذا جزاؤك يا قبيص لأنه ... جادت يداه وأنت قفل حديد)\nدثني جعفر بن قدامة قال حدثنا حماد بن إسحاق حدثني أبي قال كانت لأبي حذيفة مولى جعفر بن سليمان جارية مغنية يقال لها بستان فبلغه أن أبا عيينة بن محمد بن عيينة ذكر لبعض إخوانه محبته لها ولاستماع غنائها فدعاه وسأله أن يطرح الحشمة بينه وبينه فأجابه إلى ذلك وقال لما سكر وانصرف من عنده في ذلك\n(ألم ترني على كسلي وفتري ... أجبت أبا حذيفة إذ دعاني)\n(وكنت إذا دعيت إلى سماع ... أجبت ولم يكن مني تواني)\n(كأنا من بشاشتنا ظللنا ... بيوم ليس من هذا الزمان)\nأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني محمد بن عثمان قال كانت لعيسى بن موسى ضيعة إلى جانب ضيعة ابن أبي عيينة بالبصرة وكان له إلى جانب ضيعته سماد كثير فسأله أن يعطيه بعضه ليعمر ابن أبي عيينة به ضيعته فلم يفعل فقال فيه\n(رأيت الناس همهم المعالي ... وعيسى همه جمع السماد)\n(ورزق العالمين بكف ربي ... وعيسى رزقه في أست العباد)\nكذا ذكره ابن مهرويه وهذا بيت فاسد وإنما هو\n(إذا رزق العباد فإن عيسى ... له رزق من استاه العباد)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":11,"spl":"يفر إلى عمان خوفا من المأمون — يهجو قبيصة بن روح المهلبي"},
{"id":"b256-15","bab":"الجزء 20","sec":"أخباره مع ابن عمه خالد","page":"ج20 ص118","text":"ولابن أبي عيينة مع ابن عمه خالد أخبار جمة اذكرها ها هنا والسبب الذي حمله على هجائه أخبرني علي بن سليمان الأخفش ببعضها عن محمد بن يزيد المبرد وببعضها عن أحمد بن يزيد المهلبي عن أبيه وقد جمعت روايتهما فيما اتفقا عليه ونسبت كل ما انفرد به أحدهما أو خالف فيه إليه وذكرت في فصول ذلك وخلاله ما لم يأتيا به مما كتبته عن الرواة قالا جميعا\nولي خالد بن يزيد بن حاتم بن قبيصة بن المهلب جرجان فسأل يزيد بن حاتم أبا عيينة أن يصحبه ويخرج معه ووعده الإحسان والولاية وأوسع له المواعيد وكان أبو عيينة جنديا فجرد اسمه في جريدته وأخرج رزقه معه فلما حصل لجرجان أعطاه رزقه لشهر واحد واقتصر على ذلك وتشاغل عنه وجفاه فبلغه أنه قد هجاه وطعن عليه وبسط لسانه فيه وذكره بكل قبيح عند أهل عمله ووجوه رعيته فلم يقدر على معاقبته لموضع أبيه وسنه ومحله في أهله فدعا به وقال له إنه قد بلغني أنك تريد أن تهرب فإما أن أقمت لي كفيلا برزقك أو رددته فأتاه بكفيل فأعنته ولم يقبله ولم يزل يردده حتى ضجر فجاءه بما قبض من الرزق فأخذه ولج أبو عيينة في هجائه وأكثر فيه حتى فضحه فقال في هذا عن أحمد بن يزيد المهلبي\n(دنيا دعوتك مسرعا فأجيبي ... وبما اصطفيتك في الهوى فأثيبي)\n(دومي أدم لك بالصفاء على النوى ... إني بعهدك واثق فثقي بي)\n(ومن الدليل على اشتياقي عبرتي ... ومشيب رأسي قبل حين مشيبي)\n(أبكي إليك إذا الحمامة طربت ... يا حسن ذاك إلي من تطريب)\n(تبكي على فنن الغصون حزينة ... حزن الحبيبة من فراق حبيب)\n(وأنا الغريب فلا ألام على البكا ... إن البكا حسن بكل غريب)\n(أفلا ينادى للقفول برحلة ... تشفي جوى من أنفس وقلوب)\n(مالي اصطفيت على التعسف خالدا ... والله ما أنا بعدها بأريب)\n(تبا لصحبة خالد من صحبة ... ولخالد بن يزيد من مصحوب)\n(يا خالد بن قبيصة هيجت بي ... حربا فدونك فاصطبر لحروبي)\n(لما رأيت ضمير غشك قد بدا ... وأبيت غير تجهم وقطوب)\n(وعرفت منك خلائقا جربتها ... ظهرت فضائحها على التجريب)\n(خليت عنك مفارقا لك عن قلى ... ووهبت للشيطان منك نصيبي)\n(فلئن نظرت إلى الرصافة مرة ... نظرا يفرج كربة المكروب)\n(لأمزقنك قائما أو قاعدا ... ولأروين عليك كل عجيب)\n(ولتأتين أباك فيك قصائد ... حبرتها بتشكر مقلوب)\n(ولينشدن بها الإمام قصيدة ... ولتشتمن وأنت غير مهيب)\n(ولأوذينك مثلما آذيتني ... ولأشلين على نعاجك ذيبي)\nال أحمد بن يزيد في خبره حدثني أبي قال أعرس داود بن محمد بن أبي عيينة أخو أبي عيينة بالبصرة وأخوه غائب يومئذ مع ابن عمه خالد بجرجان فكتب داود إلى أخيه يخبره بسلامته وسلامة أهل بيته وبخبر نقله أهله إليه فقال أبو عيينة في ذلك\n(ألا ما لعينك معتله ... وما لدموعك منهله)\n(وكيف يجرجان صبر امرئ ... وحيد بها غير ذي خله)\n(وأطول بليلك أطول به ... إذا عسكر القوم بالأثله)\n(وراعك من خيله حاشر ... من القوم ليست له قبله)\n(يسوقك نحوهم مكرها ... وداود بالمصر في غفله)\n(عروس ينعم من تحته ... سرير ومن فوقه كله)\n(وما مدنف بين عواده ... ينادي وفي سمعه ثقله)\n(بأوجع مني إذا قيل لي ... تأهب إلى الري بالرحله)\n(ومالي وللري لولا الشقاء ... إن كنت عنها لفي عزله)\n(أكلف أجبالها شاتيا ... على فرس أو على بغله)\n(وأهون من ذاك لو سهلوه ... ركوب القراقير في دجله)\n(تروح إلينا بها طربة ... رواح الندامى إلى دله)\n(أخالد خذ من يدي لطمة ... تغيظ ومن قدمي ركله)\n(جمعت خصال الردى جملة ... وبعت خصال الندى جمله)\n(فمالك في الخير من خلة ... وكم لك في الشر من خله)\n(ولما تناضل أهل العلا ... نضلت فاذعنت للنضله)\n(فما لك في المجد يا خالد ... مقرطسة لا ولا خصله)\n(وأسرعت في هدم ما قد بنى ... أبوك وأشياخه قبله)\n(وكانت من النبع عيدانهم ... نضارا وعودك من أثله)\n(فيا عجبا نبعة انبتت ... خلافا وريحانة بقله)\n(ثيابك للعبد مطوية ... وعرضك للشتم والبذله)\n(أجعت بنيك وأعريتهم ... ولم تؤت في ذاك من قله)\n(إذا ما دعينا لقبض العطاء ... وهيأت كيسك للغلة)\n(وجلة تمر تغادى بها ... فتأتي على آخر الجلة)\n(وتقصي بنيك وهم بالعراء ... نزلهم الملح والملة)\n(ولو كان خبز وتمر لديك ... لما طمعوا منك في فضله)\n(وتصبح تقلس عن تخمة ... كأن جشاءك عن فجله)\n(إذا الحي راعهم رائع ... فأوهن من غادة طفله)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":12,"spl":"أخباره مع ابن عمه خالد"},
{"id":"b256-16","bab":"الجزء 20","sec":"أخباره مع ابن عمه خالد","page":"ج20 ص118","text":"(وليث يصول على قرنه ... إذا ما دعيت إلى أكله)\n(فلله درك عند الخون ... من فارس صادق الحمله)\n(وإن جاءك الناس في حاجة ... تفكرت يومين في العله)\n(وتلقاهم أبدا كالحا ... كأن قد عضضت على بصله)\n(فهذا نصيبي من خالد ... لكم هنة بتة بتله)\nإني لصحبته مبغض ... ولا خير في صحبة السفله\nدثني أحمد بن عبيد الله بن عمار الثقفي قال حدثني أبو الحسن بن المنجم قال\nرأيت مسلم بن الوليد الأنصاري يوما عند أبي ثم خرج من عنده فلقيه ابن أبي عيينة فسلم عليه وتحفى به ثم قال له ما خبرك مع خالد قال الخبر الذي تعرفه ثم أنشده قوله فيه\n(يا حفص عاط أخاك عاطه ... كأسا تهيج من نشاطه)\nال ومسلم يبتسم من هجائه إياه حتى مر فيها كلها ثم ختمها بقوله\n(وإذا تطاولت الرؤوس ... فغط رأسك ثم طاطه)\nقال مسلم مه إنا لله هتكته والله وأخزيته وإنما كنت أظن أنك تمزح وتهزل إلى آخر قولك حتى ختمته بالجد القبيح وأفرطت فيما خرجت به إليه ثم مضى وهو يقول فضحته والله هتكته والله أخبرني عمي قال حدثني أحمد بن يزيد قال حدثني أبي قال لقي دعبل أبا عيينة فقال له\n(ياحفص عاط أخاك عاطه ... كأسا تهيج من نشاطه)\n(صرفا يعود لوقعها ... كالظبي أطلق من رباطه)\n(صبا طوت عنه الهموم ... نعيمه بعد انبساطه)\n(فبكى وحق له البكا ... لشقائه بعد اغتباطه)\n(جزع المخنث خالد ... لما وقعت على قماطه)\n(فانظر إلى نزواته ... من منطقي وإلى اختلاطه)\n(دعني وإيا خالد ... فلأقطعن عرى نياطه)\n(إني وجدت كلامه ... فيه مشابه من ضراطه)\n(رجل يعد لك الوعيد ... إذا وطئت على بساطه)\n(وإذا انتظرت غداءه ... فخف البوادر من سياطه)\n(يا خال صد المجد عنك ... فلن تجوز على صراطه)\n(وعريت من حلل الندى ... عري اليتيم ومن رياطه)\n(فإذ تطاولت الرؤوس ... فغط رأسك ثم طاطه)\nقال له دعبل أغرقت والله في النزع وأسرفت وهتكت ابن عمك وقتلته وغضضت منه وإنما استنشدتك وأنا أظن أنك قلت كما يقول الناس قولا متوسطا ولو علمت أنك بلغت به هذا كله لما استنشدتك أخبرني بهذا الخبر الحسن بن علي وعمي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثني الحسين بن السري قال لقي دعبل أبا عيينة فقال له أنشدني بعض ما قلت في ابن عمك ثم ذكر الخبر مثل ما ذكره أحمد بن يزيد وقال فيه إنما ظننت أنك قلت فيه قولا أبقيت معه عليه بعض الإبقاء ولو علمت أنك بلغت به هذا كله وأغرقت هذا الإغراق ما استنشدتك وجعل يعيد\n(فغط رأسك ثم طاطه ... )\nويقول قتله والله","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":13,"spl":"أخباره مع ابن عمه خالد","partial":1},
{"id":"b256-17","bab":"الجزء 20","sec":"نماذج من هجائه في خالد","page":"ج20 ص125","text":"أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد قال ومن مختار ما قاله في خالد قوله\n(قل لدنيا بالله لا تقطعينا ... واذكرينا في بعض ما تذكرينا)\n(لا تخوني بالغيب عهد صديق ... لم تخافيه ساعة أن يخونا)\n(واذكري عيشنا وإذ نفض الريح ... علينا الخيري والياسمينا)\n(إذ جعلنا الشاهسفرام فراشا ... من أذى الأرض والظلال غصونا)\n(حفظ الله اخوتي حيث كانوا ... من بلاد سارين أم مدلجينا)\n(فتية نازحون عن كل عيب ... وهم في المكارم الأولونا)\n(وهو الأكثرون يعلم ذاك الناس ... والأطيبون للأطيبينا)\n(أزعجتني الأقدار عنهم وقد كنت ... بقربي منهم شحيحا ضنينا)\n(وتبدلت خالدا لعنة الله ... عليه ولعنة اللاعنينا)\n(رجل يقهر اليتيم ولا يؤتي ... زكاة وينهر المسكينا)\n(ويصون الثياب والعرض بال ... ويرائي ويمنع الماعونا)\n(نزع الله منه صالح ما أعطاه ... آمين عاجلا آمينا)\n(فلعمر المبادرين إلى مكة ... وفدا غادين أو رائحينا)\n(إن أضياف خالد وبنيه ... ليجوعون فوق مايشبعونا)\n(وتراهم من غير نسك يصومون ... ومن غير علة يحتمونا)\n(يا بني خالد دعوه وفروا ... كم على الجوع ويحكم تصبرونا)\nال محمد بن يزيد ومن مشهور شعره فيه قصيدته التي أولها\n(ألا خبروا إن كان عندكم خبر ... أنقفل أم نثوي على الهم والضجر)\n(نفى النوم عن عيني تعرض رحلة ... بها الهم واستولى بها بعده السهر)\n(فإن أشك من ليلي بجرجان طوله ... لقد كنت أشكو فيه بالبصرة القصر)\n(فيا حبذا بطن الخرير وظهره ... ويا حسن واديه إذا ماؤه زخر)\n(ويا حبذا نهر الأبلة منظرا ... إذا مد في إبانه النهر أو جزر)\n(وفتيان صدق همهم طلب العلا ... وسيماهم التحجيل في المجد والغرر)\n(لعمري لقد فارقتهم غير طائع ... ولا طيب نفسا بذاك ولا مقر)\n(وقائلة ماذا نأى بك عنهم ... فقلت لها لا علم لي فسلي القدر)\n(فيا سفرا أودى بلهوي ولذتي ... ونغصني عيشي عدمتك من سفر)\n(دعوني وإيا خالد بعد ساعة ... سيحمله شعري على الأبلق الأغر)\n(كأني بصدق القول لما لقيته ... وأعلمته ما فيه ألقمته الحجر)\n(دنيء به عن كل خير بلادة ... لكل قبيح عن ذراعيه قد حسر)\n(له منظر يحمي العيون سماجة ... وإن يختبر يوما فيا سوء مختبر)\n(أبوك لنا غيث يعاش بوبله ... وأنت جراد ليس يبقي ولا يذر)\n(له أثر في المكرمات يسرنا ... وأنت تعفي دائما ذلك الأثر)\n(لقد قنعت قحطان خزيا بخالد ... فهل لك فيه يخزك الله يا مضر)\nخبرني عيسى بن الحسين قال حدثني الزبير بن بكار قال حدثني عمي قال أنشد الرشيد قول ابن أبي عيينة\n(لقد قنعت قحطان خزيا بخالد ... فهل لك فيه يخزك الله يا مضر)\nقال الرشيد بل يوقرون ويشكرون أخبرني محمد بن يحيى الصولي قال لنا أبو العباس محمد بن يزيد لم يجتمع لأحد من المحدثين في بيت واحد هجاء رجل ومديح أبيه كما اجتمع لابن أبي عيينة في قوله\n(أبوك لنا غيث نعيش بوبله ... وأنت جراد ليس يبقي ولا يذر)\nوقال محمد بن يزيد ومن جيد قوله أيضا يهجو خالدا هذا\n(على إخوتي مني السلام تحية ... تحية مثن بالأخوة حامد)\n(وقل لهم بعد التحية أنتم ... بنفسي ومالي من طريف وتالد)\n(وعز عليهم أن أقيم ببلدة ... أخا سقم فيها قليل العوائد)\n(لئن ساءهم ما كان من فعل خالد ... لقد سرهم ما قد فعلت بخالد)\n(وقد علموا أن ليس مني بمفلت ... ولا يومه المسكين مني بواحد)\n(أخالد لا زالت من الله لعنة ... عليك وإن كنت ابن عمي وقائدي)\n(أخالد كانت صحبتيك ضلالة ... عصيت بها ربي وخالفت والدي)\n(وأرسل يبغي الصلح لما تكنفت ... عوارض جنبيه سياط القصائد)\n(فأرسلت بعد الشر أني مسالم ... إلى غير مالا تشتهي غير عائد)\nخبرني عمي قال حدثنا الكراني قال زعم القحذمي أن الرشيد قال للفضل بن الربيع من أهجى المحدثين عندك يا فضل في عصرنا هذا قال الذي يقول في ابن عمه\n(لو كما ينقص يزداد ... إذا نال السماء)\n(خالد لولا أبوه ... كان والكلب سواء)\n(أنا ما عشت عليه ... أسوأ الناس ثناء)\n(إن من كان مسيئا ... لحقيق أن يساء)","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":14,"spl":"نماذج من هجائه في خالد"},
{"id":"b256-18","bab":"الجزء 20","sec":"نماذج من هجائه في خالد","page":"ج20 ص125","text":"قال الرشيد هذا ابن أبي عيينة ولعمري لقد صدقت أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبي قال كان ابن أبي عيينة مع ابن عمه خالد بجرجان فأساء به وجفاه وكان لابن أبي عيينة صديقان من جند خالد من أهل البصرة أحدهما مهلبي والآخر مولى للأزد وكلهم شاعر ظريف فكانوا يمدحون السراة من أهل جرجان فيصيبون منهم ما يقوتهم وولي موسى الهادي الخلافة فكتب ابن أبي عيينة إلى من كان في خدمة الخلفاء من أهله بهذه القصيدة\n(كيف صبري ومنزلي جرجان ... والعراق البلاد والأوطان)\n(نحن فيها ثلاثة حلفاء ... وندامى على الهوى إخوان)\n(نتساقى الهوى ونطرب للذكر ... كما تطرب النشاوى القيان)\n(وإذا ما بكى الحمام بكينا ... لبكاه كأننا صبيان)\n(يا زماني الماضي ببغداد عد ... لي طالما قد سررتني يا زمان)\n(يا زماني المسيء أحسن فقدما ... كان عندي من فعلك الإحسان)\n(ما يريد العذال مني أما يترك ... أيضا بغمه الإنسان)\n(ويقولون أملك هواك وأقصر ... قلت مالي على الهوى سلطان)\n(أيها الكاتم الحديث وقد طال ... به الأمر وانتهى الكتمان)\n(قد لعمري عرضت حينا فبين ... ليس بعد التعريض إلا البيان)\n(واتخذ خالدا عدوا مبينا ... ما تعادى الإنسان والشيطان)\n(وإله عنه فما يضرك منه ... عض كلب ليست له أسنان)\n(ولعمري لولا أبوه لنالته ... بسوء مني يد ولسان)\n(قل لفتياننا المقيمين بالباب ... ثقوا بالنجاح يا فتيان)\n(لا تخافوا الزمان قد قام موسى ... فلكم من ردى الزمان أمان)\n(أولم تأته الخلافة طوعا ... طاعة ليس بعدها عصيان)\n(فهي منقادة لموسى وفيها ... عن سواه تقاعس وحران)\n(قل لموسى يا مالك الملك طوعا ... بقياد وفي يديك العنان)\n(أنت بحر لنا ورأيك فينا ... خير رأي رأى لنا سلطان)\n(فاكفنا خالدا فقد سامنا الخسف ... رماه لحتفه الرحمن)\n(كم إلى كم يغضى على الذل منه ... وإلى كم يكون هذا الهوان)\nقال فلما قرأ هذه القصيدة موسى الهادي أمر له بصلة وأعطاه ما فات من رزقه وأقفله من جيش خالد إليه صوت\n(أين محل الحي يا وادي ... خبر سقاك الرائح الغادي)\n(مستصحب للحرب خيفانة ... مثل عقاب السرحة العادي)\n(بين خدور الظن محجوبة ... حدا بقلبي معها الحادي)\n(وأسمرا في رأسه أزرق ... مثل لسان الحية الصادي)\nلشعر لدعبل بن علي الخزاعي والغناء لأحمد بن يحيى المكي خفيف ثقيل مطلق في مجرى الوسطى عن أبي عبد الله الهشامي","topic":"نسب ابن أبي عيينة وأخباره","topicNo":256,"sp":15,"spl":"نماذج من هجائه في خالد"},
{"id":"b257-1","bab":"الجزء 20","sec":"أخبار دعبل بن علي ونسبه","page":"ج20 ص131","text":"هو دعبل بن علي بن رزين بن سليمان بن تميم بن نهشل بن خداش بن خالد بن عبد بن دعبل بن أنس بن خزيمة بن سلامان بن أسلم بن أفصى بن حارثة بن عمرو بن عامر بن مزيقيا ويكنى أبا علي شاعر متقدم مطبوع هجاء خبيث اللسان لم يسلم عليه أحد من الخلفاء ولا من وزرائهم ولا أولادهم ولا ذو نباهة أحسن إليه أو لم يحسن ولا أفلت منه كبير أحد وكان شديد التعصب على النزارية للقحطانية وقال قصيدة يرد فيها على الكميت بن زيد ويناقضه في قصيدته المذهبة التي هجا بها قبائل اليمن\n(ألا حييت عنا يا مرينا ... )\nرأى النبي في النوم فنهاه عن ذكر الكميت بسوء وناقضه أبو سعد المخزومي في قصيدته وهاجاه وتطاول الشر بينهما\nفخافت بنو مخزوم لسان دعبل وأن يعمهم بالهجاء فنفوا أبا سعد عن نسبهم وأشهدوا بذلك على أنفسهم","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":0,"spl":"أخبار دعبل بن علي ونسبه","partial":1},
{"id":"b257-2","bab":"الجزء 20","sec":"تشيع دعبل","page":"ج20 ص132","text":"وكان دعبل من الشيعة المشهورين بالميل إلى علي صلوات الله عليه وقصيدته\n(مدارس آيات خلت من تلاوة ... )\nن أحسن الشعر وفاخر المدائح المقولة في أهل البيت عليهم السلام وقصد بها أبا الحسن علي بن موسى الرضا عليه السلام بخراسان فأعطاه عشرة آلاف درهم من الدراهم المضروبة باسمه وخلع عليه خلعة من ثيابه فأعطاه بها أهل قم ثلاثين ألف درهم فلم يبعها فقطعوا عليه الطريق فأخذوها فقال لهم إنها إنما تراد لله عز و جل وهي محرمة عليكم فدفعوا إليه ثلاثين ألف درهم فحلف ألا يبيعها أو يعطوه بعضها ليكون في كفنه فأعطوه فردكم فكان في أكفانه وكتب قصيدته مدارس آيات فيما يقال على ثوب وأحرم فيه وأمر بأن يكون في أكفانه ولم يزل مرهوب اللسان وخائفا من هجائه للخلفاء فهو دهره كله هارب متوار\nحدثني إبراهيم بن أيوب قال حدثنا عبد الله بن مسلم بن قتيبة قال رأيت دعبل بن علي وسمعته يقول أنا أحمل خشبتي على كتفي منذ خمسين سنة لست أجد أحدا يصلبني عليها حدثني عمي قال حدثنا ميمون بن هرون قال قال إبراهيم بن المهدي للمأمون قولا في دعبل يحرضه عليه فضحك المأمون وقال إنما تحرضني عليه لقوله فيك\n(يا معشر الأجناد لا تقنطوا ... وارضوا بما كان ولا تسخطوا)\n(فسوف تعطون حنينية ... يلتذها الأمرد والأشمط)\n(والمعبديات لقوادكم ... لا تدخل الكيس ولا تربط)\n(وهكذا يرزق قواده ... خليفة مصحفه البربط)\nفقال له إبراهيم فقد والله هجاك أنت يا أمير المؤمنين فقال دع هذا عنك فقد عفوت عنه في هجائه إياي لقوله هذا وضحك ثم دخل أبو عباد فلما رآه المأمون من بعد قال لإبراهيم دعبل يجسر على أبي عباد بالهجاء ويحجم عن أحد فقال له وكأن أبا عباد أبسط يدا منك يا أمير المؤمنين قال لا ولكنه حديد جاهل لا يؤمن وأنا أحلم وأصفح والله ما رأيت أبا عباد مقبلا إلا أضحكني قول دعبل فيه\n(أولى الأمور بضيعة وفساد ... أمر يدبره أبو عباد)\n(وكأنه من دير هزقل مفلت ... حرد يجر سلاسل الأقياد)\nخبرني الحسن بن علي الخفاف قال حدثني محمد بن القاسم بن مهرويه قال حدثني أبي قال أخبرني دعبل بن علي قال قال لي أبي علي بن رزين ما قلت شيئا من الشعر قط إلا هذه الأبيات\n(خليلي ماذا أرتجي من غد امرىء ... طوى الكشح عني اليوم وهو مكين)\n(وإن امرأ قد ضن منه بمنطق ... يسد به فقر امرىء لضنين)\nبيتين آخرين وهما\n(أقول لما رأيت الموت يطلبني ... يا ليتني درهم في كيس مياح)\n(فيا له درهما طالت صيانته ... لا هالك ضيعة يوما ولا ضاح)\nخبرني علي بن صالح بن الهيثم الكاتب قال حدثني أبو هفان قال قال لي دعبل قال لي أبو زيد الأنصاري مم اشتق دعبل قلت لا أدري قال الدعبل الناقة التي معها ولدها أخبرني محمد بن عمران الصيرفي قال حدثني العنزي قال حدثني محمد بن أيوب قال دعبل اسمه محمد وكنيته أبو جعفر ودعبل لقب لقب به\nوحدثني بعض شيوخنا عن أبي عمرو الشيباني قال الدعبل البعير المسن أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال سمعت حذيفة بن محمد الطائي يقول الدعبل الشيء القديم قال ابن مهرويه سمعت أبي يقول ختم الشعر بدعبل قال وقال أبي كان أبو محلم يقول ختم الشعر بعمارة بن عقيل أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال سمعت أبي يقول لم يزل دعبل عند الناس جليل القدر حتى رد على الكميت بن زيد\n(ألا حييت عنا يا مرينا ... )\nكان ذلك مما وضعه قال وقال فيه أبو سعد المخزومي\n(وأعجب ما سمعنا أو رأينا ... هجاء قاله حي لميت)\n(وهذا دعبل كلف معنى ... بتسطير الأهاجي في الكميت)\n(وما يهجو الكميت وقد طواه الردى ... إلا ابن زانية بزيتت)\nأخبرني علي بن سليمان الأخفش قال حدثني محمد بن زيد قال حدثني دعبل قال كنت جالسا مع بعض أصحابنا ذات يوم فلما قمت سأل رجل لم يعرفني أصحابنا عني فقالوا هذا دعبل فقال قولوا في جليسكم خيرا كأنه ظن اللقب شتما أخبرني علي بن سليمان قال حدثني محمد بن يزيد قال حدثني دعبل قال صرع مجنون مرة فصحت في أذنه دعبل ثلاث مرات فأفاق وأخبرني بهذين الخبرين الحسن بن علي عن ابن مهرويه عن محمد بن يزيد عن دعبل وزاد فيه قال دعبل وصرع مرة مجنون بحضرتي فصحت به دعبل ثلاث مرات فأفاق من جنونه","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":1,"spl":"تشيع دعبل","partialRef":{"sid":"b257-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b257-3","bab":"الجزء 20","sec":"سبب خروجه من الكوفة","page":"ج20 ص136","text":"أخبرني محمد بن عمران الصيرفي أبو أحمد قال حدثنا الحسن بن عليل العنزي قال حدثني علي بن عمرو بن شيبان قال حدثني أبو خالد الخزاعي الأسلمي قال العنزي وقد كتبت عن أبي خالد أشياء كثيرة ولم أكتب عنه هذا الخبر قال كان سبب خروج دعبل بن علي من الكوفة أنه كان يتشطر ويصحب الشطار فخرج هو ورجل من أشجع فيما بين العشاء والعتمة فجلسا على\nطريق رجل من الصيارفة وكان يروح كل ليلة بكيسه إلى منزله فلما طلع مقبلا إليهما وثبا إليه فجرحاه وأخذا ما في كمه فإذا هي ثلاث رمانات في خرقة ولم يكن كيسه ليلتئذ معه ومات الرجل مكانه واستتر دعبل وصاحبه وجد أولياء الرجل في طلبهما وجد السلطان في ذلك فطال على دعبل الإستتار فاضطر إلى أن هرب من الكوفة قال أبو خالد فما دخلها حتى كتبت إليه أعلمه أنه لم يبق من أولياء الرجل أحد أخبرني محمد بن عمران قال حدثني أبو خالد الخزاعي الأسلمي قال قلت لدعبل ويحك قد هجوت الخلفاء والوزراء والقواد ووترت الناس جميعا فأنت دهرك كله شريد طريد هارب خائف فلو كففت عن هذا وصرفت هذا الشر عن نفسك فقال ويحك إني تأملت ما تقول فوجدت أكثر الناس لا ينتفع بهم إلا على الرهبة ولا يبالي بالشاعر وإن كان مجيدا إذا لم يخف شره ولمن يتقيك على عرضه أكثر ممن يرغب إليك في تشريفه وعيوب الناس أكثر من محاسنهم وليس كل من شرفته شرف ولا كل من وصفته بالجود والمجد والشجاعة ولم يكن ذلك فيه انتفع بقولك فإذا رآك قد أوجعت عرض غيره وفضحته اتقاك على نفسه وخاف من مثل ما جرى على الآخر ويحك يا أبا خالد إن الهجاء المقذع آخذ بضبع الشاعر من المديح المضرع فضحكت من قوله وقلت هذا والله مقال من لا يموت حتف أنفه أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني الحمدوي الشاعر قال سمعت دعبل بن علي يقول أنا ابن قولي\n(لا تعجبني يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nسمعت أبا تمام يقول أنا ابن قولي\n(نقل فؤادك حيث شئت من الهوى ... ما الحب إلا للحبيب الأول)\nال الحمدوي وأنا ابن قولي في الطيلسان\n(طال ترداده إلى الرفو حتى ... لو بعثناه وحده لتهدى)\nال الحمدوي معنى قولنا انا ابن قولي أي أني به عرفت أخبرني علي بن صالح قال حدثني أبو هفان قال قال مسلم بن الوليد\n(مستعبر يبكي على دمنة ... ورأسه يضحك فيه المشيب)\nسرقه دعبل فقال\n(لا تعجبي يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nجاء به أجود من قول مسلم فصار أحق به منه قال أبو هفان فأنشدت يوما بعض البصريين الحمقى قول دعبل\n(ضحك المشيب برأسه فبكى ... )\nجاءني بعد أيام فقال قد قلت أحسن من البيت الذي قاله دعبل فقلت له وأي شيء قلت فتمنع ساعة ثم قال قلت\n(قهقه في رأسك القتير ... )\nخبرني بهذه الحكاية الحسن بن علي عن ابن مهرويه عن أبي هفان\nقال ذكر نحوه وزاد فيه ابن مهرويه وحدثني الحمدوي قال سمع رجل قول المأمون\n(قبلته من بعيد ... فاعتل من شفتيه)\nقال\n(رق حتى تورمت شفتاه ... إذ توهمت أن أقبل فاه)\nخبرني علي بن الحسن قال حدثني ابن مهرويه قال حدثني أبو ناجية وزعم أنه من ولد زهير بن أبي سلمى قال كنت مع دعبل في شهرزور فدعاه رجل إلى منزله وعنده قينة محسنة فغنت الجارية بشعر دعبل\n(أين الشباب وأية سلكا ... لا أين يطلب ظل بل هلكا)\nقال فارتاح دعبل لهذا الشعر وقال قد قلت هذا الشعر منذ سبعين سنة","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":2,"spl":"سبب خروجه من الكوفة — نسبة هذا الصوت","partialRef":{"sid":"b194-2","gi":6,"vi":0,"side":1},"partial":1},
{"id":"b257-4","bab":"الجزء 20","sec":"نسبة هذا الصوت","page":"ج20 ص139","text":"صوت\n(أين الشباب وأية سلكا ... لا أين يطلب ضل بل هلكا)\n(لا تعجبي يا سلم من رجل ... ضحك المشيب برأسه فبكى)\n(يا ليت شعري كيف نومكما ... يا صاحبي إذا دمي سفكا)\n(لا تأخذوا بظلامتي أحدا ... قلبي وطرفي في دمي اشتركا)\nقال والغناء لأحمد بن المكي ثقيل أول بالوسطى مطلق أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أبو المثنى أحمد بن يعقوب ابن أخت أبي بكر الأصم قال كنا في مجلس الأصمعي فأنشده رجل لدعبل قوله\n(لا تعجبي يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nاستحسناه فقال الأصمعي إنما سرقه من قول الحسين بن مطير الأسدي\n(أين أهل القباب بالدهناء ... أين جيراننا على الأحساء)\n(فارقونا والأرض ملبسة نور ... الأقاحي تجاد بالأنواء)\n(كل يوم يأقحوان جديد ... تضحك الأرض من بكاء السماء)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":2,"spl":"سبب خروجه من الكوفة — نسبة هذا الصوت"},
{"id":"b257-5","bab":"الجزء 20","sec":"نماذج من هجائه","page":"ج20 ص140","text":"أخبرني أحمد بن العباس العسكري قال حدثني الحسن بن عليل العنزي قال حدثني أحمد بن خالد قال\nكنا يوما بدار صالح بن علي من عبد القيس ببغداد ومعنا جماعة من أصحابنا فسقط على كنينة في سطحه ديك طار من دار دعبل فلما رأيناه قلنا هذا صيدنا فأخذناه فقال صالح ما نصنع به قلنا نذبحه فذبحناه وشويناه وخرج دعبل فسأل عن الديك فعرف أنه سقط في دار صالح فطلبه منا فجحدناه وشربنا يومنا فلما كان من الغد خرج دعبل فصلى الغداة ثم جلس على المسجد وكان ذلك المسجد مجمع الناس يجتمع فيه جماعة من العلماء وينتابهم الناس فجلس دعبل على المسجد وقال\n(أسر المؤذن صالح وضيوفه ... اسر الكمي هفا خلال الماقط)\n(بعثوا عليه بنيهم وبناتهم ... من بين ناتفة وآخر سامط)\n(يتنازعون كأنهم قد أوثقوا ... خاقان أو هزموا كتائب ناعط)\n(نهشوه فانتزعت له أسنانهم ... وتهشمت أقفاؤهم بالحائط)\nال فكتبها الناس عنه ومضوا فقال لي أبي وقد رجع إلى البيت ويحكم ضاقت عليكم المآكل فلم تجدوا شيئا تأكلونه سوى ديك دعبل ثم أنشدنا الشعر وقال لي لا تدع ديكا ولا دجاجة تقدر عليه إلا اشتريته وبعثت به إلى دعبل وإلا وقعنا في لسانه ففعلت ذلك قال وناعط قبيلة من همدان ومجالد بن سعيد ناعطي قال وأصله جبل نزلوا به فنسبوا إليه أخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني أحمد بن أبي كامل قال كان دعبل ينشدني كثيرا هجاء قاله فأقول له فيمن هذا فيقول ما\nاستحقه أحد بعينه بعد وليس له صاحب فإذا وجد على رجل جعل ذلك الشعر فيه وذكر اسمه في الشعر وقد أخبرني الحسن بن علي عن ابن مهرويه عن أحمد بن أبي كامل بهذا الخبر بعينه وزاد فيه فيما ذكر ابن أبي كامل أنه كان عند صالح هذا في يوم أخذه ديك دعبل قال وهو صالح بن بشر بن صالح بن الجارود العبدي أخبرني محمد بن عمران قال حدثني العنزي قال حدثني أحمد بن محمد بن أبي أيوب قال مدح دعبل أبا نضير بن حميد الطوسي فقصر في أمره ولم يرضه من نفسه فقال عند ذلك دعبل فيه يهجوه\n(أبا نضير تحلحل عن مجالسنا ... فإن فيك لمن جاراك منتقصا)\n(أنت الحمار حرنا إن وقعت به ... وإن قصدت إلى معروفه قمصا)\n(إني هززتك لا آلوك مجتهدا ... لو كنت سيفا ولكني هززت عصا)\nال فشكاه أبو نضير إلى أبي تمام الطائي واستعان به عليه فقال أبو تمام يجيب دعبلا عن قوله ويهجوه ويتوعده\n(أدعبل إن تطاولت الليالي ... عليك فإن شعري سم ساعه)\n(وما وفد المشيب عليك إلا ... بأخلاق الدناءة والضراعه)\n(ووجهك إن رضيت به نديما ... فأنت نسيج وحدك في الرقاعه)\n(ولو بدلته وجها بوجه ... لما صليت يوما في جماعه)\n(ولكن قد رزقت به سلاحا ... لو استعصيت ما أعطيت طاعه)\n(مناسب طيئ قسمت فدعها ... فليست مثل نسبتك المشاعه)\n(وروح منكبيك فقد أعيدا ... حطاما من زحامك في خزاعه)\nقال العنزي يقول إنك تزاحم خزاعة تدعي أنك منهم ولا يقبلونك أخبرني محمد بن عمران قال حدثني العنزي قال حدثني محمد بن أحمدبن أيوب قال تعرض الخاركي النصري وهو رجل من الأزد لدعبل بن علي فهجاه وسبه فقال فيه دعبل\n(وشاعر عرض لي نفسه ... لخارك آباؤه تنمي)\n(يشم عرضي عند ذكري وما ... أمسى ولا أصبح من همي)\n(فقلت لا بل حبذا أمه ... خيرة طاهرة علمي)\n(أكذب والله علىأمه ... ككذبه كان على أمي)\nخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني إبراهيم بن المدبر قال لقيت دعبل بن علي فقلت له أنت أجسر الناس عندي وأقدمهم حيث تقول\n(إني من القوم الذين سيوفهم ... قتلت أخاك وشرفتك بمقعد)\n(رفعوا محلك بعد طول خموله ... واستنقذوك من الحضيض الأوهد)\nقال يا أبا إسحق أنا أحمل خشبتي منذ أربعين سنة فلا أجد من يصلبني عليها أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال قال دعبل بن علي يرثي ابن عم له من خزاعة نعي إليه قال محمد بن يزيد ولقد أحسن فيها ما شاء\n(كانت خزاعة ملء الأرض ما اتسعت ... فقص مر الليالي من حواشيها)\n(هذا أبو القاسم الثاوي ببلقعة ... تسقي الرياح عليه من سوافيها)\n(هبت وقد علمت أن لا هبوب به ... وقد تكون حسيرا إذ يباريها)\n(أضحى قرى للمنايا إذ نزلن به ... وكان في سالف الأيام يقريها)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":3,"spl":"نماذج من هجائه"},
{"id":"b257-6","bab":"الجزء 20","sec":"نماذج من هجائه","page":"ج20 ص140","text":"دثني الحسن بن مهرويه عن أبيه فذكر أن المنعي إلى دعبل أبو القاسم المطلب بن عبد الله بن مالك وأنه نعي إلى دعبل وكان هو بالجبل فرثاه بهذه الأبيات أخبرني الأخفش قال حدثنا محمد ين يزيد قال بلغ إسماعيل بن جعفر بن سليمان أن دعبلا هجاه فتوعده بالمكروه وشتمه وكان إسماعيل بن جعفر على الأهواز فهرب من زيد بن موسى بن جعفر بن محمد لما ظهر وبيض في أيام أبي السرايا فقال دعبل بن علي يعير إسماعيل بذلك\n(لقد خلف الأهواز من خلف ظهره ... يريد وراء الزاب من أرض كسكر)\n(يهول إسماعيل بالبيض والقنا ... وقد فر من زيد بن موسى بن جعفر)\n(وعاينته في يوم خلى حريمه ... فيا قبحها منه ويا حسن منظر)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":4,"spl":"نماذج من هجائه — دعبل يتشطر وهو شاب"},
{"id":"b257-7","bab":"الجزء 20","sec":"دعبل يتشطر وهو شاب","page":"ج20 ص145","text":"أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني ابن الأعرابي عن أبي خالد الأسلمي قال كان دعبل بن علي الخزاعي بالكوفة يتشطر وهو شاب وكانت له شعرة جعدة وكان يدهنها ويرجلها حتى تكاد تقطر دهنا وكان يصلت على الناس بالليل فقتل رجلا صيرفيا وظن أن كيسه معه فوجد في كمه رمانا فهرب من الكوفة وكنت إذا رأيت دعبلا يمشي رأيت الشطارة في مشيته وتبختره أخبرني الحسن قال حدثنا ابن مهرويه قال حدثني الحسن بن أبي السري قال كان عمير الكاتب أقبح الناس وجها فلقي دعبلا يوما بكرة وقد خرج\nلحاجة له فلما رآه دعبل تطير من لقائه فقال فيه\n(خرجت مبكرا من سر من را ... أبادر حاجة فإذا عمير)\n(فلم أثن العنان وقلت أمضي ... فوجهك يا عمير خرا وخير)\nخبرني الحسن قال حدثنا ابن مهرويه قال حدثني الحسن بن أبي السري قال حدثني دعبل قال مدحت عبد الرحمن بن خاقان وطلبت منه برذونا فبعث إلي ببرذون غامز فكتبت إليه\n(حملت على قارح غامز ... فلا للركوب ولا للثمن)\n(حملت على زمن ظالع ... فسوف تكافا بشكر زمن)\nبعث إلي ببرذون غيره فاره بسرجه ولجامه وألفي درهم قال ابن مهرويه وحدثني إسحاق بن إبراهيم العكبري عن دعبل أنه مدح يحيى بن خاقان فبعث إليه بهذا البرذون أخبرني الحسن قال حدثنا ابن مهرويه قال قال الحسين بن دعبل كان أبي يختلف إلى الفضل بن العباس بن جعفر بن محمد بن الأشعث وهو خرجه وفهمه وأدبه فظهر له منه جفاء وبلغه أنه يعيبه ويذكره وينال منه فقال يهجوه\n(يا بؤس للفضل لو لم يأت ما عابه ... يستفرغ السم من صماء قرضابه)\n(ما إن يزال وفيه العيب يجمعه ... جهلا لأعراض أهل المجد عيابه)\n(إن عابني لم يعب إلا مؤدبه ونفسه عاب لما عاب أدابه ... )\n(فكان كالكلب ضراه مكلبه ... لصيده فعدا فاصطاد كلابه)\nخبرني الحسن قال حدثنا ابن مهرويه قال حدثني أبو جعفر العجلي قال كان أحمد بن أبي داود يطعن على دعبل بحضرة المأمون والمعتصم ويسبه تقربا إليهما لهجاء دعبل إياهما وتزوج ابن أبي داود امرأتين من بني عجل في سنة واحدة فلما بلغ ذلك دعبلا قال يهجوه\n(غصبت عجلا على فرجين في سنة ... أفسدتهم ثم ما أصلحت من نسبك)\n(ولو خطبت إلى طوق وأسرته ... فزوجوك لما زادوك في حسبك)\n(بك من هويت ونل ما شئت من نشب ... أنت ابن زرياب منسوبا إلى نشبك)\n(إن كان قوم أراد الله خزيهم ... فزوجوك ارتغابا منك في ذهبك)\n(فذاك يوجب أن النبع تجمعه ... إلى خلافك في العيدان أو غربك)\n(ولو سكت ولم تخطب إلى عرب ... لما نشبت الذي تطويه من سبيك)\n(عد البيوت التي ترضى بخطبتها ... تجد فزارة العكلي من عربك)\nقال فلقيه فزارة العكلي فقال له يا أبا علي ما حملك على ذكري حتى فضحتني وأنا صديقك قال يا أخي والله ما اعتمدتك بمكروه ولكن كذا جاءني الشعر لبلاء صبه الله عز و جل عليك لم أعتمدك به أخبرني جعفر بن قدامة قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني أبو خالد الأسلمي الكوفي قال اجتمعت مع دعبل في منزل بعض أصحابنا وكانت عنده جارية مغنية صفراء مليحة حسنة الغناء فوقع لها العبث بدعبل والعنت والأذى له ونهيناها عنه فما انتهت فأقبل علينا فقال اسمعوا ما قلت في هذه الفاجرة فقلنا هات فقد نهيناها فلم تنته فقال\n(تخضب كفا قطعت من زندها ... فتخضب الحنا من مسودها)\n(كأنها والكحل في مرودها ... تكحل عينيها ببعض جلدها)\n(أشبه شيء آستها بخدها ... )\nال فجلست الجارية تبكي وصارت فضيحة واشتهرت بالأبيات فما انتفعت بنفسها بعد ذلك","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":4,"spl":"نماذج من هجائه — دعبل يتشطر وهو شاب","partial":1},
{"id":"b257-8","bab":"الجزء 20","sec":"دعبل يحبس ويضرب","page":"ج20 ص148","text":"أخبرني جعفر بن قدامة قال حدثني هارون قال حدثني أبي وخالد\nقالا كان دعبل قد جنى جناية بالكوفة وهو غلام فأخذه العلاء بن منظور الأسدي وكان على شرطة الكوفة من قبل موسى بن عيسى فحبسه فكلمه فيه عمه سليمان بن رزين فقال أضربه أنا خير من أن يأخذه غريب فيقطع يده فلعله أن يتأدب بضربي إياه ثم ضربه ثلثمائة سوط فخرج من الكوفة فلم يدخلها بعد ذلك إلا عزيزا أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن أبي كامل قال كان دعبل يخرج فيغيب سنين يدور الدنيا كلها ويرجع وقد أفاد وأثرى وكانت الشراة والصعاليك يلقونه فلا يؤذونه ويؤاكلونه ويشاربونه ويبرونه وكان إذا لقيهم وضع طعامه وشرابه ودعاهم إليه ودعا بغلاميه ثقيف وشعف وكانا مغنيين فأقعدهما يغنيان وسقاهم وشرب معهم وأنشدهم فكانوا قد عرفوه وألفوه لكثرة أسفاره وكانوا يواصلونه ويصلونه وأنشدني دعبل بن علي لنفسه في بعد أسفاره\n(حللت محلا يقصر البرق دونه ... ويعجز عنه الطيف أن يتجشما)\nأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال قال لي البحتري دعبل بن علي أشعر عندي من مسلم بن الوليد\nفقلت له وكيف ذلك قال لأن كلام دعبل أدخل في كلام العرب من كلام مسلم ومذهبه أشبه بمذاهبهم وكان يتعصب له أخبرني الحسن قال حدثنا ابن مهرويه قال حدثنا الفضل بن الحسن بن موسى البصري قال بات دعبل ليلة عند صديق له من أهل الشأم وبات عندهم رجل من أهل بيت لهياني يقال له حوى بن عمرو السككي جميل الوجه فدب إليه صاحب البيت وكان شيخا كبيرا فانيا قد أتى عليه حين فقال فيه دعبل\n(لولا حوى لبيت لهياني ... ما قام أير العزب الفاني)\n(له دواة في سراويله ... يليقها النازح والداني)\nقال وشاع هذان البيتان فهرب حوى من ذلك البلد وكان الشيخ إذا رأى دعبلا سبه وقال فضحتني أخزاك الله أخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني محمد بن الأشعث قال سمعت دعبلا يقول ما كانت لأحد قط عندي منة إلا تمنيت موته أخبرني الحسن قال حدثنا ابن مهرويه قال حدثنا محمد بن عمر الجرجاني قال دخل دعبل بن علي الري في أيام الربيع فجاءهم ثلج لم يروا مثله في الشتاء فجاء شاعر من شعرائهم فقال شعرا وكتبه في رقعة هو\n(جاءنا دعبل بثلج من الشعر ... فجادت سماؤنا بالثلوج)\n(نزل الري بعد ما سكن البرد ... وقد أينعت رياض المروج)\n(فكسانا ببرده لا كساه الله ... ثوبا من كرسف محلوج)\nال فألقى الرقعة في دهليز دعبل فلما قرأها ارتحل عن الري أخبرني محمد بن عمران قال حدثنا العنزي قال حدثنا أبو خالد الأسلمي قال عرضت لدعبل حاجة إلى صالح بن عطية الأضجم فقصر عنها ولم يبلغ ما أحبه دعبل فيها فقال يهجوه\n(أحسن ما في صالح وجهه ... فقس على الغائب بالشاهد)\n(تأملت عيني له خلقة ... تدعو إلى تزنية الوالد)\nتحمل عليه صالح بي وبجماعة من إخوانه حتى كف عنه وعرض عليه قضاء الحاجة فأباها أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني أبي قال فخر قوم من خزاعة على دعبل بن علي يقال لهم بنو مكلم الذئب وكان جدهم جاء إلى النبي أن الذئب أخذ من غنمه شاة فتبعه فلما غشيه بالسيف قال له ما لي ولك تمنعني رزق الله قال فقلت يا عجبا لذئب يتكلم فقال أعجب منه أن محمدا نبي قد بعث بين أظهركم وأنتم لا تتبعونه فبنوه يفخرون بتكليم الذئب جدهم فقال دعبل بن علي يهجوهم تهتم علينا بأن الذئب كلمكم ... فقد لعمري أبوكم كلم الذيبا\n(فكيف لو كلم الليث الهصور إذا ... أفنيتم الناس مأكولا ومشروبا)\n(هذا السنيدي لا أصل ولا طرف ... يكلم الفيل تصعيدا وتصويبا)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":5,"spl":"دعبل يحبس ويضرب"},
{"id":"b257-9","bab":"الجزء 20","sec":"دعبل يهجو محمد بن عبد الملك الزيات","page":"ج20 ص152","text":"حدثني الحسن بن علي قال حدثني ابن مهرويه قال حدثني أبي قال كان دعبل قد مدح محمد بن عبد الملك الزيات فأنشده ما قاله فيه وفي يده طومار قد جعله على فمه كالمتكئ عليه وهو جالس فلما فرغ أمر له بشيء لم يرضه فقال يهجوه\n(يا من يقلب طومارا ويلثمه ... ماذا بقلبك من حب الطوامير)\n(فيه مشابه من شيء تسر به ... طولا بطول وتدويرا بتدوير)\n(لو كنت تجمع أموالا كجمعكها ... إذا جمعت بيوتا من دنانير)\nخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أبي قال نزل دعبل بحمص على قوم من أهلها فبروه ووصلوه سوى رجلين منهم يقال لأحدهما أشعث وللآخر أبو الصناع فارتحل من وقته من حمص وقال فيهما يهجوهما\n(إذا نزل الغريب بأرض حمص ... رأيت عليه عز الإمتناع)\n(سمو المكرمات بآل عيسى ... أحلهم على شرف التلاع)\n(هناك الخز يلبسه المغالي ... وعيسى منهم سقط المتاع)\n(فسدد لاست أشعث أير بغل ... وآخر في حرأم أبي الصناع)\n(فليس بصانع مجدا ولكن ... أضاع المجد فهو أبو الضياع)\nخبرني الحسن قال حدثنا محمد بن القاسم بن مهرويه عن الحسين بن دعبل قال قال أبي في الفضل بن مروان\n(نصحت فأخلصت النصيحة للفضل ... وقلت فسيرت المقالة في الفضل)\n(ألا إن في الفضل بن سهل لعبرة ... إن اعتبر الفضل بن مروان بالفضل)\n(وللفضل في الفضل بن يحيى مواعظ ... إذا فكر الفضل بن مروان في الفضل)\n(فابق جميلا من حديث تفز به ... ولا تدع الإحسان والأخذ بالفضل)\n(فإنك قد أصبحت للملك قيما ... وصرت مكان الفضل والفضل والفضل)\n(ولم أر أبياتا من الشعر قبلها ... جميع قوافيها على الفضل والفضل)\n(وليس لها عيب إذا هي أنشدت ... سوى أن نصحي الفضل كان من الفضل)\nبعث إليه الفضل بن مروان بدنانير وقال له قدقبلت نصحك فاكفني خيرك وشرك حدثني عمي قال حدثني ميمون بن هرون قال حدثني أبو الطيب الحراني قال أنشد رجل دعبل بن علي شعرا له فجعل يعيبه وينبهه على خطئه فيه بيتا بيتا ويقول أي شيء صنعت بنفسك ولم تقول الشعر إذا لم تقدر إلا على مثل هذا منه إلى أن مر له بيت جيد فقال دعبل أحسنت أحسنت\nما شئت فقال له يا أبا علي أتقول لي هذا بعد ما مضى فقال له يا حبيبي لو أن رجلا ضرط سبعين ضرطة ما كان بمنكر أن يكون فيها دستنبوية واحدة أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني محمد بن حاتم المؤدب قال قيل للمأمون إن دعبل بن علي قد هجاك فقال وأي عجب في ذاك هو يهجو أبا عباد ولا يهجوني أنا ومن أقدم على جنون أبي عباد أقدم على حلمي ثم قال للجلساء من كان منكم يحفظ شعره في أبي عباد فلينشدنيه فأنشده بعضهم\n(أولى الأمور بضيعة وفساد ... أمر يدبره أبو عباد)\n(خرق على جلسائه فكأنهم ... حضروا لملحمة ويوم جلاد)\n(يسطو على كتابه بدواته ... فمضمخ بدم ونضح مداد)\n(وكأنه من دبر هزقل مفلت ... حرد يجر سلاسل الأقياد)\n(فاشدد أمير المؤمنين وثاقه ... فأصح منه بقية الحداد)\nال وكان بقية هذا مجنونا في المارستان فضحك المأمون وكان إذا نظر إلى أبي عباد يضحك ويقول لمن يقرب منه والله ما كذب دعبل في قوله حدثني جحظة عن ميمون بن هارون فذكر مثله أو قريبا منه أخبرني أحمد بن عبيد الله بن عمار ومحمد بن أحمد الحكيم قالا حدثنا أنس بن عبد الله النبهاني قال حدثني علي بن المنذر قال حدثني\nعبد الله بن سعيد الأشقري قال حدثني دعبل بن علي قال لما هربت من الخليفة بت ليلة بنيسابور وحدي وعزمت على أن أعمل قصيدة في عبد الله بن طاهر في تلك الليلة فإني لفي ذلك إذ سمعت والباب مردود علي السلام عليكم ورحمة الله أنج يرحمك الله فاقشعر بدني من ذلك ونالني أمر عظيم فقال لي لا ترع عافاك الله فإني رجل من إخوانك من الجن من ساكني اليمن طرأ إلينا طارئ من أهل العراق فأنشدنا قصيدتك\n(مدارس آيات خلت من تلاوة ... ومنزل وحي مقفر العرصات)\nأحببت أن أسمعها منك قال فأنشدته إياها فبكى حتى خر ثم قال رحمك الله ألا أحدثك حديثا يزيد في نيتك ويعينك على التمسك بمذهبك قلت بلى قال مكثت حينا أسمع بذكر جعفر بن محمد عليه السلام فصرت إلى المدينة فسمعته يقول حدثني أبي عن أبيه عن جده أن رسول الله قال علي وشيعته هم الفائزون ثم ودعني لينصرف فقلت له يرحمك الله إن رأيت أن تخبرني باسمك فافعل قال أنا ظبيان بن عامر أخبرني الحسين بن القاسم الكوكبي قال حدثني إسحاق بن محمد","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":6,"spl":"دعبل يهجو محمد بن عبد الملك الزيات"},
{"id":"b257-10","bab":"الجزء 20","sec":"دعبل يهجو محمد بن عبد الملك الزيات","page":"ج20 ص152","text":"النخعي وأخبرني به الحليمي عن يعقوب بن إسرائيل عن إسحاق النخعي قال كنت جالسا مع دعبل بالبصرة وعلى رأسه غلامه ثقيف فمر به أعرابي يرفل في ثياب خز فقال لغلامه ادع لي هذا الأعرابي فأومأ الغلام إليه فجاء فقال له دعبل ممن الرجل قال من بني كلاب قال من أي كلاب أنت قال من ولد أبي بكر فقال دعبل أتعرف القائل\n(ونبئت كلبا من كلاب يسبني ... ومحض كلاب يقطع الصلوات)\n(فإن أنا لم أعلم كلابا بأنها ... كلاب وأني باسل النقمات)\n(فكان إذا من قيس عيلان والدي ... وكانت إذا أمي من الحبطات)\nال وهذا الشعر لدعبل يقوله في عمرو بن عاصم الكلابي فقال له الأعرابي ممن أنت فكره أن يقول له من خزاعة فيهجوهم فقال أنا أنتمي إلى القوم الذين يقول فيهم الشاعر\n(أناس علي الخير منهم وجعفر ... وحمزة والسجاد ذو الثفنات)\n(إذا فخروا يوما أتوا بمحمد ... وجبريل والفرقان والسورات)\nفوثب الأعرابي وهو يقول ما لي إلى محمد وجبريل والفرقان والسورات مرتقى أخبرني الكوكبي قال حدثني ابن عبدوس قال سأل دعبل نصر بن منصور بن بسام حاجة فلم يقضها لشغل عرض له دونها فقال يهجو بني بسام\n(حواجب كالجبال سود ... إلى عثانين كالمخالي)\n(وأوجه جهمة غلاظ ... عطل من الحسن والجمال)\nخبرني الكوكبي قال حدثني ميمون بن هرون قال لما ولي أحمد بن أبي خالد الوزارة في أيام المأمون قال دعبل بن علي يهجوه\n(وكان أبو خالد مرة ... إذا بات متخما عاقدا)\n(يضيق بأولاده بطنه ... فيخراهم واحدا واحدا)\n(فقد ملأ الأرض من سلحه ... خنافس لا تشبه الوالدا)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":7,"spl":"دعبل يهجو محمد بن عبد الملك الزيات"},
{"id":"b257-11","bab":"الجزء 20","sec":"هرب إلى الجبل وهجا المعتصم","page":"ج20 ص157","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا أبو ناجية قال كان المعتصم يبغض دعبلا لطول لسانه وبلغ دعبلا أنه يريد اغتياله وقتله فهرب إلى الجبل وقال يهجوه\n(بكى لشتات الدين مكتئب صب ... وفاض بفرط الدمع من عينه غرب)\n(وقام إمام لم يكن ذا هداية ... فليس له دين وليس له لب)\n(وما كانت الآباء تأتي بمثله ... يملك يوما أو تدين له العرب)\n(ولكن كما قال الذين تتابعوا ... من السلف الماضين إذ عظم الخطب)\n(ملوك بني العباس في الكتب سبعة ... ولم تأتنا عن ثامن لهم كتب)\n(كذلك أهل الكهف في الكهف سبعة ... خيار إذا عدوا وثامنهم كلب)\n(وإني لأعلي كلبهم عنك رفعة ... لأنك ذو ذنب وليس له ذنب)\n(لقد ضاع ملك الناس إذ ساس ملكهم ... وصيف وأشناس وقد عظم الكرب)\n(وفضل بن مروان يثلم ثلمة ... يظل لها الإسلام ليس له شعب)\nخبرني عمي قال حدثني ميمون بن هرون قال لما مات المعتصم قال محمد بن عبد الملك الزيات يرثيه\n(قد قلت إذ غيبوه وانصرفوا ... في خير قبر لخير مدفون)\n(لن يجبر الله أمة فقدت ... مثلك إلا بمثل هارون)\nقال دعبل يعارضه\n(قد قلت إذ غيبوه وانصرفوا ... في شر قبر لشر مدفون)\n(اذهب إلى النار والعذاب فما ... خلتك إلا من الشياطين)\n(ما زلت حتى عقدت بيعة من ... أضر بالمسلمين والدين)\nقال عمي حدثنا ابن مهرويه قال حدثني محمد بن عمر الجرجاني قال أنشد دعبل بن علي يوما قول بعض الشعراء\n(قد قلت إذ غيبوه وانصرفوا ... )\nذكر البيتين والجواب ولم يسم قائل المرثية ولا نسبه إلى محمد بن عبد الملك الزيات ولا غيره أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال سألت دعبلا عن هذه الأبيات\n(ملوك بني العباس في الكتب سبعة ... )\nفأنكر أن تكون له فقلت له فمن قالها قال من حشا الله قبره نارا إبراهيم بن المهدي أراد أن يغري بي المعتصم فيقتلني لهجائي إياه أخبرني عمي والحسن بن علي جميعا قالا حدثنا محمد بن القاسم بن مهرويه قال حدثني أبي قال كنت عند أحمد بن المدبر ليلة من الليالي فأنشدته لدعبل في أحمد بن أبي داود قوله\n(إن هذا الذي دواد أبوه ... وإياد قد أكثر الأنباء)\n(ساحقت أمه ولاط أبوه ... ليت شعري عنه فمن أين جاء)\n(جاء من بين صخرين صلوتين ... عقامين ينيتان الهباء)\n(لا سفاح ولا نكاح ولا ما ... يوجب الأمهات والآباء)\nال فاستعادها أربع مرات فظننت أنه يريد أن يحفظها ثم قال لي جئني بدعبل حتى أوصله إلى المتوكل فقلت له دعبل موسوم بهجاء الخلفاء\nوالتشيع وإنما غايته أن يخمل ذكره فأمسك عني ثم لقيت دعبلافحدثته بالحديث فقال لو حضرت أنا أحمد بن المدبر لما قدرت أن أقول أكثر مما قلت أخبرني الحسن قال حدثنا محمد بن القاسم بن مهرويه قال حدثني محمد بن جرير قال أنشدني عبيد الله بن يعقوب هذا البيت وحده لدعبل يهجو به المتوكل وما سمعت له غيره فيه\n(ولست بقائل قذعا ولكن ... لأمر ما تعبدك العبيد)\nال يرميه في هذا البيت بالأبنة أخبرني الحسن قال حدثنا محمد بن القاسم بن مهرويه قال كنت مع دعبل بالصيمرة وقد جاء نعي المعتصم وقيام الواثق فقال لي دعبل أمعك شيء تكتب فيه فقلت نعم وأخرجت قرطاسا فأملى علي بديها\n(الحمد لله لا صبر ولا جلد ... ولا عزاء إذا أهل البلا رقدوا)\n(خليفة مات لم يحزن له أحد ... وآخر قام لم يفرح به أحد)\nدثني عمي قال حدثنا أحمد بن عبيد الله بن ناصح قال قلت لدعبل وقد عرض علي قصيدة له يمدح بها الحسن بن وهب\nأولها\n(أعاذلتي ليس الهوى من هوائيا ... )\nقلت له ويحك أتقول فيه هذا بعد قولك\n(أين محل الحي يا حادي ... خبر سقاك الرائح الغادي)\nوبعد قولك\n(قالت سلامة أين المال قلت لها ... المال ويحك لاقى الحمد فاصطحبا)\nبعد قولك\n(فعلى أيماننا يجري الندى ... وعلى أسيافنا تجري المهج)\nالله إني أراك لو أنشدته إياها لأمر لك بصفع قفاك فقال صدقت والله ولقد نبهتني وحذرتني ثم مزقها أخبرني عمي قال حدثني العنزي قال حدثني الحسين بن أبي السري قال غضب دعبل على أبي نصر بن جعفر بن محمد بن الأشعث وكان دعبل مؤدبه قديما لشيء بلغه عنه فقال يهجو أباه\n(ما جعفر بن محمد بن الأشعث ... عندي بخير أبوة من عثعث)\n(عبثا تمارس بي تمارس حية ... سوارة إن هجتها لم تلبث)\n(لو يعلم المغرور ماذا حاز من ... خزي لوالده إذا لم يعبث)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":8,"spl":"هرب إلى الجبل وهجا المعتصم","partial":1},
{"id":"b257-12","bab":"الجزء 20","sec":"هرب إلى الجبل وهجا المعتصم","page":"ج20 ص157","text":"ال فلقيه عثعث فقال له عليك لعنة الله أي شيء كان بيني وبينك حتى ضربت بي المثل في خسة الآباء فضحك وقال لا شيء والله اتفاق اسمك واسم ابن الأشعث في القافية أولا ترضى أن أجعل أباك وهو\nأسود خيرا من آباء الأشعث بن قيس أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني إبراهيم بن سهل القاري وكان يلقب أرزة قال حدثني دعبل بن علي الخزاعي قال كتبت إلى أبي نهشل بن حميد الطوسي قوله\n(إنما العيش في منادمة الإخوان ... لا في الجلوس عند الكعاب)\n(وبصرف كأنها ألسن البرق ... إذا استعرضت رقيق السحاب)\n(إن تكونوا تركتم لذة العيش ... حذار العقاب يوم العقاب)\n(فدعوني وما ألذ وأهوى ... وادفعوا بي في صدر يوم الحساب)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":9,"spl":"هرب إلى الجبل وهجا المعتصم"},
{"id":"b257-13","bab":"الجزء 20","sec":"دعبل وعلي بن موسى الرضا","page":"ج20 ص162","text":"أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني موسى بن عيسى المروزي وكان منزله بالكوفة في رحبة طيىء قال سمعت دعبل بن علي وأنا صبي يتحدث في مسجد المروزية قال دخلت على علي بن موسى الرضا عليهما السلام فقال لي أنشدني شيئا مما أحدثت فأنشدته\n(مدارس آيات خلت من تلاوة ... ومنزل وحي مقفر العرصات)\nتى انتهيت إلى قولي\n(إذا وتروا مدوا إلى واتريهم ... أكفا عن الأوتار منقبضات)\nقال فبكى حتى أغمي عليه وأومأ إلي خادم كان على رأسه أن اسكت فسكت ساعة ثم قال لي أعد فأعدت حتى انتهيت إلى هذا البيت أيضا فأصابه مثل الذي أصابه في المرة الأولى وأومأ الخادم إلي أن اسكت فسكت فمكث ساعة أخرى ثم قال لي أعد فأعذت حتى انتهيت إلى هذا البيت أيضا فأصحابه مثل الذي أصابه في المرة الأولى وأومأ الخادم إلي أن اسكت فسكت فمكث ساعة أخرى ثم قال لي أعد فأعدت حتى انتهيت إلى آخرها فقال لي أحسنت ثلاث مرات ثم أمر لي بعشرة آلاف درهم مما ضرب باسمه ولم تكن دفعت إلى أحد بعد وأمر لي من في منزله بحلي كثير أخرجه إلي الخادم فقدمت العراق فبعت كل درهم منها بعشرة دراهم اشتراها مني الشيعة فحصل لي مائة ألف درهم فكان أول مال اعتقدته قال ابن مهرويه وحدثني حذيفة بن محمد أن دعبلا قال له إنه استوهب من الرضا عليه السلام ثوبا قد لبسه ليجعله في أكفانه فخلع جبة كانت عليه فأعطاه إياها وبلغ أهل قم خبرها فسألوه أن يبيعهم إياها بثلاثين ألف درهم فلم يفعل فخرجوا عليه في طريقه فأخذوها منه غصبا وقالوا له إن شئت أن تأخذ المال فافعل والا فأنت أعلم فقال لهم إني والله لا أعطيكم إياها طوعا ولا تنفعكم غصبا وأشكوكم إلى الرضا عليه السلام فصالحوه على أن أعطوه الثلاثين الألف الدرهم وفرد كم من بطانتها فرضي بذلك أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال بويع إبراهيم بن المهدي ببغداد وقد قل المال عنده وكان قد لجأ إليه أعراب من أعراب السواد وغيرهم من أوغاد الناس فاحتبس عنهم العطاء\nفجعل إبراهيم يسوفهم ولا يرون له حقيقة إلى أن خرج إليهم رسوله يوما وقد اجتمعوا وضجوا فصرح لهم بأنه لا مال عنده فقال قوم من غوغاء أهل بغداد أخرجوا إلينا خليفتنا ليغني لأهل هذا الجانب ثلاثة أصوات ولأهل هذا الجانب ثلاثة أصوات فتكون عطاء لهم فأنشدني دعبل بعد ذلك بأيام قوله\n(يا معشر الأجناد لا تقنطوا ... وارضوا بما كان ولا تسخطوا)\n(فسوف تعطون حنينية ... يلتذها الأمرد والأشمط)\n(والمعبديات لقوادكم ... لا تدخل الكيس ولا تربط)\n(وهكذا يرزق قواده ... خليفة مصحفه البربط)\nزادني فيها جعفر بن قدامة\n(قد ختم الصك بأرزاقكم ... وصحح العزم فلا تسخطوا)\n(بيعة إبراهيم مشؤومة ... يقتل فيها الخلق أو يقحط)\nأخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أبو علي يحيى بن محمد بن ثوابةالكاتب قال حدثني دعبل قال كان لي صديق متخلف يقول شعرا فاسدا مرذولا وأنا أنهاه عنه إذا أنشدني فأنشدني يوما\n(إن ذا الحب شديد ... ليس ينجيه الفرار)\n(ونجا من كان لا يعشق ... من ذل المخازي)\nفقلت له هذا لا يجوز البيت الأول على الراء والبيت الثاني على الزاي فقال لا تنقطه فقلت له فالأول مرفوع والثاني مخفوض فقال أنا أقول له لا تنقطه وهو يشكله أخبرني الحسن قال حدثنا ابن مهرويه قال حدثنا محمد بن زكريا بن ميمون الفرغاني قال سمعت دعبل بن علي يقول في كلام جرى ليسك فأنكرته عليه فقال دخل زيد الخيل على النبي له يا زيد ما وصف لي رجل إلا رأيته دون وصفه ليسك يريد غيرك أخبرني الحسن قال حدثنا ابن مهرويه قال حدثنا علي بن عبد الله بن سعد قال قال لي دعبل وقد أنشدته قصيدة بكر بن خارجة في عيسى بن البراء النصراني الحربي\n(زناره في خصره معقود ... كأنه من كبدي مقدود)\nقال والله ما أعلمني حسدت أحدا على شعر كما حسدت بكرا على قوله كأنه من كبدي مقدود أخبرني هاشم بن محمد الخزاعي قال سمعت الجاحظ يقول سمعت دعبل بن علي يقول مكثت نحو ستين سنة ليس من يوم ذر شارقه إلا وأنا أقول فيه شعرا","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":10,"spl":"دعبل وعلي بن موسى الرضا"},
{"id":"b257-14","bab":"الجزء 20","sec":"دعبل وعلي بن موسى الرضا","page":"ج20 ص162","text":"أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني أبي قال سمعت دعبل بن علي يقول دخلت على أبي الحارث جميز وقد فلج لأعوده وكان صديقي فقلت ما هذا يا أبا الحارث فقال أخذت من شعري ودخلت الحمام فغلط بي الفالج وظن أني قد احتجمت فقلت له لو تركت خفة الروح والمجون في موضع لتركتهما في هذا الموضع وعلى هذه الحال","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":11,"spl":"دعبل وعلي بن موسى الرضا — المأمون يسأل عن شعره"},
{"id":"b257-15","bab":"الجزء 20","sec":"المأمون يسأل عن شعره","page":"ج20 ص166","text":"أخبرني الحسين بن القاسم الكوكبي قال حدثنا أحمد بن صدقة قال حدثني أبي قال حدثني عمرو بن مسعدة قال حضرت أبا دلف عند المأمون أي شيء تروي لأخي خزاعة يا قاسم فقال وأي أخي خزاعة يا أمير المؤمنين قال ومن تعرف فيهم شاعرا فقال أما من أنفسهم فأبو الشيص ودعبل وابن أبي الشيص وداود بن أبي رزين وأما من مواليهم فطاهر وابنه عبد الله فقال ومن عسى في هؤلاء أن يسأل عن شعره سوى دعبل هات أي شيء عندك فيه فقال وأي شيء أقول في رجل لم يسلم عليه أهل بيته حتى هجاهم فقرن إحسانهم بالإساءة وبذلهم بالمنع وجودهم بالبخل حتى جعل كل\nحسنة منهم بإزاء سيئة قال حين يقول ماذا قال حين يقول في المطلب بن عبد الله بن مالك وهو أصدق الناس له وأقربهم منه وقد وفد إليه إلى مصر فأعطاه العطايا الجزيلة وولاه ولم يمنعه ذلك من أن قال فيه\n(اضرب ندى طلحة الطلحات متئدا ... بلوم مطلب فينا وكن حكما)\n(تخرج خزاعة من لؤم ومن كرم ... فلا تحس لها لؤما ولا كرما)\nقال فقال المأمون قاتله الله ما أغوصه وألطفه وأدهاه وجعل يضحك ثم دخل عبد الله بن طاهر فقال له أي شيء تحفظ يا عبد الله لدعبل فقال أحفظ أبياتا له في أهل بيت أمير المؤمنين قال هاتها ويحك فأنشده عبد الله قول دعبل\n(سقيا ورعيا لأيام الصبابات ... أيام أرفل في أثواب لذاتي)\n(أيام غصني رطيب من ليانته ... أصبو إلى غير جارات وكنات)\n(دع عنك ذكر زمان فات مطلبه ... واقذف برجلك عن متن الجهالات)\n(واقصد بكل مديح أنت قائله ... نحو الهداة بنى بيت الكرامات)\nقال المأمون إنه قد وجد والله مقالا فقال ونال ببعيد ذكرهم مالا يناله في وصف غيرهم ثم قال المأمون لقد أحسن في وصف سفر سافره فطال ذلك السفر عليه فقال فيه\n(ألم يأن للسفر الذين تحملوا ... إلى وطن قبل الممات رجوع)\n(فقلت ولم أملك سوابق عبرة ... نطقن بما ضمت عليه ضلوع)\nتبين فكم دار تفرق شملها ... وشمل شتيت عاد وهو جميع كذاك الليالي صرفهن كما ترى ... لكل أناس جدبة وربيع\nم قال ما سافرت قط إلا كانت هذه الأبيات نصب عيني في سفري وهجيري ومسليتي حتى أعود أخبرني علي بن سليمان الأخفش قال حدثني المبرد ومحمد بن الحسن بن الحرون قالا قال دعبل خرجت إلى الجبل هاربا من المعتصم فكنت أسير في بعض طريقي والمكاري يسوق بي بغلا تحتي وقد أتعبني تعبا شديدا فتغنى المكاري في قولي\n(لا تعجبي يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nقلت له وأنا أريد أن أتقرب إليه وأكف ما يستعلمه من الحث للبغل لئلا يتعبني تعرف لمن هذا الشعر يا فتى فقال لمن ناك أمه وغرم درهمين فما أردي أي أموره أعجب من هذا الجواب أم من قلة الغرم على عظم الجناية حدثني عمي قال حدثني أحمد بن الطيب السرخسي قال حضرت مجلس محمد بن طاهر وحضرته مغنية يقال لها شنين مشهورة فغنت\n(لا تعجبي يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nثم غنت بعده\n(لقد عجبت سلمى وذاك عجيب ... )\nقلت لها ما أكثر تعجب سلمى هذه فعلمت أني أعبث بها لأسمع جوابها فقالت متمثلة غير متوقفة ولا متفكرة\n(فهلك الفتى ألا يراح إلى ندى ... وألا يرى شيئا عجيبا فيعجبا)\nفعجبت والله من جوابها وحدته وسرعته وقلت لمن حضر والله لو أجاب الجاحظ هذا الجواب لكان كثيرا منه مستظرفا","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":11,"spl":"دعبل وعلي بن موسى الرضا — المأمون يسأل عن شعره","partial":1},
{"id":"b257-16","bab":"الجزء 20","sec":"نسبة هذا الصوت","page":"ج20 ص169","text":"صوت\n(لقد عجبت سلمى وذاك عجيب ... رأت بي شيبا عجلته خطوب)\n(وما شيبتني كبرة غير أنني ... بدهر به رأس العظيم يشيب)\nلغناء ليحيى المكي ثقيل أول بالوسطى من كتاب ابنه أحمد حدثني جعفر بن قدامة قال حدثني محمد المرتجل بن أحمد بن يحيى المكي قال كان أبي صديقا لدعبل كثير العشرة له حافظا لغيبه وكل شعر يغنى\nفيه لدعبل فهو من صنعة أبي و غناني من صنعة أبيه في شعر دعبل والطريقة فيه خفيف ثقيل في مجرى البنصر صوت\n(سرى طيف ليلى حين آن هبوب ... وقضيت شوقا حين كاد يذوب)\n(فلم أرمطروقا يحل برحله ... ولا طارقا يقرى المنى ويثيب)\nأنشدني عمي هذين البيتين عن أحمد بن أبي طاهر وابن مهرويه جميعا لدعبل حدثني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال سألت دعبلا من الذي يقول\n(ملوك بني العباس في الكتب سبعة ... )\nقال من أضرم الله قبره نارا إبراهيم بن المهدي قال ابن أبي سعد وحدثني عبد العزيز بن سهل أنه سأله عنها فاعترف بها حدثني عمي قال أنشدني ابن أخي دعبل لعمه في طاهر بن الحسين وكان قد نقم عليه أمرا أنكره منه\n(وذي يمينين وعين واحده ... نقصان عين ويمين زائده)\n(نزر العطيات قليل الفائده ... أعضه الله ببظر الوالده)\nدثني جحظة قال حدثني ميمون بن هارون قال كان دعبل قد مدح دينار بن عبد الله وأخاه يحيى فلم يرض ما فعلاه فقال يهجوهما\n(ما زال عصياننا لله يرذلنا ... حتى دفعنا إلى يحيى ودينار)\n(وغدين علجين لم تقطع ثمارها ... قد طال ما سجدا للشمس والنار)\nال وفيهما وفي الحسن بن سهل يقول أيضا دعبل يهجوهم والحسن بن رجاء وأبيه أيضا\n(ألا فاشتروا مني ملوك المخزم ... أبع حسنا وابني رجاء بدرهم)\n(وأعط رجاء فوق ذاك زيادة ... وأسمح بدينار بغير تندم)\n(فإن رد من عيب علي جميعهم ... فليس يرد العيب يحيى بن أكثم)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبو الطيب الحراني قال كان دعبل منحرفا عن الطاهرية مع ميلهم إليه وأياديهم عنده فأنشدني لنفسه فيهم\n(وأبقى طاهر فينا ثلاثا ... عجائب تستخف لها الحلوم)\n(ثلاثة أعبد لأب وأم ... تميز عن ثلاثتهم أروم)\n(فبعض في قريش منتماه ... ولا غير ومجهول قديم)\n(وبعضهم يهش لآل كسرى ... ويزعم أنه علج لئيم)\n(فقد كثرت مناسبهم علينا ... وكلهم على حال زنيم)\nأخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أبي قال كان صالح بن عطية الأضجم من أبناء الدعوة وكان من أقبح الناس وجها وكان ينزل واسطا فقال فيه دعبل\n(أحسن ما في صالح وجهه ... فقس على الغائب بالشاهد)\n(تأملت عيني له خلقة ... تدعو إلى تزنيه الوالد)\nقال وقال فيه أيضا وخاطب فيها المعتصم\n(قل للإمام إمام آل محمد ... قول امرئ حدب عليك محام)\n(أنكرت أن تفتر عنك صنيعة ... في صالح بن عطية الحجام)\n(ليس الصنائع عنده بصنائع ... لكنهن طوائل الإسلام)\n(اضرب به جيش العدو فوجهه ... جيش من الطاعون والبرسام)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":12,"spl":"نسبة هذا الصوت","partialRef":{"sid":"b257-11","gi":0,"vi":4,"side":0},"partial":1},
{"id":"b257-17","bab":"الجزء 20","sec":"دعبل ومسلم بن الوليد","page":"ج20 ص172","text":"أخبرني محمد بن خلف بن المرزبان قال أخبرني إبراهيم بن محمد الوراق قال حدثني الحسين بن أبي السري قال قال لي دعبل ما زلت أقول الشعر وأعرضه على مسلم فيقول لي اكتم هذا حتى قلت\n(أين الشباب وأية سلكا ... لا أين يطلب ضل بل هلكا)\nلما أنشدته هذه القصيدة قال اذهب الآن فأظهر شعرك كيف شئت لمن شئت\nقال إبراهيم وحدثني الفتح غلام أبي تمام الطائي وكان أبو سعيد الثغري اشتراه له بثلثمائة دينار لينشد شعره وكان غلاما أديبا فصيحا وكان إنشاد أبي تمام قبيحا فكان ينشد شعره عنه فقال سألت مولاي أبا تمام عن نسب دعبل فقال هو دعبل بن علي الذي يقول\n(ضحك المشيب برأسه فبكى ... )\nال الفتح وحدثني مولاي أبو تمام قال ما زال دعبل مائلا إلى مسلم بن الوليد مقرا بأستاذيته حتى ورد عليه جرجان فجفاه مسلم وكان فيه بخل فهجره دعبل وكتب إليه\n(أبا مخلد كنا عقيدي مودة ... هوانا وقلبانا جميعا معا معا)\n(أحوطك بالغيب الذي أنت حائطي ... وأيجع إشفاقا لأن تتوجعا)\n(فصيرتني بعد انتكاسك متهما ... لنفسي عليها أرهب الخلق أجمعا)\n(غششت الهوى حتى تداعت أصوله ... بنا وابتذلت الوصل حتى تقطعا)\n(وأنزلت من بين الجوانح والحشا ... ذخيرة ود طالما تمنعا)\n(فلا تعذلني ليس لي فيك مطمع ... تخرقت حتى لم أجد لك مرقعا)\n(فهبك يميني استأكلت فقطعتها ... وجشمت قلبي صبره متشجعا)\nيروى وحملت قلبي فقدها قال ثم تهاجرا فما التقيا بعد ذلك أخبرني محمد بن خلف قال حدثني إبراهيم بن محمد قال حدثنا الحسين بن علي قال قلت لابن الكلبي إن دعبلا قطعي فلو أخبرت الناس أنه ليس من خزاعة فقال لي\nيا فاعل مثل دعبل تنفيه خزاعة والله لو كان من غيرها لرغبت فيه حتى تدعيه دعبل والله يا أخي خزاعة كلها","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":13,"spl":"دعبل ومسلم بن الوليد","partialRef":{"sid":"b194-2","gi":6,"vi":0,"side":1},"partial":1},
{"id":"b257-18","bab":"الجزء 20","sec":"دعبل والمطلب بن عبد الله بن مالك","page":"ج20 ص174","text":"أخبرني محمد بن المرزبان قال حدثني إبراهيم بن محمد الوراق عن الحسين بن أبي السري عن عبد الله بن أبي الشيص قال حدثني دعبل قال حججت أنا وأخي رزين وأخذنا كتبا إلى المطلب بن عبد الله بن مالك وهو بمصر يتولاها فصرنا من مكة إلى مصر فصحبنا رجل يعرف بأحمد بن فلان السراج نسي عبد الله بن أبي الشيص اسم أبيه فما زال يحدثنا ويؤانسنا طول طريقنا ويتولى خدمتنا كما يتولاها الرفقاء والأتباع وأريناه حسن الأدب وكان شاعرا ولم نعلم وكتمنا نفسه وقد علم ما قصدنا له فعرضنا عليه أن يقول في المطلب قصيدة ننحله إياها فقال إن شئتم وأرانا بذلك سرورا وتقبلا له فعملنا قصيدة وقلنا له تنشدها المطلب فإنك تنتفع بها فقال نعم ووردنا مصر به فدخلنا إلى المطلب وأوصلنا إليه كتبا كانت معنا وأنشدناه فسر بموضعنا ووصفنا له أحمد السراج هذا وذكرنا له أمره فأذن له فدخل عليه ونحن نظن أنه سينشد القصيدة التي نحلناه إياها فلما مثل بين يديه عدل عنها وأنشده\n(لم آت مطلبا إلا بمطلب ... وهمة بلغت بي غاية الرتب)\n(أفردته برجاء أن تشاركه ... في الوسائل أو ألقاه في الكتب)\nال وأشار إلى كتبي التي أوصلتها إليه وهي بين يديه فكان ذلك أشد من كل شيء مر بي منه علي ثم أنشده\n(رحلت عنسي إلى البيت الحرام على ... ما كان من وصب فيها ومن نصب)\n(ألقى بها وبوجهي كل هاجرة ... تكاد تقدح بين الجلد والعصب)\n(حتى إذا ما قضت نسكي ثنيت لها ... عطف الزمام فأمت سيد العرب)\n(فيممتك وقد ذابت مفاصلها ... من طول ما تعب لاقت ومن نقب)\n(إني استجرت بإستارين مستلما ... ركنين مطلبا والبيت ذا الحجب)\n(فذاك للآجل المأمول ألمسه ... وأنت للعاجل المرجو والطلب)\n(هذا ثنائي وهذي مصر سانحة ... وأنت أنت وقد ناديت من كثب)\nال فصاح مطلب لبيك لبيك ثم قام إليه فأخذه بيده وأجلسه معه وقال يا غلمان البدر فأحضرت ثم قال الخلع فنشرت ثم قال الدواب فقيدت فأمر له من ذلك بما ملأ عينه وأعيننا وصدورنا وحسدناه عليه وكان حسدنا له بما أتفق له من القبول وجودة الشعر وغيظنا بكتمه إيانا نفسه واحتياله علينا أكثر وأعظم فخرج بما أمر له به وخرجنا صفرا فمكثنا أياما ثم ولى دعبل بن علي أسوان وكان دعبل قد هجا المطلب غيظا منه فقال\n(تعلق مصر بك المخزيات ... وتبصق في وجهك الموصل)\n(وعاديت قوما فما ضرهم ... وشرفت قوما فلم ينبلوا)\n(شعارك عند الحروب النجاء ... وصاحبك الأخور الأفشل)\n(فأنت إذا ما التقوا آخر ... وأنت إذا انهزموا أول)\nقال فيه\n(اضرب ندى طلحة الطلحات متئدا ... بلؤم مطلب فينا وكن حكما)\n(تخرج خزاعة من لؤم ومن كرم ... فلا تعد لها لؤما ولا كرما)\nال وكانت القصيدة التي مدح بها دعبل المطلب قصيدته المشهورة التي يقول فيها\n(أبعد مصر وبعد مطلب ... ترجو الغنى إن ذا من العجب)\n(إن كاثرونا جئنا بأسرته ... أو واحدونا جئنا بمطلب)\nال وبلغ المطلب هجاؤه إياه بعد أن ولاه فعزله عن أسوان فأنفذ إليه كتاب العزل مع مولى له وقال انتظره حتى يصعد المنبر يوم الجمعة فإذا علاه فأوصل الكتاب إليه وامنعه من الخطبة وأنزله عن المنبر واصعد مكانه فلما أن علا المنبر وتنحنح ليخطب ناوله الكتاب فقال له دعبل دعني أخطب فإذا نزلت قرأته قال لا قد أمرني أن أمنعك الخطبة حتى تقرأه فقرأه وأنزله عن المنبر معزولا قال فحدثني عبد الله بن أبي الشيص قال قال لي دعبل قال لي المطلب ما تفكرت في قولك قط\n(إن كاثرونا جئنا بأسرته ... أو واحدونا جئنا بمطلب)\nلا كنت أحب الناس إلي ولا تفكرت والله في قولك لي\n(وعاديت قوما فما ضرهم ... وقدمت قوما فلم ينبلوا)\nإلا كنت أبغض الناس إلي قال ابن المرزبان حدثني من سأل الرياشي عن قوله إستارين قال يجوز على معنى إستار كذا وإستار كذا وأنشدنا الرياشي\n(سعى عقالا فلم يترك لنا سبدا ... فكيف لو قد سعى عمرو عقالين)\n(لأصبح القوم أوفاضا فلم يجدوا ... يوم الترحل والهيجا جمالين)\nخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني عبد العزيز بن سهل قال لما قصد دعبل عبد المطلب بن عبد الله بن مالك إلى مصر ولم يرض ما كان منه إليه قال فيه\n(أمطلب أنت مستعذب ... حميا الأفاعي ومستقبل)\n(فإن أشف منك تكن سبة ... وإن أعف عنك فما تعقل)\n(ستأتيك إما وردت العراق ... صحائف يأثرها دعبل)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":14,"spl":"دعبل والمطلب بن عبد الله بن مالك"},
{"id":"b257-19","bab":"الجزء 20","sec":"دعبل والمطلب بن عبد الله بن مالك","page":"ج20 ص174","text":"(منمقة بين أثنائها ... مخاز تحط فلا ترحل)\n(وضعت رجالا فما ضرهم ... وشرفت قوما فلم ينبلوا)\n(فأيهم الزين وسط الملا ... عطية أم صالح الأحول)\n(أم الباذنجاني أم عامر ... أمين الحمام التي تزجل)\n(تنوط مصر بك المخزيات ... وتبصق في وجهك الموصل)\n(ويوم السراة تحسيتها ... يطيب لدى مثلها الحنظل)\n(توليت ركضا وفتياننا ... صدور القنا فيهم تعمل)\n(إذا الحرب كنت أميرا لها ... فحظهم منك أن يقتلوا)\n(فمنك الرؤوس غداة اللقاء ... وممن يحاربك المنصل)\n(شعارك في الحرب يوم الوغى ... إذا انهزموا عجلوا عجلوا)\n(هزائمك الغر مشهورة ... يقرطس فيهن من ينضل)\n(فأنت لأولهم آخر ... وأنت لآخرهم أول)\nخبرني عمي أنشدنا المبرد لدعبل يهجو المطلب بن عبد الله ويعيره بغلامين علي وعمرو وكان يتهم بهما\n(فأير علي له آلة ... وفقحة عمرو له ربه)\n(فطورا تصادفه جعبة ... وطورا تصادفه حربه)\nأنشدني ابن عمار عن أحمد بن سليمان بن أبي شيخ لدعبل يمدح المطلب بن عبد الله بن مالك وفيه غناء صوت\n(زمني بمطلب سقيت زمانا ... ما كنت إلا روضة وجنانا)\n(كل الندى إلا نداك تكلف ... لم أرض بعدك كائنا من كانا)\n(أصلحتني بالبر بل أفسدتني ... فتركتني أتسخط الإحسانا)\nقد أخبرني بخبره الأول الطويل مع المطلب الحسن بن علي عن أحمد بن محمد حدان عن أحمد بن يحيى العدوي أن سبب سخطه على المطلب أن رجلا من العلويين كان قد تحرك بطنجة فكان يبث دعاته إلى\nمصر وخافه المطلب فوكل بالأبواب من يمنع الغرباء دخولها فلما جاء دعبل منع فأغلظ للذي منعه فقنعه بالسوط وحبسه فمضى رزين فأخبر المطلب فأمر بإطلاقه ودعا به فخلع عليه فقال له لا أرضى أو تقتل الموكل بالباب فقال له هذا لا يمكن لأنه قائد من قواد السلطان فغضب ثم أنشده الرجل الأبيات المذكورة فأجازه وحكى أن اسمه محمد بن الحجاج لا أحمد بن السراج وسائر الخبر مثله","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":15,"spl":"دعبل والمطلب بن عبد الله بن مالك"},
{"id":"b257-20","bab":"الجزء 20","sec":"دعبل والمخزومي","page":"ج20 ص179","text":"وكان سبب مناقضته أبا سعد المخزومي وما خرج إليه الأمر بينهما قول دعبل قصيدته التي هجا فيها قبائل نزار فحمي لذلك أبو سعد فهجاهم فأجابه أبو سعد ولج الهجاء بينهما وروي أنه نزل بقوم من بني مخزوم فلم يضيفوه فهجاهم فأجابهم أبو سعد ولج الهجاء بينهما أخبرني عمي والحسن بن علي الخفاف قالا حدثنا محمد بن القاسم بن مهرويه قال حدثني محمد بن الأشعث قال حدثني دعبل أنه ورزينا العروضي نزلا بقوم من بني مخزوم فلم يقروهما ولا أحسنوا ضيافتها فقال دعبل فقلت فيهم\n(عصابة من بني مخزوم بت بهم ... بحيث لا تطمع المسحاة في الطين)\nم قلت لرزين أجز فقال\n(في مضغ أعراضهم من خبزهم عوض ... بني النفاق وأبناء الملاعين)\nال ابن الأشعث فكان هذا أول الأسباب في مهاجاته لأبي سعد\nأخبرني محمد بن عمران الصيرفي قال حدثني العنزي قال حدثني علي بن عمرو الشيباني أن الذي هاج الهجاء بين أبي سعد و دعبل قصيدته القحطانية التي هجا فيها نزارا فأجابه عنها أبو سعد ولج الهجاء بينهما أخبرني الحسن بن علي قال حدثنا محمد بن القاسم قال حدثني أحمد بن أبي كامل قال كان سبب وقوع الهجاء بين دعبل وأبي سعد قول دعبل في قصيدة يفخر فيها بخزاعة ويهجو نزارا وهي التي يقول فيها\n(أتانا طالبا وعرا ... فأعقبناه بالوعر)\n(وترناه فلم يرض ... فأعقبناه بالوتر)\nغضب أبو سعد وقال قصيدته التي يقول فيها لدعبل وهي مشهورة\n(وبالكرخ هوى أبقى ... على الدهر من الدهر)\n(هوى والحمد لله ... كفاني كلفة العذر)\nال ثم التحم الهجاء بينهما بعد ذلك أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن هارون قال دخلت على أبي سعد الخزومي يوما وهو يقول وأي شيء ينفعني أجود الشعر فلا يروى ويرذل فيروى ويفضحني برديئه ولا أفضحه بجيدي فقلت من تعني يا أبا سعد فقال من تراني أعني إلا من عليه لعنة الله دعبلا فقلت فيه\n(ليس لبس الطيالس ... من لباس الفوارس)\n(لاولا حومة الوغى ... كصدور المجالس)\n(ضرب أوتار نفنف ... غير ضرب القوانس)\n(وظهور الجياد غير ... ظهور الطنافس)\n(ليس من ضارس الحروب ... كمن لم يضارس)\n(بأبي غرس فتية ... من كرام المغارس)\n(فتية من بني المغيرة ... شم المعاطس)\n(يطعمون السديف في ... كل شهباء دامس)\n(في جفان كأنها ... من جفان العرائس)\n(ثم يمشون في السنور ... مشي العنابس)\n(ويخوضون باللواء ... دماء الأبالس)\n(نحن خير الأنام عند ... قياس المقايس)\nفوالله ما التفت إليها في مصرنا هذا إلا علماء الشعر وقال هو في\n(يا أبا سعد قوصره ... زاني الأخت والمره)\n(لو تراه محنبا ... خلته عقد قنطره)\n(أو ترى الأير في آسته ... قلت ساق بمقطره)\nقال فوالله لقد رواه صبيان الكتاب ومارة الطريق والسفل أجتاز والسفل فما اجتاز بموضع إلا سمعته من سفلة يهذرون به فمنهم من يعرفني فيعيبني به ومنهم\nمن لا يعرفني فأسمعه منه لسهولته على لسانه أخبرني محمد بن عمران الصيرفي ومحمد بن يحيى الصولي وعمي قالوا حدثنا الحسن بن عليل العنزي قال حدثني علي بن أبي عمرو الشيباني قال جاءني إسماعيل بن إبراهيم بن ضمرة الخزاعي فقال لي إني سألت دعبلا أن اقرأ عليه قصيدته التي يناقض بها الكميت\n(أفيقي من ملامك يا ظعينا ... كفاك اللوم مر الأربعينا)\nقال لي إسماعيل قال لي دعبل يا أبا الحسن فيها أخبار وغريب فليكن معك رجل يقرأها علي وأنت معه فيكون أهون علي منك فقلت له لقد اخترت صديقا لي يقال له علي فقال أمن العرب هو قلت نعم قال من أي العرب قلت من بني شيبان قال شيبان كندة فقلت بل شيبان ربيعة فقال لي ويحك أتأتيني برجل أسمعه ما يكره في قومه فقلت له إنه رجل يحتمل ويحب أن يسمع ماله وعليه فقال في مثل هذا رغبة فأتني به فصرنا إليه فلما لقيه قال قد أخبرني عنك أبو الحسن بما سررت به أن كنت رجلا من العرب تحب أن تمسع ما لك وعليك لكيلا تغبن فقرأنا عليه الشعر حتى انتهينا في القصيدة إلى قوله\n(من أي ثنية طلعت قريش ... وكانوا معشرا متنبطينا)\nفقال دعبل معاذ الله أن يكون هذا البيت لي ثم قال لعنه الله وانتقم منه يعني أبا سعد المخزومي دسه والله في هذا الشعر وضرب بيده إلى سكين كانت معه فجرد البيت بحدها ثم قال لنا أحدثكم عنه بحديث طريف جاءني يوما ببغداد أشد ما كان بيني وبينه من الهجاء وبين يدي","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":16,"spl":"دعبل والمخزومي"},
{"id":"b257-21","bab":"الجزء 20","sec":"دعبل والمخزومي","page":"ج20 ص179","text":"صحيفة ودواة وأنا أهجوه فيها إذ دخل علي غلام لي فقال أبو سعد المخزومي بالباب فقلت له كذبت فقال وهو عارف بأبي سعد بلى والله يا مولاي فأمرته برفع الدواة والجلد الذي كان بين يدي وأذنت له في الدخول وجعلت أحمد الله في نفسي فأقول الحمد لله الذي أصلح بيني وبينه من هتك الأعراض وذكر القبيح وكان الابتداء منه فقمت إليه وسلمت عليه وهو ضاحك مسرور فأبديت له مثل ذلك من السرور به ثم قلت أصبحت والله حاسدا لك قال على ماذا يا أبا علي فقلت بسبقك إياي إلى الفضل فقال لي أنا اليوم في دعوى عندك فقلت قل ما أحببت فقال إن كان عندك ما نأكله وإلا ففي منزلي شيء معد فسألت الغلمان فقالوا عندنا قدر أمسية فقال غاية واتفاق جيد فهل عندك شيء نشربه وإلا وجهت إلى منزلي ففيه شراب معد فقلت له عندنا ما نشرب فطرح ثيابه ورد دابته وقال أحب ألا يكون معنا غيرنا فتغدينا وشربنا فلما أن أخذ الشراب منا قال مر غلاميك يغنياني فأمرت الغلامين فغنياه فطرب وفرح واستحسن الغناء حتى سرني وأطربني معه ثم قال حاجتي إليك يا أبا علي أن تأمرهما بأن يغنياني في هجائك لي وكان الغلامان لكثرة ما يسمعانه مني في هجائي قد حفظا منه أشياء ولحناها فقلت له سبحان الله يا أبا سعد قد طفئت النائرة وذهبت العداوة بيننا وانقطع الشر فما حاجتك إلى هذا فقال لي سألتك بالله إلا فعلت فليس يشق ذلك علي ولو كرهته لما سألته فقلت في نفسي أترى أبا سعد يتماجن علي يا غلمان غنوه بما يريد فقال غنوه\n(يا أبا سعد قوصرة ... زاني الأخت والمره)\nفغنوه وهو يحرك رأسه وكتفيه ويطرب ويصفق فما زلنا يومنا مسرورين فلما ثمل ودعني وقام فانصرف وأمرت غلماني فخرجوا معه إلى الباب فإذا غلام منهم قد انصرف إلي بقطعة قرطاس وقال دفعها إلي أبو سعد المخزومي وأمرني أن أدفعها إليك فقرأتها فإذا فيها\n(لدعبل منه يمن بها ... فلست حتى الممات أنساها)\n(أدخلنا بيته فأكرمنا ... ودس بامرأته فنكناها)\nقال ويلي على ابن الفاعلة هاتوا جلدا وداوة قال فردوهما علي فعدت غلى هجائه ولقيته بعد يومين أو ثلاثة فما سلم علي ولا سلمت عليه أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا علي بن عبد الله بن سعد أنه سمع دعبلا يحدث بخيره هذا مع أبي سعد فذكر نحو ما ذكره العنزي أخبرني الحسن بن علي قال حدثنا محمد بن القاسم قال حدثني أحمد بن أبي كامل قال رأيت دعبلا قد لقي أبا سعد في الرصافة وعليهما السواد وسيفاهما على أكتافهما فشد دعبل على أبي سعد فقنعه فركض أبو سعد بين يديه هاربا وركض دعبل في أثره وهو يهرب منه حتى غاب قال وكنت أرى ابا سعد يجلس مع بني مخزوم في دار المأمون فتظلموا منه إلى المأمون وذكروا أنهم لا يعرفون له فيهم نسبا فأمرهم المأمون بنفيه فانتفوا منه وكتبوا بذلك كتابا فقال دعبل فيه يذكر ذلك من قصيدة طويلة\n(غير أن الصيد منهم ... قنعوه بخزايه)\n(كتبوا الصك عليه ... فهو بين الناس آيه)\n(فإذا أقبل يوما ... قيل قد جاء النفايه)\nوقال فيه أيضا\n(هم كتبوا الصك الذي قد علمته ... عليك وشنوا فوق هامتك القفدا)\nال وكان إذا قيل له بعد ذلك شيء في نسبه قال أنا عبد ابن عبد قال ونظر دعبل فرأى على أبي سعد قباء مرويا مصبوغا بسواد فقال هذا دعي على دعي أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن مروان مولى الهادي قال لقيني أبو سعد المخزومي على ظهر الطريق فقال لي يا أحمد أنا أدرس شكايتك إلى أبيك قال فقلت ولم أبقاك الله قال فما فعل دفتر البزاريات قلت هو ذا أجيئك به فلما صليت الظهر جئت بالدفتر أريده فمررت بدعبل فدققت بابه فسمعته يقول لجاريه له أنظري من بالباب فقالت له أحمد بن مروان فقال افتحي له فلما دخلت قلت له أيش هو دراهم من الأسماء قال سميتم جواريكم دنانير فسمينا جوارينا بدراهم ثم قال ما هذا معك قلت دفتر فيه شعر أبي سعد في البزاريات فأخذه فنظر فيه وابنه علي بن دعبل بن علي معه فلما بلغ من نظره إلى شعره الذي يقول فيه\n(مالت إلى قلبك أحزانه ... فهو مجم الهم خزانه)\nقال له ابنه علي فما كان عليه يا أبت لو قال في شعره\n(عادت إلى قلبك أحزانه ... )\nفقال دعبل صدقت والله يا بني أنت والله أشعر منه ثم قال إنه أملى علي دعبل إملاء\n(ما كنت أحسب أن الدهر يمهلني ... حتى أرى أحدا يهجوه لا أحد)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":17,"spl":"دعبل والمخزومي","partial":1},
{"id":"b257-22","bab":"الجزء 20","sec":"دعبل والمخزومي","page":"ج20 ص179","text":"(إني لأعجب ممن في حقيبته ... من المني بحور كيف لا يلد)\n(فإن سمعت به بعت القنا عبثا ... فقد أراد قنا ليست له عقد)\nم صرت إلى أبي سعد فلما رآني من بعيد قال يا أحمد من أين أقبلت قلت من عند دعبل قال وما دعبلت عنده فأنشدته شعر دعبل فيه وأخبرته بما قال ابنه في شعره فقال صدق والله في أي سن هو قلت قد بلغ فدعا بدواة وقرطاس وقال اكتب فكتبت\n(لا والذي خلق الصهباء من ذهب ... والماء من فضة لا ساد من بخلا)\n(يقول لي دعبل في بطنه حبل ... ولو أصابت ثيابي دعبل حبلا)\n(ودعبل رجل ما شئت من رجل ... لو كان أسفله من خلقه رجلا)\nال ثم هجاني أبو سعد فقال\n(عدو راح في ثوبي صديق ... شريك في الصبوح وفي الغبوق)\n(له وجهان ظاهره ابن عم ... وباطنه ابن زانية عتيق)\n(يسرك معلنا ويسوء سرا ... كذاك يكون أبناء الطريق)\nخبرني عمي والحسن بن علي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثنا أبو ناجية شيخ من ولد زهير بن أبي سلمى قال حضرت بني مخزوم وهم ببغداد وقد اجتمعوا على أبي سعد لما لج الهجاء بينه وبين دعبل وقد خافوا لسان دعبل وأن يقطعهم ويهجوهم هجاء\nيعمهم جميعا فكتبوا عليه كتابا وأشهدوا أنه ليس منهم فحدثني غير واحد أنه أتى حينئذ بخاتمه النقاش فنقش عليه أبو سعد العبد ابن العبد بريء من بني مخزوم تهاونا بما فعلوه أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد قال كان أبو سعد المخزومي قد كان يستعلي على دعبل في أول أمره وكان يدخل إلى المأمون فينشده هجاء دعبل وللخلفاء ويحرضه عليه وينشده جوابه فلم يجد عند المأمون ما أراده فيه وكان يقول الحق في يدك والباطل في يد غيرك والقول لك ممكن فقل ما يكذبه فأما القتل فإني لست أستعمله فيمن عظم ذنبه أفأستعمله في شاعر فاعترض بينهما ابن أبي الشيص فقال يهجو أبا سعد\n(أنا بشرت أبا سعد ... فأعطاني البشاره)\n(بأب صيد له بالأمس ... في دار الإماره)\n(فهو يوما من تميم ... وهو يوما من فزاره)\n(كل يوم لأبي سعد ... على الأنساب غاره)\n(خزمت مخزوم فاه ... فادعاها بالإشارة)\nال وقال فيه ابن أبي الشيص أيضا\n(أبا سعد بحق الخمس ... والمفروض من صومك)\n(أقلت الحق في النسبة ... أمن تحلم في نومك)\n(أبن لي أيها المعرور ... ممن أنت في قومك)\n(فولى قائلا لو شئت ... قد أقصرت من لومك)\n(ودعني أك من شئت ... إذا لم أك من قومك)\nوقال فيه دعبل\n(إن أبا سعد فتى شاعر ... يعرف بالكنية لا الوالد)\n(ينشد في حي معد أبا ... ضل عن المنشود والناشد)\n(فرحمة الله على مسلم ... أرشد مفقودا إلى فاقد)\nخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أحمد بن عثمان الطبري قال سمعت دعبل بن علي يقول لما هاجيت أبا سعد أخذت معي جوزا ودعوت الصبيان فأعطيتهم منه وقلت لهم صيحوا به قائلين\n(يا أبا سعد قوصره ... زاني الأخت والمره)\nصاحوا به فغلبته أخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني أحمد بن مروان قال حدثني أبو سعد المخزومي واسمه عيسى بن خالد بن الوليد قال أنشدت المأمون قصيدتي الدالية التي رددت فيها على دعبل قوله\n(ويسومني المأمون خطة عاجز ... أو ما رأى بالأمس رأس محمد)\nأول قصيدتي\n(أخذ المشيب من الشباب الأغيد ... والنائبات من الأنام بمرصد)\nم قلت له يا أمير المؤمنين ائذن لي أن أجيئك برأسه قال لا هذا رجل فخر علينا فافخر عليه كما فخر علينا فأما قتله بلا حجة فلا أخبرني عمي والحسن بن علي عن أحمد بن أبي طاهر قال حدثني أبو السري عمرو الشيباني قال\nنظر دعبل يوما في المرآة فجعل يضحك وكانت في عنفقته سلعة فقلت له من أي شيء تضحك قال نظرت إلى وجهي في المرآة ورأيت هذه السلعة التي في عنفقتي فذكرت قول الفاجر أبي سعد\n(وسلعة سوء به سلعة ... ظلمت أباه فلم ينتصر)\nخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال قال عبد الله بن الحسن بن أحمد مولى عمر بن عبد العزيز قال حدثنا محمد بن علي الطالبي قال لقيت دعبل بن علي فحدثني أن أبا عمرو الشيباني سأله ما هو دعبل فقلت له لا أدري فقال إنها الناقة المسنة قال محمد بن علي الطالبي ثم تحدثنا ساعة فقلت أما ترى لأبي سعد يا أبا علي وانهماكه في هجائك فقال دعبل لكني لم أقل فيه إلا أبياتا سخيفة يلعب بها الصبيان والإماء وأنشدني قوله فيه\n(يا أبا سعد قوصره ... زاني الأخت والمره)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":18,"spl":"دعبل والمخزومي"},
{"id":"b257-23","bab":"الجزء 20","sec":"دعبل والمخزومي","page":"ج20 ص179","text":"(لو تراه محنبا ... خلته عقد قنطره)\n(أو ترى الأير في استه ... قلت ساق بمقطره)\nال محمد فقلت لدعبل دع عنك ذا فقد الله أوجعك الرجل فإن أجبته بجواب مثله انتصفت وإلا فإن هذا اللغو الذي فخرت به يسقط وتفضح\nآخر الدهر قال ثم أنشدته قول أبي سعد فيه\n(لم يبق لي لذة من طية بدد ... ولا المنازل من خيف ولا سند)\n(أبعد خمسين عادت جاهليته ... يا ليت ما عاد منها اليوم لم يعد)\n(وما تريد عيون العين من رجل ... كر الجديدان في أيامه الجدد)\n(أبدى سرائره وجدا بغانية ... ولو أطاع مشيب الرأس لم يجد)\n(واستمطرت عبرات العين منزلة ... لم يبق منها سوى الآري والوتد)\n(وما بكاؤك دارا لا أنيس بها ... إلا الخواضب من خيطانها الربد)\n(لدعبل وطر في كل فاحشة ... لو باد لؤم بني قحطان لم يبد)\n(ولي قواف إذا أنزلتها بلدا ... طارت بهن شياطيني إلى بلد)\n(لم ينج من خيرها أو شرها أحد ... فاحذر شآبيبها إن كنت من أحد)\n(إن الطرماح نالته صواعقها ... في ظلمة القبر بين الهام والصرد)\n(وأنت أولى بها إذ كنت وارثه ... فابعد وجهدك أن تنجو على البعد)\n(تهجو نزارا وترعى في أرومتها ... وتنتمي في أناس حاكة البرد)\n(إني إذا رجل دبت عقاربه ... سقيته سم حياتي فلم يعد)\n(زدني أزدك هوانا أنت موضعه ... ومن يزيد إذا ما نحن لم نزد)\n(لو كنت متئدا فيما تلفقه ... لكان حظك منه حظ متئد)\n(أو كنت معتمدا منه على ثقة ... من المكارم قلنا طول معتمد)\n(لقد تقلدت أمرا لست نائله ... بلا ولي ولا مولى ولا عضد)\n(وقد رميت بياض الشمس تحسبه ... بياض بطنك من لؤم ومن نكد)\n(لا توعدني بقوم أنت ناصرهم ... واقعد فإنك نومان من القعد)\n(لله معتصم بالله طاعته ... قضية من قضايا الواحد الصمد)\nال فلما أنشدتها دعبلا قال أنا أشتمه وهو يشتمني فما إدخال المعتصم بيننا وشق ذلك عليه وخافه ثم قال نقيض هذه القصيدة\n(منازل الحي من غمدان فالنضد ... )\nهي طويلة مشهورة في شعره هكذا قال العنزي في الخبر ولم يأت بها حدثنا محمد قال حدثنا العنزي قال حدثني عبد الله بن الحسين عن محمد بن علي الطالبي قال عبر دعبل الجسر ببغداد وأبو سعد واقف على دابته عند الجسر وعليه ثوب صوف مشبه بالخز مصبوغ فضرب دعبل بيده على فخده وقال\nدعي على دعي","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":19,"spl":"دعبل والمخزومي","partial":1},
{"id":"b257-24","bab":"الجزء 20","sec":"حديث عن شبه بين عبد الله بن طاهر والضبي عن نسبه","page":"ج20 ص192","text":"أخبرني محمد بن جعفر الصيدلاني صهر المبرد قال حدثني محمد بن موسى الضبي راوية العتابي وكان نديما لعبد الله بن طاهر قال\nبينما هو ذات ليلة يذاكرنا بالأدب وأهله وشعراء الجاهلية والإسلام إذ بلغ إلى ذكر المحدثين حتى انتهى إلى ذكر دعبل فقال ويحك يا ضبي إني أريد أن أحدثك بشيء على أن تستره طول حياتي فقلت له أصلحك الله أنا عندك في موضع ظنه قال لا ولكن أطيب لنفسي أن توثق لي الأيمان لأركن إليها ويسكن قلبي عندها فأحدثك حينئذ\nقال قلت إن كنت عند الأمير في هذه الحال فلا حاجة به إلى إفشاء سره إلي واستعفيته مرارا فلم يعفني فاستحييت من مراجعته وقلت فلير الأمير رأيه فقال لي يا ضبي قل والله قلت فأمرها علي غموسا مؤكدة بالبيعة والطلاق وكل ما يحلف به مسلم ثم قال أشعرت أن دعبلا مدخول النسب وأمسك فقلت أعز الله الأمير أفي هذا أخذت العهود والمواثيق ومغلظ الأيمان قال إي والله فقلت ولم قال لأني رجل لي في نفسي حاجة ودعبل رجل قد حمل نفسه على المهالك وحمل جذعه على عنقه فليس يجد من يصلبه عليه وأخاف إن بلغه أن يقول في ما يبقى علي عاره على الدهر وقصاراي إن ظفرت به وأسلمته اليمن وما أراها تفعل لأنه اليوم لسانها وشاعرها والذاب عنها والمحامي لها والمرامي دونها فأضربه مائة سوط وأثقله حديدا وأصيره في مطبق باب الشام\nوليس في ذلك عوض مما سار في من الهجاء وفي عقبي من بعدي فقلت ما أراه يفعل ويقدم عليك فقال لي يا عاجز أهون عليه مما لم يكن أتراه أقدم على الرشيد والأمين والمأمون وعلى أبي ولا يقدم علي فقلت فإذا كان الأمر كذا فقد وفق الأمير فيما أخذه علي قال وكان دعبل صديقا لي فقلت هذا شيء قد عرفته فمن أين قال الأمير إنه مدخول النسب وهو في البيت الرفيع من خزاعة ولا يتقدمهم غير بني أهبان مكلم الذئب فقال أسمع أنه كان أيام ترعرع خاملا لا يؤبه له وكان ينام هو ومسلم بن الوليد في إزار واحد لا يملكان غيره ومسلم أستاذه وهو غلام أمرد يخدمه ودعبل حينئذ لا يقول شعرا يفكر فيه حتى قال\n(لا تعجبني يا سلم من رجل ... ضحك المشيب برأسه فبكى)\nوغنى فيه بعض المغنين وشاع فغني به بين يدي الرشيد إما ابن جامع أو ابن المكي فطرب الرشيد وسأل عن قائل الشعر فقيل له دعبل بن علي وهو غلام نشأ من خزاعة فأمر بإحضار عشرة آلاف درهم وخلعة من ثيابه فأحضر ذلك فدفعه مع مركب من مراكبه إلى خادم من خاصته وقال له اذهب بهذا إلى خزاعة فاسأل عن دعبل بن علي فإذا دللت عليه فأعطه هذا وقل له ليحضر إن شاء وإن لم يجب ذلك فدعه وأمر للمغني بجائزة فسار الغلام إلى دعبل وأعطاه الجائزة وأشار عليه بالمسير إليه\nفلما دخل عليه وسلم أمره بالجلوس فجلس واستنشده الشعر فأنشده إياه فاستحسنه وأمره بملازمته وأجرى عليه رزقا سنيا فكان أول من حرضه على قول الشعر فوالله ما بلغه أن الرشيد مات حتى كافأه على ما فعله من العطاء السني والغنى بعد الفقر والرفعة بعد الخمول بأقبح مكافأة وقال فيه من قصيدة مدح بها أهل البيت عليهم السلام وهجا الرشيد\n(وليس حي من الأحياء نعلمه ... من ذي يمان ومن بكر ومن مضر)\n(إلا وهم شركاء في دمائهم ... كما تشارك أيسار على جزر)\n(قتل وأسر وتحريق ومنهبة ... فعل الغزاة بأرض الروم والخزر)\n(أرى أمية معذورين إن قتلوا ... ولا أرى لبني العباس من عذر)\n(اربع بطوس على القبر الزكي إذا ... ما كنت تربع من دين على وطر)\n(قبران في طوس خير الناس كلهم ... وقبر شرهم هذا من العبر)\n(ما ينفع الرجس من قرب الزكي ولا ... على الزكي بقرب الرجس من ضرر)\n(هيهات كل امرئ رهن بما كسبت ... له يداه فخذ ما شئت أو فذر)\nعني قبر الرشيد وقبر الرضا عليه السلام فهذه واحدة وأما الثانية فإن المأمون لم يزل يطلبه وهو طائر على وجهه حتى دس إليه قوله\n(علم وتحكيم وشيب مفارق ... طمسن ريعان الشباب الرائق)\n(وإمارة في دولة ميمونة ... كانت على اللذات أشغب عائق)\n(أنى يكون وليس ذاك بكائن ... يرث الخلافة فاسق عن فاسق)\n(إن كان إبراهيم مصطلعا بها ... فلتصلحن من بعده لمخارق)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":20,"spl":"حديث عن شبه بين عبد الله بن طاهر والضبي عن نسبه"},
{"id":"b257-25","bab":"الجزء 20","sec":"حديث عن شبه بين عبد الله بن طاهر والضبي عن نسبه","page":"ج20 ص192","text":"لما قرأها المأمون ضحك وقال قد صفحت عن كل ما هجانا به إذ قرن إبراهيم بمخارق في الخلافة وولاه عهده وكتب إلى أبي أن يكاتبه بالأمان ويحمل إليه مالا وإن شاء أن يقيم عنده أو يصير إلى حيث شاء فليفعل فكتب إلي أبي بذلك وكان واثقا به فصار إليه فحمله وخلع عليه وأجازه وأعطاه المال وأشار عليه بقصد المأمون ففعل فلما دخل وسلم عليه تبسم في وجهه ثم قال أنشدني\n(مدارس آيات خلت من تلاوة ... ومنزل وحي مقفر العرصات)\nجزع فقال له لك الأمان فلا تخف وقد رويتها ولكني أحب سماعها من فيك فأنشده إياها إلى آخرها والمأمون يبكي حتى أخضل لحيته بدمعه فوالله ما شعرنا به إلا وقد شاعت له أبيات يهجو بها المأمون بعد إحسانه إليه وأنسه به حتى كان أول داخل وآخر خارج من عنده أخبرني محمد بن خلف بن المرزبان قال حدثني أبو بكر العامري قال استدعى بعض بني هاشم دعبل وهو يتولى للمعتصم ناحية من نواحي الشام فقصده إليها فلم يقع منه بحيث ظن وجفاه فكتب إليه دعبل\n(دليتني بغرور وعدك في ... متلاطم من حومة الغرق)\n(حتى إذا شمت العدو وقد ... شهر انتقاصك شهرة البلق)\n(أنشأت تحلف أن ودك لي ... صاف وحبلك غير منحذق)\n(وحسبتني فقعا بقرقرة ... فوطئتني وطئا على حنق)\n(ونصبتني علما على غرض ... ترميني الأعداء بالحدق)\n(وظننت أرض الله ضيقة ... عني وأرض الله لم تضق)\n(من غير ما جرم سوى ثقة ... مني بوعدك حين قلت ثق)\n(ومودة تحنو عليك بها ... نفسي بلا من ولا ملق)\n(فمتى سألتك حاجة أبدا ... فاشدد بها قفلا على غلق)\n(وقف الإخاء على شفا جرف ... هار فبعه بيعة الخلق)\n(وأعد لي قفلا وجامعة ... فاشدد يدي بها إلى عنقي)\n(أعفيك مما لا تحب بها ... واسدد علي مذاهب الأفق)\n(ما أطول الدنيا وأعرضها ... وأدلني بمسالك الطرق)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":21,"spl":"حديث عن شبه بين عبد الله بن طاهر والضبي عن نسبه"},
{"id":"b257-26","bab":"الجزء 20","sec":"يهرب بعد اتهامه بشتم صفية بنت عبد المطلب","page":"ج20 ص196","text":"أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أبي قال قدم دعبل الدينور فجرى بينه وبين رجل من ولد الزبير بن العوام\nكلام وعربدة على النبيذ فاستعدى عليه عمرو بن حميد القاضي وقال هذا شتم صفية بنت عبد المطلب واجتمع عليه الغوغاء فهرب دعبل وبعث القاضي إلى دار دعبل فوكل بها وختم بابه فوجه إليه برقعة فيها ما رأيت قط أجهل منك إلا من ولاك فإنه أهل يقضي في العربدة على النبيذ ويحكم على خصم غائب ويقبل عقلك أني رافضي شتم صفية بنت عبد المطلب سخنت عينك أفمن دين الرافضة شتم صفية قال أبي فسألني الزبيري القاضي عن هذا الحديث فحدثته فقال صدق والله دعبل في قوله لو كنت مكانه لوصلته وبررته أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني إبراهيم بن سهل القارىء قال حدثني دعبل قال كتبت إلى أبي نهشل بن حميد وقد كان نسك وترك شرب النبيذ ولزم دار الحرم\n(إنما العيش في منادمة الإخوان لا في الجلوس عند الكعاب ... )\n(وبصرف كأنها ألسن البرق ... إذا استعرضت رقيق السحاب)\n(إن تكونوا تركتم لذة العيش ... حذار العقاب يوم العقاب)\n(فدعوني وما ألذ وأهوى ... وادفعو بي في نحر يوم الحساب)\nال فكان بعد ذلك يدعوني وسائر ندمائي فنشرب بين يديه ويستمع الغناء ويقتصر على الأنس والحديث أخبرني الحسن قال حدثنا ابن مهرويه قال حدثنا إبراهيم بن المدبر قال كنت أنا وإبراهيم بن العباس رفيقين نتكسب بالشعر قال و أنشدني قصيدة دعبل في المطلب بن عبد الله\n(أمطلب أنت مستعذب ... سمام الأفاعي ومستقبل)\nقال وقال لي دعبل نصفها لإبراهيم بن العباس كنت أقول مصراعا فيجيزه ويقول هو مصراعا فأجيزه قال ابن مهرويه وحدثني إبراهيم بن المدبر أن دعبلا قصد مالك بن طوق ومدحه فلم يرض ثوابه فخرج عنه وقال فيه\n(إن ابن طوق وبنى تغلب ... لو قتلوا أو جرحوا قصره)\n(لم يأخذوا من دية درهما ... يوما ولا من أرشهم بعره)\n(دماؤهم ليس لها طالب ... مطلولة مثل دم العذره)\n(وجوههم بيض وأحسابهم ... سود وفي آذانهم صفره)\nحدثنا محمد بن عمران الصيرفي قال حدثني العنزي قال حدثنا عبد الله بن الحسن قال حدثني عمر بن عبد الله أبو حفص النحوي مؤدب آل طاهر قال دخل دعبل بن علي على عبد الله بن طاهر فأنشده وهو ببغداد\n(جئت بلا حرمة ولا سبب ... إليك إلا بحرمة الأدب)\n(فاقض ذمامي فإنني رجل ... غير ملح عليك في الطلب)\nال فانتعل عبد الله ودخل إلى الحرم ووجه إليه بصرة فيها ألف درهم وكتب إليه\n(أعجلتنا فأتاك عاجل برنا ... ولو انتظرت كثيره لم يقلل)\n(فخذ القليل وكن كأنك لم تسل ... ونكون نحن كأننا لم نفعل)\nخبرني أحمد بن عاصم الحلواني قال حدثنا أبو بكر المدائني قال حدثنا أبو طالب الجعفري ومحمد بن أمية الشاعر جميعا قالا هجا دعبل بن علي مالك بن طوق فقال\n(سألت عنكم يا بني مالك ... في نازح الأرضين والدانيه)\n(طرا فلم تعرف لكم نسبة ... حتى إذا قلت بني الزانية)\n(قالوا فدع دارا على يمنة ... وتلك ها دارهم ثانيه)\n(لا حد أخشاه على ... من قال أمك زانيه)\nقال أيضا في\n(يا زاني ابن الزان إبن ... الزان إبن الزانية)\n(أنت المردد في الزناء ... على السنين الخاليه)\n(ومردد فيه على ... كر السنين الباقيه)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":22,"spl":"يهرب بعد اتهامه بشتم صفية بنت عبد المطلب","partial":1},
{"id":"b257-27","bab":"الجزء 20","sec":"يهرب بعد اتهامه بشتم صفية بنت عبد المطلب","page":"ج20 ص196","text":"وبلغت الأبيات مالكا فطلبه فهرب فأتى البصرة وعليها إسحاق بن العباس بن علي بن عبد الله بن العباس بن عبد المطلب وكان بلغه هجاء دعبل وابن أبي عيينة نزارا فأما ابن أبي عيينة فإنه هرب منه فلم يظهر بالبصرة طول أيامه وأما دعبل فإنه حين دخل البصرة بعث فقبض عليه ودعا بالنطع والسيف ليضرب عنقه فجحد القصيدة وحلف بالطلاق على جحدها وبكل يمين تبرىء من الدم أنه لم يقلها وأن عدوا له قالها إما أبو سعد المخزومي أو غيره ونسبها إليه ليغري بدمه وجعل يتضرع إليه ويقبل الأرض ويبكي بين يديه فرق له فقال أما إذا أعقيتك من القتل فلا بد من أن أشهرك ثم دعا بالعصا فضربه حتى سلح وأمر به فألقي على قفاه وفتح فمه فرد سلحه فيه والمقارع تأخذ رجليه وهو يحلف ألا يكف عنه حتى يستوفيه ويبلعه أو يقتله فما رفعت عنه حتى بلع سلحه كله ثم خلاه فهرب إلى الأهواز وبعث مالك بن طوق رجلا حصيفا مقداما وأعطاه سما وأمره أن يغتاله كيف شاء وأعطاه على ذلك عشرة آلاف درهم لم يزل يطلبه حتى وجده في قرية من نواحي السوس فاغتاله في وقت من الأوقات بعد صلاة العتمة فضرب ظهر قدمه بعكاز لها زج مسموم فمات من غد ودفن بتلك القرية وقيل بل حمل إلى السوس فدفن فيها وأمر إسحاق بن العباس شاعرا يقال له الحسن بن زيد ويكنى أبا الذلفاء فنقض قصيدتي دعبل وابن أبي عيينة بقصيدة أولها\n(أما تنفك متبولا حزينا ... تحب البيض تعصي العاذلينا)\nهجو بها قبائل اليمن ويذكر مثالبهم وأمره بتفسير ما نظمه وذكر الأيام والأحوال ففعل ذلك وسماها الدامغة وهي إلى اليوم موجودة صوت\n(أتهجر من تحب بغير جرم ... أسأت إذا وأنت له ظلوم)\n(تؤرقني الهموم وأنت خلو ... لعمرك ما تؤرقك الهموم)\nلشعر لجعيفران الموسوس أنشدنيه عمي عن عبد الله بن عثمان الكاتب عن أبيه عن جده وأنشد فيه جحظة عن خالد الكاتب له وأنشدنيه ابن الوشاء عن بعض شيوخه عن سلمة النحوي له ووجدته في بعض الكتب منسوبا إلى أم الضحاك المحاربية والقول الأول أصح والغناء لابن أبي قباحة ثاني ثقيل بالوسطى في مجرى البنصر وفي أبيات أخر من شعر جعيفران غناء فإن لم يصح هذا له فالغناء له في أشعاره الأخر صحيح منها\n(ما يفعل المرء فهو أهله ... كل امرئ يشبهه فعله)\n(ولا ترى أعجز من عاجز ... سكتنا عن ذمه بذله)\nلشعر لجعيفران والغناء لمتيم ومما وجدته من الشعر المنسوب إليه في جامعه وفيه له غناء\n(قلبي بصاحبة الشنوف معلق ... وتفر صاحبة الشنوف وألحق)","topic":"أخبار دعبل بن علي ونسبه","topicNo":257,"sp":23,"spl":"يهرب بعد اتهامه بشتم صفية بنت عبد المطلب"}]);
window.__BOOK__['p10'].push([{"id":"b258-1","bab":"الجزء 20","sec":"أخبار جعيفران ونسبه","page":"ج20 ص202","text":"هو جعيفران بن علي بن أصفر بن السري بن عبد الرحمن الأبناوي من ساكني سر من رأى ومولده ومنشؤه ببغداد وكان أبوه من أبناء الجند الخراسانية وكان يتشيع ويكثر لقاء أبي الحسن علي بن موسى بن جعفر أخبرني بذلك أبو الحسن علي بن العباس بن أبي طلحة الكاتب عن أبيه وأهله وكان جعيفران أديبا شاعرا مطبوعا وغلبت عليه المرة السوداء فاختلط وبطل في أكثر أوقاته ومعظم أحواله ثم كان إذا أفاق ثاب إليه عقله وطبعه فقال الشعر الجيد وكان أهله يزعمون أنه من العجم ولد أذين فأخبرني الحسن بن علي الخفاف قال حدثني محمد بن مهرويه قال حدثني علي بن سليمان النوفلي قال حدثني صالح بن عطية قال كان لجعيفران الموسوس قبل أن يختلط عقله أب يقال له علي بن أصفر وكان دهقان الكرخ ببغداد وكان يتشيع فظهر على ابنه جعيفران أنه خالفه إلى جارية له سرية فطرده عن داره\nوحج فشكا ذلك إلى موسى بن جعفر فقال له موسى إن كنت صادقا عليه فليس يموت حتى يفقد عقله وإن كنت قد تحققت ذلك عليه فلا تساكنه في منزلك ولا تطعمه شيئا من مالك في حياتك وأخرجه عن ميراثك بعد وفاتك فقدم فطرده وأخرجه من منزله وسأله الفقهاءعن حيلة يشهد بها في ماله حتى يخرجه عن ميراثه فدلوه على السبيل إلى ذلك فأشهد به وأوصى إلى رجل فلما مات الرجل حاز ميراثه ومنع منه جعيفران فاستعدى عليه أبا يوسف القاضي فأحضر الوصي وسأل جعيفران البينة على نسبه وتركة أبيه فأقام على ذلك بينة عدة وأحضر الوصي بينة عدولا على الوصية يشهدون على أبيه بما كان احتال به عليه فلم ير أبو يوسف ذلك شيئا وعزم على أن يورثه فدفعه الوصي عن ذلك مرات بعلل ثم عزم أبو يوسف على أن يسجل لجعيفران بالمال فقال له الوصي أيها القاضي أنا أدفع هذا بحجة واحدة بقيت عندي فأبى أبو يوسف أن يقبل منه وجعل جعيفران يحرج عليه ويقول له قد ثبت عندك أمري فبأي شيء تدافعني وجعل الوصي يسأله أن يسمع منه منفردا فيأبى ويقول لا أسمع منك إلا بحضرة خصمك فقال له أجلني إلى غد فأجله فجاء إلى منزله وكتب رقعة خبره فيها بحقيقة ما أفتى به موسى بن جعفر ودفعها إلى صديق لأبي يوسف فدفعها إليه فلما قرأها دعا الوصي واستحلفه أنه قد صدق في ذلك فحلف باليمين الغموس فقال له اغد علي غدا مع صاحبك فحضر وحضر جعيفران معه فحكم عليه أبو يوسف للوصي فلما أمضى الحكم عليه وسوس جعيفران واختلط منذ يومئذ وأخبرني بجمل أخباره المذكورة في هذا الكتاب علي بن العباس بن أبي\nطلحة الكاتب عن شيوخ له أخذها عنهم وإجازات وجدتها في الكتب ولم أر أخباره عند أحد أكثر مما وجدتها إلا ما أذكره عن غيره فأنسبه إليه قال علي بن العباس وذكر عبد الله بن عثمان الكاتب أن أباه عثمان بن محمد حدثه قال كنت يوما برصافة مدينة السلام جالسا إذ جاءني جعيفران وهو مغضب فوقف علي وقال\n(استوجب العالم مني القتلا ... )\nقلت ولم يا أبا الفضل فنظر إلي نظرة منكرة خفت منها وقال\n(لما شعرت فرأوني فحلا ... )\nم سكت هنيهة وقال\n(قالوا علي كذبا وبطلا ... إني مجنون فقدت العقلا)\n(قالوا المحال كذبا وجهلا ... أقبح بهذا الفعل منهم فعلا)\nثم ذهب لينصرف فخفت أن يؤذيه الصبيان فقلت اصبر فديتك حتى أقوم معك فإنك مغضب وأكره أن تخرج على هذه الحال فرجع إلي وقال سبحان الله أتراني أنسبهم إلى الكذب والجهل وأستقبح فعلهم وتتخوف مني مكافأتهم ثم إنه ولى وهو يقول\n(لست براض من جهول جهلا ... ولا مجازيه بفعل فعلا)\n(لكن أرى الصفح لنفسي فضلا ... من يرد الخير يجده سهلا)\nم مضى وقال علي بن العباس وقال عثمان بن محمد قال أبي كنت أشرف مرة من سطح لي على جعيفران وهو في دار وحده وقد\nاعتل وتحركت عليه السوداء فهو يدور في الدار طول ليلته ويقول\n(طاف به طيف من الوسواس ... نفر عنه لذة النعاس)\n(فما يرى يأنس بالأناس ... ولا يلذ عشرة الجلاس)\n(فهو غريب بين هذا الناس ... )\nتى أصبح وهو يرددها ثم سقط كأنه بقلة ذابلة قال علي وحدثني علي بن رستم النحوي قال حدثني سلمة بن محارب قال مررت ببغداد فرأيت قوما مجتمعين على رجل فقلت ما هذا فقالوا جعيفران المجنون فقلت قل بيتا بنصف درهم قال هاته فأعطيته فقال\n(لج ذا الهم واعتلج ... كل هم إلى فرج)","topic":"أخبار جعيفران ونسبه","topicNo":258,"sp":0,"spl":"أخبار جعيفران ونسبه","partial":1},
{"id":"b258-2","bab":"الجزء 20","sec":"أخبار جعيفران ونسبه","page":"ج20 ص202","text":"م قال زد إن شئت حتى أزيدك قال علي وحدثني عبد الله بن عثمان عن أبيه قال غاب عنا جعيفران أياما ثم جاءنا والصبيان يشدون خلفه وهو عريان وهم يصيحون به يا جعيفران يا خرا في الدار فلما بلغ إلي وقف وتفرقوا عنه فقال يا أبا عبد الله\n(رأيت الناس يدعوني ... بمجنون على حالي)\n(وما بي اليوم من جن ... ولا وسواس بلبال)\n(ولكن قولهم هذا ... لإفلاسي وإقلالي)\n(ولو كنت أخا وفر ... رخيا ناعم البال)\n(رأوني حسن العقل ... أحل المنزل العالي)\n(وما ذاك على خبر ... ولكن هيبة المال)\nقال فأدخلته منزلي فأكل وسقيته أقداحا ثم قلت له تقدر على أن تغير القافية فقال نعم ثم قال بديهة غير مفكر ولا متوقف\n(رأيت الناس يرموني ... أحيانا بوسواس)\n(ومن يضبط يا صاح ... مقال الناس في الناس)\n(فدع ما قاله الناس ... ونازع صفوة الكاس)\n(فتى حرا صحيح الودذ ... بر وإيناس)\n(فإن الخلق مغرور ... بأمثالي وأجناسي)\n(ولو كنت أخا مال ... أتوني بين جلاسي)\nيحبوني ويحبوني ... على العينين والراس ويدعوني عزيزا غير ... أن الذل إفلاسي\nثم قام يبول فقال بعض من حضر أي شيء معنى عشرتنا هذا المجنون العريان والله ما نأمنه وهو صاح فكيف إذا سكر وفطن جعيفران للمعنى فخرج إلينا وهو يقول\n(وندامى أكلوني ... إذ تغيبت قليلا)\n(زعموا أني مجنون ... أرى العري جميلا)\n(كيف لا أعرى وما أبصر ... في الناس مثيلا)\nإن يكن قد ساءكم قربي ... فخلوا لي سبيلا وأتموا يومكم ... سركم الله طويلا\nال فرققنا له واعتذرنا إليه وقلنا له والله ما نلتذ إلا بقربك وأتيناه بثوب فلبسه وأتممنا يومنا ذلك معه أخبرني جحظة قال حدثني ميمون بن هارون قال تقدم جعيفران إلى أبي يوسف الأعور القاضي بسر من رأى في حكومة في شيء كان في يده من وقف له فدفعه عنه وقضى عليه فقال له أراني الله أيها القاضي عينيك سواء فأمسك عنه وأمر برده إلى داره فلما رجع أطعمه ووهب له دراهم ثم دعا به فقال له ماذا أردت بدعائك أردت أن يرد الله على بصري ما ذهب فقال له والله لئن كنت وهبت لي هذه الدراهم لأسخر منك لأنت المجنون لا أنا أخبرني كم من أعور رأيته عمي قال كثيرا قال فهل رأيت أعور صح قط قال لا قال فكيف توهمت علي الغلط فضحك وصرفه","topic":"أخبار جعيفران ونسبه","topicNo":258,"sp":1,"spl":"أخبار جعيفران ونسبه"},
{"id":"b258-3","bab":"الجزء 20","sec":"جعيفران يمدح أبا دلف","page":"ج20 ص207","text":"أخبرني محمد بن جعفر النحوي صهر المبرد قال حدثني أحمد بن القاسم البرتي قال حدثني علي بن يوسف قال كنت عند أبي دلف القاسم بن عيسى العجلي فاستأذن عليه حاجبه لجعيفران الموسوس فقال له أي شيء اصنع بموسوس قد قضينا حقوق العقلاء وبقي علينا حقوق المجانين فقلت له جعلت فداء الأمير موسوس أفضل كثير من العقلاء وإن له لسانا يتقى وقولا مأثورا يبقى فالله الله أن تحجبه فليس عليك منه أذى ولا ثقل فأذن له فلما مثل بين يديه قال\n(يا أكرم العالم موجودا ... ويا أعز الناس مفقودا)\n(لما سألت الناس عن واحد ... أصبح في الأمة محمودا)\n(قالوا جميعا إنه قاسم ... أشبه آباء له صيدا)\n(لو عبدوا شيئا سوى ربهم ... أصبحت في الأمة معبودا)\n(لا زلت في نعمى وفي غبطة ... مكرما في الناس معدودا)\nال فأمر له بكسوة وبألف درهم فلما جاء بالدراهم أخذ منها عشرة وقال تأمر القهرمان أن يعطيني الباقي مفرقا كلما جئت لئلا يضيع مني فقال للقهرمان أعطه المال وكلما جاءك فأعطه ما شاء حتى يفرق الموت بيننا فبكى عند ذلك جعيفران وتنفس الصعداء وقال\n(يموت هذا الذي أراه ... وكل شيء له نفاد)\n(لو غير ذي العرش دام شيء ... لدام ذا المفضل الجواد)\nم خرج فقال أبو دلف أنت كنت أعلم به مني قال وغير عني مدة ثم لقيني وقال يا أبا الحسن ما فعل أميرنا وسيدنا وكيف حاله فقلت بخير وعلى غاية الشوق إليك فقال أنا والله يا أخي أشوق ولكني أعرف أهل العسكر وشرههم وإلحاحهم والله ما أراهم يتركونه من المسألة ولا يتركهم كرمه أن يخليهم من العطية حتى يخرج فقيرا فقلت دع هذا عنك وزره فإن كثرة السؤال لا تضر بماله فقال وكيف أهو أيسر من الخليفة قلت لا قال والله لو تبذل لهم الخليفة كما يبذل أبو دلف وأطعمهم في ماله كما يطعمهم لأفقروه في يومين ولكن اسمع ما قلته في وقتي فقلت هاته يا أبا الفضل فأنشأ يقول\n(أبا حسن بلغن قاسما ... بأني لم أجفه عن قلبي)\n(ولا عن ملال لإتيانه ... ولا عن صدود ولا عن غنى)\n(ولكن تعففت عن ماله ... وأصفيته مدحتي والثنا)\n(أبو دلف سيد ماجد ... سني العطية رحب الفنا)\n(كريم إذا انتابه المعتفون ... عمهم بجزيل الحبا)\nال فأبلغتها أبا دلف وحدثته بالحديث الذي جرى فقال لي قد لقيته منذ أيام فلما رأيته وقفت له وسلمت عليه وتحفيت به فقال لي سر أيها الأمير على بركة الله ثم قال لي\n(يا معدي الجود على الأموال ... ويا كريم النفس في الفعال)\n(قد صنتني عن ذلة السؤال ... بجودك الموفي على الآمال)\n(صانك ذو العزة والجلال ... من غير الأيام والليالي)\nال ولم يزل يختلف إلى أبي دلف ويبره حتى افترقا","topic":"أخبار جعيفران ونسبه","topicNo":258,"sp":2,"spl":"جعيفران يمدح أبا دلف — جعيفران يهجو نفسه"},
{"id":"b258-4","bab":"الجزء 20","sec":"جعيفران يهجو نفسه","page":"ج20 ص209","text":"سمعت عبد الله بن أحمد عم أبي رحمه الله يحدث فحفظت الخبر ولا أدري أذكر له إسنادا فلم أحفظه أم ذكره بغير إسناد قال كان جعيفران خبيث اللسان هجاء لا يسلم عليه أحد فاطلع يوما في الحب فرأى وجهه قد تغير وعفا شعره فقال\n(ما جعفر لأبيه ... ولا له بشبيه)\n(أضحى لقوم كثير ... فكلهم يدعيه)\n(هذا يقول بنيي ... وذا يخاصم فيه)\n(والأم تضحك منهم ... لعلمها بأبيه)\nحدثني محمد بن الحسن الكندي خطيب القادسية قال حدثني رجل من كتاب الكوفة قال اجتاز بي جعيفران مرة فقال أنا جائع فأي شيء عندك تطعمني فقلت سلق بخردل فقال اشتر لي معه بطيخا فقلت أفعل فادخل وبعثت بالجارية تجيئه به وقدمت إليه الخبز والخردل والسلق فأكل منه حتى ضجر وأبطأت الجارية فأقبل علي وقد غضب فقال\n(سلقتنا وخردلت ... ثم ولت فأدبرت)\n(وأراها بواحد ... وافر الأير قد خلت)\nال فخرجت يشهد الله أطلبها فوجدتها خالية في الدهليز بسائس لي علي ما وصف صوت\n(ولها مربع ببرقة خاخ ... ومصيف بالقصر قصر قباء)\n(كفنوني إن مت في درع أروى ... واجعلوا لي من بئر عروة مائي)\n(سخنة في الشتاء باردة الصيف ... سراج في الليلة الظلماء)\nلشعر للسري بن عبد الرحمن والغناء لمعبد ثقيل أول بالوسطى\nعن الهشامي قال وفيهما يعني الثالث والأول رمل مطلق في مجرى الوسطى","topic":"أخبار جعيفران ونسبه","topicNo":258,"sp":2,"spl":"جعيفران يمدح أبا دلف — جعيفران يهجو نفسه"},
{"id":"b259-1","bab":"الجزء 20","sec":"أخبار السري ونسبه","page":"ج20 ص212","text":"السري بن عبد الرحمن بن عتبة بن عويم بن ساعدة الأنصاري ولجده عويم بن ساعدة صحبة بالنبي والسري شاعر من شعراء أهل المدينة وليس بمكثر ولا فحل إلا أنه كان أحد الغزلين والفتيان والمنادمين على الشراب كان هو وعتير بن سهل بن عبد الرحمن بن عوف وجبير بن أيمن وخالد بن أبي أيوب الأنصاري يتنادمون قال وفيهم يقول\n(إذا أنت نادمت العتير وذا الندى ... جبيرا ونازعت الزجاجة خالدا)\n(أمنت بإذن الله أن تقرع العصا ... وأن ينبهوا من نومة السكر راقدا)\nناه الغريض ثقيلا\nوكان السري هذا هجا الأحوص وهجا نصيبا فلم يجيباه أخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني عمي وأخبرني الحسين بن يحيى المرداسي قال حدثنا حماد بن إسحاق عن أبيه عن ابن الكلبي قالا حبس النصيب في مسجد النبي فأنشد وكان إذا أنشد لوي حاجبيه وأشار بيده فرآه السري بن عبد الرحمن الأنصاري فجاءه حتى وقف بإزائه ثم قال\n(فقدت الشعر حين أتى نصيبا ... ألم تستحي من مقت الكرام)\n(إذا رفع ابن ثوبة حاجبيه ... حسبت الكلب يضرب في الكعام)\nال فقال نصيب من هذا فقالوا هذا ابن عويم الأنصاري قال قد وهبته لله عز و جل ولرسوله ولعويم بن ساعدة قال وكان لعويم صحبة ونصرة أخبرني الحرمي قال حدثنا الزبير قال حدثني عمي عن عبد الرحمن بن عبد الله العمري قال كان السري قصيرا دميما أزرق وكان يهوى\nامرأة يقال لها زينب ويشبب بها فخرج إلى البادية فرآها في نسوة فصار إلى راع هناك وأعطاه ثيابه وأخذ منه جبته وعصاه وأقبل يسوق الغنم حتى صار إلى النسوة فلم يحفلن به وظنن أنه أعرابي فأقبل يقلب بعصاه الأرض وينظر إليهن فقلن له أذهب منك يا راعي الغنم شيء فأنت تطلبه فقال نعم قال فضربت زينب بكمها على وجهها وقالت السري والله أخزاه الله فأنشأ يقول صوت\n(ما زال فينا سقيم يستطب له ... من ريح زينب فينا ليلة الأحد)\n(حزت الجمال ونشرا طيبا أرجا ... فما تسمين إلا مسكة البلد)\n(أما فؤادي فشيء قد ذهبت به ... فما يضرك ألا تحربي جسدي)","topic":"أخبار السري ونسبه","topicNo":259,"sp":0,"spl":"أخبار السري ونسبه"},
{"id":"b259-2","bab":"الجزء 20","sec":"المهدي يستحسن شعره في الغزل","page":"ج20 ص214","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن أبي خيثمة قال حدثنا مصعب الزبيري قال قال أبي قال لي المهدي أنشدني شعرا غزلا فأنشدته قول السري بن عبد الرحمن\n(ما زال فينا سقيم يستطب له ... من ريح زينب فينا ليلة الأحد)\nأعجبته وما زال يستعيدها مرارا حتى حفظها أخبرني الحسن قال حدثني أحمد قال حدثني محمد بن سلام\nالجمحي قال كان السري بن عبد الرحمن ينادم عتير بن سهل بن عبد الرحمن بن عوف وجبير بن أيمن بن أم أيمن مولى النبي وخالد بن أيوب الأنصاري وكانوا يشربون النبيذ وكلهم كان على ذلك مقبول الشهادة جليل القدر مستورا فقال السري\n(إذا أنت نادمت العتير وذا الندى ... جبيرا ونازعت الزجاجة خالدا)\n(أمنت بإذن الله أن تقرع العصا ... وأن ينبهوا من نومة السكر راقدا)\nقالوا قبحك الله ماذا أردت إلى التنبيه علينا والإذاعة لسرنا إنك لحقيق ألا ننادمك قال والله ما أردت بكم سوءا ولكنه شعر طفح فنفثته عن صدري قال وخالد بن أبي أيوب الأنصار ي الذي يقول صوت\n(ألا سقني كأسي ودع قول من لحى ... ورو عظاما قصرهن إلى بلى)\n(فإن بطوء الكأس موت وحبسها ... وإن دراك الكأس عندي هو الحيا)\nلغناء في هذين البيتين هو لعبد الله بن العباس الربيعي خفيف رمل بالبنصر عن عمرو بن بانة\nأخبرني أبو الحسن الأسدي قال حدثني سليمان بن أبي شيخ قال حدثني مصعب بن عبد الله الزبيري قال حدثني مصعب بن عثمان قال حدثني عبيد الله بن عروة بن الزبير قال خرجت وأنا غلام أدور في السكك بالمدينة فانتهيت إلى فناء مرشوش وشاب جميل الوجه جالس فلما رآني دعاني ثم قال لي من أنت يا غلام فقلت عبيد الله بن عروة بن الزبير فقال اجلس فجلست فدعا بالغداء فتغدينا جميعا ثم قال يا جارية فأقبلت جارية تتهادى كأنها مهاة وفي يدها قنينية فيها شراب صاف وقلة ماء وكأس فقال لها اسقيني فصبت في الكأس وسكبت عليه ماء وناولته فشرب ثم قال اسقيه فصبت في الكأس وسكبت عليه ماء وناولتني فلما وجدت رائحته بكيت فقال ما يبكيك يا بن أخي فقلت إن أهلي إن وجدوا رائحة هذامني ضربوني فأقبل على الجارية بوجهه وقال لها يخاطبها\n(ألا سقني كأسي ودع عنك من أبى ... ورو عظاما قصرهن إلى بلى)\nأخذته من يدي وأعطته فشربه وقمت فلما جاوزته سألت عنه فقيل لي هذا خالد بن أبي أيوب الأنصاري الذي يقول فيه الشاعر\n(إذا أنت نادمت العتير وذا الندى ... جبيرا ونازعت الزجاجة خالدا)\n(أمنت بإذن الله أن تقرع العصا ... وأن يوقظوا من سكرة النوم راقدا)\n(وصرت بحمد الله في خير عصبة ... حسان الندامى لا تخاف العرابدا)","topic":"أخبار السري ونسبه","topicNo":259,"sp":1,"spl":"المهدي يستحسن شعره في الغزل"},
{"id":"b259-3","bab":"الجزء 20","sec":"السري وابن الماجشون","page":"ج20 ص217","text":"أخبرنا وكيع قال حدثنا محمد بن علي بن حمزة قال حدثني أبو غسان عن محمد بن يحيى بن عبد الحميد قال كان السري بن عبد الرحمن يختلف إلى فتية فجاء ابن الماجشون فقال لا أدخل حتى يخرج السري فأخرجته فقال السري\n(قبح الله أهل بيت بسلع ... أخرجوني وأدخلوا الماجشونا)\n(أدخلوا هرة تلاعب قردا ... ما نراهم يرون ما يصنعونا)\nخبرني الحسن قال حدثنا أحمد بن زهير قال حدثني مصعب قال أنشدني أبي للسري بن عبد الرحمن في أمة الحميد بنت عبد الله بن عباس وفي ابنتها أمة الواحد\n(أمة الحميد وبنتها ... ظبيان في ظل الأراك)\n(يتتبعان بريره ... وظلاله فهما كذاك)\n(حذي الجمال عليهما ... حذو الشراك على الشراك)\nخبرني محمد بن العباس اليزيدي قال حدثني محمد بن الحسن بن مسعود الزرقي قال حدثني يحيى بن عثمان بن أبي قباحة الزهري قال أنشدني أبو غسان صالح بن العباس بن محمد وهو إذ ذاك على المدينةللسري بن عبد الرحمن\n(ليتني في المؤذنين نهارا ... إنهم يبصرون من في السطوح)\n(فيشيرون أو يشار إليهم ... حبذا كل ذات جيد مليح)\nال فأمر صالح بسد المنار فلم يقدر أحد على أن يطلع رأسه حتى عزل صالح أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن شبيب قال حدثني زبير بن بكار عن عمه\nأن السري بن عبد الرحمن وقف على عمر بن عمرو بن عثمان وهو جالس على بابه والناس حوله فأنشأ يقول\n(با بن عثمان يا بن خير قريش ... أبغني ما يكفني بقباء)\n(ربما بلني نداك وجلى ... عن جبيني عجاجة الغرماء)\nأعمره أرضا بقباء وجعلها طعمة له أيام حياته فلم تزل في يده حتى مات أخبرني وسواسة بن الموصلي قال حدثني حماد بن إسحاق عن أبيه عن عزيز بن طلحة قال قال معبد خرجت من مكة أريد المدينة فلما كنت قريبا من المنزل أريت بيتا فعدلت إليه فإذا فيه أسود عنده حبان من ماء وقد جهدني العطش فسلمت عليه واستسقيت فقال تأخر عافاك الله فقلت يا هذا اسقني بسرعة من الماء فقد كدت أموت عطشا فقال والله لا تذوق منه جرعة ولو مت فرجعت القهقرى وأنخت راحلتي واستظللت بظلها من الشمس ثم اندفعت أغني ليبتل لساني\n(كفنوني إن مت في درع أروى ... واستقوا لي من بئر عروة مائي)\nفإذا أنا بالأسود قد خرج إلي ومعه قدح خيشاني فيه سويق ملت بماء بارد فقال هل لك في هذا أرب قلت قد منعتني ما هو أقل منه الماء فقال اشرب عافاك الله ودع عنك ما مضى فشربت ثم قال أعد فديتك الصوت فأعدته فقال هل لك بأبي وأمي أن أحمل لك قربة من ماء وأمشي بها معك إلى المنزل وتعيد علي هذا الصوت حتى أتزود منه وكلما عطشت سقيتك قلت افعل ففعل وسارمعي فما زلت أغنيه إياه وكلما عطشت استقيته حتى بلغت المنزل عشاء صوت\n(سلب الشباب رداءه ... عني ويتبعه إزاره)\n(ولقد تحل علي حلته ... ويعجبني افتخاره)\n(سائل شبابي هل مست ... بسوءة أو ذل جاره)\n(ما إن ملكت المال إلا ... كان لي وله خياره)\nيروى هل أسأت مساكه الشعر لمسكين الدارمي والغناء لمقاسه بن ناصح خفيف رمل بالبنصر عن عمرو","topic":"أخبار السري ونسبه","topicNo":259,"sp":2,"spl":"السري وابن الماجشون"},
{"id":"b260-1","bab":"الجزء 20","sec":"أخبار مسكين ونسبه","page":"ج20 ص220","text":"مسكين لقب غلب عليه واسمه ربيعة بن عامر بن أنيف بن شريح بن عمرو بن زيد بن عبد الله بن عدس بن دارم بن مالك بن زيد مناة بن تميم وقال أبو عمرو الشيباني مسكين بن أنيف بن شريح بن عمرو بن عدس بن زيد بن عبد الله بن دارم بن مالك بن حنظلة بن مالك بن زيد مناة بن تميم قال أبو عمرو وإنما لقب مسكينا لقوله\n(أنا مسكين لمن أنكرني ... ولمن يعرفني جد نطق)\n(لا أبيع الناس عرضي إنني ... لو أبيع الناس عرضي لنفق)\nقال أيضا\n(سميت مسكينا وكانت لجاجة ... وإني لمسكين إلى الله راغب)\nقال أيضا\n(إن أدع مسكينا فلست بمنكر ... وهل ينكرن الشمس ذر شعاعها)\n(لعمرك ما الأسماء إلا علامة ... منار ومن خير المنار ارتفاعها)\nشاعر شريف من سادات قومه هاجى الفرزدق ثم كافه فكان الفرزدق بعد ذلك في الشدائد التي أفلت منها","topic":"أخبار مسكين ونسبه","topicNo":260,"sp":0,"spl":"أخبار مسكين ونسبه — مسكين والفرزدق"},
{"id":"b260-2","bab":"الجزء 20","sec":"مسكين والفرزدق","page":"ج20 ص221","text":"حدثني حبيب بن أوس بن نصر المهلبي قال حدثنا عمر بن شبة عن أبي عبيدة قال كان زياد قد أرعى مسكينا الدارمي حمى له بناجية العذيب في عام قحط حتى أخصب الناس وأحيوا ثم كتب له بئر وتمر وكساه قال فلما مات زياد رثاه مسكين فقال\n(رأيت زيادة الإسلام ولت ... جهارا حين ودعنا زياد)\nفعارضه الفرزدق وكان منحرفا عن زياد لطلبه إياه وإخافته له فقال\n(أمسكين أبكى الله عينك إنما ... جرى في ضلال دمعها فتحدرا)\n(بكيت على علج بميسان كافر ... ككسرى على عدانه أو كقيصرا)\n(أقول له لما أتاني نعيه به ... لا بظبي بالصريمة أعفرا)\nقال مسكين يجيبه\n(ألا أيها المرء الذي لست قاعدا ... ولا قائما في القوم إلا انبرى ليا)\n(فجئني بعم مثل عمي أو أب ... كمثل أبي أو خال صدق كخاليا)\n(كعمرو بن عمرو أو زرارة ذي الندى ... أو البشر من كل فرعت الروابيا)\nال فأمسك الفرزدق عنه فلم يجبه وتكافا أخبرني ببعض هذا الخبر أو خليفة عن محمد بن سلام فذكر نحوا مما ذكره أبو عبيدة وزاد فيه قال والبشر خال لمسكين من النمر بن قاسط وقد فخربه فقال\n(شريح فارس النعمان عمي ... وخالي البشر بشر بني هلال)\n(وقاتل خاله بأبيه منا ... سماعة لم يبع حسبا بمال)\nأخبرني عمي قال حدثنا الحزنبل عن عمرو بن أبي عمرو عن أبيه بمثل هذه الحكاية وزاد فيها قال فتكافا واتقاه الفرزدق أن يعين عليه جريرا واتقاه مسكين أن يعين عليه عبد الرحمن بن حسان بن ثابت ودخل شيوخ بني عبد الله وبني مجاشع فتكافا وأخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة عن أبي عمرو قال قال الفرزدق نجوت من ثلاثة أشياء لا أخاف بعدها شيئا نجوت من زياد حين طلبني ونجوت من ابني رميلة وقد نذرا دمي وما فاتهما أحد طلباه قط ونجوت من مهاجاة مسكين الدارمي لأنه لو هجاني اضطرني أن أهدم شطر حسبي وفخري لأنه من بحبوحة نسبي وأشراف عشيرتي فكان جرير حينئذ ينتصف من بيدي ولساني أخبرني أحمد بن عبيد الله بن عمار قال حدثني محمود بن داود عن\nأبي عكرمة عامر بن عمران عن مسعود بن بشر عن أبي عبيدة أنه سمعه يقول أشعر ما قيل في الغيرة قول مسكين الدارمي\n(ألا أيها الغائر المستشيط ... فيم تغار إذا لم تغر)\n(فما خير عرس إذا خفتها ... وما خير عرس إذا لم تزر)\n(تغار على الناس أن ينظروا ... وهل يفتن الصالحات النظر)\n(وإني سأخلي لها بيتها ... فتحفظ لي نفسها أو تذر)\n(إذ الله لم يعطني حبها ... فلن يعطي الحب سوط ممر)","topic":"أخبار مسكين ونسبه","topicNo":260,"sp":0,"spl":"أخبار مسكين ونسبه — مسكين والفرزدق"},
{"id":"b260-3","bab":"الجزء 20","sec":"مسكين ومعاوية","page":"ج20 ص223","text":"أخبرني هاشم بن محمد الخزاعي قال حدثني عبد الله بن عمرو بن أبي سعد قال حدثني عبد الله بن مالك الخزاعي قال حدثني عبد الله بن بشير قال أخبرني أيوب بن أبي أيوب السعدي قال لما قدم مسكين الدارمي على معاوية فسأله أن يفرض له فأبى عليه وكان لا يفرض إلا لليمن فخرج من عنده مسكين وهو يقول\n(أخاك أخاك إن من لا أخا ... له كساع إلى الهيجا بغير سلاح)\n(وإن ابن عم المرء فاعلم جناحه ... وهل ينهض البازي بغير جناح)\n(وما طالب الحاجات إلا مغرر ... وما نال شيئا طالب كنجاح)\nقال السعدي فلم يزل معاوية كذلك حتى غزت اليمن وكثرت وضعضعت عدنان فبلغ معاوية أن رجلا من أهل اليمن قال يوما لهممت ألا أدع بالشأم أحدا من مضر بل هممت ألا أحل حبوتي حتى أخرج كل نزاري بالشأم فبلغت معاوية ففرض من وقته لأربعة آلاف رجل من قيس سوى خندف وقدم على تفيئة ذلك عطارد بن حاجب على معاوية فقال له ما فعل الفتى الدارمي الصبيح الوجه الفصيح اللسان يعني مسكينا فقال صالح يا أمير المؤمنين فقال أعلمه أني قد فرضت له في شرف العطاء وهو في بلاده فإن شاء أن يقيم بها أني قد فرضت له في شرف العطاء وهو في بلاده فإن شاء أن يقيم بها أو عندنا فليفعل فإن عطاءه سيأتيه وبشره أني قد فرضت لأربعة آلف من قومه من خندف قال وكان معاوية بعد ذلك يغزي اليمن في البحر ويغزي قيسا في البر فقال شاعر اليمن\n(ألا أيها القوم الذين تجمعوا ... بعكا أناس أنتم أم أباعر)\n(أتترك قيس آمنين بدارهم ... ونركب ظهر البحر والبحر زاخر)\n(فوالله ما أدري وإني لسائل ... أهمدان يحمى ضيمها أم يحابر)\n(أم الشرف الأعلى من أولاد حمير ... بنو مالك إذ تستمر المرائر)\n(أأوصى أبوهم بينهم أن تواصلوا ... وأوصى أبوكم بينكم أن تدابروا)\nال ويقال إن النجاشي قال هذه الأبيات أخبرني بذلك عبد الله بن أحمد بن الحارث العدوي عن محمد بن عائد\nعن الوليد بن مسلم عن إسماعيل بن عياش وغيره قالوا فلما بلغت هذه الأبيات معاوية بعث إلى اليمن فاعتذر إليهم وقال ما أغرينكم البحر إلا لأني أتيمن بكم وأن في قيس نكدا وأخلاقا لا يحتملها الثغر وأنا عارف بطاعتكم ونصحكم فأما إذ قد ظننتم غير ذلك فأنا أجمع فيه بينكم وبين قيس فتكونون جميعا فيه وأجعل الغزو فيه عقبا بينكم فرضوا فعل ذلك فيما بعد حدثني الحسن بن علي قال حدثنا أحمدبن زهير بن حرب قال حدثني مصعب بن عبد الله قال وحدثنيه زبير عن عمه قال كان أصاغر ولد مروان في حجر ابنه عبد العزيز بن مروان فكتب عبد العزيز إلى بشر كتابا وهو يومئذ على العراق فورد عليه وهو ثمل وكان فيه كلام أحفظه فأمر بشر كاتبه فأجاب عبد العزيز جوابا قبيحا فلما ورد عليه علم أنه كتبه وهو سكران فجفاه وقطع مكاتبته زمانا وبلغ بشرا عتبه عليه فكتب إليه لولا الهفوة لم احتج إلى العذر ولم يكن لك في قبوله مني الفضل ولو احتمل الكتاب أكثر مما ضمنته لزدت فيه وبقية الأكابر على الأصاغر من شيم الأكارم ولقد أحسن مسكين الدارمي حين يقول\n(أخاك أخاك إن من لا أخا له ... كساع إلى الهيجا بغير سلاح)\n(وإن ابن عم المرء فاعلم جناحه ... وهل ينهض البازي بغير جناح)\nال فلما وصل كتابه إلى عبد العزيز دمعت عينه وقال إن أخي كان منتشيا ولولا ذلك لما جرى منه ما جرى فسلوا عمن شهد ذلك المجلس فسئل عنهم فأخبر بهم فقبل عذره وأقسم عليه ألا يعاشر أحدا من ندمائه\nالذين حضروا ذلك المجلس وأن يعزل كاتبه عن كتابته ففعل أخبرني محمد بن الحسين الكندي خطيب القادسية قال حدثنا عمر بن شبة عن أبي عبيدة عن أبي عمرو قال كان الفرزدق يقول نجوت من ثلاث أرجو ألا يصيبني بعدهن شر نجوت من زياد حين طلبني وما فاته مطلوب قط ونجوت من ضربة رئاب بن رميلة أبي البذال فلم يقع في رأسي ونجوت من مهاجاة مسكين الدارمي ولو هاجيته لحال بيني وبين بيت بني عمي وقطع لساني عن الشعراء أخبرني محمد بن خلف بن المرزبان قال حدثنا أبو العيناء عن الأصمعي قال خطب مسكين الدارمي فتاة من قومه فكرهته لسواد لونه وقلة ماله وتزوجت بعده رجلا من قومه ذا يسار ليس له مثل نسب مسكين فمر بهما مسكين ذات يوم وتلك المرأة جالسة مع زوجها فقال\n(أنا مسكين لمن يعرفني ... لوني السمرة ألوان العرب)\n(من رأى ظبيا عليه لؤلؤ ... واضح الخدين مقرونا بضب)\n(أكسبته الورق البيض أبا ... ولقد كان وما يدعى لأب)","topic":"أخبار مسكين ونسبه","topicNo":260,"sp":1,"spl":"مسكين ومعاوية"},
{"id":"b260-4","bab":"الجزء 20","sec":"مسكين ومعاوية","page":"ج20 ص223","text":"(رب مهزول سمين بيته ... وسمين البيت مهزول النسب)\n(أصبحت ترزق من شحم الذرا ... وتخال اللؤم درا ينتهب)\n(لا تلمها إنها من نسوة ... صخبات ملحها فوق الركب)\n(كشموس الخيل يبدو شغبها ... كلما قيل لها هال وهب)","topic":"أخبار مسكين ونسبه","topicNo":260,"sp":2,"spl":"مسكين ومعاوية — يزيد بن معاوية يستعين بمسكين"},
{"id":"b260-5","bab":"الجزء 20","sec":"يزيد بن معاوية يستعين بمسكين","page":"ج20 ص227","text":"أخبرني محمد بن مزيد قال حدثني حماد بن إسحاق الموصلي قال حدثني أبي عن الهيثم بن عدي عن عبد الله بن عياش قال كان يزيد بن معاوية يؤثر مسكينا الدارمي ويصله ويقوم بحوائجه عند أبيه فلما أراد معاوية البيعة ليزيد تهيب ذلك وخاف ألا يمالئه عليه الناس لحسن البقية فيهم وكثرة من يرشح للخلافة وبلغه في ذلك ذرء وكلام كرهه من سعيد بن العاص ومروان بن الحكم وعبد الله بن عامر فأمر يزيد مسكينا أن يقول أبياتا وينشدها معاوية في مجلسه إذا كان حافلا وحضره وجوه بني أمية فلما اتفق ذلك دخل مسكين إليه وهو جالس وابنه يزيد عن يمينه وبنو أمية حواليه وأشراف الناس في مجلسه فمثل بين يديه وأنشأ يقول\n(إن أدع مسكينا فإني ابن معشر ... من الناس أحمي عنهم وأذود)\n(إليك أمير المؤمنين رحلتها ... تثير القطا ليلا وهن هجود)\n(وهاجرة ظلت كأن ظباءها ... إذا ما اتقتها بالقرون سجود)\nصوت\n(ألا ليت شعري ما يقول ابن عامر ... ومروان أم ماذا يقول سعيد)\n(بني خلفاء الله مهلا فإنما ... يبوئها الرحمن حيث يريد)\n(إذا المنبر الغربي خلاه ربه ... فإن أمير المؤمنين يزيد)\nالغناء لمعبد ثقيل أول بالبنصر عن عمرو بن بانة\n(على الطائر الميمون والجد صاعد ... لكل أناس طائر وجدود)\n(فلا زلت أعلى الناس كعبا ولا تزل ... وفود تساميها إليك وفود)\n(ولا زال بيت الملك فوقك عاليا ... تشيد أطناب له وعمود)\n(قدور ابن حرب كالجوابي وتحتها ... أثاف كأمثال الرئال ركود)\nقال له معاوية ننظر فيما قلت يا مسكين ونستخير الله قال ولم يتكلم أحد من بني أمية في ذلك إلا بالإقرار والموافقة وذلك الذي أراده يزيد ليعلم ما عندهم ثم وصله يزيد ووصله معاوية فأجزلا صلته أخبرني محمد بن خلف قال حدثنا العنزي قال حدثنا أبو معاوية بن سيعد بن سالم قال قال لي عقيد غنيت الرشيد\n(إذا المنببر الغربي خلاه ربه ... )\nثم فطنت لخطابي ورأيت وجه الرشيد قد تغير قال فتداركتها وقلت\n(فإن أمير المحسنين عقيد ... )\nطرب وقال أحسنت والله بحياتي قل\n(فإن أمير المؤمنين عقيد ... )\nوالله لأنت أحق بها من يزيد بن معاوية فتعاظمت ذلك فحلف لا أغنيه إلا كما أمر ففعلت وشرب عليه ثلاثة أرطال ووصلني صلة سيئة أخبرني محمد بن الحسن بن دريد قال حدثنا عبد الرحمن ابن أخي الأصمعي قال حدثني عمي قال كانت لمسكين الدارمي امرأة من منقر وكانت فاركا كثيرة الخصومة والمماظة فجازت به يوما وهو ينشد قوله في نادي قومه\n(إن أدع مسكينا فما قصرت ... قدري بيوت الحي والجدر)\nوقفت عليه تسمع حتى إذا بلغ قوله\n(ناري ونار الجار واحدة ... وإليه قبلي تنزل القدر)\nقالت له صدقت والله يجلس جارك فيطبخ قدره فتصطلي بناره ثم ينزلها فيجلس يأكل وأنت بحذائه كالكلب فإذا شبع أطعمك أجل\nوالله إن القدر لتنزل إليه قبلك فأعرض عنها ومر في قصيدته حتى بلغ قوله\n(ما ضر جارا لي أجاوره ... ألا يكون لبيته ستر)\nقالت له أجل إن كان له ستر هتكته فوثب إليها يضربها وجعل قومه يضحكون منهما وهذه القصيدة من جيد شعره صوت\n(يا فرحتا إذ صرفنا أوجه الإبل ... نحو الأحبة بالإزعاج والعجل)\n(نحثهن وما يؤتين من دأب ... لكن للشوق حثا ليس للإبل)\nلشعر لأبي محمد اليزيدي والغناء لسليمان ثقيل أول بالبنصر عن عمرو والهشامي","topic":"أخبار مسكين ونسبه","topicNo":260,"sp":2,"spl":"مسكين ومعاوية — يزيد بن معاوية يستعين بمسكين","partial":1},
{"id":"b261-1","bab":"الجزء 20","sec":"أخبار أبي محمد ونسبه","page":"ج20 ص231","text":"أبو محمد يحيى بن المبارك أحد بني عدي بن عبد شمس بن زيد مناة بن تميم سمعت أبا عبد الله محمد بن العباس بن محمد بن أبي محمد اليزيدي يذكر ذلك ويقول نحن من رهط ذي الرمة وقيل أنهم موالي بني عدي وقيل لأبي محمد اليزيدي لأنه كان فيمن خرج مع إبراهيم بن عبد الله بن الحسن بالبصرة ثم توارى زمانا حتى استتر أمره ثم اتصل بعد ذلك بيزيد بن منصور خال المهدي فوصله بالرشيد فلم يزل معه وأدب المأمون خاصة من ولده ولم يزل أبو محمد وأولاده منقطعين إليه وإلى ولده ولهم فيهم مدائح كثيرة جياد وكان أبو محمد عالما باللغة والنحو راوية للشعر متصرفا في علوم\nالعرب أخذ عن أبي عمرو بن العلاء ويونس بن حبيب النحوي وأكابر البصريين وقرأ القرآن على أبي عمرو بن العلاء وجود قراءته ورواها عنه وهي المعول عليها في هذا الوقت وكان بنوه جميعا في مثل منزلته من العلم والمعرفة باللغة وحسن التصرف في علوم العرب ولسائرهم علم جيد ونحن نذكر بعد انقضاء أخباره أخبار من كان له شعر وفيه غناء من ولده إذ كنا قد شرطنا ذكر ما فيه صنعة دون غيره فمنهم محمد بن أبي محمد وإبراهيم بن أبي محمد واسماعيل بن أبي محمد كل هؤلاء ولده لصلبه ولكلهم شعر جيد ومن ولد ولده أحمد بن محمد بن أبي محمد وهو أكبرهم وكان شاعرا راوية عالما ومنهم عبيد الله والفضل ابنا محمد بن محمد وقد رويا عن أكابر أهل اللغة وحمل عنهما علم كثير وآخر من كان بقي من علماء أهل هذا البيت أبو عبد الله محمد بن العباس بن محمد بن أبي محمد وكان فاضلا عالما ثقة فيما يرويه منقطع القرين في الصدق وشدة التوقي فيما ينقله وقد حملنا نحن عنه وكثير من طلبة العلم ورواته علما كثيرا فسمعنا\nمنه سماعا جما فأما ما أذكر ها هنا من أخبارهم فإني أخذته عن أبي عبد الله عن عمية عبيد الله والفضل وأضفت إليه أشياء أخر يسيرة أخذتها عن غيره فذكرت ذلك في مواضعه ورويته عن أهله أخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله عن عمه إسماعيل بن أبي محمد قال حدثني أبي قال كان الرشيد جالسا في مجلسه فأتي بأسير من الروم فقال لدفافة العبسي قم فاضرب عنقه فضربه فنبا سيفه فقال لابن فليح المدني قم فاضرب عنقه فضربه فنبا سيفه أيضا فقال أصلح الله أمير المؤمنين تقدمتني ضربة عبسية فقال الرشيد للمأمون وهو يومئذ غلام قم فداك أبوك فاضرب عنقه فقام فضرب العلج فأبان رأسه ثم دعا بآخر فأمره بضرب عنقه فضربه فأبان رأسه ونظر إلي المأمون نظر مستنطق فقلت\n(أبقى دفافة عارا بعد ضربته ... عند الإمام لعبس آخر الأبد)\n(كذاك أسرته تنبو سيوفهم ... كسيف ورقاء لم يقطع ولم يكد)\n(ما بال سيفك قد خانتك ضربته ... وقد ضربت بسيف غير ذي أود)\n(هلا كضربة عبد الله إذ وقعت ... ففرقت بين رأس العلج والجسد)\nال إسماعيل بن أبي محمد في أخباره كان حمويه ابن أخت الحسن الحاجب وسعيد الجوهري واقفين فذكرا أبا محمد يعني أباه والكسائي ففضل حمويه الكسائي على أبي محمد وفضل سعيد الجوهري أبا محمد على الكسائي وطال الكلام بينهما إلى أن تراضيا برجل يحكم بينهما فتراهنا على أن من غلب أخذ برذون صاحبه فجعلا الحكم بينهما أبا صفوان الأحوزي فلما دخل سألاه فقال لهما لو ناصح الكسائي نفسه لصار إلى أبي محمد وتعلم منه كلام العرب فما رأيت أحدا أعلم منه به فأخذ الجوهري دابة حمويه وبلغ أبا محمد اليزيدي هذا الخبر فقال\n(يا حمويه اسمع ثنا صادقا ... فيك وما الصادق كالكاذب)\n(يا جالب الخزي على نفسه ... بعدا وسحقا لك من جالب)\n(إن فخر الناس بآبائهم ... آتيتهم بالعجب العاجب)\n(قلت وأدغمت أبا خاملا ... أنا ابن أخت الحسن الحاجب)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":0,"spl":"أخبار أبي محمد ونسبه"},
{"id":"b261-2","bab":"الجزء 20","sec":"ابو محمد وسلم الخاسر","page":"ج20 ص234","text":"قال إسماعيل وحدثني أبي قال كنت ذات يوم جالسا أكتب كتابا فنظر فيه سلم الخاسر طويلا\nثم قال\n(أير يحيى أخط من كف يحيى ... إن يحيى بأيره لخطوط)\nقال أبو محمد يحيى\n(أم سلم بذاك أعلم شيء ... إنها تحت أيره لضروط)\n(ولها تارة إذا ما علاها ... أزمل من وداقها وأطيط)\n(أم سلم تعلم الشعر سلما ... حبذا شعر أمك المنقوط)\n(ليت شعري ما بال سلم بن عمرو ... كاسف البال حين يذكر لوط)\n(لا يصلي عليه فيمن يصلي ... بل له عند ذكره تثبيط)\nقال له سلم ويحك ما لك خبثت أي شيء دعاك إلى هذا كله فقال أبو محمد بدأت فانتصرت والبادي أظلم قال أبو عبد الله محمد بن العباس اليزيدي حدثني عبيد الله وعمي أبو القاسم عن أبي علي إسماعيل قال قال لي أبي قال سلم الخاسر يوما يا أبا محمد قل أبياتا على قول امرىء القيس\n(رب رام من بني ثعل ... )\nلا أبالي أن تهجوني فيها فقلت\n(رب مغموم بعافية ... غمط النعماء من أشره)\n(مورد أمرا يسر به ... فرأى المكروه في صدره)\n(وامرىء طالت سلامته ... فرماه الدهر من غيره)\n(بسهام غير مشوية ... نقضت منه عرا مرره)\n(وكذاك الدهر مختلف ... بالفتى حالين من عصره)\n(يخلط العسرى بميسرة ... ويسار المرء في عسره)\n(عق سلم أمه سفها ... وأبا سلم على كبره)\n(كل يوم خلفه رجل ... رامح يسعى على أثره)\n(يولج الغرمول سبته ... كولوج الضب في جحره)\nانصرف سلم وهو يشتمه ويقول ما يحل لأحد أن يكلمك قال وقال لي يوما أبو حنش الشاعر يا أبا محمد قل أبياتا قافيتها على هاءين فقلت له على أن أهجوك فيها فقال نعم فقلت\n(قلت ونفسي جم تأوهها ... تصبو إلى إلفها وأندهها)\n(سقيا لصنعاء لا أرى بلدا ... أوطنه الموطنون يشبهها)\n(حصنا وحسنا ولا كبهجتها ... أعذى بلاد عذا وأنزهها)\n(يعرف صنعاء من أقام بها ... أرغد أرض عيشا وأرفهها)\n(أبلغ حضيرا عني أبا حنش ... عائرة نحوه أوجهها)\n(تأتيه مثل السهام عامدة ... عليه مشهورة أدهدهها)\n(كنيته طرح نون كنيته ... إذا تهجيتها ستفقهها)\nيريد إسقاط النون من أبي حنش حتى يكون أبا حش قال أبو عبد الله وحدثني عمي قال حدثني الطلحي وكان له علم وأدب قال اجتمعت مع أبي محمد عند يونس بن الربيع وكان قد دعانا فأقمنا عنده فاتفق مجلسي إلى جنب مجلس أبي محمد فقام يونس لحاجته وكان جميلا وسيما فالتفت إلى اليزيدي فقال\n(وفتى كالقناة في الطرف منه ... إن تأملت طرفه استرخاء)\n(فإذا الرامح المشيح تلاه ... وضع الرمح منه حيث يشاء)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":1,"spl":"ابو محمد وسلم الخاسر","partialRef":{"sid":"b89-12","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b261-3","bab":"الجزء 20","sec":"أبو محمد وقتيبة الخراساني","page":"ج20 ص237","text":"قال وحدثني عمي عن عمه إسماعيل عن أبي محمد قال كان قتيبة الخراساني صاحب عيسى بن عمر يأتيني فيسألني عن مسائل كالمتعنت فإذا أجبته عنها انصرف منكسرا وكان أفطس فقلت له يوما\n(أمخبري أنت يا قتيبة عن ... أنفك أم أنت كاتم خبره)\n(بأي جرم وأي ذنب ترى ... سوت بخديك أنفك البقره)\n(فصيرته كفيشة نبتت ... في وجه قرد مفضوضة الكمره)\n(قد كان في ذاك شاغل لك عن ... تفتيش باب العرفان والنكره)\nقلت فيه أيضا\n(إذا عافى مليك الناس عبدا ... فلا عافاك ربك يا قتيبه)\n(طلبت النحو مذ أن كنت طفلا ... إلى أن جللتك قبحت شيبه)\n(فما تزداد إلا النقص فيه ... وأنت لدى الإياب بشر أوبه)\n(وكنت كغائب قد غاب حينا ... فطال مقامه وأتى بخيبه)\nال أبو محمد كان عيسى بن عمر أعلم الناس بالغريب فأتاني قتيبة الخراساني هذا فقال لي أفدني شيئا من الغريب أعاني به عيسى بن عمر فقلت له أجود المساويك عند العرب الأراك وأجود الأراك عندهم ما كان متمئرا عجارما جيدا وقد قال الشاعر\n(إذا استكت يوما بالأراك فلا يكن ... سواكك إلا المتمئر العجارما)\nعني الأير قال فكتب قتيبة ما قلت له وكتب البيت ثم أتى عيسى بن عمر في مجلسه فقال يا أبا عمر ما أجود المساويك عند العرب فقال الأراك يرحمك الله فقال له قتيبة أفلا أهدي إليك منه شيئا متمئرا عجارما فقال أهده إلى نفسك وغضب وضحك كل من كان في مجلسه وبقي قتيبة متحيرا فعلم عيسى أنه قد وقع عليه بلاء\nفقال له ويلك من فضحك وسخر منك بهذه المسألة ومن أهلكك ودمر عليك قال أبو محمد اليزيدي فضحك عيسى حتى فحص برجله وقال هذه والله من مزحاته وبلاياه أراه عنك منحرفا فقد فضحك فقال قتيبة لا أعاود مسألته عن شيء حدثني عمي قال حدثني عبيد الله بن محمد اليزيدي قال حدثني أخي أبو جعفر قال سمعت جدي أبا محمد يقول صرت يوما إلى الخليل بن أحمد والمجلس غاص بأهله فقال لي ها هنا عندي فقلت أضيق عليك فقال إن الدنيا بحذافيرها تضيق عن متباغضين وإن شبرا في شبر لا يضيق عن متحابين قال وكان الخليل لأبي محمد صافي الود حدثنا اليزيدي قال حدثني عمي عبيد الله قال حدثني أخي أحمد قال سمعت جدي أبا محمد يقول كنت ألقى الخليل بن أحمد فيقول لي أحب أن يجمع بيني وبين عبد الله بن المقفع وألقى ابن المقفع فيقول أحب أن يجمع بيني وبين الخليل بن أحمد فجمعت بينهما فمر لنا أحسن مجلس وأكثره علما ثم افترقنا فلقيت الخليل فقلت له يا أبا عبد الرحمن كيف رأيت صاحبك قال ما شئت من علم وأدب إلا أني رأيت كلامه أكثر من علمه ثم لقيت ابن المقفع فقلت كيف رأيت صاحبك فقال ما شئت من علم وأدب إلا أن عقله أكثر من علمه","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":2,"spl":"أبو محمد وقتيبة الخراساني"},
{"id":"b261-4","bab":"الجزء 20","sec":"ناظر الكسائي وغلبه","page":"ج20 ص239","text":"حدثنا اليزيدي قال حدثني عمي عبيد الله قال حدثني أخي أحمد بن محمد قال حدثني أبي محمد بن أبي محمد قال قال لي أبو محمد\nكنا مع المهدي ببلد في شهر رمضان قبل أن يستخلف بأربعة أشهر وكان الكسائي معنا فذكر المهدي العربية وعنده شيبة بن الوليد العبسي عم دفافة فقال المهدي نبعث إلى اليزيدي والكسائي وأنا يومئذ مع يزيد بن المنصور خال المهدي والكسائي مع الحسن الحاجب فجاءنا الرسول فجئت أنا فإذا الكسائي على الباب قد سبقني فقال يا أبا محمد أعوذ بالله من شرك فقلت والله لا تؤتى من قبلي حتى أوتى من قبلك فلما دخلنا عليه أقبل علي وقال كيف نسبوا إلى البحرين فقالوا بحراني ونسبوا إلى الحصنين فقالوا حصني ولم يقولوا حصناني كما قالوا بحراني فقلت أصلح الله الأمير لو أنهم نسبوا إلى البحرين فقالوا بحري لم يعرف أإلى البحرين نسبوا أم إلى البحر فلما جاؤوا إلى الحصنين لم يكن موضع آخر يقال له الحصن ينسب إليه غيرهما فقالوا حصني قال أبو محمد سمعت الكسائي يقول لعمر بن بزيع وكان حاضرا\nلو سألني الأمير لأخبرته فيها بعلة هي أحسن من هذه قال أبو محمد قلت أصلح الله الأمير إن هذا يزعم أنك لو سألته لأجاب بأحسن مما أجبت به قال فقد سألته فقال الكسائي لما نسبوا إلى الحصنين كانت فيه نونان فقالوا حصني اجتزاء بإحدى النونين عن الأخرى ولم يكن في البحرين إلا نون واحدة فقالوا بحراني فقلت أصلح الله الأمير فكيف تنسب رجلا من بني جنان فإنه يلزمه على قياسه أن يقول جني إن في جنان نونين فإن قال ذلك فقد سوى بينه وبين المنسوب إلى الجن قال فقال لي المهدي وله تناظرا في غير هذا حتى نسمع فتناظرنا في مسائل حفظ فيها قولي وقوله إلى أن قلت له كيف تقول إن من خير القوم أو خيرهم نية زيد قال فأطال الفكر لا يجيب فقلت لأن تجيب فتخطئ فتتعلم أحسن من هذه الإطالة فقال إن من خير القوم أو خيرهم نية زيدا قال فقلت أصلح الله الأمير ما رضي أن يلحن حتى لحن وأحال قال وكيف قلت لرفعه قبل أن يأتي باسم إن ونصبه بعد رفعه فقال شيبة بن الوليد أراد بأو بل فرفع هذا معنى فقال الكسائي ما أردت غير ذلك فقلت فقد أخطأ جميعا أيها الأمير لو أراد بأو بل رفع زيدا لأنه لا يكون بل خيرهم زيدا فقال المهدي يا كسائي لقد دخلت علي مع مسلمة النحوي وغيره فما رأيت كما أصابك اليوم قال ثم قال هذان عالمان ولا يقضي بينهما إلا أعرابي فصيح يلقى عليه المسائل التي اختلفا فيها فيجيب قال فبعث إلى فصيح من فصحاء الأعرب قال أبو محمد وأطرقت إلى أن يأتي الأعرابي وكان المهدي محبا لأخواله ومنصور بن يزيد بن منصور حاضر فقلت أصلح الله الأمير كيف ينشد هذا البيت الذي جاء في هذه الأبيات\n(يا أيها السائلي لأخبره ... عمن بصنعاء من ذوي الحسب)\n(حمير سادتها تقر لها ... بالفضل طرا جحاجح العرب)\n(وإن من خيرهم وأكرمهم ... أو خيرهم نية أبو كرب)\nال فقال لي المهدي كيف تنشده أنت فقلت أو خيرهم نية أبو كرب على إعادة إن كأنه قال أو إن خيرهم نية أبو كرب فقال الكسائي هو والله قالها الساعة قال فتبسم المهدي وقال إنك لتشهد له وما تدري قال ثم طلع الأعرابي الذي بعث إليه فألقيت عليه المسائل فأجاب فيها كلها بقولي فاستفزني السرور حتى ضربت بقلنسيتي الأرض وقلت أنا أبو محمد فقال لي شيبة أتتكنى باسم الأمير فقال المهدي والله ما أراد بذلك مكروها ولكنه فعل ما فعل للظفر وقد لعمري ظفر فقلت إن الله عز و جل أنطقك أيها الأمير بما أنت أهله وأنطق غيرك بما هو أهله قال فلما خرجنا قال لي شيبة أتخطئني بين يدي الأمير أما لتعلمن قلت قد سمعت ما قلت وأرجو أن تجد غبها ثم لم أصبح حتى كتبت رقاعا عدة فلم أدع ديوانا إلا دسست إليه رقعة فيها أبيات قلتها فيه فأصبح الناس يتناشدونها وهي\n(عش بجد ولا يضرك نوك ... إنما عيش من ترى بالجدود)\n(عش بجد وكن هبنقة القيسي ... نوكا أو شيبة بن الوليد)\n(شيب يا شيب يا جددي بني القعقاع ... ما أنت بالحليم الرشيد)\n(لا ولا فيك خلة من خلال الخير ... أحرزتها لحزم وجود)\n(غير ما أنك المجيد لتقطيع ... غناء وضرب دف وعود)\n(فعلى ذا وذاك يحتمل الدهر ... مجيدا له وغير مجيد)\nال وقال أبو محمد اليزيدي يهجو خلفا الأحمر أستاذ الكسائي أنشدنيه عمي الفضل\n(زعم الأحمر المقيت علي ... والذي أمه تقر بمقته)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":3,"spl":"ناظر الكسائي وغلبه"},
{"id":"b261-5","bab":"الجزء 20","sec":"ناظر الكسائي وغلبه","page":"ج20 ص239","text":"(أنه علم الكسائي نحوا ... فلئن كان ذا كذاك فباسته)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":4,"spl":"ناظر الكسائي وغلبه"},
{"id":"b261-6","bab":"الجزء 20","sec":"الرشيد يأمر له بمال فيستعين بأصحابه على تعجيله","page":"ج20 ص243","text":"وبهذا الإسناد عن أبي محمد قال\nأمر لي الرشيد بمال وحضر شخوصه إلى السن فأتيت عاصما الغساني وكان أثيرا عند يحيى بن خالد فقلت له إن أمير المؤمنين قد\nأمر لي بمال وقد حضر من شخوصه ما قد علمت فأحب أن تذكر أبا علي يحيى بن خالد أمره ليعجله إلي فقال نعم ثم عدت بعد ذلك بيومين فقال لي يتفخم في لفظه ما أصبت بحاجتك موضعا قال قلت فاجعلها منك أكرمك الله ببال فلما خرجت لحقني بعض من كان في المجلس فقال لي يا أبا محمد إني لأربأ بك أن تأتي هذا الكلب أو تسأله حاجة قلت وكيف قال سمعته يقول وقد وليت لو أن بيدي دجلة والفرات ما سقيت هذا منها شربة فقيل له ولم ذاك أصلحك الله فإن له قدرا وعلما قال لأنه من مضر ما رأيت مضريا قط يحب اليمانية قال فأحببت ألا أعجل فعدت إليه من غد فقلت هل كان منك أكرمك الله في الحاجة شيء فقال والله لكأنك تطلبنا بدين فتحقق عندي ما بلغني عنه فقلت له لا قضى الله هذه الحاجة على يدك ولا قضى لي حاجة أبدا إن سألتكها والله لا سلمت عليك مبتدئا أبدا ولا رددت عليك السلام إن بدأتني به ونفضت ثوبي وخرجت فإني لأسير وأفكر في الحيلة لحاجتي إذا براكب يركض حتى لحقني فقال بعثني إليك أبو علي يحيى بن خالد لتقف حتى يلحقك فرجعت مع رسوله إليه فلقيته وكان قريبا فسلمت عليه ثم سايرته فقال لي إن أمير المؤمنين أمرني أن آمرك بطلب مؤدب لابنه صالح فإني أحدثك حديثا حدثني به أبي خالد بن برمك أن الحجاج بن يوسف أراد مؤدبا لولده فقيل له ها هنا رجل نصراني عالم وها هنا مسلم ليس علمه كعلم النصراني قال ادعوا لي المسلم فلما أتاه قال ألا ترى يا هذا أنا قد دللنا على نصراني قد ذكروا أنه أعلم منك غير أني كرهت أن أضم إلى ولدي من لا ينبههم للصلاة عند\nوقتها ولا يدلهم على شرائع الإسلام ومعالمه وأنت إن كان لك عقل قادر على أن تتعلم في اليوم ما يعلمه أولادي في جمعة وفي الجمعة ما يعلمهم في الشهر وفي الشهر ما يعلمهم في سنة ثم قال لي يحيى فينبغي يا أبا محمد أن نؤثر الدين على ما سواه فقلت له قد أصبت من أرضاه وذكرت له الحسن بن المسور فضمه إليه ثم سألني من أين أقبلت فأخبرته بخبر عاصم وما كان منه فقلت له قد حضر هذا المسير ولست أدري من أي وجه أتقاضاه فضحك وقال ولم لا تدري الق صديقك جعفرا يعني ابنه حتى يكلم أمير المؤمنين أو يذكرني حاجتك فقد تركته على المضي الساعة فانثنيت إلى جعفر وقلت له في طريقي\n(يا سائلي عما أخبره ... عن جعفر كرما وعن شيمه)\n(إن ابن يحيى جعفرا رجل ... سيط السماح بلحمه ودمه)\n(فعليه لا أبدا محرمة ... وكلامه وقف على نعمه)\n(وترى مسابقه ليدركه ... بمكان حذو النعل من قدمه)\nلما دخلت إليه أخبرته الخبر وأنشدته الأبيات وأعلمته ما أمرني به أبوه فقال لي قل بيتين تدكره فيهما إلى أن أجدد طهرا واكتبهما حتى يكونا معي فأذكر بهما حاجتك فقلت نعم يا سيدي وأخذت الدواة وكتبت\n(أحق من أنجز موعوده ... خليفة الله على خلقه)\n(ومن له إرث نبي الهدى ... بالحق لا يدفع عن حقه)\n(ينسب في الهدي إلى هديه ... برا وفي الصدق إلى صدقه)\n(ومن له الطاعة مفروضة ... لائحة بالوحي في رقه)\n(والراتق الفتق العظيم الذي ... لا يقدر الناس على رتقه)\nقال فأخذ الشعر ومضى إلى الرشيد في حاجتي وأقرأه إياه فصك إلي بالمال عليه وقبضته بعد ذلك بيوم وأنشأت أقول في الغساني\n(ألا طرقت أسماء أم أنت حالم ... فأهلا بطيف زار والليل عاتم)\n(إذا قيل أي الناس أعظم جفوة ... وألأم قيل الجر مقاني عاصم)\n(دعي أجاءته إلى اللؤم دعوة ... ومغرس سوء لؤمه متقادم)\n(شهيدي على أن ليس حرا صليبة ... صفيحة وجه ابن استها واللهازم)\n(صفيحة دقاق أبوه شبيهه ... وجداه سماك لئيم وحاجم)\n(أعاصم خل المكرمات لأهلها ... وأغض على لؤم ووجهك سالم)\n(فكيف تنال الدهر مجدا وسوددا ... وفي كل يوم كوكب لك ناجم)\n(وأصلك مدخول وفسقك ظاهر ... وعجبك مهموز وعردك عارم)\n(تصانع غسانا لتلحق فيهم ... ورب دعي ألحقته الدراهم)\n(فإن راب ريب أو أصابتك شدة ... رجعت إلى شلثى وأنفك راغم)\nال وكان اسم ابن شلثى ... فصيره صلتا\n(إذا عاصما يوما أتيت لحاجة ... فلا تلقه إلا وأيرك قائم)\n(وعرض له من قبل ذاك بأمرد ... وضيء وسيم أثقلته المآكم)\n(وإلا فلا تسأله ما عشت حاجة ... ولا تبكه إن أعولته المآتم)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":5,"spl":"الرشيد يأمر له بمال فيستعين بأصحابه على تعجيله"},
{"id":"b261-7","bab":"الجزء 20","sec":"الرشيد يأمر له بمال فيستعين بأصحابه على تعجيله","page":"ج20 ص243","text":"ال فلما حدث ببني برمك ما حدث قبضت ضيعته في المقبوض من ضياع أسبابهم فصار إلي وكلمني في أمرها وسألني كلام الجوهري في ذلك فقمت له حتى ردت الضيعة عليه فجاءني يشكرني ويعتذر مما جرى من فعله المتقدم فقلت له تناس ما مضى فلست ممن يكافئ على سوء أحدا","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":6,"spl":"الرشيد يأمر له بمال فيستعين بأصحابه على تعجيله"},
{"id":"b261-8","bab":"الجزء 20","sec":"أبو محمد يهجو أبا عبيدة","page":"ج20 ص247","text":"قال أبو محمد كان أبو عبيدة يجلس في مسجد البصرة إلى سارية وكنت أنا وخلف الأحمر نجلس جميعا إلى أخرى وكان أبو عبيدة من أعضه الناس للناس وأذكرهم لمثالبهم فقال لأصحابه أترون الأحمر واليزيدي إنما يجتمعان على الوقيعة للناس وذكرمساويهم وبلغني ذلك وأنه قد رمانا بمذهبه فقلت لخلف دعه فأنا أكفيكه فلما كان من الأذان جئت أنا وخلف إلى المسجد فكتبت على الجص في الموضع الذي كان يجلس فيه أبو عبيدة\n(صلى الإله على لوط وشيعته ... أبا عبيدة قل بالله آمينا)\nال وأصبح الناس وجاء أبو عبيدة فجلس وهو يعلم ما فوق رأسه مكتوبا وأقبل الناس ينظرون إلى البيت ويضحكون ورفع أبو عبيدة رأسه ونظر إليه فخجل ولم يزل منكسا رأسه حتى انصرف الناس وأنا وخلف ناحية ننظر إلى ما به ثم قمنا حتى وقفنا عليه فقلنا له ما قال\nصاحب هذا البيت إلا حقا نعم فصلى الله على لوط فأقبل علي وقال قد علمت من أين أتيت ولن أعاود التعرض لتلك الجهة ولم يعد لذكرنا بعد ذلك وقال أبو محمد اعتللت علة من حمى ربع طالت علي أشهرا فجفاني يزيد بن منصور ولم يمر بي في علتي ولم يتفقدني كما ينبغي فكتبت رقعة إليه ضمنتها هذه الأبيات\n(قل للأمير الذي يرجو نوافله ... من جاء طالبا للخير منتابا)\n(إني صحبتك دهرا كل ذاك أرى ... من دون خيرك حجابا وأبوابا)\n(وكم ضريك أجاءته شقاوته ... إليك إذا أنشبت ضراؤها نابا)\n(فما فتحت له بابا لميسرة ... ولا سددت له من فاقة بابا)\n(كغائب شاهد يخفي عليك كما ... من غاب عنك فوافى حظه غابا)\nلما قرأها قال جفونا أبا محمد وأحوجناه إلى استبطائنا والله المستعان وبعث إليه بصلة أخبرني هاشم بن محمد الخزاعي أبو دلف قال حدثني محمد بن عبد الرحمن بن الفهم وكان من أصحاب الأصمعي قال كان خلف الأحمر يعبث بأبي محمد اليزيدي عبثا شديدا وربما جد فيه وأخرجه مخرج المزح فقال فيه ينسبه إلى اللواط\n(إني ومن وسج المطي له ... حدب الذرى أذقانها رجف)\n(يطرحن بالبيد السحال إذا ... حث النجاء الركب وازدهفوا)\n(والمحرمين لصوتهم زجل ... بفناء كعبته إذا هتفوا)\n(وإذا قطعن مساف مهمهة ... قذف تعرض دونها شرف)\n(وافت بهم خوص محزمة ... مثل القسي ضوامر شسف)\n(مني إليه غير ذي كذب ... ما إن رأى قوم ولا عرفوا)\n(في غابر الناس الذين بقوا ... والفرط الماضين إذ سلفوا)\n(أحدا كيحيى في الطعان إذا افترش ... القنا وتضعضع الحجف)\n(في معرك يلقى الكمي به ... للوجه منبطحا وينحرف)\n(وإذا أكب القرن يتبعه ... طعنا دوين صلاه ينخسف)\n(لله درك أي ذي نزل ... في الحرب إذ هموا وإذ وقفوا)\n(لا تخطىء الوجعاء ألته ... ولا تصد إذا هم زحفوا)\n(وله جياد لا يفرطها الإحلال ... والمضمار والعلف)\n(جرد يهان لها السوق وألبان ... اللقاح كأنها نزف)\n(مرد وأطفال تخالهم ... درا تطابق فوقه الصدف)\n(فهم لديه يعكفون به ... والمرء منه اللين واللطف)\n(ومتى يشا يجنب له جذع ... نهد أسيل الخد مشترف)\n(يمشي العرضنة تحت فارسه ... عبل الشوى في متنه قطف)\n(ربذ إذا عرقت مغابنه ... ذهب السكون وأقبل العنف)\n(فأعد ذاك لسرجه وله ... في كل غادية لها عرف)\n(في حقوه عرد تقدمه ... صلعاء في خرطومها قلف)\n(جرداء تشحذ بالزاق إذا ... دعيت نزال وهب مرتدف)\n(أوفى على قيد الذراع شديد ... الجلز في يافوخه جوف)\n(خاظ ممر متنه ضرم ... لا خانه خور ولا قضف)\n(عرد المجس بمتنه عجر ... في جذره عن فخذه جنف)\n(فلو أن فياضا تأمله ... نادى بجهد الويل يلتهف)\n(وإذا تمسحه لعادته ... ودنا الطعان فمدعس ثقف)\n(وإذا رأى نفقا ربا ونزا ... حتى يكاد لعابه يكف)\n(لا ناشئا يبقي ولا رجلا ... فندا وهذا قلبه كلف)\n(يا ليتني أدري أمنجيتي ... وجناء ناجية بها شدف)\n(من أن تعلقني حبائله ... أو أن يواري هامتي لجف)\n(ولقد أقول حذار سطوته ... إيها إليك توق يا خلف)\n(ولو أن بيتك في ذرا علم ... من دون قلة رأسه شعف)\n(زلق أعاليه وأسفله ... وعر التنائف بيتها قذف)\n(لخشيت عردك أن يبيتني ... أن لم يكن لي عنه منصرف)\nال الأصمعي فحدثني شيخ من آل أبي سفيان بن العلاء أخي أبي عمرو بن العلاء قال أنشدت قصيدة خلف الفائية هذه وأعرابي جالس يسمع فلما سمع قوله\n(فإذا أكب القرن أتبعه ... طعنا دوين صلاه ينخسف)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":7,"spl":"أبو محمد يهجو أبا عبيدة"},
{"id":"b261-9","bab":"الجزء 20","sec":"أبو محمد يهجو أبا عبيدة","page":"ج20 ص247","text":"ال الأعرابي وأبيك لقد أحب أن يضعه في حاق مقيل ضرطته أخبرني هاشم بن محمد قال حدثني ابن الفهم قال حدثني الأصمعي قال كنت مع خلف جالسا فجرى كلام في شيء من اللغة وتكلم فيه أبو محمد اليزيدي وجعل يشغب فقال لي خلف دعني من هذا يا أبا محمد وأخبرني من الذي يقول\n(فإذا انتشأت فإنني ... رب الحريبة والرميح)\n(وإذا صحوت فإنني ... رب الدوية واللويح)\nعرض به أنه معلم وأنه يلوط فغضب اليزيدي وقام فانصرف أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني طلحة الخزاعي قال حدثني أبو سعيد عثمان بن يوسف الحنفي قال غاضب أبو محمد اليزيدي مواليه بني عدي رهط ذي الرمة من بني تميم لأمر استنهضهم فيه فقعدوا عنه فقال يهجوهم\n(يا أيها السائل عن قومنا ... لما رأى بزة أحبارهم)\n(وحسن سمت منهم ظاهرا ... إعلانهم ليس كإسرارهم)\n(سائل بهم أحمر أو غيره ... ينبيك عن قومي وأخبارهم)\n(قوم كرام ما عدا أنهم ... صولتهم منهم على جيرانهم)\n(أسد على الجيران أعداؤهم ... آمنة تخطر في دارهم)\n(لو جاءهم مقتبسا جارهم ... ما قبسوه الدهر من نارهم)\n(وقد وترناهم فلم نخش من ... ينهض في سيره أو ثارهم)\n(أحسن قوم لمواليهم ... إن أيسروا يوما لأيسارهم)\n(شهادة الزور لهم عادة ... حقا بها قيمة أخبارهم)\n(وما لهم مجد سوى مسجد ... به تعدوا فوق أطوارهم)\n(لو هدم المسجد لم يعرفوا ... يوما ولم يسمع بأخبارهم)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":8,"spl":"أبو محمد يهجو أبا عبيدة — مدحه المأمون عندما بلغ وصار في حد الرجال"},
{"id":"b261-10","bab":"الجزء 20","sec":"مدحه المأمون عندما بلغ وصار في حد الرجال","page":"ج20 ص253","text":"أخبرني محمد بن العباس اليزيدي قال أخبرني عمي عبيد الله قال حدثني عمي إسماعيل وأخي أحمد قالا لما بلغ المأمون وصار في حد الرجال أمرنا الرشيد أن نعمل له خطبة يقوم بها يوم الجمعة فعملنا له خطبته المشهورة وكان جهير الصوت حسن اللهجة فلما خطب بها رقت قلوب الناس وأبكى من سمعه فقال أبو محمد اليزيدي\n(لتهن أمير المؤمنين كرامة ... عليه بها شكر الإله وجوب)\n(بأن ولي العهد مأمون هاشم ... بدا فضله إذ قام وهو خطيب)\n(ولما رماه الناس من كل جانب ... بأبصارهم والعود منه صليب)\n(رماهم بقول أنصتوا عجبا له ... وفي دونه للسامعين عجيب)\n(لما وعت آذانهم ما أتى به ... أنابت ورقت عند ذاك قلوب)\n(فأبكى عيون الناس أبلغ واعظ ... أغر بطاحي النجار نجيب)\n(مهيب عليه للوقار سكينة ... جريء جنان لا أكع هيوب)\n(ولا واجب فوق المنابر قلبه ... إذا ما اعترى قلب النجيب وجيب)\n(إذا ما علا المأمون أعواد منبر ... فليس له في العالمين ضريب)\n(تصدع عنه الناس وهو حديثهم ... تحدث عنه نازح وقريب)\n(شبيه أمير المؤمنين حزامة ... إذا وردت يوما عليه خطوب)\n(إذا طاب أصل في عروق مشاجه ... فأغصانه من طيبه ستطيب)\n(فقل لأمير المؤمنين الذي به ... يقدم عبد الله فهو أديب)\n(كأن لم تغب عن بلدة كان واليا ... عليها ولا التدبير منك يغيب)\n(تتبع ما يرضيك في كل أمره ... فسيرته شخص إليك حبيب)\n(ورثتم بني العباس إرث محمد ... فليس لحي في التراث نصيب)\n(وإني لأرجو يابن عم محمد ... عطاياك والراجيك ليس يخيب)\n(أثبني على المأمون وابني محمدا ... نوالا فإياه بذاك تثيب)\n(جناب أمير المؤمنين مبارك ... لنا ولكل المؤمنين خصيب)\n(لقد عمهم جود الإمام فكلهم ... له في الذي حازت يداه نصيب)\nصوت فلما وصلت هذه الأبيات إلى الرشيد أمر لأبي محمد بخمسين ألف\nدرهم ولابنه محمد بن أبي محمد بمثله أخبرني عمي قال حدثنا الفضل بن محمد اليزيدي قال حدثني أخي أحمد عن أبيه قال أستأذن أبو محمد الرشيد وهو بالرقة في الحج فأذن له فلما أعاد أنشدنا لنفسه\n(يا فرحتا إذ صرفنا أوجه الإبل ... إلى الأحبة بالإزعاج والعجل)\n(نحثهن ولا يؤتين من دأب ... لكن للشوق حثا ليس للإبل)\n(يا نائيا قربت منه وساوسه ... أمسى قرين الهوى والشوق والوجل)\n(إن طال عهدك بالأحباب مغتربا ... فإن عهدك بالتسهيد لم يطل)\n(أما اشتفى الدهر من حران مختبل ... صب الفؤاد إلى حران مختبل)\n(عش بالرجاء وأمل قرب دراهم ... لعل نفسك أن تبقى مع الأمل)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":8,"spl":"أبو محمد يهجو أبا عبيدة — مدحه المأمون عندما بلغ وصار في حد الرجال"},
{"id":"b261-11","bab":"الجزء 20","sec":"أخبار من له شعر فيه صنعة من ولد أبي محمد اليزيدي وولد ولده","page":"ج20 ص256","text":"فمنهم محمد بن أبي محمد ومما يغنى من شعره قوله صوت\n(أتيتك عائذا بك منك ... لما ضاقت الحيل)\n(وصيرني هواك وبي ... لحيني يضرب المثل)\n(فان سلمت لكم نفسي ... فما لاقيته جلل)\n(وإن قتل الهوى رجلا ... فإني ذلك الرجل)\nلشعر لمحمد بن أبي محمد اليزيدي يكنى أبا عبد الله والغناء لسليم بن سلام ثقيل أول بالبنصر وله أيضا فيه ماخوري وكان سليم صديق محمد بن أبي محمد اليزيدي كثير العشرة له وليس في شيء من شعره صنعة إلا له وله يقول محمد بن أبي محمد اليزيدي صوت\n(بأبي أنت يا سليم وأمي ... ضقت ذرعا بهجر من لا أسمي)\n(صد عني أقر من خلق الله ... لعيني فاشتد غمي وهمي)\n(ما احتيالي إن كان في القدر السابق ... للحين أن أموت بسقمي)\nالغناء لسليم خفيف رمل بالوسطى عن عمرو أخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله عن أخيه أبي جعفر عن أبيه محمد بن أبي محمد قال قال لي أبي نظر إليك أبو ظبية العكلي وقد جاءني فقال لي وقد أقبلت\n(يلد الرجال بنيهم أولادهم ... وولدت أنت أبا من الأولاد)\nال أبو محمد وكتب أبو ظبية يوما\n(أيحيى لقد زرناك نلتمس الجدا ... وأنت امرؤ يرجى جداه ونائله)\n(وما صنع المعروف في الناس صانع ... فيحمد إلا أنت بالخير فاضله)\n(تخيرك الناس الخليفة لابنه ... وأحكمت من كل أمر يحاوله)\n(فما ظن ذو ظن من الناس علمه ... كعلمك إلا مخطىء الظن فائله)\n(إليك تناهت غاية الناس كلهم ... إذا اشتبهت عند البصير مسائله)\nال أبو محمد فكتب إليه\n(أبا ظبية اسمع ما أقول فخير ما ... يقال إذا ما قيل صدق قائله)\n(إذا شئت فانهد بي إلي من أردته ... وأملت جدواه فإني منازلة)\n(فإن يك تقصير ولا يك عارفا ... بحقك فاعذله فتكثر عواذله)\nدثني أبو عبد الله محمد بن العباس اليزيدي قال حدثني عمي عبيد الله قال حدثني أخي أحمد عن أبي قال\nصرت إلى العباس بن الأحنف فقال لي ما حاجتك قلت أمرني أخوك وأبي أن أصير إليك وأستفيد منك فقال لي أتصير إلي وددت أني سبقتك إلى بيتين قلتهما وإني لم أقل من الشعر شيئا غيرهما فدخلني من السرور ما الله به عليم فقلت وما هما فقال قولك\n(يا بعيد الدار موصولا ... بقلبي ولساني)\n(ربما باعدك الدهر ... وأدنتك الأماني)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":9,"spl":"أخبار من له شعر فيه صنعة من ولد أبي محمد اليزيدي وولد ولده"},
{"id":"b261-12","bab":"الجزء 20","sec":"سرق معنيين من الشعر لمسلم بن الوليد","page":"ج20 ص258","text":"حدثني أحمد بن عبيد الله بن عمار قال حدثني محمد بن داود الجراح قال حدثني أبو القاسم عبيد الله بن محمد اليزيدي قال حدثني أحمد بن محمد قال سمعت أبي يقول ما سرقت من الشعر شيئا إلا معنيين قال مسلم بن الوليد\n(ذاك ظبي تحير الحسن في الأركان ... منه وحل كل مكان)\n(عرضت دونه الحجال فما يل ... قاك إلا في النوم أو في الأماني)\nفقلت\n(يا بعيد الدار موصولا ... بقلبي ولساني)\n(ربما باعدك الدهر ... وأدنتك الأماني)\nوقال مسلم أيضا\n(متى ما تسمعي بقتيل حب ... أصيب فإنني ذاك القتيل)\nقلت أنا\n(أتيتك عائذا بك منك ... لما ضاقت الحيل)\n(وصيرني هواك وبي ... لحيني يضرب المثل)\n(فإن سلمت لكم نفسي ... فما لاقيته جلل)\n(وإن قتل الهوى رجلا ... فإني ذلك الرجل)\nخبرني محمد بن العباس قال حدثني عمي عبيد الله عن أخيه أبي جعفر قال عتب أبي يعني محمد بن أبي محمد على يونس بن الربيع وكان صديقه فكتب إليه\n(سأبكيك حيا لا بكيتك ميتا ... بأربعة تجري عليك همولا)\n(وأعفيك ممن طول اللقاء وإنني ... أرى اليوم لا ألقاك فيه طويلا)\n(فكيف بصبري عنك لا كيف بعدما ... حللت محلا في الفؤاد جليلا)\nال وكتب إليه يونس\n(إلى كم قد بليت وليس يبلى ... عتاب منك لي أبدا طويل)\n(إذا كثر التجني من خليل ... ولم تذنب فقد ظلم الخليل)\nخبرني عمي قال حدثني الحسن بن الفهم قال قال لي أبو سمير عبد الله بن أيوب مولى بني أمية بات عندي ليلة محمد بن أبي محمد اليزيدي فظهر لنا قنفذ فقلت له قل فيه شيئا فأنشأ يقول\n(وطارق ليل زارنا بعد هجعة ... من الليل إلا ما تحدث سامر)\n(فقلت لعبد الله ما طارق أتى ... فقال امرؤ سبقت إليه المقادر)\n(قريناه صفو الزاد حين رأيته ... وقد جاء خفاق الحشا وهو سادر)\n(جميل المحيا والرضا فإذا أبى ... حمته من الضيم الرماح الشواجر)\n(ولست تراه واضعا لسلاحه ... مدى الدهر موتورا ولا هو واتر)\nدثنا اليزيدي قال حدثني عمي الفضل قال حدثني أبو صالح بن يزداد قال حدثني أبي قال جاء محمد بن أبي محمد اليزيدي إلى باب المأمون وأنا حاضر فاستأذن فقال الحاجب قد أخذ دواء وأمرني ألا آذن لأحد قال فأمرك ألا توصل إليه رقعة قال لا فدفع إليه رقعة فيها\n(هديتي التحية للإمام ... إمام العدل والملك الهمام)\n(لأني لو بذلت له حياتي ... وما هوى لقلا للإمام)\n(أراك من الدواء الله نفعا ... وعافية تكون إلى تمام)\n(وأعقبك السلامة منه رب ... يريك سلامة في كل عام)\n(أتأذن في السلام بلا كلام ... سوى تقبيل كفك والسلام)\nقال فأوصلها وخرج فأذن له فدخل وسلم وحملت معه ألفا دينار حدثني عمي قال حدثني الفضل اليزيدي قال حدثني أخي أحمد عن أبي\nقال دخلت إلى المعتصم وهو ولي عهد وقد طلع القمر فتنفس ثم قال يا محمد قل أبياتا في معنى طلوع القمر فإنه غاب مدة كما غاب محبوب عن حبيبه ثم طلع فإن كان كما أحب فلك بكل بيت مائة دينار فقلت صوت\n(هذا شبيه الحبيب قد طلعا ... غاب كما غاب ثم قد لمعا)\n(وما أرى غيره يشاكله ... فاسأله بالله عنه ما صنعا)\n(فرق بيني وبينه قدر ... هو الذي كان بيننا جمعا)\n(فهل له عودة فأرقبها ... كما رأينا شبهه رجعا)\nقال أحسنت وحياتي ثم قال لعلويه غن في هذه الأبيات وكان حاضرا فغنى فيها وشرب عليها ليلته وأمر لي بأربعمائة دينار ولعلويه بمثلها لحن علوية في هذه الأبيات رمل","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":10,"spl":"سرق معنيين من الشعر لمسلم بن الوليد"},
{"id":"b261-13","bab":"الجزء 20","sec":"المأمون يحكم له بثلاثة آلاف دينار","page":"ج20 ص261","text":"حدثني عمي قال حدثنا الفضل بن محمد قال حدثني أخي عن أبي قال شكوت إلى المأمون دينا علي فقال إن عبد الله بن طاهر اليوم عندي وأريد الخلوة معه فإذا علمت بذلك فاستدع أن يكون دخولك أو إخراجه إليك فإني سأحكم لك عليه بمال فلما علمت أنهم قد جلسوا للشرب صرت إلى الدار وكتبت بهذين البيتين\n(يا خير سادات وأصحاب ... هذا الطفيلي على الباب)\n(فصيروا لي معكم مجلسا ... أو أخرجوا لي بعض أصحابي)\nبعثت بهما إليه فلما قرأهما قال صدق اكتبوا إليه وسلوه أن يختار فكتب إلي أما وصولك فلا سبيل إليه ولكن من تختار لنخرجه إليك فتمضي معه فكتب ما كنت لأختار على أبي العباس أحدا فقال له المأمون قم إلى صديقك فقال يا أمير المؤمنين إن رأيت أن تعفيني من ذلك أتخرجني عما شرفتني به من منادمتك وتبدلني بها منادمة ابن اليزيدي قال لا بد من ذلك أو ترضيه قال فيلحتكم قال أخاف أن يشتط أو تقصر أنت ولكني أحكم فأعدل قال قد رضيت قال تحمل إليه ثلاثة آلاف دينار معجلة قال قد فعلت فأمر صاحب بيت المال أن يحملها معي وأمر عبد الله بردها إلى بيت المال حدثني الصولي قال حدثني عون بن محمد قال كان محمد بن أبي أحمد اليزيدي يعشق جارية لسحاب يقال لها عليا وكانت من أظرف النساء لسانا وأحسنهن وجها وغناء فأعطي بها ثلاثة آلاف دينار فلم تبع واشتراها المعتصم بخمسة آلا ف دينار وذلك في خلافة المأمون وكان علي بن الهيثم جونقا صديقا لمحمد بن ابي أحمد اليزيدي فبلغ المأمون الخبر فدعا محمدا وقال ما قصتك مع عليا قال قد قلت في ذلك أبياتا فإن أذن أمير المؤمنين أنشدتها قال هاتها فأنشده\n(أشكو إلى الله حبي للعليينا ... وأنني فيهم ألقى الأمرينا)\n(حسبي عليا أمير المؤمنين فقد ... أصبحت حقا أرى حبي له دينا)\n(وحب خلي وخلصاني أبي حسن ... أعني عليا قريع التغلبيينا)\n(ورقتي لبني لي أصبت به ... وجدي به فوق وجد الآدميينا)\n(ورابع قد رمى قلبي باسهمه ... فجزت في حبه حد المحبينا)\n(وبعض من لا أسمي قد تملكه ... فرحت عنه بما أعيا المداوينا)\n(أتاه بالدين والدنيا تمكنه ... فلم يدع لي لا دنيا ولادينا)\nال فقال المأمون لولا أنه أبو إسحاق لانتزعتها منه ولكن هذا ألف دينار فخذه عوضا ولقيني المعتصم في الدار فقال لي يا محمد قد علمت ما آل إليه أمر فلانة فلا تذكرنها فقلت السمع والطاعة لأمرك أخبرني علي بن سليمان الأخفش قال حدثنا أبو العباس محمد بن الحسن بن دينار مولى بني هاشم قال حدثني جعفر بن محمد اليزيدي عن أبيه محمد بن أبي محمد قال كنت عند المأمون فقال لي يا محمد قل شعرا في نحو هذين البيتين\n(صحيح يود السقم كيما تعوده ... وإن لم تعده عاد منها رسولها)\n(ليعلم هل ترتاع عند شكاته ... كما قد يروع المشفقات خليلها)\nال فقلت\n(صحيح ود لو أمسى عليلا ... لتكتب أو يرى منكم رسولا)\n(رآك تسومه الهجران حتى ... إذا ما اعتل كنت له وصولا)\n(فود ضنا الحياة بوصل يوم ... يكون على هواك له دليلا)\n(هما موتان موت هوى وهجر ... وموت الهجر شرهما سبيلا)\nقال فأمر لي بعشرة آلاف درهم أخبرني إسماعيل بن يونس الشيعي قال حدثني أبو جعفر أحمد بن محمد بن أبي محمد اليزيدي عن أبيه قال دخلت على المأمون وهو يشرب وعنده عريب ومحمد بن الحارث بن بسخنر يغنيانه فقال أطعموا محمدا شيئا فقلت قد بدأت بذلك في دار أمير المؤمنين فقال أما ترى كيف عتق هذا الشراب حتى لم يبق إلا أقله ما أحسن ما قيل في قديم الشراب فقلت قول الحكمي\n(عتقت حتى لو اتصلت ... بلسان ناطق وفم)\n(لاحتبت في القوم ماثلة ... ثم قصت قصة الأمم)\nقال هذا كان في نفسي ثم قال اسقوا محمدا رطلين وأعطوه عشرين ألف درهم ثم نكت في الأرض ورفع رأسه ثم قال يا محمد\n(إني وأنت رضيعا قهوة لطفت ... عن العيان ودقت عن مدى الفهم)\n(لم نرتضع غير كأس درها ذهب ... والكأس حرمتها أولى من الرحم)\nال والشعر له قاله في ذلك الوقت ومما فيه غناء من شعر محمد بن أبي محمد أنشدناه محمد بن العباس عن عمه عبيد الله عن أخيه أحمد صوت\n(أنت امرؤ متجن ... ولست بالغضبان)\n(أنت امرؤ لك شأن ... فيما أرى غير شاني)\n(صرح بما عنه أكني ... أكف عنك لساني)\n(حسبي أسأت فهلا ... مننت بالغفران)\nمنها صوت\n(يا أحسن الأمة في ... عيني أما ترحمني)\n(أما تراني كامدا ... موكلا بالحزن)\n(أما ترى فيك مداراتي ... لأهل الظنن)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":11,"spl":"المأمون يحكم له بثلاثة آلاف دينار"},
{"id":"b261-14","bab":"الجزء 20","sec":"المأمون يحكم له بثلاثة آلاف دينار","page":"ج20 ص261","text":"(أصرف طرفي عنك خوفا ... منه أن يفضحني)\n(يراني الله وما ألقى ... وإن لم ترني)\nممن له شعر فيه صنعة من ولد أبي محمد اليزيدي لصلبه إبراهيم صوت\n(لا تلحني إن منحت عشقا ... من كان للعشق مستحقا)\n(ولم يقدم علي خلقا ... ولم أقدم عليه خلقا)\n(يملك رقي ولست أبغي ... من ملكه ما حييت عتقا)\n(لم أر فيمن هويت خلقا ... أعطف منه ولا أرقا)\nلشعر لإبراهيم بن محمد اليزيدي والغناء لأبي العبيس بن حمدون خفيف ثقيل مطلق وفيه لعريب رمل مزموم","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":12,"spl":"المأمون يحكم له بثلاثة آلاف دينار — إبراهيم في سيحان"},
{"id":"b261-15","bab":"الجزء 20","sec":"أخبار إبراهيم","page":"ج20 ص266","text":"أخبرني عمي قال حدثني الفضل بن محمد اليزيدي قال حدثنا أحمد عن عمه إبراهيم قال كنت مع المأمون في بلد الروم فبينا أنا في ليلة مظلمة شاتية ذات غيم وريح وإلى جانبي قبة فبرقت برقة وإذا في القبة عريب قالت إبراهيم بن اليزيدي فقلت لبيك فقالت قل في هذا البرق أبياتا ملاحا لأغني فيها فقلت\n(ماذا بقلبي من أليم الخفق ... إذا رأيت لمعان البرق)\n(من قبل الأردن أو دمشق ... لأن من أهوى بذاك الأفق)\n(فارقته وهو أعز الخلق ... علي والزور خلاف الحق)\n(ذاك الذي يملك مني رقي ... ولست أبغي ما حييت عتقي)\nال فتنفست نفسا ظننته قد قطع حيازيمها فقلت ويحك على من هذا فضحكت ثم قالت على الوطن فقلت هيهات ليس هذا كله للوطن فقالت ويلك أفتراك ظننت أنك تستفزني والله لقد نظرت نظرة مريبة في مجلس فادعاها أكثر من ثلاثين رئيسا والله ما علم أحد منهم لمن كانت إلى هذا اليوم","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":12,"spl":"المأمون يحكم له بثلاثة آلاف دينار — إبراهيم في سيحان"},
{"id":"b261-16","bab":"الجزء 20","sec":"إبراهيم في سيحان","page":"ج20 ص267","text":"أخبرني الحسن بن علي قال حدثني الفضل بن محمد اليزيدي قال حدثني أخي عن عمي إبراهيم بن أبي محمد أنه كان مع المعتصم لما خرج إلى الغزو قال فكتب في رفقة فيها فتى من أهل البصرة ظريف أديب شاعر راوية فكان لي فيه أنس وكنا لا نفترق حتى غزونا وعدنا فعاد إلى البصرة وكان له بستان حسن بسيحان فكان أكثر مقامه به وعزم لي على الشخوص إلى البصرة لحاجة عرضت لي فكان أكثر نشاطي لها من أجله فوردتها ونظرت فيما وردت له ثم سألت عنه ومضيت إليه فكان أن يستطار بي فرحا وأقمت بسيحان معه أياما وقلت في بعضها وقد اصطبحنا في بستانه\n(يا مسعدي بسيحان فديتكما ... حثا المدامة في أكناف سيحانا)\n(نهر كريم من الفردوس مخرجه ... بذاك خبرنا من كان أنبانا)\n(لا تحسداني رواحا أو مباكرة ... طيب المسير على سيحان أحيانا)\n(بشط سيحان إنسان كلفت به ... نفسي تقي ذلك الإنسان إنسانا)\n(رياه ريحاننا والكأس معملة ... لا شيء أطيب من رياه ريحانا)\n(حثا شرابكما حتى أرى بكما ... سكرا فإني قد أمسيت سكرانا)\n(ريا الحبيب وكأس من معتقه ... يهيجان لنفس الصب أشجانا)\n(سقيا لسيحان من نهر ومن وطن ... وساكنيه من السكان من كانا)\n(هم الذين عقدنا الود بينهم ... وبيننا وهم في دير مرانا)\nخبرني محمد بن العباس قال حدثني عمي عبيد الله عن جماعة من أهلنا أن إبراهيم بن أبي محمد اليزيدي كان يعاشر أبا غسان مولى منيرة وكانت له جارية مغنية يقال لها جاني فدعاه يوما أبو غسان وجلسنا للشرب فقال له لو دعوت ابن أخيك يعني محمد بن أبي محمد لنأنس به فكتب إليه إبراهيم\n(يا أكرم الناس طرا ... وأكرم الفتيان)\n(بادر إلينا لكيما ... تسقى سلاف الدنان)\n(على غناء غزال ... مهفهف فتان)\n(اشرب على وجه جان ... شرابك الخسرواني)\n(فما لجان نظير ... ومالها من مدان)\n(إلا الذي هو فرد ... وماله من ثان)\n(أعني الهلال لست ... في شهره وثمان)\n(للناس بدر منير ... يرى بكل مكان)\n(وما لنا غير بدر ... لدى أبي غسان)\n(ذكراه في كل وقت ... موصولة بلساني)\n(سبيته وسباني ... فحبه قد براني)\n(من ثم لست تراني ... أصبو إلى إنسان)\nأنشدنا أبو عبيد الله اليزيدي عن عمه الفضل لإبراهيم بن أبي محمد اليزيدي في بعض إخوانه وقد رأى منه جفوة ثم عاد واستصلحه فكتب إليه\n(من تاه واحدة فته عشرا ... كي لا يجوز بنفسه القدرا)\n(وإذا زها أحد عليك فكن ... أزهى عليه ولا تكن غمرا)\n(أرأيت من لم ترج منفعة ... منه ولم تحذر له ضرا)\n(لم يستذل وتستذل له ... بل كن أشد إذا زها كبرا)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":12,"spl":"المأمون يحكم له بثلاثة آلاف دينار — إبراهيم في سيحان"},
{"id":"b261-17","bab":"الجزء 20","sec":"يشرب ويعربد في مجلس شراب مع المأمون","page":"ج20 ص269","text":"حدثني عمي والحسن بن علي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثني أبي عن جعفر بن المأمون قال دخل إبراهيم بن أبي محمد اليزيدي على أبي وهو يشرب فأمره بالجلوس فجلس وأمر له بشراب فشرب وزاد في الشرب فسكر وعربد فأخذ علي بن صالح صاحب المصلى بيده فأخرجه فلما أصبح كتب إلى أبي\n(أنا المذنب الخطاء والعفو واسع ... ولو لم يكن ذنب لما عرف العفو)\n(ثملت فأبدت مني الكاس بعض ما ... كرهت وما إن يستوي السكر والصحو)\n(ولولا حميا الكأس كان احتمال ما ... بدهت به لا شك فيه هو السرو)\n(ولا سيما إذ كنت عند خليفة ... وفي مجلس ما إن يجوز به اللغو)\n(تنصلت من ذنبي تنصل ضارع ... إلى من لديه يغفر العمد والسهو)\n(فإن تعف عني تلف خطوي واسعا ... والا يكن عفو فقد قصر الخطو)\nحدثني عمي قال حدثنا الفضل بن محمد اليزيدي قال جاء عمي إبراهيم إلى هارون بن المأمون فصادفه قد خلا هو وجماعة من المعتزلة فلم يصل إليه وحجب عنه فكتب إليه\n(غلبت عليكم هذه القدريه ... فعليكم مني السلام تحيه)\n(آتيكم شوقا فلا ألقاكم ... وهم لديكم بكرة وعشيه)\n(هرون قائدهم وقد حفت به ... أشياعه وكفى بتلك بليه)\n(لكن قائدنا الإمام ورأينا ... ما قد رآه فنحن مأونية)\nخبرني عمي قال حدثني الفضل قال كان لعمي إبراهيم ابن يقال له إسحاق وكان يألف غلاما من أولاد الموالي فلما خرج المعتصم إلى الشام خرج إبراهيم معه وخرج الغلام الذي يألفه في العسكر وعرف إبراهيم أنه قد صحب فتى من فتيان العسكر غير ابنه فكتب عمي إبراهيم إلى ابنه\n(قل لأبي يعقوب إن الذي ... يعرفه قد فعل الحوبا)\n(كان محبا لك فيما مضى ... فالآن قد صادف محبوبا)\n(يركب هذا ذا وذا ذا فما ... ينفك تصعيدا وتصويبا)\nرأس إسحاق فديناه فما ... ينفك تصعيدا وتصويبا أرى قرونا قد تجللنه ... منصوبة شعبن تشعيبا أظنه يعجز عن حملها ... إذ ركبت في الرأس تركيبا يا رحمتا لابني على ضعفه ... يحمل منهن أعاجيبا\nحدثني عمي قال حدثني فضل اليزيدي قال كتبت إلى عمي إبراهيم أستعين به في حاجة لي وأستزيده من عنايته بأموري وأطالبه أن يتوفر نصيبي لديه وفيما أبتغيه منه فكتب إلي\n(فديتك لو لم تكن لي قريبا ... وكنت امرأ أجنبيا غربيا)\n(مع البر منك وما يستجر ... به مسخفا إليك اللبيبا)\n(لما إن جعلت لخلق سواك ... مثل نصيبك مني نصيبا)\n(وكنت المقدم ممن أود ... وازداد حقك عندي وجوبا)\n(تلطف لما قد تكلمت فيه ... فما زلت في الحاج شهما نجيبا)\n(وراوض أبا حسن إن رأيت ... واحتل برفقك حتى يجيبا)\n(فإن هو صار إلى ما تريد ... وإلا استعنت عليه الحبيبا)\n(وما لا يخالف ما تشتهيه ... لتلفيه غير شك مجيبا)\n(يودك خاقان ودا عجيبا ... كذاك الأديب يحب الأديبا)\n(وأنت تكافيه بل قد تزيد ... عليه وتجمع فيه ضروبا)\n(تثيب أخاك على الورد منه ... وذو اللب يأنف ألا يثيبا)\n(ولا سيما إذ براه الإله ... كالبدر يدعو إليه القلوبا)\n(يرى المتمني له ردفه ... كثيبا وأعلاه يحكي القضيبا)\n(وقد فاق في العلم والفهم منه ... كما تم ملحا وحسنا وطيبا)\n(ويبلغ فيما يقولون ليس ... يعاف إذا ناولوه القضيبا)\n(ولكنه وافق الزاهدين ... فخاب وقد ظن أن لن يخيبا)\n(وإن ركب المرء فيه هواه ... عاث فتطهيره أن يثوبا)\n(إذا زارت الشاة ذئبا طبيبا ... فلا تأمنن على الشاة ذيبا)\n(وعند الطبيب شفاء السقيم ... إذا اعتل يوما وجاء الطبيبا)\n(ولست ترى فارسا في الأنام ... إلا وثوبا يجيد الركوبا)\nخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله قال وحدثني أخي أحمد قال زامل المأمون في بعض أسفاره بين يحيى بن أكثم وعبادة المخنث فقال عمي إبراهيم في ذلك\n(وحاكم زامل عباده ... ولم يزل تلك له عاده)\n(لو جاز لي حكم لما جاز أن ... يحكم في قيمة لباده)\n(كم من غلام عز في أهله ... وافت قفاه منه سجاده)\nقال في يحيى أيضا\n(وكنا نرجي أن نرى العدل ظاهرا ... فأعقبنا بعد الرجاء قنوط)\n(متى تصلح الدنيا ويصلح أهلها ... وقاضي قضاة المسلمين يلوط)\nأخبرني عمي حدثنا أبو العيناء قال نظر المأمون إلى يحيى بن أكثم يلحظ خادما له فقال للخادم تعرض له إذا قمت فإني سأقوم للوضوء وأمره ألا يبرح وعد إلي بما يقول لك وقام المأمون وأمر يحيى بالجلوس فلما غمزه الخادم بعينه قال يحيى ( لولا أنتم لكنا مؤمنين","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":13,"spl":"يشرب ويعربد في مجلس شراب مع المأمون"},
{"id":"b261-18","bab":"الجزء 20","sec":"يشرب ويعربد في مجلس شراب مع المأمون","page":"ج20 ص269","text":"فمضى الخادم إلى المأمون فأخبره فقال له عد\nإليه فقال له ( أنحن صددناكم عن الهدى بعد إذ جاءكم بل كنتم مجرمين\nخرج الخادم إليه فقال له ما أمره به المأمون فأطرق يحيى وكاد يموت جزعا وخرج المأمون وهو يقول\n(متى تصلح الدنيا ويصلح أهلها ... وقاضي قضاة المسلمين يلوط)\nم وانصرف واتق الله وأصلح نيتك حدثنا اليزيدي قال حدثني ابن عمي إسحاق بن إبراهيم بن أبي محمد اليزيدي عن أبيه إبراهيم قال كنت عند المأمون يوما وبحضرته عريب فقالت لي على سبيل الولع بي يا سلعوس وكان جواري المأمون يلقبنني بذلك عبثا فقلت لها\n(قل لعريب لا تكوني مسلعسه ... وكوني كتنريف وكوني كمونسه)\nفقال المأمون\n(فإن كثرت منك الأقاويل لم يكن ... هنالك شك أن ذا منك وسوسة)\nال فقلت كذا والله يا أمير المؤمنين أردت أن أقول وعجبت من ذهن المأمون","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":14,"spl":"يشرب ويعربد في مجلس شراب مع المأمون — وممن غني في شعره من ولد أبي محمد اليزيدي أبو جعفر أح"},
{"id":"b261-19","bab":"الجزء 20","sec":"وممن غني في شعره من ولد أبي محمد اليزيدي أبو جعفر أحمد بن محمد بن أبي","page":"ج20 ص274","text":"محمد فمن ذلك صوت\n(شوقي إليك على الأيام يزداد ... والقلب مذ غبت للأحزان معتاد)\n(يا لهف نفسي على دهر فجعت به ... كأن أيامه في الحسن أعياد)\nلشعر لأحمد بن محمد بن أبي محمد والغناء لبحر هزج وفيه ثاني ثقيل مطلق ذكر الهشامي أنه لإسحاق وما أراه أصاب ولا هو في جامع إسحاق ولا يشبه صنعته وكان أحمد راوية لعلم أهله فاضلا أديبا وكان أسن ولد محمد بن أبي محمد وكان إخوته جميعا يأثرون علوم جدهم وعمومتهم عنه وقد أدرك أبا محمد وأظن أنه روى عنه أيضا إلا أني لم أذكر شيئا من ذلك وقت ذكري إياه فأحكيه عنه أخبرني الحسن بن علي قال حدثنا الفضل بن محمد اليزيدي قال حدثني أخي أبو جعفر قال كنت عند جعفر بن المأمون مقيما فلما أردت الانصراف منعني فبت عنده وزارته لما أصبحنا عريب في جواريها وبت فاحتبسها من غد\nفاستطبت المقام أيضا فأقمت فكتب إلي عمي إبراهيم بن محمد اليزيدي\n(شردت يا هذا شرود البعير ... وطالت الغيبة عند الأمير)\n(أقمت يومين وليليهما ... وثالثا تحبى ببر كثير)\n(يوم عريب مع إحسانها ... إن طالت الأيام يوم قصير)\n(لها أغان غير مملولة ... منها ولا تخلق عند الكرور)\nير ملوم يا أبا جعفر ... أن تؤثر اللهو ويوم السرور فاجعل لك منا نصيبا فما ... إن كنت عن مجلسنا بالنفور وصر إلينا غير ما صاغر ... أصارك الرحمن خير المصير إن لم يكن عندي غناء ولا ... عود فعندي القمر بالنردشير والذكر بالعلم الذي قد مضى ... بأهله حادث صرف الدهور وهو جديد عندنا نهجه ... أعلامه تحويه منا الصدور فالحمد لله على كل ما ... أولى وأبلى ولربي الشكور\nدثنا محمد بن العباس اليزيدي قال حدثني عمي الفضل قال سمعت أخي أبا جعفر أحمد بن محمد يقول دخلت إلى المعتصم يوما وبين يديه خادم وضيء جميل وسيم فطلعت عليه الشمس فما رأيت أحسن منها على وجهه فقال لي يا أحمد قل في هذا الخادم شيئا وصف طلوع الشمس عليه وحسنها فقلت\n(قد طلعت شمس على شمس ... وطاب لي الهوى مع الأنس)\n(وكنت أقلي الشمس فيما مضى ... فصرت أشتاق إلى الشمس)\nدثني اليزيدي قال حدثني عمي الفضل قال\nكتب إلى أخي بعض إخوانه ممن كان يألفه ويديم زيارته ثم انقطع عنه يعتذر إليه من تأخره عنه فكتب إليه\n(إني امرؤ أعذر إخواني ... في تركهم بري وإتياني)\n(لأنه لا لهو عندي ولا ... لي اليوم جاه عند سلطان)\n(وأكثر الإخوان في دهرنا ... أصحاب تمييز ورجحان)\n(فمن أتاني منعما مفضلا ... فشكره عندي شكران)\n( ومن جفاني لم يكن لومه ... عندي ولا تعنيفه شاني أعفو عن السيئ من فعلهم ... وأتبع الحسنى بإحسان حسب صديقي أنه واثق ... مني بإسراري وإعلاني","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":14,"spl":"يشرب ويعربد في مجلس شراب مع المأمون — وممن غني في شعره من ولد أبي محمد اليزيدي أبو جعفر أح"},
{"id":"b261-20","bab":"الجزء 20","sec":"ينشد المأمون شعرا وهو لا يزال غلاما","page":"ج20 ص276","text":"حدثني اليزيدي قال حدثني أبي عن عمي عن أبي جعفر أحمد بن محمد قال دخلت على المأمون وهو في مجلس غاص بإهله وأنا يومئذ غلام فاستأذنت في الإنشاد فأذن فأنشدته مديحا لي مدحته به وكان يستمع للشاعر ما دام في تشبيب أو وصف ضرب من الضروب حتى إذا بلغ إلى مديحه لم يسمع منه إلا بيتين أو ثلاثة ثم يقول للمنشد حسبك ترفعا فأنشدته\n(يا من شكوت إليه ما ألقاه ... وبذلت من وجدي له أقصاه)\n(فأجابني بخلاف ما أملته ... ولربما منع الحريص مناه)\n(أترى جميلا أن شكا ذو صبوة ... فهجرته وغضبت من شكواه)\n(يكفيك صمت أو جواب مؤيس ... إن كنت تكره وصله وهواه)\n(موت المحب سعادة إن كان من ... يهواه يزعم أن ذاك رضاه)\nفلما صرت إلى المديح قلت\n(أبقى لنا الله الإمام وزاده ... عزا إلى العز الذي أعطاه)\n(فالله مكرمنا بأنا معشر ... عتقاء من نعم العباد سواه)\nسر بذلك وضحك وقال جعلنا الله وإياكم ممن يشكر النعمة ويحسن العمل أخبرنا محمد بن العباس قال حدثني أبي عن أخيه أبي جعفر قال دخلت يوما على المأمون بقارا وهو يريد الغزو فأنشدته شعرا مدحته فيه أوله\n(يا قصر ذا النخلات من بارا ... إني حللت إليك من قارا)\n(أبصرت أشجارا على نهر ... فذكرت أشجارا وأنهارا)\n(لله أيام نعمت بها ... بالقفص أحيانا وفي بارا)\n(إذ لا أزال أزور غانية ... ألهو بها وأزور خمارا)\n(لا أستجيب لمن دعا لهدى ... وأجيب شطارا ودعارا)\n(أعصي النصيح وكل عاذلة ... وأطيع أو تارا ومزمارا)\nقال فغضب المأمون وقال أنا في وجه عدو وأحض الناس على الغزو وأنت تذكرهم نزهة بغداد فقلت الشيء بتمامه ثم قلت\n(فصحوت بالمأمون عن سكري ... ورأيت خير الأمر ما اختارا)\n(ورأيت طاعته مؤدية ... للفرض إعلانا وإسرارا)\n(فخلعت ثوب الهزل عن عنقي ... ورضيت دار الجد لي دارا)\n(وظللت معتصما بطاعته ... وجواره وكفى به جارا)\n(إن حل أرضا فهي لي وطن ... وأسير عنها حيثما سارا)\nقال له يحيى بن أكثم ما أحسن ما قال يا أمير المؤمنين أخبر أنه كان في سكر وخسار فترك ذلك وارعوى وآثر طاعة خليفته وعلم أن الرشيد فيها فسكن وأمسك حدثني الصولي قال حدثني محمد بن يحيى بن أبي عباد قال حدثني هارون بن محمد بن عبد الملك الزيات عن أبيه قال دعا المعتصم ذات يوم المأمون فجاءه فأجلسه في بيت على سقفه جامات فوقع ضوء الشمس من وراء تلك الجامات على وجه سيما التركي غلام المعتصم وكان المعتصم أوجد الناس به ولم يكن في عصره مثله فصاح المأمون يا أحمد بن محمد اليزيدي وكان حاضرا فقال انظر إلى ضوء الشمس على وجه سيما التركي أرأيت أحسن من هذا قط وقد قلت\n(قد طلعت شمس على شمس ... وزالت الوحشة بالأنس)\nأجز يا أحمد فقلت\n(قد كنت أشنا الشمس فيما مضى ... فصرت أشتاق إلى الشمس)\nال وفطن المعتصم فعض على شفته لأحمد فقال أحمد للمأمون والله لئن لم يعلم الحقيقة من أمير المؤمنين لأقعن معه فيما أكره فدعاه المأمون فأخبره الخبر فضحك المعتصم فقال له المأمون كثر الله في غلمانك مثله إنما استحسنت شيئا فجرى ما سمعت لا غيره حدثني الصولي قال حدثني عون بن محمد قال حدثني أحمد بن محمد اليزيدي قال كنا بين يدي المأمون فأنشدته مدحا فقال لئن كانت حقوق أصحابي تجب علي لطاعتهم بأنفسهم فإن أحمد ممن تجب له المراعاة لنفسه وصحبته ولأبيه وخدمته ولجده وقديم خدمته وحرمته وإنه للعريق في خدمتنا فقلت قد علمتني يا أمير المؤمنين كيف أقول ثم تنحيت ورجعت إليه فأنشدته\n(لي بالخليفة أعظم السبب ... فبه أمنت بوائق العطب)\n(ملك غذتني كفه وأبي ... قبلي وجدى كان قبل أبي)\n(قد خصني الرحمن منه بما ... أسمو به في العجم والعرب)\nضحك وقال قد نظمت يا أحمد ما نثرناه هذا آخر أخبار اليزيديين وأشعارهم التي فيها صنعة\nصوت\n(أفي كل يوم أنت من غبر الهوى ... إلى الشم من أعلاه ميلاء ناظر)\n(بعمشاء من طول البكاء كأنما ... بها خزر أو طرفها متختازر)\nروضه من الطويل والغبر البقية من الشيء يقال فلان في غبر من علته وأكثر ما يستعمل في هذا ونحوه والشم الطوال والأعلام جمع علم وهو الجبل قالت الخنساء\n(وإن صخرا لتأتم الهداة به ... كأنه علم في رأسه نار)\nالخزر ضيق العين وصغرها ومنه سمي الخزر بذلك لصغر أعينهم قال الراجز\n(إذا تخازرت وما بي من خزر ... ثم كسرت الطرف من غير عور)","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":15,"spl":"ينشد المأمون شعرا وهو لا يزال غلاما"},
{"id":"b261-21","bab":"الجزء 20","sec":"ينشد المأمون شعرا وهو لا يزال غلاما","page":"ج20 ص276","text":"الشعر لرجل من قيس يقال كعب ويلقب بالمخبل والغناء لإبراهيم ثقيل أول بالوسطى ومن الناس من يروي الشعر لغير هذا الرجل وينسبه إلى ذي الرمة ويجعل فيه مية مكان ميلاء ويقال إن اللحن لابن المكي وقد نسب إلى غيرهما والصحيح ما ذكرناه أولا","topic":"أخبار أبي محمد ونسبه","topicNo":261,"sp":16,"spl":"ينشد المأمون شعرا وهو لا يزال غلاما"},
{"id":"b262-1","bab":"الجزء 20","sec":"أخبار المخبل القيسي ونسبه","page":"ج20 ص280","text":"قال عبد الله بن أبي سعد الوراق فيما أخبرني به حبيب بن نصر المهلبي إجازة عنه حدثني علي بن الصباح بن الفرات قال أخبرني علي بن الحسن بن أيوب النبيل عن رباح بن قطيب بن زيد الأسدي قال كانت عند رجل من قيس يقال له كعب بنت عم له وكانت أحب الناس إليه فخلا بها ذات يوم فنظر إليها وهي واضعة ثيابها فقال يا أم عمرو هل ترين أن الله خلق أحسن منك قالت نعم أختي ميلاء هي أحسن مني قال فإني أحب أن أنظر إليها فقالت إن علمت بك لم تخرج إليك ولكن كن من وراء الستر ففعل وأرسلت إليها فجاءتها فلما نظر إليها عشقها وانتظرها حتى راحت إلى أهلها فاعترضها فشكا إليها حبها فقالت والله يا ابن عم ما وجدت من شيء إلا وقد وقع لك في قلبي أكثر منه وواعدته مرة أخرى فأتتهما أم عمرو وهما لا يعلمان فرأتهما جالسين فمضت إلى إخوتها وكانوا سبعة فقالت إما أن تزوجوا ميلاء كعبا وإما أن تكفوني أمرها وبلغهما الخبر ووقف إخوتها على ذلك فرمى بنفسه نحو الشام حياء منهم وكان منزله ومنزل أهله الحجاز فلم يدر أهله ولا بنو عمه أين ذهب فقال كعب","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":0,"spl":"أخبار المخبل القيسي ونسبه — شعره في أرض الغربة"},
{"id":"b262-2","bab":"الجزء 20","sec":"شعره في أرض الغربة","page":"ج20 ص281","text":"(أفي كل يوم أنت من لاعج الهوى ... إلى الشم من أعلام ميلاء ناظر)\n(بعمشاء من طول البكاء كأنما ... بها خزر أوطرفها متخازر)\n(تمنى المنى حتى إذا ملت المنى ... جرى واكف من دمعها متبادر)\n(كما أرفض عنها بعد ما ضم ضمة ... بخيط الفتيل اللؤلؤ المتناثر)\nال فرواه عنه رجل من أهل الشام ثم خرج بعد ذلك الشامي يريد مكة فاجتاز بأم عمرو وأختها ميلاء وقد ضل الطريق فسلم عليهما ثم سألهما عن الطريق فقالت أم عمرو يا ميلاء صفي له الطريق فذكر لما نادت يا ميلاء شعر كعب هذا فتمثل به فعرفت أم عمرو الشعر فقالت يا عبد الله من أين أنت قال رجل من أهل الشام قالت من أين رويت هذا الشعر قال رويته عن أعرابي بالشام قالت أو تدري ما اسمه فقال سمعت أنه كعب فأقسمت عليه لا تبرح حتى تعرف أخوتنا بذلك فنحسن إليك نحن وهم وقد أنعمت علينا قال أفعل وإني لأروي له شعرا آخر فما أدري أتعرفانه أم لا فقالت نسألك بالله إلا أسمعتنا قال سمعته يقول\n(خليلي قد قست الأمور ورمتها ... بنفسي وبالفتيان كل زمان)\n(فلم أخف سوءا للصديق ولم أجد ... خليا ولا ذا البث يستويان)\n(من الناس إنسانان ديني عليهما ... مليئان لو شاءا لقد قضياني)\n(خليلي أما أم عمرو فمنهما ... وأما عن الأخرى فلا تسلاني)\n(بلينا بهجران ولم أر مثلنا ... من الناس إنسانين يهتجران)\n(أشد مصافاة وأبعد من قلى ... وأعصىلواش حين يكتفيان)\n(تحدث طرفانا بما في صدورنا ... إذا استعجمت بالمنطق الشفتان)\n(فوالله ما أدري أكل ذوي الهوى ... على ما بنا أو نحن مبتليان)\n(فلا تعجبا مما بي اليوم من هوى ... فبي كل يوم مثل ما تريان)\n(خليلي عن أي الذي كان بيننا ... من الوصل أم ماضي الهوى تسلان)\n(وكنا كريمي معشر حم بيننا ... هوى فحفظناه بحسن صيان)\n(سلاه بأم العمرو من هي إذ بدا ... به سقم جم وطول ضمان)\n(فما زادنا بعد المدى نقض مرة ... ولا رجعنا من علمنا ببيان)\n(خليلي لا والله ما لي بالذي ... تريدان من هجر الحبيب يدان)\n(ولا لي بالبين اعتلاء إذا نأت ... كما أنتما بالبين معتليان)\nال ونزل الرجل ووضع رحله حتى جاء إخوتهما فأخبراهم الخبر وكانوا مهتمين بكعب وكان كعب أظرفهم وأشعرهم فأكرموا الرجل وحملوه على راحلة ودلوه على الطريق وطلبوا كعبا فوجدوه بالشام فأقبلوا به حتى إذا كانوا في ناحية ماء أهلهم إذا الناس قد اجتمعوا عند البيوت وكان كعب ويحك يا غلام من أبوك فقال رجل يقال له كعب قال وعلى أي شيء قد اجتمع الناس وأحس قلبه بالشر قال اجتمعوا على خالتي ميلاء قال وما قصتها قال ماتت فزفر زفرة مات منها مكانه فدفن حذاء قبرها قال وقال كعب وهو بالشام\n(أحقا عباد الله أن لست ماشيا ... بمرحاب حتى يحشر الثقلان)\n(ولا لاهيا يوما إلى الليل كله ... ببيض لطيفات الخصور رواني)\n(يمنيننا حتى تريع قلوبنا ... ويخلطن مطلا ظاهرا بليان)\n(فعيني ياعيني حتام أنتما ... بهجران أم العمرو تختلجان)\n(أما أنتما إلا علي طليعة ... على قرب أعدائي كما تريان)\n(فلو أن أم العمرو وأضحت مقيمة ... بمصر وجثماني بشحر عمان)\n(إذا لرجوت الله يجمع شملنا ... فإنا على ما كان ملتقيان)","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":0,"spl":"أخبار المخبل القيسي ونسبه — شعره في أرض الغربة"},
{"id":"b262-3","bab":"الجزء 20","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج20 ص284","text":"صوت\n(من الناس إنسانان ديني عليهما ... مليئان لو شاءا لقد قضياني)\n(خليلي أما أم عمرو فمنهما ... وأما عن الأخرى فلا تسلاني)\nروضه من الطويل الشعر على ما في هذا الخبر لكعب المذكورة قصته وروى المفضل بن سلمة وأبو طالب بن أبي طاهر هذين البيتين مع غيرهما لابن الدمينة الخثعمي والغناء لإبراهيم الموصلي خفيف رمل بالوسطى ذكره أبو العبيس عنه وذكر ابن المكي أنه لعلويه والأبيات التي\nذكرنا أن المفضل بن سلمة وابن أبي طاهر روياها لابن الدمينة مع البيتين اللذين فيهما الغناء هي\n(من الناس إنسانان ديني عليهما ... مليئان لو شاءا لقد قضياني)\n(خليلي أما أم عمرو فمنهما ... وأما عن الأخرى فلا تسلاني)\n(منوعان ظلامان ما ينصفانني ... بدليهما والحسن قد خلباني)\n(من البيض نجلاء العيون غذاهما ... نعيم وعيش ضارب بجران)\n(أفي كل يوم أنت رام بلادها ... بعينين إنساناهما غرقان)\n(إذا اغرورقت عيناي قال صحابتي ... لقد أولعت عيناك بالهملان)\nوقد روي أيضا أن هذا البيت\n(أفي كل يوم أنت رام بلادها ... )\nعروة بن حزام\n(ألا فاحملاني بارك الله فيكما ... إلى حاضر الروحاء ثم ذراني)\nخبرني محمد بن خلف وكيع قال حدثني أبو سعيد القيسي قال حدثني سليمان بن عبد العزيز قال حدثني خارجة المالي قال حدثني من رأى عروة بن حزام يطاف به حول البيت قال فقلت له من أنت قال أنا الذي أقول\n(أفي كل يوم أنت رام بلادها ... بعينين إنساناهما غرقان)\n(ألا فاحملاني بارك الله فيكما ... إلى حاضر الروحاء ثم ذراني)\nفقلت زدني قال لا ولا حرف","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":1,"spl":"نسبة ما في هذا الخبر من الغناء","partial":1},
{"id":"b262-4","bab":"الجزء 20","sec":"التغني بالصوت المنسوب إليه يهيج الواثق","page":"ج20 ص286","text":"ويقال إن الذي هاج الواثق على القبض على أحمد بن الخصيب وسليمان بن وهب أنه غنى هذا الصوت أعني\n(من الناس إنسانان ديني عليهما ... )\nدعا خادما كان للمعتصم ثم قال له اصدقني وإلا ضربت عنقك قال سل يا أمير المؤمنين عما شئت قال سمعت أبي وقد نظر إليك يتمثل بهذين البيتين ويومئ إليك إيماء تعرفه فمن اللذان عنى قال قال لي إنه وقف على إقطاع أحمد بن الخصيب وسليمان بن وهب ألفي دينار وأنه يريد الإيقاع بهما فكان كلما رآني يتمثل بهذين البيتين قال صدقني والله والله سبقاني بهما كما سبقاه ثم أوقع بهما وأخبرني محمد بن يحيى الصولي حدثني ميمون بن هارون قال نظر الواثق إلى أحمد بن الخصيب يمشي فتمثل\n(من الناس إنسانان ديني عليهما ... )\nوذكر البيتين وأشار بقوله\n(خليلي أما أم عمرو فمنهما ... )\nلى أحمد بن الخصيب فلما بلغ هذا سليمان بن وهب قال إنا لله أحمد بن الخصيب والله أم عمرو وأنا الأخرى قال ونكبهما بعد أيام وقد قيل إن محمد بن عبد الملك الزيات كان السبب في نكتبهما\nأخبرنا محمد بن يحيى قال حدثنا عون بن محمد الكندي قال كانت الخلافة أيام الواثق تدور على إيتاخ وعلى كاتبه سليمان بن وهب وعلى أشناس وكاتبه أحمد بن الخصيب فعمل الوزير محمد بن عبد الملك الزيات قصيدة وأوصلها إلى الواثق على أنها لبعض أهل العسكر وهي\n(يابن الخلائف والأملاك إن نسبوا ... حزت الخلافة عن آبائك الأول)\n(أجرت أم رقدت عيناك عن عجب ... فيه البرية من خوف ومن وهل)\n(وليت أربعةأمر العباد معا ... وكلهم حاطب في حبل محتبل)\n(هذا سليمان قد ملكت راحته ... مشارق الأرض من سهل ومن جبل)\n(ملكته السند فالشحرين من عدن ... إلى الجزيرة فالأطراف من ملل)\n(خلافة قد حواها وحده فمضت ... أحكامه في دماء القوم والنفل)\n(وابن الخصيب الذي ملكت راحته ... خلافة الشأم والغازين والقفل)\n(فنيل مصر فبحر الشأم قد جريا ... بما أراد من الأموال والحلل)\n(كأنهم في الذي قسمت بينهم ... بنو الرشيد زمان القسم للدول)\n(حوى سليمان ما كان الأمين حوى ... من الخلافة والتبليغ للأمل)\n(وأحمد بن خصيب في إمارته ... كالقاسم بن الرشيد الجامع السبل)\n(أصبحت لا ناصح يأتيك مستترا ... ولا علانية خوفا من الحيل)\n(سل بيت مالك أين المال تعرفه ... وسل خراجك عن أموالك الجمل)\n(كم في حبوسك ممن لا ذنوب لهم ... أسرى التكذب في الأقياد والكبل)\n(سميت باسم الرشيد المرتضى فبه ... قس الأمور التي تنجي من الزلل)\n(عث فيهم مثل ما عاثت يداه معا ... على البرامك بالتهديم للقلل)\nلما قرأ الواثق الشعر غاظه وبلغ منه ونكب سليمان بن وهب وأحمد بن الخصيب وأخذ منهما ومن أسبابهما ألف ألف دينار فجعلها في بيت المال فقال أحمد بن أبي فنن\n(نزلت بالخائنين سنه ... سنة للناس ممتحنه)\n(سوغت ذا النصح بغيته ... وأزالت دولة الخونه)\n(فترى أهل العفاف بها ... وهم في دولة حسنه)\n(وترى من جار همته ... أن يؤدي كل ما احتجنه)\nقال إبراهيم بن العباس لابن الزيات\n(إيها أبا جعفر وللدهر كررات ... وعما يريب متسع)\n(أرسلت ليثا على فرائسه ... وأنت منها فانظر متى تقع)\n(لكنه قوته وفيك له ... وقد تقضت أقواته شبع)\nهي أبيات وقد كان أحمد بن أبي داود حمل الواثق على الإيقاع بابن الزيات وأمر علي بن الجهم فقال فيه\n(لعائن الله موفرات ... مصبحات ومهجرات)\n(على ابن عبد الملك الزيات ... عرض شمل الملك للشتات)\n(يرمي الدواوين بتوقيعات ... معقدات غير مفتوحات)\n(أشبه شيء برقى الحيات ... كأنها بالزيت مدهونات)\n(بعد ركوب الطوف في الفرات ... وبعد بيع الزيت بالحبات)\n(سبحان من جل عن الصفات ... هارون يابن سيد السادات)\n(أما ترى الأمور مهملات ... تشكو إليك عدم الكفاة)\nهي أبيات فهم الواثق بالقبض على ابن الزيات وقال لقد صدق قائل هذا الشعر ما بقي لنا كاتب فطرح نفسه على إسحاق بن إبراهيم وكانا مجتمعين على عداوة ابن أبي داود فقال للواثق أمثل ابن الزيات مع خدمته وكفايته يفعل به هذا وما جنى عليك وما خانك وإنما دلك على خونة أخذت ما اختانوه فهذا ذنبه وبعد فلا ينبغي لك أن تعزل أحدا أو تعد مكانه جماعة يقومون مقامه فمن لك بمن يقوم مقامه فمحا ما كان في نفسه عليه ورجع له","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":2,"spl":"التغني بالصوت المنسوب إليه يهيج الواثق","partialRef":{"sid":"b262-2","gi":1,"vi":3,"side":0},"partial":1},
{"id":"b262-5","bab":"الجزء 20","sec":"التغني بالصوت المنسوب إليه يهيج الواثق","page":"ج20 ص286","text":"وكان إيتاخ صديقا لابن أبي داود فكان يغشاه كثيرا فقال له بعض كتابه إن هذا بينه وبين الوزير ما تعلم وهو يجيئك دائما ولا تأمن أن يظن الوزير بك ممالأة عليه فعرفه ذلك فلما دخل ابن أبي داود إليه خاطبه في هذا المعنى فقال إني والله ما أجيئك متعززا بك من ذلة ولا متكثرا من قلة ولكن أمير المؤمنين رتبك رتبة أوجبت لقاءك فإن لقيناك فله وإن تأخرنا عنك فلنفسك ثم خرج من عنده فلم يعد إليه وفي هذه القصة أخبار كثيرة يطول ذكرها ليس هذا موضعها وإنما ذكرنا ها هنا هذا القدر منها كما يذكر الشيء بقرائنه صوت\n(عش فحبيك سريعا قاتلي ... والضنى إن لم تصلني واصلي)\n(ظفر الشوق بقلب دنف ... فيك والسقم بجسم ناحل)\n(فهما بين اكتئاب وضنى ... تركاني كالقضيب الذابل)\nالشعر لخالد الكاتب والغناء للمسدود رمل مطلق في مجرى الوسطى وذكر جحظة أن هذا الرمل أخذ عنه وأنه أول صوت سمعه فكتبه","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":3,"spl":"التغني بالصوت المنسوب إليه يهيج الواثق — أخبار خالد الكاتب"},
{"id":"b262-6","bab":"الجزء 20","sec":"أخبار خالد الكاتب","page":"ج20 ص291","text":"هو خالد بن يزيد ويكنى أبا الهيثم من أهل بغداد وأصله من خراسان وكان أحد كتاب الجيش ووسوس في آخر عمره قيل إن السوداء غلبت عليه وقال قوم كان يهوى جارية لبعض الوجوه ببغداد فلم يقدر عليها وولاه محمد بن عبد الملك الإعطاء في الثغور فخرج فسمع في طريقه منشدا ينشد ومغنية تغني\n(من كان ذا شجن بالشام يطلبه ... ففي سوى الشام أمسى الأهل والشجن)\nبكى حتى سقط على وجهه مغشيا عليه ثم أفاق مختلطا واتصل ذلك حتى وسوس وبطل وكان اتصل بعلي بن هشام وإبراهيم بن المهدي وكان سبب اتصاله بعلي بن هشام أنه صحبه في وقت خروجه إلى قم في جملة كتاب الإعطاء فبلغه وهو في طريقه أن خالدا يقول الشعر فأنس به وسر به وأحضره فأنشده قوله\n(يا تارك الجسم بلا قلب ... إن كنت أهواك فما ذنبي)\n(يا مفردا بالحسن أفردتني ... منك بطول الهجر والعتب)\nإن تك عيني أبصرت فتنة ... فهل على قلبي من عتب حسيبك الله لما بي كما ... أنك في فعلك بي حسبي\nلمسدود في هذه الأبيات رمل طنبوري مطلق من رواية الهشامي قال فجعله علي بن هشام في ندمائه إلى أن قتل ثم صحب الفضل بن مروان فذكره للمعتصم وهو بالماحوزة قبل أن يبني سر من رأى فقال خالد\n(عزم السرور على المقام ... بسر من را للإمام)\n(بلد المسرة والفتوح ... المستنيرات العظام)\n(وتراه أشبه منزل ... في الأرض بالبلد الحرام)\n(فالله يعمره بمن ... أضحى به عز الأنام)\nاستحسنها الفضل بن مروان وأوصلها إلى المعتصم قبل أن يقال في بناء سر من رأى شيء فكانت أول ما أنشد في هذا المعنى من الشعر فتبرك بها وأمر لخالد بخمسة آلاف درهم وذكر ذلك كله إسماعيل بن يحيى الكاتب وذكر اليوسفي صاحب الرسائل أن خالدا قال أيضا في ذلك\n(بين صفو الزمان عن كدره ... في ضحكات الربيع عن زهره)\n(يا سر من را بوركت من بلد ... بورك في نبته وفي شجره)\n(غرس جدود الأمام ينبته ... بابك والمازيار من ثمره)\n(فالفتح والنصر ينزلان به ... والخصب في تربه وفي شجره)\nغنى مخارق في هذه الأبيات فسأله المعتصم لمن هذا الشعر فقال لخالد يا أمير المؤمنين قال الذي يقول\n(كيف ترجى لذاذة الإغتماض ... لمريض من العيون المراض)\nقال محمد بن عبد الملك نعم يا أمير المؤمنين هو له ولكن بضاعته لا تزيد على أربعة أبيات فأمر له المعتصم بأربعة آلاف درهم وبلغ خالدا الخبر فقال لأحمد بن عبد الوهاب صاحب محمد بن عبد الملك وقيل لأبي جعفر أعزه الله إذا بلغت المراد في أربعة أبيات فالزيادة فضل قال اليوسفي ولما قال خالد في صفة سر من رأى قصيدته التي يقول فيها\n(اسقني في جرائر وزقاق ... لتلاقي السرور يوم التلاق)\n(من سلاف كأن في الكأس منه ... عبرات من مقلتي مشتاق)\n(في رياض بسر من را إلى الكرخ ... ودعني من سائر الآفاق)\n(باد كارات كل فتح عظيم ... لإمام الهدى أبي إسحاق)\nوهي قصيدة لقيه دعبل فقال يا أبا الهيثم كنت صاحب مقطعات فداخلت الشعراء في القصائد الطوال وأنت لا تدوم على ذلك ويوشك أن تتعب بما تقول وتغلب عليه فقال له خالد لو عرفت النصح منك لغيري لأطعتك في نفسي","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":3,"spl":"التغني بالصوت المنسوب إليه يهيج الواثق — أخبار خالد الكاتب"},
{"id":"b262-7","bab":"الجزء 20","sec":"خلاف خالد مع الحلبي الشاعر في معنى شعر","page":"ج20 ص293","text":"قال اليوسفي وحدثني أبو الحسن الشهرزاني أن خالدا وقع بينه وبين الحلبي الشاعر الذي يقول فيه البحتري\n(سل الحلبي عن حلب ... )\nخلاف في معنى شعر فقال له الحلبي لا تعد طورك فأخرسك فقال له خالد لست هناك ولا فيك موضع للهجاء ولكن ستعلم أني أجعلك ضحكة سر من رأى وكان الحلبي من أوسخ الناس فجعل يهجو جبته وثيابه وطيلسانه فمن ذلك قوله\n(وشاعر ذي منطق رائق ... في جبة كالعارض البارق)\n(قطعاء شلاء رقاعية ... دهرية مرقوعة العاتق)\n(قدمها العري على نفسه ... لفضلها في القدر السابق)\nقوله\n(وشاعر مقدم له قوم ... ليس عليهم في نصره لوم)\n(قد ساعدوه في الجوع كلهم ... فقرى فكل غداؤه الصوم)\n(يأتيك في جبة مرقعة ... أطول أعمار مثلها يوم)\n(وطيلسان كالآل يلبسه ... على قميص كأنه غيم)\n(من حلب في صميم سفلتها ... غناه فقر وعزه ضيم)\nال وقال فيه\n(تاه على ربه فأفقره ... حتى رآه الغنى فأنكره)\n(فصار من طول حرفة علما ... يقذفه الرزق حيث أبصره)\n(يا حلبيا الإله له ... بالتيه والفقر حين صوره)\n(لو خلطوه بالمسك وسخه ... أو طرحوه في البحر كدره)\nدثني جحظة قال حدثني خالد الكاتب قال دخلت على إبراهيم بن المهدي فاستنشدني فقلت أيها الأمير أنا غلام أقول في شجون نفسي لا أكاد أمدح ولا أهجو فقال ذلك أشد لدواعي البلاء فأنشدته صوت\n(عاتبت نفسي في هواك ... فلم أجدها تقبل)\n(وأطعت داعيها إليك ... ولم أطع من يعذل)\n(لا والذي جعل الوجوه ... لحسن وجهك تمثل)\n(لا قلت إن البصر عنك ... من التصابي أجمل)\nجحظة في هذه الأبيات رمل مطلق بالوسطى قال فبكى إبراهيم وصاح واي عليك بإبراهيم ثم أنشدته أبياتي التي أقول فيها\n(وبكى العاذل من رحمتي ... فبكائي لبكا العاذل)\nقال إبراهيم يا رشيق كم معك من العين قال ستمائة وخمسون دينارا قال اقسمها بيني وبين الفتى واجعل الكسر له صحيحا فأعطاني ثلاثمائة وخمسين دينارا فاشتريت بها منزلي بساباط الحسن والحسين فواراني إلى يومي هذا\nحدثني جحظة قال حدثني خالد الكاتب قال قال لي علي بن الجهم هب لي بيتك الذي تقول فيه\n(ليت ما أصبح من رقة ... خديك بقلبك)\nقلت يا جاهل هل رأيت أحدا يهب ولده وقال أحمد بن إسماعيل الكاتب لقيت خالدا الكاتب ذات يوم فسألته عن صديق له وكان قد باعده ولم أعلم فأنشأ يقول\n(ظعن الغريب لغيبة الأبد ... حتى المخافة نائي البلد)\n(حيران يؤنسه ويكلؤه ... يوم توعده بشر غد)\n(سنح الغراب له بأنكر ما ... تغدو النحوس به على أحد)\n(وابتاع أشأمه بأيمنه الجد ... العثور له يدا بيد)\n(حتى ينيخ بأرض مهلكة ... في حيث لم يولد ولم يلد)\n(جزعت حليلته عليه فما ... تخلو من الزفرات والكمد)\n(نزل الزمان بها فأهلكها ... منه وأهدى اليتم للولد)\n(ظفرت به الأيام فانحسرت ... عنه بناقرة ولم تكد)\n(فتركن منه بعد طيته ... مثل الذي أبقين من لبد)\nال فقلت له يا أبا الهيثم مذ كم دخلت في قول الهجاء قال مذ سالمت فحوربت وصافيت فتوقفت","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":4,"spl":"خلاف خالد مع الحلبي الشاعر في معنى شعر","partial":1},
{"id":"b262-8","bab":"الجزء 20","sec":"بين خالد وأبي تمام","page":"ج20 ص297","text":"وقال الرياشي كان خالد مغرما بالغلمان المرد ينفق عليهم كل ما يفيد فهوي غلاما يقال له عبد الله وكان أبو تمام الطائي يهواه فقال فيه خالد\n(قضيب بان جناه ورد ... تحمله وجنة وخد)\n(لم أثن طرفي إليه إلا ... مات عزاء وعاش وجد)\n(ملك طوع النفوس حتى ... علمه الزهو حين يبدو)\n(واجتمع الصد فيه حتى ... ليس لخلق سواه صد)\nبلغ أبا تمام ذلك فقال فيه أبياتا منها\n(شعرك هذا كل مفرط ... في برده يا خالد البارد)\nفعلمها الصبيان فلم يزالوا يصيحون به يا خالد يا بارد حتى وسوس قال ومن الناس من يزعم أن هذا السبب كان بينه وبين رجل غير أبي تمام وليس الأمر كذلك وكان خالد قد هجا أبا تمام في هذه القصة فقال فيه\n(يا معشر المرد إني ناصح لكم ... والمرء في القول بين الصدق والكذب)\n(لا ينكحن جبيبا منكم أحد ... فإن وجعاءه أعدى من الجرب)\n(لا تأمنوا أن تحولوا بعد ثالثة ... فتركبوا عمدا ليست من الخشب)\nدثني محمد بن يحيى الصولي قال حدثني الحسن بن إسحاق قال حدثني خالد الكاتب قال لما بويع إبراهيم بن المهدي بالخلافة طلبني\nوقد كان يعرفني وكنت متصلا ببعض أسبابه فأدخلت إليه فقالت أنشدني يا خالد شيئا من شعرك فقلت يا أمير المؤمنين ليس شعري من الشعر الذي قال فيه رسول الله \" إن من الشعر لحكما \" وإنما أمزح وأهمل فقال لا تقل هذا فإن جد الأدب وهزله جد هات أنشدني فأنشدته\n(عش فجبيك سريعا قاتلي ... والضنى إن لم تصلني واصلي)\n(ظفر الشوق بقلب دنف ... فيك والسقم بجسم ناحل)\n(فهما بين اكتئاب وضنى ... تركاني كالقضيب الذابل)\nال فاستملح ذلك ووصلني حدثني حمزة بن أبي سلالة الشاعر الكوفي قال دخلت بغداد في بعض السنين فبينا أنا مار بجنينة إذا أنا برجل عليه مبطنة نظيفة وعلى رأسه قلنسية سوداء وهو راكب قصبة والصبيان خلفه يصيحون به يا خالد يا بارد فإذا آذوه حمل عليهم بالقصبة فلم أزل أطردهم عنه حتى تفرقوا وأدخلته بستانا هناك فجلس واستراح واشتريت له رطبا فأكل واستنشدته فأنشدني\n(قد حاز قلبي فصار يملكه ... فكيف أسلو وكيف أتركه)\n(رطيب جسم كالماء تحسبه ... يخطر في القلب منه مسلكه)\n(يكاد يجري من القميص من النعمة ... لولا القميص يمسكه)\nاستزدته فقال لا ولا حرف وذكر علي بن الحسين بن أبي طلحة عن أبي الفضل الكاتب أنه دعا خالدا ذات يوم فأقام عنده وخلع عليه فما استقر به المجلس حتى خرج\nقال فأتبعته رسولا ليعرف خبره فإذا هو قد جاء إلى غلام كان يحبه فسأل عنه فوجده في دار القمار فمضى إليه حتى خلع عليه تلك الثياب وقبله وعانقه وعاد إلينا فلما جاء خالد أعطيت الغلام الذي وجهنا به دنانير ودعاه فجاء به إلينا وأخفيناه وسألنا خالدا عن خبره فكتمه وجمجم فغمزنا الرسول فأخرجه علينا فلما رآه خالد بكى ودهش فقلنا له لا ترع فإن من القصة كيت وكيت وإنما أردنا أن نعرف خبرك لا أن نسوءك فطابت نفسه وأجلسه إلى جنبه وقال قد بليت بحبه وبالخوف عليه مما قد بلي به من القمار ثم أنشد لنفسه فيه\n(محب شفه ألمه ... وخامر جسمه سقمه)\n(وباح بما يجمجمه ... من الأسرار مكتتمه)\n(أما ترثي لمكتئب ... يحبك لحمه ودمه)\n(يغار على قميصك حين ... تلبسه ويتهمه)","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":5,"spl":"بين خالد وأبي تمام"},
{"id":"b262-9","bab":"الجزء 20","sec":"من شعره في الشوق","page":"ج20 ص299","text":"وذكر علي بن الحسين أيضا أن محمد بن السري حدثه أنه طال الغيبة عن بغداد وقد وسوس خالد فمر به في الرصافة والصبيان يصيحون به يا غلام الشريطي يا خالد البارد ويرجع إليهم فيضربهم ويزيد ويرميهم قال فقلت له كيف أنت يا أبا الهيثم قال كما ترى فقلت له فمن تعاشر اليوم قال من أحذره فعجبت من جوابه مع اختلاله فقلت له ما قلت بعدي من الشعر قال ما حفظه الناس وأنسيته وعلى ذلك قولي\n(كبد شفها غليل التصابي ... بين عتب وسخطة وعذاب)\n(كل يوم تدمى بجرح من الشوق ... ونوع مجدد من عذاب)\n(يا سقيم الجفون أسقمت جسمي ... فاشفني كيف شئت لا بك ما بي)\n(إن أكن مذنبا فكن حسن العفو ... أو اجعل سوى الصدود عقابي)\nم قال يا أبا جعفر جننت بعدك فقلت ما جعلك الله مجنونا وهذا كلامك لي ونظمك حدثني محمد بن الطلاس أبو الطيب قال حضرت جنازة بعض جيراني فلقيت خالدا في المقبرة فقبضت عليه وقلت أنشدني فذهب ليهرب مني فغمزت على يده غمزة أوجعته فقال خل عني أنشدك فأرخيت يدي عن يده فأنشدني\n(لم تر عين نظرت ... أحسن من منظره)\n(النور والنعمة والنعمة ... في مخبره)\n(لا تصل الألسن بالوصف ... إلى أكثره)\n(كيف بمن تنتسب الشمس ... إلى جوهره)\nدثني عمي رحمه الله قال مر بنا خالد الكاتب ها هنا والصبيان خلفه يصيحون به فجلس إلي فقال فرق هؤلاء عني ففعلت وألحت عليه جارية تصيح يا خالد يا بارد فقال لها مري يا منتنة الكس ويا من كسها دس فقلت يا أبا الهيثم أي شيء معنى دس ها هنا قال تشتهي الأير الصغير الصغير والكبير والوسط ولا تكره منها شيئا وأقبل الصبيان يصيحون بتلك الجارية بمثل ما قال لها خالد وهي ترميهم وتهرب منهم حتى غابوا معها عنا فأقبل علي خالد متمثلا فقال\n(وما أنا في أمري ولا في خصومتي ... بمهتضم حقي ولا قارع سني)\nفاحتسبته عندي يومي ذلك فلما شرب وطابت نفسه أنشدنا لأبي تمام\n(أحبابه لم تفعلون بقلبه ... ما ليس يفعله به أعداؤه)\n(مطر من العبرات خدي أرضه ... حتى الصباح ومقلتاي سماؤه)\n(نفسي فداء محمد ووقاؤه ... وكذبت ما في العالمين فداؤه)\n(أزعمت أن البدر يحكي وجهه ... والغصن حين يميد فيه ماؤه)\n(اسكت فأين بهاؤه وكماله ... وجماله وحياؤه وضياؤه)\n(لا تقر أسماء الملاحة باطلا ... فيمن سواه فإنها أسماؤه)\nم قال وقد عارضه أبو الهيثم يعني خالدا نفسه فقال\n(فديت محمدا من كل سوء ... يحاذر في رواح أو غدو)\n(أيا قمر السماء سفلت حتى ... كأنك قد ضجرت من العلو)\n(رأيتك من حبيبك ذا بعاد وممن لا يحبك ذا دنو ... )\n(وحسبك حسرة لك من حبيب ... رأيت زمامه بيدي عدو)\nكذا أخبرني عمي عن خالد وهذه الأبيات أيضا تروى لأبي تمام وقال ابن أبي طلحة حدثني الهلالي قال مررت بخالد وحوله جماعة ينشدهم فقلت له يا أبا الهيثم سلوت عن صديقك قال لا والله قلت فإنه عليل وما وعدته فسكت ساعة ثم رفع رأسه إلي وقال\n(زعموا أنني صحوت وكلا ... أشهد الله أنني لن أملا)\n(كيف صبري يا من إذا ازداد تيها ... أبدا زدته خضوعا وذلا)\nم قال احفظه وأبلغه عني\n(بجسمي لا بجسمك يا عليل ... ويكفيني من الألم القليل)\n(تعداك السقام إلي إني ... على ما بي لعاديه حمول)\n(إذا كنت يا أملي صحيحا ... فحالفني وسالمك النحول)\n(ألست شقيق ما ضمت ضلوعي ... على أني لعلتك العليل)\nال وحدثني العباس بن يحيى أنهم كانوا عند علي بن المعتصم فغني في شعر لخالد فأمر بإحضاره وطلب فلم يوجد فوجه إلى غلام كان يتعشقه فأحضر وسأله عنه فدل عليه وقال كنا نشرب إلى السحر وقد مضى إلى حمام فلان وهو يخرج ويجلس عند فلان الفقاعي ودكانه مألف للغلمان المرد والمغنين فبعث إليه فأحضر فلما جلس أخرج علي بن المعتصم الغلام وقال هذا دلنا عليك وهو يزعم أنك تعشقه فقال له الغلام نعم أيها الأمير لو لم يكن من فضيحته إياي إلا أنه إذا لم يوجد أحضرت وسئلت عنه فأقبل عليه خالد وقال\n(يا تارك الجسم بلا قلب ... إن كنت أهواك فما ذنبي)\n(يا مفردا بالحسن أفردتني ... منك بطول الشوق والحب)\n(إن تك عيني أبصرت فتنة ... فهل على قلبي من عتب)\n(حسيبك الله لما بي كما ... أنك في فعلك بي حسبي)","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":6,"spl":"من شعره في الشوق","partial":1},
{"id":"b262-10","bab":"الجزء 20","sec":"من شعره في الشوق","page":"ج20 ص299","text":"جحظة فيه رمل فاستحسن علي الشعر وأمر له بخمسين دينارا قال حدثني ابن أبي المدور أنه شهد خالدا عند عبد الرحيم بن الأزهر الكاتب وأنه دخل عليهم غلام من أولاد الكتاب فلما رأى خالدا أعرض عنه فقلت له لم أعرضت عن أبي الهيثم فقال والله لو علمت أنه ها هنا ما دخلت إليكم ما يبالي إذا شرب هذين القدحين ما قال ولا من هتك فقال لي خالد ألا تعينني على ظالمي فقلت بلى والله أعينك فأقبل على الفتى وقال\nصوت\n(هبني أسأت فكان ذنبي ... مثل ذنب أبي لهب)\n(فأنا أتوب وكم اسأت ... وكم أسأت ولم تتب)\nما زلنا مع ذلك الفتى نداريه ونستعطفه له حتى أقبل عليه وكلمه وحادثه فطابت نفسه وسر بقية يومه في هذين البيتين لأبي العبيس خفيف رمل بالسبابة في مجرى الوسطى ولرذاذ خفيف رمل مطلق حدثني عبد الله بن صالح الطوسي أن علي بن المعتصم دعا خالدا يوما وهو يشرب وقد أخرجت إليه وصيغة من وصفاء حظيته تفاحة معضوضة مغلفة بعثت به إليه ستها فقال\n(تفاحة خرجت بالدر من فيها ... أشهى إلي من الدنيا وما فيها)\n(بيضاء في حمرة علت بغالية ... كأنما قطفت من خد مهديها)\n(جاءت بها قينة من عند غانية ... روحي من السوء والمكروه تفديها)\n(لو كنت ميتا ونادتني بنغمتها ... إذا لأسرعت من لحدي ألبيها)\nاستحسن علي بن المعتصم الأبيات وغني فيها وأمر له بتخت ثياب وخمسين دينارا","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":7,"spl":"من شعره في الشوق — أخبار المسدود"},
{"id":"b262-11","bab":"الجزء 20","sec":"أخبار المسدود","page":"ج20 ص304","text":"المسدود من أهل بغداد وكان منزله في ناحية درب المفضل في الموضع المعروف بخراب المسدود منسوب إليه وأخبرني جحظة أن اسمه الحسن وكنيته أبو علي وأن أباه كان قصابا وأنه كان مسدود فرد منخر ومفتوح الآخر وكان يقول لو كان منخري الآخر مفتوحا لأذهلت بغنائي أهل الحلوم وذوي الألباب وشغلت من سمعه عن أمر دينه ودنياه ومعاشه ومعاده قال جحظة وكان أشجى الناس صوتا وأحضرهم نادرة ولم يكتسب أحد من المغنين بطنبور ما كسبه وكان مع يساره وقلة نفقته يقرض بالعينة وكانت له صنعة عجيبة أكثرها الأهزاج قال جحظة قال لي مخارق غلامه قال لي وقد صنع هذين البيتين وهما جميعا هزج صوت\n(من رأى العيس عليها الرحال ... إضم قصد لها أم أثال)\n(لست أدري حيث حلوا ولكن ... حيثما حلوا فثم الجمال)\nالآخر\n(عج بنا نجن بطرف العين ... تفاح الخدود)\n(ونسل القلب عمن ... حظنا منه الكدود)\nم قال والله لا تركت بعدي من يهزج قال جحظة والله ما كذب","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":7,"spl":"من شعره في الشوق — أخبار المسدود"},
{"id":"b262-12","bab":"الجزء 20","sec":"الواثق ينفي المسدود إلى عمان","page":"ج20 ص305","text":"أخبرني جحظة قال كان الواثق قد أذن لجلسائه ألا يرد أحد نادرة عن أحد يلاعبه فغنى الواثق يوما\n(نظرت كأني من وراء زجاجة ... إلى الدار من ماء الصبابة أنظر)\nقد كان النبيذ عمل فيه وفي الجلساء فانبعث إليه المسدود فقال أنت تنظر أبدا من وراء زجاجة إن كان في عينيك ماء صبابة أولم يكن فغضب الواثق من ذلك وكان في عينيه بياض ثم قال خذوا برجل العاض بظر أمه فسحب من بين يديه ثم قال ينفى إلى عمان الساعة فنفي من وقته وحدر ومعه الموكلون فلما سلموه إلى صاحب البصرة سأله أن يقيم عنده يوما ويغنيه ففعل\nفلما جلسوا للشراب ابتدأ فقال احذروني يا أهل البصرة على حرمكم فقد دخلت إلى بلدكم وأنا أزنى خلق الله قال فقال له الجماز أما يعني أنه أزنى خلق الله أما فغضب المسدود وضرب بطنبوره الأرض وحلف ألا يغني فسأله الأمير أن يقيم عنده وأمر بإخراج الجماز وكل من حضر فأبى ولج فأحدره إلى عمان ومكث الواثق لا يسأل عنه سنة ثم أشتاقه فكتب في إحضاره فلما جاءه الرسول ووصل إلى الواثق قبل الأرض بين يديه فاعتذر من هفوته وشكر التفضيل عليه فأمر بالجلوس ثم قال له حدثني بما رأيت بعدي فقال لي حديث ليس في الأرض أظرف منه وأعاد عليه حديثه بالبصرة فقال له الواثق قبحك الله ما أجهلك ويلك فأنت سوقة أنا ملك وكنت صاحيا وكنت منتشيا وبدأت القوم فأجابوك فبلغ بك الغضب ما ذكرته وما بدأتك فتجيبني وبدأتني من المزح بما لا يحتمله النظير لنظيره ويلك لا تعاود بعدها ممازحة خليفة وإن أذن ذلك في ذلك فليس كل واحد يحضره حلمه كما حضرني فيك أخبرني محمد بن يحيى الصولي قال حدثني عون بن محمد قال سمعت حمدون بن إسماعيل يقول لم يكن في الخلفاء أحمد أحلم من الواثق ولا أصبر على أذى وخلاف وكان يعجبه غناء أبي حشيشة الطنبوري فوجد المسدود من ذلك فكان يبلغه عنه ما يكره ويتجاوز عنه وكان المسدود قد هجاه ببيتين فكانا معه في رقعة وفي رقعة أخرى حاجة له يريد أن يرفعها إليه فغلط بين الرقعتين فناوله رقعة الشعر وهو يرى أنها رقعة الحاجة فقرأها وفيها\n(من المسدود في الأنف ... إلى المسدود في العين)\n(أنا طبل له شق ... فيا طبلا بشقين)\nفلما قرأ الرقعة علم أنها فيه فقال للمسدود خلطت في الرقعتين فهات الأخرى وخذ هذه واحترز من مثل هذا والله ما زاده على هذا القول","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":8,"spl":"الواثق ينفي المسدود إلى عمان — من اجوبت الموجعة"},
{"id":"b262-13","bab":"الجزء 20","sec":"من اجوبت الموجعة","page":"ج20 ص307","text":"أخبرني جحظة قال تحدث المسدود في مجلس المنتصر بحديث فقال له المنتصر متى كان ذلك قال ليلة لاناه ولا زاجر يعرض له بليلة قتل فيها المتوكل فأغضى المنتصر واحتمله قال وقالت الذكورية يوما بين يدي المعتمد غن يا مسدود قال نعم يا مفتوحة وقالت له امرأة كيف آخذ إلى شجرة بابك قال قدامك أطعمك الله من ثمرها قال وغنى بين يدي المتوكل فسكته وقال لبكران الشيري تغن أنت فقال المسدود أنا أحتاج إلى مستمع فلم يفهم المتوكل ما قال وقدم إليه طباخ المتوكل طبقا وعليه رغيفان ثم قال له أي شيء تشتهي حتى أجيئك به قال خبزا فبلغ ذلك المتوكل فأمر بالطباخ فضرب مائتي مقرعة قال جحظة وحدثني بعض الجلساء أنه لما وضع الطباخ الرغيفين بين يديه قال له المسدود هذا حرز فأين النير قال ودعاه بعض الرؤساء فأهدى له برذونا أشهب فارتبطه ليلته فلما كان من غد نفق وبعث إليه يدعوه بعد ذلك فكتب أنا لا أمضي إلى من يعرف آجال الدواب فيهب ما قرب أجله منها\nقال واستوهب من بعض الرؤساء وبرا فأعطاه سمورا قد قرع بعضه فرده وقال ليس هذا سمورا هذا أشكر صوت\n(أجدك ما تعفو كلوم مصيبة ... على صاحب إلا فجعت بصاحب)\n(تقطع أحشائي إذا ما ذكرتهم ... وتنهل عيني بالدموع السواكب)\nروضه من الطويل الشعر لسلمة بن عياش والغناء لحكم وله فيه لحنان رمل بالبنصر وهزج بالوسطى","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":8,"spl":"الواثق ينفي المسدود إلى عمان — من اجوبت الموجعة"},
{"id":"b262-14","bab":"الجزء 20","sec":"أخبار سلمة بن عياش","page":"ج20 ص309","text":"سلمة بن عياش مولى بني حسل بن عامر بن لؤي شاعر بصري من مخضرمي الدولتين وكان يتدين ويتصون وانقطع إلى جعفر ومحمد ابني سليمان بن علي بن عبد الله بن عباس ومدحهما فأكثر وأجاد ومما مدحمها به وفيه غناء قوله صوت أرقت وطالت ليلتي بأبان ... لبرق سرى بعد الهدوء يمان يضيء بأعلام المدينة همدا ... غلى أمج فالطلح طلح قنان\nنى في هذين البيتين دحمان ولحنه ثقيل أول بالوسطى عن عمرو قال وفيه لحن لعطرد يقول فيها\n(وردت خليجي جعفر ومحمد ... وكل بديء من نداه سقاني)\n(إني لأرجو جعفرا ومحمدا ... لأفضل ما يرجى له ملكان)\n(هما ابنا رسول الله وابنا ابن عمه ... فقد كرم الجدان والأبوان)\n(ومنها ما ذكره محمد بن داود بن الجراح قوله ... )\n(صوت ... )\n(أنار بدت وهنا لعينك ترمض ... ببغداد أم سار من البرق مومض)\n(يضيء سناه مكفهرا كأنه ... حناتم سود أو عشار تمخض)\nنى فيهما عطرد ثقيلا أو ل بإطلاق الوتر في مجرى الوسطى عن إسحاق يقول فيها\n(ولولا انتظاري جعفرا ونواله ... لما كان في بغداد ما أتبرض)\nقد وجدت هذا الشعر لابن المولى في جامع شعره من قصيدة له وأظن ذلك الصحيح لا ما ذكر محمد بن داود من أنها لسلمة بن عياش أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وغيره قال قال سلمة بن عياش وذكر محمد بن داود عن عسل بن ذكوان عن أبي حاتم عن الأصمعي عن سلمة بن عياش مولى بني عامر بن لؤي قال دخلت على الفرزدق السجن وهو محبوس وقد قال قصيدته\n(إن الذي سمك السماء بنى لنا ... بيتا دعائمه أعز وأطول)\nوقد أفحم وأجبل فقلت له ألا أرفدك فقال وهل ذاك عندك فقلت نعم ثم قلت\n(بيت زرارة محتب بفنائه ... ومجاشع وأبو الفوارس نهشل)\nاستجاد البيت وغاظه قولي له فقال لي ممن أنت فقلت من قريش فقال كل أير حمار من قريش فمن أيها أنت قلت من بني عامر بن يؤي قال لئام والله رضعة جاورتهم بالمدينة فما أحمدتهم فقلت ألأم والله منهم قومك وأرضع جاء رسول مالك بن المنذر وأنت سيدهم وشاعرهم فأخذ بأذنك يقودك حتى احتسبك فما اعترضه أحد ولا نصرك فقال قاتلك الله ما أكرمك وأخذ البيت فأدخله في قصيدته","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":9,"spl":"أخبار سلمة بن عياش","partialRef":{"sid":"b76-5","gi":6,"vi":5,"side":0},"partial":1},
{"id":"b262-15","bab":"الجزء 20","sec":"سلمة وبربر الجارية","page":"ج20 ص311","text":"أخبرنا وكيع قال أخبرني محمد بن سعد الكراني قال حدثنا سهل بن محمد قال حدثني العتبي قال كان سلمة بن عياش وأبو سفيان بن العلاء عند محمد بن سليمان وجارية تغنيهم وتسقيهم يقال لها بربر فقال سلمة\n(إلى الله أشكو ما ألاقي من القلى ... لأهلي وما لاقيت من حب بربر)\n(على حين ودعت الصبابة والصبا ... وفارقت أخداني وشمرت مئزري)\n(نأى جعفر عنا وكان لمثلها ... وأنت لنا في النائبات كجعفر)\nقال فقال محمد بن سليمان لسلمة خذها هي لك فاستحيا وارتدع وقال لا أريدها فألح عليه في أخذها فقال أعتق ما أ ملك إن أخذتها فقال له أبو سفيان ياسخين العين أعتق ما تملك وخذها فهي خير من كل ما تلك فلما مات أبو سفيان رثاه سلمة فقال\n(لعمرك لا تعفو كلوم مصيبة ... على صاحب إلا فجعت بصاحب)\n(تقطع أحشائي إذا ما ذكرتكم ... وتنهل عيني بالدموع السواكب)\n(وكنت أمرأ جلدا على ما ينوبني ... ومعترفا بالصبر عند المصائب)\n(فهد أبو سفيان ركني ولم أكن ... جزوعا ولا مستنكرا للنوائب)\n(غنينا معا بضعا وستين حجة ... خليلي صفار ودنا غير كاذب)\n(فأصبحت لما حالت الأرض دونه ... على قربه مني كمن لم أصاحب)\nوذكر محمد بن داود عن عسل بن ذكوان أن محمد بن سليمان قال له اختر ما شئت غيرها لأن أبا أيوب قد وطئها أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد النحوي قال حدثت من غير وجه عن سلمة بن عياش أنه قال قلت لأبي حية النميري أهزأ به ويحك يا أبا حية أتدري ما يقول الناس قال لا قلت يزعمون أني أشعر منك قال إنا لله هلك والله الناس وفي بربر هذه يقول سلمة بن عياش وفيه غناء وذكر عمر بن شبة أنه لمطيع بن إياس\nصوت\n(أظن الحب من وجدي ... سيقتلني على بربر)\n(وبربر دره الغواص ... من يملكها يحبر)\n(فخافي الله يا بربر ... فقد أفتنت ذا العسكر)\n(بحسن الدل والشكل ... وريح المسك والعنبر)\n(ووجه يشبه البدر ... وعيني جؤذر أحور)\nيه لحكم ثلاثة ألحان رمل مطلق في مجرى الوسطى عن إسحاق وخفيف رمل عن هارون بن الزيات وهزج عن أبي أيوب المدني أخبرني إسماعيل بن يونس قال حدثنا عمر شبة قال بربر جارية آل سليمان أعتقت وكان لها جوار مغنيات فيهن جارية اسمها جوهر وكان في البصرة فتى يعرف بالصحاف حسن الوجه فبلغ مطيع بن إياس أنه بات مع جوهر جارية بربر فغاظه ذلك فقال\n(ناك والله جوهر الصحاف ... وعليها قميصها الأفواف)\n(شام فيها أيرا له ذا صلاع ... لم يخنه نقص ولا إخطاف)\n(زعموها قالت وقد غاب فيها ... قائما في قيامه استحصاف)\n(وهو في جارة استها يتلظى ... وبها شهوة له والتهاف)\n(بعض هذا مهلا ترفق قليلا ... ما كذا يا فتى تناك الظراف)\nال وقال فيها وقد وجهت بجواريها إلى عسكر المهدي\n(خافي الله يا بربر ... فقد أفسدت ذا العسكر)\n(أفضت الفسق في الناس ... فصار الفسق لا ينكر)\n(ومن ذا يملك الناس ... إذا ما أقبلت بربر)\n(وأعطاف جواريها ... كريح المسك والعنبر)\n(وجوهر دره الغواص ... من يملكها يحبر)\n(ألا يا جوهر القلب ... لقد زدت على الجوهر)\n(وقد أكملك الله ... بحسن الدل والمنظر)\n(إذا غنيت يا أحسن خلق الله بالمزهر ... )\n(فهذا حزنا يبكي ... وهذا طربا يكفر)\n(وهذا يشرب الكأس ... وذا من فرح ينعر)\n(ولا والله ما المهدي ... أولى منك بالمنبر)\n(فما عشت ففي كفيك ... خلع ابن أبي جعفر)\nال فبلغ ذلك المهدي فضحك وأمر لمطيع بصلة وقال أنفق هذا عليها وسلها ألا تخلعنا ما عاشت قال وفي جوهر يقول مطيع\n(جارية أحسن من حليها ... وفيه فضل الدر والجوهر)\n(وجرمها أطيب من طيبها ... والطيب فيه المسك والعنبر)\n(جاءت بها بربر ممكورة ... يا حبذا ما جلبت بربر)\nال وقال فيها\n(أنت يا جوهر عندي جوهره ... في بياض الدرة المشتهره)\n(وإذا غنت فنار أضرمت ... قدحت في كل قلب شرره)\nوت\n(يا عمود الإسلام خير عمود ... والذي صيغ من حياء وجود)\n(إن يوما أراك فيه ليوم ... طلعت شمسه بسعد السعود)\nلشعر لأبي العتاهية يمدح محمد الأمين والغناء لإسحاق ثقيل أول بالبنصر عن عمرو بن بانة وإسحاق","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":10,"spl":"سلمة وبربر الجارية","partial":1},
{"id":"b262-16","bab":"الجزء 20","sec":"أخبار لأم جعفر","page":"ج20 ص316","text":"أخبرني محمد بن يحيى الصولي قال حدثنا العلائي قال حدثني محمد بن أبي العتاهية قال لما جلس الأمين في الخلافة أنشده أبو العتاهية\n(يا بن عم النبي خير البرية ... إنما أنت رحمة للرعيه)\n(يا إمام الهدىالأمين المصفى ... بلباب الخلافة الهاشميه)\n(لك نفس أمارة لك بالخير ... وكف بالمكرمات نديه)\n(إن نفسا تحملت منك ما حملت ... للمسلمين نفس قويه)\nال ثم خرج إلى دار أم جعفر فقالت له أنشدني ما أنشدت أمير المؤمنين فأنشدها فقالت أين هذا من مدائحك في المهدي والرشيد فغضب وقال إنما أنشدت أمير المؤمنين ما يستملح وأنا القائل فيه\n(يا عمود الإسلام خير عمود ... والذي صيغ من حياء وجود)\n(والذي فيه ما يسلي ذوي الأحزان ... عن كل هالك مفقود)\n(إن يوما أراك فيه ليوم ... طلعت شمسه بسعد السعود)\nقالت له الآن وفيت المديح حقه وأمرت له بعشرة آلاف درهم أخبرني محمد بن يحيى قال حدثني محمد بن موسى اليزيدي قال حدثني محمد بن الفضل قال\nكان المأمون يوجه إلى أم جعفر زبيدة في كل سنة بمائة ألف دينار جدد وألف ألف درهم فكانت تعطي أبا العتاهية منها مائة دينار وألف درهم فأغفلته سنة فدفع إلي رقعة وقال ضعها بين يديها فوضعتها وكان فيها\n(خبروني أن في ضرب السنه ... جددا بيضا وصفرا حسنه)\n(سككا قد أحدثت لم أرها ... مثل ما كنت أرى كل سنة)\nقالت إنا لله أغفلناه فوجهت إليه بوظيفة على يدي حدثني محمد بن موسى قال حدثنا جعفر بن الفضل الكاتب قال أحست زبيدة من المأمون بجفاء فوجهت إلى أبي العتاهية تعلمه بذلك وتأمره أن يعمل فيه أبياتا تعطفه عليها فقال صوت\n(ألا إن ريب الدهر يدني ويبعد ... ويؤنس بالالاف طورا ويفقد)\n(أصابت لريب الدهر مني يدي يدي ... فسلمت للإقدار والله أحمد)\n(وقلت لريب الدهر إن ذهبت يد ... فقد بقيت والحمد لله لي يد)\n(إذا بقي المأمون لي فالرشيد لي ... ولي جعفر لم يفقدا ومحمد)\nلغناء لعلويه\nقال فحسن موقع الأبيات منه وعاد لها المأمون إلى أكثر مما كان لها عليه وجدت في كتاب محمد بن الحسن الكاتب حدثني هارون بن مخارق قال حدثني أبي قال ظهرت لأم جعفر جفوة من المأمون فبعثت إلي بأبيات وأمرتني أن أغني فيها المأمون إذا رأيته نشيطا وأسنت لي الجائزة وكان كاتبها قال الأبيات ففعلت فسألني المأمون عن الخبر فعرفته فبكى ورق لها وقام من وقته فدخل إليها فأكب عليها وقبلت يديه وقال لها يا أمه ما جفوتك تعمدا ولكن شغلت عنك بما لا يمكن إغفاله فقالت يا أمير المؤمنين إذا حسن رأيك لم يوحشني شغلك وأتم يومه عندها والأبيات\n(ألا إن ريب الدهر يدني ويبعد ... ويؤنس بالألاف طورا ويفقد)\nذكر باقي الأبيات مثل ما في الخبر الأول","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":11,"spl":"أخبار لأم جعفر"},
{"id":"b262-17","bab":"الجزء 20","sec":"أبو العتاهية ينظم شعرا عن لسانها للمأمون","page":"ج20 ص318","text":"أخبرني محمد بن يحيى قال حدثني الحسن بن علي الرازي قال حدثني أبو سهل الرازقي عن أبيه قال عمل أبو العتاهية شعرا على لسان زبيدة بأمرها لما قدم المأمون بغداد أوله\n(لخير إمام قام من خير عنصر ... وأفضل راق فوق أعواد منبر)\nذكر محمد بن أحمد بن المرزبان عن بعض كتاب السلطان أن المأمون لما قدم مدينة السلام واستقرت به الدار وانتظمت له الأمور أمرت أم جعفر كاتبا لها فقال هذه الأبيات وبعثت بها إلى علويه وسألته أن يصنع فيها لحنا ويغني فيه المأمون ففعل وكان ذلك مما عطفه عليها وأمرت لعلويه بعشرين ألف درهم وقد روي أن الأبيات التي أولها\n(يا عمود الإسلام خير عمود ... )\nعيسى بن زينب المراكبي أخبرني محمد بن يحيى قال حدثني الحسين بن يحيى الكاتب قال حدثنا علي بن نجيح قال حدثني صالح بن الرشيد قال كنا عند المأمون يوما وعقيد المغني وعمرو بن بانة يغنيان وعيسى بن زينب المراكبي حاضر وكان مشهورا بالأبنة فتغنى عقيد بشعر عيسى\n(يا عمود الإسلام خير عمود ... والذي صيغ من حياء وجود)\n(لك عندي في كل يوم جديد ... طرفة تستفاد يا بن الرشيد)\nقال المأمون لعقيد أنشد باقي هذا الشعر فقال أصون سمع أمير المؤمنين عنه فقال هاته ويحك فقال\n(كنت في مجلس أنيق وريحان ... وراح ومسمعات وعود)\n(فتغنى عمرو بن بانة إذا ذاك ... وهو ممسك بأير عقيد)\n(يا عمود الإسلام خير عمود ... والذي صيغ من حياء وجود)\n(فتنفست ثم قلت كذا كل ... محب صب الفؤاد عميد)\nقال المأمون لعيسى بن زينب والله لا فارقتك حتى تخبرني عن تنفسك عند قبض عمرو على أير عقيد لإي شيء هو لا بد من أن يكون ذلك إشفاقا عليه أو على أن تكون مثله لعن الله تنفسك هذا يا مريب قال وإنما سمي المراكبي لتوليه مراكب المنصور وأمه زينب بنت بشر صاحب طاقات بشر بباب الشام صوت\n(لقيت من الغانيات العجابا ... لو أدرك مني العذارى الشبابا)\n(علام يكحلن حور العيون ... ويحدثن بعد الخضاب الخضابا)\n(ويبرقن إلا لما تعلمون ... فلا تمنعن النساء الضرايا)\nلشعر لأيمن بن خريم بن فاتك الأسدي والغناء لإبراهيم الموصلي ولحنه من الثقيل بالسبابة في مجرى الوسطى من راويةالهشامي","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":12,"spl":"أبو العتاهية ينظم شعرا عن لسانها للمأمون","partialRef":{"sid":"b262-15","gi":7,"vi":0,"side":0},"partial":1},
{"id":"b262-18","bab":"الجزء 20","sec":"أخبار أيمن بن خريم","page":"ج20 ص321","text":"وأيمن بن خريم بن فاتك الأسدي لأبيه صحبة برسول الله ورواية عنه وينسب إلى فاتك وهو جد أبيه وهو أيمن بن خريم بن الأخرم بن عمرو بن فاتك بن القليب بن عمرو بن أسد بن خزيمة بن مدركة بن إلياس بن مضر بن نزار وكان أيمن يتشيع وكان أبوه أحد من اعتزل حرب الجمل وصفين وما بعدهما من الأحداث فلم يحضرها أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني النوشجاني عن العمري عن الهيثم بن عدي عن عبد الله بن عياش عن مجالد قال كان عبد الملك شديد الشغف بالنساء فلما أسن ضعف عن الجماع وازداد غرامه بهن فدخل إليه يوما أيمن بن خريم فقال له كيف أنت فقال بخير يا أمير المؤمنين قال فكيف قوتك قال كما أحب ولله الحمد إني لآكل الجذعة من الضأن بالصاع من البر وأشرب العس المملوء وأرتحل البعير الصضعب وأنصبه وأركب المهر الأرن فأذلله وأفترع العذراء ولا يقعدوني عنها الكبر ولا يمنعني منها الحصر ولا\nيرويني منها الغمر ولا ينقضي مني الوطر فغاظ عبد الملك قوله وحسده فمنعه العطاء وحجبه وقصده بما كره حتى أثر ذلك في حاله فقالت له امرأته ويحك أصدقني عن حالك هل لك جرم قال لا والله قالت فأي شيء دار بينك وبين أمير المؤمنين آخر ما لقيته فأخبرها فقالت إنا لله من ها هنا أتيت أنا أحتال لك في ذلك حتى أزيل ما جرى عليك فقد حسدك الرجل على ما وصفت به نفسك فتهيأت ولبست ثيابها ودخلت على عاتكة زوجته فقالت أسألك أن تستعدي لي أمير المؤمنين على زوجي قالت وماله قالت والله ما أدري أنا مع رجل أو حائط وإن له لسنين ما يعرف فراشي فسليه أن يفرق بيني وبينه فخرجت عاتكة إلى عبد الملك فذكرت ذلك له وسألته في أمرها فوجه إلى أيمن بن خريم فحضر فسأله عما شكت منه فاعترف به فقال أو لم أسألك عاما أول عن حالك فوصفت كيت وكيت فقال يا أمير المؤمنين إن الرجل ليتجمل عن سلطانه ويتجلد عند أعدائه بأكثر مما وصفت نفسي به وأنا القائل\n(لقيت من الغانيات العجابا ... لو ادرك مني الغواني الشبابا)\n(ولكن جمع النساء الحسان ... عناء شديد إذا المرء شابا)\n(ولو كلت بالمد للغانيات ... وضاعفت فوق الثياب الثيابا)\n(إذا لم تنلهن من ذاك ذاك ... جحدنك عند الأمير الكتابا)\n(يذدن بكل عصا ذائد ... ويصبحن كل غداة صعابا)\n(إذا لم يخالطن كل الخلاط ... أصبحن مخرنطمات غضابا)\n(علام يكحلن حور العيون ... ويحدثن بعد الخضاب الخضابا)\n(ويعركن بالمسك أجيادهن ... ويدنين عند الحجال العيابا)\n(ويبرقن إلا لما تعلمون ... فلا تحرموا الغانيات الضراب)\nال فجعل عبد الملك يضحك من قوله ثم قال أولى لك يابن خريم لقد لقيت منهن ترحا فما ترى أن نصنع فما بينك وبين زوجتك قال تستأجلها إلى أجل العنين وأدريها العلي أستطيع إمساكها قال أفعل ذلك وردها إليه وأمر له بما فات من عطائه وعاد إلى بره وتقريبه أخبرني هاشم بن محمد الخزاعي أبو دلف قال حدثنا الرياشي قال ذكر العتبي أن منازعة بين عمرو بن سعيد وعبد العزيز بن مروان فتعصب لكل واجد منهما أخواله وتداعوا بالسلاح واقتتلوا وكان أيمن بن خريم حاضرا للمنازعة فاعتزلهم هو ورجل من قومه يقال له ابن كوز فعاتبه عبد العزيز وعمرو جميعا على ذلك فقال\n(أأقتل بين حجاج بن عمرو ... وبين خصيمه عبد العزيز)\n(أنقتل ضلة في غير شيء ... ويبقى بعدنا أهل الكنوز)\n(لعمر أبيك ما أتيت رشدي ... ولا وفقت للحرز الحريز)\n(فإني تارك لهما جميعا ... ومعتزل كما اعتزل ابن كوز)","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":13,"spl":"أخبار أيمن بن خريم"},
{"id":"b262-19","bab":"الجزء 20","sec":"أيمن يهجو يحيى بن الحكم","page":"ج20 ص323","text":"أخبرني عمي قال حدثني الكراني عن العمري عن الهيثم بن\nعدي قال أصاب حيى بن الحكم جارية في غزاة الصائفة بها وضح فقال أعطوها أيمن بن خريم وكان موضحا فغضب وأنشأ يقول\n(تركت بني مروان تندى أكفهم ... وصاحبت يحيى ضلة من ضلاليا)\n(فإنك لو أشبهت مروان لم تقل ... لقومي هجرا أن أتوك ولاليا)\nانصرف عنه فأتى عبد العزيز بن مروان وكان يحيى محمقا حدثني محمد بن العباس اليزيدي قال حدثني عمي الفضل قال حدثني مصعب اليزبدي عن أشياخه أن عبد الملك بن مروان قال يا معشر الشعراء تشبهوننا مرة بالأسد الأبخر ومرة بالجبل الأوعر ومرة بالبحر الأجاج ألا قلتم فينا كما قال أيمن بن خريم في بني هاشم\n(نهاركم مكابدة وصوم ... وليلكم صلاة واقتراء)\n(وليتم بالقران وبالتزكي ... فأسرع فيكم ذاك البلاء)\n(بكى نجد غداة غد عليكم ... ومكة والمدينة والجواء)\n(وحق لكل أرض فارقوها ... عليكم لا أبالكم البكاء)\n(أأجعلكم وأقواما سواء ... وبينكم وبينهم الهواء)\n(وهم أرض لأرجلكم وأنتم ... لأرؤسهم وأعينهم سماء)\nأخبرني الحسن بن علي عن أحمد بن زهير عن أبي همام الوليد بن شجاع قال حدثنا عبد الله بن إدريس قال أصاب أيمن بن خريم امرأة له\nخطأ يعني قتلها فوداها عبد الملك بن مروان أعطي ورثتها ديتها وكفر عنه كفارة القتل وأعطاه عدة جوار ووهب له مالا فقال أيمن\n(رأيت الغواني شيئا عجابا ... لو انس مني الغواني الشبابا)\n(ولكن جمع العذارى الحسان ... عناء شديد إذا المرء شابا)\n(ولو كلت بالمد للغانيات ... وضاعفت فوق الثياب ثيابا)\n(إذا لم تنلهن من ذاك ذاك ... بغينك عند الأمير الكذابا)\n(يذدن بكل عصا ذائد ... ويصبحن كل غداة صعابا)\n(إذا لم يخالطن كل الخلاط ... تراهن مخرنطمات غضابا)\n(علام يكحلن حور العيون ... ويحدثن بعد الخضاب الخضابا)\n(ويعركن بالمسك أجيادهن ... ويدنين عند الحجال العيابا)\n(ويغمزن إلا لما تعلمون ... فلا تحرموا الغانيات الضرابا)\nال فبلغني أن عبد الملك أنشد هذا الشعر فقال نعم الشفيع أيمن لهن وأخبرني أحمد بن عبد العزيز عن عمر بن شبة وإبراهيم بن أيوب عن ابن قتيبة قال قال له عبد الملك لما أنشده هذا الشعر ما وصف النساء أحد مثل صفتك وعرفهن أحد معرفتك قال فقال له لئن كنت صدقت في ذلك لقد صدق الذي يقول صوت\n(فإن تسألوني بالنساء فإنني ... خبير بأدواء النساء طبيب)\n(إذا شاب رأس المرء أو قل ماله ... فليس له في ودهن نصيب)\n(يردن ثراء المال حيث علمنه ... وشرخ الشباب عندهن عجيب)\nفقال له عبد الملك قد لعمري صدقتما وأحسنتما الشعر لعلقمة بن عبدة والغناء لبسباسة ولحنه خفيف ثقيل أول بالوسطى عن حبش وهذه الأبيات يقولها علقمة بن عبدة يمدح بها الحارث ويسأله إطلاق ابنه شأس وخبره يذكر وخبر الحارث بعد انقضاء أخبار أيمن بن خريم","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":14,"spl":"أيمن يهجو يحيى بن الحكم — رجع الحديث إلى أخبار أيمن"},
{"id":"b262-20","bab":"الجزء 20","sec":"رجع الحديث إلى أخبار أيمن","page":"ج20 ص326","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني المدائني عن أبي بكر الهذلي قال دخل نصيب يوما إلى عبد العزيز بن مروان فأنشده قصيدة له امتدحه بها فأعجبته وأقبل على أيمن بن خريم فقال كيف ترى شعر مولاي هذا قال هو أشعر أهل جلدته فقال هو أشعر والله منك قال أمني أيها الأمير فقال إي والله قال لا والله ولكنك طرف ملول فقال لو كنت كذلك ما صبرت على مؤاكلتك منذ سنة وبك من البرص ما بك فقال ائذن لي أيها الأمير في الانصراف قال ذلك إليك فمضى لوجهه حتى لحق ببشر بن مروان وقال فيه\n(ركبت من المقطم في جمادى ... إلى بشر بن مروان البريدا)\n(ولو أعطاك بشر ألف ألف ... رأى حقا عليه أن يزيدا)\n(أمير المؤمنين أقم ببشر ... عمود الدين إن له عمودا)\n(ودع بشرا يقومهم ويحدث ... لأهل الزيغ إسلاما جديدا)\n(وإنا قد وجدنا أم بشر ... كأم الأسد مذكارا ولودا)\n(كأن التاج تاج أبي هرقل ... جلوه لأعظم الأيام عيدا)\n(يحالف لونه ديباج بشر ... إذا الألوان حالفت الخدودا)\nعرض بنمش كان بوجه عبد العزيز فقبله بشر بن مروان ووصله ولم يزل أثيرا عنده","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":14,"spl":"أيمن يهجو يحيى بن الحكم — رجع الحديث إلى أخبار أيمن"},
{"id":"b262-21","bab":"الجزء 20","sec":"أيمن يمدح بشر بن مروان","page":"ج20 ص327","text":"أخبرني عمي قال حدثني الكراني وأبو العيناء عن العتبي قال لما أتى أيمن بن خريم بشر بن مروان نظر الناس يدخلون عليه أفواجا فقال من يؤذن لنا الأمير أو يستأذن لنا عليه فقيل له ليس على الأمير حجاب ولا ستر فدخل وهو يقول\n(يرى بارزا للناس بشر كأنه ... إذا لاح في أثوابه قمر بدر)\n(ولو شاء بشر أغلق الباب دونه ... طماطم سود أو صقالبة شقر)\n(أبى ذا ولكن سهل الإذن للتي ... يكون له في غبها الحمد والشكر)\nضحك إليه بشر وقال إنا قوم نحجب الحرم وأما الأموال والطعام فلا وأمر له بعشرةآلاف درهم أخبرني هاشم بن محمد الخزاعي أبو دلف قال حدثني الرياشي قال حدثنا الأصمعي عن المعتمد بن سليمان قال لما طالت الحرب بين غزالة وبين أهل العراق وهم لا يغنون شيئا قال أيمن بن خريم\n(أتينا بهم مائتي فارس ... من السافكين الحرام العبيطا)\n(وخمسون من مارقات النساء ... يسحبن للمنديات المروطا)\n(وهم مائتا ألف ذي قونس ... يئط العراقان منهم أطيطا)\n(رأيت غزالة إن طرحت ... بمكة هودجها والغبيطا)\n(سمت للعراقين في جمعها ... فلاقى العراقان منها بطيطا)\n(ألا يستحي الله أهل العراق ... إن قلدوا الغانيات السموطا)\n(وخيل غزالة تسبي النساء ... وتحوي النهاب وتحوي النبيطا)\n(ولو أن لوطا أمير لكم ... لأسلمتم في الملمات لوطا)\nصوت\n(تصابيت أم هاجت لك الشوق زينب ... وكيف تصابي المرء والرأس أشيب)\n(إذا قربت زادتك شوقا بقربها ... وإن جانبت لم يسل عنها التجنب)\n(فلا اليأس إن ألممت يبدو فترعوي ... ولا أنت مردود بما جئت تطلب)\n(وفي اليأس لو يبدو لك اليأس راحة ... وفي الأرض عمن لا يؤاتيك مذهب)\nلشعر لحجية بن المضرب الكندي فيما ذكره إسحاق والكوفيون وذكر الزبير بن بكار أنه لإسماعيل بن يسار وذكر غيره أنه لأخيه أحمد بن\nيسار والغناء ليونس الكاتب ولحنه من الثقيل الثاني بإطلاق الوتر في مجرى البنصر وفيه ثقيل أول بالبنصر ذكر حبش أنه لمالك وذكر غيره أنه لمعبد","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":15,"spl":"أيمن يمدح بشر بن مروان"},
{"id":"b262-22","bab":"الجزء 20","sec":"أخبار حجبة بن المضرب","page":"ج20 ص330","text":"حدثني ابن عمار قال حدثنا سعيد بن يحيى الأموي وأخبرنا به وكيع عن إسماعيل بن إسحاق عن سعيد بن يحيى الأموي قال حدثني المحبر بن قحذم عن هشام بن عروة عن أبيه قال لما قدم القاسم بن محمد بن أبي بكر وأخته من مصر وأخبرني بهذا الخبر محمد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن الهيثم بن عدي عن عوانة قال كان القاسم بن محمد بن أبي بكر يحدث قال لما قتل معاوية بن حديج الكندي وعمرو بن العاص أبي يعني محمد بن أبي بكر بمصر جاء عمي عبد الرحمن بن أبي بكر فاحتملني وأختا لي من مصر وقد جمعت الروايتين واللفظ لابن أبي الأزهر وخبره أتم قال فقدم بنا المدينة فبعثت إلينا عائشة فاحتملتنا من منزل عبد الرحمن إليها فما رأيت والدة قط ولا والدا أبر منها فلم نزل في حجرها حتى إذا كان ذات يوم وقد ترعرعنا ألبستنا ثيابا بيضاء ثم أجلست كل واحد منا على فخذها ثم بعثت إلى عمي عبد الرحمن فلما دخل عليها تكلمت فحمدت\nالله عز و جل وأئثنت عليه فما رأيت متكلما ولا متكلمة قبلها ولا بعدها أبلغ منها ثم قالت يا أخي إني لم أزل أراك معرضا عني منذ قبضت هذين الصبيين منك ووالله ما قبضتهما تطاولا عليك ولا تهمة لك فيهما ولا لشيء تكرهه ولكنك كنت رجلا ذا نساء وكانا صبيين لا يكفيان من أنفسهما شيئا فخشيت أن يرى نساؤك منهما ما يتقذرن به من قبيح أمر الصبيان فكنت ألطف لذلك وأحق بولايته فقد قويا على أنفسهما وشبا وعرفا ما يأتيان فهاهما هذان فضمهما إليك وكن لهما كحجية بن المضرب أخي كندة فإنه كان له أخ يقال له معدان فمات وترك أصيبية صغارا في حجر أخيه فكان أبر الناس بهم وأعطفهم عليهم وكان يؤثرهم على صبيانه فمكث بذلك ما شاء الله ثم إنه عرض له سفر لم يجد بدا من الخروج فيه فخرج وأوصى بهم امرأته وكانت إحدى بنات عمه وكان يقال لها زينب فقال اصنعي ببني أخي ما كنت أصنع بهم ثم مضى لوجهه فغاب أشهرا ثم رجع وقد ساءت حال الصبيان وتغيرت فقال لامرأته ويلك مالي أرى بني معدان مهازيل وأرى بني سمانا قالت قد كنت أواسي بينهم ولكنهم كانوا يعبثون ويلعبون فخلا بالصبيان فقال كيف كانت زينب لكم قالوا سيئة ما كانت تعطينا من القوت إلا ملء هذا القدح من لبن وأروه قدحا صغيرأ فغضب على امرأته غضبا شديدا وتركها حتى إذا أراح عليه راعيا إبله قال لهما اذهب فأنتما وإبلكما لبني معدان فغضبت من ذلك زينب وهجرته وضربت بينه وبينها حجابا فقال والله لا تذوقين منها صبوحا ولا غبوقا أبدا وقال في ذلك\n(لججنا ولجت هذه في التغضب ... ولط الحجاب بيننا والتجنب)\n(وخطت بفردي إثمد جفن عينها ... لتقتلني وشد ما حب زينب)\n(تلوم على مال شفاني مكانه ... فلومي حياتي ما بدا لك واغضبي)\n(رحمت بني معدان أن قل مالهم ... وحق لهم مني ورب المحصب)\n(وكان اليتامى لا يسد اختلالهم ... هدايا لهم في كل قعب مشعب)\n(فقلت لعبدينا أريحا عليهم ... سأجعل بيتي بيت آخر معزب)\n(وقلت خذوها واعلموا أن عمكم ... هو اليوم أولى منكم بالتكسب)\n(عيالي أحق أن ينالوا خصاصة ... وأن يشربوا رنقا إلى حين مكسبي)\n(أحابي بها من لو قصدت لماله ... حريبا لآساني على كل موكب)\n(أخي والذي إن أدعه لعظيمة ... يجبني وإن أغضب إلى السيف يغضب)\nلى ها هنا رواية ابن عمار وفي خبر إسحاق قال فلما بلغ زينب هذا الشعر وما وهب زوجها خرجت حتى أتت المدينة فأسلمت وذلك في ولاية عمر بن الخطاب فقدم حجية المدينة فطلب زينب أن ترد عليه وكان نصرانيا فنزل بالزبير بن العوام فأخبره بقصته فقال له إياك وأن يبلغ هذا عنك عمر فتلقى منه أذى وانتشر خبر حجية وفشا بالمدينة وعلم فيم كان مقدمه فبلغ ذلك عمر فقال للزبير\nقد بلغني قصة ضيفك ولقد هممت به لولا تحرمه بالنزول عليك فرجع الزبير إلى حجية فأعلمه قول عمر فقال حجية في ذلك\n(إن الزبير بن عوام تداركني ... منه بسيب كريم سيبه عصم)\n(نفسي فداؤك مأخوذا بحجزتها ... إذ شاط لحمي وإذ زلت بي القدم)\n(إذ لا يقوم بها إلا فتى أنف ... عاري الأشاجع في عرنينه شمم)\nم انصرف من عنده متوجها إلى بلده آيسا من زينب كئيبا حزينا فقال في ذلك\n(تصابيت أم هاجت لك الشوق زينب ... )\nلأبيات المذكور فيها الغناء صوت\n(خليلي هبا نصطبح بسواد ... ونرو قلوبا هامهن صواد)\n(وقولا لساقينا زياد يرقها ... فقد هز بعض القوم سقي زياد)","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":16,"spl":"أخبار حجبة بن المضرب","partialRef":{"sid":"b44-23","gi":6,"vi":0,"side":0},"partial":1},
{"id":"b262-23","bab":"الجزء 20","sec":"أخبار حجبة بن المضرب","page":"ج20 ص330","text":"لشعر والغناء لإسحاق ولحنه من الثقيل الأول بالبنصر","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":17,"spl":"أخبار حجبة بن المضرب — خبر إسحاق مع غلامه زياد"},
{"id":"b262-24","bab":"الجزء 20","sec":"خبر إسحاق مع غلامه زياد","page":"ج20 ص334","text":"هذا الشعر يقوله إسحاق في غلام له مملوك خلاسي يقال له زياد كان مولدا من مولدي المدينة فصيحا ظريفا فجعله ساقيه وذكره هو وغيره في شعره فممن ذكره من الشعراء دعبل وله يقول أخبرني بذلك علي بن سليمان الأخفش عن أبي سعيد السكري قال كان زياد الذي يذكره إسحاق في عدة مواضع منها قوله\n(وقولا لساقينا زياد يرقها ... )\nوكان نظيف السقي لبقا فقال فيه دعبل\n(يقول زياد قف بصحبك مرة ... على الربع مالي والوقوف على الربع)\nصوت\n(أدرها على الحبيب فربما ... شربت على نأي الأحبة والفجع)\n(فما بلغنتني الكأس إلا شربتها ... وإلا سقيت الأرض كأسا من الدمع)\nنى في البيت الثاني والثالث من هذه الأبيات محمد بن العباس بن عبد الله بن طاهر لحنا من خفيف الثقيل الأول بالبنصر قال أبو الحسن وقد قيل إن هذين البيتين يعني\n(خليلي هبا نصطبح بسواد ... )\nلأخطل أخبرني علي بن سليمان قال حدثني أبي قال قال لي جعفر بن معروف الكاتب وكان قد جاوز مائة سنة لقد شهدت إسحاق يوما في مجلس أنس وهو يتغنى هذا الصوت\n(خليلي هبا نصطبح بسواد ... )\nغلامه زياد جالس على مسورة يسقي وهو يومئذ غلام أمرد أصفر رقيق البدن حلو الوجه ثم أخذ يراجعه ولا أحد يستطيع يقول له زدني ولا انقصني أخبرني علي بن صالح بن الهيثم الأنباري قال حدثني أحمد بن الهيثم يعني جد أبي رحمه الله قال كنت ذات يوم جالسا في منزلي بسر من رأى وعندي إخوان لي وكان طريق إسحاق في مضيه إلى دار الخليفة ورجوعه منها على منزلي فجاءني الغلام يوما وعندي أصدقاء لي فقال لي إسحاق بن إبراهيم الموصلي بالباب فقلت له قل له ويلك يدخل أوفي الخلق أحد يستأذن عليه لإسحاق فذهب الغلام وبادرت أسعى في أثره حتى تلقيته فدخل وجلس منبسطا آنسا فعرضنا عليه ما عندنا فأجاب إلى الشرب فأحضرناه نبيذا مشمسا فشرب منه ثم قال أتحبون أن أغنيكم قلنا إي والله أطال الله بقاءك إنا نحب ذلك قال فلم لم تسألوني قلنا هبناك والله قال فلا\nتفعلوا ثم دعا بعود فأحضرناه فاندفع فغنانا فشربنا وطربنا فلما فرغ قال أحسنت أملا فقلنا بلى والله جعلنا الله فداءك لقد أحسنت قال فما منعكم أن تقولوا لي أحسنت قلنا الهيبة والله لك قال فلا تفعلوا هذا فيما تستأنفون فإن المغني يحب أن يقال له غن ويحب أن يقال له إذا غنى أحسنت ثم غنانا صوته\n(خليلي هبا نصطبح بسواد ... )\nقلنا له يا أبا محمد من هو زياد الذي عنيته قال هو غلامي الواقف بالباب ادعوه يا غلمان فأدخل إلينا فإذا غلام خلاسي قيمته عشرون دينارا أو نحوها فأمسكنا عنه فقال أتسألوني عنه فأعرفكم إياه ويخرج كما دخل وقد سمعتم شعري فيه وغنائي أشهدكم أنه حر لوجه الله وأني زوجته أمتي فلانه فأعينوه على أمره قال فلم يخرج حتى أوصلنا إليه عشرين ألف درهم أخرجناها له من أموالنا أخبرني يحيى بن علي بن يحيى قال حدثني أبي قال توفي زياد غلام إسحاق الذي يقول فيه\n(وقولا لساقينا زياد يرقها ... )\nفقال إسحاق يرثيه\n(فقدنا زيادا بعد طول صحابة ... فلا زال يسقي الغيث قبر زياد)\n(ستبكيك كأس لم تجد من يديرها ... وظمآن يستبطي الزجاجة صاد)","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":17,"spl":"أخبار حجبة بن المضرب — خبر إسحاق مع غلامه زياد","partialRef":{"sid":"b52-110","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b262-25","bab":"الجزء 20","sec":"الأمين يطلب إسحاق فيغنيه","page":"ج20 ص336","text":"أخبرني عمي قال حدثني ابن المكي عن أبيه قال\nاصطبح محمد الأمين ذات يوم وأمر بالتوجيه إلى إسحاق فوجه إليه عدة رسل كلهم لا يصادفه حتى جاء أحدهم به فدخل منشيا ومحمد مغضب فقال له أين كنت ويلك قال أصبحت يا أمير المؤمنين نشيطا فركبت إلى بعض المنتزهات فاستطبت الموضع وأقمت فيه وسقاني زياد فذكرت أبياتا للأخطل وهو يسقيني فدار لي فيها لحن حسن فصنعته فيها وقد جئتك به فتبسم ثم قال هات فما تزال تأتي بما يرضي عنك عند السخط فغناه صوت\n(إذا ما زياد علني ثم علني ... ثلاث زجاجات لهن هدير)\n(خرجت أجر الذيل زهوا كأنني ... عليك أمير المؤمنين أمير)\nال بل على أبيك قبح الله فعلك فما يزال إحسانك في غنائك يمحو إساءتك في فعلك وأمر له بألف دينار الشعر في هذين البيتين للأخطل والغناء لإسحاق رمل بالبنصر ورواية شعر الأخطل\n(إذا ما نديمي علني ثم علني ... )\nإنما غيره إسحاق فقال إذا ما زياد أخبرني علي بن سليمان عن محمد بن يزيد النحوي أن عبد الملك بن مروان قال للأخطل ما يدعوك إلى الخمر فوالله إن أولها لمر وإن آخرها لسكر قال أجل ولكن بينهما حالة ما ملكك عندها بشيء وقد قلت في ذلك\n(إذا ما نديمي علني ثم علني ... ثلاث زجاجات لهن هدير)\n(خرجت أجر الذيل زهوا كأنني ... عليك أمير المؤمنين أمير)\nال فجعل عبد الملك يضحك صوت\n(أشارت بطرف العين خيفة أهلها ... إشارة محزون ولم تتكلم)\n(فأيقنت أن الطرف قد قال مرحبا ... وأهلا وسهلا بالحبيب المسلم)\n(هنيئا لكم حبي وصفو مودتي ... فقد سيط من لحمي هواك ومن دمي)\nلشعر لعمر بن أبي ربيعة والغناء لابن عائشة ثاني ثقيل بالبنصر وفيه لدحمان ثقيل أول بالبنصر ويقال إنه لابن سريج وقيل إن الثقيل الأول لابن عائشة والثقيل الثاني لابن سريج وفيه خفيف ثقيل أول ينسب إلى ابن سريج وإلى علي بن الجواري","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":18,"spl":"الأمين يطلب إسحاق فيغنيه","partial":1},
{"id":"b262-26","bab":"الجزء 20","sec":"خبر لحبابة مع ابن عائشة","page":"ج20 ص339","text":"أخبرني الحسن بن يحيى وابن أبي يحيى الأزهر عن حماد بن إسحاق عن أبيه عن المدائني قال كانت حبابة جارية يزيد بن عبد الملك معجبة بغناء ابن عائشة وكان ابن عائشة حديث السن فلما طال عهدها به اشتاقت إلى أن تسمع غناءه فلم تدر كيف تصنع فاختلفت هي وسلامة في صوت لمعبد فأمر\nيزيد بإحضاره ووجه في ذلك رسولا فبعثت حبابة إلى الرسول سرا فأمرته أن يأتي ابن عائشة وأمير المدينة في خفاء ويبلغهما رسالتهما بالخروج مع معبد سرا وقالت قل لهما يستران ذلك عن أمير المؤمنين فلما قدم الرسول إلى عامل المدينة أبلغه ما قالت حبابة فأمر ابن عائشة بالرحلة مع معبد وقال لمعبد انظر ما تأمرك به حبابة فانتبه إليه فقال نعم فخرجا حتى قدما على يزيد وبلغ الخبر حبابة فلم تدر كيف تصنع في أمر ابن عائشة فلما حضر معبد حاكمت سلامة إليه فحكم لها فاندفعت فغنت صوتا لابن عائشة وفيه لابن سريج لحن ولحن ابن عائشة أشهرهما وهو\n(أشارت بطرف العين خيفة أهلها ... )\nقال يزيد يا حبيبتي أنى لك هذا ولم أسمعه منك وهو على غاية الحسن إن لهذ لشأنا فقالت يا أمير المؤمنين هذا لحن كنت أخذته عن ابن عائشة قال ذلك الصبي قالت نعم وهذا أستاذه وأشارت بيدها إلى معبد فقال لمعبد أهذا لحن ابن عائشة أو انتحله فقال معبد هذا أصلح الله الأمير له فقال يزيد لو كان حاضرا ما كرهنا أن نسمع منه فقال معبد هو والله معي لا يفارقني فقال يزيد ويلك يا معبد احتملنا الساعة أمرك فزدتنا ما كرهنا ثم قال لحبابة هذا والله عملك قالت أجل يا سيدي قال لها هذه الشام ولا تحتمل لنا ما تحتمله المدينة قالت يا سيدي أنا والله أنا أحب أن أسمع من ابن عائشة فأحضر فلما دخل قال له صوتا غنته حبابة\n(أشارت بطرف العين خيفة أهلها ... )\nغناه فقال هو والله يا حبابة منه أحسن منه منك قالت أجل يا سيدي ثم قال يزيد هات يا محمد ما عندك فغنى\nصوت\n(قف بالمنازل قبل أن نتفرقا ... واستنطق الربع المحيل المخلقا)\n(عن علم ما فعل الخليط لعله ... بجواب رجع حديثهم أن ينطقا)\n(فيبين من أخبارهم لمتيم ... أمسى وأصبح بالرسوم معلقا)\n(كلفا بها أبدا تسح دموعه ... وسط الديار مسائلا مستنطقا)\n(ذرفت له عين يرى إنسانها ... في لجة ما مائها مغرورقا)\n(تجري محاجرها الدموع كأنها ... در وهي من سلكه مستوسقا)\nلغناء لابن عائشة ولحنه من الثقيل الأول بالوسطى وفيه لشارية خفيف رمل مطلق في مجرى الوسطى ويقال إن فيه لابن جندب وحنين لحنين قال فقال له يزيد أهلا وسهلا بك يابن عائشة فأنت والله\nالحسن الوجه الحسن الغناء وأحسن إليه ووصله ثم لم يره يزيد بعد هذا المجلس وبعثت إليه حبابة ببر وألطاف وأتبعتها سلامة في ذلك صوت\n(لما سمعت الديك صاح بسحرة ... وتوسط النسران بطن العقرب)\n(وبدا سهيل في السماء كأنه ... نور وعارضه هجان الربرب)\n(نبهت ندماني وقلت له اصطبح ... يابن الكرام من الشراب الطيب)\n(صفراء تبرق في الزجاج كأنها ... حدق الجرادة أو لعاب الجندب)\nالشعر لأبي الهندي والغناء لإبراهيم الموصلي ثاني ثقيل بالبنصر عن عمرو","topic":"أخبار المخبل القيسي ونسبه","topicNo":262,"sp":19,"spl":"خبر لحبابة مع ابن عائشة","partialRef":{"sid":"b126-11","gi":6,"vi":0,"side":0},"partial":1},
{"id":"b263-1","bab":"الجزء 20","sec":"أخبار أبي الهندي ونسبه","page":"ج20 ص342","text":"اسمه غالب بن عبد القدوس بن شبث بن ربعي وكان شاعرا مطبوعا وقد أدرك الدولتين دولة بني أمية وأول دولة ولد العباس وكان جزل الشعر حسن الألفاظ لطيف المعاني وإنما أخمله وأمات ذكره بعده من بلاد العرب ومقامه بسجستان وبخراسان وشغفه بالشراب ومعاقرته إياه وفسقه وما كان يتهم به من فساد الدين واستفرغ شعره بصفة الخمر وهو أول من وصفها من شعراء الإسلام فجعل وصفها وكده وقصده ومن مشهور قوله فيها ومختاره\n(سقيت أبا المطرح إذ أتاني ... وذو الرعثات منتصب يصيح)\n(شرابا يهرب الذبان منه ... ويلثغ حين يشربه الفصيح)","topic":"أخبار أبي الهندي ونسبه","topicNo":263,"sp":0,"spl":"أخبار أبي الهندي ونسبه — أبو نواس يأخذ معانيه في الخمر من شعره"},
{"id":"b263-2","bab":"الجزء 20","sec":"أبو نواس يأخذ معانيه في الخمر من شعره","page":"ج20 ص343","text":"أخبرني علي بن سليمان الأخفش قال حدثني فضل اليزيدي أنه سمع إسحاق الموصلي يوما يقول وأنشد شعرا لأبي الهندي في صفة الخمر فاستحسنه وقرظه فذكر عنده أبو نواس فقال ومن أين أخذ أبو نواس معانيه إلا من هذه الطبقة وأنا أوجدكم سلخه هذه المعاني كلها في شعره فجعل ينشد\nبيتا من شعر أبي الهندي ثم يستخرج المعنى والموضع الذي سرقه الحسن فيه حتى أتى على الأبيات كلها واستخرجها من شعره أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني عبد الله بن أبي سعد قال حدثني شيخ من أهل البصرة قال كنا عند أبي عبيدة فأنشد منشد شعرا في صفة الخمر أنسيه الشيخ فضحك ثم قال هذا أخذه من قول أبي المهندي\n(سيغني أبا الهندي عن وطب سالم ... أباريق لم يعلق بها وضر الزبد)\n(مفدمة قز كأن رقابها ... رقاب بنات الماء تفزع للرعد)\n(جلتها الجوالي حين طاب مزاجها ... وطيبتها بالمسك والعنبر والورد)\n(تمج سلافا في الأباريق خالصا ... وفي كل كأس من مها حسن القد)\n(تضمنها زق أزب كأنه ... صريع من السودان ذو شعر جعد)\nسخت من كتاب ابن النطاح حدثني بعض أصحابنا أن أبا الهندي اشتهى الصبوح في الحانة ذات يوم فأتى خمارا بسجستان في محله يقال لها كوه زيان وتفسيره جبل الخسران يباع فيها الخمر والفاحشة ويأوي إليها كل خارب وزان ومغنية فدخل إلى الخمار\nفقال له اسقني وأعطاه دينارا فكال له وجعل يشرب حتى سكر وجاء قوم يسألون عنه فصادفوه على تلك الحال فقالوا للخمار ألحقنا به فسقاهم حتى سكروا فانتبه فسأل عنهم فعرفه الخمار خبرهم فقال له هذا الآن وقت السكر الآن طاب ألحقني بهم فجعل يشرب حتى سكر وانتبهوا فقالوا للخمار ويحك هذا نائم بعد فقال لا ولقد انتبه فلما عرف خبركم شرب حتى سكر فقالوا ألحقنا به فسقاهم حتى سكروا وانتبه فسأل عن خبرهم فعرفه فقال والله لألحقن بهم فشرب حتى سكر ولم يزل ذلك دأبه ودأبهم ثلاثة أيام لم يلتقوا وهم في موضع واحد ثم تركوا هم الشرب عمدا حتى أفاق فلقوه وهذا الخبر بعينه يحكى لوالبة بن الحباب مع أبي نواس وقد ذكر في أخبار والبة والصحيح أنه لأبي الهندي وفي ذلك يقول\n(ندامى بعد ثالثة تلاقوا ... يضمهم بكوه زيان راح)\n(وقد باكرتها فتركت منها ... قتيلا ما أصابتني جراح)\n(وقالوا أيهاالخمار من ذا ... فقال أخ تخونه اصطباح)\n(فقالوا هات راحك ألحقنا ... به وتعللواثم ولها سلاح)\n(فما إن لبثتهم أن رمتهم ... بحد سلاحها ولها سلاح)\n(وحان تنبهي فسألت عنهم ... فقال أتاحهم قدر متاح)\n(رأوك مجدلا فاستخبروني ... فحركهم إلى الشرب ارتياح)\n(فقلت بهم فألحقني فهبوا ... فقالوا هل تنبه حين راحوا)\n(فقال نعم فقالوا ألحقنا ... به قد لاح للرائي صياح)\n(فما إن زال ذاك الدأب منا ... ثلاثا يستغب ويستباح)\n(نبيت معا وليس لنا لقاء ... ببيت ما لنا فيه براح)","topic":"أخبار أبي الهندي ونسبه","topicNo":263,"sp":0,"spl":"أخبار أبي الهندي ونسبه — أبو نواس يأخذ معانيه في الخمر من شعره"},
{"id":"b263-3","bab":"الجزء 20","sec":"مات مختنقا بسبب الشراب","page":"ج20 ص346","text":"أخبرني عمي الحسن بن أحمد قال حدثني الحسن بن عليل العنزي قال قال صدقة بن إبراهيم البكري كان أبو الهندي يشرب معنا بمرو وكان إذا سكر يتقلب تقلبا قبيحا في نومه فكنا كثيرا ما نشد رجله لئلا يسقط من السطح فسكر ليلة وشددنا رجله بحبل وطولنا فيه ليقدر على القيام إلى البول وغير ذلك من حوائجه فتقلب وسقط من السطح وأمسكه الحبل فبقي منكسا وتخنق بما في جوفه من الشراب فأصبحنا فوجدناه ميتا قال صدقة فمررت بقبره بعذ ذلك فوجدت عليه مكتوبا\n(اجعلوا إن مت يوما كفني ... ورق الكرم وقبري معصره)\n(إنني أرجو من الله غدا ... بعد شرب الراح حسن المغفرة)\nقال فكان الفتيان بعد ذلك يجيئون إلى قبره ويشربون ويصبون القدح إذا انتهى إليه على قبره قال حماد بن إسحاق عن أبيه في وفاة أبي الهندي إنه خرج وهو سكران في ليلة باردة من حانة خمار وهو ريان فأصابه ثلج فقتله فوجد من غد ميتا على الطريق\nوروى حماد بن إسحاق عن أبيه قال حج نصر بن سيار وأخرج معه أبا الهندي فلما حضرت أيام الموسم قال له أبا الهندي إنا بحيث ترى وفد الله وزوار بيته فهب لي النبيذ في هذه الأيام واحتكم علي فلولا ما ترى ما منعتك فضمن له ذلك وغلظ عليه الإحتكام ووكل به نصر بن سيار فلما انقضى الأجل مضى في السحر قبل أن يلقى نصرا فجلس في أكمة يشرف منها على فضاء واسع فجلس عليها ووضع بين يديه إداوة وأقبل يشرب ويبكي ويقول\n(أديرا علي الكأس إلي فقدتها ... كما فقد المفطوم در المراضع)\n(حليف مدام فارق الراح روحه ... فظل عليها مستهل المدامع)\nال وعاتب قوم أبا الهندي على فسقه ومعاقرته الشراب فقال\n(إذا صليت خمسا كل يوم ... فإن الله يغفر لي فسوقي)\n(ولم أشرك برب الناس شيئا ... فقد أمسكت بالدين الوثيق)\n(وجاهدت العدو ونلت مالا ... يبلغني إلى البيت العتيق)\n(فهذا الدين ليس به خفاء ... دعوني من بنيات الطريق)\nال إسحاق وشرب يوما أبو الهندي بكوه زيان عند خمارة هناك وكان\nعندها نسوة عواهر ففجر بهن ولم يعطهن شيئا فجعلن يطالبنه بجعل فلم ينفعهن فقال في ذلك\n(آلى يمينا أبو الهندي كاذبة ... ليعطين زاوني لست ماشينا)\n(وغرهن فلما أن قضى و طرا ... قال ارتحلن فأخزى الله ذادينا)\nأخبرني عمي عن عبيد الله بن عبد الله بن طاهر عن أبي محلم قال خطب أبو الهندي غالب بن عبد القدوس بن شبث بن ربعي إلى رجل من بني تميم فقال لو كنت مثل أبيك لزوجتك فقال له غالب لكنك لو كنت مثل أبيك ما خطبت إليك قال أبو محلم ومر نصر بن سيار بأبي الهندي وهو سكران يتمايل فوقف عليه فعذله وسبه وقال ضيعت شرفك وفضحت أسلافك فلما طال عتابه التفت إليه فقال لولا أني ضيعت شرفي لم تكن أنت على خراسان فانصرف نصر خجلا قال أبو محمل وكان بسجستان رجل يقال له برزين ناسكا وكان أبوه صلب في خرابة فجلس إليه أبو الهندي فطفق يعذله ويعرض له بالشراب فقال له أبو الهندي أحدكم يرى القذاة في عين أخيه ولا يرى الخشبة في است أبيه فأخجله قال أبو محلم وكان أسرع الناس جوابا صوت\n(لقد قلت حين قربت ... العيس يا نوار)\n(قفوا فاربعوا قليلا ... فلم يربعوا وساروا)\n(فنفسي لها حنين ... وقلبي له انكسار)\n(وصدري به غليل ... ودمعي له انحدار)\nلشعر لسعيد بن وهب والغناء لسليم رمل بالوسطى عن الهشامي ومن جامع سليم ونسخة عمرو الثانية","topic":"أخبار أبي الهندي ونسبه","topicNo":263,"sp":1,"spl":"مات مختنقا بسبب الشراب"},
{"id":"b263-4","bab":"الجزء 20","sec":"أخبار سعيد بن وهب","page":"ج20 ص350","text":"سعيد بن وهب أبو عثمان بني سامة بن لؤي بن نصر مولده ومنشؤه بالبصرة ثم سار إلى بغداد فأقام بها وكانت الكتابة صناعته فتصرف مع البرامكة فاصطنعوه وتقدم عندهم وكان شاعرا مطبوعا ومات في أيام المأمون وأكثر شعره في الغزل والتشبيب بالمذكر وكان مشغوفا بالغلمان والشراب ثم تنسك وتاب وحج راجلا على قدميه ومات على توبة وإقلاع ومذهب جميل ومات وأبو العتاهية حي وكان صديقه فرثاه فأخبرني علي بن سليمان الأخفش عن محمد بن مزيد قال حدثت عن بعض أصحاب أبي العتاهية قال جاء رجل إلى أبي العتاهية ونحن عنده فساره في شيء فبكى أبو العتاهية فقلنا له ما قال لك هذا الرجل يا أبا إسحاق فأبكاك فقال وهو يحدثنا لا يريد أن يقول شعرا\n(قال لي مات سعيد بن وهب ... رحم الله سعيد ين وهب)\n(يا أبا عثمان أبكيت عيني ... يا أبا عثمان أوجعت قلبي)\nقال فعجبنا من طبعه وأنه تحدث فكان حديثه شعرا موزونا أخبرني الحسن بن علي الخفاف قال حدثنا عبد الله بن أبي سعد قال حدثني سيبويه أبو محمد قال كان سعيد بن وهب الشاعر البصري مولى بني سامة قد تاب وتزهد وترك قول الشعر وكان له عشرة من البنين وعشر من البنات فكان إذا وجد شيئا من شعره خرقه وأحرقه وكان امرأ صدق كثير الصلاة يزكي في كل سنة عن جميع ما عنده حتى إنه ليزكي عن فضة كانت على امرأته","topic":"أخبار أبي الهندي ونسبه","topicNo":263,"sp":2,"spl":"أخبار سعيد بن وهب"},
{"id":"b263-5","bab":"الجزء 20","sec":"نماذج من شعره","page":"ج20 ص351","text":"أخبرني عمي قال حدثني علي بن الحسين بن عبد الأعلى قال حدثني أبو عثمان الليثي قال كان سعيد بن وهب يتعشق غلاما يتشطر يقال له سعيد فبلغه أنه توعده أن يجرحه فقال فيه\n(من عذيري من سميي ... من عذيري من سعيد)\n(أنا باللحم أجاه ... ويجاني بالحديد)\nدثني حجظة قال حدثني ميمون بن هارون قال نظر سعيد بن وهب إلى قوم من كتاب السلطان في أحوال جميلة فأنشأ يقول\n(من كان في الدنيا له شارة ... فنحن من نظارة الدنيا)\n(نرمقها من كثب حسرة ... كأننا لفظ بلا معنى)\n(يعلو بها الناس وأيامنا ... تذهب الأرذل والأدنى)\nخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن يعقوب بن داود قال حدثني عبد الله بن أبي العلاء المغني قال نظر إلي سعيد بن وهب وأنا على باب ميمون بن إسماعيل حين اخضر شاربي ومعه إسحاق بن إبراهيم الموصلي فسلمت على إسحاق فأقبل عليه سعيد وقال من هذا الغلام فتبسم وقال هذا ابن صديق لي فأقبل علي وقال\n(لا تخرجن مع الغزي لمغنم ... إن الغزي يراك أفضل مغنم)\n(في مثل وجهك يستحل ذوو التقى ... والدين والعلماء كل محرم)\n(ما أنت إلا غادة ممكورة ... لولا شواربك المطلة بالفم)\nخبرني محمد بن خلف بن المرزبان قال حدثني احمد بن أبي طاهر عن أبي دعامة قال مر سعيد بن وهب والكسائي فلقيا غلاما جميل الوجه فاستحسنه الكسائي وأراد أن يستميله فأخذ يذاكره بالنحو ويتكلم به فلم يمل إليه وأخذ سعيد بن وهب في الشعر ينشده فمال إليه الغلام فبعث به إلى منزله وبعث معه بالكسائي وقال له حدثه وآنسه إلى أن أجيء وتشاغل بحاجة له فمضى به الكسائي فما زال يداريه حتى قضى حاجته وأربه ثم قال له انصرف وجاء سعيد فلم يره فقال\n(أبو حسن لا يفي ... فمن ذا يفي بعده)\n(أثرت له شادنا ... فصايده وحده)\n(وأظهر لي غدرة ... وأخلفني وعده)\n(سأطلب ما ساءه ... كما ساءني جهده)\nخبرني جعفر بن قدامة قال حدثني حماد بن إسحاق عن أبيه قال كان سعيد بن وهب لي صديقا وكان له ابن يكنى أبا الخطاب من أكيس الصبيان وأحسنهم وجها وأدبا فكان لا يكاد يفارقه في كل حال لشدة شغفه به ورقته عليه فمات وله عشر سنين فجزع عليه جزعا شديدا وانقطع عن لذاته فدخلت إليه يوما لأعاتبه على ذلك وأستعطفه فحين رأى ذلك في وجهي فاضت دموعه ثم انتحب حتى رحمته وأنشدني\n(عين جودي على أبي الخطاب ... إذ تولى غضبا بماء الشباب)\n(لم يقارف ذنبا ولم يبلغ الحنث ... مرجى مطهر الثواب)\n(فقدته عيني إذا ما سعى أترابه ... من جماعة الأتراب)\n(إن غدا موحشا لداري فقد أصبح ... أنس الثرى وزين التراب)\n(أحمد الله يا حبيبي فإني ... بك راج منه عظيم الثواب)\nم ناشدني ألا أذكره بشيء مما جئت إليه فقمت ولم أخاطبه بحرف وقد رأيت هذه الأبيات بعينها بخط إسحاق في بعض دفاتره يقول فيه أنشدني سعي بن وهب لنفسه يرثي ابنا له صغيرا وهي على ما ذكره جعفر بن قدامة عن حماد سواء\nأخبرني عيسى بن الحسين الوارق قال حدثني أبو هفان قال حدثني أبو دعامة قال كان سعيد بن وهب مألفة لكل غلام أمرد وفتى ظريف وقينة محسنة فحدثني رجل كان يعاشره قال دخل إليه يوما وأنا عنده غلامان أمردان فقالا له قد تحاكمنا إليك أينا أجمل وجها وأحسن جسما وجعلنا لك أجر حكمك أن تختار أينا حكمت له فتقضي حاجتك منه فحكم لأحدهما وقام فقضى حاجته واحتبسهما فشربا عنده نبيذا ثم مال على الآخر أيضا وقمت معه فداخلتهما حتى فعلت كفعله فقال لي سعيد هذا يوم الغارات في الحارات ثم قال\n(رئمان جاءا فحكماني ... لا حكم قاض ولا أمير)\n(هذا كشمس الضحى جمالا ... وذا كبدر الدجى المنير)\n(وفضل هذا كذا على ذا ... فضل خميس على عشير)\n(قالا أشر بيننا برأي ... ونجعل الفضل للمشير)\n(تباذلا ثم قمت حتى ... أخذت فضلي من الكبير)\n(وكان عيبا بأن أراني ... أحرم حظي من الصغير)\n(فكان مني ومن قريني ... إليهما وثبة المغير)\n(فمن رأى حاكما كحكمي ... أعظم جورا بلا نكير)\nقال وشاعت الأبيات حتى بلغت الرشيد فدعا به فاستننشده إياها فتلكأ فقال له أنشد ولا بأس عليك فأنشد فقال له ويلك اخترت الكبير سنا أو قدرا قال بل الكبير قدرا قال لو قلت غير هذا سقطت عندي واستخففت بك ووصله","topic":"أخبار أبي الهندي ونسبه","topicNo":263,"sp":3,"spl":"نماذج من شعره"},
{"id":"b263-6","bab":"الجزء 20","sec":"سعيد بن وهب والفضل بن يحيى","page":"ج20 ص355","text":"أخبرني جعفر بن قدامة حدثني أبو العيناء قال دخل سعيد بن وهب على الفضل بن يحيى في يوم قد جلس فيه للشعراء فجعلوا ينشدونه ويأمر لهم بالجوائز حتى لم يبق منهم أحد فالتفت إلى سعيد بن وهب كالمستنطق فقال له أيها الوزير إني ما كنت استعددت لهذه الحال ولا تقدمت لها عندي مقدمة فأعرفها ولكن قد حضرني بيتان أرجو أن ينوبا عن قصيدة فقال هاتهما فرب قليل أبلغ من الكثير فقال سعيد\n(مدح الفضل نفسه بالفعال ... فعلا عن مديحنا بالمقال)\n(أمرني بمدحه قلت كلا ... كبر الفضل عن مديح الرجال)\nال فطرب الفضل وقال له أحسنت والله وأجدت ولئن قل القول ونزر لقد اتسع المعنى وكثر ثم أمر له بمثل ما أعطاه كل من أنشده مديحا يومئذ وقال لا خير فيما يجيء بعد بيتيك وقام من المجلس وخرج الناس يومئذ بالبيتين لا يتناشدون سواهما حدثني عمي قال حدثني ميمون بن هارون قال حدثت عن الخريمي قال كان الفضل بن يحيى ينافس أخاه جعفرا وينافسه جعفر وكان أنس بن أبي شيخ خاصا بجعفر ينادمه ويأنس به في خلواته وكان سعيد بن وهب بهذه المنزلة للفضل فدخلت يوما إلى جعفر ودخل إليه سعيد بن وهب فحدثه وأنشده\nوتنادر له وحكى عن المتنادرين وأتى بكل ما يسر ويطرب ويضحك وجعفر ساكت ينظر إليه لا يزيد على ذلك فلما خرج سعيد من عنده تجاهلت عليه وقلت له من هذا الرجل الكثير الهذيان قال أو ما تعرفه قلت لا قال هذا سعيد بن وهب صديق أخي أبي العباس وخلصانه وعشيقه قلت وأي شيء رأى فيه قال لا شيء والله إلا القذر والبرد والغثاثة ثم دخلت بعد ذلك إلى الفضل ودخل أنس بن أبي شيخ فحدث وندر وحكى عن المضحكين وأتى بك طريفة فكانت قصة الفضل معه قصة جعفر مع سعيد فقلت له بعد أن خرج من حضرته من هذا المبرد قال أو لا تعرفه قلت لا قال هذا أنس بن أبي شيخ صديق أخي أبي الفضل وعشيقه وخاصته قلت وأي شيء أعجبه فيه قال لا أدري والله إلا القذر والبرد وسوء الإختيار قال وأنا والله أعرف بسعيد وأنس من الناس جميعا ولكني تجاهلت عليهما و ساعدتهما على هواهما","topic":"أخبار أبي الهندي ونسبه","topicNo":263,"sp":4,"spl":"سعيد بن وهب والفضل بن يحيى — سعيد والفضل بن الربيع"},
{"id":"b263-7","bab":"الجزء 20","sec":"سعيد والفضل بن الربيع","page":"ج20 ص356","text":"حدثني عمي قال حدثني ميمون بن هارون قال قال إبراهيم بن العباس قال لي الفضل بن الربيع ذات يوم عرفتنا أيام النكبة من كنا نجهله من الناس وذلك أنا احتجنا إلى أن نودع أموالنا وكان أمرها كثيرا مفرطا فكنا\nنلقيها على الناس إلقاء ونودعها الثقة وغير الثقة فكان ممن أودعته سعيد بن وهب وكان رجلا صعلوكا لا مال له إنما صحبنا على البطالة فظننت أن ما أودعته ذاهب ثم طلبته منه بعد حين فجاءني والله بخواتيمه وأودعت علي بن الهيثم كاتبنا جملة عظيمة وكان عندي أوثق من أودعته فلما أمنت طالبته بالوديعة فجحدنيها وبهتني وحلف على ذلك فصار سعيد عندي في السماء وبلغت به كل مبلغ وسقط علي بن الهيثم فما يصل إلي ولا يلقاني أخبرني جعفر بن قدامة قال حدثني حماد بن إسحاق عن أبيه حدثني عمرو بن بانة قال كان في جواري رجل من البرامكة وكانت له جارية شاعرة ظريفة يقال لها حسناء يدخل إليها الشعراء ويسألونها عن المعاني فتأتي بكل مستحسن من الجواب فدخل إليها سعيد بن وهب يوما وجلس إليها فحادثها طويلا ثم قال لها بعد ذلك\n(حاجيتك يا حسناء ... في جنس من الشعر)\n(وفيما طوله شبر ... وقد يوفي على الشبر)\n(له في رأسه شق ... نطوف بالندى يجري)\n(إذا ماجف لم يجر ... لدى بر ولا بحر)\n(وإن بل أتى بالعجب ... العاجب والسحر)\n(أجيبي لم أرد فحشا ... ورب الشفع والوتر)\n(ولكن صغت أبياتا ... لها حظ من الزجر)\nال فغضب مولاها وتغير لونه وقال أتفحش على جاريتي وتخاطبها بالخنا فقالت له خفض عليك فما ذهب إلى ظننت وإنما يعني القلم فسري عنه وضحك سعيد وقال هي أعلم منك بما سمعت صوت\n(داينت أروى والديون تقضى ... فمطلت بعضا وأدت بعضا)\n(يا ليت أروى إذ لوتك القرضا ... جادت بقرض فشكرت القرضا)\nلشعر لرؤبة بن العجاج والغناء لعمرو بن بانة رمل بالوسطى","topic":"أخبار أبي الهندي ونسبه","topicNo":263,"sp":4,"spl":"سعيد بن وهب والفضل بن يحيى — سعيد والفضل بن الربيع"},
{"id":"b264-1","bab":"الجزء 20","sec":"أخبار رؤبة ونسبه","page":"ج20 ص359","text":"هو رؤبة بن العجاج واسم العجاج عبد الله بن رؤبة بن حنيفة وهو أبو جذيم بن مالك بن قدامة بن أسامة بن الحارث بن عوف بن مالك بن سعد بن زيد مناة بن تميم من رجاز الإسلام وفصحائهم والمذكورين المقدمين منهم بدوي نزل البصرة وهو من مخضرمي الدولتين مدح بني أمية وبني العباس ومات في أيام المنصور وقد أخذ عنه وجوه أهل اللغة وكانوا يقتدون به ويحتجون بشعره ويجعلونه إماما ويكنى أبا الجحاف وأبا العجاج أخبرني أحمد بن عبد العزيز الجوهري وأحمد بن عمار واللفظ له قال حدثنا عمر بن شبة قال حدثنا خلاد بن يزيد قال حدثني يونس بن حبيب قال كنت جالسا مع أبي عمرو بن العلاء إذ مر بنا شبيل بن عزرة الضبعي قا ل أبو يزيد وكان علامة فقال يا أبا عمرو أشعرت أني سألت رؤبة عن\nاسمه فلم يدر ما هو وما معناه قال يونس فقلت له والله لروبة أفصح من معد بن عدنان وأنا غلام رؤبة أفتعرف أنت روبة وروبة وروبة وروبة ورؤبة قال فضرب بغلته وذهب فما تكلم بشيء قال يونس فقال لي أبي عمرو ما يسرني أنك نقصتني منها قال ابن عمار في خبره والروبة اللبن الخاثر والروبة ماء الفحل والروبة الساعة تمضي من الليل والروبة الحاجة والرؤبة شعب القدح قال وأنشدني بعد ذلك\n(فأما تميم تميم بن مر ... فألفاهم القوم روبى نياما)\nحدثني ابن عمار قال حدثني عبد الله بن أبي سعد قال حدثني يحيى بن محمد بن أعين المروزي قال حدثني أبو عبيدة قال شهدت شبيلا الضبعي وأبا عمرو فذكر نحوه أخبرني أبو خليفة في كتابه إلي عن محمد بن سلام قال قلت ليونس هل رأيت عربيا قط أفصح من رؤبة قال لا ما كان معد بن عدنان أفصح منه قال يونس قال لي رؤبة حتى متى أزخرف لك كلام الشيطان أما ترى الشيب قد بلغ في لحيتك وقد روى رؤبة بن العجاج الحديث المسند عن رسول الله ورواه أبوه أيضا","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":0,"spl":"أخبار رؤبة ونسبه — أنشد ابا هريرة فشهد له بالإيمان"},
{"id":"b264-2","bab":"الجزء 20","sec":"أنشد ابا هريرة فشهد له بالإيمان","page":"ج20 ص360","text":"أخبرني عبد الله بن أبي داود السجستاني قال حدثنا عبد الله بن\nمحمد بن خلاد قال حدثنا يعقوب بن محمد الزهري قال حدثنا محمد بن إبراهيم عن يونس بن حبيب عن رؤبة بن العجاج عن أبيه قال أنشدت أبا هريرة\n(الحمد لله الذي تعلت ... بأمره السماء واستقلت)\n(بإذنه الأرض وما تغيت ... أرسى عليها بالجبال الثبت)\n(الباعث الناس ليوم الموقت ... )\nال أبو هريرة أشهد أنك تؤمن بيوم الحساب أخبرني أحمد بن عبد العزيز الجوهري عن ابن شبة عن أبي حرب البابي من آل الحجاج بن باب قال حدثنا يونس بن حبيب عن رؤبة بن العجاج عن أبي الشعثاء عن أبي هريرة قال كنا مع النبي سفر وحاد يحدو\n(طاف الخيالان فهاجا سقما ... خيال لبنى وخيال تكتما)\n(قامت تريك خشية أن تصرما ... ساقا بخنداة وكعبا أدرما)\nالنبي يسمع ولا ينكر أخبرني محمد بن خلف وكيع قال حدثنا عبد الله بن عمرو عن محمد بن إسحاق السهمي عن أبي عبيدة الحداد قال حدثنا رؤبة بن العجاج عن أبه قال سمعت أبا عبيدة يقول السواك يذهب وضر الطعام","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":0,"spl":"أخبار رؤبة ونسبه — أنشد ابا هريرة فشهد له بالإيمان","partial":1},
{"id":"b264-3","bab":"الجزء 20","sec":"أنشد أبا مسلم الخراساني فأجازه","page":"ج20 ص362","text":"أخبرني عمي قال حدثنا محمد بن سعد الكراني قال حدثنا أبو حاتم والأشنانداني أبو عثمان عن أبي عبيدة عن رؤبة بن العجاج قال بعث إلي أبو مسلم لما أفضت الخلافة إلى بني هاشم فلما دخلت عليه رأى مني جزعا فقال اسكن فلا بأس عليك ما هذا الجزع الذي ظهر منك قلت أخافك قال ولم قلت لأنه بلغني أنك تقتل الناس قال إنما أقتل من يقاتلني ويريد قتلي أفأنت منهم قلت لا قال فهل ترى بأسا قلت فأقبل على جلسائه ضاحكا ثم قال أما ابن العجاج فقد رخص لنا ثم قال أنشدني قولك\n(وقائم الأعماق خاوي المخترق ... )\nقلت أو أنشدك أصلحك الله أحسن منه قال هات فأنشدته\n(قلت وقولي مستجد حوكا ... لبيك إذ دعوتني لبيكا)\n(أحمد ربا ساقني إليكا ... )\nقال هات كلمتك الأولى قلت أو أنشدك أحسن منها قال هات فأنشدته\n(ما زال يبني خندقا ويهدمه ... ويستجيش عسكرا ويهزمه)\n(ومغنما يجمعه ويقسمه ... مروان لما أن تهاوت أنجمه)\n(وخانه في حكمه منجمه ... )\nال دع هذا وأنشدني وقاتم الأعماق قلت أو أحسن منه قال هات فأنشدته\n(رفعت بيتا وخفضت بيتا ... وشدت ركن الدين إذ بنيتا)\nقال هات ما سألتك عنه فأنشدته\n(في الأكرمين من قريش بيتا ... )\n(ما زال يأتي الأمر من أقطاره ... على اليمين وعلى يساره)\n(مشمرا لا يصطلى بناره ... حتى أقر الملك في قراره)\n(وفر مروان على حماره ... )\nقال ويحك هات ما دعوتك له وامرتك بإنشاده ولا تنشد شيئا غيره فأنشدته\n(وقاتم الأعماق خاوي المخترق ... )\nلما صرت إلى قولي\n(يرمي الجلاميد بجلمود مدق ... )\nال قاتلك الله لشد ما ما استصلبت الحافر ثم قال حسبك أنا ذلك الجلمود المدق قال وجيء بمنديل فيه مال فوضع بين يدي فقال أبو مسلم يا رؤبة إنك أتيتنا والأموال مشفوهة وإن لك لعودة إلينا وعلينا معولا والدهر أطرق مستتب فلا تجعل بجنبيك الأسدة قال رؤبة فأخذت المنديل منه وتالله ما رأيت أعجميا أفصح منه وما ظننت أن أحدا يعرف هذا الكلام غيري وغير أبي\nقال الكراني قال أبو عثمان الأشنانداني خاصة يقال اشتق ما في الإناء وشفهه إذا أتى عليه وأنشد\n(وكاد المال يشفهه عيالي ... وما ذو عيلتي من لا أعول)","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":1,"spl":"أنشد أبا مسلم الخراساني فأجازه","partial":1},
{"id":"b264-4","bab":"الجزء 20","sec":"رؤبة آكل الفأر","page":"ج20 ص364","text":"أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد وأخبرني إبراهيم بن أيوب قال حدثني ابن قتيبة قال كان رؤبة يأكل الفأر فقيل له في ذلك وعوتب فقال هو والله أنظف من دواجنكم ودجاجكم اللواتي يأكلن القذر وهل يأكل الفأر إلا نقي البر ولباب الطعام أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة عن رؤبة قال لما ولي الوليد بن عبد الملك الخلافة بعث بي الحجاج مع أبي لنلقاه فاستقبلنا الشمال حتى صرنا بباب الفراديس قال وكان خروجنا في عام مخصب وكنت أصلي الغداة وأجتني من الكمأة ما شئت ثم لا أجاوز إلا قليل حتى أرى خيرا منها فأرمي بها\nوآخذ الآخر حتى نزلنا بعض المياه فأهدي لنا حمل مخرفج ووطب لبن غليظ وزبدة كأنها رأس نعجة حوشية فقطعنا الحمل آرابا وكررنا عليه اللبن والزبدة حتى إذا بلغ إناه انتشلنا اللحم بغير خبز ثم شربت من مرقه شربة لم تزل لها ذفرياي ترشحان حتى رجعنا إلى حجر فكان أول من لقينا من الشعراء جريرا فاستعهدنا ألا نعين عليه فكان أول من أذن له من الشعراء أبي ثم أنا فأقبل الوليد على جرير فقال له ويلك ألا تكون مثل هذين عقدا الشفاه عن أعراض الناس فقال إني أظلم فلا أصبر ثم لقينا بعد ذلك جرير فقال يا بني أم العجاج والله لئن وضعت كلكلي عليكما ما أغنت عنكما مقطعاتكما فقلنا لا والله ما بلغه عنا شيء ولكنه حسدنا لما أذن لنا قبله واستنشدنا قبله\nوقد أخبرني ببعض هذا الخبر الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن الحارث الخراز عن المدائني قال قال روح بن فلان الكلبي كنت عند عبد الملك بن بشر بن مروان فدخل جرير فلما رأى العجاج أقبل عليه ثم قال له والله لئن سهرت لك ليلة ليقلن عنك نفع مقطعاتك هذه فقال العجاج يا أبا حرزة والله ما فعلت ما بلغك وجعل يعتذر ويحلف ويخضع فلما خرج قال له رجل لشد ما اعتذرت إلى جرير قال والله لو علمت أنه لا ينفعني إلا السلاح لسلحت أخبرني أحمد بن العزيز الجوهري قال حدثنا عمر بن شبة عن أحمد بن معاوية عن الأصمعي عن سليمان بن أخضر عن ابن عون قال ما شبهت لهجة الحسن البصري إلا بلهجة رؤبة ولم يوجد له ولا لأبيه في شعرهما حرف مدغم قط أخبرني محمد بن الحسن بن دريد قال أخبرني عبد الرحمن ابن أخي الأصمعي عن عمه قال قيل ليونس من أشعر الناس قال العجاج ورؤبة فقيل له ولم نعن الرجاز فقال هما أشعر من أهل القصيد إنما الشعر كلام فأجود أشعره قد قال العجاج\n(قد جبر الدين الإله فجبر ... )\nهي نحو من مائتي بيت موقوفة القوافي ولو أطلقت قوافيها كانت كلها منصوبة وكذلك عامة أراجيزهما","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":2,"spl":"رؤبة آكل الفأر","partial":1},
{"id":"b264-5","bab":"الجزء 20","sec":"يقعد اللغويين إليه يوم الجمعة","page":"ج20 ص366","text":"أخبرني أبو خليفة في كتابه إلي عن محمد بن سلام عن أبي زيد الأنصاري والحكم بن قنبر قالا\nكنا نقعد إلى رؤبة يوم الجمعة في رحبة بني تميم فاجتمعنا يوما فقطعنا الطريق ومرت بنا عجوز فلم تقدر على أن تجوز في طريقها فقال رؤبة بن العجاج\n(تنح للعجوز عن طريقها ... إذ أقبلت رائحة من سوقها)\n(دعها فما النحوي من صديقها ... )\nأخبرني أحمد بن عبد العزيز الجوهري وأحمد بن عبيد الله بن عمار قالا حدثنا عمر بن شبة قال حدثنا أبو زيد سعيد بن أوس الأنصاري النحوي قال دخل رؤبة بن العجاج السوق وعليه برنكان أخضر فجعل الصبيان يعبثون به ويغرزون شوك النخل في برنكانه ويصيحون به يا مرذوم يا مرذوم فجاء إلى الوالي فقال أرسل معي الوزعة فإن الصبيان قد حالوا بيني وبين دخول السوق فأرسل معه أعوانا فشد على الصبيان وهو يقول\n(أنحى على أمك بالمرذوم ... أعور جعد من بني تميم)\n(شراب ألبان خلايا الكوم ... )\nفروا من بين يديه فدخلوا دارا في الصيارفة فقال له الشرط أين هم قال دخلوا دار الظالمين فسميت دار الظالمين إلى الآن لقول رؤبة وهي في صيارفة سوق البصرة\nوذكر أحمد بن الحارث الخراز عن المدائني قال قدم البصرة راجز من أهل المدينة فجلس إلى حلقة فيها الشعراء فقال أنا أرجز العرب أنا الذي أقول\n(مروان يعطي وسعيد يمنع ... مروان نبع وسعيد خروع)\nددت أني راميت من أحب في الرجز يدا بيد والله لأنا أرجز من العجاج فليت البصرة جمعت بيني وبينه قال والعجاج حاضر وابنه رؤبة معه فأقبل رؤبة على أبيه فقال قد أنصفك الرجل فأقبل عليه العجاج وقال هأنذا العجاج فهلم وزحف إليه فقال وأي العجاجين أنت قال ما خلتك تعني غيري أنا عبد الله الطويل وكان يكنى بذلك فقال له المدني ما عنيتك ولا أردتك فقال وكيف وقد هتفت بي قال وما في الدنيا عجاج سواك قال علمت قال لكني أعلم وإياه عنيت قال فهذا ابني رؤبة فقال اللهم غفرا ما بيني وبينكما عمل وإنما مرادي غيركما فضحك أهل الحلقة منه وكفا عنه أخبرني أبو خليفة في كتابه عن محمد بن سلام عن يونس قال غدوت يوما أنا وإبراهيم بن محمد العطاردي على رؤبة فخرج إلينا كأنه نسر فقال له ابن نوح أصبحت والله كقولك\n(كالكرز المشدود بين الأوتاد ... ساقط عنه الريش كر الإبراد)\n(فقال له رؤبة والله يا بن نوح ما زلت لك ماقتا فقلت بل أصبحت يا أبا الجحاف كما قال الآخر ... )\n(فأبقين منه وأبقى الطراد ... بطنا خميصا وصلبا سمينا)\nضحك وقال هات حاجتك قال ابن سلام ووقف رؤبة على باب سليمان بن علي يستأذن فقيل له قد أخذ الإذريطوس فقال رؤبة\n(يا منزل الوحي على إدريس ... ومنزل اللعن على إبليس)\n(وخالق الإثنين والخميس ... بارك له في شرب إذريطوس)\nخبرني الحسن بن يحيى قال حماد أخبرني أبي عن الأصمعي قال أنشد رؤبة سلم بن قتيبة في صفة خيل\n(يهوين شتى ويقعن وقفا ... )\nقال له أخطأت يا أبا الجحاف جعلته مقيدا فقال أدنني أيها الأمير ذنب البعير أصفه لك كما يجب أخبرني أبو خليفة في كتابه إلي عن محمد بن سلام عن عبد الرحمن بن محمد عن علقمة الضبي قال خرج شاهين بن عبد الله الثقفي برؤبة إلى أرضه فقعدوا يلعبون بالنرد\nفلما أتوا بالخوان قال رؤبة\n(يا إخوتي جاء الخوان فارفعوا ... حنانة كعابها تقعقع)\n(لم أدر ما ثلاثها والأربع ... )\nال فضحكنا ورفعناها وقدم الطعام أخبرني الحسن بن علي حدثني محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن أبي سعد عن محمد بن عبد الله بن مالك عن أبيه عن يعقوب بن داود قال لقيت الخليل بن أحمد يوما بالبصرة فقال لي يا أبا عبد الله دفنا الشعر واللغة والفصاحة اليوم فقلت وكيف ذاك قال هذا حين انصرفت من جنازة رؤبة صوت\n(لعمري لقد صاح الغراب بينهم ... فأوجع قلبي بالحديث الذي يبدي)\n(فقلت له أفصحت لا طرت بعدها ... بريش فهل للبين ويحك من رد)\nلشعر لقيس بن ذريح وقد تقدمت أخباره والغناء لعمرو بن أبي الكنات ثقيل أول بإطلاق الوتر في مجرى الوسطى","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":3,"spl":"يقعد اللغويين إليه يوم الجمعة","partial":1},
{"id":"b264-6","bab":"الجزء 20","sec":"أخبار عمرو بن أبي الكنات","page":"ج20 ص371","text":"هو عمرو بن عثمان بن أبي الكنات مولى بني جمح مكي مغن محسن موصوف بطيب الصوت من طبقة ابن جامع وأصحابه وفيه يقول الشاعر\n(أحسن فاعلموه غناء ... رجل من بني أبي الكنات)\nله في هذا الشعر غناء مع أبيات قبله لحن ابتداؤه صوت\n(عفت الدار بالهضاب اللواتي ... بسوار فملتقى عرفات)\n(فالحريان أوحشا بعد أنس ... فديار بالربع ذي السلمات)\n(إن بالبين مربعا من سليمى ... فإلى محضرين فالنخلات)\nبعده البيت الأول المذكور الغناء في هذا الشعر لعمرو بن أبي الكنات وطريقته من الرمل\nبالوسطى وقيل إنه لابن سريج وقيل بل لحن ابن سريج غير هذا اللحن وليس فيه البيت الرابع الذي فيه ابن أبي الكنات ويكنى عمرو بن أبي الكنات أبا عثمان وذكر ابن خرداذبه أنه كان يكنى أبا معاذوكان له ابن يغني أيضا يقال له دراج ليس بمشهور ولا كثير الغناء","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":4,"spl":"أخبار عمرو بن أبي الكنات"},
{"id":"b264-7","bab":"الجزء 20","sec":"الرشيد يؤثره على جمع من المغنين","page":"ج20 ص372","text":"فذكر هارون بن محمد بن عبد الملك الزيات في الخبر الذي حكاه عنه من أخباره أن محمدا بن عبد الله المخزومي حدثه قال حدثني محمد بن عبد الله بن فزوة قال قلت لابن جامع يوما هل غلبك أحد من المغنين قط قال نعم كنت ليلة ببغداد إذ جاءني رسول الرشيد يأمرني بالركوب فركبت حتى إذا صرت إلى الدار فإذا أنا بفضل بن الربيع معه زلزل العواد وبرصوما فسلمت وجلست قليلا ثم طلع خادم فقال للفضل هل جاء فقال لا قال فابعث إليه ولم يزل المغنون يدخلون واحدا بعد واحد حتى كنا ستة أو سبعة ثم طلع الخادم فقال هل جاء فقال لا قال قم فابعث في طلبه فقام فغاب غير طويل فإذا هو قد جاء بعمرو بن أبي الكنات فسلم وجلس إلى جنبي فقال لي من هؤلاء قلت مغنون وهذا زلزل وهذا برصوما فقال والله لأغنيك غناء يخرق هذا السقف وتجيبه الحيطان ولا يفهمون منه شيئا قال ثم طلع الخصي فدعا بكراسي وخرجت الجواري فلما جلسن قال الخادم للمغنين شدوا فشدوا عيدانهم ثم قال نعم يا بن جامع فغنيت سبعة أو ثمانية أصوات ثم قال اسكت وليغن إبراهيم الموصلي\nفغنى مثل ذلك أو دونه ثم سكت فلم يزل يمر القوم واحدا واحدا حتى فرغوا ثم قال لابن أبي الكنات غن فقال لزلزل شد طبقتك فشد ثم أخذ العود من يده فجسه حتى وقف على الموضع الذي يريده ثم قال على هذا وابتدأ بصوت أوله ألالا فو الله لقد خيل لي أن الحيطان تجاوبه ثم رجع النغم فيه فطلع الخصي فقال له اسكت لا تتم الصوت فسكت ثم قال يحبس عمرو بن أبي الكنات وينصرف باقي المغنين فقمنا بأكسف حال وأسوإبال لا والله ما زال كل واحد منا يسأل صاحبه عن كل شعر يرويه من الغناء الذي أوله ألالا طمعا في أن يعرفه أو يوافق غناءه فما عرفه منا أحد وبات عمرو ليلته عند الرشيد وانصرف من عنده بجوائز وصلات وطرف سنية قال هارون وأخبرني محمد بن عبد الله عن موسى بن أبي المهاجر قال خرج ابن جامع وابن أبي الكنات حين دفعا من عرفة حتى إذا كانا بين المأزمين جلس عمرو على طرف الجبل ثم اندفع يغني فوقف القطارات وركب الناس بعضهم بعضا حتى صاحوا واستغاثوا يا هذا الله الله اسكت عنا يجز الناس فضبط إسماعيل بن جامع بيده على فيه حتى مضى الناس إلى مزدلفة قال هارون وحدثني عبد الرحمن بن سليمان عن علي بن أبي الجهم قال حدثني من أثق به قال واقفت ابن أبي الكنات المديني على جسر بغداد أيام الرشيد فحدثته بحديث اتصل بي عن ابن عائشة أنه فعله أيام هشام وهو أن بعض\nأصحابنا حدثني قال وقف ابن عائشة في الموسم فمر به بعض أصحابه فقال له ما تعمل فقال إني لأعرف رجلا لو تكلم لحبس الناس فلم يذهب أحد ولم يجيء فقلت له ومن هذا الرجل قال أنا ثم اندفع يغني صوت\n(جرت سنحا فقلت لها أجيزي ... نوى مشمولة فمتى اللقاء)\n(بنفسي من تذكره سقام ... أعالجه ومطلبه عناء)\nال فحبس الناس واضطربت المحامل ومدت الإبل أعناقها وكادت الفتنة تقع فأتي به هشام فقال يا عدو الله أردت أن تفتن الناس فأمسك عنه وكان تياها فقال له هشام أرفق بتيهك فقال ابن عائشة حق لمن كانت هذه قدرته على القلوب أن يكون تياها فضحك وأطلقه قال فبرق ابن أبي الكنات وكان معجبا بنفسه وقال أنا أفعل كما فعل وقدرتي على القلوب أكثر من قدرته كانت ثم اندفع فغنى في هذا الصوت ونحن على جسر بغداد وكان إذ ذاك على دجلة ثلاثة جسور معقودة فانقطعت الطرق وامتلأت الجسور بالناس وازدحموا عليها واضطربت حتى خيف عليها أن تنقطع لثقل من عليها من الناس فأخذ فأتي به الرشيد فقال يا عدو الله أردت أن تفتن الناس فقال لا والله يا أمير المؤمنين ولكنه بلغني أن ابن عائشة فعل مثل هذا في أيام هشام فأحببت أن يكون في أيامك مثله فأعجب من قوله ذلك وأمر له بمال وأمره أن يغني فسمع شيئا لم يسمع مثله\nفاحتسبه عنده شهرا يستزيده في كل يوم استأذنه فيه في الإنصراف يوما آخر حتى تم له شهر فقال هذا المخبر عنه وكان ابن أبي الكنات كثير الغشيان لي فلما أبطأ توهمته قد قتل فصار إلي بعد شهر بأموال جسيمة وحدثني بما جرى بينه وبين الرشيد","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":5,"spl":"الرشيد يؤثره على جمع من المغنين"},
{"id":"b264-8","bab":"الجزء 20","sec":"غناؤه يسمع على ثلاثة أميال","page":"ج20 ص375","text":"قال هارون وأخبرني محمد بن عبد الله المخزومي عن عثمان بن موسى مولانا قال كنا يوما باللاحجة ومعنا عمرو بن أبي الكنات ونحن على شرابنا إذ قال لنا قبل طلوع الشمس من تحبون أن يجيئكم قلنا منصور الحجبي فقال أمهلوا حتى يكون الوقت الذي ينحدر فيه إلى سوق البقر فمكثنا ساعة ثم اندفع يغني\n(أحسن الناس فاعلموه غناء ... رجل من بني أبي الكنات)\n(عفت الدار بالهضاب اللواتي ... بسوار فملتقى عرفات)\nلم نلبث أن رأينا منصورا من بعد قد أقبل يركض دابته نحونا فلما جلس إلينا قلنا له من أين علمت بنا قال سمعت صوت عمرو يغني كذا وكذا وأنا في سوق البقر فخرجت أركض دابتي حتى صرت إليكم قال وبيننا وبين ذلك الموضع ثلاثة أميال قال هارون وأخبرني محمد بن عبد الله قال أخبرني يحيى بن يعلى بن سعيد قال بينا أنا ليلة في منزلي في الرمضة أسفل مكة إذ سمعت صوت عمرو بن\nأبي الكنات كأنه معي فأمرت الغلام فأسرج لي دابتي وخرجت أريده فلم أزل أتبع الصوت حتى وجدته جالسا على الكثيب العارض ببطن عرنة يغني صوت\n(خذي العفو مني تستديمي مودتي ... ولا تنطقي في سورتي حين أغضب)\n(ولا تنقريني نقرة الدف مرة ... فإنك لا تدرين كيف المغيب)\n(فإني وجدت الحب في الصدر والأذى ... إذا اجتمعا لم يلبث الحب يذهب)\nعروضه من الطويل ولحنه من الثقيل الثاني بالوسطى من رواية إسحاق والشعر لأسماء بن خارجة الفزاري وقد قيل إنه لأبي الأسود الدؤلي وليس ذلك بصحيح والغناء لإبراهيم الموصلي وفيه لحن قديم للغريض من رواية حماد عن أبيه","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":6,"spl":"غناؤه يسمع على ثلاثة أميال — أسماء بن خارجة وابنته هند"},
{"id":"b264-9","bab":"الجزء 20","sec":"أسماء بن خارجة وابنته هند","page":"ج20 ص377","text":"أخبرني اليزيدي عن أحمد بن زهير عن الزبير بن بكار قال زوج أسماء بن خارجة الفزاري بنته هندا من الحجاج بن يوسف فلما كانت ليلة أراد البناء بها قال لها أسماء بن خارجة يا بنية إن الأمهات يؤدبن البنات وإن أمك هلكت وأنت صغيرة فعليك بأطيب الطيب الماء وأحسن الحسن الكحل وإياك وكثرة المعاتبة فإنها قطيعة للود وإياك والغيرة فإنها مفتاح الطلاق وكوني لزوجك أمة يكن لك عبدا واعلمي أني القائل لأمك\n(خذي العفو مني تستديمي مودتي ... )\nذكر الأبيات قال وكانت هند امرأة مجربة قد تزوجها جماعة من أمراء العراق فقبلت من أبيها وصيته وكان الحجاج يصفها في مجلسه بكل خير وفيها يقول بعض الشعراء يخاطب أباها\n(جزاك الله يا أسماء خيرا ... كما أرضيت فيشلة الأمير)\n(بصدغ قد يفوح المسك منه ... عليه مثل كركرة البعير)\n(إذا أخذ الأمير بمشعبيها ... سمعت لها أزيزا كالصرير)\n(إذا لقحت بأرواح تراها ... تجيد الرهز من فوق السرير)\nال مؤلف هذا الكتاب الشعر لعقيبة الأسدي أخبرني الجوهري وحبيب المهلبي عن ابن شبة قال لما قدم الحجاج الكوفة أشار عليه محمد بن عمير بن عطارد أن يخطب إلى أسماء ابنته هند فخطبها فزوجه أسماء ابنته فأقبل عليه محمد متمثلا يقول\n(أمن حذر الهزال نكحت عبدا ... فصهر العبد أدنى للهزال)\nاحتملها عليه أسماء وسكت عن جوابه ثم أقبل على الحجاج يوما وهند جالسة فقال ما يمنعك من الخطبة إلى محمد بن عمير ابنته فإن من شأنها كيت وكيت فقال أتقول هذا وهند تسمع فقال موافقتك أحب إلي\nمن رضا هند فخطبها إلى محمد بن عمير فزوجه إياها فقال أسماء لمحمد بن عمير وضرب بيده على منكبه\n(دونك ما أسديته يا بن حاجب ... سواء كعين الديك أوقذة النسر)\n(بقولك للحجاج إن كنت ناكحا ... فلا تعد هندا من نساء بني بدر)\n(فإن أباها لا يرى أن خاطبا ... كفاء له إلا المتوج من فهر)\n(فزوجتها الحجاج لا متكارها ... ولا راغبا عنه ونعم أخو الصهر)\n(أردت ضراري فاعتمدت مسرتي ... وقد يحسن الإنسان من حيث لا يدري)\n(فإن ترها عارا فقد جئت مثلها ... وإن ترها فخرا فهل لك من شكر)","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":6,"spl":"غناؤه يسمع على ثلاثة أميال — أسماء بن خارجة وابنته هند","partialRef":{"sid":"b264-8","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b264-10","bab":"الجزء 20","sec":"هند أحبت عبيد الله بن زياد وكان أبا عذرها","page":"ج20 ص379","text":"قال المدائني حدثني الحرمازي عن الوليد بن هشام القحذمي وكان كاتب خالدا القسري ويوسف بن عمر أن هندا بنت أسماء كانت تحت\nعبيد الله بن زياد وكان أبا عذرها فلما قتل وكانت معه لبست قباء وتقلدت سيفا وركبت فرسا لعبيد الله كان يقال لها الكامل وخرجت حتى دخلت الكوفة ليس معها دليل ثم كانت بعد ذلك أشد خلق الله جزعا عليه ولقد قالت يوما إني لأشتاق إلى القيامة لأرى وجه عبيد الله بن زياد فلما قدم بشر بن مروان الكوفة دل عليها فخطبها فزوجها فولدت له عبد الملك بن بشر وكان ينال من الشراب ويكتم ذلك وكان إذا صلى العصر خلا من ناحية من داره ليس معه إلا أعين مولاه صاحب حمام أعين بالكوفة وأخذ في شأنه فلم تزل هند تتجسس خبره حتى عرفته فبعثت مولى لها فأحضرها أطيب شراب وأحده وأشده وأرقه وأصفاه وأحضرت له طعاما علمت أنه يشتهيه وأرسلت إلى أخويها مالك وعيينة فأتياها وبعثت إلى بشر وأعتلت عليه بعلة فجاءها فوضعت بين يديه ما أعدته فأكل وشرب وجعل مالك يسقيه وعيينة يحدثه وهند تريه وجهها فلم يزل في ذلك حتى أمسى فقال هل عندكم من هذا شيء نعود عليه غدا فقالت هذا دائم لك ما أردته فلزمها وبقي أعين يتبع الديار بوجهه ولا يرى بشرا إلا أن يبحث عن أمره فعرفه وعلم أنه ليس فيه حظ بعدها قال ومات عنها بشر فلم تجزع عليه فقال الفرزدق في ذلك\n(فان تك لا هند بكته فقد بكت ... عليه الثريا في كواكبها الزهر)","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":7,"spl":"هند أحبت عبيد الله بن زياد وكان أبا عذرها"},
{"id":"b264-11","bab":"الجزء 20","sec":"الحجاج يخلف بشرا في تزوجها","page":"ج20 ص381","text":"ثم خلف عليها الحجاج وكان السبب في ذلك فيما ذكره المدائني عن الحرمازي عن القحذمي وأخبرني به من ها هنا أحمد بن عبد العزيز عن ابن شبة عن عثمان بن عبد الوهاب عن عبد الحميد الثقفي قالا كان السبب في ذلك أنه بعث أبا بردة بن أبي موسى الأشعري وهو قاضيه إلى أسماء يقول له إن قبيحا بي مع بلاء أمير المؤمنين عندي أن أقيم بموضع فيه ابنا أخيه بشر لا أضمهما إلي وأتولى منهما مثل ما أتولى من ولدي فاسأل هندا أن تطيب عنهما وقال عمر بن شبة في خبره وأعلمها أنه لابد من التفرقة بينها وبينهما حتى أؤدبهما قال أبو بردة فاستأذنت فأذن لي وهو يأكل وهند معه فما رأيت وجها ولا كفا ولا ذراعا أحسن من وجهها وكفها وذراعها وجعلت تتحفني وتضع بين يدي قال أبو زيد في خبره فدعاني إلى الطعام فلم أفعل وجعلت تعبث بي وتضحك فقلت أما والله لو علمت ما جئت له لبكيت فأمسك يدها عن الطعام فقال أسماء قد منعتها الأكل فقل ما جئت له فلما بلغت أسماء ما أرسلت به بكت فلم أر والله دموعا قط سائلة من محاجر أحسن من دموعها على محاجرها ثم قالت نعم أرسل بهما إليه فلا أحد أحق بتأديبهما منه وقال أسماء إنما عبد الملك ثمرة قلوبنا يعني عبد الملك بن بشر وقد أنسنا به ولكن أمر الأمير طاعة فأتيت الحجاج فأعلمته جوابها وهيئتها فقال ارجع فاخطبها علي فرجعت وهما على حالهما فلما دخلت قلت إني جئتك بغير الرسالة الأولى قال اذكر ما أحببت قلت قد جئت خاطبا قال أعلى نفسك فما بنا عنك رغبة قلت لا على من هو خير لها\nمني وأعلمته ما أمرني به الحجاج فقال ها هي تسمع ما أديت فسكتت فقال أسماء قد رضيت وقد زوجتها إياه فقال أبو زيد في حديثه فلما زوجها أبوها قامت مبادرة وعليها مطرف ولم تستقل قائمة من ثقل عجيزتها حتى انثنت ومالت لأحد شقيها من شحمها فانصرفت بذلك إلى الحجاج فبعث إليها بمائة ألف درهم وعشرين تختا من ثياب وقال يا أبا بردة إني أحب أن تسلمها إليها ففعلت ذلك وأرسلت إلي من المال بعشرين ألفا ومن الثياب تختين فقلت ما أقبل شيئا حتى أستطلع رأي الأمير ثم انصرفت إليه فأعلمته فأمرني بقيضة ووصلني بمثله وقال أبو زيد في حديثه فأرسل إليها بثلاثين غلاما مع كل غلام عشرة آلاف درهم وثلاثين جارية مع كل جارية تخت من ثياب وأمر لي بثلاثين ألفا وثيابا لم يذكر عددها فلما وصل ذلك إلى هند أمرت بمثل ما أمر لي به الحجاج فأبيت قبوله وقلت ليس الحجاج ممن يتعرض له بمثل هذا وأتيت الحجاج فأخبرته فقال قد أحسنت وأضعف الله لك ذلك وأمر له بستين ألفا وبضعف تلك الثياب وكان أول ما أصبته مع الحجاج وأرسل إليها إني أكره أن أبيت خلوا ولي زوجة فقالت وما احتباس امرأة عن زوجها وقد ملكها وآتاها كرامته وصداقها فأصلحت من شأنها وأتته ليلا قال المدائني فسمعت أن ابن كناسة ذكر أن رجلا من أهل العلم حدثه عن امرأة من أهله قالت كنت فيمن زفها فدخلنا عليه وهو في بيت عظيم في أقصاه ستارة وهو دون الستارة على فرشه فلما أن دخلت سلمت فأومأ إليها بقضيب كان في يده فجلست عند رجليه ومكثت ساعة وهو لا\nيتكلم ونحن وقوف فضربت بيدها على فخذه ثم قالت ألم تبعد من سوء الخلق قال فتبسم وأقبل عليها واستوى جالسا فدعونا له وخرجنا وأرخيت الستور","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":8,"spl":"الحجاج يخلف بشرا في تزوجها"},
{"id":"b264-12","bab":"الجزء 20","sec":"سبب تطليق الحجاج لها","page":"ج20 ص383","text":"قال ثم قدم الحجاج البصرة فحملها معه فلما بنى قصره الذي دون المحدثة الذي يقول له قصر الحجاج اليوم قال لها هل رأيت قط أحسن من هذا القصر قالت ما أحسنه قال اصدقيني قالت أما إذ أبيت فوالله ما رأيت أحسن من القصر الأحمر وكان فيه عبيد الله بن زياد وكان دار الإمارة بالبصرة وكان ابن زياد بناه بطين أحمر فطلق هندا غضبا بما قالته وبعث إلى القصر فهدمه وبناه بلبن ثم تعهده صالح بن عبد الرحمن في خلافة سليمان بن عبد الملك فبناه بالآجر ثم هدم بعد ذلك فأدخل في المسجد الجامع قال القحذمي عن محمد بن عبد الرحمن بن الحارث بن هشام المخزومي فخرجنا يوما نعود عبد الملك بن بشر فسلمنا عليه وعدناه معه ثم خرجنا وتخلف الحجاج فوقفنا ننتظره فلما خرج التفت فرآني فقال يا محمد ويحك رأيت هندا الساعة فما رأيتها قط أجمل ولا أشب منها حين رأيتها وما أنا بممس حتى أراجعها فقلت أصلح الله الأمير امرأة طلقتها\nعلى عتب يرى الناس أن نفسك تتبعها وتكون لها الحجة عليك قال صدقت الصبر أحجى قال محمد والله ما كان مني نظرا ولا نصيحة ولكني أنفت لرجل من قريش أن تداس أمه في كل وقت أخبرني الحسين بن يحيى عن حماد عن أبيه عن المدائني عن جويرية بن أسماء عن عمه قال حججت فإني لفي رفقة من قومي إذ نزلنا منزلا ومعنا امرأة فنامت وانتبهت وحية مطوية عليها قد جمعت رأسها وذنبها بين ثدييها فهالنا ذلك وارتحلنا فلم تزل منطوية عليها لا تضيرها حتى دخلنا الحرم فانسابت فدخلنا مكة وقضينا نسكنا فرآها الغريض فقال أي شقية ما فعلت حيتك فقالت في النار قال ستعلمين من أهل النار ولم أفهم ما أراد وظننت أنه مازحها واشتقت إلى غنائه ولم يكن بيني وبينه ما يوجب ذلك فأتيت بعض أهله فسألته ذلك فقال نعم فوجه إليه أن اخرج بنا إلى موضع كذا وقال لي اركب بنا فركبنا حتى سرنا قدر ميل فإذا الغريض هناك فنزلنا فإذا طعام معد وموضع حسن فأكلنا وشربنا ثم قال يا أبا يزيد هات بعض طرائفك فاندفع يغني ويوقع بقضيب\n(مرضت فلم تحفل علي جنوب ... وأدنفت والممشى إلي قريب)\n(فلا يبعد الله الشباب وقولنا ... إذا ما صبونا صبوة سنتوب)\nلقد سمعنا شيئا ظننت أن الجبال التي حولي تنطق معه شجا صوت وحسن غناء وقال لي أتحب أن يزيدك فقلت إي والله فقال هذا ضيفك وضيفنا وقد رغب إليك وإلينا فأسعفه بما يريد فاندفع يغني بشعر مجنون بني عامر\nإنه لمجنون بني عامر ويقال إنه لعمر بن أبي ربيعة والغناء لابن سريج خفيف رمل بالوسطى عن عمرو بن بانة وفيه للغريض ثاني ثقيل بالوسطى وفي الثاني والأول خفيف ثقيل أول بالبنصر مجهول أخبرني الحرمي عن الزبير عن محمد بن الضحاك عن أبيه قال قال أبو دهبل\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\n(هبوني امرأ منكم أضل بعيره ... له ذمة إن الذمام كبير)\n(وللصاحب المتروك أعظم حرمة ... على صاحب من أن يضل بعير)\nال الزبير وقال عمي هذه الأبيات لمجنون بني عامر قال أحمد بن الحارث الخراز عن المدائني عن أبي محمد الشيباني قال قال عبد الملك بن مروان لعمر بن أبي ربيعة أنت القائل\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\nال نعم قال فبئس المحب أنت تركتها وبينها وبينك غدوة قال يا أمير المؤمنين إنها من غدوات سليمان غدوها شهر ورواحها شهر أخبرني اليزيدي عن أحمد بن يحيى وابن زهير قال حدثني عمر بن القاسم بن المعتمر الزهري قال قلت لأبي السائب المخزومي أما أحسن الذي يقول\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\n(هبوني امرأ منكم أضل بعيره ... له ذمة إن الذمام كبير)\n(وللصاحب المتروك أعظم حرمة ... على صاحب من أن يضل بعير)\nمنطوية عليها فلم ألبث أن صغرت الحية فإذا الوادي يسيل علينا حيات فنهشنها حتى بقيت عظاما فطال تعجبنا من ذلك وأرينا ما لم نر مثله قط فقلت لجارية كانت معها ويحك أخبرينا عن هذه المرأة قالت نعم أثكلت ثلاث مرات كل مرة تلد ولدا فإذا وضعته سجرت التنور ثم ألقته فذكرت قول الغريض حين سألها عن الحية فقالت في النار فقال ستعلمين من في النار","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":9,"spl":"سبب تطليق الحجاج لها"},
{"id":"b264-13","bab":"الجزء 20","sec":"نسبة ما في هذه الأصوات من الغناء","page":"ج20 ص386","text":"فمنها صوت\n(مرضت فلم تحفل علي جنوب ... وأدنفت والممشى إلي قريب)\n(فلا يبعد الله الشباب وقولنا ... إذا ما صبونا صبوة سنتوب)\nعروضه من الطويل الشعر لحميد بن ثور الهلالي والغناء للغريض من رواية حماد عن أبيه وفيه لعلويه ثقيل أول بالوسطى على مذهب إسحاق من رواية عمرو بن بانة ومنها صوت\n(عفا الله عن ليلى الغداة فإنها ... إذا وليت حكما علي تجور)\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\nروضه من الطويل والشعر يقال لأبي دهبل الجمحي ويقال\nإنه لمجنون بني عامر ويقال إنه لعمر بن أبي ربيعة والغناء لابن سريج خفيف رمل بالوسطى عن عمرو بن بانة وفيه للغريض ثاني ثقيل بالوسطى وفي الثاني والأول خفيف ثقيل أول بالبنصر مجهول أخبرني الحرمي عن الزبير عن محمد بن الضحاك عن أبيه قال قال أبو دهبل\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\n(هبوني امرأ منكم أضل بعيره ... له ذمة إن الذمام كبير)\n(وللصاحب المتروك أعظم حرمة ... على صاحب من أن يضل بعير)\nال الزبير وقال عمي هذه الأبيات لمجنون بني عامر قال أحمد بن الحارث الخراز عن المدائني عن أبي محمد الشيباني قال قال عبد الملك بن مروان لعمر بن أبي ربيعة أنت القائل\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\nال نعم قال فبئس المحب أنت تركتها وبينها وبينك غدوة قال يا أمير المؤمنين إنها من غدوات سليمان غدوها شهر ورواحها شهر أخبرني اليزيدي عن أحمد بن يحيى وابن زهير قال حدثني عمر بن القاسم بن المعتمر الزهري قال قلت لأبي السائب المخزومي أما أحسن الذي يقول\n(أأترك ليلى ليس بيني وبينها ... سوى ليلة إني إذا لصبور)\n(هبوني امرأ منكم أضل بعيره ... له ذمة إن الذمام كبير)\n(وللصاحب المتروك أعظم حرمة ... على صاحب من أن يضل بعير)\nفقال بأبي أنت كنت والله أجنبك وتثقل علي فأنا الآن أحبك وتخف علي حيث تعرف هذا صوت\n(من الخفرات لم تفضح أخاها ... ولم ترفع لوالدها شنارا)\n(كأن مجامع الأرداف منها ... نقا درجت عليه الريح هارا)\n(يعاف وصال ذات البذل قلبي ... ويتبع الممنعة النوارا)\nلخفرة الحيية والخفر الحياء والشنار العار والنقا الكثيب من الرمل درجت عليه الريح مرت هار تهافت وتداعى قال الله تبارك وتعالى ( على شفا جرف هار\nويعاف يكره والنوار الصعبة الممتنعة الشديدة الإباء عروضه من الوافر الشعر للسليك بن السلكة والغناء لابن سريج رمل بالسبابة في مجرى البنصر عن إسحاق وفيه لابن الهربذ لحن من رواية بذل ولم يذكر طريقته وفيه لابن طنبورة لحن ذكره إبراهيم في كتابه ولم يجنسه","topic":"أخبار رؤبة ونسبه","topicNo":264,"sp":10,"spl":"نسبة ما في هذه الأصوات من الغناء"},
{"id":"b265-1","bab":"الجزء 20","sec":"أخبار السليك بن السلكة ونسبه","page":"ج20 ص389","text":"هو السليك بن عمرو وقيل ابن عمير بن يثربي أحد بني مقاعس وهو الحارث بن عمرو بن كعب بن سعد بن زيد مناة بن تميم والسلكة أمه وهي أمة سوداء وهو أحد صعاليك العرب العدائين الذين كانوا لا يلحقون ولا تعلق بهم الخيل إذا عدوا وهم السليك بن السلكة و الشنفري وتأبط شرا وعمرو بن براق ونفيل بن براقة وأخبارهم تذكر على تواليها ها هنا إن شاء الله تعالى في أشعار لهم يغنى فيها لتتصل أحاديثهم فأما السليك فأخبرني بخبره الأخفش عن السكري عن ابن حبيب عن ابن الأعرابي قال وقرىء لي خبره وشعره على محمد بن الحسن الأحول عن الأثرم\nعن أبي عبيدة أخبرني ببعضه اليزيدي عن عمه عن ابن حبيب عن ابن الأعرابي عن المفضل وقد جمعت رواياتهم فإذا اختلفت نسبت كل مروي إلى راويه قال أبو عبيدة حدثني المنتجع بن نبهان قال كان السليك بن عمير السعدي إذا كان الشتاء استودع ببيض النعام ماء السماء ثم دفنه فإذا كان الصيف وانقطعت إغارة الخيل أغار وكان أدل من قطاة يجيء حتى يقف على البيضة وكان لا يغير على مضر وإنما يغير على اليمن فإذا لم يمكنه ذلك أغار على ربيعة وقال المفضل في روايته وكان السليك من أشد رجال العرب وأنكرهم وأشعرهم وكانت العرب تدعوه سليك المقانب وكان أدل الناس بالأرض وأعلمهم بمسالكها وأشدهم عدوا على رجليه لا تعلق به الخيل وكان يقول اللهم إنك تهيىء ما شئت لما شئت إذا شئت اللهم إني لو كنت ضعيفا كنت عبدا ولو كنت امرأة كنت أمة اللهم إني أعوذ بك من الخيبة فأما الهيبة فلا هيبة","topic":"أخبار السليك بن السلكة ونسبه","topicNo":265,"sp":0,"spl":"أخبار السليك بن السلكة ونسبه"},
{"id":"b265-2","bab":"الجزء 20","sec":"من أنباء غارات السليك الصعلوك","page":"ج20 ص390","text":"فذكروا أنه أ ملق حتى لم يبق له شيء فخرج على رجليه رجاء أن يصيب غرة من بعض من يمر به فيذهب بإبله حتى أمسى في ليلة من ليالي الشتاء باردة مقمرة فاشتمل الصماء ثم نام واشتمال الصماء أن يرد فضلة ثوبه على عضده اليمنى ثم ينام عليها\nفبينا هو نائم إذ جثم رجل فقعد على جنبه فقال استأسر فرفع السليك إليه رأسه وقال الليل طويل وأنت مقمر فأرسلها مثلا فجعل الرجل يلهزه ويقول يا خبيث استأسر فلما آذاه بذلك أخرج السليك يده فضم الرجل إليه ضمة ضرط منها وهو فوقه فقال السليك أضرطا وأنت الأعلى فأرسلها مثلا ثم قال من أنت فقال أنا رجل افتقرت فقلت لأخرجن فلا أرجع إلى أهلي حتى أستغني فآتيهم وأنا غني قال انطلق معي فانطلقا فوجد رجلا قصته مثل قصتهما فاصطحبوا جميعا حتى أتوا الجوف جوف مراد فلما أشرفوا عليه إذا فيه نعم قد ملأ كل شيء من كثرته فهابوا أن يغيروا فيطردوا بعضها فيلحقهم الطلب فقال لهما سليك كونا قريبا مني حتى آتي الرعاء فأعلم لكما علم الحي أقريب أم بعيد فإن كانوا قريبا رجعت إليكما وإن كانوا بعيدا قلت لكما قولا أومىء إليكما به فأغيرا فانطلق حتى أتى الرعاء فلم يزل يستنطقهم حتى أخبروه بمكان الحي فإذا هم بعيد إن طلبوا لم يدركوا فقال السليك للرعاء ألا أغنيكم فقالوا بلى غننا فرفع صوته وغنى\n(يا صاحبي ألا لا حي بالوادي ... سوى عبيد وآم بين أذواد)\n(أتنظران قريبا ريث غفلتهم ... أم تغدوان فإن الريح للغادي)\nلما سمعا ذلك أتيا السليك فأطردوا الإبل فذهبوا بها ولم يبلغ الصريخ الحي حتى فاتوهم بالإبل قال المفضل وزعموا أن سليكا خرج ومعه رجلان من بني الحارث بن امرىء القيس بن زيد مناة بن تميم لهما عمرو وعاصم وهو يريد الغارة\nفمر على حي بني شيبان في ربيع و الناس مخصبون في شعية فيها ضباب ومطر فإذا هو ببيت قد انفرد من البيوت وقد أمسى فقال لأصحابه كونوا بمكان كذا حتى آتي أهل هذا البيت فلعلي أن أصيب لكم خيرا أو آتيكم بطعام قالوا افعل فانطلق وقد أمسى وجن عليه الليل فإذا البيت بيت رويم وهو جد حوشب بن يزيد بن رويم وإذا الشيخ وامرأته بفناء البيت فأتى السليك البيت من مؤخره فدخله فلم يلبث أن راح ابنه بإبله فلما أراحها غضب الشيخ وقال لابنه هلا عشيتها ساعة من الليل فقال له ابنه إنها أبت العشاء فقال العاشية تهيج الآبية فأرسلها مثلا ثم غضب الشيخ ونفض في وجهها فوجعت إلى مراتعها ومعها الشيخ حتى مالت بأدنى روضة فرتعت وجلس الشيخ عندها لتتعشى وغطى وجهه بثوبه من البرد وتبعه سليك فلما وجد الشيخ مغترا ختله من ورائه فضربه فأطار رأسه وصاح بالإبل فطردها فلم يشعر صاحباه وقد ساء ظنهما وتخوفا عليه حتى إذا هما بالسليك يطردها فطرداها معه وقال سليك في ذلك\n(وعاشية راحت بطانا ذعرتها ... بسوط قتيل وسطها يتسيف)\n(كأن عليه لون برد محبر ... إذا ما أتاه صارخ يتلهف)\n(فبات لها أهل خلاء فناؤهم ... ومرت بهم طير فلم يتعيفوا)\n(وباتوا يظنون الظنون وصحبتي ... إذا ما علوا نشزا أهلوا وأوجفوا)\n(وما نلتها حتى تصعلكت حقبة ... وكدت لأسباب المنية أعرف)\n(وحتى رأيت الجوع بالصيف ضرني ... إذا قمت تغشاني ظلال فأسدف)\nقال الأثرم في روايته عن أبي عبيدة خرج سليك في الشهر الحرام حتى أتى عكاظ فلما اجتمع الناس ألقى ثيابه ثم خرج متفضلا مترجلا فجعل يطوف الناس ويقول من يصف لي منازل قومه وأصف له منازل قومي فلقيه قيس بن مكشوح المرادي فقال أنا أصف لك منازل قومي وصف لي منازل قومك فتواقفا وتعاهدا ألا يتكاذبا قال قيس بن المكشوح خذ بين مهب الجنوب والصبا ثم سر حتى لا تدري أين ظل الشجرة فإذا انقطعت المياه فسر أربعا حتى تبدو لك رملة وقف بينها الطريق فإنك ترد على قومي مراد وخثعم فقال السليك خذ بين مطلع وسهيل ويد الجوزاء اليسرى العاقد لها من أفق السماء فثم منازل قومي بني سعيد بن زيد مناة فانطلق قيس إلى قومه فأخبرهم الخبر فقال أبوه المكشوح ثكلتك أمك هل تدري من لقيت قال رجلا فضلا كأنما خرج من أهله فقال هو والله سليك بن سعد","topic":"أخبار السليك بن السلكة ونسبه","topicNo":265,"sp":1,"spl":"من أنباء غارات السليك الصعلوك"},
{"id":"b265-3","bab":"الجزء 20","sec":"من أنباء غارات السليك الصعلوك","page":"ج20 ص390","text":"فاستعلق واستعوى السليك قومه فخرج أحماس من بني سعد وبني عبد شمس وكان في الربيع يعمد إلى بيض النعام فيملؤه من الماء ويدفنه في طريق اليمن في المفاوز قال فإذا غزا في الصيف مر به فاستثاره فمر بأصحابه حتى إذا انقطعت عنهم المياه قالوا يا سليك أهلكتنا ويحك قال قد بلغتم الماء ما أقربكم منه حتى إذا انتهى إلى قريب من المكان الذي خبأ الماء فيه طلبه فلم يجده وجعل يتردد في طلبه فقال بعض أصحابه لبعض أين يقودكم هذا العبد قد والله هلكتم وسمع ذلك ثم أصاب الماء بعد ما ساء ظنهم فهم السليك بقتل بعضهم ثم أمسك فانصرفت عنه بنو عبد شمس في طوائف من بني سعد قال ومضى السليك في بني مقاعس ومعه رجل من بني حرام يقال له صرد فلما رأى أصحابه قد انصرفوا بكى ومضى به السليك حتى إذا دنوا من بلاد خثعم ضلت ناقة صرد في جوف الليل فخرج في طلبها فأصابه أناس حين أصبح فإذا هم مراد وخثعم فأسروه ولحقه السليك فاقتتلوا قتالا شديدا وكان أول من لقيه قيس بن مكشوح فأسره السليك بعد أن ضربه ضربة أشرفت على نفسه وأصاب من نعمهم ما عجز عنه هو وأصحابه وأصاب أم الحارث بنت عوف بن يربوع الخثعمية يومئذ واستنفذ صرد من أيدي خثعم ثم انصرف مسرعا فلحق بأصحابه الذين انصرفوا عنه قبل أن يصلوا إلى الحي وهم أكثر من الذين شهدوا معه فقسمها بينهم على سهام الذين شهدوا وقال السليك في ذلك\n(بكى صرد لما رأى الحيض أعرضت ... مهامة رمل دونهم وسهوب)\n(وخوفه ريب الزمان وفقره ... بلاد عدو حاضر وجدوب)\n(ونأي بعيد عن بلاد مقاعس ... وأن مخاريق الأمور تريب)\n(فقلت له لا تبك عينك إنها ... قضية ما يقضى لها فتثوب)\n(سيكفيك فقد الحي لحم مغرض ... وماء قدور في الجفان مشوب)\n(ألم تر أن الدهر لونان لونه ... وطوران بشر مرة وكذوب)\n(فما خير من لا يرتجي خير أوبة ... ويخشى عليه مرية وحروب)\n(رددت عليه نفسه فكأنما ... تلاقى عليه منسر وسروب)\n(فما ذر قرن الشمس حتى أريته ... قصار المنايا والغبار يثوب)\n(وضاربت عنه القوم حتى كأنما ... يصعد في آثارهم ويصوب)\n(وقلت له خذ هجمة حميرية ... وأهلا ولا يبعد عليك شروب)\n(وليلة جابان كررت عليهم ... على ساعة فيها الإياب حبيب)\n(عشية كرت بالحرامي ناقة ... بحي هلا تدعى به فجيب)\n(فضاربت أولى الخيل حتى كأنما ... أميل عليها أيدع وصبيب)\nلأيدع دم الأخوين والصبيب الحناء","topic":"أخبار السليك بن السلكة ونسبه","topicNo":265,"sp":2,"spl":"من أنباء غارات السليك الصعلوك"},
{"id":"b265-4","bab":"الجزء 20","sec":"السليك القادر على الإحتمال","page":"ج20 ص395","text":"قال أبو عبيدة وبلغني أن السليك بن السلكة رأته طلائع جيش لبكر بن\nوائل وكانوا جازوا منحدرين ليغيروا على بني تميم ولا يعلم بهم أحد فقالوا إن علم السليك بنا أنذر قومه فبعثوا إليه فارسين على جوادين فلما هايجاه خرج يمحص كأنه ظبي وطارداه سحابة يومه ثم قالا إذا كان الليل أعيا ثم سقط أو قصر عن العدو فنأخذه فلما أصبحنا وجدا أثره قد عثر بأصل شجرة فنزعها فندرت قوسه فانحطمت فوجدا قصدة منها قد ارتزت بالأرض فقالا ما له أخزاه الله ما أشده وهما بالرجوع ثم قالا لعل هذا كان من أول الليل ثم فتر فتبعاه فإذا أثره متفاج قد بال فرغا في الأرض وخذها فقالا ما له قاتله الله ما أشد متنه والله لا نتبعه أبدا فانصرفا ونمى إلى قومه وأنذرهم فكذبوه لبعد الغاية فأنشأ يقول\n(يكذبني العمران عمرو بن جندب ... وعمرو بن سعد والمكذب أكذب)\n(لعمرك ما ساعيت من سعي عاجز ... ولا أنا بالواني ففيم أكذب)\n(ثكلتكما إن لم أكن قد رأيتها ... كراديس يهديها إلى الحي موكب)\n(كراديس فيها الحوفزان وقومه ... فوارس همام متى يدع يركبوا)\nعني الحوفزان بن شريك الشيباني\n(تفاقدتم هل أنكرن مغيرة ... مع الصبح يهدين أشقر مغرب)\nتفاقدتم يدعو عليهم بالتفاقد\nقال وجاء الجيش فأغاروا على جمعهم قال وكان يقال للسليك سليك المقانب وقد قال في ذلك فرار الأسدي وكان قد وجد قوما يتحدثون إلى امرأته من بني عمها فعقرها بالسيف فطلبه بنو عمها فهرب ولم يقدروا عليه فقال في ذلك\n(لزوار ليلى منكم آل برثن ... على الهول أمضى من سليك المقانب)\n(يزورونها ولا أزور نساءهم ... ألهفى لأولاد الإماء الحواطب)\nقال أبو عبيدة أغار السليك على بني عوار بطن من بني مالك بن ضبيعة فلم يظفر منهم بفائدة وأرادوا مساورته فقال شيخ منهم إنه إذا عدا لم يتعلق به فدعوه حتى يرد الماء فإذا شرب وثقل لم يستطع العدو وظفرتم به فأمهلوه حتى ورد الماء وشرب ثم بادروه فلما علم أنه مأخوذ خاتلهم وقصد لأدنى بيوتهم حتى ولج على امرأة منهم يقال لها فكيهة فاستجار بها فمنعته وجعلته تحت درعها واخترطت السيف وقامت دونه فكاثروها فكشفت خمارها عن شعرها وصاحت بإخوتها فجاؤوا ودفعوا عنه حتى نجا من القتل فقال السليك في ذلك\n(لعمر أبيك والأنباء تنمي ... لنعم الجار أخت بني عوارا)\n(من الخفرات لم تفضح أباها ... ولم ترفع لإخوتها شنارا)\n(كأن مجامع الأرداف منها ... نقا درجت عليه الريح هارا)\n(يعاف وصال ذات البذل قلبي ... ويتبع الممنعة النوارا)\n(وما عجزت فكيهة يوم قامت ... بنصل السيف واستبلوا الخمارا)\nخبرني الأخفش عن السكري عن أبي حاتم عن الأصمعي أن السليك أخذ رجلا من بني كنانة بن تيم بن أسامة بن مالك بن بكر بن حبيب بن غنم بن تغلب يقال له النعمان بن عقفان ثم أطلقه وقال\n(سمعت بجمعهم فرضخت فيهم ... بنعمان بن عقفان بن عمرو)\n(فإن تكفر فإني لا أبالي ... وإن تشكر فإني لست أدري)\nال ثم قدم بعد ذلك على بني كنانة وهو شيخ كبير وهم بماء لهم يقال له قباقب خلف البشر فأتاه نعمان بابنيه الحكم وعثمان وهما سيدا بني كنانة ونائلة ابنته فقال هذان وهذه لك وما أملك غيرهم فقالوا صدق فقال قد شكرت لك وقدرددتهم عليك فجمعت له بنو كنانة إبلا عظيمة فدفعوها إليه ثم قالوا له إن رأيت أن ترينا بعض ما بقي من إحضارك قال نعم وأبغوني أربعين شابا وأبغوني درعا ثقيلة فأتوه بذلك فلبس الدرع وقال للشبان الحقوا بي إن شئتم وعدا فلاث العدو لوثا وعدوا جنبته فلم يلحقوه إلا قليلا ثم غاب عنهم وكر حتى عاد إلى الحي هو وحده يحضر والدرع في عنقه تضرب كأنها خرقة من شدة إحضاره أخبرني به هاشم بن محمد الخزاعي عن عبد الرحمن ابن أخي الأصمعي عن عمه فذكر فيه نحو ما تقدم","topic":"أخبار السليك بن السلكة ونسبه","topicNo":265,"sp":3,"spl":"السليك القادر على الإحتمال"},
{"id":"b265-5","bab":"الجزء 20","sec":"خبر مقتله","page":"ج20 ص398","text":"وقال السكري في خبر مقتله إنه لقي رجلا من خثعم في أرض يقال لها فخة بين أرض عقيل وسعد تميم وكان يقال للرجل مالك بن\nعمير نب أبي ذراع بن جشم بن عوف فأخذه ومعه امرأة له من خفاجة يقال لها النوار فقال له الخثعمي أنا أفدي نفسي منك فقال له السليك ذلك لك على ألا تخيس بي ولا تطلع علي أحدا من خثعم فحالفه على ذلك ورجع إلى قومه وخلف امرأته رهينة معه فنكحها السليك وجعلت تقول احذر خثعم فإني أخافهم عليك فأنشأ يقول\n(تحذرني كي أحذر العام خثعما ... وقد علمت أني امرؤ غير مسلم)\n(وما خثعم إلا لئام أذلة ... إلى الذل والإسحاق تنمي وتنتمي)\nال وبلغ ذلك شبل بن قلادة بن عمر بن سعد وأنس بن مدرك الخثعميين فخالفا إلى السليك فلم يشعر إلا وقد طرقاه في الخيل فأنشأ يقول\n(من مبلغ جذمي بأني مقتول ... )\n(يا رب نهب قد حويت عثكول ... )\n(ورب قرن قد تركت مجدول ... )\n(ورب زوج قد نكحت عطبول ... )\n(ورب عان قد فككت مكبول ... )\n(ورب واد قد قطعت مسبول ... )\nال أنس للشبل إن شئت كفيتك القوم واكفني الرجل وإن شئت اكفني القوم أكفك الرجل قال بل أكفيك القوم فشد أنس على السليك فقتله وقتل شبل وأصحابه من كان معه وكاد الشر يتفاقم بين أنس وبين عبد الملك لأنه كان أجاره حتى\nوداه أنس لما خاف أن يخرج الأمر من يده وقال\n(كم من أخ لي كريم قد فجعت به ... ثم بقيت كأني بعده حجر)\n(لا أستكين على ريب الزمان ولا ... أغضي على المر يأتي دونه القدر)\n(مردى حروب أدير الأمر حابله ... إذ بعضهم لأمور تعتري جزر)\n(قد أطعن الطعنة النجلاء أتبعها ... طرفا شديدا إذا ما يشخص البصر)\n(ويوم حمضة مطلوب دلفت له ... بذات ودقين لما يعفها المطر)\nذكر باقي الأبيات التي تتلو هذه\n(إني وقتلي سليكا ثم أعقله ... )\nما ذكره من روينا عنه ذلك أخبرني هاشم بن محمد عن عبد الرحمن ابن أخي الأصمعي عن عمه فذكر ما تقدم قال أبو عبيدة وحدثني المنتجع بن نبهان قال كان السليك يعطي عبد الملك بن مويلك الخثعمي إتاوة من غنائمه على أن يجيره فيتجاوز بلاد خثعم إلى من وراءهم من أهل اليمن فيغير عليهم فمر قافلا من غزوة فإذا بيت من خثعم أهله خلوف وفيه امرأة شابة بضة فسألها عن الحي فأخبرته فتسنمها أ ي علاها ثم جلس حجرة ثم التقم المحجة\nفبادرت إلى الماء فأخبرت القوم فركب أنس بن مدرك الخثعمي في طلبه فلحقه فقتله فقال عبد الملك والله لأقتلن قاتله أو ليدينه فقال أنس والله لا أديه ولا كرامة ولو طلب في ديته عقالا لما أعطيته وقال في ذلك\n(إني وقتلي سليكا ثم أعقله ... كالثور يضرب لما عافت البقر)\n(غضبت للمرء إذ نيكت حليلته ... وإذ يشد على وجعائها الثفر)\n(إني لتارك هامات بمجزرة ... لا يزدهيني سواد الليل والقمر)\n(أغشى الحروب وسر بالي مضاعفة ... تغشى البنان وسيفي صارم ذكر)\nخبرني ابن أبي الأزهر عن حماد بن إسحاق عن أبيه عن فليح بن أبي العوراء قال كان لي صديق بمكة وكنا لا نفترق ولا يكتم أحد صاحبه سرا فقال لي ذات يوم يا فليح إني أهوى ابنة عم لي ولم أقدر عليها قط وقد زارتني اليوم فأحب أن تسرني بنفسك فإني لا أحتشمك فقلت أفعل وصرت إليهما وأحضرالطعام فأكلنا ووضع النبيذ فشربنا أقداحا فسألني أن أغنيهما فكأن الله عز و جل أنساني الغناء كله إلا هذا الصوت\n(من الخفرات لم تفضح أباها ... ولم تلحق بإخوتها شنارا)\nفلما سمعته الجارية قالت يا أخي أعد فأعدته فوثبت وقالت أحسنت أنا إلى الله تائبة والله ما كنت لأفضح أ بي ولا لأرفع لإخوتي شنارا فجهد الفتى في رجوعها فأبت وخرجت فقال لي ويحك ما حملك على ما صنعت فقلت والله ما هو شيء اعتمدته ولكنه ألقي على لساني لأمر أريد\nبك وبها وهكذا في الخبر المذكور وقد رواه غير من ذكرته عن فليح بن أبي العوراء فأخبرني اليزيدي عن عمه عبيد الله قال كان إبراهيم بن سعدان يؤدب ولد علي بن هشام وكان يغني بالعود تأدبا ولعبا قال فوجه إلي يوما علي بن هشام يدعوني فدخلت فإذا بين يديه امرأة مكشوفة الرأس تلاعبه بالنرد فرجعت عجلا فصاح بي ادخل فدخلت فإذا بين أيديهما نبيذ يشربان منه فقال خذ عودا وغن لنا ففعلت ثم غنيت في وسط غنائي\n(من الخفرات لم تفضح أباها ... ولم ترفع لإخوتها شنارا)","topic":"أخبار السليك بن السلكة ونسبه","topicNo":265,"sp":4,"spl":"خبر مقتله","partial":1},
{"id":"b265-6","bab":"الجزء 20","sec":"خبر مقتله","page":"ج20 ص398","text":"وثبت من بين يديه وغطت رأسها وقالت إني أشهد الله أني تائبة إليه ولا أفضح أبي ولا أرفع لإخوتي شنارا ففتر علي بن هشام ولم ينطق وخرجت من حضرته فقال لي ويلك من أين صبك الله علي هذه مغنية بغداد وأنا في طلبها منذ سنة لم أقدر عليها إلى اليوم فجئتني بهذا الصوت حتى هربت فقلت والله ما اعتمدت مساءتك ولكنه شيء خطر على غير تعمد صوت\n(أمسلم إني يا بن كل خليفة ... ويا جبل الدنيا ويا ملك الأرض)\n(شكرتك إن الشكر حظ من التقى ... وما كل من أوليته نعمة يقضي)\nلشعر لأبي نخيلة الحماني والغناء لابن سريج ثقيل بالوسطى عن يحيى المكي","topic":"أخبار السليك بن السلكة ونسبه","topicNo":265,"sp":5,"spl":"خبر مقتله"},
{"id":"b266-1","bab":"الجزء 20","sec":"أخبار أبي نخيلة ونسبه","page":"ج20 ص403","text":"أبو نخيلة اسمه لا كنيته ويكنى أبا الجنيد ذكر الأصمعي ذلك وأبو عمرو الشيباني وابن حبيب لا يعرف له اسم غيره وله كنيتان أبو الجنيد وأبو العرماس وهو ابن حزن بن زائدة بن لقيط بن هرم بن يثربي وقيل ابن أثربي بن ظالم بن مجاسر بن حماد بن عبد العزى بن كعب بن لؤي بن سعد بن زيد مناة بن تميم وكان عاقا بأبيه فنفاه أبوه عن نفسه فخرج إلى الشام وأقام هناك إلى أن مات أبوه ثم عاد وبقي مشكوكا في نسبه مطعونا عليه وكان الأغلب عليه الرجز وله قصيد ليس بالكبير ولما خرج إلى الشام اتصل بمسلمة بن عبد الملك فاصطنعه وأحسن إليه وأوصله إلى الخلفاء واحدا بعد واحد واستماحهم له فأغنوه وكان بعد ذلك قليل الوفاء لهم انقطع إلى بني هاشم ولقب نفسه شاعر بني هاشم فمدح الخلفاء من بني العباس وهجا بني أميه فأكثر\nوكان طامعا نحمله ذلك أن قال في المنصور أرجوزة يغريه فيها بخلع عيسى بن موسى ويعقد العهد لابنه محمد المهدي فوصله المنصور بألفي درهم وأمره أن ينشدها بحضرة عيسى بن موسى ففعل فطلبه عيسى فهرب منه وبعث في طلبه مولى له فأدركه في طريق خراسان فذبحه وسلخ جلده أخبرني هاشم الخزاعي عن عبد الرحمن ابن أخي الأصمعي عن عمه قال رأى أبو نخيلة على شبيب حلة فأعجبته فسأله إياها فوعده ومطله فقال فيه\n(يا قوم لا تسودوا شبيبا ... الخائن ابن ا لخائن الكذوبا)\n(هل تلد الذيبة إلا الذيبا ... )\nال فبلغه ذلك فبعث إليه بها فقال\n(إذا غدت سعد على شبيبها ... على فتاها وعلى خطيبها)\n(من مطلع الشمس إلى مغيبها ... عجبت من كثرتها وطيبها)\nدثني حبيب بن نصر المهلبي عن عمر بن شبة قال حدثني الرعل بن الخطاب قال بنى أبو نخيلة داره فمر به خالد بن صفوان وكان بينهما مداعبة قديمة ومودة وكيدة فوقف عليه\nفقال أبو نخيلة يا بن صفوان كيف ترى داري قال رأيتك سألت فيها إلحافا وأنفقت ما جمعت إسرافا جعلت إحدى يديك سطحا وملأت الأخرى سلحا فقلت من وضع في سطحي وإلا ملأته بسلحي ثم ولى وتركه فقيل له ألا تهجوه فقال إذن والله يركب بغلته ويطوف في مجالس البصرة ويصف أبنيتي بما يعيبها ما عسى أن يضر الإنسان صفة أبنيته بما يعيبها سنة ثم لا يعيد فيها كلمة","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":0,"spl":"أخبار أبي نخيلة ونسبه","partial":1},
{"id":"b266-2","bab":"الجزء 20","sec":"أبو نخيلة ومسلمة بن عبد الملك","page":"ج20 ص405","text":"أخبرني الحسن بن علي الخفاف عن ابن مهرويه عن أبي مسلم المستملي عن الحرمازي عن يحيى بن نجيم قال لما انتفى أبو نخيلة من أبيه خرج يطلب الرزق لنفسه فتأدب بالبادية حتى شعر وقال رجزا كثيرا وقصيدا صالحا وشهر بهما وسار شعره في البدو والحضر ورواه الناس ثم وفد إلى مسلمة بن عبد الملك فرفع منه وأعطاه وشفع له وأوصله إلى الوليد بن عبد الملك فمدحه ولم يزل به حتى أغناه قال يحيى بن نجيم فحدثني أبو نخيلة قال وردت على مسلمة بن عبد الملك فمدحته وقلت له\n(أمسلم إني يابن كل خليفة ... ويا فارس الهيجا ويا جبل الأرض)\n(شكرتك إن الشكر حبل من التقى ... وما كل من أوليته نعمة يقضي)\n(وألقيت لما أن أتيتك زائرا ... علي لحافا سابغ الطول والعرض)\n(وأحييت لي ذكرى وما كان خاملا ... ولكن بعض الذكر أنبه من بعض)\nقال فقال لي مسلمة ممن أنت فقلت من بني سعد فقال مالكم يا بني سعد والقصيد وإنما حظكم في الرجز قال فقلت له أنا والله أرجز العرب قال فأنشدني من رجزك فكأني والله لما قال ذلك لم أقل رجزا قط أنساينه الله كله فما ذكرت منه ولا من غيره شيئا إلا أرجوزة لرؤبة كان قالها في تلك السنة فظننت أنها لم تبلغ مسلمة فأنشدته إياها فنكس رأسه وتتعتعت فرفع رأسه إلي وقال لا تتعب نفسك فأنا أروى لها منك قال فانصرفت وأنا أكذب الناس عنده وأخزاهم عند نفسي حتى تلطفت بعد ذلك ومدحته برجز كثير فعرفني وقربني وما رأيت ذلك أثر فيه يC ولا قرعني به حتى افترقنا وحدثني أبو نخيلة قال لما انصرف مسلمة من حرب يزيد بن المهلب تلقيته فلما عاينته صحت به\n(مسلم يا مسلمة الحروب ... أنت المصفى من أذى العيوب)\n(مضاضة من كرم وطيب ... لولا ثقاف ليس بالتدبيب)\n(تفري به عن حجب القلوب ... لأمست الأمة شاء الذيب)\nحك وضمني إليه وأجزل صلتي حدثني هاشم بن محمد الخزاعي قال حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه وأخبرني بهذا الخبر أحمد بن عبيد الله بن عمار قال\nحدثني علي بن محمد النوفلي عن أبيه وقد جمعت روايتهما وأكثر اللفظ الأصمعي قال قال أبو نخيلة وفدت على هشام بن عبد الملك فصادفت مسلمة قد مات وكنت بأخلاق هشام غرا وأنا غريب فسألت عن أخص الناس به فذكر لي رجلان أحدهما من قيس والآخر من اليمن فعدلت إلى القيسي بالتؤدة فقلت هو أقربهما إلي وأجدرهما بما أحب فجلست إليه ثم وضعت يدي على ذراعه وقلت له إني مسستك لتمسني رحمك أنا رجل غريب شاعر من عشيرتك وأنا غير عارف بأخلاق هذا الخليفة وأحببت أن ترشدني إلى ما أعمل فينفعني عنده وعلى أن تشفع لي وتوصلني إليه فقال ذلك كله لك علي وفي الرجل شدة ليس كمن عهدت من أهله وإذا سئل وخلط مدحه بطلب حرم الطالب فأخلص له المدح فإنه أجدر أن ينفعك واغد إليه غدا فإني منتظرك بالباب حتى أوصلك والله يعينك فصرت من غد إلى باب هشام فإذا بالرجل منتظر لي فأدخلني معه وإذا بأبي النجم قد سبقني فبدأ فأنشده قوله\n(إلى هشام وإلى مروان ... بيتان ما مثلهما بيتان)\n(كفاك بالجود تباريان ... كما تبارى فرسا رهان)\n(مال علي حدث الزمان ... وبيع مايغلو من الغلمان)\n(بالثمن الوكس من الأثمان ... والمهر بعد المهر والحصان)","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":1,"spl":"أبو نخيلة ومسلمة بن عبد الملك"},
{"id":"b266-3","bab":"الجزء 20","sec":"أبو نخيلة يمدح هشاما فيجيزه","page":"ج20 ص407","text":"قال فأطال فيها وأكثر المسألة حتى ضجر هشام وتبينت الكراهة في وجهه ثم استأذنت فأذن لي فأنشدته\n(لما أتتني بغية كالشهد ... والعسل الممزوج بعد الرقد)\n(يا بردها لمشتف بالبرد ... رفعت من أطمار مستعد)\n(وقلت للعيس اعتلي وجدي ... فهي تخدي أبرح التخدي)\n(كم قد تعسفت بها من نجد ... ومجر هد بعد مجر هد)\n(قد ادرعن في مسير سمد ... ليلا كلون الطيلسان الجرد)\n(إلى أمير المؤمنين المجدي ... رب معد وسوى معد)\n(ممن دعا من أصيد وعبد ... ذي المجد والتشريف بعد المجد)\n(في وجهه بدر بدا بالسعد ... أنت الهمام القرم عند الجد)\n(طوقتها مجتمع الأشد ... فانهل لما قمت صوب الرعد)\nال حتى أتيت عليها وهممت أن أسأله ثم عزفت نفسي وقلت قد استنصحت رجلا وأخشى أن اخالفه فأخطىء وحانت مني التفاتة فرأيت وجه هشام منطلقا فلما فرغت أقبل على جلسائه فقال الغلام السعدي أشعر من الشيخ العجلي وخرجت فلما كان بعد أيام أتتني جائزته ثم دخلت عليه بعد ذلك وقد مدحته بقصيدة فأنشدته إياها فألقى علي جبة خز من جبابه مبطنة بسمور ثم دخلت عليه يوما آخر فكساني دواجا كان عليه من خز\nأحمر مبطن بسمور ثم دخلت عليه يوما ثالثا فلم يأمر لي بشيء فحملتني نفسي على أن قلت له\n(كسوتنيها فهي كالتجفاف ... من خزك المصونة الكثاف)\n(كأنني فيها وفي اللحاف ... من عبد شمس أبو بني مناف)\n(والخز مشتاق إلى الأفواف ... )\nال فضحك وكانت عليه جبة أفواف وأدخل يده فيها ونزعها ورمى بها إلي وقال خذها فلا بارك الله لك فيها قال محمد بن هشام في خبره خاصة فلما أفضت الخلافة إلى السفاح نقلها إليه وغيرها وجعلها فيه يعني الأرجوزة الدالية فهي الآن تنسب في شعره إلى السفاح","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":2,"spl":"أبو نخيلة يمدح هشاما فيجيزه","partial":1},
{"id":"b266-4","bab":"الجزء 20","sec":"أبو نخيلة والفرزدق","page":"ج20 ص409","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن الهيثم بن فراس قال حدثني أبو عمر الخصاف عن العتبي قال لما حبس عمر بن هبيرة الفرزدق وهو أمير العراق أبى أن يشفع فيه أحدا فدخل عليه أبو نخيلة في يوم فطر فوقف بين يديه وأنشأ يقول\n(أطلقت بالأمس أسير بكر ... فهل فداك نفري ووفري)\n(من سبب أو حجة أو عذر ... ينجي التميمي القليل الشكر)\n(من حلق القيد الثقال السمر ... ما زال مجنونا على آست الدهر)\n(ذا حسب ينمو وعقل يحري ... هبه لأخوالك يوم الفطر)\nال فأمر بإطلاقه وكان قد أطلق قبله رجلا من عجل جيء به من عين التمر قد أفسد فشفعت فيه بكر بن وائل فأطلقه وإياه عنى أبو نخيلة فلما أخرج الفرزدق سأل عمن شفع له فأخبر فرجع إلى الحبس وقال لا أريمه ولو مت انطلق قبلي بكري وأخرجت بشفاعة دعي والله لا أخرج هكذا ولو من النار فأخبر ابن هبيرة بذلك فضحك ودعا به فأطلقه وقال وهبتك لنفسك وكان هجاه فحبسه لذلك فلما عزل ابن هبيرة وحبس مدحه الفرزدق فقال ما رأيت أكرم منه هجاني أميرا ومدحني أسيرا وجدت هذا الخبر بخط القاسم بن يوسف فذكر أن أبا القاسم الحضرمي حدثه أن هذه القصة كانت لأبي نخيلة مع يزيد بن عمر بن هبيرة وأنه أتي بأسيرين من الشراة أخذا بعين التمر أحدهما أبو القاسم بن بسطام بن ضرار بن القعقاع بن معبد بن زرارة والآخر رجل من بكر بن وائل فتكلم في البكري قومه فأطلقه ولم يتكلم في التميمي أحد فدخل عليه أبو نخيلة فقال\n(الحمد لله ولي الأمر ... هو الذي أخرج كل غمر)\n(وكل عوار وكل وغر ... من كل ذي قلب نقي الصدر)\n(لما أتت من نحو عين التمر ... ست أثاف لا أثافي القدر)\n(فظلت القضبان فيهم تجري ... هبرا هو الهبر وفوق الهبر)\n(إني لمهد للإمام الغمر ... شعري ونصح الحب بعد الشعر)\nم ذكر باقي الأبيات كما ذكرت في الخبر المتقدم أخبرني أبو الحسن الأسدي أحمد بن محمد قال حدثني محمد بن صالح بن النطاح قال ذكر عن العتبي أن أبا نخيلة حج ومعه جريب من سويق قد حلاه بقند فنزل منزلا في طريقه فأتاه أعرابي من بني تميم وهو يقلب ذلك السويق واستحيا منه فعرض عليه فتناول ما أعطاه فأتى عليه ثم قال زدني يا بن أخ فقال أبو نخيلة\n(لما نزلنا منزلا ممقوتا ... نريد أن نرحل أو نبيتا)\n(جئت ولم ندر من أين جيتا ... إذا سقيت المزبد السحتيتا)\n(قلت ألا زدني وقد رويتا ... )\nقام الأعرابي وهو يسبه وحدثني بهذا الخبر هاشم بن محمد أبو دلف الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال كان أبو نخيلة إذا نزل به ضيف هجاه فنزل به يوما رجل من عشيرته فسقاه سويقا قد حلاه فقال له زدني فزاده فلما رحل هجاه وذكر الأبيات بعينها وقال في الخبر قال أبو عبيدة السحتيت السويق الدقاق","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":3,"spl":"أبو نخيلة والفرزدق","partial":1},
{"id":"b266-5","bab":"الجزء 20","sec":"أبو نخيلة يعتذر لأبي العباس السفاح","page":"ج20 ص412","text":"أخبرني محمد بن يحيى الصولي قال حدثنا محمد بن زكريا الغلابي قال حدثني ابن عائشة قال دخل أبو نخيلة على أبي العباس السفاح فسلم واستأذن في الإنشاد فقال له أبو العباس لا حاجة لنا في شعرك إنما تنشدنا فضلات بني مروان فقال يا أمير المؤمنين\n(كنا أناسا نرهب الملاكا ... إذ ركبوا الإعناق والأوراكا)\n(قد ارتجينا زمنا أباكا ... ثم ارتجينا بعده أخاكا)\n(ثم ارتجينا بعده إياكا ... وكان ما قلت لمن سواكا)\n(زورا فقد كفر هذا ذا كا ... )\nضحك أبو العباس وأجازه جائزة سنية وقال أجل إن التوبة لتكفر ما قبلها وقد كفر هذا ذاك وأخبرنا أبو الفياض سوار بن ابي شراعة قال حدثني أبي عن عبد الصمد بن المعذل عن أبيه قال\nدخل أبو نخيلة على أبي العباس قال وكان لا يجترىء عليه مع ما يعرفه به من اصطناع مسلمة إياه وكثرة مديحه لبني مروان حتى علم أنه قد عفا عمن هو أكبر محلا من القوم وأعظم جرما منه فلما وقف بين يديه سلم عليه ودعا له وأثنى ثم استأذنه في الإنشاد فقال له ومن أنت قال عبدك يا أمير المؤمنين أبو نخيلة الحماني فقال لا حياك الله ولا قرب دارك يا نضو السوء ألست القائل في مسلمة بن عبد الملك بالأمس\n(أمسلم يا من ساد كل خليفة ... ويا فارس الهيجا ويا قمر الأرض)\nالله لولا أني قد أمنت نظراءك لما ارتد إليك طرفك حتى أخضبك بدمك فقال أبو نخيلة\n(كنا أناسا نرهب الأملاكا ... )\nذكر الأبيات المتقدمة كلها مثل ما مضى من ذكرها فتبسم أبو العباس ثم قال له أنت شاعر وطالب خير وما زال الناس يمدحون الملوك في دولهم والتوبة تكفر الخطيئة والظفر يزيد الحقد وقد عفونا عنك واستأنفنا الصنيعة لك وأنت الآن شاعرنا فاتسم بذلك فيزول عنك ميسم بني مروان فقد كفر هذا ذاك كما قلت ثم التفت إلى أبي الخصيب فقال يا مرزوق أدخله دار الرقيق فخيره جارية يأخذها لنفسه ففعل واختار جارية وطفاء كثيرة اللحم فلم يحمدها فلما كان من غد دخل على أبي العباس وعلى رأسه وصيفة حسناء تذب عنه فقال له قد عرفت خبر الجارية التي أخذتها بالأمس وهي كذناكونه فاحتفظ بها فأنشأ يقول\n(إني وجدت الكذناذنوكا ... غير منيك فابغني منيكا)\n(حتى إذا حركته تحركا ... )\nضحك أبو العباس وقال خذ هذه الوصيفة فإنك إذا خلوت بها تحرك من غير أن تحركه أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال ادان أبو نخيلة من بقال له يقال له ماعز الكلابي باليمامة وكان يأخذ منه أولا أولا حتى كثر ما عليه وثقل فطالبه ماعز فمطله ثم بلغه أنه قد استعدى عليه عامل اليمامة فارتحل يريد الموصل وخرج عن اليمامة ليلا فلم يعد به ماعز إلا بعد ثلاث وقد نجا أبو نخيلة وقال في ذلك\n(يا ماعز الكراث خزيتا ... لقد خدعت ولقد هجيتنا)\n(كدت تخصينا فقد خصيتا ... وكنت ذا حظ فقد محيتا)\n(ويحك لم تعلم بمن صليتا ... ولا بأي حجر رميتا)\n(إذا رأيت المزيد الهبوتا ... يركب شدقا شدقما هريتا)\n(طر بجناحك فقد أتيتا ... حران حران فهيتا هيتا)\nوالموصل الموصل أو تكريتا ... حيث تبيع النبط البيوتا\n(ويأكلون العدس المريتا ... )\nقال أيضا لماعز هذا\n(يا ماعز القمل وبيت الذل ... بتنا وبات البغل في الإصطبل)\n(وبات شيطان القوافي يملي ... على امرئ فحل وغير فحل)\n(لا خير في علمي ولا في جهلي ... لو كان أودى ماعز بنخلي)\n(ما زال يقليني وعيمي يغلي ... حتى إذا العيم رمى بالجفل)\n(طبقت تطبيق الجزاز النصل ... )\nماذج من مدحه وهجائه نسخت من كتاب اليوسفي حدثني المنمق بن جماع عن أبيه قال كان أبو نخيلة يرضيه القليل ويسخطه وكان الربيع ينزله عنده ويأمر سائسا يتفقد فرسه فمدح الربيع بأرجوزة ومدح فيها معه سائسه فقال\n(لولا أبو الفضل ولولا فضله ... ما اسطيع باب لا يسنى قفله)\n(ومن صلاح راشد إصطبله ... نعم الفتى وخير فعل فعله)\n(يسمن منه طرفه وبغله ... )\nضحك الربيع وقال يا أبا نخيلة أترضى أن تقرن بي السائس في مديح كأنك لو لم تمدحه معي كان يضيع فرسك قال ونزل أبو نخيلة بسليمان بن صعصعة فأمر غلامه بتعهده وكان\nيغاديه ويراوحه في كل يوم بالخبز والحم فقال أبو نخيلة يمدح خباز سليمان بن صعصعة\n(بارك ربي فيك من خباز ... ما زلت إذ كنت على أوفاز)\n(تنصب باللحم انصباب الباز ... )","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":4,"spl":"أبو نخيلة يعتذر لأبي العباس السفاح","partial":1},
{"id":"b266-6","bab":"الجزء 20","sec":"أبو نخيلة يعتذر لأبي العباس السفاح","page":"ج20 ص412","text":"خبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل تينة قال حدثنا أحمد بن المعذل عن علي بن أبي نخيلة الحماني قال دخلت مع أبي إلى أرض له وقد قدم من مكة فرآها وقد أضر بها جفاء القيم عليها وتهاونه بها وكلما رآه الذين يسقونها زادوا في العمل والعمارة حتى سمعت نقيض الليف فقلت الساعة يقول في هذا شعرا فلم ألبث أن التفت إلي وقال\n(شاهد مالا رب مال فساسه ... سياسة شهم حازم وابن حازم)\n(أقام بها العصرين حينا ولم يكن ... كمن ضن عن عمرانها بالدراهم)\n(كأن نقيض الليف عن سعفاته ... نقيض رحال الميس فوق العياهم)\n(وأضحت تغالي بالبنات كأنها ... على متن شيخ من شيوخ الأعاجم)\n(وما الأصل ما رويت مضرب عرقه ... من الماء عن إصلاح فرع بنائم)\nخبرني بهذا الخبر محمد بن مزيد عن أبي الأزهر البوشنجي قال حدثنا حماد بن إسحاق الموصلي عن النضر بن حديد عن أبي محضة عن الأزرق بن الخميس بن أرطأة وهو ابن أخت أبي نخيلة فذكر قريبا مما ذكر في الخبر الذي قبله\nوأخبرني عيسى بن الحسن الوراق المروزي قال حدثنا علي بن محمد النوفلي قال حدثني أبي قال ابتاع أو نخيلة دارا في بني حمان ليصحح بها نسبه وسأل في بنائها فأعطاه الناس اتقاء للسانه وشره فسأل شبيب بن شبة فلم يعطه شيئا واعتذر إليه فقال\n(يا قوم لا تسودوا شبيبا ... الملذان الخائن الكذوبا)\n(هل تلد الذيبة إلا الذبيا ... )\nقال شبيب ما كنت لأعطيه على هذا القول شيئا فإنه قد جعل إحدى يديه سطحا وملأ الأخرى سلحا وقال من وضع شيئا في سطحي وإلا ملأته بسلحي من أجل دار يريد أن يصحح نسبه بها فسفر بينهما مشايخ الحي حتى يعطيه فأبى شبيب أن يعطيه شيئا وحلف أبو نخيلة ألا يكف عن عرضه أو يأخذ منه شيئا يستعين به فلما رأى شبيب ذلك خافه فبعث إليه بما سأل وغدا أبو نخيلة عليه وهو جالس في مجلسه مع قومه فوقف عليهم ثم أنشأ يقول\n(إذا عدت سعد على شبيبها ... على فتاها وعلى خطيبها)\n(من مطلع الشمس إلى مغيبها ... عجبت من كثرتها وطيبها)\nخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة قال دخل أبو نخيلة على عمر بن هبيرة وعنده رؤبة قد قام من مجلسه فاضطجع خلف ستر فأنشد أبو نخيلة مديحه له ثم قال ابن هبيرة يا أبا\nنخيلة أي شيء أحدثت بعدنا فاندفع ينشده أرجوزة لرؤبة فلما توسطها كشف رؤبة الستر وأخرج رأسه من تحته فقال له كيف أنت يا أبا نخيلة فقطع إنشاده وقال بخير أبا العجاج فمعذرة إليك ما علمت بمكانك فقال له رؤبة أم ننهك أن تعرض لشعري إذا كنت حاضرا فإذا ما غبت فشأنك به فضحك أبو نخيلة وقال هل أنا إلا حسنة من حسناتك وتابع لك وحامل عنك فعاد رؤبة إلى موضعه فاضطجع ولم يراجعه حرفا والله أعلم أخبرني هاشم بن محمد قال حدثنا دماذ عن أبي عبيدة أن أبا نخيلة قدم على المهاجرين بن عبد الله الكلابي وكان أبو نخيلة أشبه خلق الله به وجها وجسما وقامة لا يكاد الناظر إلى أحدهما أن يفرق بينه وبين الآخر فدخل عليه فأنشده قوله فيه\n(يا دار أم مالك ألا أسلمي ... على التنائي من مقام وأنعمي)\n(كيف أنا إن أنت لم تكلمي ... بالوحي أو كيف بأن تجمجمي)\n(تقول لي بنتي ملام اللوم ... يا أبتا إنك يوما مؤتمي)\n(فقلت كلا فاعلمي ثم اعلمي ... أني لميقات كتاب محكم)\n(لو كنت في ظلمة شعب مظلم ... أو في السماء أرتقي بسلم)\n(لا نصب مقداري إلى مجرنثمي ... إني ورب الراقصات الرسم)\n(ورب حوض زمزم وزمزم ... لأستبين الخير عند مقدمي)\n(وعند ترحالي عن مخيمي ... على ابن عبد الله قرم الأقرم)\n(فإنني بالعلم ذو ترسم ... لم أدر ما مهاجر التكرم)\nحتى تبينت قضايا الغشم ... مهاجر يا ذا النوال الخضرم أنت إذا انتجعت خير مغنم ... مشترك النائل جم الأنعم ولتميم منك خير مقسم ... إذا التقوا شتى معا كالهيم قد علم الشأم وكل موسم ... أنك تحلو لي كحلو المعجم طورا وطورا أنت مثل العلقم ...\nقال فأمر له المهاجر بناقة فتركها ومضى مغضبا وقال يهجوه\n(إن الكلابي اللئيم الأثرما ... أعطى على المدحة نابا عرزما)\n(ما جبر العظم ولكن تمما ... )\nبلغ ذلك المهاجر فبعث فترضاه وقام في أمره بما يحب ووصله فقال أبو نخيلة هذه صلة المديح فأين صلة الشبه فإن التشابه في الناس نسب فوصله حتى أرضاه فلم يزل يمدحه بعد ذلك حتى مات ورثاه بعد وفاته فقال","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":5,"spl":"أبو نخيلة يعتذر لأبي العباس السفاح","partial":1},
{"id":"b266-7","bab":"الجزء 20","sec":"أبو نخيلة يعتذر لأبي العباس السفاح","page":"ج20 ص412","text":"(خليلي مالي باليمامة مقعد ... ولا قرة للعين بعد المهاجر)\n(مضى ما مضى من مصالح العيش فاربعا ... على ابن سبيل مزمع البين عابر)\n(فإن تك في ملحودة يا بن وائل ... فقد كنت زين الوفد زين المنابر)\n(وقد كنت لولا سلك السيف لم ينم ... مقيم ولم تأمن سبيل المسافر)\n(لعز على الحيين قيس وخندف ... تبكي علي والوليد وجابر)\n(هوى قمر من بينهم فكأنما ... هوى البدر من بين النجوم الزواهر)\nخبرني هاشم بن محمد قال حدثنا دماذ عن أبي عبيدة قال\nتزوجت أخت أبي نخيلة برجل يقال له ميار وكان أبو نخيلة يقوم بمالها مع ماله ويرعى سوامها مع سوامه ويستبد عليها بأكثر منافعها فخاصمته يوما من وراء خدرها في ذلك فأنشأ يقول\n(أظل أرعى وترا هزينا ... ململما ترى له غضونا)\n(ذا أبن مقوما عثنونا ... يطعن طعنا يقضب الوتينا)\n(ويهتك الأعفاج والربينا ... يذهب ميار وتقعدينا)\n(وتفسدين أو تبذرينا ... وتمنحين استك آخرينا)\n(أير الحمار في است هذا دينا ... )\nخبرني هاشم بن محمد الخزاعي قال حدثنا دماذ عن أبي عبيدة قال تزوج أبو نخيلة امرأة من عشيرته فولدت له بنتا فغمه ذلك فطلقها تطليقة ثم ندم وعاتبه قومه فراجعها فبينما هو في بيته يوما إذ سمع صوت ابنته وأمها تلاعبها فحركه ذلك ورق لها فقام إليها فأخذها وجعل ينزيها ويقول\n(يا بنت من لم يك يهوى بنتا ... ما كنت إلا خمسة أو ستا)\n(حتى حللت في الحشى وحتى ... فتت قلبي من جوى فانفتا)\n(لأنت خير من غلام أنتا ... يصبح مخمورا ويمسي سبتا)","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":6,"spl":"أبو نخيلة يعتذر لأبي العباس السفاح","partial":1},
{"id":"b266-8","bab":"الجزء 20","sec":"جمال شعره يجمل النساء","page":"ج20 ص421","text":"أخبرني جعفر بن قدامة قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثنا أبو هفان قال حدثني أصحابنا الأهتميون قالوا دخل عقال بن شبة المجاشعي على المهدي فقال له يا أبا الشيظم ما بقي من حبك بنات آدم وما بعجبك منهن التي عصبت عصب الجان وجلدت جدل العنان واهتزت اهتزاز البان أم التي بدنت فعظمت وكملت فتمت فقال يا أمير المؤمنين أحبهما إلي التي وصفها أبو نخيلة فإنه كانت له جارية صغيرة وهبها له عمك أبو العباس السفاح فكان إذا غشيها صغرت عنه وقلت تحته فقال\n(إني وجت الكذناذنوكا ... غير منيك فابغني منيكا)\n(شيئا إذا حركته تحركا ... )\nال فوهب له المهدي جراية كاملة فائقة متأدبة ربعة فلما أصبح عقال غدا على المهدي متشكرا فخرج المهدي وفي يده مشط يسرح به لحيته وهو يضحك فدعا له عقال وقال له يا أمير المؤمنين مم تضحك أدام الله سرورك قال يا أبا الشيظم إني اغتسلت آنفا من شيء إذا حركته تحرك وذكرت قولك الآن لما رأيتك فضحكت أخبرني محمد بن جعفر النحوي صهر المبرد قال حدثني أحمد بن القاسم العجلي البرتي قال حدثني أبو هفان قال حدثتني رقية بنت حمل عن أبيها قال\nكان أبو نخيلة مداحا للجنيد بن عبد الرحمن المري وكان الجنيد له محبا يكثر رفده ويقرب مجلسه ويحسن إليه فلما مات الجنيد قال أبو نخيلة يرثيه\n(لعمري لئن ركب الجنيد تحملوا ... إلى الشأم من مر وراحت ركائبه)\n(لقد غادر الركب الشآمون خلفهم ... فتى غطفانيا يعلل جانبه)\n(فتى كان يسري للعدو كأنما ... سروب القطا في كل يوم كتائبه)\n(وكان كأن البدر تحت لوائه ... إذا راح في جيش وراحت عصائبه)\nخبرنا محمد بن جعفر قال حدثني أحمد بن القاسم قال حدثني أبو هفان عن عبد الله بن داود عن علي بن أبي نخيلة قال كان أبي شديد الرقة علي معجبا بي فكان إذا أكل خصني بأطيب الطعام وإذا نام أضجعني إلى جنبه فغاظ ذلك امرأته أم حماد الحنفية فجعلت تعذله وتؤنبه وتقول قد أقمت في منزلك وعكفت على هذا الصبي وتركت الطلب لولدك وعيالك فقال أبي في ذلك\n(ولولا شهوتي شفتي علي ... ربعت على الصحابة والركاب)\n(ولكن الوسائل من علي ... خلصن إلى الفؤاد من الحجاب)\nال فازدادت غضبا فقال لها\n(وليس كأم حماد خليل ... إذا ما الأمر جل عن الخطاب)\n(منعمة أرى فتقر عيني ... وتكفيني خلائقها عتابي)\nفرضيت وأمسكت عنا حدثني عمي قال حدثني هارون بن محمد بن عبد الله قال حدثني سهل بن زكريا قال حدثني عبد الله بن أحمد الباهلي قال قال أبان بن عبد الله النميري يوما لجلسائه وفيهم أبو نخيلة والله لوددت أنه قيل في ما قيل في جرير بن عبد الله\n(لولا جرير هلكت بجيله ... نعم الفتى وبئست القبيلة)\nإنني أثبت على ذلك مالي كله فقال له أبو نخيلة هلم الثواب فقد حضرني من ذلك ما تريد فأمر له بدراهم فقال اسمع يا طالب ما يجزيه\n(لولا أبان هلكت نمير ... نعم الفتى وليس فيهم خير)\nخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثنا سلمة بن خالد المازني عن أبي عبيدة قال وقف أبو نخيلة على باب أبي جعفر واستأذن فلم يصل وجعلت الخراسانية تدخل وتخرج فتهزأ به فيرون شيخا أعرابيا جلفا فيبعثون به فقال له رجل عرفه كيف أنت أبا نخيلة فأنشأ يقول\n(أصبحت لا يملك بعضي بعضا ... أشكو العروق الآبضات أبضا)\n(كما تشكى الأرحبي الغرضا ... كأنما كان شبابي قرضا)\nقال له الرجل وكيف ترى ما أنت فيه هذه الدولة فقال\n(أكثر خلق الله من لا يدرى ... من أي خلق الله حين يلقى)\n(وحلة تنشر ثم تطوى ... وطيلسان يشترى فيغلى)\n(لعبد عبد أو لمولى مولى ... يا ويح بيت المال ماذا يلقى)\nبهذا الإسناد عن أبي عبيدة أن أبا نخيلة قدم علىأبان بن الوليد فامتدحه فكساه ووهب له جارية جميلة فخرج يوما من عنده فلقيه رجل من قومه فقيل له كيف وجدت أبان بن الوليد يا أبا نخيلة فقال\n(أكثر والله أبان ميري ... ومن أبان الخير كل خيري)\n(ثوب لجلدي وحر لأيري ... )","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":7,"spl":"جمال شعره يجمل النساء","partial":1},
{"id":"b266-9","bab":"الجزء 20","sec":"جمال شعره يجمل النساء","page":"ج20 ص421","text":"سخت من كتاب اليوسفي حدثني خالد بن حميد عن أبي عمرو الشيباني قال أقحمت السنة أبا نخيلة فأتى القعقاع بن ضرار وهو يومئذ على شرطة الكوفة فمدحه وأنزله القعقاع بن ضرار وابنيه وعبديه وركابهم في دار وأقام لهم الأنزال ولركابهم العلوفة وكان طباخ القعقاع يجيئهم في كل يوم بأربع قصاع فيها ألوان مطبوخة من لحوم الغنم ويأتيهم بتمر وزبد فقال له يوما القعقاع كيف منزلك أبا نخيلة فقال\n(ما زال عنا قصعات أربع ... شهرين دأبا ذود ورجع)\n(عبداي وابناي وشيخ يرفع ... كما يقوم الجمل المطبع)\nقال وكان أبو نخيلة يكثر الأكل فأصابته تخمة فدخل على القعقاع فسأله كيف أصبحت أبا نخيلة فقال أصبحت والله بشما أمرت خبازك فأتاني بهذاالرقاق الذي كأنه الثياب المبلولة قد غمسه في الشحم غمسا وأتبعه يزيد كرأس النعجة الخرسية وتمر كأنه عنز رابضة إذا أخذت التمرة من موضعها تبعها من الرب كالسلوك الممدودة فأمعنت في ذلك وأعجبني حتى بشمت فهل من أقداح جياد وبين يدي القعقاع حجام واقف وسفرة موضوعة فيها المواسي فإذا أتي بشراب النبيذ حلق رؤوسهم ولحاهم فقال له القعقاع أتطلب مني النبيذ وأنت ترى ما أصنع بشرابه عليك بالعسل والماء البارد فوثب ثم قال\n(قد علم المظل والمبيت ... أني من القعقاع فيما شيت)\n(إذا أتت مائدة أتيت ... ببدع لست بها غذيت)\n(وليت فاستشفيت واستعديت ... كأني كنت الذي وليت)\n(ولو تمنيت الذي أعطيت ... ما ازددت شيئا فوق ما لقيت)\n(أيا بن بيت دونه البيوت ... أقصر فقد فوق القرى قريت)\n(ما بين شرابي عسل منعوت ... ولا فرات صرد بيوت)\n(لكنني في النوم قد أريت ... رطل نبيذ مخفس سقيت)\n(صلبا إذا جاذبته رويت ... )\nغمزه على إسماعيل ابن أخيه وأومأ إلى إسماعيل فأخذ بيده ومضى به إلى منزله فسقاه حتى صلح","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":8,"spl":"جمال شعره يجمل النساء — ومنها","partial":1},
{"id":"b266-10","bab":"الجزء 20","sec":"أبو نخيلة يمدح السفاح","page":"ج20 ص426","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا قعنب بن المحرز وأبو عمرو الباهلي قالا حدثنا الأصمعي قال دخل أبو نخيلة على أبي العباس السفاح وعنده أبو صفوان إسحاق بن مسلم العقيلي فأنشده قوله\n(صادتك يوم الرملتين شعفر ... وقد يصيد القانص المزعفر)\n(يا صورة حسنها المصور ... للريم منها جيدها والمحجر)\nقول فيها في مدح أبي العباس\n(حق إذا ما الأوصياء عسكروا ... وقام من تبر النبي الجوهر)\n(ومن بني العباس نبع أصفر ... ينميه فرع طيب وعنصر)\n(أقبل بالناس الهوى المستبهر ... وصاح في الليل نهار أنور)\n(أنا الذي لو قيل إني أشعر ... جلى الضباب الرجز المخبر)\n(لما مضت لي أشهر و أشهر ... قلت لنفس تزدهى فتصبر)\n(لا يستخفنك ركب يصدر ... لا منجد يمضي ولا مغور)\n(وخالفي الأنباء فهي المحشر ... أو يسمع الخليفة المطهر)\n(مني فإني كل جنح أحضر ... وإن بالأنبار غيثا يهمر)\n(والغيث يرجى والديار تنضر ... ما كان إلا أن أتاها العسكر)\n(حتى زهاها مسجد ومنبر ... لم يبق من مروان عين تنظر)\n(لا غائب ولا أناس حضر ... هيهات أودى المنعم المعقر)\n(وأمست الأنبار دارا تعمر ... وخربت من الشآم أدور)\n(حمص وباب التبن والموقر ... ودمرت بعد امتناع تدمر)\n(وواسط لم يبق إلا القرقر ... منها وإلا الديربان الأخضر)","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":8,"spl":"جمال شعره يجمل النساء — ومنها"},
{"id":"b266-11","bab":"الجزء 20","sec":"ومنها","page":"ج20 ص427","text":"(أين أبو الورد وأين الكوثر ... )\nبو الورد بن هذيل بن زفر وكوثر بن الأسود صاحب شرطة مروان\n(وأين مروان وأين الأشقر ... وأين فل لم يفت محير)\n(وأين عاديكم المجمهر ... وعامر وعامر وأعصر)\nقال يعني عامر بن صعصعة وعامر بن ربيعة وأعصر باهلة وغني قال فغضب إسحاق بن مسلم وقال هؤلاء كلهم في جر أمك أبا نخيلة فأنكر الخليفة عليه ذلك فقال إني والله يا أمير المؤمنين قد سمعت\nمنه فيكم شرا من هذا في مجالس بني مروان وما له عهد وما هو بوفي ولا كريم فبان ذلك في وجه أبي العباس وقال له قولا ضعيفا إن التوبة تغسل الحوبة والحسنات يذهبن السيئات وهذا شاعر بني هاشم وقام فدخل وانصرف الناس ولم يعط أبا نخيلة شيئا","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":8,"spl":"جمال شعره يجمل النساء — ومنها","partial":1},
{"id":"b266-12","bab":"الجزء 20","sec":"أبو نخيلة والمنصور","page":"ج20 ص428","text":"وأخبرني أحمد بن عبيد الله بن عمار الثقفي حدثنا علي بن محمد بن سليمان النوفلي قال حدثني أبي عن عبد الله بن أبي سليم مولى عبد الله بن الحارث قال بينا أنا أسير مع أبي الفضل يعني سليمان بن عبد الله وحدي بين الحيرة والكوفة وهو يريد المنصور وقد هم بتولية المهدي العهد وخلع عيسى بن موسى وهو يروض ذلك إذا هو بأبي نخيلة الشاعر ومعه ابنان له وعبد وهم يحملون متاعه فقال له يا أبا نخيلة ما هذا الذي أرى قال كنت نازلا على القعقاع بن معبد أحد ولد معبد بن زرارة فقلت شعرا فيما عزم عليه أمير المؤمنين من تولية المهدي العهد ونزع عيسى بن موسى فسألني التحول عنه لئلا يناله مكروه من عيسى إذ كان صنيعته فقال سليمان يا عبد الله اذهب بأبي نخيلة فأنزله منزلا وأحسن نزله وبره ففعلت ودخل سليمان إلى المنصور فأخبره الخبر فلما كان يوم البيعة جاء بأبي نخيلة فأدخله على المنصور فقام فأنشد الشعر على رؤوس الناس وهي قصيدته التي يقول فيها\n(بل يا أمين الواحد الموحد ... إن الذي ولاك رب المسجد)\n(ليس ولي عهدنا بالأسعد ... عيسى فزحلفها إلى محمد)\n(من عند عيسى معهدا عن معهد ... حتى تؤدى من يد إلى يد)\nقال فأعطاه المنصور عشرة آلاف درهم قال وبايع لمحمد بالعهد فانصرف عيسى بن موسى إلى منزله قال فحدثني داود بن عيسى بن موسى قال جمعنا أبي فقال يا بني قد رأيتم ما جرى فأيما أحب إليكم أن يقال لكم يا بني المخلوع أو يقال لكم يا بني المفقود فقلنا لا بل يا بني المخلوع فقال وفقتم بني وأول هذه الأرجوزة التي هذه الأبيات منها\n(لم ينسني يا بنة آل معبد ... ذكراك تكرار الليالي العود)\n(ولا ذوات العصب المورد ... ولو طلبن الود بالتودد)\n(ورحن في الدر وفي الزبرجد ... هيهات منهن وإن لم تعهدي)\n(نجدية ذات معان منجد ... كأن رياها بعيد المرقد)\n(ريا الخزامي في ثرى جعد ندي ... كيف التصابي فعل من لم يهتد)\n(وقد علتني درة بادي بدي ... ورثية تنهض في تشددي)\n(بعد انتهاضي في الشباب الأملد ... )\nقول فيها\n(إلى أمير المؤمنين فاعمد ... إلى الذي يندي ولا يندى ندي)\n(سيري إلى وبحر البحار المزبد ... إلى الذي إن نفدت لم ينفد)\n(أو ثمدت أشراعها لم يثمد ... )\nويقول في ذكر البيعة لمحمد بعد الأبيات التي مضت في صدر الخبر\n(فقد رضينا بالغلام الأمرد ... وقد فرغنا غير أن لم نشهد)\n(وغير أن العقد لم يؤكد ... فلو سمعنا قولك امدد امدد)\n(كانت لنا كزعقة الورد الصدي ... فناد للبعية جمعا نحشد)\n(في يومنا الحاضر هذا أوغد ... واصنع كما شئت ورد يردد)\n(ورده منك رداء يرتد ... فهو رداء السابق المقلد)\n(وكان يروي أنها كأن قد ... عادت ولو قد نقلت لم تردد)\n(أقول في كرى أحاديث الغد ... لله دري من أخ ومنشد)\n(لو نلت حظ الحبشي الأسود ... )\nعني أبا دلامة فأخبرني عبد الله بن محمد الرازي قال حدثنا أحمد بن الحارث قال حدثنا المدائني أن أبا نخيلة أظهر هذه القصيدة التي رواها الخدم والخاصة وتناشدتها العامة فبلغت المنصور فدعا به وعيسى بن موسى عنده جالس عن يمينه فأنشده إياها وأنصت له حتى سمعها إلىآخرها قال أبو نخيلة فجعلت أرى فيه السرور ثم قال لعيسى بن موسى ولئن كان هذا عن رأيك لقد سررت عمك وبلغت من مرضاته أقصى ما يبلغه الولد البار السار فقال عيسى لقد ضللت إذا وما أنا من المهتدين قال أبو\nنخيلة فلما خرجت لحقني عقال بن شبة فقال أما أنت فقد سررت أمير المؤمنين ولئن تم الأمر فلعمري لتصيبن خيرا ولئن لم يتم فابتغ نفقا في الأرض أو سلما في السماء فقلت له\n(علقت معالقها وصر الجندب ... )\nال المدائني وحدثني بعض موالي المنصور قال لما أراد المنصور أن يعقد للمهدي أحب أن تقول الشعراء في ذلك فحدثني عبد الجبار بن عبيد الله الحماني قال حدثني أبو نخيلة قال قدمت على أبي جعفر فأقمت ببابه شهرا لا أصل إليه فقال لي عبد الله بن الربيع الحارثي يا أبا نخيلة إن أمير المؤمنين يريد أن يقدم المهدي بين يدي عيسى بن موسى فلو قلت شيئا تحثه على ما يريد فقلت\n(ماذا على شحط النوى عناكا ... أم ما مرى دمعك من ذكراكا)\n(وقد تبكيت فما أبكاكا ... )\nوذكر أرجوزة طويلة يقول فيها\n(خليفة الله وأنت ذاكا ... أسند إلى محمد عصاكا)\n(فأحفظ الناس لها أدناكا ... وابنك ما استكفيته كفاكا)\n(وكلنا منتظر لذاكا ... لو قلت هاتوا قلت هاك هاكا)","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":9,"spl":"أبو نخيلة والمنصور","partial":1},
{"id":"b266-13","bab":"الجزء 20","sec":"أبو نخيلة والمنصور","page":"ج20 ص428","text":"قال فأنشدته إياها فوصلني بألفي درهم وقال لي احذر عيسى بن موسى فإني أخافه عليك أن يغتالك قال المدائني وخلع أبو جعفر عيسى بن موسى فبعث عيسى في طلب أبي نخيلة فهرب منه وخرج يريد خراسان فبلغ عيسى خبره فجرد خلفه مولى له يقال له قطري معه عدة من مواليه وقال له نفسك نفسك أن يفوتك أبو نخيلة فخرج في طلبه مغذا للسير فلحقه في طريقه إلى خراسان فقتله وسلخ وجهه ونسخت من كتاب القاسم بن يوسف عن خالد بن حمل أن علي بن أبي نخيلة حدثه أن المنصور أمر أبا نخيلة أن يهرب إلى خراسان فأخذه قطري وكتفه فأضجعه فلما وضع السكين على أوداجه قال إيه يا بن الخناء ألست القائل\n(علقت معالقها وصر الجندب ... )\nالآن صر جندبك فقال لعن الله ذاك جندبا ما كان أشأم ذكره ثم ذبحه قطري وسلخ وجهه وألقى جسمه إلى النسور وأقسم لا يريم مكانه حتى تمزق السباع والطيور لحمه فأقام حتى لم يبق منه إلا عظامه ثم انصرف أخبرنا جعفر بن قدامة قال حدثنا أبو حاتم السجستاني قال حدثني\nالأصمعي عن سعيد بن سلم عن أبيه قال قلت لأبي الأبرش مات أبو نخيلة قال حتف أنفه قلت لا بل اغتيل فقتل فقال الحمد لله الذي قطع قلبه وقبض روحه وسفك دمه وأراحني منه وأحياني بعده وكان أبو نخيلة يهاجي الأبرش فغلبه أبو نخيلة صوت\n(ولقد دخلت على الفتاة ... الخدر في اليوم المطير)\n(فدفعتها فتدافعت ... مشي القطاة على الغدير)\n(فلثمتها فتنفست ... كتنفس الظبي البهير)\nالشعر للمنخل اليشكري والغناء لإبراهيم ثاني ثقيل بالوسطى عن عمرو وأحمد المكي تم الجزء العشرون من كتاب الأغاني ويليه إن شاء الله تعالى الجزء الحادي والعشرون وأوله أخبار المنخل ونسبه\nبسم الله الرحمن الرحيم","topic":"أخبار أبي نخيلة ونسبه","topicNo":266,"sp":10,"spl":"أبو نخيلة والمنصور","partialRef":{"sid":"b266-12","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b267-1","bab":"الجزء 20","sec":"أخبار المنخل ونسبه","page":"ج20 ص433","text":"هو المنخل بن عمرو - ويقال المنخل بن مسعود - بن أفلت بن عمرو بن كعب بن سواءة بن غنم بن حبيب بن يشكر بن بكر بن وائل وذكر أبو محلم النسابة أنه المنخل بن مسعود بن أفلت بن قطن بن سوءة بن مالك بن ثعلبة بن حبيب بن غنم بن حبيب بن كعب بن يشكر وقال ابن الأعرابي هو المنخل بن الحارث بن قيس بن عمرو بن ثعلبة بن عدي بن جشم بن حبيب بن كعب بن يشكر","topic":"أخبار المنخل ونسبه","topicNo":267,"sp":0,"spl":"أخبار المنخل ونسبه"}]);